CREATE VIEW public.action_formation_lib (
    "id", "idplanformation", "idplanformationlib", "idtypeformation", "idtypeformationlib", "idcategorieformation", "idcategorieformationlib", "formateur", "reference", "intitule", "typeprestataire", "idsemestre", "idsemestrelib", "nbsessionprevus", "dureestagiaireheure", "nbouvriersprevue", "nbcadreprevue", "objectif", "etat", "etatlib", "estrealiseelib", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.idplanformation AS idplanformation,
  base.idplanformationlib AS idplanformationlib,
  base.idtypeformation AS idtypeformation,
  base.idtypeformationlib AS idtypeformationlib,
  base.idcategorieformation AS idcategorieformation,
  base.idcategorieformationlib AS idcategorieformationlib,
  base.formateur AS formateur,
  base.reference AS reference,
  base.intitule AS intitule,
  base.typeprestataire AS typeprestataire,
  base.idsemestre AS idsemestre,
  base.idsemestrelib AS idsemestrelib,
  base.nbsessionprevus AS nbsessionprevus,
  base.dureestagiaireheure AS dureestagiaireheure,
  base.nbouvriersprevue AS nbouvriersprevue,
  base.nbcadreprevue AS nbcadreprevue,
  base.objectif AS objectif,
  base.etat AS etat,
  base.etatlib AS etatlib,
  base.estrealiseelib AS estrealiseelib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idplanformation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idplanformationlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypeformation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypeformationlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idcategorieformation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idcategorieformationlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.formateur AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.reference AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.intitule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.typeprestataire AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idsemestre AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idsemestrelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbsessionprevus
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbsessionprevus
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbsessionprevus
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.dureestagiaireheure
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.dureestagiaireheure
                  ) AS TEXT)))
                  ELSE CAST((
                    base.dureestagiaireheure
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbouvriersprevue
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbouvriersprevue
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbouvriersprevue
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbcadreprevue
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbcadreprevue
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbcadreprevue
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.objectif AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    base.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.etatlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.estrealiseelib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    af.id AS id,
    af.idplanformation AS idplanformation,
    pf.libelle AS idplanformationlib,
    af.idtypeformation AS idtypeformation,
    tf.val AS idtypeformationlib,
    af.idcategorieformation AS idcategorieformation,
    cf.val AS idcategorieformationlib,
    af.formateur AS formateur,
    af.reference AS reference,
    af.intitule AS intitule,
    CASE
      WHEN af.typeprestataire = '1'
      THEN 'INTERNE'
      WHEN af.typeprestataire = '0'
      THEN 'EXTERNE'
      ELSE 'Inconnu'
    END AS typeprestataire,
    af.idsemestre AS idsemestre,
    s.val AS idsemestrelib,
    af.nbsessionprevus AS nbsessionprevus,
    af.dureestagiaireheure AS dureestagiaireheure,
    af.nbouvriersprevue AS nbouvriersprevue,
    af.nbcadreprevue AS nbcadreprevue,
    af.objectif AS objectif,
    af.etat AS etat,
    CASE
      WHEN af.etat = 1
      THEN 'Cree'
      WHEN af.etat = 11
      THEN 'Valide'
      WHEN af.etat = 0
      THEN 'Annule'
      ELSE 'Inconnu'
    END AS etatlib,
    CASE
      WHEN af.estrealisee = CAST('1' AS DECIMAL)
      THEN 'OUI'
      WHEN af.estrealisee = CAST('0' AS DECIMAL)
      THEN 'NON'
      ELSE 'Inconnu'
    END AS estrealiseelib
  FROM public.action_formation AS af
  LEFT JOIN public.plan_formation_annuel AS pf
    ON pf.id = af.idplanformation
  LEFT JOIN public.type_formation AS tf
    ON tf.id = af.idtypeformation
  LEFT JOIN public.categorie_formation AS cf
    ON cf.id = af.idcategorieformation
  LEFT JOIN public.semestre AS s
    ON s.id = af.idsemestre
) AS base;

