                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.calorie
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.calorie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
