        ' | ',
        COALESCE(CAST(sq.bienouserv AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.etatlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.compte_vente AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.compte_achat AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.pv
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.pv
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.pv
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.tva
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.tva
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.tva
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.typestock AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idunite AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.refpost AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.refqualification AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.refpostlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.refqualificationlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idfamillelib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.typeproduit AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idligne AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.compte_stock AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.compte_sortie_stock AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idfournisseurlib AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    ing.id AS id,
    ing.libelle AS libelle,
    ing.parfums AS parfums,
    ing.seuil AS seuil,
    au.val AS unite,
    ing.quantiteparpack AS quantiteparpack,
    ing.pu AS pu,
    ing.actif AS actif,
    ing.photo AS photo,
    ing.calorie AS calorie,
    ing.durre AS durre,
    ing.compose AS compose,
    CAST(CASE WHEN ing.compose = 1 THEN 'OUI' WHEN ing.compose = 0 THEN 'NON' END AS VARCHAR(100)) AS composelib,
    cating.id AS idcategorieingredient,
    cating.val AS categorieingredient,
    ing.categorieingredient AS idcategorie,
    ing.idfournisseur AS idfournisseur,
    ing.daty AS daty,
    cating.desce AS bienouserv,
    CASE
      WHEN ing.id IN (
        SELECT
          i.idproduit AS idproduit
        FROM public.indisponibilite AS i
      )
      THEN 'INDISPONIBLE'
      WHEN NOT ing.id IN (
        SELECT
          i.idproduit AS idproduit
        FROM public.indisponibilite AS i
      )
      THEN 'DISPONIBLE'
    END AS etatlib,
    ing.compte_vente AS compte_vente,
    ing.compte_achat AS compte_achat,
    ing.pv AS pv,
    ing.tva AS tva,
    ing.typestock AS typestock,
    ing.unite AS idunite,
    ing.refpost AS refpost,
    ing.refqualification AS refqualification,
    p.val AS refpostlib,
    qp.val AS refqualificationlib,
    fp.val AS idfamillelib,
    ing.typeproduit AS typeproduit,
    tp.idligne AS idligne,
    ing.compte_stock AS compte_stock,
    ing.compte_sortie_stock AS compte_sortie_stock,
    f.nom AS idfournisseurlib
  FROM public.as_ingredients AS ing
  LEFT JOIN public.as_unite AS au
    ON ing.unite = au.id
  LEFT JOIN public.categorieingredientlib AS cating
    ON cating.id = ing.categorieingredient
  LEFT JOIN public.poste AS p
    ON p.id = ing.refpost
  LEFT JOIN public.familleproduit AS fp
    ON fp.id = ing.idfamille
  LEFT JOIN public.qualification_paie AS qp
    ON qp.id = ing.refqualification
  LEFT JOIN public.type_produit AS tp
    ON tp.id = ing.typeproduit
  LEFT JOIN public.fournisseur AS f
    ON ing.idfournisseur = f.id
  LEFT JOIN public.as_ingredient_maintenance AS aim
    ON aim.idingredient = ing.id
  WHERE
    NOT aim.idingredient IS NULL AND aim.identite = 'ENT000004'
) AS sq;

-- Niveau 1 - vue 3 / 129 : AS_RECETTEOF
-- Dependances nouvelles : aucune.
CREATE VIEW public.as_recetteof (
    "id", "idproduits", "idingredients", "quantite", "unite", "compose"
) AS
SELECT
  _0.id AS id,
  _0.idproduits AS idproduits,
  _0.idingredients AS idingredients,
  CAST(_0.quantite AS DECIMAL(30, 10)) AS quantite,
  _0.unite AS unite,
  _0.compose AS compose
FROM (
  SELECT
    offi.id AS id,
    offi.idmere AS idproduits,
    offi.idingredients AS idingredients,
    CAST(offi.qte AS DECIMAL(30, 10)) * CAST(COALESCE(e.qte, 1) AS DECIMAL(30, 10)) AS quantite,
    ing.unite AS unite,
    ing.compose AS compose
  FROM public.offille AS offi
  LEFT JOIN public.equivalence AS e
    ON e.idproduit = offi.idingredients AND e.idunite = offi.idunite
  LEFT JOIN public.as_ingredients AS ing
    ON ing.id = offi.idingredients
  UNION ALL
  SELECT
    as_recettecompose.id AS id,
    as_recettecompose.idproduits AS idproduits,
    as_recettecompose.idingredients AS idingredients,
    as_recettecompose.quantite AS quantite,
    as_recettecompose.unite AS unite,
    as_recettecompose.compose AS compose
  FROM public.as_recettecompose AS as_recettecompose
) AS _0;

