CREATE VIEW public.avance_lib2 (
    "id", "idpersonnel", "montant", "nbremboursement", "remarque", "daty", "dateavance", "interet", "etat", "datedeblocage", "datedebutremboursement", "etatlib", "idtypeavance", "idtypeavancelib", "matricule", "moislib", "mois", "datesaisie", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.idpersonnel AS idpersonnel,
  base.montant AS montant,
  base.nbremboursement AS nbremboursement,
  base.remarque AS remarque,
  base.daty AS daty,
  base.dateavance AS dateavance,
  base.interet AS interet,
  base.etat AS etat,
  base.datedeblocage AS datedeblocage,
  base.datedebutremboursement AS datedebutremboursement,
  base.etatlib AS etatlib,
  base.idtypeavance AS idtypeavance,
  base.idtypeavancelib AS idtypeavancelib,
  base.matricule AS matricule,
  base.moislib AS moislib,
  base.mois AS mois,
  base.datesaisie AS datesaisie,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montant
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montant
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montant
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbremboursement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbremboursement
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbremboursement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.remarque AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.dateavance, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.interet
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.interet
                  ) AS TEXT)))
                  ELSE CAST((
                    base.interet
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    base.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(base.datedeblocage, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.datedebutremboursement, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(base.etatlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypeavance AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypeavancelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.moislib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.mois
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.mois
                  ) AS TEXT)))
                  ELSE CAST((
                    base.mois
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(base.datesaisie, 'YYYY-MM-DD HH24:MI:SS'), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    av.id AS id,
    NULLIF(CONCAT(log.nom, ' ', log.prenom), '') AS idpersonnel,
    av.montant AS montant,
    av.nbremboursement AS nbremboursement,
    av.remarque AS remarque,
    av.daty AS daty,
    av.dateavance AS dateavance,
    av.interet AS interet,
    av.etat AS etat,
    av.datedeblocage AS datedeblocage,
    av.datedebutremboursement AS datedebutremboursement,
    CASE
      WHEN av.etat = 1
      THEN '<span style= color:blue; >creee</span>'
      WHEN av.etat = 11
      THEN '<span style= color:blue; >validee et impayee</span>'
      WHEN av.etat = 21
      THEN '<span style= color:blue; >validee et payee </span>'
      ELSE NULL
    END AS etatlib,
    av.idtypeavance AS idtypeavance,
    ty.val AS idtypeavancelib,
    p.matricule AS matricule,
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(av.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
    av.mois AS mois,
    av.datesaisie AS datesaisie
  FROM public.avance AS av
  LEFT JOIN public.log_personnel AS log
    ON log.id = av.idpersonnel
  LEFT JOIN public.paie_info_personnel AS p
    ON p.id = log.id
  LEFT JOIN public.typeavance AS ty
    ON ty.id = av.idtypeavance
) AS base
ORDER BY
  CAST(REGEXP_REPLACE(base.matricule, '[^0-9]', NULL, 'g') AS DECIMAL);

