                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qtefabrestante
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qtefabrestante
                  ) AS TEXT)
                END
              ),
