                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.qtelivre
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qtelivre
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qtelivre
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.qtenonlivre
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qtenonlivre
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qtenonlivre
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.libelleproduit AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    bcf.id AS id,
    bcf.idbc AS idbc,
    bcf.iddevise AS iddevise,
    AVG(bcf.montant) AS montant,
    bcf.produit AS produit,
    AVG(bcf.pu) AS pu,
    AVG(bcf.quantite) AS quantite,
    AVG(bcf.remise) AS remise,
    AVG(bcf.tva) AS tva,
    ing.unite AS unite,
    COALESCE(AVG(o.qte), 0) AS qteof,
    COALESCE(SUM(bcf.quantite) - COALESCE(AVG(o.qte), 0), 0) AS qteofrestante,
    COALESCE(AVG(f.qte), 0) AS qtefab,
    COALESCE(SUM(bcf.quantite) - COALESCE(AVG(f.qte), 0), 0) AS qtefabrestante,
    AVG(COALESCE(abcf.quantite, 0)) AS qtelivre,
    COALESCE(AVG(bcf.quantite) - AVG(COALESCE(abcf.quantite, 0)), 0) AS qtenonlivre,
    ing.libelle AS libelleproduit,
    bccli.etat AS etat,
    bccli.daty AS daty,
    bccli.idclient AS idclient
  FROM public.bondecommande_client_fille AS bcf
  LEFT JOIN public.bondecommande_client AS bccli
    ON bccli.id = bcf.idbc
  LEFT JOIN public.ofgroupbyidbc AS o
    ON o.idbcfille = bcf.id
  LEFT JOIN public.fabrgroupbyidbc AS f
    ON f.idbcfille = bcf.id
  LEFT JOIN public.blgroupbyidbc AS abcf
    ON abcf.idbc_fille = bcf.id
  LEFT JOIN public.as_ingredients AS ing
    ON ing.id = bcf.produit
  GROUP BY
    bcf.idbc,
    bcf.id,
    bcf.iddevise,
    bcf.produit,
    ing.libelle,
    ing.unite,
    bccli.etat,
    bccli.daty,
    bccli.idclient
) AS sq;

-- Niveau 1 - vue 6 / 129 : CAISSECPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.caissecpl (
    "id", "val", "desce", "idtypecaisse", "idtypecaisselib", "idpoint", "idpointlib", "idpompiste", "etat", "compte", "etatlib", "idcategoriecaisse", "idcategoriecaisselib", "idmagasin", "idmagasinlib", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.val AS val,
  sq.desce AS desce,
  sq.idtypecaisse AS idtypecaisse,
  sq.idtypecaisselib AS idtypecaisselib,
  sq.idpoint AS idpoint,
  sq.idpointlib AS idpointlib,
  sq.idpompiste AS idpompiste,
  sq.etat AS etat,
  sq.compte AS compte,
  sq.etatlib AS etatlib,
  sq.idcategoriecaisse AS idcategoriecaisse,
  sq.idcategoriecaisselib AS idcategoriecaisselib,
  sq.idmagasin AS idmagasin,
  sq.idmagasinlib AS idmagasinlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.desce AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idtypecaisse AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idtypecaisselib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idpoint AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idpointlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idpompiste AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.compte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.etatlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idcategoriecaisse AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idcategoriecaisselib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idmagasin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idmagasinlib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    c.id AS id,
    c.val AS val,
    c.desce AS desce,
    c.idtypecaisse AS idtypecaisse,
    t.val AS idtypecaisselib,
    c.idpoint AS idpoint,
    p.val AS idpointlib,
    c.idpompiste AS idpompiste,
    c.etat AS etat,
    NULLIF(CONCAT(cop.libelle, '(', cop.compte, ')'), '') AS compte,
    CASE
      WHEN c.etat = 0
      THEN 'ANNUL&Eacute;'
      WHEN c.etat = 1
      THEN 'CR&Eacute;&Eacute;'
      WHEN c.etat = 11
      THEN 'VIS&Eacute;'
      ELSE NULL
    END AS etatlib,
    c.idcategoriecaisse AS idcategoriecaisse,
    c2.val AS idcategoriecaisselib,
    c.idmagasin AS idmagasin,
    m.val AS idmagasinlib
  FROM public.caisse AS c
  LEFT JOIN public.typecaisse AS t
    ON t.id = c.idtypecaisse
  LEFT JOIN public.point AS p
    ON p.id = c.idpoint
  LEFT JOIN public.categoriecaisse AS c2
    ON c2.id = c.idcategoriecaisse
  LEFT JOIN public.compta_compte AS cop
    ON cop.compte = c.compte
  LEFT JOIN public.magasin2 AS m
    ON m.id = c.idmagasin
) AS sq;

-- Niveau 1 - vue 7 / 129 : CAISSESESSIONLIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.caissesessionlib (
    "id", "dateouverture", "heureouverture", "datefermeture", "heurefermeture", "iduserouverture", "iduserfermeture", "etat", "idpoint", "idpointlib", "iduserouverturelib", "iduserfermeturelib", "idcaisselib"
) AS
SELECT
  cs.id AS id,
  cs.dateouverture AS dateouverture,
  cs.heureouverture AS heureouverture,
  cs.datefermeture AS datefermeture,
  cs.heurefermeture AS heurefermeture,
  cs.iduserouverture AS iduserouverture,
  cs.iduserfermeture AS iduserfermeture,
  cs.etat AS etat,
  cs.idpoint AS idpoint,
  pnt.val AS idpointlib,
  util.nomuser AS iduserouverturelib,
  util2.nomuser AS iduserfermeturelib,
  c.val AS idcaisselib
FROM public.caissesession AS cs
LEFT JOIN public.point AS pnt
  ON cs.idpoint = pnt.id
LEFT JOIN public.utilisateur AS util
  ON util.refuser = CAST(cs.iduserouverture AS DECIMAL)
LEFT JOIN public.utilisateur AS util2
  ON util2.refuser = CAST(cs.iduserfermeture AS DECIMAL)
LEFT JOIN public.caisse AS c
  ON c.id = cs.idcaisse;

-- Niveau 1 - vue 8 / 129 : CANDIDATURESLIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.candidatureslib (
    "id", "idcandidat", "idcandidatlib", "idoffreemploie", "idoffreemploielib", "etat", "etatlib", "dateapplication", "remarque", "raisonrefus", "motsclesss"
) AS
SELECT
  c.id AS id,
  c.idcandidat AS idcandidat,
  NULLIF(CONCAT(ca.nom, ' ', ca.prenom), '') AS idcandidatlib,
  c.idoffreemploie AS idoffreemploie,
  o.titre AS idoffreemploielib,
  c.etat AS etat,
  CASE
    WHEN c.etat = 1
    THEN 'Creee'
    WHEN c.etat = 11
    THEN 'Validee'
    WHEN c.etat = 13
    THEN 'Embauchee'
    WHEN c.etat = -1
    THEN 'Refuser'
    ELSE 'Inconnu'
  END AS etatlib,
  c.dateapplication AS dateapplication,
  c.remarque AS remarque,
  c.raisonrefus AS raisonrefus,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(c.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(c.idcandidat AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(ca.nom, ' ', ca.prenom), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(c.idoffreemploie AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(o.titre AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    c.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    c.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    c.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        CASE
          WHEN c.etat = 1
          THEN 'Creee'
          WHEN c.etat = 11
          THEN 'Validee'
          WHEN c.etat = 13
          THEN 'Embauchee'
          WHEN c.etat = -1
          THEN 'Refuser'
          ELSE 'Inconnu'
        END,
        ' | ',
        COALESCE(TO_CHAR(c.dateapplication, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(c.remarque AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(c.raisonrefus AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.candidatures AS c
LEFT JOIN public.candidat AS ca
  ON ca.id = c.idcandidat
LEFT JOIN public.offre_emploi AS o
  ON o.id = c.idoffreemploie;

