CREATE VIEW public.categ_qualilibcomplet (
    "id", "idcategorie", "idqualification", "remarque", "etat", "montant", "etatlibelle", "etatval", "matricule", "date_debut", "date_fin", "nomcpl", "prenom"
) AS
SELECT
  cq.id AS id,
  cp.val AS idcategorie,
  qp.val AS idqualification,
  cq.remarque AS remarque,
  cq.etat AS etat,
  cq.montant AS montant,
  CASE WHEN cq.etat = 1 THEN 'actif' ELSE 'inactif' END AS etatlibelle,
  ecq.desce AS etatval,
  vim.matricule AS matricule,
  cq.date_debut AS date_debut,
  cq.date_fin AS date_fin,
  NULLIF(CONCAT(vim.nom, vim.prenom), '') AS nomcpl,
  vim.prenom AS prenom
FROM public.categorie_qualification AS cq
JOIN public.categorie_paie AS cp
  ON cp.id = cq.idcategorie
JOIN public.qualification_paie AS qp
  ON qp.id = cq.idqualification
JOIN public.etat_categ_qualif2 AS ecq
  ON CAST(ecq.id AS DECIMAL) = cq.etat
LEFT JOIN public.vue_id_matricule AS vim
  ON vim.id = cq.remarque;

-- Niveau 1 - vue 12 / 129 : CATEG_QUALI_CONTRAT_2
-- Dependances nouvelles : aucune.
CREATE VIEW public.categ_quali_contrat_2 (
    "id", "idcategorie", "idqualification", "remarque", "etat", "montant", "date_debut", "date_fin", "datefin", "avenant", "numero"
) AS
SELECT
  cq.id AS id,
  cq.idcategorie AS idcategorie,
  cq.idqualification AS idqualification,
  cq.remarque AS remarque,
  cq.etat AS etat,
  cq.montant AS montant,
  cq.date_debut AS date_debut,
  cq.date_fin AS date_fin,
  COALESCE(
    (
      LEAD(cq.date_debut) OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - (
        1
      ) * INTERVAL '1 DAY'
    ),
    cq.date_fin
  ) AS datefin, /* Utilisation de LEAD pour datefin */
  CASE
    WHEN ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) = 1
    THEN 'initial'
    ELSE NULLIF(
      CONCAT(
        'Avenant N?',
        (
          ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1
        )
      ),
      ''
    )
  END AS avenant, /* Generation de l''avenant */
  CASE
    WHEN ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) = 1
    THEN '0'
    ELSE REPLACE(
      REGEXP_REPLACE(
        (
          CASE
            WHEN POSITION(
              '.' IN CAST((
                ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1
              ) AS TEXT)
            ) > 0
            THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
              ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1
            ) AS TEXT)))
            ELSE CAST((
              ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1
            ) AS TEXT)
          END
        ),
        '^(-?)0[.]',
        e'\\1.'
      ),
      '.',
      ','
    )
  END AS numero /* Numero de l''avenant */
FROM public.categ_quali_contrat AS cq;

-- Niveau 1 - vue 13 / 129 : CHARGE_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.charge_lib (
    "id", "daty", "libelle", "pu", "type", "idfabrication", "etat", "idingredients", "qte", "idoffille", "idof", "motsclesss", "typechargelib", "idingredientslib", "montant"
) AS
SELECT
  sq.id AS id,
  sq.daty AS daty,
  sq.libelle AS libelle,
  sq.pu AS pu,
  sq.type AS type,
  sq.idfabrication AS idfabrication,
  sq.etat AS etat,
  sq.idingredients AS idingredients,
  sq.qte AS qte,
  sq.idoffille AS idoffille,
  sq.idof AS idof,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(sq.libelle AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.pu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.pu
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.pu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.type AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idfabrication AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.idingredients AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.qte
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qte
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qte
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.idoffille AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idof AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss,
  sq.typechargelib AS typechargelib,
  sq.idingredientslib AS idingredientslib,
  sq.montant AS montant
FROM (
  SELECT
    c.id AS id,
    c.daty AS daty,
    c.libelle AS libelle,
    c.pu AS pu,
    c.type AS type,
    c.idfabrication AS idfabrication,
    c.etat AS etat,
    c.idingredients AS idingredients,
    c.qte AS qte,
    f.idoffille AS idoffille,
    f.idof AS idof,
    tc.val AS typechargelib,
    ing.libelle AS idingredientslib,
    CAST(COALESCE(c.pu * c.qte, 0) AS DECIMAL(30, 2)) AS montant
  FROM public.charge AS c
  LEFT JOIN public.fabrication AS f
    ON f.id = c.idfabrication
  LEFT JOIN public.typecharge AS tc
    ON c.type = tc.id
  LEFT JOIN public.as_ingredients AS ing
    ON c.idingredients = ing.id
) AS sq;

-- Niveau 1 - vue 14 / 129 : CHECKLIST_MERE_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.checklist_mere_lib (
    "id", "daty", "idpersonnel", "typecheckliste", "typechecklistelib", "idpersonnellib", "matricule", "idfonction", "idfonctionlib", "idservice", "idservicelib", "iddirection", "iddirectionlib", "motsclesss"
) AS
SELECT
  cm.id AS id,
  cm.daty AS daty,
  cm.idpersonnel AS idpersonnel,
  cm.typecheckliste AS typecheckliste,
  CASE cm.typecheckliste WHEN 0 THEN 'entree' WHEN 1 THEN 'sortie' ELSE 'Inconnu' END AS typechecklistelib,
  NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS idpersonnellib,
  pip.matricule AS matricule,
  pip.idfonction AS idfonction,
  pf.val AS idfonctionlib,
  lp.service AS idservice,
  ls.libelle AS idservicelib,
  lp.direction AS iddirection,
  ld.val AS iddirectionlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(cm.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(cm.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(cm.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    cm.typecheckliste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    cm.typecheckliste
                  ) AS TEXT)))
                  ELSE CAST((
                    cm.typecheckliste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        CASE cm.typecheckliste WHEN 0 THEN 'entree' WHEN 1 THEN 'sortie' ELSE 'Inconnu' END,
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pip.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pip.idfonction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pf.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(lp.service AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(ls.libelle AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(lp.direction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(ld.val AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.checklist_mere AS cm
LEFT JOIN public.log_personnel AS lp
  ON lp.id = cm.idpersonnel
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = lp.id
LEFT JOIN public.paie_fonction AS pf
  ON pf.id = pip.idfonction
LEFT JOIN public.log_service AS ls
  ON ls.id = lp.service
LEFT JOIN public.log_direction AS ld
  ON ld.id = lp.direction;

-- Niveau 1 - vue 15 / 129 : COMPTA_MOUVEMENT_ANALYTIQUE
-- Dependances nouvelles : aucune.
CREATE VIEW public.compta_mouvement_analytique (
    "debit", "credit", "compte", "etat", "libelle_compte", "typecompte", "mois", "annee", "chiffre3", "chiffre2"
) AS
SELECT
  CAST(SUM(_0.debit) AS DECIMAL(30, 2)) AS debit,
  CAST(SUM(_0.credit) AS DECIMAL(30, 2)) AS credit,
  _0.compte AS compte,
  _0.etat AS etat,
  _0.libelle_compte AS libelle_compte,
  _0.typecompte AS typecompte,
  _0.mois AS mois,
  _0.annee AS annee,
  _0.chiffre3 AS chiffre3,
  _0.chiffre2 AS chiffre2
FROM (
  SELECT
    cse.id AS id,
    cse.debit AS debit,
    cse.credit AS credit,
    cse.analytique AS compte,
    cc.libelle AS libelle_compte,
    cse.daty AS daty,
    cse.etat AS etat,
    cc.typecompte AS typecompte,
    EXTRACT(MONTH FROM cse.daty) AS mois,
    EXTRACT(YEAR FROM cse.daty) AS annee,
    NULLIF(
      CONCAT(
        NULLIF(SUBSTRING(cse.analytique FROM 1 FOR 3), ''),
        NULLIF(SUBSTRING(cse.analytique FROM 5 FOR 1), '')
      ),
      ''
    ) AS chiffre3,
    NULLIF(SUBSTRING(cse.analytique FROM 1 FOR 2), '') AS chiffre2
  FROM public.compta_sous_ecriture AS cse
  JOIN public.compta_compte AS cc
    ON cc.compte = cse.analytique
  WHERE
    cse.journal <> 'COMP000015'
    AND (
      cse.debit + cse.credit
    ) > 0
    AND cse.etat = 11
    AND NOT EXISTS(
      SELECT
        rs.id AS id
      FROM (
        SELECT
          ce.id,
          cse.compte,
          cc.libelle AS libelle_compte,
          cse.debit,
          cse.credit,
          ce.daty,
          cc.typecompte,
          EXTRACT(month FROM ce.daty) AS mois,
          EXTRACT(year FROM ce.daty) AS annee
        FROM public.compta_sous_ecriture AS cse, public.compta_ecriture AS ce, public.compta_compte AS cc, public.compta_journal AS jrn
        WHERE
          CAST(cse.idmere AS TEXT) = CAST(ce.id AS TEXT)
          AND CAST(cc.compte AS TEXT) = CAST(cse.compte AS TEXT)
          AND CAST(ce.journal AS TEXT) = CAST('COMP000015' AS TEXT)
          AND ce.etat = CAST(11 AS DECIMAL)
          AND CAST(jrn.id AS TEXT) = CAST(cse.journal AS TEXT)
        UNION
        SELECT
          ce.id,
          cse.analytique AS compte,
          cc.libelle AS libelle_compte,
          cse.debit,
          cse.credit,
          ce.daty,
          cc.typecompte,
          EXTRACT(month FROM ce.daty) AS mois,
          EXTRACT(year FROM ce.daty) AS annee
        FROM public.compta_sous_ecriture AS cse, public.compta_ecriture AS ce, public.compta_compte AS cc, public.compta_journal AS jrn
        WHERE
          CAST(cse.idmere AS TEXT) = CAST(ce.id AS TEXT)
          AND CAST(cc.compte AS TEXT) = CAST(cse.analytique AS TEXT)
          AND CAST(ce.journal AS TEXT) = CAST('COMP000015' AS TEXT)
          AND ce.etat = CAST(11 AS DECIMAL)
          AND CAST(jrn.id AS TEXT) = CAST(cse.journal AS TEXT)
      ) AS rs
      WHERE
        rs.id = cse.id
    )
) AS _0 /* group by   ce.id, cse.analytique, ce.daty, cse.etat, cc.LIBELLE, cc.typecompte , extract(month from cse.daty), */ /* extract(year from cse.daty) */
GROUP BY
  _0.compte,
  _0.etat,
  _0.libelle_compte,
  _0.typecompte,
  _0.mois,
  _0.annee,
  _0.chiffre3,
  _0.chiffre2
ORDER BY
  chiffre3 ASC;

-- Niveau 1 - vue 16 / 129 : COMPTA_MOUVEMENT_DETAILS_GEN_2
-- Dependances nouvelles : aucune.
CREATE VIEW public.compta_mouvement_details_gen_2 (
    "id", "contrep", "compte", "debit", "credit", "libellepiece", "remarque", "idmere", "reference_engagement", "compte_aux", "lettrage", "journal", "exercice", "etat", "daty", "folio", "coursdevise", "montantdevise", "compteint"
) AS
SELECT
  compta_mouvement_detailgen.id AS id,
  compta_mouvement_detailgen.contrep AS contrep,
  compta_mouvement_detailgen.compte AS compte,
  compta_mouvement_detailgen.debit AS debit,
  compta_mouvement_detailgen.credit AS credit,
  compta_mouvement_detailgen.libellepiece AS libellepiece,
  compta_mouvement_detailgen.remarque AS remarque,
  compta_mouvement_detailgen.mere AS idmere,
  compta_mouvement_detailgen.reference_engagement AS reference_engagement,
  compta_mouvement_detailgen.compte_aux AS compte_aux,
  compta_mouvement_detailgen.lettrage AS lettrage,
  compta_mouvement_detailgen.journal AS journal,
  compta_mouvement_detailgen.exercice AS exercice,
  compta_mouvement_detailgen.etat AS etat,
  compta_mouvement_detailgen.daty AS daty,
  compta_mouvement_detailgen.folio AS folio,
  CAST(compta_mouvement_detailgen.coursdevise AS DECIMAL(20, 2)) AS coursdevise,
  CAST(compta_mouvement_detailgen.montantdevise AS DECIMAL(20, 2)) AS montantdevise,
  CAST(SUBSTRING(NULLIF(TRIM(compta_mouvement_detailgen.compte), '') FROM '^[0-9]+') AS DECIMAL) AS compteint
FROM (
  SELECT
    cse.id,
    CAST(CAST(NULL AS TEXT) AS TEXT) AS contrep,
    cse.compte,
    cse.debit,
    cse.credit,
    cse.libellepiece,
    cse.remarque,
    cse.idmere AS mere,
    cse.analytique AS reference_engagement,
    cse.compte_aux,
    lettre.lettre AS lettrage,
    cj.val AS journal,
    EXTRACT(year FROM cse.daty) AS exercice,
    cse.etat,
    cse.daty,
    cse.folio,
    CAST(0 AS DECIMAL(20, 2)) AS coursdevise,
    CAST(0 AS DECIMAL(20, 2)) AS montantdevise
  FROM public.compta_sous_ecriture AS cse
  LEFT JOIN public.compta_journal_view AS cj
    ON CAST(cj.id AS TEXT) = CAST(cse.journal AS TEXT)
  LEFT JOIN public.compta_compte AS cc
    ON CAST(cse.compte AS TEXT) = CAST(cc.compte AS TEXT)
  LEFT JOIN public.compta_type_compte AS ctc
    ON CAST(cc.typecompte AS TEXT) = CAST(ctc.id AS TEXT)
  LEFT JOIN public.compta_lettrage AS lettre
    ON CAST(lettre.id AS TEXT) = CAST(cse.lettrage AS TEXT)
  WHERE
    1 < 2
    AND CAST(cj.id AS TEXT) <> CAST('COMP000015' AS TEXT)
    AND (
      cse.debit > CAST(0 AS DECIMAL)
      AND cse.credit = CAST(0 AS DECIMAL)
      OR cse.debit = CAST(0 AS DECIMAL)
      AND cse.credit > CAST(0 AS DECIMAL)
    )
) AS compta_mouvement_detailgen
WHERE
  NULLIF(TRIM(compta_mouvement_detailgen.compte), '') ~ '^[0-9]+';

-- Niveau 1 - vue 17 / 129 : COMPTA_MOUVEMENT_GENERAL
-- Dependances nouvelles : aucune.
CREATE VIEW public.compta_mouvement_general (
    "debit", "credit", "compte", "etat", "libelle_compte", "typecompte", "mois", "annee", "chiffre3", "chiffre2"
) AS
SELECT
  CAST(SUM(_0.debit) AS DECIMAL(30, 2)) AS debit,
  CAST(SUM(_0.credit) AS DECIMAL(30, 2)) AS credit,
  _0.compte AS compte,
  _0.etat AS etat,
  _0.libelle_compte AS libelle_compte,
  _0.typecompte AS typecompte,
  _0.mois AS mois,
  _0.annee AS annee,
  _0.chiffre3 AS chiffre3,
  _0.chiffre2 AS chiffre2
FROM (
  SELECT
    cse.id AS id,
    cse.debit AS debit,
    cse.credit AS credit,
    cse.compte AS compte,
    cc.libelle AS libelle_compte,
    cse.daty AS daty,
    cse.etat AS etat,
    cc.typecompte AS typecompte,
    EXTRACT(MONTH FROM cse.daty) AS mois,
    EXTRACT(YEAR FROM cse.daty) AS annee,
    CASE
      WHEN NULLIF(SUBSTRING(cse.compte FROM 1 FOR 4), '') = '4007'
      THEN '407'
      ELSE NULLIF(
        CONCAT(
          NULLIF(SUBSTRING(cse.compte FROM 1 FOR 2), ''),
          NULLIF(SUBSTRING(cse.compte FROM 5 FOR 1), '')
        ),
        ''
      )
    END AS chiffre3,
    NULLIF(SUBSTRING(cse.compte FROM 1 FOR 2), '') AS chiffre2
  FROM public.compta_sous_ecriture AS cse
  JOIN public.compta_compte AS cc
    ON cc.compte = cse.compte
  JOIN public.compta_journal AS cj
    ON cj.id = cse.journal
  WHERE
    (
      cse.debit + cse.credit
    ) > 0
    AND NOT EXISTS(
      SELECT
        rs.id AS id
      FROM (
        SELECT
          ce.id,
          cse.compte,
          cc.libelle AS libelle_compte,
          cse.debit,
          cse.credit,
          ce.daty,
          cc.typecompte,
          EXTRACT(month FROM ce.daty) AS mois,
          EXTRACT(year FROM ce.daty) AS annee
        FROM public.compta_sous_ecriture AS cse, public.compta_ecriture AS ce, public.compta_compte AS cc, public.compta_journal AS jrn
        WHERE
          CAST(cse.idmere AS TEXT) = CAST(ce.id AS TEXT)
          AND CAST(cc.compte AS TEXT) = CAST(cse.compte AS TEXT)
          AND CAST(ce.journal AS TEXT) = CAST('COMP000015' AS TEXT)
          AND ce.etat = CAST(11 AS DECIMAL)
          AND CAST(jrn.id AS TEXT) = CAST(cse.journal AS TEXT)
        UNION
        SELECT
          ce.id,
          cse.analytique AS compte,
          cc.libelle AS libelle_compte,
          cse.debit,
          cse.credit,
          ce.daty,
          cc.typecompte,
          EXTRACT(month FROM ce.daty) AS mois,
          EXTRACT(year FROM ce.daty) AS annee
        FROM public.compta_sous_ecriture AS cse, public.compta_ecriture AS ce, public.compta_compte AS cc, public.compta_journal AS jrn
        WHERE
          CAST(cse.idmere AS TEXT) = CAST(ce.id AS TEXT)
          AND CAST(cc.compte AS TEXT) = CAST(cse.analytique AS TEXT)
          AND CAST(ce.journal AS TEXT) = CAST('COMP000015' AS TEXT)
          AND ce.etat = CAST(11 AS DECIMAL)
          AND CAST(jrn.id AS TEXT) = CAST(cse.journal AS TEXT)
      ) AS rs
      WHERE
        rs.id = cse.id
    )
) AS _0
GROUP BY
  _0.compte,
  _0.etat,
  _0.libelle_compte,
  _0.typecompte,
  _0.mois,
  _0.annee,
  _0.chiffre3,
  _0.chiffre2
ORDER BY
  chiffre3 ASC;

-- Niveau 1 - vue 18 / 129 : COMPTA_SOUSECRITURE_LETTRE2
-- Dependances nouvelles : aucune.
CREATE VIEW public.compta_sousecriture_lettre2 (
    "id", "numero", "compte", "journal", "idjournal", "ecriture", "daty", "credit", "debit", "datecomptable", "exercice", "remarque", "etat", "idmere", "horsexercice", "od", "origine", "tiers", "libellepiece", "compte_aux", "raisonsocial", "folio", "lettrage", "analytique", "montantreste", "idvente", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.numero AS numero,
  sq.compte AS compte,
  sq.journal AS journal,
  sq.idjournal AS idjournal,
  sq.ecriture AS ecriture,
  sq.daty AS daty,
  sq.credit AS credit,
  sq.debit AS debit,
  sq.datecomptable AS datecomptable,
  sq.exercice AS exercice,
  sq.remarque AS remarque,
  sq.etat AS etat,
  sq.idmere AS idmere,
  sq.horsexercice AS horsexercice,
  sq.od AS od,
  sq.origine AS origine,
  sq.tiers AS tiers,
  sq.libellepiece AS libellepiece,
  sq.compte_aux AS compte_aux,
  sq.raisonsocial AS raisonsocial,
  sq.folio AS folio,
  sq.lettrage AS lettrage,
  sq.analytique AS analytique,
  sq.montantreste AS montantreste,
  sq.idvente AS idvente,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.numero AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.compte AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.journal AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idjournal AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.ecriture AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.credit
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.credit
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.credit
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.debit
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.debit
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.debit
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(sq.datecomptable, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.exercice
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.exercice
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.exercice
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.remarque AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.idmere AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.horsexercice
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.horsexercice
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.horsexercice
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.od AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.origine AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.tiers AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.libellepiece AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.compte_aux AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.raisonsocial AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.folio AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.lettrage AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.analytique AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantreste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantreste
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantreste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.idvente AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    lib.id AS id,
    lib.numero AS numero,
    lib.compte AS compte,
    lib.journal AS journal,
    lib.idjournal AS idjournal,
    lib.ecriture AS ecriture,
    lib.daty AS daty,
    lib.credit AS credit,
    lib.debit AS debit,
    lib.datecomptable AS datecomptable,
    lib.exercice AS exercice,
    lib.remarque AS remarque,
    lib.etat AS etat,
    lib.idmere AS idmere,
    lib.horsexercice AS horsexercice,
    lib.od AS od,
    lib.origine AS origine,
    lib.tiers AS tiers,
    lib.libellepiece AS libellepiece,
    lib.compte_aux AS compte_aux,
    lib.raisonsocial AS raisonsocial,
    lib.folio AS folio,
    lib.lettrage AS lettrage,
    lib.analytique AS analytique,
    v.montantreste AS montantreste,
    v.id AS idvente
  FROM public.compta_sousecriture_lib AS lib
  JOIN public.compta_ecriture AS ecr
    ON lib.idmere = ecr.id
  JOIN (
    SELECT
      v.id,
      v.designation,
      v.idmagasin,
      m.val AS idmagasinlib,
      v.daty,
      v.remarque,
      v.etat,
      CASE
        WHEN v.etat = CAST(1 AS DECIMAL)
        THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
        WHEN v.etat = CAST(11 AS DECIMAL)
        THEN CAST('VIS&Eacute;E' AS TEXT)
        WHEN v.etat = CAST(0 AS DECIMAL)
        THEN CAST('ANNUL&Eacute;E' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib,
      CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
      v2.iddevise,
      v.idclient,
      c.nom AS idclientlib,
      CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
      CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
      CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
      CAST(COALESCE(mv.montant, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
      CAST((
        COALESCE(v2.montantttc, CAST(0 AS DECIMAL)) - COALESCE(mv.montant, CAST(0 AS DECIMAL)) - COALESCE(acg.montantttcar - acg.montantpayear, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS montantreste,
      CAST(COALESCE(acg.montantttcar, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS avoir,
      CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
      CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
      CAST((
        v2.montantttcar - v2.montantrevient
      ) AS DECIMAL(20, 5)) AS margebrute,
      v.idreservation,
      CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
      rf.reference AS referencefacture,
      CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
      CAST((
        COALESCE(v2.montanttotal, CAST(0 AS DECIMAL)) + COALESCE(v2.montantremise, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS montant,
      EXTRACT(month FROM v.daty) AS mois,
      EXTRACT(year FROM v.daty) AS annee,
      CAST(v2.poids AS DECIMAL(30, 5)) AS poids,
      CAST(v2.colis AS DECIMAL(30, 5)) AS colis,
      v.modepaiement,
      mp.val AS modepaiementlib,
      COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(v2.poids, CAST(0 AS DECIMAL)) AS fraislivraison,
      v.modelivraison,
      CASE
        WHEN v.modelivraison = CAST(1 AS DECIMAL)
        THEN CAST('<span style=color: green;>LIVRAISON</span>' AS TEXT)
        WHEN v.modelivraison = CAST(2 AS DECIMAL)
        THEN CAST('<span style=color: green;>RECUPERATION</span>' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS modelivraisonlib,
      CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
      pv.id AS idprovince,
      pv.val AS provincelib,
      v.idorigine,
      CAST(COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS frais,
      v.referencefact,
      v.numerofacture,
      v.lieulivraison,
      v.datelivraison,
      v.updated_at,
      CASE
        WHEN v.estprevu = CAST(0 AS DECIMAL)
        THEN CAST('Non' AS TEXT)
        ELSE CAST('Oui' AS TEXT)
      END AS estprevulib,
      ce.id AS idecriture,
      COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
      NULLIF(
        CONCAT(
          (
            NULLIF(
              CONCAT(
                (
                  NULLIF(
                    CONCAT(
                      (
                        NULLIF(
                          CONCAT(
                            (
                              NULLIF(
                                CONCAT(
                                  (
                                    NULLIF(
                                      CONCAT(
                                        (
                                          NULLIF(
                                            CONCAT(
                                              (
                                                NULLIF(
                                                  CONCAT(
                                                    (
                                                      NULLIF(
                                                        CONCAT(
                                                          (
                                                            NULLIF(
                                                              CONCAT(
                                                                (
                                                                  NULLIF(
                                                                    CONCAT((
                                                                      NULLIF(CONCAT(CAST(v.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                                    ), v.daty),
                                                                    ''
                                                                  )
                                                                ),
                                                                CAST(NULL AS TEXT)
                                                              ),
                                                              ''
                                                            )
                                                          ),
                                                          CAST(v.idclient AS TEXT)
                                                        ),
                                                        ''
                                                      )
                                                    ),
                                                    CAST(NULL AS TEXT)
                                                  ),
                                                  ''
                                                )
                                              ),
                                              CAST(c.nom AS TEXT)
                                            ),
                                            ''
                                          )
                                        ),
                                        CAST(NULL AS TEXT)
                                      ),
                                      ''
                                    )
                                  ),
                                  CAST(v.idmagasin AS TEXT)
                                ),
                                ''
                              )
                            ),
                            CAST(NULL AS TEXT)
                          ),
                          ''
                        )
                      ),
                      CAST(m.val AS TEXT)
                    ),
                    ''
                  )
                ),
                CAST(NULL AS TEXT)
              ),
              ''
            )
          ),
          CAST(v.remarque AS TEXT)
        ),
        ''
      ) AS motsclesss,
      v.heuresaisie,
      v.adeclarer,
      v.factureechange,
      m.id AS idpoint
    FROM public.vente AS v
    LEFT JOIN public.client AS c
      ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
    LEFT JOIN public.point AS m
      ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
    LEFT JOIN public.zone AS pv
      ON CAST(pv.id AS TEXT) = CAST(m.idzone AS TEXT)
    JOIN (
      SELECT
        vd.idvente AS id,
        CAST(SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        ) AS DECIMAL(30, 2)) AS montanttotal,
        CAST((
          SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))) - SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            )
          )
        ) AS DECIMAL(30, 2)) AS montantremise,
        CAST(SUM(
          COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * COALESCE(vd.qte, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS frais,
        CAST(SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.puachat, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS montanttotalachat,
        CAST(SUM(
          (
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) AS DECIMAL(30, 2)) AS montanttva,
        CAST((
          SUM(
            (
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) + SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          )
        ) AS DECIMAL(30, 2)) AS montantttc,
        COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
        COALESCE(AVG(vd.tauxdechange), CAST(1 AS DECIMAL)) AS tauxdechange,
        CAST((
          SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL))
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) + SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            ) * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          )
        ) AS DECIMAL(30, 2)) AS montantttcar,
        CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
        v.idreservation,
        COALESCE(SUM(ing.calorie * vd.qte), CAST(0 AS DECIMAL)) AS poids,
        SUM(vd.qte) AS colis
      FROM public.vente_details AS vd
      LEFT JOIN public.vente AS v
        ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
      LEFT JOIN public.as_ingredients AS ing
        ON CAST(ing.id AS TEXT) = CAST(vd.idproduit AS TEXT)
      GROUP BY
        vd.idvente,
        vd.iddevise,
        v.idreservation
    ) AS v2
      ON CAST(v2.id AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.liaisonpaiementtotal AS mv
      ON CAST(v.id AS TEXT) = CAST(mv.id2 AS TEXT)
    LEFT JOIN (
      SELECT
        a.id,
        a.designation,
        a.idmagasin,
        CAST(NULL AS TEXT) AS idmagasinlib,
        a.daty,
        a.remarque,
        a.etat,
        a.idorigine,
        a.idclient,
        CAST(NULL AS TEXT) AS compte,
        CAST(NULL AS TEXT) AS compteauxiliaire,
        a.idvente,
        CAST(NULL AS TEXT) AS idventelib,
        a.idmotif,
        CAST(NULL AS TEXT) AS idmotiflib,
        a.idcategorie,
        CAST(NULL AS TEXT) AS idcategorielib,
        ag.iddevise,
        ag.tauxdechange,
        ag.montantht,
        ag.montanttva,
        ag.montantttc,
        ag.montanthtar,
        ag.montanttvaar,
        ag.montantttcar,
        CAST(NULL AS TEXT) AS idreservation,
        CAST(NULL AS TEXT) AS typeavoir,
        CAST(NULL AS TEXT) AS clientlib,
        COALESCE(m.montant, CAST(0 AS DECIMAL)) * COALESCE(ag.tauxdechange, CAST(0 AS DECIMAL)) AS montantpayear
      FROM public.avoirfc AS a
      JOIN public.avoirfcfille_grp AS ag
        ON CAST(ag.idavoirfc AS TEXT) = CAST(a.id AS TEXT)
      LEFT JOIN (
        SELECT
          m.id1 AS idorigine,
          SUM(m.montant) AS montant,
          CAST('AR' AS TEXT) AS iddevise
        FROM public.liaisonpaiement AS m
        WHERE
          m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
        GROUP BY
          m.id1
      ) AS m
        ON CAST(a.id AS TEXT) = CAST(m.idorigine AS TEXT)
      WHERE
        a.etat >= CAST(11 AS DECIMAL) AND a.idorigine IS NOT NULL
    ) AS acg
      ON CAST(acg.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.referencefacture AS rf
      ON CAST(rf.idfacture AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.modepaiement AS mp
      ON CAST(mp.id AS TEXT) = CAST(v.modepaiement AS TEXT)
    LEFT JOIN public.vente_reste AS vr
      ON CAST(vr.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.as_bondelivraison_client AS blc
      ON CAST(blc.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.compta_ecriture AS ce
      ON CAST(ce.idobjet AS TEXT) = CAST(v.id AS TEXT)
  ) AS v
    ON v.id = ecr.idobjet
  UNION ALL
  /* CAS 2 : MOUVEMENTCAISSE ? VENTE */
  SELECT
    lib.id AS id,
    lib.numero AS numero,
    lib.compte AS compte,
    lib.journal AS journal,
    lib.idjournal AS idjournal,
    lib.ecriture AS ecriture,
    lib.daty AS daty,
    lib.credit AS credit,
    lib.debit AS debit,
    lib.datecomptable AS datecomptable,
    lib.exercice AS exercice,
    lib.remarque AS remarque,
    lib.etat AS etat,
    lib.idmere AS idmere,
    lib.horsexercice AS horsexercice,
    lib.od AS od,
    mvt.idorigine AS idorigine,
    lib.tiers AS tiers,
    lib.libellepiece AS libellepiece,
    lib.compte_aux AS compte_aux,
    lib.raisonsocial AS raisonsocial,
    lib.folio AS folio,
    lib.lettrage AS lettrage,
    lib.analytique AS analytique,
    0 AS montantreste,
    mvt.idorigine AS idvente
  FROM public.compta_sousecriture_lib AS lib
  JOIN public.compta_ecriture AS ecr
    ON lib.idmere = ecr.id
  JOIN public.mouvementcaisse AS mvt
    ON mvt.id = ecr.idobjet
  JOIN public.vente AS v
    ON v.id = mvt.idorigine
  UNION ALL
  /* CAS 3 : FACTURE FOURNISSEUR */
  SELECT
    lib.id AS id,
    lib.numero AS numero,
    lib.compte AS compte,
    lib.journal AS journal,
    lib.idjournal AS idjournal,
    lib.ecriture AS ecriture,
    lib.daty AS daty,
    lib.credit AS credit,
    lib.debit AS debit,
    lib.datecomptable AS datecomptable,
    lib.exercice AS exercice,
    lib.remarque AS remarque,
    lib.etat AS etat,
    lib.idmere AS idmere,
    lib.horsexercice AS horsexercice,
    lib.od AS od,
    lib.origine AS origine,
    lib.tiers AS tiers,
    lib.libellepiece AS libellepiece,
    lib.compte_aux AS compte_aux,
    lib.raisonsocial AS raisonsocial,
    lib.folio AS folio,
    lib.lettrage AS lettrage,
    lib.analytique AS analytique,
    v.montantreste AS montantreste,
    v.id AS idvente
  FROM public.compta_sousecriture_lib AS lib
  JOIN public.compta_ecriture AS ecr
    ON lib.idmere = ecr.id
  JOIN (
    SELECT
      fcpl.id,
      fcpl.idfournisseur,
      fcpl.idfournisseurlib,
      fcpl.idmodepaiement,
      fcpl.idmodepaiementlib,
      fcpl.daty,
      fcpl.designation,
      fcpl.dateecheancepaiement,
      fcpl.etatlib,
      fcpl.reference,
      fcpl.idbc,
      fcpl.idmagasin,
      fcpl.idmagasinlib,
      fcpl.devise,
      fcpl.iddevise,
      fcpl.etat,
      CAST(fcpl.taux AS DECIMAL(30, 5)) AS taux,
      fcpl.montanttva,
      fcpl.montantht,
      fcpl.tauxdechange,
      fcpl.montantttc,
      CAST(COALESCE(fcpl.montantpaye * fcpl.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
      CAST(COALESCE(fcpl.montantreste * fcpl.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantreste,
      fcpl.idobjet,
      fcpl.idref,
      fcpl.idservicelib,
      fcpl.idtypefacture,
      fcpl.idfactureprincipale
    FROM (
      SELECT
        f.id,
        f.idfournisseur,
        f2.nom AS idfournisseurlib,
        f.idmodepaiement,
        m.val AS idmodepaiementlib,
        f.daty,
        f.designation,
        f.dateecheancepaiement,
        f.etat,
        CASE
          WHEN f.etat = CAST(1 AS DECIMAL)
          THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
          WHEN f.etat = CAST(0 AS DECIMAL)
          THEN CAST('ANNUL&Eacute;E' AS TEXT)
          WHEN f.etat = CAST(11 AS DECIMAL)
          THEN CAST('VIS&Eacute;E' AS TEXT)
          ELSE CAST(NULL AS TEXT)
        END AS etatlib,
        COALESCE(f.reference, reff.reference) AS reference,
        f.idbc,
        f.idmagasin,
        f.devise,
        CASE WHEN f.taux = CAST(0 AS DECIMAL) THEN CAST(1 AS DECIMAL) ELSE f.taux END AS taux,
        p.val AS idmagasinlib,
        f3.iddevise,
        CAST(f3.montanttva AS DECIMAL(30, 5)) AS montanttva,
        CAST((
          f3.montantttc - f3.montanttva
        ) AS DECIMAL(30, 5)) AS montantht,
        CAST(f3.montantttc AS DECIMAL(30, 5)) AS montantttc,
        CAST((
          f3.montantttc * f3.tauxdechange
        ) AS DECIMAL(30, 5)) AS montantttcar,
        CAST(COALESCE(mv.debit, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
        CAST((
          f3.montantttc - COALESCE(mv.debit, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS montantreste,
        CAST(COALESCE(f3.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS tauxdechange,
        prev.id AS idprevision,
        CASE
          WHEN f.estprevu = CAST(0 AS DECIMAL)
          THEN CAST('NON' AS TEXT)
          ELSE CAST('OUI' AS TEXT)
        END AS estprevulib,
        f.idobjet,
        f.idref,
        f.idtypefacture,
        tf.val AS typefacture,
        f.numero,
        f.typeachat,
        f.idfactureprincipale,
        s.libelle AS idservicelib,
        f.service,
        f.typefacturefournisseur,
        tff.desce AS typefacturefournisseurlib,
        ce.id AS idecriture,
        ta.val AS typeachatlib
      FROM public.facturefournisseur AS f
      LEFT JOIN public.typeachat AS ta
        ON CAST(ta.desce AS TEXT) = CAST(f.typeachat AS TEXT)
      LEFT JOIN public.fournisseur AS f2
        ON CAST(f2.id AS TEXT) = CAST(f.idfournisseur AS TEXT)
      LEFT JOIN public.modepaiement AS m
        ON CAST(m.id AS TEXT) = CAST(f.idmodepaiement AS TEXT)
      LEFT JOIN (
        SELECT
          p.id,
          p.val,
          p.desce,
          p.id AS idpoint,
          CAST('-' AS TEXT) AS idproduit,
          CAST(NULL AS TEXT) AS idtypemagasin,
          11 AS etat
        FROM public.point AS p
      ) AS p
        ON CAST(p.id AS TEXT) = CAST(f.idmagasin AS TEXT)
      JOIN (
        SELECT
          v.id,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            )
          ) AS DECIMAL(30, 2)) AS montanttotal,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) AS DECIMAL(30, 2)) AS montanttva,
          CAST((
            SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
            ) + SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              )
            )
          ) AS DECIMAL(30, 2)) AS montantttc,
          COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
          COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) AS tauxdechange
        FROM public.facturefournisseurfille AS vd
        LEFT JOIN public.facturefournisseur AS v
          ON CAST(v.id AS TEXT) = CAST(vd.idfacturefournisseur AS TEXT)
        GROUP BY
          v.id,
          vd.iddevise,
          vd.tauxdechange
      ) AS f3
        ON CAST(f.id AS TEXT) = CAST(f3.id AS TEXT)
      LEFT JOIN public.mouvementcaissegroupefacture AS mv
        ON CAST(f.id AS TEXT) = CAST(mv.idorigine AS TEXT)
      LEFT JOIN public.prevision AS prev
        ON CAST(prev.idfacture AS TEXT) = CAST(f.id AS TEXT)
      LEFT JOIN public.type_facture AS tf
        ON CAST(tf.id AS TEXT) = CAST(f.idtypefacture AS TEXT)
      LEFT JOIN public.service AS s
        ON CAST(f.service AS TEXT) = CAST(s.compte AS TEXT)
      LEFT JOIN public.referencefacture AS reff
        ON CAST(f.id AS TEXT) = CAST(reff.idfacture AS TEXT)
      LEFT JOIN public.typefacturefournisseur AS tff
        ON CAST(tff.id AS TEXT) = CAST(f.typefacturefournisseur AS TEXT)
      LEFT JOIN public.compta_ecriture AS ce
        ON CAST(ce.idobjet AS TEXT) = CAST(f.id AS TEXT)
    ) AS fcpl
  ) AS v
    ON v.id = ecr.idobjet
  UNION ALL
  /* CAS 4 : ECRITURE COMPTABLE SANS LIEN AVEC VENTE NI FACTURE FOURNISSEUR */
  SELECT
    lib.id AS id,
    lib.numero AS numero,
    lib.compte AS compte,
    lib.journal AS journal,
    lib.idjournal AS idjournal,
    lib.ecriture AS ecriture,
    lib.daty AS daty,
    lib.credit AS credit,
    lib.debit AS debit,
    lib.datecomptable AS datecomptable,
    lib.exercice AS exercice,
    lib.remarque AS remarque,
    lib.etat AS etat,
    lib.idmere AS idmere,
    lib.horsexercice AS horsexercice,
    lib.od AS od,
    lib.origine AS origine,
    lib.tiers AS tiers,
    lib.libellepiece AS libellepiece,
    lib.compte_aux AS compte_aux,
    lib.raisonsocial AS raisonsocial,
    lib.folio AS folio,
    lib.lettrage AS lettrage,
    lib.analytique AS analytique,
    CAST(NULL AS DECIMAL) AS montantreste,
    CAST(NULL AS TEXT) AS idvente
  FROM public.compta_sousecriture_lib AS lib
  JOIN public.compta_ecriture AS ecr
    ON lib.idmere = ecr.id
  LEFT JOIN (
    SELECT
      v.id,
      v.designation,
      v.idmagasin,
      m.val AS idmagasinlib,
      v.daty,
      v.remarque,
      v.etat,
      CASE
        WHEN v.etat = CAST(1 AS DECIMAL)
        THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
        WHEN v.etat = CAST(11 AS DECIMAL)
        THEN CAST('VIS&Eacute;E' AS TEXT)
        WHEN v.etat = CAST(0 AS DECIMAL)
        THEN CAST('ANNUL&Eacute;E' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib,
      CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
      v2.iddevise,
      v.idclient,
      c.nom AS idclientlib,
      CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
      CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
      CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
      CAST(COALESCE(mv.montant, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
      CAST((
        COALESCE(v2.montantttc, CAST(0 AS DECIMAL)) - COALESCE(mv.montant, CAST(0 AS DECIMAL)) - COALESCE(acg.montantttcar - acg.montantpayear, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS montantreste,
      CAST(COALESCE(acg.montantttcar, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS avoir,
      CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
      CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
      CAST((
        v2.montantttcar - v2.montantrevient
      ) AS DECIMAL(20, 5)) AS margebrute,
      v.idreservation,
      CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
      rf.reference AS referencefacture,
      CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
      CAST((
        COALESCE(v2.montanttotal, CAST(0 AS DECIMAL)) + COALESCE(v2.montantremise, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS montant,
      EXTRACT(month FROM v.daty) AS mois,
      EXTRACT(year FROM v.daty) AS annee,
      CAST(v2.poids AS DECIMAL(30, 5)) AS poids,
      CAST(v2.colis AS DECIMAL(30, 5)) AS colis,
      v.modepaiement,
      mp.val AS modepaiementlib,
      COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(v2.poids, CAST(0 AS DECIMAL)) AS fraislivraison,
      v.modelivraison,
      CASE
        WHEN v.modelivraison = CAST(1 AS DECIMAL)
        THEN CAST('<span style=color: green;>LIVRAISON</span>' AS TEXT)
        WHEN v.modelivraison = CAST(2 AS DECIMAL)
        THEN CAST('<span style=color: green;>RECUPERATION</span>' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS modelivraisonlib,
      CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
      pv.id AS idprovince,
      pv.val AS provincelib,
      v.idorigine,
      CAST(COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS frais,
      v.referencefact,
      v.numerofacture,
      v.lieulivraison,
      v.datelivraison,
      v.updated_at,
      CASE
        WHEN v.estprevu = CAST(0 AS DECIMAL)
        THEN CAST('Non' AS TEXT)
        ELSE CAST('Oui' AS TEXT)
      END AS estprevulib,
      ce.id AS idecriture,
      COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
      NULLIF(
        CONCAT(
          (
            NULLIF(
              CONCAT(
                (
                  NULLIF(
                    CONCAT(
                      (
                        NULLIF(
                          CONCAT(
                            (
                              NULLIF(
                                CONCAT(
                                  (
                                    NULLIF(
                                      CONCAT(
                                        (
                                          NULLIF(
                                            CONCAT(
                                              (
                                                NULLIF(
                                                  CONCAT(
                                                    (
                                                      NULLIF(
                                                        CONCAT(
                                                          (
                                                            NULLIF(
                                                              CONCAT(
                                                                (
                                                                  NULLIF(
                                                                    CONCAT((
                                                                      NULLIF(CONCAT(CAST(v.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                                    ), v.daty),
                                                                    ''
                                                                  )
                                                                ),
                                                                CAST(NULL AS TEXT)
                                                              ),
                                                              ''
                                                            )
                                                          ),
                                                          CAST(v.idclient AS TEXT)
                                                        ),
                                                        ''
                                                      )
                                                    ),
                                                    CAST(NULL AS TEXT)
                                                  ),
                                                  ''
                                                )
                                              ),
                                              CAST(c.nom AS TEXT)
                                            ),
                                            ''
                                          )
                                        ),
                                        CAST(NULL AS TEXT)
                                      ),
                                      ''
                                    )
                                  ),
                                  CAST(v.idmagasin AS TEXT)
                                ),
                                ''
                              )
                            ),
                            CAST(NULL AS TEXT)
                          ),
                          ''
                        )
                      ),
                      CAST(m.val AS TEXT)
                    ),
                    ''
                  )
                ),
                CAST(NULL AS TEXT)
              ),
              ''
            )
          ),
          CAST(v.remarque AS TEXT)
        ),
        ''
      ) AS motsclesss,
      v.heuresaisie,
      v.adeclarer,
      v.factureechange,
      m.id AS idpoint
    FROM public.vente AS v
    LEFT JOIN public.client AS c
      ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
    LEFT JOIN public.point AS m
      ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
    LEFT JOIN public.zone AS pv
      ON CAST(pv.id AS TEXT) = CAST(m.idzone AS TEXT)
    JOIN (
      SELECT
        vd.idvente AS id,
        CAST(SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        ) AS DECIMAL(30, 2)) AS montanttotal,
        CAST((
          SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))) - SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            )
          )
        ) AS DECIMAL(30, 2)) AS montantremise,
        CAST(SUM(
          COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * COALESCE(vd.qte, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS frais,
        CAST(SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.puachat, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS montanttotalachat,
        CAST(SUM(
          (
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) AS DECIMAL(30, 2)) AS montanttva,
        CAST((
          SUM(
            (
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) + SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          )
        ) AS DECIMAL(30, 2)) AS montantttc,
        COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
        COALESCE(AVG(vd.tauxdechange), CAST(1 AS DECIMAL)) AS tauxdechange,
        CAST((
          SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL))
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) + SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            ) * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          )
        ) AS DECIMAL(30, 2)) AS montantttcar,
        CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
        v.idreservation,
        COALESCE(SUM(ing.calorie * vd.qte), CAST(0 AS DECIMAL)) AS poids,
        SUM(vd.qte) AS colis
      FROM public.vente_details AS vd
      LEFT JOIN public.vente AS v
        ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
      LEFT JOIN public.as_ingredients AS ing
        ON CAST(ing.id AS TEXT) = CAST(vd.idproduit AS TEXT)
      GROUP BY
        vd.idvente,
        vd.iddevise,
        v.idreservation
    ) AS v2
      ON CAST(v2.id AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.liaisonpaiementtotal AS mv
      ON CAST(v.id AS TEXT) = CAST(mv.id2 AS TEXT)
    LEFT JOIN (
      SELECT
        a.id,
        a.designation,
        a.idmagasin,
        CAST(NULL AS TEXT) AS idmagasinlib,
        a.daty,
        a.remarque,
        a.etat,
        a.idorigine,
        a.idclient,
        CAST(NULL AS TEXT) AS compte,
        CAST(NULL AS TEXT) AS compteauxiliaire,
        a.idvente,
        CAST(NULL AS TEXT) AS idventelib,
        a.idmotif,
        CAST(NULL AS TEXT) AS idmotiflib,
        a.idcategorie,
        CAST(NULL AS TEXT) AS idcategorielib,
        ag.iddevise,
        ag.tauxdechange,
        ag.montantht,
        ag.montanttva,
        ag.montantttc,
        ag.montanthtar,
        ag.montanttvaar,
        ag.montantttcar,
        CAST(NULL AS TEXT) AS idreservation,
        CAST(NULL AS TEXT) AS typeavoir,
        CAST(NULL AS TEXT) AS clientlib,
        COALESCE(m.montant, CAST(0 AS DECIMAL)) * COALESCE(ag.tauxdechange, CAST(0 AS DECIMAL)) AS montantpayear
      FROM public.avoirfc AS a
      JOIN public.avoirfcfille_grp AS ag
        ON CAST(ag.idavoirfc AS TEXT) = CAST(a.id AS TEXT)
      LEFT JOIN (
        SELECT
          m.id1 AS idorigine,
          SUM(m.montant) AS montant,
          CAST('AR' AS TEXT) AS iddevise
        FROM public.liaisonpaiement AS m
        WHERE
          m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
        GROUP BY
          m.id1
      ) AS m
        ON CAST(a.id AS TEXT) = CAST(m.idorigine AS TEXT)
      WHERE
        a.etat >= CAST(11 AS DECIMAL) AND a.idorigine IS NOT NULL
    ) AS acg
      ON CAST(acg.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.referencefacture AS rf
      ON CAST(rf.idfacture AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.modepaiement AS mp
      ON CAST(mp.id AS TEXT) = CAST(v.modepaiement AS TEXT)
    LEFT JOIN public.vente_reste AS vr
      ON CAST(vr.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.as_bondelivraison_client AS blc
      ON CAST(blc.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.compta_ecriture AS ce
      ON CAST(ce.idobjet AS TEXT) = CAST(v.id AS TEXT)
  ) AS v
    ON v.id = ecr.idobjet
  LEFT JOIN (
    SELECT
      fcpl.id,
      fcpl.idfournisseur,
      fcpl.idfournisseurlib,
      fcpl.idmodepaiement,
      fcpl.idmodepaiementlib,
      fcpl.daty,
      fcpl.designation,
      fcpl.dateecheancepaiement,
      fcpl.etatlib,
      fcpl.reference,
      fcpl.idbc,
      fcpl.idmagasin,
      fcpl.idmagasinlib,
      fcpl.devise,
      fcpl.iddevise,
      fcpl.etat,
      CAST(fcpl.taux AS DECIMAL(30, 5)) AS taux,
      fcpl.montanttva,
      fcpl.montantht,
      fcpl.tauxdechange,
      fcpl.montantttc,
      CAST(COALESCE(fcpl.montantpaye * fcpl.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
      CAST(COALESCE(fcpl.montantreste * fcpl.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantreste,
      fcpl.idobjet,
      fcpl.idref,
      fcpl.idservicelib,
      fcpl.idtypefacture,
      fcpl.idfactureprincipale
    FROM (
      SELECT
        f.id,
        f.idfournisseur,
        f2.nom AS idfournisseurlib,
        f.idmodepaiement,
        m.val AS idmodepaiementlib,
        f.daty,
        f.designation,
        f.dateecheancepaiement,
        f.etat,
        CASE
          WHEN f.etat = CAST(1 AS DECIMAL)
          THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
          WHEN f.etat = CAST(0 AS DECIMAL)
          THEN CAST('ANNUL&Eacute;E' AS TEXT)
          WHEN f.etat = CAST(11 AS DECIMAL)
          THEN CAST('VIS&Eacute;E' AS TEXT)
          ELSE CAST(NULL AS TEXT)
        END AS etatlib,
        COALESCE(f.reference, reff.reference) AS reference,
        f.idbc,
        f.idmagasin,
        f.devise,
        CASE WHEN f.taux = CAST(0 AS DECIMAL) THEN CAST(1 AS DECIMAL) ELSE f.taux END AS taux,
        p.val AS idmagasinlib,
        f3.iddevise,
        CAST(f3.montanttva AS DECIMAL(30, 5)) AS montanttva,
        CAST((
          f3.montantttc - f3.montanttva
        ) AS DECIMAL(30, 5)) AS montantht,
        CAST(f3.montantttc AS DECIMAL(30, 5)) AS montantttc,
        CAST((
          f3.montantttc * f3.tauxdechange
        ) AS DECIMAL(30, 5)) AS montantttcar,
        CAST(COALESCE(mv.debit, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
        CAST((
          f3.montantttc - COALESCE(mv.debit, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS montantreste,
        CAST(COALESCE(f3.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS tauxdechange,
        prev.id AS idprevision,
        CASE
          WHEN f.estprevu = CAST(0 AS DECIMAL)
          THEN CAST('NON' AS TEXT)
          ELSE CAST('OUI' AS TEXT)
        END AS estprevulib,
        f.idobjet,
        f.idref,
        f.idtypefacture,
        tf.val AS typefacture,
        f.numero,
        f.typeachat,
        f.idfactureprincipale,
        s.libelle AS idservicelib,
        f.service,
        f.typefacturefournisseur,
        tff.desce AS typefacturefournisseurlib,
        ce.id AS idecriture,
        ta.val AS typeachatlib
      FROM public.facturefournisseur AS f
      LEFT JOIN public.typeachat AS ta
        ON CAST(ta.desce AS TEXT) = CAST(f.typeachat AS TEXT)
      LEFT JOIN public.fournisseur AS f2
        ON CAST(f2.id AS TEXT) = CAST(f.idfournisseur AS TEXT)
      LEFT JOIN public.modepaiement AS m
        ON CAST(m.id AS TEXT) = CAST(f.idmodepaiement AS TEXT)
      LEFT JOIN (
        SELECT
          p.id,
          p.val,
          p.desce,
          p.id AS idpoint,
          CAST('-' AS TEXT) AS idproduit,
          CAST(NULL AS TEXT) AS idtypemagasin,
          11 AS etat
        FROM public.point AS p
      ) AS p
        ON CAST(p.id AS TEXT) = CAST(f.idmagasin AS TEXT)
      JOIN (
        SELECT
          v.id,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            )
          ) AS DECIMAL(30, 2)) AS montanttotal,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) AS DECIMAL(30, 2)) AS montanttva,
          CAST((
            SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
            ) + SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              )
            )
          ) AS DECIMAL(30, 2)) AS montantttc,
          COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
          COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) AS tauxdechange
        FROM public.facturefournisseurfille AS vd
        LEFT JOIN public.facturefournisseur AS v
          ON CAST(v.id AS TEXT) = CAST(vd.idfacturefournisseur AS TEXT)
        GROUP BY
          v.id,
          vd.iddevise,
          vd.tauxdechange
      ) AS f3
        ON CAST(f.id AS TEXT) = CAST(f3.id AS TEXT)
      LEFT JOIN public.mouvementcaissegroupefacture AS mv
        ON CAST(f.id AS TEXT) = CAST(mv.idorigine AS TEXT)
      LEFT JOIN public.prevision AS prev
        ON CAST(prev.idfacture AS TEXT) = CAST(f.id AS TEXT)
      LEFT JOIN public.type_facture AS tf
        ON CAST(tf.id AS TEXT) = CAST(f.idtypefacture AS TEXT)
      LEFT JOIN public.service AS s
        ON CAST(f.service AS TEXT) = CAST(s.compte AS TEXT)
      LEFT JOIN public.referencefacture AS reff
        ON CAST(f.id AS TEXT) = CAST(reff.idfacture AS TEXT)
      LEFT JOIN public.typefacturefournisseur AS tff
        ON CAST(tff.id AS TEXT) = CAST(f.typefacturefournisseur AS TEXT)
      LEFT JOIN public.compta_ecriture AS ce
        ON CAST(ce.idobjet AS TEXT) = CAST(f.id AS TEXT)
    ) AS fcpl
  ) AS f
    ON f.id = ecr.idobjet
  WHERE
    v.id IS NULL AND f.id IS NULL
) AS sq
ORDER BY
  idvente DESC;

-- Niveau 1 - vue 19 / 129 : COMPTEURCPLRECENT
-- Dependances nouvelles : aucune.
CREATE VIEW public.compteurcplrecent (
    "id", "daty", "idligne", "valeur", "ecart", "idcategorie", "idmagasin", "etat", "ancien", "idlignelib", "idcategorielib", "idmagasinlib", "rn"
) AS
SELECT
  _0.id AS id,
  _0.daty AS daty,
  _0.idligne AS idligne,
  _0.valeur AS valeur,
  _0.ecart AS ecart,
  _0.idcategorie AS idcategorie,
  _0.idmagasin AS idmagasin,
  _0.etat AS etat,
  _0.ancien AS ancien,
  _0.idlignelib AS idlignelib,
  _0.idcategorielib AS idcategorielib,
  _0.idmagasinlib AS idmagasinlib,
  _0.rn AS rn
FROM (
  SELECT
    cm.id AS id,
    cm.daty AS daty,
    cm.idligne AS idligne,
    cm.valeur AS valeur,
    cm.ecart AS ecart,
    cm.idcategorie AS idcategorie,
    cm.idmagasin AS idmagasin,
    cm.etat AS etat,
    cm.ancien AS ancien,
    cm.idlignelib AS idlignelib,
    cm.idcategorielib AS idcategorielib,
    cm.idmagasinlib AS idmagasinlib,
    ROW_NUMBER() OVER (PARTITION BY cm.idligne, cm.idcategorie, cm.idmagasin ORDER BY cm.daty DESC) AS rn
  FROM (
    SELECT
      c.id,
      c.daty,
      c.idligne,
      c.ancien,
      c.valeur,
      c.ecart,
      c.idcategorie,
      l.val AS idlignelib,
      cc.libelle AS idcategorielib,
      c.etat,
      CASE
        WHEN c.etat = CAST(0 AS DECIMAL)
        THEN CAST('ANNUL&Eacute;E' AS TEXT)
        WHEN c.etat = CAST(1 AS DECIMAL)
        THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
        WHEN c.etat = CAST(11 AS DECIMAL)
        THEN CAST('VIS&Eacute;(E) par Chef de Fabrication' AS TEXT)
        WHEN c.etat = CAST(3 AS DECIMAL)
        THEN CAST('VIS&Eacute;(E) par Releveur' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib,
      c.idmagasin,
      m.val AS idmagasinlib
    FROM public.compteurmaintenance AS c
    LEFT JOIN public.ligne AS l
      ON CAST(l.id AS TEXT) = CAST(c.idligne AS TEXT)
    LEFT JOIN (
      SELECT
        ai.id,
        ai.libelle,
        ai.seuil,
        ai.unite,
        ai.quantiteparpack,
        ai.pu,
        ai.actif,
        ai.photo,
        ai.calorie,
        ai.durre,
        ai.compose,
        ai.categorieingredient,
        ai.idfournisseur,
        ai.daty,
        ai.qtelimite,
        ai.pv,
        ai.libellevente,
        ai.seuilmin,
        ai.seuilmax,
        ai.puachatusd,
        ai.puachateuro,
        ai.puachatautredevise,
        ai.puventeusd,
        ai.puventeeuro,
        ai.puventeautredevise,
        ai.isvente,
        ai.isachat,
        ai.compte_vente,
        ai.compte_achat,
        ai.libelleextacte,
        ai.tva,
        ai.filepath,
        ai.reste,
        ai.typestock,
        ai.refpost,
        ai.refqualification,
        ai.idchambre,
        ai.isperishable,
        ai.pv2,
        ai.idfamille,
        ai.idmagasin,
        ai.parfums,
        ai.ispetri,
        ai.typeconso,
        ai.compte_tva,
        ai.typeproduit
      FROM public.as_ingredients AS ai
      WHERE
        CAST(ai.categorieingredient AS TEXT) = CAST('CAT0011' AS TEXT)
    ) AS cc
      ON CAST(cc.id AS TEXT) = CAST(c.idcategorie AS TEXT)
    LEFT JOIN public.magasin2 AS m
      ON CAST(m.id AS TEXT) = CAST(c.idmagasin AS TEXT)
  ) AS cm
) AS _0
WHERE
  _0.rn = 1;

-- Niveau 1 - vue 20 / 129 : DEMANDETRANSFERTCPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.demandetransfertcpl (
    "id", "designation", "idmagasindepart", "idmagasindepartlib", "idmagasinarrive", "idmagasinarrivelib", "daty", "etat", "idof", "categorieingredient", "categorieingredientlib", "etatlib", "motsclesss", "montantquantite"
) AS
SELECT
  t.id AS id,
  t.designation AS designation,
  t.idmagasindepart AS idmagasindepart,
  m.val AS idmagasindepartlib,
  t.idmagasinarrive AS idmagasinarrive,
  m2.val AS idmagasinarrivelib,
  t.daty AS daty,
  t.etat AS etat,
  t.idof AS idof,
  t.categorieingredient AS categorieingredient,
  c.val AS categorieingredientlib,
  CASE
    WHEN t.etat = 0
    THEN 'Annul&eacute;'
    WHEN t.etat = 1
    THEN 'Cr&eacute;&eacute;'
    WHEN t.etat = 11
    THEN 'Vis&eacute;'
    ELSE NULL
  END AS etatlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(t.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(t.designation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(t.idmagasindepart AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(m.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(t.idmagasinarrive AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(m2.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(t.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    t.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    t.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    t.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(t.idof AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(t.categorieingredient AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(c.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          CASE
            WHEN t.etat = 0
            THEN 'Annul&eacute;'
            WHEN t.etat = 1
            THEN 'Cr&eacute;&eacute;'
            WHEN t.etat = 11
            THEN 'Vis&eacute;'
            ELSE NULL
          END,
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss,
  dmtsf.montantquantite AS montantquantite
FROM public.demandetransfert AS t
LEFT JOIN public.magasinpoint AS m
  ON m.id = t.idmagasindepart
LEFT JOIN public.magasinpoint AS m2
  ON m2.id = t.idmagasinarrive
LEFT JOIN public.categorieingredient AS c
  ON c.id = t.categorieingredient
LEFT JOIN public.demtransfillegroupemere AS dmtsf
  ON dmtsf.iddemandetransfert = t.id;

-- Niveau 1 - vue 21 / 129 : DEMANDETRAVAUX_CPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.demandetravaux_cpl (
    "id", "identite", "idsituation", "idmachine", "daty", "datebesoin", "priorite", "estexistant", "description", "etat", "iddepartement", "identitelib", "idsituationlib", "idmachinelib", "estexistantlib", "etatlib", "iddepartementmaintenance", "iddepartementmaintenancelib", "prioritelib", "iddepartementlib", "idotfille", "idtypemaintenance", "idtypemaintenancelib", "personnellib", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.identite AS identite,
  sq.idsituation AS idsituation,
  sq.idmachine AS idmachine,
  sq.daty AS daty,
  sq.datebesoin AS datebesoin,
  sq.priorite AS priorite,
  sq.estexistant AS estexistant,
  sq.description AS description,
  sq.etat AS etat,
  sq.iddepartement AS iddepartement,
  sq.identitelib AS identitelib,
  sq.idsituationlib AS idsituationlib,
  sq.idmachinelib AS idmachinelib,
  sq.estexistantlib AS estexistantlib,
  sq.etatlib AS etatlib,
  sq.iddepartementmaintenance AS iddepartementmaintenance,
  sq.iddepartementmaintenancelib AS iddepartementmaintenancelib,
  sq.prioritelib AS prioritelib,
  sq.iddepartementlib AS iddepartementlib,
  sq.idotfille AS idotfille,
  sq.idtypemaintenance AS idtypemaintenance,
  sq.idtypemaintenancelib AS idtypemaintenancelib,
  sq.personnellib AS personnellib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.identite AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idsituation AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idmachine AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.datebesoin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(sq.priorite AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.estexistant
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.estexistant
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.estexistant
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.description AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.iddepartement AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.identitelib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idsituationlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idmachinelib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.estexistantlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.etatlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.iddepartementmaintenance AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.iddepartementmaintenancelib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.prioritelib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.iddepartementlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idotfille AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idtypemaintenance AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idtypemaintenancelib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.personnellib AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    dmd.id AS id,
    dmd.identite AS identite,
    dmd.idsituation AS idsituation,
    dmd.idmachine AS idmachine,
    dmd.daty AS daty,
    dmd.datebesoin AS datebesoin,
    dmd.priorite AS priorite,
    dmd.estexistant AS estexistant,
    dmd.description AS description,
    dmd.etat AS etat,
    dmd.iddepartement AS iddepartement,
    e.val AS identitelib,
    s.val AS idsituationlib,
    m.libelle AS idmachinelib,
    CASE dmd.estexistant WHEN 0 THEN 'NON' WHEN 1 THEN 'OUI' ELSE 'Non specifie' END AS estexistantlib,
    CASE dmd.etat
      WHEN 1
      THEN 'CR&Eacute;&Eacute;E'
      WHEN 11
      THEN 'VALID&Eacute;E'
      ELSE 'CR&Eacute;&Eacute;E'
    END AS etatlib,
    d.id AS iddepartementmaintenance,
    d.val AS iddepartementmaintenancelib,
    pri.val AS prioritelib,
    departement.val AS iddepartementlib,
    otf.id AS idotfille,
    pl.idtypemaintenance AS idtypemaintenance,
    tm.val AS idtypemaintenancelib,
    pers.nom AS personnellib
  FROM public.demandetravaux AS dmd
  LEFT JOIN public.entite AS e
    ON e.id = dmd.identite
  LEFT JOIN public.situation AS s
    ON s.id = dmd.idsituation
  LEFT JOIN public.as_ingredient_maintenance AS m
    ON m.id = dmd.idmachine
  LEFT JOIN public.departementmaintenance AS d
    ON d.id = dmd.iddepartementmaintenance
  LEFT JOIN public.priorite AS pri
    ON dmd.priorite = pri.id
  LEFT JOIN public.departement AS departement
    ON departement.id = dmd.iddepartement
  LEFT JOIN public.ordretravaux AS o
    ON o.idbc = dmd.id
  LEFT JOIN public.ordretravauxfille AS otf
    ON otf.idmere = o.id
  LEFT JOIN public.planning AS pl
    ON pl.id = dmd.idplanning
  LEFT JOIN public.typemaintenance AS tm
    ON tm.id = pl.idtypemaintenance
  LEFT JOIN public.personnel AS pers
    ON dmd.demandeur = pers.id
) AS sq;

-- Niveau 1 - vue 22 / 129 : DEMANDE_REMPLACENTS
-- Dependances nouvelles : aucune.
CREATE VIEW public.demande_remplacents (
    "id", "remplacents"
) AS
SELECT
  d.id AS id,
  STRING_AGG(NULLIF(CONCAT(t.nom, ' ', t.prenom), ''), '   ,    '
  ORDER BY
    t.nom) AS remplacents
FROM public.demande AS d
LEFT JOIN (
  SELECT
    logp.id,
    logp.nom,
    logp.prenom,
    logp.id_pers,
    paie.initiale,
    paie.matricule,
    logp.date_naissance,
    paie.lieu_naissance_commune,
    s.desce AS sexe,
    logp.numero_cin,
    logp.date_cin,
    logp.date_dupl_cin,
    paie.lieu_delivrance_cin,
    logp.adresse,
    ld.val AS direction,
    sf.val AS fokotany,
    p.val AS nationalite,
    logp.acte_naissance,
    sitmat.desce AS situation_matrimonial,
    paie.idconjoint,
    serv.libelle AS service,
    pf.desce AS idfonction,
    paie.ctg,
    pc.val AS idcategorie,
    paie.classee,
    paie.indicegrade,
    paie.indice_fonctionnel,
    paie.matricule_patron,
    paie.statut,
    pm.val AS mode_paiement,
    paie.code_agence_banque,
    paie.banque_compte_cle,
    paie.banque_numero_compte,
    logp.permis_conduire,
    logp.remarque,
    logp.chemin_permis,
    paie.cturgence_nom_prenom,
    paie.cturgence_telephone1,
    paie.cturgence_telephone2,
    paie.cturgence_telephone3,
    paie.dateembauche,
    paie.datesaisie,
    serv.code_dr,
    trs.val AS banque_code,
    paie.echelon,
    paie.vehiculee,
    CASE paie.vehiculee
      WHEN 0
      THEN CAST('non' AS TEXT)
      WHEN 1
      THEN CAST('oui' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS vehiculee_str,
    tab.date_dernierpromo,
    paie.heurejournalier,
    paie.heurehebdomadaire,
    paie.heuremensuel,
    paie.numero_cnaps,
    paie.numero_ostie,
    paie.temporaire,
    CASE
      WHEN paie.temporaire = CAST('-1' AS DECIMAL)
      THEN CAST('Temporaire' AS TEXT)
      WHEN paie.temporaire = CAST(0 AS DECIMAL)
      THEN CAST('Permanent' AS TEXT)
      WHEN paie.temporaire = CAST(1 AS DECIMAL)
      THEN CAST('Cadre' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS temporaire_lib,
    paie.idstatut,
    stat.val AS idstatutlib,
    paie.nbenfant,
    lpnv.motif AS motif_debauche,
    ddt.val AS type_debauche,
    paie.adresse_ligne1,
    paie.adresse_ligne2,
    paie.mail,
    paie.telephone,
    paie.code_postal,
    reg.val AS region,
    paie.anneeexperience,
    fd.val AS formation,
    paie.discipline,
    paie.etat,
    cp.desce AS categoriepaielib,
    paie.iddepartement,
    dep.val AS iddepartementlib,
    paie.idcategorie_paie,
    paie.idqualification,
    paie.salairebase,
    paie.salairebase / 173.33 AS tauxhoraire
  FROM public.log_personnel AS logp
  LEFT JOIN (
    SELECT
      paie_avancement.id_logpers,
      MAX(paie_avancement.datedecision) AS date_dernierpromo
    FROM public.paie_avancement
    GROUP BY
      paie_avancement.id_logpers
  ) AS tab
    ON CAST(logp.id AS TEXT) = CAST(tab.id_logpers AS TEXT)
  LEFT JOIN public.paie_info_personnel AS paie
    ON CAST(logp.id AS TEXT) = CAST(paie.id AS TEXT)
  LEFT JOIN public.log_service AS serv
    ON CAST(serv.id AS TEXT) = CAST(logp.service AS TEXT)
  LEFT JOIN public.trs_banques_agences AS trs
    ON CAST(paie.code_agence_banque AS TEXT) = CAST(trs.id AS TEXT)
  LEFT JOIN public.sexe AS s
    ON logp.sexe = CAST(s.id AS BPCHAR)
  LEFT JOIN public.sig_fokontany AS sf
    ON CAST(logp.fokotany AS TEXT) = CAST(sf.id AS TEXT)
  LEFT JOIN public.pays AS p
    ON CAST(logp.nationalite AS TEXT) = CAST(p.id AS TEXT)
  LEFT JOIN public.log_direction AS ld
    ON CAST(logp.direction AS TEXT) = CAST(ld.id AS TEXT)
  LEFT JOIN public.paie_fonction AS pf
    ON CAST(paie.idfonction AS TEXT) = CAST(pf.id AS TEXT)
  LEFT JOIN public.paie_categorie AS pc
    ON CAST(paie.idcategorie AS TEXT) = CAST(pc.id AS TEXT)
  LEFT JOIN public.modepaiement AS pm
    ON CAST(paie.mode_paiement AS TEXT) = CAST(pm.id AS TEXT)
  LEFT JOIN public.situation_matrimoniale AS sitmat
    ON CAST(paie.situation_matrimonial AS TEXT) = CAST(sitmat.id AS TEXT)
  LEFT JOIN public.log_personnel_non_valide AS lpnv
    ON CAST(logp.id AS TEXT) = CAST(lpnv.idlogpers AS TEXT)
  LEFT JOIN public.dec_decision_type AS ddt
    ON CAST(lpnv.idtypedebauche AS TEXT) = CAST(ddt.id AS TEXT)
  LEFT JOIN public.region AS reg
    ON CAST(reg.id AS TEXT) = CAST(paie.region AS TEXT)
  LEFT JOIN public.formation_diplome AS fd
    ON CAST(fd.id AS TEXT) = CAST(paie.formation AS TEXT)
  LEFT JOIN public.categorie_paie AS cp
    ON CAST(paie.idcategorie_paie AS TEXT) = CAST(cp.id AS TEXT)
  LEFT JOIN public.departement AS dep
    ON CAST(dep.id AS TEXT) = CAST(paie.iddepartement AS TEXT)
  LEFT JOIN public.paie_statut AS stat
    ON CAST(stat.id AS TEXT) = CAST(paie.idstatut AS TEXT)
  WHERE
    CAST(logp.id AS TEXT) <> CAST('1002067' AS TEXT)
) AS t
  ON POSITION(t.id IN d.idremplacents) > 0
GROUP BY
  d.id;

