  SUM(d.indemnite_de_transport) AS indemnite_de_transport,
  SUM(d.avantages_en_nature) AS avantages_en_nature,
  SUM(d.juillet) + SUM(d.indemnitedepresentationbrut) + SUM(d.indemnite_de_transport) + SUM(d.avantages_en_nature) AS montant_brut,
  SUM(d.cnaps_travailleur) AS cnaps,
  SUM(d.juillet) + SUM(d.indemnitedepresentationbrut) + SUM(d.indemnite_de_transport) + SUM(d.avantages_en_nature) - SUM(d.cnaps_travailleur) AS brutcnaps,
  100 * TRUNC(
    CAST((
      SUM(d.juillet) + SUM(d.indemnitedepresentationbrut) + SUM(d.indemnite_de_transport) + SUM(d.avantages_en_nature) - SUM(d.cnaps_travailleur)
    ) AS DECIMAL) / 100
  ) AS imposable,
  SUM(d.irsa) AS irsa,
  ROUND(
    CAST((
      SUM(d.juillet) + SUM(d.indemnitedepresentationbrut) + SUM(d.indemnite_de_transport) + SUM(d.avantages_en_nature) - SUM(d.cnaps_travailleur) - SUM(d.irsa)
    ) AS DECIMAL),
    1
  ) AS netaprescalcul,
  SUM(d.reductionpourpersonnesacharge) AS reductionpourpersonnesacharge,
  SUM(d.irsanet) AS irsanet,
  SUM(d.net_a_payer) AS net_a_payer,
  d.mois AS mois,
  d.annee AS annee,
  o.dateembauche AS dateembauche,
  o.numero_cnaps AS numero_cnaps,
  o.matricule AS matricule,
  d.idedition AS idedition,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(d.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib
FROM (
  SELECT
    paie_edition.idpersonnel,
    paie_edition.idelementpaie,
    paie_edition.gain,
    paie_edition.retenue,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000041' AS TEXT)
      AND cq2.montant IS NOT NULL
      THEN cq2.montant
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000041' AS TEXT)
      AND cq2.montant IS NULL
      THEN cq.montant
      ELSE CAST(0 AS DECIMAL)
    END AS salaire_de_base,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000041' AS TEXT)
      AND cq2.montant IS NOT NULL
      THEN cq2.montant
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000041' AS TEXT)
      AND cq2.montant IS NULL
      THEN cq.montant
      ELSE CAST(0 AS DECIMAL)
    END / CAST(30 AS DECIMAL) AS taux,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000041' AS TEXT)
      THEN paie_edition.gain
      ELSE CAST(0 AS DECIMAL)
    END AS juillet,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000001' AS TEXT)
      THEN paie_edition.gain
      ELSE CAST(0 AS DECIMAL)
    END AS indemnite_de_transport,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000021' AS TEXT)
      THEN paie_edition.gain
      ELSE CAST(0 AS DECIMAL)
    END AS indemnitedepresentationbrut,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000201' AS TEXT)
      THEN paie_edition.gain
      ELSE CAST(0 AS DECIMAL)
    END AS avantages_en_nature,
    0 AS montant_brut,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000101' AS TEXT)
      THEN paie_edition.retenue
      ELSE CAST(0 AS DECIMAL)
    END AS cnaps_travailleur,
    0 AS brutcnaps,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000181' AS TEXT)
      THEN paie_edition.gain
      ELSE CAST(0 AS DECIMAL)
    END AS reductionpourpersonnesacharge,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000141' AS TEXT)
      THEN GREATEST(paie_edition.retenue, CAST(3000 AS DECIMAL))
      ELSE CAST(0 AS DECIMAL)
    END AS irsa,
    0 AS netaprescalcul,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000141NET' AS TEXT)
      THEN paie_edition.retenue
      ELSE CAST(0 AS DECIMAL)
    END AS irsanet,
    CASE
      WHEN CAST(paie_edition.idelementpaie AS TEXT) = CAST('PR000210A' AS TEXT)
      THEN paie_edition.gain
      ELSE CAST(0 AS DECIMAL)
    END AS net_a_payer,
    paie_edition.mois,
    paie_edition.annee,
    paie_edition.idedition
  FROM public.paie_edition
  JOIN public.paie_info_personnel AS pip
    ON CAST(pip.id AS TEXT) = CAST(paie_edition.idpersonnel AS TEXT)
  LEFT JOIN public.categorie_qualification AS cq
    ON CAST(cq.idcategorie AS TEXT) = CAST(pip.idcategorie_paie AS TEXT)
    AND CAST(cq.idqualification AS TEXT) = CAST(pip.idqualification AS TEXT)
    AND CAST(cq.remarque AS TEXT) = CAST('''' AS TEXT)
    AND cq.etat = CAST(1 AS DECIMAL)
  LEFT JOIN public.categorie_qualification AS cq2
    ON CAST(cq2.idcategorie AS TEXT) = CAST(pip.idcategorie_paie AS TEXT)
    AND CAST(cq2.idqualification AS TEXT) = CAST(pip.idqualification AS TEXT)
    AND CAST(cq2.remarque AS TEXT) = CAST(paie_edition.idpersonnel AS TEXT)
    AND CAST(cq2.remarque AS TEXT) = CAST(pip.id AS TEXT)
    AND cq2.etat = CAST(1 AS DECIMAL)
) AS d
LEFT JOIN public.paie_info_personnel_libcomplet AS o
  ON o.id = d.idpersonnel
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = d.idpersonnel
LEFT JOIN public.paie_fonction AS pf
  ON pf.id = pip.idfonction
GROUP BY
  d.idpersonnel,
  o.cturgence_nom_prenom,
  pf.desce,
