-- Niveau 1 - vue 25 / 129 : ELEMENTINSPECTIONMACHINELIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.elementinspectionmachinelib (
    "id", "idelementinspection", "idmachine", "idelementinspectionlib", "idmachinelib", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.idelementinspection AS idelementinspection,
  sq.idmachine AS idmachine,
  sq.idelementinspectionlib AS idelementinspectionlib,
  sq.idmachinelib AS idmachinelib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idelementinspection AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idmachine AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idelementinspectionlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idmachinelib AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    eim.id AS id,
    eim.idelementinspection AS idelementinspection,
    eim.idmachine AS idmachine,
    ei.val AS idelementinspectionlib,
    m.descriptionobjet AS idmachinelib
  FROM public.elementinspectionmachine AS eim
  LEFT JOIN public.elementinspection AS ei
    ON eim.idelementinspection = ei.id
  LEFT JOIN public.as_ingredient_maintenance AS m
    ON eim.idmachine = m.id
) AS sq;

-- Niveau 1 - vue 26 / 129 : EQUIVALENCECARTONLIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.equivalencecartonlib (
    "id", "idpetris", "idcarton", "nbcarton", "idpetrislib", "idcartonlib", "motsclesss"
) AS
SELECT
  e.id AS id,
  e.idpetris AS idpetris,
  e.idcarton AS idcarton,
  e.nbcarton AS nbcarton,
  a.libelle AS idpetrislib,
  p.libelle AS idcartonlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(e.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(e.idpetris AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(e.idcarton AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    e.nbcarton
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    e.nbcarton
                  ) AS TEXT)))
                  ELSE CAST((
                    e.nbcarton
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(a.libelle AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(p.libelle AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.equivalencecarton AS e
LEFT JOIN public.as_ingredients AS a
  ON a.id = e.idpetris
LEFT JOIN public.as_ingredients AS p
  ON p.id = e.idcarton;

-- Niveau 1 - vue 27 / 129 : EVALUATION_FROID_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.evaluation_froid_lib (
    "id", "idformationsuivi", "idpersonnel", "note", "commentaire", "dateevaluation", "personnel", "matricule", "motsclesss"
) AS
SELECT
  ef.id AS id,
  ef.idformationsuivi AS idformationsuivi,
  ef.idpersonnel AS idpersonnel,
  ef.note AS note,
  ef.commentaire AS commentaire,
  ef.dateevaluation AS dateevaluation,
  NULLIF(CONCAT(lp.nom, lp.prenom), '') AS personnel,
  pip.matricule AS matricule,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(ef.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(ef.idformationsuivi AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(ef.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    ef.note
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    ef.note
                  ) AS TEXT)))
                  ELSE CAST((
                    ef.note
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(ef.commentaire AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(ef.dateevaluation, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(lp.nom, lp.prenom), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pip.matricule AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.evaluation_froid AS ef
LEFT JOIN public.log_personnel AS lp
  ON lp.id = ef.idpersonnel
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = ef.idpersonnel;

-- Niveau 1 - vue 28 / 129 : FABRICATIONCPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.fabricationcpl (
    "id", "lancepar", "cible", "remarque", "libelle", "besoin", "daty", "idoffille", "idof", "lanceparlib", "ciblelib", "etat", "lanceur", "lanceurlib", "etatlib", "fabricationprec", "fabricationsuiv"
) AS
SELECT
  f.id AS id,
  f.lancepar AS lancepar,
  f.cible AS cible,
  f.remarque AS remarque,
  f.libelle AS libelle,
  f.besoin AS besoin,
  f.daty AS daty,
  f.idoffille AS idoffille,
  COALESCE(f.idof, off.idmere) AS idof,
  p.val AS lanceparlib,
  p2.val AS ciblelib,
  f.etat AS etat,
  f.lanceur AS lanceur,
  NULLIF(CONCAT(lp.prenom, lp.nom), '') AS lanceurlib,
  CASE
    WHEN f.etat = 1
    THEN 'CREE'
    WHEN f.etat = 11
    THEN 'VALIDE'
    WHEN f.etat = 0
    THEN 'ANNULE'
    WHEN f.etat = 21
    THEN 'ENTAME'
    WHEN f.etat = 31
    THEN 'BLOQUE'
    WHEN f.etat = 41
    THEN 'TERMINE'
  END AS etatlib,
  f.fabricationprec AS fabricationprec,
  f.fabricationsuiv AS fabricationsuiv
FROM public.fabrication AS f
LEFT JOIN public.magasinpoint AS p
  ON p.id = f.lancepar
LEFT JOIN public.magasinpoint AS p2
  ON p2.id = f.cible
LEFT JOIN public.offille AS off
  ON f.idoffille = off.id
LEFT JOIN public.log_personnel AS lp
  ON lp.id = f.lanceur;

-- Niveau 1 - vue 29 / 129 : FACTUREFOURNISSEURCPL_MONTANT
-- Dependances nouvelles : aucune.
CREATE VIEW public.facturefournisseurcpl_montant (
    "id", "idfournisseur", "idfournisseurlib", "idmodepaiement", "idmodepaiementlib", "daty", "designation", "dateecheancepaiement", "etat", "etatlib", "reference", "idbc", "idmagasin", "devise", "taux", "idmagasinlib", "montant", "montantpayer", "montantreste"
) AS
SELECT
  f.id AS id,
  f.idfournisseur AS idfournisseur,
  f2.nom AS idfournisseurlib,
  f.idmodepaiement AS idmodepaiement,
  mp.val AS idmodepaiementlib,
  f.daty AS daty,
  f.designation AS designation,
  f.dateecheancepaiement AS dateecheancepaiement,
  f.etat AS etat,
  CASE
    WHEN f.etat = 1
    THEN 'CREE'
    WHEN f.etat = 0
    THEN 'ANNULEE'
    WHEN f.etat = 11
    THEN 'VISEE'
    WHEN f.etat = 9
    THEN 'ENCAISEE'
  END AS etatlib,
  f.reference AS reference,
  f.idbc AS idbc,
  f.idmagasin AS idmagasin,
  f.devise AS devise,
  f.taux AS taux,
  p.val AS idmagasinlib,
  CAST(mon.montant AS DECIMAL(30, 2)) AS montant,
  CAST(COALESCE(m.montantapayer, 0) AS DECIMAL(30, 2)) AS montantpayer,
  CASE
    WHEN mon.montant < COALESCE(m.montantapayer, 0)
    THEN 0
    ELSE CAST((
      mon.montant - COALESCE(m.montantapayer, 0)
    ) AS DECIMAL(30, 2))
  END AS montantreste
FROM public.facturefournisseur AS f
LEFT JOIN public.fournisseur AS f2
  ON f2.id = f.idfournisseur
LEFT JOIN public.modepaiement AS mp
  ON mp.id = f.idmodepaiement
LEFT JOIN (
  SELECT
    p.id,
    p.val,
    p.desce,
    p.id AS idpoint,
    CAST('-' AS TEXT) AS idproduit,
    CAST(NULL AS TEXT) AS idtypemagasin,
    11 AS etat
  FROM public.point AS p
) AS p
  ON p.id = f.idmagasin
LEFT JOIN public.facturefournisseur_montant AS mon
  ON mon.idfacturefournisseur = f.id
LEFT JOIN public.montantapayer AS m
  ON f.id = m.idfacturefournisseur;

-- Niveau 1 - vue 30 / 129 : FACTUREFOURNISSEUR_FL_ERITURE
-- Dependances nouvelles : aucune.
CREATE VIEW public.facturefournisseur_fl_eriture (
    "compte", "idfacturefournisseur", "montantht", "iddevise", "tauxdechange"
) AS
SELECT
  _0.compte AS compte,
  _0.idfacturefournisseur AS idfacturefournisseur,
  CAST(_0.montantht AS DECIMAL(32, 2)) AS montantht,
  _0.iddevise AS iddevise,
  _0.tauxdechange AS tauxdechange
FROM (
  SELECT
    facturefournisseur_fl_compte.compte AS compte,
    facturefournisseur_fl_compte.idfacturefournisseur AS idfacturefournisseur,
    CAST(facturefournisseur_fl_compte.montantht AS DECIMAL(32, 2)) AS montantht,
    facturefournisseur_fl_compte.iddevise AS iddevise,
    facturefournisseur_fl_compte.tauxdechange AS tauxdechange
  FROM public.facturefournisseur_fl_compte AS facturefournisseur_fl_compte
  UNION ALL
  SELECT
    facturefournisseur_fl_tva.compte AS compte,
    facturefournisseur_fl_tva.idfacturefournisseur AS idfacturefournisseur,
    CAST(facturefournisseur_fl_tva.montantht AS DECIMAL(32, 2)) AS montantht,
    facturefournisseur_fl_tva.iddevise AS iddevise,
    facturefournisseur_fl_tva.tauxdechange AS tauxdechange
  FROM public.facturefournisseur_fl_tva AS facturefournisseur_fl_tva
) AS _0;

-- Niveau 1 - vue 31 / 129 : FACTUREFOURNISSEUR_RECAP_JOUR
-- Dependances nouvelles : aucune.
CREATE VIEW public.facturefournisseur_recap_jour (
    "daty", "montantttc", "montantpaye", "montantreste", "nombre", "montantresteacejour"
) AS
WITH bornes AS (
  SELECT
    CAST('2026-06-01' AS DATE) AS date_min,
    DATE_TRUNC('day', LOCALTIMESTAMP(0)) AS date_max
), calendrier AS (
  SELECT
    g.daty AS daty
  FROM bornes AS b
  CROSS JOIN LATERAL GENERATE_SERIES(CAST(b.date_min AS TIMESTAMP), CAST(b.date_max AS TIMESTAMP), INTERVAL '1 DAY') AS g(daty)
), facture_jour AS (
  SELECT
    DATE_TRUNC('DAY', facturefournisseurcpl_tous_fae.daty) AS daty,
    SUM(COALESCE(facturefournisseurcpl_tous_fae.montantttc, 0)) AS montantttc,
    SUM(COALESCE(facturefournisseurcpl_tous_fae.montantpaye, 0)) AS montantpaye,
    SUM(COALESCE(facturefournisseurcpl_tous_fae.montantreste, 0)) AS montantreste,
    COUNT(*) AS nombre
  FROM (
    SELECT
      fcpl.id,
      fcpl.idfournisseur,
      fcpl.idfournisseurlib,
      fcpl.idmodepaiement,
      fcpl.idmodepaiementlib,
      fcpl.daty,
      fcpl.designation,
      fcpl.dateecheancepaiement,
      fcpl.etatlib,
      fcpl.reference,
      fcpl.idbc,
      fcpl.idmagasin,
      fcpl.idmagasinlib,
      fcpl.devise,
      fcpl.iddevise,
      fcpl.etat,
      CAST(fcpl.taux AS DECIMAL(30, 5)) AS taux,
      fcpl.montanttva,
      fcpl.montantht,
      fcpl.tauxdechange,
      fcpl.montantttc,
      CAST(COALESCE(fcpl.montantpaye * fcpl.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
      CAST(COALESCE(fcpl.montantreste * fcpl.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantreste,
      fcpl.idobjet,
      fcpl.idref,
      fcpl.idservicelib,
      fcpl.idtypefacture,
      fcpl.idfactureprincipale,
      fcpl.typefacture
    FROM (
      SELECT
        f.id,
        f.idfournisseur,
        f2.nom AS idfournisseurlib,
        f.idmodepaiement,
        m.val AS idmodepaiementlib,
        f.daty,
        f.designation,
        f.dateecheancepaiement,
        f.etat,
        CASE
          WHEN f.etat = CAST(1 AS DECIMAL)
          THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
          WHEN f.etat = CAST(0 AS DECIMAL)
          THEN CAST('ANNUL&Eacute;E' AS TEXT)
          WHEN f.etat = CAST(11 AS DECIMAL)
          THEN CAST('VIS&Eacute;E' AS TEXT)
          ELSE CAST(NULL AS TEXT)
        END AS etatlib,
        COALESCE(f.reference, reff.reference) AS reference,
        f.idbc,
        f.idmagasin,
        f.devise,
        CASE WHEN f.taux = CAST(0 AS DECIMAL) THEN CAST(1 AS DECIMAL) ELSE f.taux END AS taux,
        p.val AS idmagasinlib,
        f3.iddevise,
        CAST(f3.montanttva AS DECIMAL(30, 5)) AS montanttva,
        CAST((
          f3.montantttc - f3.montanttva
        ) AS DECIMAL(30, 5)) AS montantht,
        CAST(f3.montantttc AS DECIMAL(30, 5)) AS montantttc,
        CAST((
          f3.montantttc * f3.tauxdechange
        ) AS DECIMAL(30, 5)) AS montantttcar,
        CAST(COALESCE(mv.debit, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
        CAST((
          f3.montantttc - COALESCE(mv.debit, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS montantreste,
        CAST(COALESCE(f3.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS tauxdechange,
        prev.id AS idprevision,
        CASE
          WHEN f.estprevu = CAST(0 AS DECIMAL)
          THEN CAST('NON' AS TEXT)
          ELSE CAST('OUI' AS TEXT)
        END AS estprevulib,
        f.idobjet,
        f.idref,
        f.idtypefacture,
        tf.val AS typefacture,
        f.numero,
        f.typeachat,
        f.idfactureprincipale,
        s.libelle AS idservicelib,
        f.service,
        f.typefacturefournisseur,
        tff.desce AS typefacturefournisseurlib,
        ce.id AS idecriture,
        ta.val AS typeachatlib
      FROM public.facturefournisseur AS f
      LEFT JOIN public.typeachat AS ta
        ON CAST(ta.desce AS TEXT) = CAST(f.typeachat AS TEXT)
      LEFT JOIN public.fournisseur AS f2
        ON CAST(f2.id AS TEXT) = CAST(f.idfournisseur AS TEXT)
      LEFT JOIN public.modepaiement AS m
        ON CAST(m.id AS TEXT) = CAST(f.idmodepaiement AS TEXT)
      LEFT JOIN (
        SELECT
          p.id,
          p.val,
          p.desce,
          p.id AS idpoint,
          CAST('-' AS TEXT) AS idproduit,
          CAST(NULL AS TEXT) AS idtypemagasin,
          11 AS etat
        FROM public.point AS p
      ) AS p
        ON CAST(p.id AS TEXT) = CAST(f.idmagasin AS TEXT)
      JOIN (
        SELECT
          v.id,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            )
          ) AS DECIMAL(30, 2)) AS montanttotal,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) AS DECIMAL(30, 2)) AS montanttva,
          CAST((
            SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
            ) + SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              )
            )
          ) AS DECIMAL(30, 2)) AS montantttc,
          COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
          COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) AS tauxdechange
        FROM public.facturefournisseurfille AS vd
        LEFT JOIN public.facturefournisseur AS v
          ON CAST(v.id AS TEXT) = CAST(vd.idfacturefournisseur AS TEXT)
        GROUP BY
          v.id,
          vd.iddevise,
          vd.tauxdechange
      ) AS f3
        ON CAST(f.id AS TEXT) = CAST(f3.id AS TEXT)
      LEFT JOIN public.mouvementcaissegroupefacture AS mv
        ON CAST(f.id AS TEXT) = CAST(mv.idorigine AS TEXT)
      LEFT JOIN public.prevision AS prev
        ON CAST(prev.idfacture AS TEXT) = CAST(f.id AS TEXT)
      LEFT JOIN public.type_facture AS tf
        ON CAST(tf.id AS TEXT) = CAST(f.idtypefacture AS TEXT)
      LEFT JOIN public.service AS s
        ON CAST(f.service AS TEXT) = CAST(s.compte AS TEXT)
      LEFT JOIN public.referencefacture AS reff
        ON CAST(f.id AS TEXT) = CAST(reff.idfacture AS TEXT)
      LEFT JOIN public.typefacturefournisseur AS tff
        ON CAST(tff.id AS TEXT) = CAST(f.typefacturefournisseur AS TEXT)
      LEFT JOIN public.compta_ecriture AS ce
        ON CAST(ce.idobjet AS TEXT) = CAST(f.id AS TEXT)
    ) AS fcpl
    LEFT JOIN (
      SELECT
        f.id,
        f.idfournisseur,
        f2.nom AS idfournisseurlib,
        f.idmodepaiement,
        m.val AS idmodepaiementlib,
        f.daty,
        f.designation,
        f.dateecheancepaiement,
        f.etat,
        CASE
          WHEN f.etat = CAST(1 AS DECIMAL)
          THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
          WHEN f.etat = CAST(0 AS DECIMAL)
          THEN CAST('ANNUL&Eacute;E' AS TEXT)
          WHEN f.etat = CAST(11 AS DECIMAL)
          THEN CAST('VIS&Eacute;E' AS TEXT)
          ELSE CAST(NULL AS TEXT)
        END AS etatlib,
        COALESCE(f.reference, reff.reference) AS reference,
        f.idbc,
        f.idmagasin,
        f.devise,
        CASE WHEN f.taux = CAST(0 AS DECIMAL) THEN CAST(1 AS DECIMAL) ELSE f.taux END AS taux,
        p.val AS idmagasinlib,
        f3.iddevise,
        CAST(f3.montanttva AS DECIMAL(30, 5)) AS montanttva,
        CAST((
          f3.montantttc - f3.montanttva
        ) AS DECIMAL(30, 5)) AS montantht,
        CAST(f3.montantttc AS DECIMAL(30, 5)) AS montantttc,
        CAST((
          f3.montantttc * f3.tauxdechange
        ) AS DECIMAL(30, 5)) AS montantttcar,
        CAST(COALESCE(mv.debit, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
        CAST((
          f3.montantttc - COALESCE(mv.debit, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS montantreste,
        CAST(COALESCE(f3.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS tauxdechange,
        prev.id AS idprevision,
        CASE
          WHEN f.estprevu = CAST(0 AS DECIMAL)
          THEN CAST('NON' AS TEXT)
          ELSE CAST('OUI' AS TEXT)
        END AS estprevulib,
        f.idobjet,
        f.idref,
        f.idtypefacture,
        tf.val AS typefacture,
        f.numero,
        f.typeachat,
        f.idfactureprincipale,
        s.libelle AS idservicelib,
        f.service,
        f.typefacturefournisseur,
        tff.desce AS typefacturefournisseurlib,
        ce.id AS idecriture,
        ta.val AS typeachatlib
      FROM public.facturefournisseur AS f
      LEFT JOIN public.typeachat AS ta
        ON CAST(ta.desce AS TEXT) = CAST(f.typeachat AS TEXT)
      LEFT JOIN public.fournisseur AS f2
        ON CAST(f2.id AS TEXT) = CAST(f.idfournisseur AS TEXT)
      LEFT JOIN public.modepaiement AS m
        ON CAST(m.id AS TEXT) = CAST(f.idmodepaiement AS TEXT)
      LEFT JOIN (
        SELECT
          p.id,
          p.val,
          p.desce,
          p.id AS idpoint,
          CAST('-' AS TEXT) AS idproduit,
          CAST(NULL AS TEXT) AS idtypemagasin,
          11 AS etat
        FROM public.point AS p
      ) AS p
        ON CAST(p.id AS TEXT) = CAST(f.idmagasin AS TEXT)
      JOIN (
        SELECT
          v.id,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            )
          ) AS DECIMAL(30, 2)) AS montanttotal,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) AS DECIMAL(30, 2)) AS montanttva,
          CAST((
            SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
            ) + SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              )
            )
          ) AS DECIMAL(30, 2)) AS montantttc,
          COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
          COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) AS tauxdechange
        FROM public.facturefournisseurfille AS vd
        LEFT JOIN public.facturefournisseur AS v
          ON CAST(v.id AS TEXT) = CAST(vd.idfacturefournisseur AS TEXT)
        GROUP BY
          v.id,
          vd.iddevise,
          vd.tauxdechange
      ) AS f3
        ON CAST(f.id AS TEXT) = CAST(f3.id AS TEXT)
      LEFT JOIN public.mouvementcaissegroupefacture AS mv
        ON CAST(f.id AS TEXT) = CAST(mv.idorigine AS TEXT)
      LEFT JOIN public.prevision AS prev
        ON CAST(prev.idfacture AS TEXT) = CAST(f.id AS TEXT)
      LEFT JOIN public.type_facture AS tf
        ON CAST(tf.id AS TEXT) = CAST(f.idtypefacture AS TEXT)
      LEFT JOIN public.service AS s
        ON CAST(f.service AS TEXT) = CAST(s.compte AS TEXT)
      LEFT JOIN public.referencefacture AS reff
        ON CAST(f.id AS TEXT) = CAST(reff.idfacture AS TEXT)
      LEFT JOIN public.typefacturefournisseur AS tff
        ON CAST(tff.id AS TEXT) = CAST(f.typefacturefournisseur AS TEXT)
      LEFT JOIN public.compta_ecriture AS ce
        ON CAST(ce.idobjet AS TEXT) = CAST(f.id AS TEXT)
    ) AS f2
      ON CAST(f2.idfactureprincipale AS TEXT) = CAST(fcpl.id AS TEXT)
    WHERE
      f2.id IS NULL
  ) AS facturefournisseurcpl_tous_fae
  WHERE
    facturefournisseurcpl_tous_fae.idtypefacture = 'TPF0002'
    AND facturefournisseurcpl_tous_fae.etat = 11
    AND facturefournisseurcpl_tous_fae.daty >= CAST('2026-06-01' AS DATE)
  GROUP BY
    DATE_TRUNC('DAY', facturefournisseurcpl_tous_fae.daty)
)
SELECT
  c.daty AS daty,
  CAST(COALESCE(f.montantttc, 0) AS DECIMAL(30, 5)) AS montantttc,
  CAST(COALESCE(f.montantpaye, 0) AS DECIMAL(30, 5)) AS montantpaye,
  CAST(COALESCE(f.montantreste, 0) AS DECIMAL(30, 5)) AS montantreste,
  CAST(COALESCE(f.nombre, 0) AS DECIMAL(10, 0)) AS nombre,
  CAST(SUM(COALESCE(f.montantreste, 0)) OVER (ORDER BY c.daty ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS DECIMAL(30, 5)) AS montantresteacejour
FROM calendrier AS c
LEFT JOIN facture_jour AS f
  ON c.daty = f.daty;

-- Niveau 1 - vue 32 / 129 : FF_FILLEBL_GRP
-- Dependances nouvelles : aucune.
CREATE VIEW public.ff_fillebl_grp (
    "produit", "idbc_fille", "qte"
) AS
SELECT
  _0.produit AS produit,
  _0.idbc_fille AS idbc_fille,
  SUM(_0.quantite) AS qte
FROM (
  SELECT
    blf.id AS id,
    blf.produit AS produit,
    blf.numbl AS numbl,
    blf.quantite AS quantite,
    blf.iddetailsfacturefournisseur AS iddetailsfacturefournisseur,
    blf.unite AS unite,
    blf.idbc_fille AS idbc_fille,
    blf.idfacturefournisseur AS idfacturefournisseur,
    blf.pu AS pu,
    blf.designation AS designation,
    blf.tauxdechange AS tauxdechange
  FROM public.as_bondelivraison_fille AS blf
  JOIN public.as_bondelivraison AS bl
    ON bl.id = blf.numbl
  WHERE
    bl.etat >= 11
) AS _0
GROUP BY
  _0.produit,
  _0.idbc_fille;

-- Niveau 1 - vue 33 / 129 : FICHE_POSTE_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.fiche_poste_lib (
    "id", "iddepartement", "idtypecontrat", "titre", "reference", "description", "missions", "exigenceposte", "salairemin", "salairemax", "etat", "daty", "lieutravail", "materieldocument", "outils", "conditiontravail", "modecontrole", "idniveauformation", "idpermis", "idfonction", "idbu", "autre", "idcategoriepaie", "idqualificationpaie", "iddepartementlib", "idtypecontratlib", "idfonctionlib", "idniveauformationlib", "idpermislib", "idbulib", "idcategoriepaielib", "idqualificationpaielib", "etatlib", "idfamilleprofessionellib", "idmetierlib", "idemploilib", "idcoderomelib", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.iddepartement AS iddepartement,
  base.idtypecontrat AS idtypecontrat,
  base.titre AS titre,
  base.reference AS reference,
  base.description AS description,
  base.missions AS missions,
  base.exigenceposte AS exigenceposte,
  base.salairemin AS salairemin,
  base.salairemax AS salairemax,
  base.etat AS etat,
  base.daty AS daty,
  base.lieutravail AS lieutravail,
  base.materieldocument AS materieldocument,
  base.outils AS outils,
  base.conditiontravail AS conditiontravail,
  base.modecontrole AS modecontrole,
  base.idniveauformation AS idniveauformation,
  base.idpermis AS idpermis,
  base.idfonction AS idfonction,
  base.idbu AS idbu,
  base.autre AS autre,
  base.idcategoriepaie AS idcategoriepaie,
  base.idqualificationpaie AS idqualificationpaie,
  base.iddepartementlib AS iddepartementlib,
  base.idtypecontratlib AS idtypecontratlib,
  base.idfonctionlib AS idfonctionlib,
  base.idniveauformationlib AS idniveauformationlib,
  base.idpermislib AS idpermislib,
