        ' | ',
        COALESCE(CAST(base.idqualificationpaie AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.iddepartementlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypecontratlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idfonctionlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idniveauformationlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idpermislib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idbulib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idcategoriepaielib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idqualificationpaielib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.etatlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idfamilleprofessionellib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idmetierlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idemploilib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idcoderomelib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    f.id AS id,
    f.iddepartement AS iddepartement,
    f.idtypecontrat AS idtypecontrat,
    f.titre AS titre,
    f.reference AS reference,
    f.description AS description,
    f.missions AS missions,
    f.exigenceposte AS exigenceposte,
    f.salairemin AS salairemin,
    f.salairemax AS salairemax,
    f.etat AS etat,
    f.daty AS daty,
    f.lieutravail AS lieutravail,
    f.materieldocument AS materieldocument,
    f.outils AS outils,
    f.conditiontravail AS conditiontravail,
    f.modecontrole AS modecontrole,
    f.idniveauformation AS idniveauformation,
    f.idpermis AS idpermis,
    f.idfonction AS idfonction,
    f.idbu AS idbu,
    f.autre AS autre,
    f.idcategoriepaie AS idcategoriepaie,
    f.idqualificationpaie AS idqualificationpaie,
    d.val AS iddepartementlib,
    t.val AS idtypecontratlib,
    pf.val AS idfonctionlib,
    nf.desce AS idniveauformationlib,
    p.desce AS idpermislib,
    bu.val AS idbulib,
    cp.val AS idcategoriepaielib,
    qp.val AS idqualificationpaielib,
    CASE
      WHEN f.etat = CAST('1' AS DECIMAL)
      THEN 'Cree'
      WHEN f.etat = CAST('11' AS DECIMAL)
      THEN 'Valide'
      WHEN f.etat = CAST('0' AS DECIMAL)
      THEN 'Annule'
      ELSE 'Inconnu'
    END AS etatlib,
    fp.val AS idfamilleprofessionellib,
    m.val AS idmetierlib,
    em.val AS idemploilib,
    cr.code AS idcoderomelib
  FROM public.fiche_poste AS f
  LEFT JOIN public.departement AS d
    ON d.id = f.iddepartement
  LEFT JOIN public.type_contrat AS t
    ON t.id = f.idtypecontrat
  LEFT JOIN public.paie_fonction AS pf
    ON pf.id = f.idfonction
  LEFT JOIN public.formation_diplome AS nf
    ON nf.id = f.idniveauformation
  LEFT JOIN public.permis AS p
    ON p.id = f.idpermis
  LEFT JOIN public.business_unite AS bu
    ON bu.id = f.idbu
  LEFT JOIN public.categorie_paie AS cp
    ON cp.id = f.idcategoriepaie
  LEFT JOIN public.qualification_paie AS qp
    ON qp.id = f.idqualificationpaie
  LEFT JOIN public.famille_professionnelle AS fp
    ON fp.id = f.idfamilleprofessionel
  LEFT JOIN public.metier AS m
    ON m.id = f.idmetier
  LEFT JOIN public.emploi AS em
    ON em.id = f.idemploi
  LEFT JOIN public.code_rome AS cr
    ON cr.id = f.idcoderome
) AS base;

