        ' | ',
        COALESCE(TO_CHAR(base.dateimport, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantheuresupp
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantheuresupp
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantheuresupp
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    h.id AS id,
    h.idressparfab AS idressparfab,
    h.heurenormale AS heurenormale,
    h.hs AS hs,
    h.mn AS mn,
    h.jf AS jf,
    h.hd AS hd,
    h.if AS if,
    h.etat AS etat,
    h.remarque AS remarque,
    p.id AS idpersonne,
    h.idfabrication AS idfabrication,
    h.daty AS datefabrication,
    CASE
      WHEN h.etat = 0
      THEN 'ANNULE'
      WHEN h.etat = 1
      THEN 'CREE'
      WHEN h.etat = 11
      THEN 'VISE'
      ELSE NULL
    END AS etatlib,
    NULLIF(CONCAT(pm.nom, ' ', pm.prenom), '') AS idpersonnelib,
    p.matricule AS matricule,
    h.tauxhoraire AS tauxhoraire,
    CAST(CAST(COALESCE(c.montant, 0) AS DECIMAL) / (
      CAST((
        40 * 52
      ) AS DECIMAL) / 12
    ) AS DECIMAL(30, 2)) AS tauxhoraireeffective,
    p.temporaire AS temporaire,
    h.montant AS montant,
    r.idqualification AS idqualification,
    COALESCE(h.montantjf, 0) AS montantjf,
    COALESCE(h.montanthd, 0) AS montanthd,
    COALESCE(h.montantif, 0) AS montantif,
    COALESCE(h.montantmn, 0) AS montantmn,
    COALESCE(h.montanthn, 0) AS montanthn,
    p.iddepartement AS iddepartement,
    d.val AS departementlib,
    h.poste AS poste,
    pf.val AS postelib,
    h.dateimport AS dateimport,
    h.montantheuresupp AS montantheuresupp
  FROM public.heuresupfabrication AS h
  LEFT JOIN (
    SELECT
      r.id,
      r.daty,
      r.idfabrication,
      r.idposte AS idpostedefaut,
      r.idressource,
      p.matricule,
      f.idof,
      r.etat,
      p.temporaire,
      p.idqualification,
      c.idcategorie,
      c.idposte,
      po.val AS idpostelib,
      p.idqualification AS idqualificationeffective,
      CAST((
        c.montant / CAST((
          40 * 52 / 12
        ) AS DECIMAL)
      ) AS DECIMAL(30, 2)) AS tauxhoraire,
      h.hs,
      h.mn,
      h.jf,
      h.hd,
      h.if,
      CASE
        WHEN r.etat = CAST(0 AS DECIMAL)
        THEN CAST('ANNULEE' AS TEXT)
        WHEN r.etat = CAST(1 AS DECIMAL)
        THEN CAST('CREE' AS TEXT)
        WHEN r.etat = CAST(11 AS DECIMAL)
        THEN CAST('VISEE' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib,
      p.matricule AS idressourcelib
    FROM public.ressourceparfabrication AS r
    LEFT JOIN public.paie_info_personnel AS p
      ON CAST(p.id AS TEXT) = CAST(r.idressource AS TEXT)
    LEFT JOIN public.categorie_qualification AS c
      ON CAST(c.idqualification AS TEXT) = CAST(r.idqualification AS TEXT)
      AND CAST(c.idcategorie AS TEXT) = CAST(p.idcategorie AS TEXT)
      AND (
        c.remarque IS NULL OR CAST(c.remarque AS TEXT) = CAST(r.idressource AS TEXT)
      )
      AND c.etat = CAST(1 AS DECIMAL)
    LEFT JOIN public.fabrication AS f
      ON CAST(f.id AS TEXT) = CAST(r.idfabrication AS TEXT)
    LEFT JOIN public.heuresupfabrication AS h
      ON CAST(h.idressparfab AS TEXT) = CAST(r.id AS TEXT)
    LEFT JOIN public.poste AS po
      ON CAST(po.id AS TEXT) = CAST(c.idposte AS TEXT)
  ) AS r
    ON r.id = h.idressparfab
  LEFT JOIN public.paie_info_personnel AS p
    ON p.id = r.idressource
  LEFT JOIN public.categorie_qualification AS c
    ON c.idqualification = r.idqualification
    AND c.idcategorie = r.idcategorie
    AND (
      c.remarque IS NULL OR c.remarque = r.idressource
    )
    AND c.etat = 1
  LEFT JOIN public.log_personnel AS pm
    ON pm.id = r.idressource
  LEFT JOIN public.fabrication AS fab
    ON fab.id = h.idfabrication
  LEFT JOIN public.departement AS d
    ON d.id = p.iddepartement
  LEFT JOIN public.paie_fonction AS pf
    ON pf.id = h.poste
) AS base;

-- Niveau 1 - vue 35 / 129 : HISTORIQUEAVECUSER
-- Dependances nouvelles : aucune.
CREATE VIEW public.historiqueavecuser (
    "idhistorique", "datehistorique", "heure", "objet", "action", "idutilisateur", "refobjet"
) AS
SELECT
  h.idhistorique AS idhistorique,
  h.datehistorique AS datehistorique,
  h.heure AS heure,
  NULLIF(
    SUBSTRING(h.objet FROM CASE
      WHEN POSITION('.' IN SUBSTRING(h.objet FROM -1)) = 0
      THEN 0
      ELSE POSITION('.' IN SUBSTRING(h.objet FROM -1)) + -1 - 1
    END + 1),
    ''
  ) AS objet,
  h.action AS action,
  u.loginuser AS idutilisateur,
  h.refobjet AS refobjet
FROM public.historique AS h
JOIN public.utilisateur AS u
  ON u.refuser = h.idutilisateur
ORDER BY
  h.datehistorique DESC,
  h.heure DESC;

-- Niveau 1 - vue 36 / 129 : HSMOIS_CPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.hsmois_cpl (
    "id", "idcategorie", "mois", "annee", "moislib", "daty", "iddepartement", "etat", "idcategorielib", "iddepartementlib", "etatlib"
) AS
SELECT
  hs.id AS id,
  hs.idcategorie AS idcategorie,
  hs.mois AS mois,
  hs.annee AS annee,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(hs.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
  hs.daty AS daty,
  hs.iddepartement AS iddepartement,
  hs.etat AS etat,
  c.val AS idcategorielib,
  d.val AS iddepartementlib,
  CASE WHEN hs.etat = 1 THEN 'CREE' WHEN hs.etat = 11 THEN 'VISEE' ELSE 'INCONNU' END AS etatlib
FROM public.hsmois AS hs
LEFT JOIN public.categorie_paie AS c
  ON hs.idcategorie = c.id
LEFT JOIN public.departement AS d
  ON hs.iddepartement = d.id;

-- Niveau 1 - vue 37 / 129 : INVENTAIRELIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.inventairelib (
    "id", "daty", "designation", "idmagasin", "idmagasinlib", "etat", "heure", "etatlib", "idcategorie", "idcategorielib", "motsclesss", "montantquantite", "remarque"
) AS
SELECT
  i.id AS id,
  i.daty AS daty,
  i.designation AS designation,
  i.idmagasin AS idmagasin,
  m.val AS idmagasinlib,
  i.etat AS etat,
  i.heure AS heure,
  CASE
    WHEN i.etat = 0
    THEN 'ANNUL&Eacute;E'
    WHEN i.etat = 1
    THEN 'CR&Eacute;&Eacute;E'
    WHEN i.etat = 11
    THEN 'VALID&Eacute;E'
    ELSE NULL
  END AS etatlib,
  i.idcategorie AS idcategorie,
  c.val AS idcategorielib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(i.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(i.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(i.designation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(i.idmagasin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(m.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    i.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    i.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    i.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(i.heure AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          CASE
            WHEN i.etat = 0
            THEN 'ANNUL&Eacute;E'
            WHEN i.etat = 1
            THEN 'CR&Eacute;&Eacute;E'
            WHEN i.etat = 11
            THEN 'VALID&Eacute;E'
            ELSE NULL
          END,
          NULL
        ),
        ' | ',
        COALESCE(CAST(i.idcategorie AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(c.val AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss,
  invfgm.montantquantite AS montantquantite,
  i.remarque AS remarque
FROM public.inventaire AS i
LEFT JOIN public.magasinpoint AS m
  ON m.id = i.idmagasin
LEFT JOIN public.categorieingredient AS c
  ON c.id = i.idcategorie
LEFT JOIN public.inventairefillegroupemere AS invfgm
  ON invfgm.idinventaire = i.id;

-- Niveau 1 - vue 38 / 129 : JOURS_PAR_MOIS
-- Dependances nouvelles : aucune.
CREATE VIEW public.jours_par_mois (
    "annee", "mois", "nb_jour", "conge_journalier"
) AS
SELECT
  EXTRACT(YEAR FROM g.dt) AS annee,
  EXTRACT(MONTH FROM g.dt) AS mois,
  EXTRACT(DAY FROM DATE_TRUNC('MONTH', g.dt) + INTERVAL '1 MONTH' - INTERVAL '1 DAY') AS nb_jour,
  ROUND(
    CAST(CAST(2.5 AS DECIMAL) / EXTRACT(DAY FROM DATE_TRUNC('MONTH', g.dt) + INTERVAL '1 MONTH' - INTERVAL '1 DAY') AS DECIMAL),
    6
  ) AS conge_journalier
FROM GENERATE_SERIES(CAST('2019-01-01' AS TIMESTAMP), LOCALTIMESTAMP(0), INTERVAL '1 MONTH') AS g(dt)
WHERE
  g.dt < LOCALTIMESTAMP(0);

-- Niveau 1 - vue 39 / 129 : LIAISONCODELIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.liaisoncodelib (
    "id", "idcodeimpot", "idcompte", "formule", "taxable"
) AS
SELECT
  liaisoncodeimpot.id AS id,
  liaisoncodeimpot.idcodeimpot AS idcodeimpot,
  liaisoncodeimpot.idcompte AS idcompte,
  liaisoncodeimpot.formule AS formule,
  CASE
    WHEN CAST(liaisoncodeimpot.taxable AS DECIMAL) = 1
    THEN 'Oui'
    WHEN CAST(liaisoncodeimpot.taxable AS DECIMAL) = 0
    THEN 'Non'
    ELSE NULL
  END AS taxable
FROM public.liaisoncodeimpot AS liaisoncodeimpot;

-- Niveau 1 - vue 40 / 129 : LISTECOLONNETABLE
-- Dependances nouvelles : aucune.
-- Metadonnees PostgreSQL de public ; statistiques Oracle sans equivalent en NULL type.
CREATE VIEW public.listecolonnetable (
    "owner", "table_name", "column_name", "data_type", "data_type_mod", "data_type_owner", "data_length", "data_precision", "data_scale", "nullable", "column_id", "default_length", "data_default", "num_distinct", "low_value", "high_value", "density", "num_nulls", "num_buckets", "last_analyzed", "sample_size", "character_set_name", "char_col_decl_length", "global_stats", "user_stats", "avg_col_len", "char_length", "char_used", "v80_fmt_image", "data_upgraded", "histogram"
) AS
SELECT
  CAST('a' AS TEXT) AS owner,
  CAST(UPPER(c.table_name) AS TEXT) AS table_name,
  CAST(UPPER(c.column_name) AS TEXT) AS column_name,
  CAST(UPPER(c.data_type) AS TEXT) AS data_type,
  CAST(NULL AS TEXT) AS data_type_mod,
  CAST(NULL AS TEXT) AS data_type_owner,
  CAST(c.character_octet_length AS DECIMAL) AS data_length,
  CAST(c.numeric_precision AS DECIMAL) AS data_precision,
  CAST(c.numeric_scale AS DECIMAL) AS data_scale,
  CASE WHEN c.is_nullable = 'YES' THEN CAST('Y' AS TEXT) ELSE CAST('N' AS TEXT) END AS nullable,
  CAST(c.ordinal_position AS DECIMAL) AS column_id,
  CAST(LENGTH(c.column_default) AS DECIMAL) AS default_length,
  CAST(c.column_default AS TEXT) AS data_default,
  CAST(NULL AS DECIMAL) AS num_distinct,
  CAST(NULL AS BYTEA) AS low_value,
  CAST(NULL AS BYTEA) AS high_value,
  CAST(NULL AS DECIMAL) AS density,
  CAST(NULL AS DECIMAL) AS num_nulls,
  CAST(NULL AS DECIMAL) AS num_buckets,
  CAST(NULL AS TIMESTAMP) AS last_analyzed,
  CAST(NULL AS DECIMAL) AS sample_size,
  CAST(NULL AS TEXT) AS character_set_name,
  CAST(c.character_maximum_length AS DECIMAL) AS char_col_decl_length,
  CAST(NULL AS TEXT) AS global_stats,
  CAST(NULL AS TEXT) AS user_stats,
  CAST(NULL AS DECIMAL) AS avg_col_len,
  CAST(c.character_maximum_length AS DECIMAL) AS char_length,
  CASE
    WHEN c.character_maximum_length IS NOT NULL
    THEN CAST('C' AS TEXT)
    ELSE CAST(NULL AS TEXT)
  END AS char_used,
  CAST(NULL AS TEXT) AS v80_fmt_image,
  CAST(NULL AS TEXT) AS data_upgraded,
  CAST(NULL AS TEXT) AS histogram
FROM information_schema.columns AS c
WHERE
  c.table_schema = 'public';

-- Niveau 1 - vue 41 / 129 : MAGASIN_SANSRESERVOIR
-- Dependances nouvelles : aucune.
CREATE VIEW public.magasin_sansreservoir (
    "id", "val", "desce", "idpoint", "idproduit", "idtypemagasin"
) AS
SELECT
  m.id AS id,
  m.val AS val,
  m.desce AS desce,
  m.idpoint AS idpoint,
  m.idproduit AS idproduit,
  m.idtypemagasin AS idtypemagasin
FROM (
  SELECT
    p.id,
    p.val,
    p.desce,
    p.id AS idpoint,
    CAST('-' AS TEXT) AS idproduit,
    CAST(NULL AS TEXT) AS idtypemagasin,
    11 AS etat
  FROM public.point AS p
) AS m
WHERE
  m.idtypemagasin <> 'TYPMG000001';

-- Niveau 1 - vue 42 / 129 : MOTRAVAUXLIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.motravauxlib (
    "id", "idpersonnel", "idtravaux", "dureeestimatif", "tauxhoraire", "dureeestimatiflib", "montant", "idpersonnellib"
) AS
SELECT
  mo.id AS id,
  mo.idpersonnel AS idpersonnel,
  mo.idtravaux AS idtravaux,
  mo.dureeestimatif AS dureeestimatif,
  mo.tauxhoraire AS tauxhoraire,
  NULLIF(
    CONCAT(
      LPAD(
        CAST(FLOOR(CAST(CAST(mo.dureeestimatif AS DECIMAL) AS DECIMAL) / 3600) AS TEXT),
        2,
        '0'
      ),
      ':',
      LPAD(
        CAST(FLOOR(
          CAST(CAST(CAST(mo.dureeestimatif AS DECIMAL) AS DECIMAL) % CAST(3600 AS DECIMAL) AS DECIMAL) / 60
        ) AS TEXT),
        2,
        '0'
      ),
      ':',
      LPAD(
        CAST(CAST(CAST(mo.dureeestimatif AS DECIMAL) AS DECIMAL) % CAST(60 AS DECIMAL) AS TEXT),
        2,
        '0'
      )
    ),
    ''
  ) AS dureeestimatiflib,
  (
    CAST((
      CAST(mo.dureeestimatif AS DECIMAL) / 60
    ) AS DECIMAL) / 60
  ) * mo.tauxhoraire AS montant,
  p.nom AS idpersonnellib
FROM public.motravaux AS mo
LEFT JOIN public.personnel AS p
  ON p.id = mo.idpersonnel;

-- Niveau 1 - vue 43 / 129 : MOUVEMENTCAISSEAVECHEURE
-- Dependances nouvelles : aucune.
CREATE VIEW public.mouvementcaisseavecheure (
    "id", "designation", "idcaisse", "idventedetail", "idvirement", "daty", "etat", "idop", "idorigine", "iddevise", "idtiers", "compte", "idprevision", "idtraite", "etatversement", "idmodepaiement", "idmvtcaissemere", "reference", "updated_at", "datycomptabilisation", "acquereur", "idtypepaiement", "debit", "credit", "taux", "heure", "idreport"
) AS
SELECT
  m.id AS id,
  m.designation AS designation,
  m.idcaisse AS idcaisse,
  m.idventedetail AS idventedetail,
  m.idvirement AS idvirement,
  CASE
    WHEN NOT m.heure IS NULL AND m.heure <> '00:00:00'
    THEN (
      (
        (
          m.daty + (
            (
              CAST(CAST(NULLIF(SUBSTRING(m.heure FROM 1 FOR 2), '') AS DECIMAL) AS DECIMAL) / 24
            )
          ) * INTERVAL '1 DAY'
        ) + (
          (
            CAST(CAST(NULLIF(SUBSTRING(m.heure FROM 4 FOR 2), '') AS DECIMAL) AS DECIMAL) / 1440
          )
        ) * INTERVAL '1 DAY'
      ) + (
        (
          CAST(CAST(NULLIF(SUBSTRING(m.heure FROM 7 FOR 2), '') AS DECIMAL) AS DECIMAL) / 86400
        )
      ) * INTERVAL '1 DAY'
    )
    ELSE m.daty
  END AS daty,
  m.etat AS etat,
  m.idop AS idop,
  m.idorigine AS idorigine,
  m.iddevise AS iddevise,
  m.idtiers AS idtiers,
  m.compte AS compte,
  m.idprevision AS idprevision,
  m.idtraite AS idtraite,
  m.etatversement AS etatversement,
  m.idmodepaiement AS idmodepaiement,
  m.idmvtcaissemere AS idmvtcaissemere,
  m.reference AS reference,
  m.updated_at AS updated_at,
  m.datycomptabilisation AS datycomptabilisation,
  m.acquereur AS acquereur,
  m.idtypepaiement AS idtypepaiement,
  m.debit AS debit,
  m.credit AS credit,
  m.taux AS taux,
  m.heure AS heure,
  m.idreport AS idreport
FROM public.mouvementcaisse AS m;

-- Niveau 1 - vue 44 / 129 : MOUVEMENTCAISSECPL_VALIDER
-- Dependances nouvelles : aucune.
CREATE VIEW public.mouvementcaissecpl_valider (
    "id", "designation", "idcaisse", "idcaisselib", "idventedetail", "idvirement", "debit", "credit", "daty", "etat", "etatlib", "idvente", "idorigine", "idtiers", "tiers", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.designation AS designation,
  sq.idcaisse AS idcaisse,
  sq.idcaisselib AS idcaisselib,
  sq.idventedetail AS idventedetail,
  sq.idvirement AS idvirement,
  sq.debit AS debit,
  sq.credit AS credit,
  sq.daty AS daty,
  sq.etat AS etat,
  sq.etatlib AS etatlib,
  sq.idvente AS idvente,
  sq.idorigine AS idorigine,
  sq.idtiers AS idtiers,
  sq.tiers AS tiers,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.designation AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idcaisse AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idcaisselib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idventedetail AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idvirement AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.debit
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.debit
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.debit
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.credit
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.credit
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.credit
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.etatlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idvente AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idorigine AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idtiers AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.tiers AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    m.id AS id,
    m.designation AS designation,
    m.idcaisse AS idcaisse,
    m.idcaisselib AS idcaisselib,
    m.idventedetail AS idventedetail,
    m.idvirement AS idvirement,
    m.debit AS debit,
    m.credit AS credit,
    m.daty AS daty,
    m.etat AS etat,
    m.etatlib AS etatlib,
    m.idvente AS idvente,
    m.idorigine AS idorigine,
    m.idtiers AS idtiers,
    m.tiers AS tiers
  FROM (
    SELECT
      m.id,
      m.designation,
      m.idcaisse,
      c.val AS idcaisselib,
      m.idventedetail,
      m.idvirement,
      m.debit,
      m.credit,
      CAST(CASE
        WHEN m.credit > CAST(0 AS DECIMAL)
        THEN COALESCE(m.credit, CAST(0 AS DECIMAL)) - COALESCE(l.montant, CAST(0 AS DECIMAL))
        ELSE CAST(0 AS DECIMAL)
      END AS DECIMAL(36, 5)) AS soldecredit,
      CAST(CASE
        WHEN m.debit > CAST(0 AS DECIMAL)
        THEN COALESCE(m.debit, CAST(0 AS DECIMAL)) - COALESCE(l.montant, CAST(0 AS DECIMAL))
        ELSE CAST(0 AS DECIMAL)
      END AS DECIMAL(36, 5)) AS soldedebit,
      m.daty,
      m.etat,
      CASE
        WHEN m.etat = CAST(0 AS DECIMAL)
        THEN CAST('ANNULEE' AS TEXT)
        WHEN m.etat = CAST(1 AS DECIMAL)
        THEN CAST('CREEE' AS TEXT)
        WHEN m.etat = CAST(11 AS DECIMAL)
        THEN CAST('VALIDEE' AS TEXT)
        WHEN m.etat = CAST(8 AS DECIMAL)
        THEN CAST('A COMPTABILISER' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib,
      vd.idvente,
      m.idorigine,
      m.idtiers,
      t.nom AS tiers,
      m.idprevision,
      m.idop,
      m.taux,
      m.compte,
      m.iddevise,
      m.idtraite,
      mp.val AS idmodepaiementlib,
      m.idmvtcaissemere,
      m.reference,
      m.datycomptabilisation,
      m.updated_at,
      m.heure,
      m.idreport,
      point.id AS idpoint,
      point.val AS idpointlib,
      NULLIF(
        CONCAT(
          (
            NULLIF(
              CONCAT(
                (
                  NULLIF(
                    CONCAT(
                      (
                        NULLIF(
                          CONCAT(
                            (
                              NULLIF(
                                CONCAT(
                                  (
                                    NULLIF(
                                      CONCAT(
                                        (
                                          NULLIF(
                                            CONCAT(
                                              (
                                                NULLIF(
                                                  CONCAT(
                                                    (
                                                      NULLIF(
                                                        CONCAT((
                                                          NULLIF(CONCAT(CAST(m.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                        ), m.daty),
                                                        ''
                                                      )
                                                    ),
                                                    CAST(NULL AS TEXT)
                                                  ),
                                                  ''
                                                )
                                              ),
                                              CAST(m.designation AS TEXT)
                                            ),
                                            ''
                                          )
                                        ),
                                        CAST(NULL AS TEXT)
                                      ),
                                      ''
                                    )
                                  ),
                                  CAST(t.nom AS TEXT)
                                ),
                                ''
                              )
                            ),
                            CAST(NULL AS TEXT)
                          ),
                          ''
                        )
                      ),
                      CAST(m.idcaisse AS TEXT)
                    ),
                    ''
                  )
                ),
                CAST(NULL AS TEXT)
              ),
              ''
            )
          ),
          CAST(c.val AS TEXT)
        ),
        ''
      ) AS motsclesss
    FROM public.mouvementcaisse AS m
    LEFT JOIN public.caisse AS c
      ON CAST(c.id AS TEXT) = CAST(m.idcaisse AS TEXT)
    LEFT JOIN public.vente_details AS vd
      ON CAST(vd.id AS TEXT) = CAST(m.idventedetail AS TEXT)
    LEFT JOIN public.tiers AS t
      ON CAST(t.id AS TEXT) = CAST(m.idtiers AS TEXT)
    LEFT JOIN public.liaisonpaiementmvtcaissegrp AS l
      ON CAST(l.idmvtcaisse AS TEXT) = CAST(m.id AS TEXT)
    LEFT JOIN public.modepaiement AS mp
      ON CAST(m.idmodepaiement AS TEXT) = CAST(mp.id AS TEXT)
    LEFT JOIN public.point AS point
      ON CAST(point.id AS TEXT) = CAST(c.idpoint AS TEXT)
  ) AS m
  WHERE
    m.etat = 11
) AS sq;

-- Niveau 1 - vue 45 / 129 : MVTINTRACAISSE_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.mvtintracaisse_lib (
    "id", "daty", "caissedepartlib", "caissearriveelib", "caissedepart", "caissearrivee", "montant", "modepaiement", "remarque", "etat", "designation"
) AS
SELECT
  mv.id AS id,
  mv.daty AS daty,
  mv.caissedepart AS caissedepartlib,
  mv.caissearrivee AS caissearriveelib,
  ca.val AS caissedepart,
  ca1.val AS caissearrivee,
  mv.montant AS montant,
  mp.val AS modepaiement,
  mv.remarque AS remarque,
  mv.etat AS etat,
  mv.designation AS designation
FROM public.mvtintracaisse AS mv
LEFT JOIN public.caisse AS ca
  ON ca.id = mv.caissedepart
LEFT JOIN public.caisse AS ca1
  ON ca1.id = mv.caissearrivee
LEFT JOIN public.modepaiement AS mp
  ON mp.id = mv.modepaiement;

-- Niveau 1 - vue 46 / 129 : MVTSTOCKFILLELIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.mvtstockfillelib (
    "id", "idmvtstock", "idproduit", "idproduitlib", "entree", "sortie", "idventedetail", "idventedetaillib", "idtransfertdetail", "idtransfertdetaillib", "daty", "idmagasin", "idmagasinlib", "pu", "montant", "libelle", "mvtsrc", "libelleexacte", "datesql", "idobjet", "idtypemvstock", "etat", "etatlib", "couleurlib", "taille", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.idmvtstock AS idmvtstock,
  base.idproduit AS idproduit,
  base.idproduitlib AS idproduitlib,
  base.entree AS entree,
  base.sortie AS sortie,
  base.idventedetail AS idventedetail,
  base.idventedetaillib AS idventedetaillib,
  base.idtransfertdetail AS idtransfertdetail,
  base.idtransfertdetaillib AS idtransfertdetaillib,
  base.daty AS daty,
  base.idmagasin AS idmagasin,
  base.idmagasinlib AS idmagasinlib,
  base.pu AS pu,
  base.montant AS montant,
  base.libelle AS libelle,
  base.mvtsrc AS mvtsrc,
  base.libelleexacte AS libelleexacte,
  base.datesql AS datesql,
  base.idobjet AS idobjet,
  base.idtypemvstock AS idtypemvstock,
  base.etat AS etat,
  base.etatlib AS etatlib,
  base.couleurlib AS couleurlib,
  base.taille AS taille,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idmvtstock AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idproduit AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idproduitlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.entree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.entree
                  ) AS TEXT)))
                  ELSE CAST((
                    base.entree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.sortie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.sortie
                  ) AS TEXT)))
                  ELSE CAST((
                    base.sortie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.idventedetail AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idventedetaillib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtransfertdetail AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtransfertdetaillib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(base.idmagasin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idmagasinlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.pu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.pu
                  ) AS TEXT)))
                  ELSE CAST((
                    base.pu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montant
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montant
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montant
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.libelle AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.mvtsrc AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.libelleexacte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.datesql, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(base.idobjet AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypemvstock AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    base.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.etatlib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    m.id AS id,
    m.idmvtstock AS idmvtstock,
    m.idproduit AS idproduit,
    p.libelle AS idproduitlib,
    m.entree AS entree,
    m.sortie AS sortie,
    m.idventedetail AS idventedetail,
    CAST(NULL AS VARCHAR(255)) AS idventedetaillib,
    m.idtransfertdetail AS idtransfertdetail,
    CAST(NULL AS VARCHAR(255)) AS idtransfertdetaillib,
    m2.daty AS daty,
    m2.idmagasin AS idmagasin,
    m3.val AS idmagasinlib,
    m.pu AS pu,
    CAST(COALESCE(m.pu, 0) * COALESCE(m.entree, 0) + COALESCE(m.pu, 0) * COALESCE(m.sortie, 0) AS DECIMAL(20, 5)) AS montant,
    p.libelle AS libelle,
    m.mvtsrc AS mvtsrc,
    p.libelle AS libelleexacte,
    m2.daty AS datesql,
    m2.idobjet AS idobjet,
    m2.idtypemvstock AS idtypemvstock,
    m2.etat AS etat,
    CASE
      WHEN m2.etat = 1
      THEN 'CR&Eacute;&Eacute;E'
      WHEN m2.etat = 11
      THEN 'VIS&Eacute;E'
      WHEN m2.etat = 0
      THEN 'ANNUL&Eacute;E'
      ELSE NULL
    END AS etatlib,
    coul.val AS couleurlib,
    p.taille AS taille
  FROM public.mvtstockfille AS m
  LEFT JOIN public.as_ingredients AS p
    ON p.id = m.idproduit
  LEFT JOIN public.couleur AS coul
    ON p.couleur = coul.id
  LEFT JOIN public.mvtstock AS m2
    ON m2.id = m.idmvtstock
  LEFT JOIN public.magasin2 AS m3
    ON m3.id = m2.idmagasin
) AS base;

-- Niveau 1 - vue 47 / 129 : MVTSTOCKLIB
