CREATE VIEW public.mvtstocklib (
    "id", "designation", "idmagasin", "idobjet", "idmagasinlib", "idvente", "idventelib", "idtransfert", "idtransfertlib", "idtypemvstock", "idtypemvstocklib", "daty", "etat", "heure", "etatlib", "idreservation", "montantentree", "montantsortie", "idcategoriestock", "idcategoriestocklib", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.designation AS designation,
  base.idmagasin AS idmagasin,
  base.idobjet AS idobjet,
  base.idmagasinlib AS idmagasinlib,
  base.idvente AS idvente,
  base.idventelib AS idventelib,
  base.idtransfert AS idtransfert,
  base.idtransfertlib AS idtransfertlib,
  base.idtypemvstock AS idtypemvstock,
  base.idtypemvstocklib AS idtypemvstocklib,
  base.daty AS daty,
  base.etat AS etat,
  base.heure AS heure,
  base.etatlib AS etatlib,
  base.idreservation AS idreservation,
  CAST(base.montantentree AS DECIMAL(30, 2)) AS montantentree,
  CAST(base.montantsortie AS DECIMAL(30, 2)) AS montantsortie,
  base.idcategoriestock AS idcategoriestock,
  base.idcategoriestocklib AS idcategoriestocklib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.designation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idmagasin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idobjet AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idmagasinlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idvente AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idventelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtransfert AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtransfertlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypemvstock AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypemvstocklib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    base.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.heure AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.etatlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idreservation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantentree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantentree
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantentree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantsortie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantsortie
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantsortie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.idcategoriestock AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idcategoriestocklib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    m.id AS id,
    m.designation AS designation,
    m.idmagasin AS idmagasin,
    m.idobjet AS idobjet,
    m2.val AS idmagasinlib,
    m.idvente AS idvente,
    v.designation AS idventelib,
    m.idtransfert AS idtransfert,
    CAST(NULL AS VARCHAR(255)) AS idtransfertlib,
    m.idtypemvstock AS idtypemvstock,
    t.val AS idtypemvstocklib,
    m.daty AS daty,
    m.etat AS etat,
    m.heure AS heure,
    CASE
      WHEN m.etat = 0
      THEN 'ANNUL&Eacute;E'
      WHEN m.etat = 1
      THEN 'CR&Eacute;&Eacute;E'
      WHEN m.etat = 11
      THEN 'VALID&Eacute;E'
      ELSE NULL
    END AS etatlib,
    v.idreservation AS idreservation,
    CAST(COALESCE(gm.montantentree, 0) AS DECIMAL(30, 5)) AS montantentree,
    CAST(COALESCE(gm.montantsortie, 0) AS DECIMAL(30, 5)) AS montantsortie,
    m.idcategoriestock AS idcategoriestock,
    cs.val AS idcategoriestocklib
  FROM public.mvtstock AS m
  LEFT JOIN public.typemvtstock AS t
    ON t.id = m.idtypemvstock
  LEFT JOIN public.vente AS v
    ON v.id = m.idvente
  LEFT JOIN public.magasin2 AS m2
    ON m2.id = m.idmagasin
  LEFT JOIN public.mvtstockfillegroupemere AS gm
    ON gm.idmvtstock = m.id
  LEFT JOIN public.categoriestock AS cs
    ON cs.id = m.idcategoriestock
) AS base;

-- Niveau 1 - vue 48 / 129 : NOTIFICATIONLIBCPLT
-- Dependances nouvelles : aucune.
CREATE VIEW public.notificationlibcplt (
    "id", "receiver", "receiverlib", "message", "daty", "heure", "etat", "ref", "reflib", "etatlib", "lien", "ecartdate"
) AS
SELECT
  n.id AS id,
  n.receiver AS receiver,
  u.nomuser AS receiverlib,
  n.message AS message,
  n.daty AS daty,
  n.heure AS heure,
  n.etat AS etat,
  n.ref AS ref,
  CAST(NULL AS TEXT) AS reflib,
  CASE WHEN n.etat = 11 THEN 'LU' WHEN n.etat = 1 THEN 'NON LU' ELSE NULL END AS etatlib,
  n.lien AS lien,
  CASE
    WHEN (
      (
        (
          EXTRACT(EPOCH FROM (
            LOCALTIMESTAMP(0) - (
              CAST(TO_TIMESTAMP(
                CAST(NULLIF(CONCAT(TO_CHAR(n.daty, 'YYYY-MM-DD'), ' ', n.heure), '') AS TEXT),
                'YYYY-MM-DD HH24:MI:SS'
              ) AS TIMESTAMP)
            )
          )) / 86400.0
        )
      ) * 24 * 60 * 60
    ) < 60
    THEN 'il y a moins d''une minute'
    WHEN (
      (
        (
          EXTRACT(EPOCH FROM (
            LOCALTIMESTAMP(0) - (
              CAST(TO_TIMESTAMP(
                CAST(NULLIF(CONCAT(TO_CHAR(n.daty, 'YYYY-MM-DD'), ' ', n.heure), '') AS TEXT),
                'YYYY-MM-DD HH24:MI:SS'
              ) AS TIMESTAMP)
            )
          )) / 86400.0
        )
      ) * 24 * 60 * 60
    ) < 3600
    THEN NULLIF(
      CONCAT(
        'il y a ',
        FLOOR(
          (
            (
              (
                EXTRACT(EPOCH FROM (
                  LOCALTIMESTAMP(0) - (
                    CAST(TO_TIMESTAMP(
                      CAST(NULLIF(CONCAT(TO_CHAR(n.daty, 'YYYY-MM-DD'), ' ', n.heure), '') AS TEXT),
                      'YYYY-MM-DD HH24:MI:SS'
                    ) AS TIMESTAMP)
                  )
                )) / 86400.0
              )
            ) * 24 * 60
          )
        ),
        ' mn'
      ),
      ''
    )
    WHEN (
      (
        (
          EXTRACT(EPOCH FROM (
            LOCALTIMESTAMP(0) - (
              CAST(TO_TIMESTAMP(
                CAST(NULLIF(CONCAT(TO_CHAR(n.daty, 'YYYY-MM-DD'), ' ', n.heure), '') AS TEXT),
                'YYYY-MM-DD HH24:MI:SS'
              ) AS TIMESTAMP)
            )
          )) / 86400.0
        )
      ) * 24 * 60 * 60
    ) < 86400
    THEN NULLIF(
      CONCAT(
        'il y a ',
        FLOOR(
          (
            (
              (
                EXTRACT(EPOCH FROM (
                  LOCALTIMESTAMP(0) - (
                    CAST(TO_TIMESTAMP(
                      CAST(NULLIF(CONCAT(TO_CHAR(n.daty, 'YYYY-MM-DD'), ' ', n.heure), '') AS TEXT),
                      'YYYY-MM-DD HH24:MI:SS'
                    ) AS TIMESTAMP)
                  )
                )) / 86400.0
              )
            ) * 24
          )
        ),
        ' h'
      ),
      ''
    )
    ELSE NULLIF(
      CONCAT(
        'il y a ',
        FLOOR(
          (
            (
              EXTRACT(EPOCH FROM (
                LOCALTIMESTAMP(0) - (
                  CAST(TO_TIMESTAMP(
                    CAST(NULLIF(CONCAT(TO_CHAR(n.daty, 'YYYY-MM-DD'), ' ', n.heure), '') AS TEXT),
                    'YYYY-MM-DD HH24:MI:SS'
                  ) AS TIMESTAMP)
                )
              )) / 86400.0
            )
          )
        ),
        ' jrs'
      ),
      ''
    )
  END AS ecartdate
FROM public.notification2 AS n
LEFT JOIN public.utilisateur AS u
  ON u.refuser = n.receiver
ORDER BY
  daty DESC;

-- Niveau 1 - vue 49 / 129 : OFFILLELIBQTERESTE
-- Dependances nouvelles : aucune.
CREATE VIEW public.offillelibqtereste (
    "id", "idingredients", "libelle", "remarque", "idmere", "datybesoin", "qte", "idunite", "qtefabrique", "qtereste", "libellemere", "daty", "idbcfille"
) AS
SELECT
  ofll.id AS id,
  ofll.idingredients AS idingredients,
  NULLIF(CONCAT(ai.libelle, ' ', ofll.libelle), '') AS libelle,
  ai.libelle AS remarque,
  ofll.idmere AS idmere,
  ofll.datybesoin AS datybesoin,
  (
    ofll.qte - COALESCE(fmf.qte, 0)
  ) AS qte,
  COALESCE(au.id, 'UNT00005') AS idunite,
  fmf.qte AS qtefabrique, /* 	au.id as lele, */
  (
    ofll.qte - fmf.qte
  ) AS qtereste,
  ofa.libelle AS libellemere,
  fmf.daty AS daty,
  ofll.idbcfille AS idbcfille
FROM public.offille AS ofll
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = ofll.idingredients
LEFT JOIN public.as_unite AS au
  ON au.id = ofll.idunite
LEFT JOIN (
  SELECT
    ff.idingredients,
    ff.idingredientslib,
    SUM(ff.qte) AS qte,
    ff.idunite,
    f.idoffille,
    f.idof,
    f.libelle,
    f.daty,
    ff.idbcfille
  FROM (
    SELECT
      f.id,
      f.idingredients,
      f.libelle,
      f.remarque,
      f.idmere,
      f.datybesoin,
      f.qte,
      f.idunite,
      f.pu,
      ai.libelle AS idingredientslib,
      NULLIF(
        CONCAT(
          (
            NULLIF(CONCAT(CAST(p.nom AS TEXT), CAST(' - ' AS TEXT)), '')
          ),
          CAST(p.telephone AS TEXT)
        ),
        ''
      ) AS operateur,
      au.val AS idunitelib,
      f.idbcfille,
      f.idmachine,
      m.descriptionobjet AS idmachinelib,
      ai.ispetri,
      f2.idoffille
    FROM public.fabricationfille AS f
    JOIN public.fabrication AS f2
      ON CAST(f2.id AS TEXT) = CAST(f.idmere AS TEXT)
    LEFT JOIN public.as_ingredients AS ai
      ON CAST(ai.id AS TEXT) = CAST(f.idingredients AS TEXT)
    LEFT JOIN public.personnel AS p
      ON CAST(p.id AS TEXT) = CAST(f.operateur AS TEXT)
    LEFT JOIN public.as_unite AS au
      ON CAST(au.id AS TEXT) = CAST(f.idunite AS TEXT)
    LEFT JOIN (
      SELECT
        asm.id,
        asm.idingredient,
        asm.identite,
        asm.referenceobjet,
        asm.marqueobjet,
        asm.modeleobjet,
        asm.numeroserieobjet,
        asm.descriptionobjet,
        asm.qualiteobjet,
        asm.etatobjet,
        asm.localisationobjet,
        asm.puissanceobjet,
        asm.observationobjet,
        asm.typerattachement,
        asm.estengin,
        asm.libelle,
        asm.dateaquisition,
        asm.ingredientlib,
        asm.identitelib,
        asm.qualiteobjetlib,
        asm.etatobjetlib,
        asm.localisationobjetlib,
        asm.estenginlib,
        asm.idligne,
        asm.idlignelib,
        asm.pu,
        im.id AS idinspection
      FROM (
        SELECT
          am.id,
          am.idingredient,
          am.identite,
          am.referenceobjet,
          am.marqueobjet,
          am.modeleobjet,
          am.numeroserieobjet,
          am.descriptionobjet,
          am.qualiteobjet,
          am.etatobjet,
          am.localisationobjet,
          am.puissanceobjet,
          am.observationobjet,
          am.typerattachement,
          am.estengin,
          am.libelle,
          am.dateaquisition,
          ai.libelle AS ingredientlib,
          am.identite AS identitelib,
          qo.val AS qualiteobjetlib,
          eo.val AS etatobjetlib,
          ld.val AS localisationobjetlib,
          CASE
            WHEN am.estengin = CAST(1 AS DECIMAL)
            THEN CAST('Oui' AS TEXT)
            ELSE CAST('Non' AS TEXT)
          END AS estenginlib,
          l.id AS idligne,
          l.val AS idlignelib,
          am.pu,
          NULLIF(
            CONCAT(
              (
                NULLIF(
                  CONCAT(
                    (
                      NULLIF(
                        CONCAT(
                          (
                            NULLIF(
                              CONCAT(
                                (
                                  NULLIF(
                                    CONCAT(
                                      (
                                        NULLIF(
                                          CONCAT(
                                            (
                                              NULLIF(
                                                CONCAT(
                                                  (
                                                    NULLIF(
                                                      CONCAT(
                                                        (
                                                          NULLIF(
                                                            CONCAT(
                                                              (
                                                                NULLIF(
                                                                  CONCAT(
                                                                    (
                                                                      NULLIF(
                                                                        CONCAT(
                                                                          (
                                                                            NULLIF(
                                                                              CONCAT(
                                                                                (
                                                                                  NULLIF(
                                                                                    CONCAT(
                                                                                      (
                                                                                        NULLIF(
                                                                                          CONCAT(CAST(COALESCE(am.id, CAST(NULL AS VARCHAR)) AS TEXT), CAST(' | ' AS TEXT)),
                                                                                          ''
                                                                                        )
                                                                                      ),
                                                                                      CAST(COALESCE(ai.libelle, CAST(NULL AS VARCHAR)) AS TEXT)
                                                                                    ),
                                                                                    ''
                                                                                  )
                                                                                ),
                                                                                CAST(' | ' AS TEXT)
                                                                              ),
                                                                              ''
                                                                            )
                                                                          ),
                                                                          CAST(COALESCE(am.identite, CAST(NULL AS VARCHAR)) AS TEXT)
                                                                        ),
                                                                        ''
                                                                      )
                                                                    ),
                                                                    CAST(' | ' AS TEXT)
                                                                  ),
                                                                  ''
                                                                )
                                                              ),
                                                              CAST(COALESCE(qo.val, CAST(NULL AS VARCHAR)) AS TEXT)
                                                            ),
                                                            ''
                                                          )
                                                        ),
                                                        CAST(' | ' AS TEXT)
                                                      ),
                                                      ''
                                                    )
                                                  ),
                                                  CAST(COALESCE(eo.val, CAST(NULL AS VARCHAR)) AS TEXT)
                                                ),
                                                ''
                                              )
                                            ),
                                            CAST(' | ' AS TEXT)
                                          ),
                                          ''
                                        )
                                      ),
                                      CAST(COALESCE(ld.val, CAST(NULL AS VARCHAR)) AS TEXT)
                                    ),
                                    ''
                                  )
                                ),
                                CAST(' | ' AS TEXT)
                              ),
                              ''
                            )
                          ),
                          CAST(COALESCE(l.val, CAST(NULL AS VARCHAR)) AS TEXT)
                        ),
                        ''
                      )
                    ),
                    CAST(' | ' AS TEXT)
                  ),
                  ''
                )
              ),
              CAST(COALESCE(am.libelle, CAST(NULL AS VARCHAR)) AS TEXT)
            ),
            ''
          ) AS motsclesss,
          ai.parfums AS iddepartement,
          de.val AS iddepartementlib
        FROM public.as_ingredients AS ai
        JOIN public.as_ingredient_maintenance AS am
          ON CAST(ai.id AS TEXT) = CAST(am.idingredient AS TEXT)
        LEFT JOIN public.qualitesobjetmaintenance AS qo
          ON CAST(am.qualiteobjet AS TEXT) = CAST(qo.id AS TEXT)
        LEFT JOIN public.etatobjetmaintenance AS eo
          ON CAST(am.etatobjet AS TEXT) = CAST(eo.id AS TEXT)
        LEFT JOIN public.log_departement AS ld
          ON CAST(am.localisationobjet AS TEXT) = CAST(ld.id AS TEXT)
        LEFT JOIN public.ligne AS l
          ON CAST(l.id AS TEXT) = CAST(am.idligne AS TEXT)
        LEFT JOIN public.departement AS de
          ON CAST(de.id AS TEXT) = CAST(ai.parfums AS TEXT)
      ) AS asm
      LEFT JOIN public.inspectionmere AS im
        ON CAST(im.idelement AS TEXT) = CAST(asm.id AS TEXT)
      WHERE
        CAST(asm.identite AS TEXT) = CAST('ENT000001' AS TEXT)
    ) AS m
      ON CAST(m.id AS TEXT) = CAST(f.idmachine AS TEXT)
  ) AS ff
  JOIN public.fabrication AS f
    ON CAST(f.id AS TEXT) = CAST(ff.idmere AS TEXT)
  WHERE
    f.etat = CAST(11 AS DECIMAL)
  GROUP BY
    ff.idingredients,
    ff.idingredientslib,
    ff.idunite,
    f.idoffille,
    f.libelle,
    f.daty,
    ff.idbcfille,
    f.idof
) AS fmf
  ON fmf.idof = ofll.idmere AND fmf.idingredients = ofll.idingredients
LEFT JOIN public.ofab AS ofa
  ON ofa.id = ofll.idmere;

-- Niveau 1 - vue 50 / 129 : OFFILLELIBSTOCK
