CREATE VIEW public.offillelibstock (
    "id", "idingredients", "libelle", "remarque", "idmere", "datybesoin", "qte", "idunite", "qtefabrique", "qtereste", "libelleexacte", "pv", "montantentree", "montantsortie", "pourc", "motsclesss", "daty"
) AS
SELECT
  sq.id AS id,
  sq.idingredients AS idingredients,
  sq.libelle AS libelle,
  sq.remarque AS remarque,
  sq.idmere AS idmere,
  sq.datybesoin AS datybesoin,
  sq.qte AS qte,
  sq.idunite AS idunite,
  sq.qtefabrique AS qtefabrique,
  sq.qtereste AS qtereste,
  sq.libelleexacte AS libelleexacte,
  sq.pv AS pv,
  sq.montantentree AS montantentree,
  sq.montantsortie AS montantsortie,
  sq.pourc AS pourc,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idingredients AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.libelle AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.remarque AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idmere AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.datybesoin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.qte
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qte
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qte
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.idunite AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.qtefabrique
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qtefabrique
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qtefabrique
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.qtereste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qtereste
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qtereste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.libelleexacte AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.pv
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.pv
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.pv
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantentree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantentree
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantentree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantsortie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantsortie
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantsortie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.pourc
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.pourc
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.pourc
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss,
  sq.daty AS daty
FROM (
  SELECT
    ofll.id AS id,
    ofll.idingredients AS idingredients,
    COALESCE(ofll.libelle, ai.libelle) AS libelle,
    ofll.remarque AS remarque,
    ofll.idmere AS idmere,
    ob.daty AS datybesoin,
    ofll.qte AS qte,
    COALESCE(au.val, 'unite') AS idunite,
    CAST(COALESCE(mv.entree, 0) AS DECIMAL(30, 5)) AS qtefabrique,
    CAST(ofll.qte - COALESCE(mv.entree, 0) AS DECIMAL(30, 5)) AS qtereste,
    COALESCE(ofll.libelle, COALESCE(ai.libelleextacte, ai.libelle)) AS libelleexacte,
    CAST(ofll.prixvente AS DECIMAL(30, 5)) AS pv,
    CAST(COALESCE(mv.entree, 0) * ai.pv AS DECIMAL(30, 5)) AS montantentree,
    CAST(COALESCE(mvt.montantsortie, 0) AS DECIMAL(30, 5)) AS montantsortie,
    CASE
      WHEN (
        COALESCE(mv.entree, 0) = 0 OR ai.pv = 0
      )
      THEN 0
      ELSE (
        1 - (
          CAST(mvt.montantsortie AS DECIMAL) / (
            COALESCE(mv.entree, 0) * ai.pv
          )
        )
      ) * 100
    END AS pourc,
    ob.daty AS daty
  FROM public.offille AS ofll
  LEFT JOIN public.as_ingredients AS ai
    ON ai.id = ofll.idingredients
  LEFT JOIN public.as_unite AS au
    ON au.id = ofll.idunite
  LEFT JOIN public.mvtstfilleoffcatvisegroupedep AS mvt
    ON ofll.id = mvt.idoff
  LEFT JOIN public.mvtstockfilleofentreeprfini AS mv
    ON mv.idoff = ofll.id AND mv.idproduit = ofll.idingredients
  LEFT JOIN public.ofab AS ob
    ON ob.id = ofll.idmere
) AS sq;

