CREATE VIEW public.offre_emploilib (
    "id", "idficheposte", "idfichepostelib", "titre", "description", "mission", "exigenceposte", "idtypecontrat", "idtypecontratlib", "salairemin", "salairemax", "etat", "datepublication", "datefermeture", "etatlib", "motsclesss"
) AS
SELECT
  o.id AS id,
  o.idficheposte AS idficheposte,
  fp.titre AS idfichepostelib,
  o.titre AS titre,
  o.description AS description,
  o.mission AS mission,
  o.exigenceposte AS exigenceposte,
  o.idtypecontrat AS idtypecontrat,
  tc.val AS idtypecontratlib,
  o.salairemin AS salairemin,
  o.salairemax AS salairemax,
  o.etat AS etat,
  o.datepublication AS datepublication,
  o.datefermeture AS datefermeture,
  CASE
    WHEN o.etat = 1
    THEN 'Cr&eacute;e'
    WHEN o.etat = 11
    THEN 'Vis&eacute;e'
    WHEN o.etat = 0
    THEN 'ANNUL&eacute;E'
    ELSE NULL
  END AS etatlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(o.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(o.idficheposte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fp.titre AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(o.titre AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(o.description AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(o.mission AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(o.exigenceposte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(o.idtypecontrat AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(tc.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    o.salairemin
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    o.salairemin
                  ) AS TEXT)))
                  ELSE CAST((
                    o.salairemin
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    o.salairemax
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    o.salairemax
                  ) AS TEXT)))
                  ELSE CAST((
                    o.salairemax
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    o.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    o.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    o.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(o.datepublication, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(o.datefermeture, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          CASE
            WHEN o.etat = 1
            THEN 'Cr&eacute;e'
            WHEN o.etat = 11
            THEN 'Vis&eacute;e'
            WHEN o.etat = 0
            THEN 'ANNUL&eacute;E'
            ELSE NULL
          END,
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM public.offre_emploi AS o
LEFT JOIN public.type_contrat AS tc
  ON tc.id = o.idtypecontrat
LEFT JOIN public.fiche_poste AS fp
  ON fp.id = o.idficheposte;

-- Niveau 1 - vue 53 / 129 : PAIE_AVANCEMENT_LIBELLE2
-- Dependances nouvelles : aucune.
CREATE VIEW public.paie_avancement_libelle2 (
    "id", "motif", "idmotif", "id_logpers", "matricule", "idpers", "datedecision", "refdecision", "date_application", "direction", "service", "idfonction", "ctg", "idcategorie", "echelon", "classee", "indicegrade", "indice_fonctionnel", "statut", "vehiculee", "remarque", "sexe", "etat", "matricule_patron", "droit_hs", "indice_ct", "code_banque", "fonctionlib", "etatlib", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.motif AS motif,
  base.idmotif AS idmotif,
  base.id_logpers AS id_logpers,
  base.matricule AS matricule,
  base.idpers AS idpers,
