  base.matricule_patron AS matricule_patron,
  base.droit_hs AS droit_hs,
  base.indice_ct AS indice_ct,
  base.code_banque AS code_banque,
  base.fonctionlib AS fonctionlib,
  base.etatlib AS etatlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.motif AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idmotif AS VARCHAR(4000)), NULL),
        ' | ',
