        ' | ',
        COALESCE(CAST(base.idpers AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.datedecision, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(base.refdecision AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.date_application, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(base.direction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.service AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idfonction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.ctg AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idcategorie AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.echelon AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.classee AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.indicegrade
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.indicegrade
                  ) AS TEXT)))
                  ELSE CAST((
                    base.indicegrade
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.indice_fonctionnel
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.indice_fonctionnel
                  ) AS TEXT)))
                  ELSE CAST((
                    base.indice_fonctionnel
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.statut AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.vehiculee AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.remarque AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.sexe AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    base.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.matricule_patron AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.droit_hs AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.indice_ct
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.indice_ct
                  ) AS TEXT)))
                  ELSE CAST((
                    base.indice_ct
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.code_banque AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.fonctionlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.etatlib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    pav.id AS id,
    dt.val AS motif,
    dt.id AS idmotif,
    NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS id_logpers,
    LPAD(CAST(pip.matricule AS TEXT), 5, '0') AS matricule,
    pip.id AS idpers,
    pav.datedecision AS datedecision,
    pav.refdecision AS refdecision,
    pav.date_application AS date_application,
    ld.val AS direction,
    ls.code_service AS service,
    pf.id AS idfonction,
    pav.ctg AS ctg,
    pg.val AS idcategorie,
    pav.echelon AS echelon,
    pav.classee AS classee,
    pav.indicegrade AS indicegrade,
    pav.indice_fonctionnel AS indice_fonctionnel,
    CASE
      WHEN pip.temporaire = -1
      THEN 'Temporaire'
      WHEN pip.temporaire = 0
      THEN 'Permanent'
      WHEN pip.temporaire = 1
      THEN 'Cadre'
      ELSE NULL
    END AS statut,
    pav.vehiculee AS vehiculee,
    pav.remarque AS remarque,
    lp.sexe AS sexe,
    pav.etat AS etat,
    pav.matricule_patron AS matricule_patron,
    pav.droit_hs AS droit_hs,
    pav.indice_ct AS indice_ct,
    pav.code_banque AS code_banque,
    pf.desce AS fonctionlib,
    CASE
      WHEN pav.etat = 1
      THEN 'NON VALIDE'
      WHEN pav.etat = 11
      THEN 'VALIDEE'
      ELSE 'AUTRE'
    END AS etatlib
  FROM public.paie_avancement AS pav
  LEFT JOIN public.dec_decision_type AS dt
    ON dt.id = pav.motif
  JOIN public.log_personnel AS lp
    ON lp.id = pav.id_logpers
  LEFT JOIN public.paie_info_personnel AS pip
    ON pip.id = pav.id_logpers
  LEFT JOIN public.log_direction AS ld
    ON ld.id = pav.direction
  LEFT JOIN public.log_service AS ls
    ON ls.id = pav.service
  LEFT JOIN public.paie_fonction AS pf
    ON pf.id = pav.idfonction
  LEFT JOIN public.paie_categorie AS pg
    ON pg.id = pav.idcategorie
) AS base;

-- Niveau 1 - vue 54 / 129 : PAIE_EDITIONMOISANNEE_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.paie_editionmoisannee_lib (
    "id", "idpersonnel", "mois", "annee", "gain", "retenue", "iduser", "iddirection", "daty", "mois_string", "etat", "montant"
) AS
SELECT
  pae.id AS id,
  NULLIF(CONCAT((
    NULLIF(CONCAT(log.nom, ' '), '')
  ), log.prenom), '') AS idpersonnel,
  pae.mois AS mois,
  pae.annee AS annee,
  pae.gain AS gain,
  pae.retenue AS retenue,
  u.nomuser AS iduser,
  dir.val AS iddirection,
  pae.daty AS daty,
  CASE
    WHEN pae.mois = 1
    THEN 'Janvier'
    WHEN pae.mois = 2
    THEN 'Fevrier'
    WHEN pae.mois = 3
    THEN 'Mars'
    WHEN pae.mois = 4
    THEN 'Avril'
    WHEN pae.mois = 5
    THEN 'Mai'
    WHEN pae.mois = 6
    THEN 'Juin'
    WHEN pae.mois = 7
    THEN 'Juillet'
    WHEN pae.mois = 8
    THEN 'Aout'
    WHEN pae.mois = 9
    THEN 'Septembre'
    WHEN pae.mois = 10
    THEN 'Octobre'
    WHEN pae.mois = 11
    THEN 'Novembre'
    WHEN pae.mois = 12
    THEN 'Decembre'
    WHEN pae.mois = 13
    THEN '13eme MOIS'
    WHEN pae.mois = 14
    THEN '13eme MOIS BIS'
    ELSE NULL
  END AS mois_string,
  pae.etat AS etat,
  CAST(ROUND(CAST(net.montant AS DECIMAL), 2) AS DECIMAL(15, 2)) AS montant
FROM public.paie_editionmoisannee AS pae
LEFT JOIN public.log_personnel AS log
  ON log.id_pers = pae.idpersonnel
LEFT JOIN public.log_direction AS dir
  ON dir.id = pae.iddirection
LEFT JOIN public.utilisateur AS u
  ON u.refuser = CAST(pae.iduser AS DECIMAL)
LEFT JOIN (
  SELECT
    pe.mois,
    pe.annee,
    CAST(SUM(pe.gain) AS DECIMAL(15, 2)) AS montant
  FROM public.paie_edition AS pe
  WHERE
    CAST(pe.idelementpaie AS TEXT) = CAST('PR000210A' AS TEXT)
  GROUP BY
    pe.mois,
    pe.annee
) AS net
  ON pae.mois = net.mois AND pae.annee = net.annee
ORDER BY
  pae.annee DESC,
  pae.mois DESC;

