-- Niveau 1 - vue 56 / 129 : PAIE_EDITIONMOISANNEE_LIB_3
-- Dependances nouvelles : aucune.
CREATE VIEW public.paie_editionmoisannee_lib_3 (
    "id", "idpersonnel", "mois", "annee", "gain", "retenue", "iduser", "iddirection", "daty", "mois_string", "etat", "idperiodepaie", "datedebut", "datefin", "montant", "categorie"
) AS
SELECT
  pae.id AS id,
  NULLIF(CONCAT((
    NULLIF(CONCAT(log.nom, ' '), '')
  ), log.prenom), '') AS idpersonnel,
  pae.mois AS mois,
  pae.annee AS annee,
  pae.gain AS gain,
  pae.retenue AS retenue,
  u.nomuser AS iduser,
  dir.val AS iddirection,
  pae.daty AS daty,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(pae.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS mois_string,
  pae.etat AS etat,
  pae.idperiodepaie AS idperiodepaie,
  pp.datedebut AS datedebut,
  pp.datefin AS datefin,
  CAST(ROUND(CAST(net.montant AS DECIMAL), 0) AS DECIMAL(15, 0)) AS montant,
  cps.val AS categorie
FROM public.paie_editionmoisannee AS pae
LEFT JOIN public.log_personnel AS log
  ON log.id_pers = pae.idpersonnel
LEFT JOIN public.log_direction AS dir
  ON dir.id = pae.iddirection
LEFT JOIN public.utilisateur AS u
  ON u.refuser = CAST(pae.iduser AS DECIMAL)
LEFT JOIN (
  SELECT
    pe.mois,
    pe.annee,
    CAST(SUM(pe.gain) AS DECIMAL(15, 2)) AS montant
  FROM public.paie_edition AS pe
  WHERE
    CAST(pe.idelementpaie AS TEXT) = CAST('PR000210A' AS TEXT)
  GROUP BY
    pe.mois,
    pe.annee
) AS net
  ON pae.mois = net.mois AND pae.annee = net.annee
LEFT JOIN public.periodepaie AS pp
  ON pp.id = pae.id
LEFT JOIN (
  SELECT
    cp.id,
    cp.val,
    cp.desce,
    cp.montant,
    cp.remarque,
    cp.droit_heure_sup,
    cp.essaie
  FROM public.categorie_paie AS cp
  WHERE
    CAST(cp.id AS TEXT) = ANY(
      CAST(ARRAY[CAST('CP0000010' AS VARCHAR), CAST('CP0000011' AS VARCHAR)] AS TEXT[])
    )
) AS cps
  ON cps.id = pp.idcategoriepaie
ORDER BY
  pae.annee DESC,
  pae.mois DESC;

-- Niveau 1 - vue 57 / 129 : PAIE_EDITION_CNAPS
-- Dependances nouvelles : aucune.
CREATE VIEW public.paie_edition_cnaps (
    "idpersonnel", "mois", "annee", "brut", "cnaps_travailleur", "cnaps_employeur"
) AS
SELECT
  pe.idpersonnel AS idpersonnel,
  pe.mois AS mois,
  pe.annee AS annee,
  ROUND(CAST(SUM(pe.gain) AS DECIMAL), 2) AS brut,
  COALESCE(edc.cnaps_travailleur, 0) AS cnaps_travailleur,
  CASE
    WHEN COALESCE(edc.cnaps_travailleur, 0) = 0
    THEN 0
    ELSE CASE
      WHEN (
        SELECT
          conf_cnaps.plafond AS plafond
        FROM public.conf_cnaps AS conf_cnaps
        WHERE
          conf_cnaps.daty >= pe.datefin AND TRUE
        LIMIT 1
      ) < (
        SUM(pe.gain) * 0.13
      )
      THEN (
        SELECT
          conf_cnaps.plafond AS plafond
        FROM public.conf_cnaps AS conf_cnaps
        WHERE
          conf_cnaps.daty >= pe.datefin AND TRUE
        LIMIT 1
      )
      ELSE ROUND(
        CAST(LEAST(COALESCE(edc.cnaps_travailleur, 0) * 13, SUM(pe.gain) * 0.13) AS DECIMAL),
        2
      )
    END
  END AS cnaps_employeur
FROM public.paie_edition AS pe
JOIN public.paie_rubrique AS pr
  ON pe.idelementpaie = pr.id AND pr.typerubrique = 'G' AND pr.imposable = 'I'
LEFT JOIN (
  SELECT
    pe_1.idpersonnel AS idpersonnel,
    pe_1.mois AS mois,
    pe_1.annee AS annee,
    pe_1.retenue AS cnaps_travailleur
  FROM public.paie_edition AS pe_1
  WHERE
    pe_1.idelementpaie = 'PR000101'
) AS edc
  ON pe.idpersonnel = edc.idpersonnel AND pe.mois = edc.mois AND pe.annee = edc.annee
GROUP BY
  pe.idpersonnel,
  pe.mois,
  pe.annee,
  edc.cnaps_travailleur,
  pe.datefin;

-- Niveau 1 - vue 58 / 129 : PAIE_EDITION_GRP_PERSONNE2
-- Dependances nouvelles : aucune.
CREATE VIEW public.paie_edition_grp_personne2 (
    "gain", "idpersonnel"
) AS
SELECT
  (
    grp2.gain + sfrm.montant
  ) AS gain,
  grp2.idpersonnel AS idpersonnel
FROM (
  SELECT
    CAST(SUM(paie_edition.gain) AS DECIMAL(15, 2)) AS gain,
    paie_edition.idpersonnel AS idpersonnel
  FROM public.paie_edition AS paie_edition
  WHERE
    paie_edition.idelementpaie NOT LIKE '%PR000FRM%' AND paie_edition.annee > 2023
  GROUP BY
    paie_edition.idpersonnel
) AS grp2
LEFT JOIN public.solde_frm_2023 AS sfrm
  ON grp2.idpersonnel = sfrm.idpersonnel;

-- Niveau 1 - vue 59 / 129 : PAIE_EDITION_LIBCOMPLET
-- Dependances nouvelles : aucune.
CREATE VIEW public.paie_edition_libcomplet (
    "id", "idpersonnel", "idelementpaie", "mois", "annee", "gain", "retenue", "datedebut", "datefin", "idedition", "remarque", "idpersonnellib", "idelementpaielib", "matricule", "coderubrique", "moislib", "motsclesss"
) AS
SELECT
  pe.id AS id,
  pe.idpersonnel AS idpersonnel,
  pe.idelementpaie AS idelementpaie,
  pe.mois AS mois,
  pe.annee AS annee,
  pe.gain AS gain,
  pe.retenue AS retenue,
  pe.datedebut AS datedebut,
  pe.datefin AS datefin,
  pe.idedition AS idedition,
  pe.remarque AS remarque,
  NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS idpersonnellib,
  NULLIF(CONCAT(pr.code, ' ', pr.val), '') AS idelementpaielib,
  lp.matricule AS matricule,
  pr.code AS coderubrique,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(pe.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(pe.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pe.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pe.idelementpaie AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    pe.mois
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    pe.mois
                  ) AS TEXT)))
                  ELSE CAST((
                    pe.mois
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    pe.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    pe.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    pe.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    pe.gain
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    pe.gain
                  ) AS TEXT)))
                  ELSE CAST((
                    pe.gain
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    pe.retenue
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    pe.retenue
                  ) AS TEXT)))
                  ELSE CAST((
                    pe.retenue
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(pe.datedebut, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(pe.datefin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(pe.idedition AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pe.remarque AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(pr.code, ' ', pr.val), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(lp.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pr.code AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          (
            ARRAY[
              'Janvier',
              'Février',
              'Mars',
              'Avril',
              'Mai',
              'Juin',
              'Juillet',
              'Août',
              'Septembre',
              'Octobre',
              'Novembre',
              'Décembre'
            ]
          )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(pe.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0],
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM public.paie_edition AS pe
LEFT JOIN public.log_personnel_infocomplet AS lp
  ON lp.id = pe.idpersonnel
LEFT JOIN public.paie_rubrique AS pr
  ON pr.id = pe.idelementpaie
LEFT JOIN public.paie_editionmoisannee AS p
  ON p.id = pe.idedition;

-- Niveau 1 - vue 60 / 129 : PERIODEPAIELIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.periodepaielib (
    "id", "mois", "datedebut", "datefin", "idcategoriepaie", "annee", "etat", "moislib", "categorielib"
) AS
SELECT
  p.id AS id,
  p.mois AS mois,
  p.datedebut AS datedebut,
  p.datefin AS datefin,
  p.idcategoriepaie AS idcategoriepaie,
  p.annee AS annee,
  p.etat AS etat,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(CAST(p.mois AS DECIMAL), 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
  categ.val AS categorielib
FROM public.periodepaie AS p
LEFT JOIN public.categorie_paie AS categ
  ON categ.id = p.idcategoriepaie;

-- Niveau 1 - vue 61 / 129 : PLANFORMATIONANNUELLELIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.planformationannuellelib (
    "id", "annee", "libelle", "etat", "etatlib", "budgettotalprevisionel", "daty", "motsclesss"
) AS
SELECT
  p.id AS id,
  p.annee AS annee,
  p.libelle AS libelle,
  p.etat AS etat,
  CASE
    WHEN p.etat = 1
    THEN 'Cree'
    WHEN p.etat = 11
    THEN 'Valide'
    WHEN p.etat = 0
    THEN 'Annule'
    ELSE 'Inconnu'
  END AS etatlib,
  p.budgettotalprevisionel AS budgettotalprevisionel,
  p.daty AS daty,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(p.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    p.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    p.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    p.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(p.libelle AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    p.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    p.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    p.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        CASE
          WHEN p.etat = 1
          THEN 'Cree'
          WHEN p.etat = 11
          THEN 'Valide'
          WHEN p.etat = 0
          THEN 'Annule'
          ELSE 'Inconnu'
        END,
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    p.budgettotalprevisionel
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    p.budgettotalprevisionel
                  ) AS TEXT)))
                  ELSE CAST((
                    p.budgettotalprevisionel
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(p.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.plan_formation_annuel AS p;

-- Niveau 1 - vue 62 / 129 : POINTAGECANTINE_CPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.pointagecantine_cpl (
    "id", "idpersonnel", "iddepartement", "mois", "annee", "nombre", "daty", "etat", "moislib", "nompersonnel", "matricule", "departementlib", "etatlib"
) AS
SELECT
  pt.id AS id,
  pt.idpersonnel AS idpersonnel,
  pt.iddepartement AS iddepartement,
  pt.mois AS mois,
  pt.annee AS annee,
  pt.nombre AS nombre,
  pt.daty AS daty,
  pt.etat AS etat,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(pt.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
  NULLIF(CONCAT(log.nom, ' ', log.prenom), '') AS nompersonnel,
  pip.matricule AS matricule,
  dp.val AS departementlib,
  CASE
    WHEN pt.etat = 1
    THEN 'CREE'
    WHEN pt.etat = 11
    THEN 'VALIDE'
    WHEN pt.etat = 0
    THEN 'ANNULE'
    ELSE 'INCONNU'
  END AS etatlib
FROM public.pointagecantine AS pt
LEFT JOIN public.log_personnel AS log
  ON log.id = pt.idpersonnel
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = pt.idpersonnel
LEFT JOIN public.departement AS dp
  ON dp.id = pt.iddepartement;

-- Niveau 1 - vue 63 / 129 : POINTAGE_LIB
