CREATE VIEW public.pointage_lib (
    "id", "idpersonnel", "direction", "annee", "mois", "heurenormal", "heuresupferie", "heuresupnormal", "heuresupnuit", "heuresupweekend", "absence", "daty", "etat", "directionlib", "moislib", "matricule", "nompersonnel"
) AS
SELECT
  p.id AS id,
  p.idpersonnel AS idpersonnel,
  p.direction AS direction,
  p.annee AS annee,
  p.mois AS mois,
  p.heurenormal AS heurenormal,
  p.heuresupferie AS heuresupferie,
  p.heuresupnormal AS heuresupnormal,
  p.heuresupnuit AS heuresupnuit,
  p.heuresupweekend AS heuresupweekend,
  p.absence AS absence,
  p.daty AS daty,
  p.etat AS etat,
  ld.val AS directionlib,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(p.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
  ec.matricule AS matricule,
  NULLIF(CONCAT(ec.nom, ' ', ec.prenom), '') AS nompersonnel
FROM public.pointage AS p
LEFT JOIN public.log_direction AS ld
  ON ld.id = p.direction
LEFT JOIN public.employe_complet AS ec
  ON ec.id = p.idpersonnel;

-- Niveau 1 - vue 64 / 129 : PRELEVEMENTCPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.prelevementcpl (
    "id", "idprelevementanterieur", "compteur", "daty", "heure", "idpompiste", "idpompe", "etat", "etatlib", "idcaisse", "idmagasin", "idproduit", "puvente", "maxpompe"
) AS
SELECT
  p.id AS id,
  p.idprelevementanterieur AS idprelevementanterieur,
  p.compteur AS compteur,
  p.daty AS daty,
  p.heure AS heure,
  p.idpompiste AS idpompiste,
  p.idpompe AS idpompe,
  p.etat AS etat,
  CASE
    WHEN p.etat = 0
    THEN 'ANNULEE'
    WHEN p.etat = 1
    THEN 'CREE'
    WHEN p.etat = 11
    THEN 'VALIDEE'
  END AS etatlib,
  c.id AS idcaisse,
  p2.idmagasin AS idmagasin,
  p3.id AS idproduit,
  p3.puvente AS puvente,
  p2.max AS maxpompe
FROM public.prelevement AS p
LEFT JOIN public.caisse AS c
  ON CAST(c.idpompiste AS DECIMAL) = p.idpompiste
LEFT JOIN public.pompe AS p2
  ON p2.id = p.idpompe
LEFT JOIN (
  SELECT
    p.id,
    p.val,
    p.desce,
    p.id AS idpoint,
    CAST('-' AS TEXT) AS idproduit,
    CAST(NULL AS TEXT) AS idtypemagasin,
    11 AS etat
  FROM public.point AS p
) AS m
  ON m.id = p2.idmagasin
LEFT JOIN public.produit AS p3
  ON p3.id = m.idproduit;

-- Niveau 1 - vue 65 / 129 : PRELEVEMENT_POMPISTE
-- Dependances nouvelles : aucune.
CREATE VIEW public.prelevement_pompiste (
    "indexf", "indexo", "vente", "produit", "pu", "montant", "id"
) AS
SELECT
  p2.compteur AS indexf,
  p.compteur AS indexo,
  p.compteur - p2.compteur AS vente,
  pro.val AS produit,
  pro.puvente AS pu,
  (
    p.compteur - p2.compteur
  ) * pro.puvente AS montant,
  pe.idencaissement AS id
FROM public.prelevement AS p
JOIN public.prelevement AS p2
  ON p2.id = p.idprelevementanterieur
JOIN public.pompe AS po
  ON po.id = p.idpompe
JOIN (
  SELECT
    p.id,
    p.val,
    p.desce,
    p.id AS idpoint,
    CAST('-' AS TEXT) AS idproduit,
    CAST(NULL AS TEXT) AS idtypemagasin,
    11 AS etat
  FROM public.point AS p
) AS m
  ON m.id = po.idmagasin
JOIN public.produit AS pro
  ON pro.id = m.idproduit
JOIN public.prelevement_encaisse AS pe
  ON pe.idprelevement = p.id;

