SELECT
  base.id AS id,
  base.designation AS designation,
  base.idcaisse AS idcaisse,
  base.idcaisselib AS idcaisselib,
  base.idventedetail AS idventedetail,
  base.idvente AS idvente,
  base.idventelib AS idventelib,
  base.idvirement AS idvirement,
  base.debit AS debit,
  base.credit AS credit,
  base.daty AS daty,
  base.etat AS etat,
  base.idop AS idop,
  base.idoplib AS idoplib,
  base.idorigine AS idorigine,
  base.iddevise AS iddevise,
  base.iddeviselib AS iddeviselib,
  base.taux AS taux,
  base.idtiers AS idtiers,
  base.compte AS compte,
  base.idfacture AS idfacture,
  base.idreservation AS idreservation,
  base.dateinitial AS dateinitial,
  base.dureeretard AS dureeretard,
  base.mois AS mois,
