        ' | ',
        COALESCE(CAST(base.idcaisse AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idcaisselib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idventedetail AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idvente AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idventelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idvirement AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.debit
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.debit
                  ) AS TEXT)))
                  ELSE CAST((
                    base.debit
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.credit
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.credit
                  ) AS TEXT)))
                  ELSE CAST((
                    base.credit
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(base.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    base.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.idop AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idoplib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idorigine AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.iddevise AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.iddeviselib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.taux
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.taux
                  ) AS TEXT)))
                  ELSE CAST((
                    base.taux
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.idtiers AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.compte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idfacture AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idreservation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.dateinitial, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.dureeretard
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.dureeretard
                  ) AS TEXT)))
                  ELSE CAST((
                    base.dureeretard
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.mois
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.mois
                  ) AS TEXT)))
                  ELSE CAST((
                    base.mois
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.moislib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.service AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idservicelib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    p.id AS id,
    p.designation AS designation,
    p.idcaisse AS idcaisse,
    c.val AS idcaisselib,
    p.idventedetail AS idventedetail,
    v.idvente AS idvente,
    v2.designation AS idventelib,
    p.idvirement AS idvirement,
    p.debit AS debit,
    p.credit AS credit,
    p.daty AS daty,
    p.etat AS etat,
    p.idop AS idop,
    o.designation AS idoplib,
    p.idorigine AS idorigine,
    p.iddevise AS iddevise,
    p.designation AS iddeviselib,
    p.taux AS taux,
    p.idtiers AS idtiers,
    p.compte AS compte,
    p.idfacture AS idfacture,
    v2.idreservation AS idreservation,
    p.dateinitial AS dateinitial,
    p.dureeretard AS dureeretard,
    p.mois AS mois,
    p.annee AS annee,
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(p.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
    p.service AS service,
    s.libelle AS idservicelib
  FROM public.prevision AS p
  LEFT JOIN public.caisse AS c
    ON c.id = p.idcaisse
  LEFT JOIN public.vente_details AS v
    ON v.id = p.idventedetail
  LEFT JOIN public.vente AS v2
    ON v2.id = v.idvente
  LEFT JOIN public.ordonnerpaiement AS o
    ON o.id = p.idop
  LEFT JOIN public.service AS s
    ON s.compte = p.service
  LEFT JOIN public.devise AS d
    ON d.id = p.iddevise
) AS base;

-- Niveau 1 - vue 67 / 129 : PROCESSMAINTENANCELIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.processmaintenancelib (
    "id", "idpersonnel", "idtravaux", "datedebut", "datefin", "heuredebut", "heurefin", "datetime_debut", "datetime_fin", "ecart_seconde", "ecart_hms", "idpersonnellib"
) AS
SELECT
  prc.id AS id,
  prc.idpersonnel AS idpersonnel,
  prc.idtravaux AS idtravaux,
  prc.datedebut AS datedebut,
  prc.datefin AS datefin,
  prc.heuredebut AS heuredebut,
  prc.heurefin AS heurefin,
  prc.datetime_debut AS datetime_debut,
  prc.datetime_fin AS datetime_fin,
  ROUND(
    (
      (
        EXTRACT(EPOCH FROM (
          prc.datetime_fin - prc.datetime_debut
        )) / 86400.0
      )
    ) * 86400
  ) AS ecart_seconde, /* Ecart en secondes */
  NULLIF(
    CONCAT(
      LPAD(
        CAST(FLOOR(
          CAST(ROUND(
            (
              (
                EXTRACT(EPOCH FROM (
                  prc.datetime_fin - prc.datetime_debut
                )) / 86400.0
              )
            ) * 86400
          ) AS DECIMAL) / 3600
        ) AS TEXT),
        2,
        '0'
      ) /* Ecart format HH:MM:SS */,
      ':',
      LPAD(
        CAST(FLOOR(
          CAST(CAST(ROUND(
            (
              (
                EXTRACT(EPOCH FROM (
                  prc.datetime_fin - prc.datetime_debut
                )) / 86400.0
              )
            ) * 86400
          ) AS DECIMAL) % CAST(3600 AS DECIMAL) AS DECIMAL) / 60
        ) AS TEXT),
        2,
        '0'
      ),
      ':',
      LPAD(
        CAST(CAST(ROUND(
          (
            (
              EXTRACT(EPOCH FROM (
                prc.datetime_fin - prc.datetime_debut
              )) / 86400.0
            )
          ) * 86400
        ) AS DECIMAL) % CAST(60 AS DECIMAL) AS TEXT),
        2,
        '0'
      )
    ),
    ''
  ) AS ecart_hms,
  p.nom AS idpersonnellib
FROM (
  SELECT
    prc.id AS id,
    prc.idpersonnel AS idpersonnel,
    prc.idtravaux AS idtravaux,
    prc.datedebut AS datedebut,
    prc.datefin AS datefin,
    prc.heuredebut AS heuredebut,
    prc.heurefin AS heurefin,
    (
      prc.datedebut /* Date + Heure debut */ + (
        (
          (
            EXTRACT(EPOCH FROM (
              CAST(TO_TIMESTAMP(CAST(prc.heuredebut AS TEXT), 'HH24:MI:SS') AS TIMESTAMP) - DATE_TRUNC('DAY', CAST(TO_TIMESTAMP(CAST(prc.heuredebut AS TEXT), 'HH24:MI:SS') AS TIMESTAMP))
            )) / 86400.0
          )
        )
      ) * INTERVAL '1 DAY'
    ) AS datetime_debut,
    (
      prc.datefin /* Date + Heure fin */ + (
        (
          (
            EXTRACT(EPOCH FROM (
              CAST(TO_TIMESTAMP(CAST(prc.heurefin AS TEXT), 'HH24:MI:SS') AS TIMESTAMP) - DATE_TRUNC('DAY', CAST(TO_TIMESTAMP(CAST(prc.heurefin AS TEXT), 'HH24:MI:SS') AS TIMESTAMP))
            )) / 86400.0
          )
        )
      ) * INTERVAL '1 DAY'
    ) AS datetime_fin
  FROM public.processmaintenance AS prc
) AS prc
LEFT JOIN public.personnel AS p
  ON p.id = prc.idpersonnel;

-- Niveau 1 - vue 68 / 129 : RECAPITULATIF_ALL_FINAL
-- Dependances nouvelles : aucune.
CREATE VIEW public.recapitulatif_all_final (
    "mois", "annee", "salaire", "indemnite", "avantage_en_nature", "salaire_brut", "irsa", "cnaps_travailleur", "montant_net_payer", "cnaps_employeur", "cnaps_a_payer", "total_frm", "id", "moislib", "motsclesss"
) AS
SELECT
  rs.mois AS mois,
  rs.annee AS annee,
  rs.salaire AS salaire,
  rs.indemnite AS indemnite,
  rs.avantage_en_nature AS avantage_en_nature,
  rs.salaire_brut AS salaire_brut,
  rs.irsa AS irsa,
  rs.cnaps_travailleur AS cnaps_travailleur,
  CAST(rs.montant_net_payer AS DECIMAL(30, 2)) AS montant_net_payer,
  rs.cnaps_employeur AS cnaps_employeur,
  rs.cnaps_a_payer AS cnaps_a_payer,
  frm.total_frm AS total_frm,
  rs.id AS id,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(rs.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
  (
    NULLIF(
      CONCAT(
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    rs.mois
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    rs.mois
