                  ) AS TEXT)))
                  ELSE CAST((
                    rs.cnaps_travailleur
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    CAST(rs.montant_net_payer AS DECIMAL(30, 2))
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    CAST(rs.montant_net_payer AS DECIMAL(30, 2))
                  ) AS TEXT)))
                  ELSE CAST((
                    CAST(rs.montant_net_payer AS DECIMAL(30, 2))
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    rs.cnaps_employeur
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    rs.cnaps_employeur
                  ) AS TEXT)))
                  ELSE CAST((
                    rs.cnaps_employeur
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
