        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    frm.total_frm
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    frm.total_frm
                  ) AS TEXT)))
                  ELSE CAST((
                    frm.total_frm
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(rs.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          (
            ARRAY[
              'Janvier',
              'Février',
              'Mars',
              'Avril',
              'Mai',
              'Juin',
              'Juillet',
              'Août',
              'Septembre',
              'Octobre',
              'Novembre',
              'Décembre'
            ]
          )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(rs.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0],
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    recap_sal_all.mois,
    recap_sal_all.annee,
    recap_sal_all.salaire,
    recap_sal_all.indemnite,
    recap_sal_all.avantage_en_nature,
    recap_sal_all.salaire_brut,
    recap_sal_all.irsa,
    recap_sal_all.cnaps_travailleur,
    recap_sal_all.montant_net_payer,
    recap_sal_all.cnaps_employeur,
    recap_sal_all.cnaps_a_payer,
    recap_sal_all.id
  FROM (
    SELECT
      pe.mois,
      pe.annee,
      ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR000041' AS TEXT)
            THEN COALESCE(pe.gain, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) AS DECIMAL),
        2
      ) AS salaire,
      ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = ANY(
              CAST(ARRAY[
                CAST('PR000021' AS VARCHAR),
                CAST('PR000061' AS VARCHAR),
                CAST('PR000081' AS VARCHAR),
                CAST('PR000001' AS VARCHAR)
              ] AS TEXT[])
            )
            THEN COALESCE(pe.gain, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) AS DECIMAL),
        2
      ) AS indemnite,
      ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR000201' AS TEXT)
            THEN COALESCE(pe.gain, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) AS DECIMAL),
        2
      ) AS avantage_en_nature,
      ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PRUNI' AS TEXT)
            THEN COALESCE(pegi.imposable, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) AS DECIMAL),
        2
      ) AS salaire_brut,
      ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR000141' AS TEXT)
            THEN COALESCE(pe.retenue, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) AS DECIMAL),
        2
      ) AS irsa,
      ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR000101' AS TEXT)
            THEN COALESCE(pe.retenue, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) AS DECIMAL),
        2
      ) AS cnaps_travailleur,
      CAST(ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR000210A' AS TEXT)
            THEN COALESCE(pe.gain, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) AS DECIMAL),
        2
      ) AS DECIMAL(30, 2)) AS montant_net_payer,
      ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR000101' AS TEXT)
            THEN COALESCE(pe.retenue, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) * CAST(13 AS DECIMAL) AS DECIMAL),
        2
      ) AS cnaps_employeur,
      ROUND(
        CAST(SUM(
          CASE
            WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR000101' AS TEXT)
            THEN COALESCE(pe.retenue, CAST(0 AS DECIMAL))
            ELSE CAST(0 AS DECIMAL)
          END
        ) * CAST(14 AS DECIMAL) AS DECIMAL),
        2
      ) AS cnaps_a_payer,
      pe.idedition AS id
    FROM public.paie_edition AS pe
    LEFT JOIN (
      SELECT
        paie_edition.idpersonnel,
        paie_edition.mois,
        paie_edition.annee,
        CAST(SUM(paie_edition.gain) AS DECIMAL(15, 2)) AS imposable
      FROM public.paie_edition
      WHERE
        (
          CAST(paie_edition.idelementpaie AS TEXT) IN (
            SELECT
              paie_rubrique.id
            FROM public.paie_rubrique
            WHERE
              CAST(paie_rubrique.typerubrique AS TEXT) = CAST('G' AS TEXT)
              AND CAST(paie_rubrique.imposable AS TEXT) = CAST('I' AS TEXT)
              AND CAST(paie_rubrique.id AS TEXT) NOT LIKE CAST('%AV%' AS TEXT)
          )
        )
      GROUP BY
        paie_edition.idpersonnel,
        paie_edition.mois,
        paie_edition.annee
    ) AS pegi
      ON CAST(pe.idpersonnel AS TEXT) = CAST(pegi.idpersonnel AS TEXT)
      AND pe.mois = pegi.mois
      AND pe.annee = pegi.annee
      AND (
        CAST(pe.idelementpaie AS TEXT) = ANY(
          CAST(ARRAY[
            CAST('PR000041' AS VARCHAR),
            CAST('PR000021' AS VARCHAR),
            CAST('PR000061' AS VARCHAR),
            CAST('PR000081' AS VARCHAR),
            CAST('PR000001' AS VARCHAR),
            CAST('PR000201' AS VARCHAR),
            CAST('PRUNI' AS VARCHAR),
            CAST('PR000141' AS VARCHAR),
            CAST('PR000101' AS VARCHAR),
            CAST('PR000210A' AS VARCHAR)
          ] AS TEXT[])
        )
      )
    GROUP BY
      pe.annee,
      pe.mois,
      pe.idedition
  ) AS recap_sal_all
) AS rs
LEFT JOIN (
  SELECT
    fma.mois,
    fma.annee,
    CAST(SUM(fma.frais_medicaux) AS DECIMAL(15, 2)) AS total_frm
  FROM (
    SELECT
      pip.id,
      pip.matricule,
      NULLIF(CONCAT(CAST(lp.nom AS TEXT), CAST(lp.prenom AS TEXT)), '') AS nom,
      pf.desce AS poste,
      pip.dateembauche,
      pip.numero_cnaps,
      frm.total_brut,
      frm.frais_medicaux,
      frm.mois,
      frm.annee,
      frm.total_brut * 0.06 AS test,
      mo.val AS moislib
    FROM public.paie_info_personnel AS pip
    LEFT JOIN public.paie_fonction AS pf
      ON CAST(pip.idfonction AS TEXT) = CAST(pf.id AS TEXT)
    LEFT JOIN public.log_personnel AS lp
      ON CAST(lp.id AS TEXT) = CAST(pip.id AS TEXT)
    LEFT JOIN (
      SELECT
        pe.idpersonnel,
        pe.mois,
        pe.annee,
        SUM(pe.gain) AS total_brut,
        COALESCE(prfrm.gain, CAST(0 AS DECIMAL)) AS frais_medicaux
      FROM public.paie_edition AS pe
      LEFT JOIN public.paie_edition AS prfrm
        ON CAST(pe.idpersonnel AS TEXT) = CAST(prfrm.idpersonnel AS TEXT)
        AND pe.mois = prfrm.mois
        AND pe.annee = prfrm.annee
        AND CAST(prfrm.idelementpaie AS TEXT) = CAST('PR000FRM' AS TEXT)
      WHERE
        (
          CAST(pe.idelementpaie AS TEXT) IN (
            SELECT
              pr.id
            FROM public.paie_rubrique AS pr
            WHERE
              CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
              AND (
                CAST(pr.id AS TEXT) <> ALL(
                  CAST(ARRAY[
                    CAST('PR000210A' AS VARCHAR),
                    CAST('PR000FRM' AS VARCHAR),
                    CAST('PR000181' AS VARCHAR)
                  ] AS TEXT[])
                )
              )
          )
        )
      GROUP BY
        pe.idpersonnel,
        pe.mois,
        pe.annee,
        prfrm.gain
    ) AS frm
      ON CAST(frm.idpersonnel AS TEXT) = CAST(pip.id AS TEXT)
    LEFT JOIN public.moiscp AS mo
      ON mo.id = frm.mois
  ) AS fma
  GROUP BY
    fma.mois,
    fma.annee
) AS frm
  ON rs.mois = frm.mois AND rs.annee = frm.annee;

-- Niveau 1 - vue 69 / 129 : RELEVERDETAILORDER
-- Dependances nouvelles : aucune.
CREATE VIEW public.releverdetailorder (
    "id", "idmere", "daty", "datyvaleur", "designation", "debit", "credit", "solde"
) AS
SELECT
  releverdetail.id AS id,
  releverdetail.idmere AS idmere,
  releverdetail.daty AS daty,
  releverdetail.datyvaleur AS datyvaleur,
  releverdetail.designation AS designation,
  releverdetail.debit AS debit,
  releverdetail.credit AS credit,
  releverdetail.solde AS solde
FROM public.releverdetail AS releverdetail
ORDER BY
  CAST(REGEXP_REPLACE(id, '[^0-9]', NULL, 'g') AS DECIMAL) ASC;

-- Niveau 1 - vue 70 / 129 : REMBOURSEMENTLIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.remboursementlib (
    "id", "idavance", "mois", "annee", "montant", "remarque", "daty", "etat", "personnel", "typeavancelib", "etatlib", "matricule", "moislib", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.idavance AS idavance,
  sq.mois AS mois,
  sq.annee AS annee,
  sq.montant AS montant,
  sq.remarque AS remarque,
  sq.daty AS daty,
  sq.etat AS etat,
  sq.personnel AS personnel,
  sq.typeavancelib AS typeavancelib,
  sq.etatlib AS etatlib,
  sq.matricule AS matricule,
  sq.moislib AS moislib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.idavance AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.mois
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.mois
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.mois
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montant
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montant
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montant
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.remarque AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.personnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.typeavancelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.etatlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.moislib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    pr.id AS id,
    pr.idavance AS idavance,
    pr.mois AS mois,
    pr.annee AS annee,
    pr.montant AS montant,
    pr.remarque AS remarque,
    pr.daty AS daty,
    pr.etat AS etat,
    NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS personnel,
    t.val AS typeavancelib,
    CASE WHEN pr.etat = 1 THEN 'CREE' WHEN pr.etat = 11 THEN 'VALIDE' ELSE NULL END AS etatlib,
    pip.matricule AS matricule,
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(pr.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib
  FROM public.remboursement AS pr
  LEFT JOIN public.avance AS a
    ON a.id = pr.idavance
  LEFT JOIN public.typeavance AS t
    ON t.id = a.idtypeavance
  LEFT JOIN public.paie_info_personnel AS pip
    ON pip.id = a.idpersonnel
  LEFT JOIN public.log_personnel AS lp
    ON lp.id = a.idpersonnel
) AS sq;

-- Niveau 1 - vue 71 / 129 : REPORTSOLDE_ANALYTIQUE
-- Dependances nouvelles : aucune.
CREATE VIEW public.reportsolde_analytique (
    "compte", "libelle_compte", "debit", "credit", "typecompte", "mois", "annee", "chiffre3", "chiffre2"
) AS
SELECT
  _0.compte AS compte,
  _0.libelle AS libelle,
  CAST(_0.debit AS DECIMAL(30, 2)) AS debit,
  CAST(_0.credit AS DECIMAL(30, 2)) AS credit,
  _0.typecompte AS typecompte,
  _0.mois AS mois,
  _0.annee AS annee,
  _0.chiffre3 AS chiffre3,
  _0.chiffre2 AS chiffre2
FROM (
  SELECT
    cse.analytique AS compte,
    cc.libelle AS libelle,
    SUM(cse.debit) AS debit,
    SUM(cse.credit) AS credit,
    cc.typecompte AS typecompte,
    EXTRACT(MONTH FROM cse.daty) AS mois,
    EXTRACT(YEAR FROM cse.daty) AS annee,
    NULLIF(
      CONCAT(
        NULLIF(SUBSTRING(cse.analytique FROM 1 FOR 3), ''),
        NULLIF(SUBSTRING(cse.analytique FROM 5 FOR 1), '')
      ),
      ''
    ) AS chiffre3,
    NULLIF(SUBSTRING(cse.analytique FROM 1 FOR 2), '') AS chiffre2
  FROM public.compta_sous_ecriture AS cse, public.compta_compte AS cc, public.compta_journal AS jrn
  WHERE
    cc.compte = cse.analytique AND cse.etat = 11 AND cse.journal = jrn.id
  GROUP BY
    cse.analytique,
    cc.libelle,
    cc.typecompte,
    EXTRACT(MONTH FROM cse.daty),
    EXTRACT(YEAR FROM cse.daty)
) AS _0;

-- Niveau 1 - vue 72 / 129 : REPORTSOLDE_GENERAL
-- Dependances nouvelles : aucune.
CREATE VIEW public.reportsolde_general (
    "compte", "libelle_compte", "debit", "credit", "typecompte", "mois", "annee", "chiffre3", "chiffre2"
) AS
SELECT
  _0.compte AS compte,
  _0.libelle AS libelle,
  CAST(_0.debit AS DECIMAL(30, 2)) AS debit,
  CAST(_0.credit AS DECIMAL(30, 2)) AS credit,
  _0.typecompte AS typecompte,
  _0.mois AS mois,
  _0.annee AS annee,
  _0.chiffre3 AS chiffre3,
  _0.chiffre2 AS chiffre2
FROM (
  SELECT
    cse.compte AS compte,
    cc.libelle AS libelle,
    SUM(cse.debit) AS debit,
    SUM(cse.credit) AS credit,
    cc.typecompte AS typecompte,
    EXTRACT(MONTH FROM cse.daty) AS mois,
    EXTRACT(YEAR FROM cse.daty) AS annee,
    CASE
      WHEN NULLIF(SUBSTRING(cse.compte FROM 1 FOR 4), '') = '4007'
      THEN '407'
      ELSE NULLIF(
        CONCAT(
          NULLIF(SUBSTRING(cse.compte FROM 1 FOR 2), ''),
          NULLIF(SUBSTRING(cse.compte FROM 5 FOR 1), '')
        ),
        ''
      )
    END AS chiffre3,
    NULLIF(SUBSTRING(cse.compte FROM 1 FOR 2), '') AS chiffre2
  FROM public.compta_sous_ecriture AS cse, public.compta_compte AS cc, public.compta_journal AS jrn
  WHERE
    cc.compte = cse.compte AND cse.etat = 11 AND cse.journal = jrn.id
  GROUP BY
    cse.compte,
    cc.libelle,
    cc.typecompte,
    EXTRACT(MONTH FROM cse.daty),
    EXTRACT(YEAR FROM cse.daty)
) AS _0;

-- Niveau 1 - vue 73 / 129 : REPORTSOLDE_JANVIER
-- Dependances nouvelles : aucune.
CREATE VIEW public.reportsolde_janvier (
    "compte", "libelle_compte", "debit", "credit", "typecompte", "mois", "annee", "chiffre3", "chiffre2"
) AS
SELECT
  _0.compte AS compte,
  _0.libelle AS libelle,
  CAST(SUM(_0.debit) AS DECIMAL(30, 2)) AS _col_2,
  CAST(SUM(_0.credit) AS DECIMAL(30, 2)) AS _col_3,
  _0.typecompte AS typecompte,
  _0.mois AS mois,
  _0.annee AS annee,
  _0.chiffre3 AS chiffre3,
  _0.chiffre2 AS chiffre2
FROM (
  SELECT
    cse.compte AS compte,
    cc.libelle AS libelle,
    cse.debit AS debit,
    cse.credit AS credit,
    cc.typecompte AS typecompte,
    EXTRACT(MONTH FROM cse.daty) AS mois,
    EXTRACT(YEAR FROM cse.daty) AS annee,
    CASE
      WHEN CAST(cc.typecompte AS DECIMAL) = 3
      THEN NULLIF(
        CONCAT(
          NULLIF(SUBSTRING(cse.compte FROM 1 FOR 3), ''),
          NULLIF(SUBSTRING(cse.compte FROM 5 FOR 1), '')
        ),
        ''
      )
      WHEN CAST(cc.typecompte AS DECIMAL) = 1
      AND NULLIF(SUBSTRING(cse.compte FROM 1 FOR 4), '') = '4007'
      THEN '407'
      ELSE NULLIF(
        CONCAT(
          NULLIF(SUBSTRING(cse.compte FROM 1 FOR 2), ''),
          NULLIF(SUBSTRING(cse.compte FROM 5 FOR 1), '')
        ),
        ''
      )
    END AS chiffre3,
    NULLIF(SUBSTRING(cse.compte FROM 1 FOR 2), '') AS chiffre2
  FROM public.compta_sous_ecriture AS cse, public.compta_compte AS cc, public.compta_journal AS jrn
  WHERE
    cc.compte = cse.compte
    AND cse.journal = 'COMP000015'
    AND cse.etat = 11
    AND jrn.id = cse.journal
  UNION
  SELECT
    cse.analytique AS analytique,
    cc.libelle AS libelle,
    cse.debit AS debit,
    cse.credit AS credit,
    cc.typecompte AS typecompte,
    EXTRACT(MONTH FROM cse.daty) AS _col_5,
    EXTRACT(YEAR FROM cse.daty) AS _col_6,
    CASE
      WHEN CAST(cc.typecompte AS DECIMAL) = 3
      THEN NULLIF(
        CONCAT(
          NULLIF(SUBSTRING(cse.analytique FROM 1 FOR 3), ''),
          NULLIF(SUBSTRING(cse.analytique FROM 5 FOR 1), '')
        ),
        ''
      )
      ELSE NULLIF(
        CONCAT(
          NULLIF(SUBSTRING(cse.analytique FROM 1 FOR 2), ''),
          NULLIF(SUBSTRING(cse.analytique FROM 5 FOR 1), '')
        ),
        ''
      )
    END AS chiffre3,
    NULLIF(SUBSTRING(cse.analytique FROM 1 FOR 2), '') AS chiffre2
  FROM public.compta_sous_ecriture AS cse, public.compta_compte AS cc, public.compta_journal AS jrn
  WHERE
    cc.compte = cse.analytique
    AND cse.journal = 'COMP000015'
    AND cse.etat = 11
    AND jrn.id = cse.journal
) AS _0
GROUP BY
  _0.compte,
  _0.libelle,
  _0.typecompte,
  _0.mois,
  _0.annee,
  _0.chiffre3,
  _0.chiffre2;

-- Niveau 1 - vue 74 / 129 : RESERVATIONDETAILSMAXDATE
-- Dependances nouvelles : aucune.
CREATE VIEW public.reservationdetailsmaxdate (
    "id", "idmere", "idproduit", "qte", "daty", "pu", "remarque", "etat", "heure", "rn"
) AS
SELECT
  _0.id AS id,
  _0.idmere AS idmere,
  _0.idproduit AS idproduit,
  _0.qte AS qte,
  _0.daty AS daty,
  _0.pu AS pu,
  _0.remarque AS remarque,
  _0.etat AS etat,
  _0.heure AS heure,
  _0.rn AS rn
FROM (
  SELECT
    r.id AS id,
    r.idmere AS idmere,
    r.idproduit AS idproduit,
    r.qte AS qte,
    r.daty AS daty,
    r.pu AS pu,
    r.remarque AS remarque,
    r.etat AS etat,
    r.heure AS heure,
    ROW_NUMBER() OVER (PARTITION BY r.idmere ORDER BY r.daty DESC) AS rn
  FROM public.reservationdetails AS r
) AS _0
WHERE
  _0.rn = 1;

-- Niveau 1 - vue 75 / 129 : RETRAIT_FRAIS_MEDICAUX_ANALYSE
-- Dependances nouvelles : aucune.
CREATE VIEW public.retrait_frais_medicaux_analyse (
    "direction", "directionlib", "mois", "annee", "dateval", "datedesc", "datelib", "gain", "depense"
) AS
SELECT
  ld.id AS direction,
  ld.val AS directionlib,
  pe.mois AS mois,
  pe.annee AS annee,
  CASE
    WHEN pe.mois = 13
    THEN TO_DATE(CAST(NULLIF(CONCAT('01-12-', pe.annee), '') AS TEXT), 'DD-MM-YYYY')
    ELSE TO_DATE(
      CAST(NULLIF(CONCAT('01-', LPAD(CAST(pe.mois AS TEXT), 2, '0'), '-', pe.annee), '') AS TEXT),
      'DD-MM-YYYY'
    )
  END AS dateval,
  NULLIF(CONCAT(pe.annee, '-', LPAD(CAST(pe.mois AS TEXT), 2, '0')), '') AS datedesc,
  NULLIF(
    CONCAT(
      CASE
        WHEN pe.mois = 1
        THEN 'Janvier'
        WHEN pe.mois = 2
        THEN 'Fevrier'
        WHEN pe.mois = 3
        THEN 'Mars'
        WHEN pe.mois = 4
        THEN 'Avril'
        WHEN pe.mois = 5
        THEN 'Mai'
        WHEN pe.mois = 6
        THEN 'Juin'
        WHEN pe.mois = 7
        THEN 'Juillet'
        WHEN pe.mois = 8
        THEN 'Aout'
        WHEN pe.mois = 9
        THEN 'Septembre'
        WHEN pe.mois = 10
        THEN 'Octobre'
        WHEN pe.mois = 11
        THEN 'Novembre'
        WHEN pe.mois = 12
        THEN 'Decembre'
        WHEN pe.mois = 13
        THEN '13 eme'
        ELSE NULL
      END,
      '-',
      pe.annee
    ),
    ''
  ) AS datelib,
  SUM(pe.gain) AS gain,
  COALESCE(SUM(rf.montant), 0) AS depense
FROM public.paie_edition AS pe
LEFT JOIN public.paie_info_personnel_libcomplet AS pf
  ON pf.id = pe.idpersonnel
LEFT JOIN public.log_direction AS ld
  ON ld.id = pf.direction
LEFT JOIN public.retrait_frais_medicaux AS rf
  ON pe.mois = EXTRACT(MONTH FROM rf.daty)
  AND pe.annee = EXTRACT(YEAR FROM rf.daty)
  AND rf.etat >= 11
WHERE
  pe.idelementpaie NOT LIKE '%PR000FRM%'
GROUP BY
  pe.mois,
  pe.annee,
  ld.id,
  ld.val;

-- Niveau 1 - vue 76 / 129 : RISTOURNELIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.ristournelib (
    "id", "designation", "idclient", "daty", "datedebutristourne", "datefinristourne", "idorigine", "etat", "idclientlib", "etatlib", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.designation AS designation,
  sq.idclient AS idclient,
  sq.daty AS daty,
  sq.datedebutristourne AS datedebutristourne,
  sq.datefinristourne AS datefinristourne,
  sq.idorigine AS idorigine,
  sq.etat AS etat,
  sq.idclientlib AS idclientlib,
  sq.etatlib AS etatlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.designation AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idclient AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.datedebutristourne, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.datefinristourne, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(sq.idorigine AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.idclientlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.etatlib AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    r.id AS id,
    r.designation AS designation,
    r.idclient AS idclient,
    r.daty AS daty,
    r.datedebutristourne AS datedebutristourne,
    r.datefinristourne AS datefinristourne,
    r.idorigine AS idorigine,
    r.etat AS etat,
    c.nom AS idclientlib,
    CASE
      WHEN r.etat = 0
      THEN 'ANNUL&Eacute;E'
      WHEN r.etat = 1
      THEN 'CR&Eacute;&Eacute;E'
      WHEN r.etat = 11
      THEN 'VIS&Eacute;E'
    END AS etatlib
  FROM public.ristourne AS r
  LEFT JOIN public.client AS c
    ON r.idclient = c.id
) AS sq;

-- Niveau 1 - vue 77 / 129 : SESSION_FORMATION_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.session_formation_lib (
    "id", "idactionformation", "idactionformationlib", "intitule", "reference", "datedebut", "datefin", "nbheureprevue", "etat", "etatlib", "remarque", "motsclesss"
) AS
SELECT
  sf.id AS id,
  sf.idactionformation AS idactionformation,
  NULLIF(CONCAT(af.reference, ' - ', af.intitule), '') AS idactionformationlib,
  af.intitule AS intitule,
  af.reference AS reference,
  sf.datedebut AS datedebut,
  sf.datefin AS datefin,
  sf.nbheureprevue AS nbheureprevue,
  sf.etat AS etat,
  CASE
    WHEN sf.etat = 1
    THEN 'Cree'
    WHEN sf.etat = 11
    THEN 'Valide'
    WHEN sf.etat = 0
    THEN 'Annule'
    ELSE 'Inconnu'
  END AS etatlib,
  sf.remarque AS remarque,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sf.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sf.idactionformation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(af.reference, ' - ', af.intitule), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(af.intitule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(af.reference AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(sf.datedebut, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(sf.datefin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sf.nbheureprevue
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sf.nbheureprevue
                  ) AS TEXT)))
                  ELSE CAST((
                    sf.nbheureprevue
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sf.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sf.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sf.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        CASE
          WHEN sf.etat = 1
          THEN 'Cree'
          WHEN sf.etat = 11
          THEN 'Valide'
          WHEN sf.etat = 0
          THEN 'Annule'
          ELSE 'Inconnu'
        END,
        ' | ',
        COALESCE(CAST(sf.remarque AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.session_formation AS sf
LEFT JOIN public.action_formation AS af
  ON af.id = sf.idactionformation;

