        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.a_payer
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.a_payer
                  ) AS TEXT)))
                  ELSE CAST((
                    base.a_payer
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.heuresupp30ni
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.heuresupp30ni
                  ) AS TEXT)))
                  ELSE CAST((
                    base.heuresupp30ni
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.heuresupp30i
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.heuresupp30i
                  ) AS TEXT)))
                  ELSE CAST((
                    base.heuresupp30i
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.heuresupp50ni
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.heuresupp50ni
                  ) AS TEXT)))
                  ELSE CAST((
                    base.heuresupp50ni
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.heuresupp50i
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.heuresupp50i
                  ) AS TEXT)))
                  ELSE CAST((
                    base.heuresupp50i
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.majnuit
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.majnuit
                  ) AS TEXT)))
                  ELSE CAST((
                    base.majnuit
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.majferie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.majferie
                  ) AS TEXT)))
                  ELSE CAST((
                    base.majferie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.majweekend
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.majweekend
                  ) AS TEXT)))
                  ELSE CAST((
                    base.majweekend
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.abbatement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.abbatement
                  ) AS TEXT)))
                  ELSE CAST((
                    base.abbatement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.moislib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    se.matricule AS matricule,
    se.nom AS nom,
    NULLIF(
      CONCAT(CAST(se.id AS VARCHAR(4000)), '//', CAST(sa.idedition AS VARCHAR(4000))),
      ''
    ) AS id,
    se.mois AS mois,
    se.annee AS annee,
    se.idedition AS idedition,
    se.salaire AS salaire,
    se.hs_m AS hs_m,
    se.indem AS indem,
    se.ancien AS ancien,
    se.prime AS prime,
    se.autres AS autres,
    se.total AS total,
    se.cnaps AS cnaps,
    se.ostie AS ostie,
    se.irsa_e AS irsa_e,
    se.irsa_s AS irsa_s,
    se.av_spe AS av_spe,
    se.autres2 AS autres2,
    se.a_payer AS a_payer,
    sa.heuresupp30ni AS heuresupp30ni,
    sa.heuresupp30i AS heuresupp30i,
    sa.heuresupp50ni AS heuresupp50ni,
    sa.heuresupp50i AS heuresupp50i,
    sa.majnuit AS majnuit,
    sa.majferie AS majferie,
    sa.majweekend AS majweekend,
    sa.abbatement AS abbatement,
    CASE se.mois
      WHEN 1
      THEN 'Janvier'
      WHEN 2
      THEN 'Fevrier'
      WHEN 3
      THEN 'Mars'
      WHEN 4
      THEN 'Avril'
      WHEN 5
      THEN 'Mai'
      WHEN 6
      THEN 'Juin'
      WHEN 7
      THEN 'Juillet'
      WHEN 8
      THEN 'Aout'
      WHEN 9
      THEN 'Septembre'
      WHEN 10
      THEN 'Octobre'
      WHEN 11
      THEN 'Novembre'
      WHEN 12
      THEN 'Decembre'
      ELSE NULL
    END AS moislib
  FROM public.situation_salaire_edition AS se
  LEFT JOIN (
    SELECT
      pe.idpersonnel,
      pe.idedition,
      pe.mois,
      pe.annee,
      SUM(
        CASE
          WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR0000130' AS TEXT)
          THEN pe.gain
          ELSE CAST(0 AS DECIMAL)
        END
      ) AS heuresupp30ni,
      SUM(
        CASE
          WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR0000130I' AS TEXT)
          THEN pe.gain
          ELSE CAST(0 AS DECIMAL)
        END
      ) AS heuresupp30i,
      SUM(
        CASE
          WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR0000150' AS TEXT)
          THEN pe.gain
          ELSE CAST(0 AS DECIMAL)
        END
      ) AS heuresupp50ni,
      SUM(
        CASE
          WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR0000150I' AS TEXT)
          THEN pe.gain
          ELSE CAST(0 AS DECIMAL)
        END
      ) AS heuresupp50i,
      SUM(
        CASE
          WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR0000221' AS TEXT)
          THEN pe.gain
          ELSE CAST(0 AS DECIMAL)
        END
      ) AS majnuit,
      SUM(
        CASE
          WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR0000222' AS TEXT)
          THEN pe.gain
          ELSE CAST(0 AS DECIMAL)
        END
      ) AS majferie,
      SUM(
        CASE
          WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR0000223' AS TEXT)
          THEN pe.gain
          ELSE CAST(0 AS DECIMAL)
        END
      ) AS majweekend,
      SUM(
        CASE
          WHEN CAST(pe.idelementpaie AS TEXT) = CAST('PR000181' AS TEXT)
          THEN pe.gain
          ELSE CAST(0 AS DECIMAL)
        END
      ) AS abbatement
    FROM public.paie_edition AS pe
    GROUP BY
      pe.idpersonnel,
      pe.idedition,
      pe.mois,
      pe.annee
  ) AS sa
    ON sa.idedition = se.idedition AND sa.idpersonnel = se.id
) AS base;

-- Niveau 1 - vue 79 / 129 : STAT_DEPENSE_CAT
-- Dependances nouvelles : aucune.
CREATE VIEW public.stat_depense_cat (
    "daty", "categorieingredient", "categorieingredientlib", "moisint", "moisstring", "annee", "depense"
) AS
SELECT
  ffc.daty AS daty,
  ai.categorieingredient AS categorieingredient,
  cat.val AS categorieingredientlib,
  EXTRACT(MONTH FROM ffc.daty) AS moisint,
  NULLIF(
    TRIM(
      RPAD(
        (
          ARRAY[
            'Janvier',
            'Février',
            'Mars',
            'Avril',
            'Mai',
            'Juin',
            'Juillet',
            'Août',
            'Septembre',
            'Octobre',
            'Novembre',
            'Décembre'
          ]
        )[CAST(EXTRACT(MONTH FROM ffc.daty) AS INT) + 0],
        9,
        ' '
      )
    ),
    ''
  ) AS moisstring,
  EXTRACT(YEAR FROM ffc.daty) AS annee,
  CAST(CAST(SUM(ffc.montant) AS DECIMAL) / 1000000 AS DECIMAL(30, 2)) AS depense
FROM public.facturefournisseurfillecpl AS ffc
JOIN public.facturefournisseur AS fc
  ON fc.id = ffc.idfacturefournisseur AND fc.etat >= 11
JOIN public.as_ingredients AS ai
  ON ffc.idproduit = ai.id
LEFT JOIN public.categorieingredient AS cat
  ON ai.categorieingredient = cat.id
GROUP BY
  ai.categorieingredient,
  ffc.daty,
  cat.val
ORDER BY
  annee,
  moisint;

-- Niveau 1 - vue 80 / 129 : STAT_DEPENSE_MAT_PREM
-- Dependances nouvelles : aucune.
CREATE VIEW public.stat_depense_mat_prem (
    "annee", "moisint", "mois", "id", "designation", "depense"
) AS
SELECT
  EXTRACT(YEAR FROM f.daty) AS annee,
  EXTRACT(MONTH FROM f.daty) AS moisint,
  RPAD(
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM f.daty) AS INT) + 0],
    9,
    ' '
  ) AS mois,
  ff.idproduit AS id,
  ai.libelle AS designation,
  CAST(COALESCE(SUM(ff.qte * ff.pu), 0) AS DECIMAL(30, 5)) AS depense
FROM public.facturefournisseurfille AS ff
LEFT JOIN public.facturefournisseur AS f
  ON f.id = ff.idfacturefournisseur
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = ff.idproduit
WHERE
  f.etat >= 11
GROUP BY
  ff.idproduit,
  ai.libelle,
  EXTRACT(YEAR FROM f.daty),
  EXTRACT(MONTH FROM f.daty),
  RPAD(
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM f.daty) AS INT) + 0],
    9,
    ' '
  )
ORDER BY
  moisint ASC;

-- Niveau 1 - vue 81 / 129 : TARIF_INGREDIENTS_MAX_DATE_MN
-- Dependances nouvelles : aucune.
CREATE VIEW public.tarif_ingredients_max_date_mn (
    "idingredient", "unite", "idtypeclient", "daty", "idmagasin"
) AS
SELECT
  _0.idingredient AS idingredient,
  _0.unite AS unite,
  _0.idtypeclient AS idtypeclient,
  MAX(_0.daty) AS daty,
  _0.idmagasin AS idmagasin
FROM (
  SELECT
    tarif_ingredients.id AS id,
    tarif_ingredients.idtypeclient AS idtypeclient,
    tarif_ingredients.idingredient AS idingredient,
    tarif_ingredients.daty AS daty,
    tarif_ingredients.prixunitaire AS prixunitaire,
    tarif_ingredients.unite AS unite,
    tarif_ingredients.idmagasin AS idmagasin
  FROM public.tarif_ingredients AS tarif_ingredients
  WHERE
    tarif_ingredients.idmagasin IS NULL
) AS _0
GROUP BY
  _0.idingredient,
  _0.unite,
  _0.idtypeclient,
  _0.idmagasin;

-- Niveau 1 - vue 82 / 129 : TARIF_INGREDIENTS_MAX_DATE_MNN
-- Dependances nouvelles : aucune.
CREATE VIEW public.tarif_ingredients_max_date_mnn (
    "idingredient", "unite", "idtypeclient", "daty", "idmagasin"
) AS
SELECT
  _0.idingredient AS idingredient,
  _0.unite AS unite,
  _0.idtypeclient AS idtypeclient,
  MAX(_0.daty) AS daty,
  _0.idmagasin AS idmagasin
FROM (
  SELECT
    tarif_ingredients.id AS id,
    tarif_ingredients.idtypeclient AS idtypeclient,
    tarif_ingredients.idingredient AS idingredient,
    tarif_ingredients.daty AS daty,
    tarif_ingredients.prixunitaire AS prixunitaire,
    tarif_ingredients.unite AS unite,
    tarif_ingredients.idmagasin AS idmagasin
  FROM public.tarif_ingredients AS tarif_ingredients
  WHERE
    NOT tarif_ingredients.idmagasin IS NULL
) AS _0
GROUP BY
  _0.idingredient,
  _0.unite,
  _0.idtypeclient,
  _0.idmagasin;

-- Niveau 1 - vue 83 / 129 : TEMPSMOYENPANNES
-- Dependances nouvelles : aucune.
CREATE VIEW public.tempsmoyenpannes (
    "idmachine", "nommachine", "idtravaux", "daty", "ecart_jours"
) AS
WITH ecarts AS (
  SELECT
    CASE WHEN ai.id IS NULL THEN aim.id ELSE ai.id END AS idmachine,
    CASE WHEN ai.libelle IS NULL THEN aim.descriptionobjet ELSE ai.libelle END AS nommachine,
    t.id AS idtravaux,
    t.daty AS daty,
    COALESCE(
      (
        EXTRACT(EPOCH FROM (
          t.daty - LAG(t.daty) OVER (PARTITION BY o.idingredients ORDER BY t.daty)
        )) / 86400.0
      ),
      0
    ) AS ecart_jours
  FROM public.travaux AS t
  LEFT JOIN public.ordretravauxfille AS o
    ON t.idoffille = o.id
  LEFT JOIN public.as_ingredients AS ai
    ON o.idingredients = ai.id
  LEFT JOIN public.as_ingredient_maintenance AS aim
    ON o.idingredients = aim.id
)
SELECT
  ecarts.idmachine AS idmachine,
  ecarts.nommachine AS nommachine,
  ecarts.idtravaux AS idtravaux,
  ecarts.daty AS daty,
  ecarts.ecart_jours AS ecart_jours
FROM ecarts AS ecarts;

-- Niveau 1 - vue 84 / 129 : TOUSLESDATE
-- Dependances nouvelles : aucune.
CREATE VIEW public.touslesdate (
    "daty"
) AS
SELECT
  g.daty AS daty
FROM GENERATE_SERIES(CAST('2000-01-01' AS TIMESTAMP), CAST('2030-12-31' AS TIMESTAMP), INTERVAL '1 DAY') AS g(daty);

-- Niveau 1 - vue 85 / 129 : TRAITELIB_GRP
-- Dependances nouvelles : aucune.
CREATE VIEW public.traitelib_grp (
    "idtraite", "code"
) AS
SELECT
  tf.idtraite AS idtraite,
  STRING_AGG(tf.code, ';'
  ORDER BY
    tf.code) AS code
FROM (
  SELECT
    t.idtraite,
    t.idfc AS idfact,
    CAST(t.code AS TEXT) AS code
  FROM (
    SELECT
      fc.id,
      tl.id AS idtraite,
      fc.id AS idfc,
      fc.montantttc AS montantfacture,
      j.credit AS montantjc,
      pf.montant,
      fc.daty,
      fc.etat,
      CAST(NULL AS TEXT) AS code,
      tl.tiers,
      tl.banque,
      fc.designation AS factureclientlib,
      fc.idclientlib AS tierslib,
      CASE
        WHEN j.etat = CAST(1 AS DECIMAL)
        THEN CAST('Cree' AS TEXT)
        WHEN j.etat >= CAST(11 AS DECIMAL)
        THEN CAST('visee' AS TEXT)
        WHEN j.etat = CAST(0 AS DECIMAL)
        THEN CAST('Annulee' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib
    FROM public.liaisonpaiement AS pf
    LEFT JOIN public.mouvementcaisse AS j
      ON CAST(j.id AS TEXT) = CAST(pf.id2 AS TEXT)
    JOIN public.traite AS tl
      ON CAST(tl.id AS TEXT) = CAST(j.idtraite AS TEXT)
    LEFT JOIN (
      SELECT
        v.id,
        v.designation,
        v.idmagasin,
        m.val AS idmagasinlib,
        v.daty,
        v.remarque,
        v.etat,
        CASE
          WHEN v.etat = CAST(1 AS DECIMAL)
          THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
          WHEN v.etat = CAST(11 AS DECIMAL)
          THEN CAST('VIS&Eacute;E' AS TEXT)
          WHEN v.etat = CAST(0 AS DECIMAL)
          THEN CAST('ANNUL&Eacute;E' AS TEXT)
          ELSE CAST(NULL AS TEXT)
        END AS etatlib,
        CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
        v2.iddevise,
        v.idclient,
        c.nom AS idclientlib,
        CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
        CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
        CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
        CAST(COALESCE(mv.montant, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
        CAST((
          COALESCE(v2.montantttc, CAST(0 AS DECIMAL)) - COALESCE(mv.montant, CAST(0 AS DECIMAL)) - COALESCE(acg.montantttcar - acg.montantpayear, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS montantreste,
        CAST(COALESCE(acg.montantttcar, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS avoir,
        CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
        CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
        CAST((
          v2.montantttcar - v2.montantrevient
        ) AS DECIMAL(20, 5)) AS margebrute,
        v.idreservation,
        CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
        rf.reference AS referencefacture,
        CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
        CAST((
          COALESCE(v2.montanttotal, CAST(0 AS DECIMAL)) + COALESCE(v2.montantremise, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS montant,
        EXTRACT(month FROM v.daty) AS mois,
        EXTRACT(year FROM v.daty) AS annee,
        CAST(v2.poids AS DECIMAL(30, 5)) AS poids,
        CAST(v2.colis AS DECIMAL(30, 5)) AS colis,
        v.modepaiement,
        mp.val AS modepaiementlib,
        COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(v2.poids, CAST(0 AS DECIMAL)) AS fraislivraison,
        v.modelivraison,
        CASE
          WHEN v.modelivraison = CAST(1 AS DECIMAL)
          THEN CAST('<span style=color: green;>LIVRAISON</span>' AS TEXT)
          WHEN v.modelivraison = CAST(2 AS DECIMAL)
          THEN CAST('<span style=color: green;>RECUPERATION</span>' AS TEXT)
          ELSE CAST(NULL AS TEXT)
        END AS modelivraisonlib,
        CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
        pv.id AS idprovince,
        pv.val AS provincelib,
        v.idorigine,
        CAST(COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS frais,
        v.referencefact,
        v.numerofacture,
        v.lieulivraison,
        v.datelivraison,
        v.updated_at,
        CASE
          WHEN v.estprevu = CAST(0 AS DECIMAL)
          THEN CAST('Non' AS TEXT)
          ELSE CAST('Oui' AS TEXT)
        END AS estprevulib,
        ce.id AS idecriture,
        COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
        NULLIF(
          CONCAT(
            (
              NULLIF(
                CONCAT(
                  (
                    NULLIF(
                      CONCAT(
                        (
                          NULLIF(
                            CONCAT(
                              (
                                NULLIF(
                                  CONCAT(
                                    (
                                      NULLIF(
                                        CONCAT(
                                          (
                                            NULLIF(
                                              CONCAT(
                                                (
                                                  NULLIF(
                                                    CONCAT(
                                                      (
                                                        NULLIF(
                                                          CONCAT(
                                                            (
                                                              NULLIF(
                                                                CONCAT(
                                                                  (
                                                                    NULLIF(
                                                                      CONCAT((
                                                                        NULLIF(CONCAT(CAST(v.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                                      ), v.daty),
                                                                      ''
                                                                    )
                                                                  ),
                                                                  CAST(NULL AS TEXT)
                                                                ),
                                                                ''
                                                              )
                                                            ),
                                                            CAST(v.idclient AS TEXT)
                                                          ),
                                                          ''
                                                        )
                                                      ),
                                                      CAST(NULL AS TEXT)
                                                    ),
                                                    ''
                                                  )
                                                ),
                                                CAST(c.nom AS TEXT)
                                              ),
                                              ''
                                            )
                                          ),
                                          CAST(NULL AS TEXT)
                                        ),
                                        ''
                                      )
                                    ),
                                    CAST(v.idmagasin AS TEXT)
                                  ),
                                  ''
                                )
                              ),
                              CAST(NULL AS TEXT)
                            ),
                            ''
                          )
                        ),
                        CAST(m.val AS TEXT)
                      ),
                      ''
                    )
                  ),
                  CAST(NULL AS TEXT)
                ),
                ''
              )
            ),
            CAST(v.remarque AS TEXT)
          ),
          ''
        ) AS motsclesss,
        v.heuresaisie,
        v.adeclarer,
        v.factureechange,
        m.id AS idpoint
      FROM public.vente AS v
      LEFT JOIN public.client AS c
        ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
      LEFT JOIN public.point AS m
        ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
      LEFT JOIN public.zone AS pv
        ON CAST(pv.id AS TEXT) = CAST(m.idzone AS TEXT)
      JOIN (
        SELECT
          vd.idvente AS id,
          CAST(SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) AS DECIMAL(30, 2)) AS montanttotal,
          CAST((
            SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))) - SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              )
            )
          ) AS DECIMAL(30, 2)) AS montantremise,
          CAST(SUM(
            COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * COALESCE(vd.qte, CAST(0 AS DECIMAL))
          ) AS DECIMAL(30, 5)) AS frais,
          CAST(SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.puachat, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS montanttotalachat,
          CAST(SUM(
            (
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) AS DECIMAL(30, 2)) AS montanttva,
          CAST((
            SUM(
              (
                (
                  CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                ) * (
                  COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
                ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
              ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
            ) + SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            )
          ) AS DECIMAL(30, 2)) AS montantttc,
          COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
          COALESCE(AVG(vd.tauxdechange), CAST(1 AS DECIMAL)) AS tauxdechange,
          CAST((
            SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL))
              ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
            ) + SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
              ) * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            )
          ) AS DECIMAL(30, 2)) AS montantttcar,
          CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
          v.idreservation,
          COALESCE(SUM(ing.calorie * vd.qte), CAST(0 AS DECIMAL)) AS poids,
          SUM(vd.qte) AS colis
        FROM public.vente_details AS vd
        LEFT JOIN public.vente AS v
          ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
        LEFT JOIN public.as_ingredients AS ing
          ON CAST(ing.id AS TEXT) = CAST(vd.idproduit AS TEXT)
        GROUP BY
          vd.idvente,
          vd.iddevise,
          v.idreservation
      ) AS v2
        ON CAST(v2.id AS TEXT) = CAST(v.id AS TEXT)
      LEFT JOIN public.liaisonpaiementtotal AS mv
        ON CAST(v.id AS TEXT) = CAST(mv.id2 AS TEXT)
      LEFT JOIN (
        SELECT
          a.id,
          a.designation,
          a.idmagasin,
          CAST(NULL AS TEXT) AS idmagasinlib,
          a.daty,
          a.remarque,
          a.etat,
          a.idorigine,
          a.idclient,
          CAST(NULL AS TEXT) AS compte,
          CAST(NULL AS TEXT) AS compteauxiliaire,
          a.idvente,
          CAST(NULL AS TEXT) AS idventelib,
          a.idmotif,
          CAST(NULL AS TEXT) AS idmotiflib,
          a.idcategorie,
          CAST(NULL AS TEXT) AS idcategorielib,
          ag.iddevise,
          ag.tauxdechange,
          ag.montantht,
          ag.montanttva,
          ag.montantttc,
          ag.montanthtar,
          ag.montanttvaar,
          ag.montantttcar,
          CAST(NULL AS TEXT) AS idreservation,
          CAST(NULL AS TEXT) AS typeavoir,
          CAST(NULL AS TEXT) AS clientlib,
          COALESCE(m.montant, CAST(0 AS DECIMAL)) * COALESCE(ag.tauxdechange, CAST(0 AS DECIMAL)) AS montantpayear
        FROM public.avoirfc AS a
        JOIN public.avoirfcfille_grp AS ag
          ON CAST(ag.idavoirfc AS TEXT) = CAST(a.id AS TEXT)
        LEFT JOIN (
          SELECT
            m.id1 AS idorigine,
            SUM(m.montant) AS montant,
            CAST('AR' AS TEXT) AS iddevise
          FROM public.liaisonpaiement AS m
          WHERE
            m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
          GROUP BY
            m.id1
        ) AS m
          ON CAST(a.id AS TEXT) = CAST(m.idorigine AS TEXT)
        WHERE
          a.etat >= CAST(11 AS DECIMAL) AND a.idorigine IS NOT NULL
      ) AS acg
        ON CAST(acg.idvente AS TEXT) = CAST(v.id AS TEXT)
      LEFT JOIN public.referencefacture AS rf
        ON CAST(rf.idfacture AS TEXT) = CAST(v.id AS TEXT)
      LEFT JOIN public.modepaiement AS mp
        ON CAST(mp.id AS TEXT) = CAST(v.modepaiement AS TEXT)
      LEFT JOIN public.vente_reste AS vr
        ON CAST(vr.idvente AS TEXT) = CAST(v.id AS TEXT)
      LEFT JOIN public.as_bondelivraison_client AS blc
        ON CAST(blc.idvente AS TEXT) = CAST(v.id AS TEXT)
      LEFT JOIN public.compta_ecriture AS ce
        ON CAST(ce.idobjet AS TEXT) = CAST(v.id AS TEXT)
    ) AS fc
      ON CAST(pf.id1 AS TEXT) = CAST(fc.id AS TEXT)
  ) AS t
) AS tf
GROUP BY
  tf.idtraite;

-- Niveau 1 - vue 86 / 129 : TRAITE_LIBMTT
-- Dependances nouvelles : aucune.
CREATE VIEW public.traite_libmtt (
    "id", "daty", "tiers", "banque", "dateecheance", "etat", "montant", "escompte", "total", "reference", "cdclt", "idbanque", "idtypepiece", "typepiece"
) AS
SELECT
  t.id AS id,
  t.daty AS daty,
  t.tiers AS tiers,
  t.banque AS banque,
  t.dateecheance AS dateecheance,
  t.etat AS etat,
  t.montant AS montant,
  SUM(COALESCE(e.frais, 0)) AS escompte,
  t.montant - SUM(COALESCE(e.frais, 0)) AS total,
  t.reference AS reference,
  t.cdclt AS cdclt,
  t.idbanque AS idbanque,
  t.idtypepiece AS idtypepiece,
  t.typepiece AS typepiece
FROM (
  SELECT
    tr.id,
    tr.daty,
    ti.nom AS tiers,
    ba.val AS banque,
    tr.dateecheance,
    tr.etat,
    tr.montant,
    tr.reference,
    CAST(NULL AS TEXT) AS cdclt,
    ba.id AS idbanque,
    tr.idtypepiece,
    tp.val AS typepiece
  FROM public.traite AS tr
  LEFT JOIN public.client AS ti
    ON CAST(tr.tiers AS TEXT) = CAST(ti.id AS TEXT)
  LEFT JOIN public.banque AS ba
    ON CAST(tr.banque AS TEXT) = CAST(ba.id AS TEXT)
  LEFT JOIN public.type_piece AS tp
    ON CAST(tp.id AS TEXT) = CAST(tr.idtypepiece AS TEXT)
) AS t
LEFT JOIN public.escompte_libv AS e
  ON e.idtraite = t.id
GROUP BY
  t.id,
  t.daty,
  t.tiers,
  t.banque,
  t.dateecheance,
  t.etat,
  t.montant,
  t.reference,
  t.cdclt,
  t.idbanque,
  t.idtypepiece,
  t.typepiece;

-- Niveau 1 - vue 87 / 129 : TRANSFERTSTOCKCPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.transfertstockcpl (
    "id", "designation", "idmagasindepart", "idmagasindepartlib", "idmagasinarrive", "idmagasinarrivelib", "daty", "etat", "idof", "etatlib", "motsclesss", "montantquantite"
) AS
SELECT
  t.id AS id,
  t.designation AS designation,
  t.idmagasindepart AS idmagasindepart,
  m.val AS idmagasindepartlib,
  t.idmagasinarrive AS idmagasinarrive,
  m2.val AS idmagasinarrivelib,
  t.daty AS daty,
  t.etat AS etat,
  t.idof AS idof,
  CASE
    WHEN t.etat = 0
    THEN 'ANNUL&Eacute;'
    WHEN t.etat = 1
    THEN 'CR&Eacute&Eacute;'
    WHEN t.etat = 11
    THEN 'VIS&Eacute;'
    ELSE NULL
  END AS etatlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(t.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(t.designation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(t.idmagasindepart AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(m.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(t.idmagasinarrive AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(m2.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(t.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    t.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    t.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    t.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(t.idof AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          CASE
            WHEN t.etat = 0
            THEN 'ANNUL&Eacute;'
            WHEN t.etat = 1
            THEN 'CR&Eacute&Eacute;'
            WHEN t.etat = 11
            THEN 'VIS&Eacute;'
            ELSE NULL
          END,
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss,
  tfdgm.montantquantite AS montantquantite
FROM public.transfertstock AS t
LEFT JOIN public.magasinpoint AS m
  ON m.id = t.idmagasindepart
LEFT JOIN public.magasinpoint AS m2
  ON m2.id = t.idmagasinarrive
LEFT JOIN public.transtockdetailsgroupemere AS tfdgm
  ON tfdgm.idtransfertstock = t.id;

-- Niveau 1 - vue 88 / 129 : UNITE_VENTE
