-- Niveau 1 - vue 89 / 129 : UTILISATEURROLE
-- Dependances nouvelles : aucune.
CREATE VIEW public.utilisateurrole (
    "refuser", "loginuser", "pwduser", "nomuser", "adruser", "teluser", "idrole", "id", "rang"
) AS
SELECT
  u.refuser AS refuser,
  u.loginuser AS loginuser,
  u.pwduser AS pwduser,
  u.nomuser AS nomuser,
  d.id AS adruser,
  u.teluser AS teluser,
  u.idrole AS idrole,
  s.id AS id,
  r.rang AS rang
FROM public.utilisateur AS u
LEFT JOIN public.annulationutilisateur AS a
  ON u.refuser = a.refuser
CROSS JOIN public.log_direction AS d
CROSS JOIN public.roles AS r
CROSS JOIN public.log_service AS s
CROSS JOIN public.log_personnel AS p
WHERE
  u.teluser = p.id
  AND p.direction = d.id
  AND p.service = s.id
  AND u.idrole = r.idrole
  AND a.refuser IS NULL;

-- Niveau 1 - vue 90 / 129 : UTILISATEURVALIDE
-- Dependances nouvelles : aucune.
CREATE VIEW public.utilisateurvalide (
    "refuser", "loginuser", "pwduser", "nomuser", "adruser", "teluser", "idrole", "rang"
) AS
SELECT
  u.refuser AS refuser,
  u.loginuser AS loginuser,
  u.pwduser AS pwduser,
  u.nomuser AS nomuser,
  u.adruser AS adruser,
  u.teluser AS teluser,
  u.idrole AS idrole,
  r.rang AS rang
FROM public.utilisateur AS u
LEFT JOIN public.annulationutilisateur AS a
  ON u.refuser = a.refuser
CROSS JOIN public.roles AS r
WHERE
  u.idrole = r.idrole AND a.refuser IS NULL;

-- Niveau 1 - vue 91 / 129 : V1_OSTIE_AFFICHE_T1
-- Dependances nouvelles : aucune.
CREATE VIEW public.v1_ostie_affiche_t1 (
    "numero", "matricule", "nom", "prenoms", "sexe", "date_naissance", "dateembauche", "date_depart", "fonction", "cnaps", "cin", "mois1", "mois2", "mois3", "salaires_non_plafonnes", "salaires_plafonnes", "employeur", "travailleur", "total", "annee", "direction", "motsclesss"
) AS
SELECT
  base.numero AS numero,
  base.matricule AS matricule,
  base.nom AS nom,
  base.prenoms AS prenoms,
  base.sexe AS sexe,
  base.date_naissance AS date_naissance,
  base.dateembauche AS dateembauche,
  base.date_depart AS date_depart,
  base.fonction AS fonction,
  base.cnaps AS cnaps,
  base.cin AS cin,
  base.mois1 AS mois1,
  base.mois2 AS mois2,
  base.mois3 AS mois3,
  base.salaires_non_plafonnes AS salaires_non_plafonnes,
  base.salaires_plafonnes AS salaires_plafonnes,
  base.employeur AS employeur,
  base.travailleur AS travailleur,
  base.total AS total,
  base.annee AS annee,
  base.direction AS direction,
  (
    NULLIF(
      CONCAT(
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.numero
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.numero
                  ) AS TEXT)))
                  ELSE CAST((
                    base.numero
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.nom AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.prenoms AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.sexe AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.date_naissance, 'YYYY-MM-DD'), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.dateembauche, 'YYYY-MM-DD'), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.date_depart, 'YYYY-MM-DD'), NULL),
        ' | ',
        COALESCE(CAST(base.fonction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.cnaps AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.cin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.mois1
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.mois1
                  ) AS TEXT)))
                  ELSE CAST((
                    base.mois1
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.mois2
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.mois2
                  ) AS TEXT)))
                  ELSE CAST((
                    base.mois2
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.mois3
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.mois3
                  ) AS TEXT)))
                  ELSE CAST((
                    base.mois3
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.salaires_non_plafonnes
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.salaires_non_plafonnes
                  ) AS TEXT)))
                  ELSE CAST((
                    base.salaires_non_plafonnes
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.salaires_plafonnes
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.salaires_plafonnes
                  ) AS TEXT)))
                  ELSE CAST((
                    base.salaires_plafonnes
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.employeur
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.employeur
                  ) AS TEXT)))
                  ELSE CAST((
                    base.employeur
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.travailleur
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.travailleur
                  ) AS TEXT)))
                  ELSE CAST((
                    base.travailleur
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.total
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.total
                  ) AS TEXT)))
                  ELSE CAST((
                    base.total
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.direction AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    ROW_NUMBER() OVER () AS numero,
    LPAD(CAST(pip.matricule AS TEXT), 5, '0') AS matricule,
    UPPER(NULLIF(TRIM(TRAILING ' ' FROM lp.nom), '')) AS nom,
    UPPER(NULLIF(TRIM(TRAILING ' ' FROM lp.prenom), '')) AS prenoms,
    sexe.val AS sexe,
    lp.date_naissance AS date_naissance,
    pip.dateembauche AS dateembauche,
    CASE
      WHEN EXTRACT(YEAR FROM pip.date_depart) = COALESCE(s3.annee, COALESCE(s2.annee, COALESCE(s1.annee, 0)))
      AND EXTRACT(MONTH FROM pip.date_depart) IN (1, 2, 3)
      THEN pip.date_depart
      ELSE NULL
    END AS date_depart,
    UPPER(paf.desce) AS fonction,
    UPPER(pip.numero_cnaps) AS cnaps,
    lp.numero_cin AS cin,
    COALESCE(s1.salairebase, 0) AS mois1,
    COALESCE(s2.salairebase, 0) AS mois2,
    COALESCE(s3.salairebase, 0) AS mois3,
    COALESCE(s1.salairebase, 0) + COALESCE(s2.salairebase, 0) + COALESCE(s3.salairebase, 0) AS salaires_non_plafonnes,
    (
      CASE
        WHEN COALESCE(s1.salairebase, 0) >= (
          SELECT
            CAST(configuration.valmin AS DECIMAL) AS valmin
          FROM public.configuration AS configuration
          WHERE
            configuration.id = 'CONF000140'
        )
        THEN (
          SELECT
            CAST(configuration.valmin AS DECIMAL) AS valmin
          FROM public.configuration AS configuration
          WHERE
            configuration.id = 'CONF000140'
        )
        ELSE COALESCE(s1.salairebase, 0)
      END
    ) + (
      CASE
        WHEN COALESCE(s2.salairebase, 0) >= (
          SELECT
            CAST(configuration.valmin AS DECIMAL) AS valmin
          FROM public.configuration AS configuration
          WHERE
            configuration.id = 'CONF000140'
        )
        THEN (
          SELECT
            CAST(configuration.valmin AS DECIMAL) AS valmin
          FROM public.configuration AS configuration
          WHERE
            configuration.id = 'CONF000140'
        )
        ELSE COALESCE(s2.salairebase, 0)
      END
    ) + (
      CASE
        WHEN COALESCE(s3.salairebase, 0) >= (
          SELECT
            CAST(configuration.valmin AS DECIMAL) AS valmin
          FROM public.configuration AS configuration
          WHERE
            configuration.id = 'CONF000140'
        )
        THEN (
          SELECT
            CAST(configuration.valmin AS DECIMAL) AS valmin
          FROM public.configuration AS configuration
          WHERE
            configuration.id = 'CONF000140'
        )
        ELSE COALESCE(s3.salairebase, 0)
      END
    ) AS salaires_plafonnes,
    COALESCE(ostie.retenue, 0) * 5 AS employeur,
    COALESCE(ostie.retenue, 0) AS travailleur,
    COALESCE(ostie.retenue, 0) * 5 + COALESCE(ostie.retenue, 0) AS total,
    ostie.annee AS annee,
    ostie.direction AS direction
  FROM public.log_personnel AS lp
  JOIN public.paie_info_personnel AS pip
    ON pip.id = lp.id
  JOIN public.log_direction AS ld
    ON ld.id = lp.direction
  JOIN public.paie_fonction AS paf
    ON paf.id = pip.idfonction
  JOIN public.sexe AS sexe
    ON sexe.id = lp.sexe
  LEFT JOIN (
    SELECT
      SUM(ROUND(CAST(pe.retenue AS DECIMAL), 0)) AS retenue,
      pe.idpersonnel AS idpersonnel,
      pe.annee AS annee,
      pe.direction AS direction
    FROM public.paie_edition AS pe
    WHERE
      pe.mois IN (1, 2, 3) AND pe.etat = 11 AND pe.idelementpaie = 'PRU000I710'
    GROUP BY
      pe.idpersonnel,
      pe.annee,
      pe.direction
  ) AS ostie
    ON ostie.idpersonnel = lp.id
  LEFT JOIN (
    SELECT
      sbm.idpersonnel AS idpersonnel,
      sbm.mois AS mois,
      sbm.annee AS annee,
      sbm.salairebase AS salairebase
    FROM (
      SELECT
        paie_edition.idpersonnel,
        paie_edition.mois,
        paie_edition.annee,
        ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
      FROM public.paie_edition
      WHERE
        (
          CAST(paie_edition.idelementpaie AS TEXT) IN (
            SELECT
              pr.id
            FROM public.paie_rubrique AS pr
            WHERE
              CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
              AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
          )
        )
      GROUP BY
        paie_edition.idpersonnel,
        paie_edition.mois,
        paie_edition.annee
    ) AS sbm
    WHERE
      sbm.mois = 1
  ) AS s1
    ON s1.idpersonnel = lp.id AND s1.annee = ostie.annee
  LEFT JOIN (
    SELECT
      sbm.idpersonnel AS idpersonnel,
      sbm.mois AS mois,
      sbm.annee AS annee,
      sbm.salairebase AS salairebase
    FROM (
      SELECT
        paie_edition.idpersonnel,
        paie_edition.mois,
        paie_edition.annee,
        ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
      FROM public.paie_edition
      WHERE
        (
          CAST(paie_edition.idelementpaie AS TEXT) IN (
            SELECT
              pr.id
            FROM public.paie_rubrique AS pr
            WHERE
              CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
              AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
          )
        )
      GROUP BY
        paie_edition.idpersonnel,
        paie_edition.mois,
        paie_edition.annee
    ) AS sbm
    WHERE
      sbm.mois = 2
  ) AS s2
    ON s2.idpersonnel = lp.id AND s2.annee = ostie.annee
  LEFT JOIN (
    SELECT
      sbm.idpersonnel AS idpersonnel,
      sbm.mois AS mois,
      sbm.annee AS annee,
      sbm.salairebase AS salairebase
    FROM (
      SELECT
        paie_edition.idpersonnel,
        paie_edition.mois,
        paie_edition.annee,
        ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
      FROM public.paie_edition
      WHERE
        (
          CAST(paie_edition.idelementpaie AS TEXT) IN (
            SELECT
              pr.id
            FROM public.paie_rubrique AS pr
            WHERE
              CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
              AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
          )
        )
      GROUP BY
        paie_edition.idpersonnel,
        paie_edition.mois,
        paie_edition.annee
    ) AS sbm
    WHERE
      sbm.mois = 3
  ) AS s3
    ON s3.idpersonnel = lp.id AND s3.annee = ostie.annee
  WHERE
    COALESCE(ostie.retenue, 0) <> 0
) AS base
ORDER BY
  base.annee,
  base.matricule;

-- Niveau 1 - vue 92 / 129 : V1_OSTIE_AFFICHE_T2
-- Dependances nouvelles : aucune.
CREATE VIEW public.v1_ostie_affiche_t2 (
    "numero", "matricule", "nom", "prenoms", "sexe", "date_naissance", "dateembauche", "date_depart", "fonction", "cnaps", "cin", "mois1", "mois2", "mois3", "salaires_non_plafonnes", "salaires_plafonnes", "employeur", "travailleur", "total", "annee", "direction"
) AS
SELECT
  ROW_NUMBER() OVER () AS numero,
  LPAD(CAST(pip.matricule AS TEXT), 5, '0') AS matricule,
  UPPER(NULLIF(TRIM(TRAILING ' ' FROM lp.nom), '')) AS nom,
  UPPER(NULLIF(TRIM(TRAILING ' ' FROM lp.prenom), '')) AS prenoms,
  sexe.val AS sexe,
  lp.date_naissance AS date_naissance,
  pip.dateembauche AS dateembauche,
  CASE
    WHEN EXTRACT(YEAR FROM pip.date_depart) = COALESCE(s3.annee, COALESCE(s2.annee, COALESCE(s1.annee, 0)))
    AND (
      EXTRACT(MONTH FROM pip.date_depart) = 4
      OR EXTRACT(MONTH FROM pip.date_depart) = 5
      OR EXTRACT(MONTH FROM pip.date_depart) = 6
    )
    THEN pip.date_depart
    ELSE NULL
  END AS date_depart,
  UPPER(paf.desce) AS fonction,
  UPPER(pip.numero_cnaps) AS cnaps,
  lp.numero_cin AS cin,
  COALESCE(s1.salairebase, 0) AS mois1,
  COALESCE(s2.salairebase, 0) AS mois2,
  COALESCE(s3.salairebase, 0) AS mois3,
  (
    COALESCE(s1.salairebase, 0) + COALESCE(s2.salairebase, 0) + COALESCE(s3.salairebase, 0)
  ) AS salaires_non_plafonnes,
  (
    CASE
      WHEN COALESCE(s1.salairebase, 0) >= (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      THEN (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      ELSE COALESCE(s1.salairebase, 0)
    END
  ) + (
    CASE
      WHEN COALESCE(s2.salairebase, 0) >= (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      THEN (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      ELSE COALESCE(s2.salairebase, 0)
    END
  ) + (
    CASE
      WHEN COALESCE(s3.salairebase, 0) >= (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      THEN (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      ELSE COALESCE(s3.salairebase, 0)
    END
  ) AS salaires_plafonnes,
  COALESCE(ostie.retenue, 0) * 5 AS employeur,
  COALESCE(ostie.retenue, 0) AS travailleur,
  (
    COALESCE(ostie.retenue, 0) * 5
  ) + COALESCE(ostie.retenue, 0) AS total,
  ostie.annee AS annee,
  ostie.direction AS direction
FROM public.log_personnel AS lp
JOIN public.paie_info_personnel AS pip
  ON pip.id = lp.id
JOIN public.log_direction AS ld
  ON ld.id = lp.direction
JOIN public.paie_fonction AS paf
  ON paf.id = pip.idfonction
JOIN public.sexe AS sexe
  ON sexe.id = lp.sexe
LEFT JOIN (
  SELECT
    SUM(ROUND(CAST(paie_edition.retenue AS DECIMAL), 0)) AS retenue,
    paie_edition.idpersonnel AS idpersonnel,
    paie_edition.annee AS annee,
    paie_edition.direction AS direction
  FROM public.paie_edition AS paie_edition
  WHERE
    (
      paie_edition.mois = 4 OR paie_edition.mois = 5 OR paie_edition.mois = 6
    )
    AND paie_edition.etat = 11
    AND paie_edition.idelementpaie = 'PRU000I710'
  GROUP BY
    paie_edition.idpersonnel,
    paie_edition.annee,
    paie_edition.direction
) AS ostie
  ON ostie.idpersonnel = lp.id
LEFT JOIN (
  SELECT
    salairebasemois.idpersonnel AS idpersonnel,
    salairebasemois.mois AS mois,
    salairebasemois.annee AS annee,
    salairebasemois.salairebase AS salairebase
  FROM (
    SELECT
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee,
      ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
    FROM public.paie_edition
    WHERE
      (
        CAST(paie_edition.idelementpaie AS TEXT) IN (
          SELECT
            pr.id
          FROM public.paie_rubrique AS pr
          WHERE
            CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
            AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
        )
      )
    GROUP BY
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee
  ) AS salairebasemois
  WHERE
    salairebasemois.mois = 4
) AS s1
  ON lp.id = s1.idpersonnel AND ostie.annee = s1.annee
LEFT JOIN (
  SELECT
    salairebasemois.idpersonnel AS idpersonnel,
    salairebasemois.mois AS mois,
    salairebasemois.annee AS annee,
    salairebasemois.salairebase AS salairebase
  FROM (
    SELECT
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee,
      ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
    FROM public.paie_edition
    WHERE
      (
        CAST(paie_edition.idelementpaie AS TEXT) IN (
          SELECT
            pr.id
          FROM public.paie_rubrique AS pr
          WHERE
            CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
            AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
        )
      )
    GROUP BY
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee
  ) AS salairebasemois
  WHERE
    salairebasemois.mois = 5
) AS s2
  ON lp.id = s2.idpersonnel AND ostie.annee = s2.annee
LEFT JOIN (
  SELECT
    salairebasemois.idpersonnel AS idpersonnel,
    salairebasemois.mois AS mois,
    salairebasemois.annee AS annee,
    salairebasemois.salairebase AS salairebase
  FROM (
    SELECT
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee,
      ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
    FROM public.paie_edition
    WHERE
      (
        CAST(paie_edition.idelementpaie AS TEXT) IN (
          SELECT
            pr.id
          FROM public.paie_rubrique AS pr
          WHERE
            CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
            AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
        )
      )
    GROUP BY
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee
  ) AS salairebasemois
  WHERE
    salairebasemois.mois = 6
) AS s3
  ON lp.id = s3.idpersonnel AND ostie.annee = s3.annee
WHERE
  COALESCE(ostie.retenue, 0) <> 0
ORDER BY
  annee,
  pip.matricule;

