  COALESCE(s1.salairebase, 0) AS mois1,
  COALESCE(s2.salairebase, 0) AS mois2,
  COALESCE(s3.salairebase, 0) AS mois3,
  (
    COALESCE(s1.salairebase, 0) + COALESCE(s2.salairebase, 0) + COALESCE(s3.salairebase, 0)
  ) AS salaires_non_plafonnes,
  (
    CASE
      WHEN COALESCE(s1.salairebase, 0) >= (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      THEN (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      ELSE COALESCE(s1.salairebase, 0)
    END
  ) + (
    CASE
      WHEN COALESCE(s2.salairebase, 0) >= (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      THEN (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      ELSE COALESCE(s2.salairebase, 0)
    END
  ) + (
    CASE
      WHEN COALESCE(s3.salairebase, 0) >= (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      THEN (
        SELECT
          CAST(configuration.valmin AS DECIMAL) AS maximum
        FROM public.configuration AS configuration
        WHERE
          configuration.id = 'CONF000140'
      )
      ELSE COALESCE(s3.salairebase, 0)
    END
  ) AS salaires_plafonnes,
  COALESCE(ostie.retenue, 0) * 5 AS employeur,
  COALESCE(ostie.retenue, 0) AS travailleur,
  (
    COALESCE(ostie.retenue, 0) * 5
  ) + COALESCE(ostie.retenue, 0) AS total,
  ostie.annee AS annee,
  ostie.direction AS direction
FROM public.log_personnel AS lp
JOIN public.paie_info_personnel AS pip
  ON pip.id = lp.id
JOIN public.log_direction AS ld
  ON ld.id = lp.direction
JOIN public.paie_fonction AS paf
  ON paf.id = pip.idfonction
JOIN public.sexe AS sexe
  ON sexe.id = lp.sexe
LEFT JOIN (
  SELECT
    SUM(ROUND(CAST(paie_edition.retenue AS DECIMAL), 0)) AS retenue,
    paie_edition.idpersonnel AS idpersonnel,
    paie_edition.annee AS annee,
    paie_edition.direction AS direction
  FROM public.paie_edition AS paie_edition
  WHERE
    (
      paie_edition.mois = 10 OR paie_edition.mois = 11 OR paie_edition.mois = 12
    )
    AND paie_edition.etat = 11
    AND paie_edition.idelementpaie = 'PRU000I710'
  GROUP BY
    paie_edition.idpersonnel,
    paie_edition.annee,
    paie_edition.direction
) AS ostie
  ON ostie.idpersonnel = lp.id
LEFT JOIN (
  SELECT
    salairebasemois.idpersonnel AS idpersonnel,
    salairebasemois.mois AS mois,
    salairebasemois.annee AS annee,
    salairebasemois.salairebase AS salairebase
  FROM (
    SELECT
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee,
      ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
    FROM public.paie_edition
    WHERE
      (
        CAST(paie_edition.idelementpaie AS TEXT) IN (
          SELECT
            pr.id
          FROM public.paie_rubrique AS pr
          WHERE
            CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
            AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
        )
      )
    GROUP BY
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee
  ) AS salairebasemois
  WHERE
    salairebasemois.mois = 10
) AS s1
  ON lp.id = s1.idpersonnel AND ostie.annee = s1.annee
LEFT JOIN (
  SELECT
    salairebasemois.idpersonnel AS idpersonnel,
    salairebasemois.mois AS mois,
    salairebasemois.annee AS annee,
    salairebasemois.salairebase AS salairebase
  FROM (
    SELECT
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee,
      ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
    FROM public.paie_edition
    WHERE
      (
        CAST(paie_edition.idelementpaie AS TEXT) IN (
          SELECT
            pr.id
          FROM public.paie_rubrique AS pr
          WHERE
            CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
            AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
        )
      )
    GROUP BY
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee
  ) AS salairebasemois
  WHERE
    salairebasemois.mois = 11
) AS s2
  ON lp.id = s2.idpersonnel AND ostie.annee = s2.annee
LEFT JOIN (
  SELECT
    salairebasemois.idpersonnel AS idpersonnel,
    salairebasemois.mois AS mois,
    salairebasemois.annee AS annee,
    salairebasemois.salairebase AS salairebase
  FROM (
    SELECT
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee,
      ROUND(CAST(SUM(paie_edition.gain) AS DECIMAL), 0) AS salairebase
    FROM public.paie_edition
    WHERE
      (
        CAST(paie_edition.idelementpaie AS TEXT) IN (
          SELECT
            pr.id
          FROM public.paie_rubrique AS pr
          WHERE
            CAST(pr.typerubrique AS TEXT) = CAST('G' AS TEXT)
            AND CAST(pr.imposable AS TEXT) = CAST('I' AS TEXT)
        )
      )
    GROUP BY
      paie_edition.idpersonnel,
      paie_edition.mois,
      paie_edition.annee
  ) AS salairebasemois
  WHERE
    salairebasemois.mois = 12
) AS s3
  ON lp.id = s3.idpersonnel AND ostie.annee = s3.annee
WHERE
  COALESCE(ostie.retenue, 0) <> 0
ORDER BY
  annee,
  pip.matricule;

-- Niveau 1 - vue 95 / 129 : VALIDATION_ROLE_LIB_CPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.validation_role_lib_cpl (
    "id", "refobject", "mapping", "niveau", "role", "personne", "valeuretat", "nomuser", "descrole"
) AS
SELECT
  vr.id AS id,
  vr.refobject AS refobject,
  vr.mapping AS mapping,
  vr.niveau AS niveau,
  vr.role AS role,
  vr.personne AS personne,
  vr.valeuretat AS valeuretat,
  u.nomuser AS nomuser,
  r.descrole AS descrole
FROM public.validation_role AS vr
LEFT JOIN public.utilisateur AS u
  ON u.refuser = CAST(vr.personne AS DECIMAL)
LEFT JOIN public.roles AS r
  ON r.idrole = vr.role;

-- Niveau 1 - vue 96 / 129 : VENTE_DETAILS_CPL1
-- Dependances nouvelles : aucune.
CREATE VIEW public.vente_details_cpl1 (
    "id", "idvente", "idventelib", "idproduit", "idproduitlib", "idorigine", "qte", "pu", "montantremise", "montant", "iddevise", "tauxdechange", "tva", "idclient", "idclientlib", "designation", "purevient", "montantrevient", "idunitelib", "putotal", "magasin", "reference", "daty", "ristourne", "idmodelelib", "idcategoriemodele", "idcategorie", "idmodele"
) AS
SELECT
  x.id AS id,
  x.idvente AS idvente,
  x.idventelib AS idventelib,
  x.idproduit AS idproduit,
  x.idproduitlib AS idproduitlib,
  x.idorigine AS idorigine,
  x.qte AS qte,
  x.pu AS pu,
  x.montantremise AS montantremise,
  x.montant AS montant,
  x.iddevise AS iddevise,
  x.tauxdechange AS tauxdechange,
  x.tva AS tva,
  x.idclient AS idclient,
  x.idclientlib AS idclientlib,
  x.designation AS designation,
  x.purevient AS purevient,
  x.montantrevient AS montantrevient,
  x.idunitelib AS idunitelib,
  CAST(x.qte * x.pu AS DECIMAL(30, 2)) AS putotal,
  x.magasin AS magasin,
  x.reference AS reference,
  x.daty AS daty,
  x.ristourne AS ristourne,
  x.idmodelelib AS idmodelelib,
  x.idcategoriemodele AS idcategoriemodele,
  x.idcategorie AS idcategorie,
  x.idmodele AS idmodele
FROM (
  SELECT
    vd.id AS id,
    vd.idvente AS idvente,
    v.designation AS idventelib,
    vd.idproduit AS idproduit,
    p.libelle AS idproduitlib,
    v.idorigine AS idorigine,
    vd.qte AS qte,
    vd.pu AS pu,
    CASE
      WHEN NOT vd.remisemontant IS NULL AND vd.remisemontant > 0
      THEN COALESCE(vd.remisemontant, 0)
      ELSE CAST((
        COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
      ) * COALESCE((
        vd.qte * vd.pu
      ), 0) AS DECIMAL(30, 2))
    END AS montantremise,
    CASE
      WHEN NOT vd.remisemontant IS NULL AND vd.remisemontant > 0
      THEN (
        vd.qte * vd.pu
      ) - vd.remisemontant
      ELSE CAST((
        1 - COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
      ) * (
        vd.qte * vd.pu
      ) AS DECIMAL(30, 2))
    END AS montant,
    vd.iddevise AS iddevise,
    vd.tauxdechange AS tauxdechange,
    vd.tva AS tva,
    v.idclient AS idclient,
    v.idclientlib AS idclientlib,
    p.libelle AS designation,
    vd.purevient AS purevient,
    CAST(vd.qte * vd.purevient AS DECIMAL(20, 2)) AS montantrevient,
    au.val AS idunitelib,
    pt.val AS magasin,
    p.reference AS reference,
    v.daty AS daty,
    vd.ristourne AS ristourne,
    p.idmodele AS idmodele,
    modele.libelle AS idmodelelib,
    modele.idcategorie AS idcategorie,
    categ.val AS idcategoriemodele
  FROM public.vente_details AS vd
  LEFT JOIN (
    SELECT
      v.idorigine,
      v.id,
      v.designation,
      v.idmagasin,
      m.val AS idmagasinlib,
      v.daty,
      v.remarque,
      v.etat,
      CASE
        WHEN v.etat = CAST(1 AS DECIMAL)
        THEN CAST('CREE' AS TEXT)
        WHEN v.etat = CAST(11 AS DECIMAL)
        THEN CAST('VALIDEE' AS TEXT)
        WHEN v.etat = CAST(0 AS DECIMAL)
        THEN CAST('ANNULEE' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib,
      v.idclient,
      c.nom AS idclientlib
    FROM public.vente AS v
    LEFT JOIN (
      SELECT
        p.id,
        p.val,
        p.desce,
        p.id AS idpoint,
        CAST('-' AS TEXT) AS idproduit,
        CAST(NULL AS TEXT) AS idtypemagasin,
        11 AS etat
      FROM public.point AS p
    ) AS m
      ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
    LEFT JOIN public.client AS c
      ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
  ) AS v
    ON v.id = vd.idvente
  LEFT JOIN public.as_ingredients AS p
    ON p.id = vd.idproduit
  LEFT JOIN public.as_unite AS au
    ON au.id = p.unite
  LEFT JOIN public.point AS pt
    ON pt.id = v.idmagasin
  LEFT JOIN public.modele AS modele
    ON modele.id = p.idmodele
  LEFT JOIN public.categoriemodele AS categ
    ON categ.id = modele.idcategorie
) AS x;

-- Niveau 1 - vue 97 / 129 : VENTE_EDITEES
-- Dependances nouvelles : aucune.
CREATE VIEW public.vente_editees (
    "id", "daty", "idristourne"
) AS
SELECT
  v.id,
  v.daty,
  r.id AS idristourne
FROM (
  SELECT
    v.id,
    v.designation,
    v.idmagasin,
    m.val AS idmagasinlib,
    v.daty,
    v.remarque,
    v.etat,
    CASE
      WHEN v.etat = CAST(1 AS DECIMAL)
      THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
      WHEN v.etat = CAST(11 AS DECIMAL)
      THEN CAST('VIS&Eacute;E' AS TEXT)
      WHEN v.etat = CAST(0 AS DECIMAL)
      THEN CAST('ANNUL&Eacute;E' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS etatlib,
    CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
    v2.iddevise,
    v.idclient,
    c.nom AS idclientlib,
    CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
    CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
    CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
    CAST(COALESCE(mv.montant, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
    CAST((
      COALESCE(v2.montantttc, CAST(0 AS DECIMAL)) - COALESCE(mv.montant, CAST(0 AS DECIMAL)) - COALESCE(acg.montantttcar - acg.montantpayear, CAST(0 AS DECIMAL))
    ) AS DECIMAL(30, 5)) AS montantreste,
    CAST(COALESCE(acg.montantttcar, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS avoir,
    CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
    CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
    CAST((
      v2.montantttcar - v2.montantrevient
    ) AS DECIMAL(20, 5)) AS margebrute,
    v.idreservation,
    CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
    rf.reference AS referencefacture,
    CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
    CAST((
      COALESCE(v2.montanttotal, CAST(0 AS DECIMAL)) + COALESCE(v2.montantremise, CAST(0 AS DECIMAL))
    ) AS DECIMAL(30, 5)) AS montant,
    EXTRACT(month FROM v.daty) AS mois,
    EXTRACT(year FROM v.daty) AS annee,
    CAST(v2.poids AS DECIMAL(30, 5)) AS poids,
    CAST(v2.colis AS DECIMAL(30, 5)) AS colis,
    v.modepaiement,
    mp.val AS modepaiementlib,
    COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(v2.poids, CAST(0 AS DECIMAL)) AS fraislivraison,
    v.modelivraison,
    CASE
      WHEN v.modelivraison = CAST(1 AS DECIMAL)
      THEN CAST('<span style=color: green;>LIVRAISON</span>' AS TEXT)
      WHEN v.modelivraison = CAST(2 AS DECIMAL)
      THEN CAST('<span style=color: green;>RECUPERATION</span>' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS modelivraisonlib,
    CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
    pv.id AS idprovince,
    pv.val AS provincelib,
    v.idorigine,
    CAST(COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS frais,
    v.referencefact,
    v.numerofacture,
    v.lieulivraison,
    v.datelivraison,
    v.updated_at,
    CASE
      WHEN v.estprevu = CAST(0 AS DECIMAL)
      THEN CAST('Non' AS TEXT)
      ELSE CAST('Oui' AS TEXT)
    END AS estprevulib,
    ce.id AS idecriture,
    COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
    NULLIF(
      CONCAT(
        (
          NULLIF(
            CONCAT(
              (
                NULLIF(
                  CONCAT(
                    (
                      NULLIF(
                        CONCAT(
                          (
                            NULLIF(
                              CONCAT(
                                (
                                  NULLIF(
                                    CONCAT(
                                      (
                                        NULLIF(
                                          CONCAT(
                                            (
                                              NULLIF(
                                                CONCAT(
                                                  (
                                                    NULLIF(
                                                      CONCAT(
                                                        (
                                                          NULLIF(
                                                            CONCAT(
                                                              (
                                                                NULLIF(
                                                                  CONCAT((
                                                                    NULLIF(CONCAT(CAST(v.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                                  ), v.daty),
                                                                  ''
                                                                )
                                                              ),
                                                              CAST(NULL AS TEXT)
                                                            ),
                                                            ''
                                                          )
                                                        ),
                                                        CAST(v.idclient AS TEXT)
                                                      ),
                                                      ''
                                                    )
                                                  ),
                                                  CAST(NULL AS TEXT)
                                                ),
                                                ''
                                              )
                                            ),
                                            CAST(c.nom AS TEXT)
                                          ),
                                          ''
                                        )
                                      ),
                                      CAST(NULL AS TEXT)
                                    ),
                                    ''
                                  )
                                ),
                                CAST(v.idmagasin AS TEXT)
                              ),
                              ''
                            )
                          ),
                          CAST(NULL AS TEXT)
                        ),
                        ''
                      )
                    ),
                    CAST(m.val AS TEXT)
                  ),
                  ''
                )
              ),
              CAST(NULL AS TEXT)
            ),
            ''
          )
        ),
        CAST(v.remarque AS TEXT)
      ),
      ''
    ) AS motsclesss,
    v.heuresaisie,
    v.adeclarer,
    v.factureechange,
    m.id AS idpoint
  FROM public.vente AS v
  LEFT JOIN public.client AS c
    ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
  LEFT JOIN public.point AS m
    ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
  LEFT JOIN public.zone AS pv
    ON CAST(pv.id AS TEXT) = CAST(m.idzone AS TEXT)
  JOIN (
    SELECT
      vd.idvente AS id,
      CAST(SUM(
        (
          CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
        ) * (
          COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
        ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
      ) AS DECIMAL(30, 2)) AS montanttotal,
      CAST((
        SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))) - SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          )
        )
      ) AS DECIMAL(30, 2)) AS montantremise,
      CAST(SUM(
        COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * COALESCE(vd.qte, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS frais,
      CAST(SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.puachat, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS montanttotalachat,
      CAST(SUM(
        (
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
      ) AS DECIMAL(30, 2)) AS montanttva,
      CAST((
        SUM(
          (
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) + SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        )
      ) AS DECIMAL(30, 2)) AS montantttc,
      COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
      COALESCE(AVG(vd.tauxdechange), CAST(1 AS DECIMAL)) AS tauxdechange,
      CAST((
        SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL))
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) + SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        )
      ) AS DECIMAL(30, 2)) AS montantttcar,
      CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
      v.idreservation,
      COALESCE(SUM(ing.calorie * vd.qte), CAST(0 AS DECIMAL)) AS poids,
      SUM(vd.qte) AS colis
    FROM public.vente_details AS vd
    LEFT JOIN public.vente AS v
      ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
    LEFT JOIN public.as_ingredients AS ing
      ON CAST(ing.id AS TEXT) = CAST(vd.idproduit AS TEXT)
    GROUP BY
      vd.idvente,
      vd.iddevise,
      v.idreservation
  ) AS v2
    ON CAST(v2.id AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.liaisonpaiementtotal AS mv
    ON CAST(v.id AS TEXT) = CAST(mv.id2 AS TEXT)
  LEFT JOIN (
    SELECT
      a.id,
      a.designation,
      a.idmagasin,
      CAST(NULL AS TEXT) AS idmagasinlib,
      a.daty,
      a.remarque,
      a.etat,
      a.idorigine,
      a.idclient,
      CAST(NULL AS TEXT) AS compte,
      CAST(NULL AS TEXT) AS compteauxiliaire,
      a.idvente,
      CAST(NULL AS TEXT) AS idventelib,
      a.idmotif,
      CAST(NULL AS TEXT) AS idmotiflib,
      a.idcategorie,
      CAST(NULL AS TEXT) AS idcategorielib,
      ag.iddevise,
      ag.tauxdechange,
      ag.montantht,
      ag.montanttva,
      ag.montantttc,
      ag.montanthtar,
      ag.montanttvaar,
      ag.montantttcar,
      CAST(NULL AS TEXT) AS idreservation,
      CAST(NULL AS TEXT) AS typeavoir,
      CAST(NULL AS TEXT) AS clientlib,
      COALESCE(m.montant, CAST(0 AS DECIMAL)) * COALESCE(ag.tauxdechange, CAST(0 AS DECIMAL)) AS montantpayear
    FROM public.avoirfc AS a
    JOIN public.avoirfcfille_grp AS ag
      ON CAST(ag.idavoirfc AS TEXT) = CAST(a.id AS TEXT)
    LEFT JOIN (
      SELECT
        m.id1 AS idorigine,
        SUM(m.montant) AS montant,
        CAST('AR' AS TEXT) AS iddevise
      FROM public.liaisonpaiement AS m
      WHERE
        m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
      GROUP BY
        m.id1
    ) AS m
      ON CAST(a.id AS TEXT) = CAST(m.idorigine AS TEXT)
    WHERE
      a.etat >= CAST(11 AS DECIMAL) AND a.idorigine IS NOT NULL
  ) AS acg
    ON CAST(acg.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.referencefacture AS rf
    ON CAST(rf.idfacture AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.modepaiement AS mp
    ON CAST(mp.id AS TEXT) = CAST(v.modepaiement AS TEXT)
  LEFT JOIN public.vente_reste AS vr
    ON CAST(vr.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.as_bondelivraison_client AS blc
    ON CAST(blc.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.compta_ecriture AS ce
    ON CAST(ce.idobjet AS TEXT) = CAST(v.id AS TEXT)
) AS v
JOIN public.ristourne AS r
  ON TRUE
CROSS JOIN LATERAL REGEXP_SPLIT_TO_TABLE(r.idorigine, ',') AS token(idvente)
WHERE
  token.idvente <> '' AND v.id = token.idvente;

-- Niveau 1 - vue 98 / 129 : VENTE_RECAP_JOUR
-- Dependances nouvelles : aucune.
CREATE VIEW public.vente_recap_jour (
    "daty", "montantttc", "montantpaye", "montantreste", "nombre", "montantresteacejour"
) AS
WITH bornes AS (
  SELECT
    CAST('2026-06-01' AS DATE) AS date_min,
    DATE_TRUNC('day', LOCALTIMESTAMP(0)) AS date_max
), calendrier AS (
  SELECT
    g.daty AS daty
  FROM bornes AS b
  CROSS JOIN LATERAL GENERATE_SERIES(CAST(b.date_min AS TIMESTAMP), CAST(b.date_max AS TIMESTAMP), INTERVAL '1 DAY') AS g(daty)
), vente_jour AS (
  SELECT
    DATE_TRUNC('DAY', vente_cpl.daty) AS daty,
    SUM(COALESCE(vente_cpl.montantttc, 0)) AS montantttc,
    SUM(COALESCE(vente_cpl.montantpaye, 0)) AS montantpaye,
    SUM(COALESCE(vente_cpl.montantreste, 0)) AS montantreste,
    COUNT(*) AS nombre
  FROM (
    SELECT
      v.id,
      v.designation,
      v.idmagasin,
      m.val AS idmagasinlib,
      v.daty,
      v.remarque,
      v.etat,
      CASE
        WHEN v.etat = CAST(1 AS DECIMAL)
        THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
        WHEN v.etat = CAST(11 AS DECIMAL)
        THEN CAST('VIS&Eacute;E' AS TEXT)
        WHEN v.etat = CAST(0 AS DECIMAL)
        THEN CAST('ANNUL&Eacute;E' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib,
      CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
      v2.iddevise,
      v.idclient,
      c.nom AS idclientlib,
      CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
      CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
      CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
      CAST(COALESCE(mv.montant, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
      CAST((
        COALESCE(v2.montantttc, CAST(0 AS DECIMAL)) - COALESCE(mv.montant, CAST(0 AS DECIMAL)) - COALESCE(acg.montantttcar - acg.montantpayear, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS montantreste,
      CAST(COALESCE(acg.montantttcar, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS avoir,
      CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
      CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
      CAST((
        v2.montantttcar - v2.montantrevient
      ) AS DECIMAL(20, 5)) AS margebrute,
      v.idreservation,
      CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
      rf.reference AS referencefacture,
      CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
      CAST((
        COALESCE(v2.montanttotal, CAST(0 AS DECIMAL)) + COALESCE(v2.montantremise, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS montant,
      EXTRACT(month FROM v.daty) AS mois,
      EXTRACT(year FROM v.daty) AS annee,
      CAST(v2.poids AS DECIMAL(30, 5)) AS poids,
      CAST(v2.colis AS DECIMAL(30, 5)) AS colis,
      v.modepaiement,
      mp.val AS modepaiementlib,
      COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(v2.poids, CAST(0 AS DECIMAL)) AS fraislivraison,
      v.modelivraison,
      CASE
        WHEN v.modelivraison = CAST(1 AS DECIMAL)
        THEN CAST('<span style=color: green;>LIVRAISON</span>' AS TEXT)
        WHEN v.modelivraison = CAST(2 AS DECIMAL)
        THEN CAST('<span style=color: green;>RECUPERATION</span>' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS modelivraisonlib,
      CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
      pv.id AS idprovince,
      pv.val AS provincelib,
      v.idorigine,
      CAST(COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS frais,
      v.referencefact,
      v.numerofacture,
      v.lieulivraison,
      v.datelivraison,
      v.updated_at,
      CASE
        WHEN v.estprevu = CAST(0 AS DECIMAL)
        THEN CAST('Non' AS TEXT)
        ELSE CAST('Oui' AS TEXT)
      END AS estprevulib,
      ce.id AS idecriture,
      COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
      NULLIF(
        CONCAT(
          (
            NULLIF(
              CONCAT(
                (
                  NULLIF(
                    CONCAT(
                      (
                        NULLIF(
                          CONCAT(
                            (
                              NULLIF(
                                CONCAT(
                                  (
                                    NULLIF(
                                      CONCAT(
                                        (
                                          NULLIF(
                                            CONCAT(
                                              (
                                                NULLIF(
                                                  CONCAT(
                                                    (
                                                      NULLIF(
                                                        CONCAT(
                                                          (
                                                            NULLIF(
                                                              CONCAT(
                                                                (
                                                                  NULLIF(
                                                                    CONCAT((
                                                                      NULLIF(CONCAT(CAST(v.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                                    ), v.daty),
                                                                    ''
                                                                  )
                                                                ),
                                                                CAST(NULL AS TEXT)
                                                              ),
                                                              ''
                                                            )
                                                          ),
                                                          CAST(v.idclient AS TEXT)
                                                        ),
                                                        ''
                                                      )
                                                    ),
                                                    CAST(NULL AS TEXT)
                                                  ),
                                                  ''
                                                )
                                              ),
                                              CAST(c.nom AS TEXT)
                                            ),
                                            ''
                                          )
                                        ),
                                        CAST(NULL AS TEXT)
                                      ),
                                      ''
                                    )
                                  ),
                                  CAST(v.idmagasin AS TEXT)
                                ),
                                ''
                              )
                            ),
                            CAST(NULL AS TEXT)
                          ),
                          ''
                        )
                      ),
                      CAST(m.val AS TEXT)
                    ),
                    ''
                  )
                ),
                CAST(NULL AS TEXT)
              ),
              ''
            )
          ),
          CAST(v.remarque AS TEXT)
        ),
        ''
      ) AS motsclesss,
      v.heuresaisie,
      v.adeclarer,
      v.factureechange,
      m.id AS idpoint
    FROM public.vente AS v
    LEFT JOIN public.client AS c
      ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
    LEFT JOIN public.point AS m
      ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
    LEFT JOIN public.zone AS pv
      ON CAST(pv.id AS TEXT) = CAST(m.idzone AS TEXT)
    JOIN (
      SELECT
        vd.idvente AS id,
        CAST(SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        ) AS DECIMAL(30, 2)) AS montanttotal,
        CAST((
          SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))) - SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            )
          )
        ) AS DECIMAL(30, 2)) AS montantremise,
        CAST(SUM(
          COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * COALESCE(vd.qte, CAST(0 AS DECIMAL))
        ) AS DECIMAL(30, 5)) AS frais,
        CAST(SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.puachat, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS montanttotalachat,
        CAST(SUM(
          (
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) AS DECIMAL(30, 2)) AS montanttva,
        CAST((
          SUM(
            (
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) + SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          )
        ) AS DECIMAL(30, 2)) AS montantttc,
        COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
        COALESCE(AVG(vd.tauxdechange), CAST(1 AS DECIMAL)) AS tauxdechange,
        CAST((
          SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL))
            ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
          ) + SUM(
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            ) * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          )
        ) AS DECIMAL(30, 2)) AS montantttcar,
        CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
        v.idreservation,
        COALESCE(SUM(ing.calorie * vd.qte), CAST(0 AS DECIMAL)) AS poids,
        SUM(vd.qte) AS colis
      FROM public.vente_details AS vd
      LEFT JOIN public.vente AS v
        ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
      LEFT JOIN public.as_ingredients AS ing
        ON CAST(ing.id AS TEXT) = CAST(vd.idproduit AS TEXT)
      GROUP BY
        vd.idvente,
        vd.iddevise,
        v.idreservation
    ) AS v2
      ON CAST(v2.id AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.liaisonpaiementtotal AS mv
      ON CAST(v.id AS TEXT) = CAST(mv.id2 AS TEXT)
    LEFT JOIN (
      SELECT
        a.id,
        a.designation,
        a.idmagasin,
        CAST(NULL AS TEXT) AS idmagasinlib,
        a.daty,
        a.remarque,
        a.etat,
        a.idorigine,
        a.idclient,
        CAST(NULL AS TEXT) AS compte,
        CAST(NULL AS TEXT) AS compteauxiliaire,
        a.idvente,
        CAST(NULL AS TEXT) AS idventelib,
        a.idmotif,
        CAST(NULL AS TEXT) AS idmotiflib,
        a.idcategorie,
        CAST(NULL AS TEXT) AS idcategorielib,
        ag.iddevise,
        ag.tauxdechange,
        ag.montantht,
        ag.montanttva,
        ag.montantttc,
        ag.montanthtar,
        ag.montanttvaar,
        ag.montantttcar,
        CAST(NULL AS TEXT) AS idreservation,
        CAST(NULL AS TEXT) AS typeavoir,
        CAST(NULL AS TEXT) AS clientlib,
        COALESCE(m.montant, CAST(0 AS DECIMAL)) * COALESCE(ag.tauxdechange, CAST(0 AS DECIMAL)) AS montantpayear
      FROM public.avoirfc AS a
      JOIN public.avoirfcfille_grp AS ag
        ON CAST(ag.idavoirfc AS TEXT) = CAST(a.id AS TEXT)
      LEFT JOIN (
        SELECT
          m.id1 AS idorigine,
          SUM(m.montant) AS montant,
          CAST('AR' AS TEXT) AS iddevise
        FROM public.liaisonpaiement AS m
        WHERE
          m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
        GROUP BY
          m.id1
      ) AS m
        ON CAST(a.id AS TEXT) = CAST(m.idorigine AS TEXT)
      WHERE
        a.etat >= CAST(11 AS DECIMAL) AND a.idorigine IS NOT NULL
    ) AS acg
      ON CAST(acg.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.referencefacture AS rf
      ON CAST(rf.idfacture AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.modepaiement AS mp
      ON CAST(mp.id AS TEXT) = CAST(v.modepaiement AS TEXT)
    LEFT JOIN public.vente_reste AS vr
      ON CAST(vr.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.as_bondelivraison_client AS blc
      ON CAST(blc.idvente AS TEXT) = CAST(v.id AS TEXT)
    LEFT JOIN public.compta_ecriture AS ce
      ON CAST(ce.idobjet AS TEXT) = CAST(v.id AS TEXT)
  ) AS vente_cpl
  WHERE
    vente_cpl.etat = 11 AND vente_cpl.daty >= CAST('2026-06-01' AS DATE)
  GROUP BY
    DATE_TRUNC('DAY', vente_cpl.daty)
)
SELECT
  c.daty AS daty,
  CAST(COALESCE(v.montantttc, 0) AS DECIMAL(30, 5)) AS montantttc,
  CAST(COALESCE(v.montantpaye, 0) AS DECIMAL(30, 5)) AS montantpaye,
  CAST(COALESCE(v.montantreste, 0) AS DECIMAL(30, 5)) AS montantreste,
  CAST(COALESCE(v.nombre, 0) AS DECIMAL(10, 0)) AS nombre,
  CAST(SUM(COALESCE(v.montantreste, 0)) OVER (ORDER BY c.daty ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS DECIMAL(30, 5)) AS montantresteacejour
FROM calendrier AS c
LEFT JOIN vente_jour AS v
  ON c.daty = v.daty;

-- Niveau 1 - vue 99 / 129 : V_ACCIDENT_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_accident_lib (
    "id", "daty", "date_declaration", "id_personnel", "id_lieu", "id_type_accident", "id_gravite", "id_machine", "cause", "heureaccident", "horairedebut", "horairefin", "activite", "lesions", "centresoin", "detailstemoin1", "detailstemoin2", "etat", "id_machine_lib", "id_lieu_lib", "id_type_accident_lib", "id_gravite_lib", "id_personnel_lib", "matricule", "etat_lib", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.daty AS daty,
  base.date_declaration AS date_declaration,
  base.id_personnel AS id_personnel,
  base.id_lieu AS id_lieu,
  base.id_type_accident AS id_type_accident,
  base.id_gravite AS id_gravite,
  base.id_machine AS id_machine,
  base.cause AS cause,
  base.heureaccident AS heureaccident,
  base.horairedebut AS horairedebut,
  base.horairefin AS horairefin,
  base.activite AS activite,
  base.lesions AS lesions,
  base.centresoin AS centresoin,
  base.detailstemoin1 AS detailstemoin1,
  base.detailstemoin2 AS detailstemoin2,
  base.etat AS etat,
  base.id_machine_lib AS id_machine_lib,
  base.id_lieu_lib AS id_lieu_lib,
  base.id_type_accident_lib AS id_type_accident_lib,
  base.id_gravite_lib AS id_gravite_lib,
  base.id_personnel_lib AS id_personnel_lib,
  base.matricule AS matricule,
  base.etat_lib AS etat_lib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.date_declaration, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(base.id_personnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_lieu AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_type_accident AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_gravite AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_machine AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.cause AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.heureaccident AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.horairedebut AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.horairefin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.activite AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.lesions AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.centresoin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.detailstemoin1 AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.detailstemoin2 AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    base.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.id_machine_lib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_lieu_lib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_type_accident_lib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_gravite_lib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_personnel_lib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.etat_lib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    acc.id AS id,
    acc.daty AS daty,
    acc.date_declaration AS date_declaration,
    acc.id_personnel AS id_personnel,
    acc.id_lieu AS id_lieu,
    acc.id_type_accident AS id_type_accident,
    acc.id_gravite AS id_gravite,
    acc.id_machine AS id_machine,
    acc.cause AS cause,
    acc.heureaccident AS heureaccident,
    acc.horairedebut AS horairedebut,
    acc.horairefin AS horairefin,
    acc.activite AS activite,
    acc.lesions AS lesions,
    acc.centresoin AS centresoin,
    acc.detailstemoin1 AS detailstemoin1,
    acc.detailstemoin2 AS detailstemoin2,
    acc.etat AS etat,
    m.val AS id_machine_lib,
    lat.val AS id_lieu_lib,
    ta.val AS id_type_accident_lib,
    ga.val AS id_gravite_lib,
    NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS id_personnel_lib,
    pip.matricule AS matricule,
    CASE
      WHEN acc.etat = 1
      THEN 'Cree'
      WHEN acc.etat = 11
      THEN 'Declare'
      ELSE 'inconnu'
    END AS etat_lib
  FROM public.accident AS acc
  LEFT JOIN public.machine AS m
    ON m.id = acc.id_machine
  LEFT JOIN public.lieu_accident_travail AS lat
    ON lat.id = acc.id_lieu
  LEFT JOIN public.type_accident AS ta
    ON ta.id = acc.id_type_accident
  LEFT JOIN public.gravite_accident AS ga
    ON ga.id = acc.id_gravite
  LEFT JOIN public.log_personnel AS lp
    ON lp.id = acc.id_personnel
  LEFT JOIN public.paie_info_personnel AS pip
    ON pip.id = acc.id_personnel
) AS base;

-- Niveau 1 - vue 100 / 129 : V_BALANCE_DETAILS
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_balance_details (
    "annee", "mois", "compte", "libellecompte", "debit", "credit", "compte3", "compte2", "cumuldebit", "cumulcredit"
) AS
WITH mois_annees AS (
  SELECT
    DATE_TRUNC('month', LOCALTIMESTAMP(0)) + (
      g.n - 25
    ) * INTERVAL '1 MONTH' AS mois
  FROM GENERATE_SERIES(1, 49) AS g(n)
), base_comptes_periode AS (
  SELECT
    CAST(c.compte AS VARCHAR(100)) AS compte,
    c.libelle AS libellecompte,
    m.mois AS mois,
    EXTRACT(YEAR FROM m.mois) AS annee,
    EXTRACT(MONTH FROM m.mois) AS mois_num
  FROM public.compta_compte AS c
  CROSS JOIN mois_annees AS m
), ecritures_mensuelles AS (
  /* Excludes journal = 'COMP000015' */
  SELECT
    CAST(cse.compte AS VARCHAR(100)) AS compte,
    DATE_TRUNC('month', cse.daty) AS mois,
    SUM(cse.debit) AS soldedebit,
    SUM(cse.credit) AS soldecredit
  FROM public.compta_sous_ecriture AS cse
  JOIN public.compta_ecriture AS ce
    ON ce.id = cse.idmere
  WHERE
    NOT cse.daty IS NULL AND cse.etat >= 11 AND cse.journal <> 'COMP000015'
  GROUP BY
    cse.compte,
    DATE_TRUNC('month', cse.daty)
), ecritures_mensuelles_cumuls AS (
  /* Includes all journals, including 'COMP000015' */
  SELECT
    CAST(cse.compte AS VARCHAR(100)) AS compte,
    DATE_TRUNC('month', cse.daty) AS mois,
    SUM(cse.debit) AS cumuldebit,
    SUM(cse.credit) AS cumulcredit
  FROM public.compta_sous_ecriture AS cse
  JOIN public.compta_ecriture AS ce
    ON ce.id = cse.idmere
  WHERE
    NOT cse.daty IS NULL AND cse.etat >= 11
  GROUP BY
    cse.compte,
    DATE_TRUNC('month', cse.daty)
), fusion_comptes_mois AS (
  SELECT
    b.annee AS annee,
    b.mois_num AS mois,
    b.compte AS compte,
    b.libellecompte AS libellecompte,
    b.mois AS date_mois,
    COALESCE(em.soldedebit, 0) AS soldedebit,
    COALESCE(em.soldecredit, 0) AS soldecredit,
    COALESCE(ec.cumuldebit, 0) AS cumuldebit,
    COALESCE(ec.cumulcredit, 0) AS cumulcredit
  FROM base_comptes_periode AS b
  LEFT JOIN ecritures_mensuelles AS em
    ON b.compte = em.compte AND b.mois = em.mois
  LEFT JOIN ecritures_mensuelles_cumuls AS ec
    ON b.compte = ec.compte AND b.mois = ec.mois
)
SELECT
  fusion_comptes_mois.annee AS annee,
  fusion_comptes_mois.mois AS mois,
  fusion_comptes_mois.compte AS compte,
  fusion_comptes_mois.libellecompte AS libellecompte,
  ROUND(CAST(fusion_comptes_mois.soldedebit AS DECIMAL), 2) AS debit,
  ROUND(CAST(fusion_comptes_mois.soldecredit AS DECIMAL), 2) AS credit,
  CAST(NULLIF(SUBSTRING(fusion_comptes_mois.compte FROM 1 FOR 3), '') AS DECIMAL) AS compte3,
  CAST(NULLIF(SUBSTRING(fusion_comptes_mois.compte FROM 1 FOR 2), '') AS DECIMAL) AS compte2,
  ROUND(
    CAST(SUM(fusion_comptes_mois.cumuldebit) OVER (
      PARTITION BY fusion_comptes_mois.compte
      ORDER BY fusion_comptes_mois.date_mois
      ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
    ) AS DECIMAL),
    2
  ) AS cumuldebit,
  ROUND(
    CAST(SUM(fusion_comptes_mois.cumulcredit) OVER (
      PARTITION BY fusion_comptes_mois.compte
      ORDER BY fusion_comptes_mois.date_mois
      ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
    ) AS DECIMAL),
    2
  ) AS cumulcredit
FROM fusion_comptes_mois AS fusion_comptes_mois
ORDER BY
  compte,
  annee,
  mois;

