) AS
WITH mois_annees AS (
  SELECT
    DATE_TRUNC('month', LOCALTIMESTAMP(0)) + (
      g.n - 25
    ) * INTERVAL '1 MONTH' AS mois
  FROM GENERATE_SERIES(1, 49) AS g(n)
), base_comptes_periode AS (
  SELECT
    CAST(c.compte AS VARCHAR(100)) AS compte,
