  FROM public.compta_compte AS c
  CROSS JOIN mois_annees AS m
  WHERE
    c.typecompte = '3'
), ecritures_mensuelles AS (
  /* For monthly values: EXCLUDE journal = 'COMP000015' */
  SELECT
    CAST(cse.compte AS VARCHAR(100)) AS compte,
