    DATE_TRUNC('month', cse.daty)
), fusion_comptes_mois AS (
  SELECT
    b.annee AS annee,
    b.mois_num AS mois,
    b.compte AS compte,
    b.libellecompte AS libellecompte,
    b.mois AS date_mois,
    COALESCE(em.soldedebit, 0) AS soldedebit,
    COALESCE(em.soldecredit, 0) AS soldecredit,
    COALESCE(ec.cumuldebit, 0) AS cumuldebit,
    COALESCE(ec.cumulcredit, 0) AS cumulcredit
  FROM base_comptes_periode AS b
  LEFT JOIN ecritures_mensuelles AS em
    ON b.compte = em.compte AND b.mois = em.mois
  LEFT JOIN ecritures_mensuelles_cumuls AS ec
    ON b.compte = ec.compte AND b.mois = ec.mois
)
SELECT
  fusion_comptes_mois.annee AS annee,
  fusion_comptes_mois.mois AS mois,
  fusion_comptes_mois.compte AS compte,
  fusion_comptes_mois.libellecompte AS libellecompte,
  ROUND(CAST(fusion_comptes_mois.soldedebit AS DECIMAL), 2) AS debit,
  ROUND(CAST(fusion_comptes_mois.soldecredit AS DECIMAL), 2) AS credit,
  CAST(NULLIF(SUBSTRING(fusion_comptes_mois.compte FROM 1 FOR 3), '') AS DECIMAL) AS compte3,
  CAST(NULLIF(SUBSTRING(fusion_comptes_mois.compte FROM 1 FOR 2), '') AS DECIMAL) AS compte2,
  ROUND(
    CAST(SUM(fusion_comptes_mois.cumuldebit) OVER (
      PARTITION BY fusion_comptes_mois.compte
      ORDER BY fusion_comptes_mois.date_mois
      ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
    ) AS DECIMAL),
    2
  ) AS cumuldebit,
  ROUND(
    CAST(SUM(fusion_comptes_mois.cumulcredit) OVER (
      PARTITION BY fusion_comptes_mois.compte
      ORDER BY fusion_comptes_mois.date_mois
      ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
    ) AS DECIMAL),
    2
  ) AS cumulcredit
FROM fusion_comptes_mois AS fusion_comptes_mois
ORDER BY
  compte,
  annee,
  mois;

