-- Niveau 1 - vue 103 / 129 : V_CLASSEETFICHE
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_classeetfiche (
    "id", "classe", "fiche", "libelle"
) AS
SELECT
  c.id,
  c.classe,
  c.fiche,
  COALESCE(
    c.libelle,
    (
      SELECT
        m.tokens[1]
      FROM REGEXP_MATCHES(c.classe, '[^\.]+', 'g') WITH ORDINALITY AS m(tokens, pos)
      WHERE
        CAST(m.pos AS DECIMAL) = LENGTH(c.classe) - LENGTH(REPLACE(c.classe, '.', '')) + 1
    )
  ) AS libelle
FROM public.classeetfiche AS c;

-- Niveau 1 - vue 104 / 129 : V_COMPTA_COMPTE
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_compta_compte (
    "id", "compteint", "compte", "libelle", "typecompte", "classy", "analytique_obli", "idjournal", "codeimpot"
) AS
SELECT
  compta_compte.id AS id,
  CAST(SUBSTRING(NULLIF(TRIM(compta_compte.compte), '') FROM '^[0-9]+') AS DECIMAL) AS compteint,
  compta_compte.compte AS compte,
  compta_compte.libelle AS libelle,
  compta_compte.typecompte AS typecompte,
  compta_compte.classy AS classy,
  compta_compte.analytique_obli AS analytique_obli,
  compta_compte.idjournal AS idjournal,
  compta_compte.codeimpot AS codeimpot
FROM public.compta_compte AS compta_compte
WHERE
  NULLIF(TRIM(compta_compte.compte), '') ~ '^[0-9]+';

-- Niveau 1 - vue 105 / 129 : V_CV_SCORE_GLOBAL
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_cv_score_global (
    "idcv", "idficheposte", "nbcompetences", "nbcompetencesvalides", "nbcompetencesnonvalides", "score", "motsclesss"
) AS
SELECT
  base.idcv AS idcv,
  base.idficheposte AS idficheposte,
  base.nbcompetences AS nbcompetences,
  base.nbcompetencesvalides AS nbcompetencesvalides,
  base.nbcompetencesnonvalides AS nbcompetencesnonvalides,
  base.score AS score,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.idcv AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idficheposte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbcompetences
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbcompetences
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbcompetences
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbcompetencesvalides
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbcompetencesvalides
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbcompetencesvalides
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbcompetencesnonvalides
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbcompetencesnonvalides
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbcompetencesnonvalides
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.score
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.score
                  ) AS TEXT)))
                  ELSE CAST((
                    base.score
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    v.idcv AS idcv,
    v.idficheposte AS idficheposte,
    COUNT(*) AS nbcompetences,
    SUM(v.estvalide) AS nbcompetencesvalides,
    COUNT(*) - SUM(v.estvalide) AS nbcompetencesnonvalides,
    ROUND(CAST(CAST(SUM(v.estvalide) AS DECIMAL) / COUNT(*) * 100 AS DECIMAL), 2) AS score
  FROM (
    SELECT
      cv.id AS idcv,
      cv.idficheposte,
      fpc.id AS idfichepostecompetence,
      fpc.idtypecompetencesfp AS idtypecompetence,
      typ.val AS typecompetencelib,
      fpc.description AS competence,
      fpc.niveau AS niveaurequis,
      cvc.niveau AS niveaucandidat,
      cvc.niveau - fpc.niveau AS ecart,
      CASE WHEN cvc.niveau IS NULL THEN 0 WHEN cvc.niveau >= fpc.niveau THEN 1 ELSE 0 END AS estvalide,
      CASE
        WHEN cvc.niveau IS NULL
        THEN CAST('NON RENSEIGNE' AS TEXT)
        WHEN cvc.niveau >= fpc.niveau
        THEN CAST('OK' AS TEXT)
        ELSE CAST('INSUFFISANT' AS TEXT)
      END AS resultat
    FROM public.cv AS cv
    JOIN public.fiche_poste_competences AS fpc
      ON CAST(fpc.idficheposte AS TEXT) = CAST(cv.idficheposte AS TEXT)
    LEFT JOIN public.type_competences_fp AS typ
      ON CAST(typ.id AS TEXT) = CAST(fpc.idtypecompetencesfp AS TEXT)
    LEFT JOIN public.cv_competence AS cvc
      ON CAST(cvc.idcv AS TEXT) = CAST(cv.id AS TEXT)
      AND CAST(cvc.idtypecompetencesfp AS TEXT) = CAST(fpc.idtypecompetencesfp AS TEXT)
  ) AS v
  GROUP BY
    v.idcv,
    v.idficheposte
) AS base;

-- Niveau 1 - vue 106 / 129 : V_DUREE_REELLE_TRAVAUX
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_duree_reelle_travaux (
    "refobjet", "objet", "action", "datehistorique", "heure", "duree_heures_decimale", "ecart"
) AS
SELECT
  p.refobjet AS refobjet,
  p.objet AS objet,
  p.action AS action,
  p.datehistorique AS datehistorique,
  p.heure AS heure,
  CASE
    WHEN NOT p.heure IS NULL
    THEN CAST(NULLIF(SUBSTRING(p.heure FROM 1 FOR POSITION(':' IN p.heure) - 1), '') AS DECIMAL) + (
      CAST(CAST(NULLIF(SUBSTRING(p.heure FROM POSITION(':' IN p.heure) + 1), '') AS DECIMAL) AS DECIMAL) / 60
    )
    ELSE NULL
  END AS duree_heures_decimale,
  p.ecart AS ecart
FROM public.process AS p
WHERE
  NOT p.refobjet IS NULL;

-- Niveau 1 - vue 107 / 129 : V_ETATCAISSE_CLOTURE
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_etatcaisse_cloture (
    "id", "idcaisse", "idcaisselib", "idtypecaisse", "idtypecaisselib", "idpoint", "idpointlib", "datedernierreport", "montantdernierreport", "debit", "credit", "reste", "devise"
) AS
SELECT
  r.id AS id,
  r.idcaisse AS idcaisse,
  c.val AS idcaisselib,
  c.idtypecaisse AS idtypecaisse,
  tc.desce AS idtypecaisselib,
  c.idpoint AS idpoint,
  p.desce AS idpointlib,
  r.daty AS datedernierreport,
  CAST(COALESCE((
    (
      r.montant + COALESCE(mvtav.credit - mvtav.debit, 0)
    ) * taux.taux
  ), 0) AS DECIMAL(30, 2)) AS montantdernierreport,
  CAST(COALESCE(mvt.debit, 0) AS DECIMAL(30, 2)) AS debit,
  CAST(COALESCE(mvt.credit, 0) AS DECIMAL(30, 2)) AS credit,
  CAST((
    COALESCE(mvt.credit, 0) - COALESCE(mvt.debit, 0)
  ) AS DECIMAL(30, 2)) AS reste,
  CAST('AR' AS TEXT) AS devise
FROM (
  SELECT
    r.id,
    r.idcaisse,
    c.val AS idcaisselib,
    r.montant,
    r.montanttheorique,
    r.daty,
    r.etat,
    c.iddevise,
    CASE
      WHEN r.etat = CAST(0 AS DECIMAL)
      THEN CAST('ANNULEE' AS TEXT)
      WHEN r.etat = CAST(1 AS DECIMAL)
      THEN CAST('CREE' AS TEXT)
      WHEN r.etat = CAST(11 AS DECIMAL)
      THEN CAST('VALIDEE' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS etatlib
  FROM public.reportcaisse AS r
  LEFT JOIN (
    SELECT
      caisse.id,
      caisse.val,
      caisse.desce,
      caisse.idtypecaisse,
      caisse.idpoint,
      caisse.idpompiste,
      caisse.etat,
      caisse.idcategoriecaisse,
      caisse.compte,
      caisse.idmagasin,
      caisse.iddevise,
      caisse.idtypebanque,
      caisse.estrib
    FROM public.caisse
    WHERE
      CAST(caisse.id AS TEXT) <> CAST('CAIS001' AS TEXT)
  ) AS c
    ON CAST(c.id AS TEXT) = CAST(r.idcaisse AS TEXT)
) AS r
LEFT JOIN (
  SELECT
    ta.id AS id,
    ta.iddevise AS iddevise,
    ta.taux AS taux,
    ta.daty AS daty
  FROM public.tauxdechange AS ta, (
    SELECT
      MAX(t.daty) AS daty,
      t.iddevise AS iddevise
    FROM public.tauxdechange AS t
    WHERE
      t.daty <= DATE_TRUNC('day', LOCALTIMESTAMP(0))
    GROUP BY
      t.iddevise
  ) AS tmax
  WHERE
    ta.daty = tmax.daty AND ta.iddevise = tmax.iddevise
) AS taux
  ON r.iddevise = taux.iddevise
LEFT JOIN public.caisse AS c
  ON r.idcaisse = c.id
LEFT JOIN (
  SELECT
    m.idcaisse AS idcaisse,
    SUM(COALESCE((
      m.debit * t.taux
    ), 0)) AS debit,
    SUM(COALESCE((
      m.credit * t.taux
    ), 0)) AS credit
  FROM public.mouvementcaisse_vise AS m
  LEFT JOIN (
    SELECT
      ta.id AS id,
      ta.iddevise AS iddevise,
      ta.taux AS taux,
      ta.daty AS daty
    FROM public.tauxdechange AS ta, (
      SELECT
        MAX(t.daty) AS daty,
        t.iddevise AS iddevise
      FROM public.tauxdechange AS t
      WHERE
        t.daty <= DATE_TRUNC('day', LOCALTIMESTAMP(0))
      GROUP BY
        t.iddevise
    ) AS tmax
    WHERE
      ta.daty = tmax.daty AND ta.iddevise = tmax.iddevise
  ) AS t
    ON m.iddevise = t.iddevise
  LEFT JOIN (
    SELECT
      r.idcaisse AS idcaisse,
      MAX(r.daty) AS maxdatereport
    FROM public.reportcaisse AS r
    WHERE
      r.etat = 11 AND r.daty <= DATE_TRUNC('day', LOCALTIMESTAMP(0))
    GROUP BY
      r.idcaisse
  ) AS rm
    ON m.idcaisse = rm.idcaisse
  WHERE
    m.daty >= DATE_TRUNC('day', LOCALTIMESTAMP(0))
    AND m.daty <= DATE_TRUNC('day', LOCALTIMESTAMP(0))
  GROUP BY
    m.idcaisse
) AS mvt
  ON r.idcaisse = mvt.idcaisse
LEFT JOIN (
  SELECT
    m.idcaisse AS idcaisse,
    SUM(COALESCE((
      m.debit * t.taux
    ), 0)) AS debit,
    SUM(COALESCE((
      m.credit * t.taux
    ), 0)) AS credit
  FROM public.mouvementcaisse_vise AS m
  LEFT JOIN (
    SELECT
      ta.id AS id,
      ta.iddevise AS iddevise,
      ta.taux AS taux,
      ta.daty AS daty
    FROM public.tauxdechange AS ta, (
      SELECT
        MAX(t.daty) AS daty,
        t.iddevise AS iddevise
      FROM public.tauxdechange AS t
      WHERE
        t.daty <= DATE_TRUNC('day', LOCALTIMESTAMP(0))
      GROUP BY
        t.iddevise
    ) AS tmax
    WHERE
      ta.daty = tmax.daty AND ta.iddevise = tmax.iddevise
  ) AS t
    ON m.iddevise = t.iddevise
  LEFT JOIN (
    SELECT
      r.idcaisse AS idcaisse,
      MAX(r.daty) AS maxdatereport
    FROM public.reportcaisse AS r
    WHERE
      r.etat = 11 AND r.daty <= DATE_TRUNC('day', LOCALTIMESTAMP(0))
    GROUP BY
      r.idcaisse
  ) AS rm
    ON m.idcaisse = rm.idcaisse
  WHERE
    m.daty >= rm.maxdatereport AND m.daty < DATE_TRUNC('day', LOCALTIMESTAMP(0))
  GROUP BY
    m.idcaisse
) AS mvtav
  ON r.idcaisse = mvtav.idcaisse
LEFT JOIN public.typecaisse AS tc
  ON c.idtypecaisse = tc.id
CROSS JOIN (
  SELECT
    r.idcaisse AS idcaisse,
    MAX(r.daty) AS maxdatereport
  FROM (
    SELECT
      r.id,
      r.idcaisse,
      c.val AS idcaisselib,
      r.montant,
      r.montanttheorique,
      r.daty,
      r.etat,
      c.iddevise,
      CASE
        WHEN r.etat = CAST(0 AS DECIMAL)
        THEN CAST('ANNULEE' AS TEXT)
        WHEN r.etat = CAST(1 AS DECIMAL)
        THEN CAST('CREE' AS TEXT)
        WHEN r.etat = CAST(11 AS DECIMAL)
        THEN CAST('VALIDEE' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib
    FROM public.reportcaisse AS r
    LEFT JOIN (
      SELECT
        caisse.id,
        caisse.val,
        caisse.desce,
        caisse.idtypecaisse,
        caisse.idpoint,
        caisse.idpompiste,
        caisse.etat,
        caisse.idcategoriecaisse,
        caisse.compte,
        caisse.idmagasin,
        caisse.iddevise,
        caisse.idtypebanque,
        caisse.estrib
      FROM public.caisse
      WHERE
        CAST(caisse.id AS TEXT) <> CAST('CAIS001' AS TEXT)
    ) AS c
      ON CAST(c.id AS TEXT) = CAST(r.idcaisse AS TEXT)
  ) AS r
  WHERE
    r.etat = 11 AND r.daty <= DATE_TRUNC('day', LOCALTIMESTAMP(0))
  GROUP BY
    r.idcaisse
) AS rm
CROSS JOIN public.point AS p
WHERE
  r.daty = rm.maxdatereport
  AND r.etat = 11
  AND r.idcaisse = rm.idcaisse
  AND c.idpoint = p.id;

-- Niveau 1 - vue 108 / 129 : V_ETATSTOCK
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_etatstock (
    "id", "idproduitlib", "idtypeproduit", "idtypeproduitlib", "idmagasin", "idmagasinlib", "datedernierinventaire", "quantite", "entree", "sortie", "reste", "idunite", "idunitelib", "puvente", "idpoint", "idtypemagasin", "seuilmin", "seuilmax"
) AS
SELECT
  inv.idproduit AS id,
  p.desce AS idproduitlib,
  p.idtypeproduit AS idtypeproduit,
  tp.desce AS idtypeproduitlib,
  inv.idmagasin AS idmagasin,
  mag.desce AS idmagasinlib,
  inv.daty AS datedernierinventaire,
  CAST(COALESCE(inv.quantite, 0) AS DECIMAL(30, 2)) AS quantite,
  COALESCE(mvt.entree, 0) AS entree,
  COALESCE(mvt.sortie, 0) AS sortie,
  COALESCE(mvt.entree, 0) + COALESCE(inv.quantite, 0) - COALESCE(mvt.sortie, 0) AS reste,
  p.idunite AS idunite,
  u.desce AS idunitelib,
  CAST(COALESCE(p.puvente, 0) AS DECIMAL(30, 2)) AS puvente,
  mag.idpoint AS idpoint,
  mag.idtypemagasin AS idtypemagasin,
  p.seuilmin AS seuilmin,
  p.seuilmax AS seuilmax
FROM public.inventaire_fille_cpl AS inv
LEFT JOIN (
  SELECT
    m.idproduit AS idproduit,
    dinv.idmagasin AS idmagasin,
    SUM(COALESCE(m.entree, 0)) AS entree,
    SUM(COALESCE(m.sortie, 0)) AS sortie
  FROM (
    SELECT
      m.id,
      m.idmvtstock,
      m.idproduit,
      p.libelle AS idproduitlib,
      m.entree,
      m.sortie,
      m.idventedetail,
      CAST(NULL AS TEXT) AS idventedetaillib,
      m.idtransfertdetail,
      CAST(NULL AS TEXT) AS idtransfertdetaillib,
      m2.daty,
      m2.idmagasin,
      m3.val AS idmagasinlib
    FROM public.mvtstockfille AS m
    LEFT JOIN public.as_ingredients AS p
      ON CAST(p.id AS TEXT) = CAST(m.idproduit AS TEXT)
    LEFT JOIN public.mvtstock AS m2
      ON CAST(m2.id AS TEXT) = CAST(m.idmvtstock AS TEXT)
    LEFT JOIN (
      SELECT
        p.id,
        p.val,
        p.desce,
        p.id AS idpoint,
        CAST('-' AS TEXT) AS idproduit,
        CAST(NULL AS TEXT) AS idtypemagasin,
        11 AS etat
      FROM public.point AS p
    ) AS m3
      ON CAST(m3.id AS TEXT) = CAST(m2.idmagasin AS TEXT)
    WHERE
      m2.etat = CAST(11 AS DECIMAL)
  ) AS m
  LEFT JOIN (
    SELECT
      inv.idproduit AS idproduit,
      inv.idmagasin AS idmagasin,
      MAX(inv.daty) AS maxdateinventaire
    FROM public.inventaire_fille_cpl AS inv
    WHERE
      inv.etat = 11 AND inv.daty <= LOCALTIMESTAMP(0)
    GROUP BY
      inv.idproduit,
      inv.idmagasin
  ) AS dinv
    ON m.idproduit = dinv.idproduit AND m.idmagasin = dinv.idmagasin
  WHERE
    m.daty > dinv.maxdateinventaire AND m.daty <= LOCALTIMESTAMP(0)
  GROUP BY
    m.idproduit,
    dinv.idmagasin
) AS mvt
  ON inv.idproduit = mvt.idproduit AND inv.idmagasin = mvt.idmagasin
LEFT JOIN public.produit AS p
  ON inv.idproduit = p.id
LEFT JOIN public.unite AS u
  ON p.idunite = u.id
CROSS JOIN (
  SELECT
    inv.idproduit AS idproduit,
    inv.idmagasin AS idmagasin,
    MAX(inv.daty) AS maxdateinventaire
  FROM public.inventaire_fille_cpl AS inv
  WHERE
    inv.etat = 11 AND inv.daty <= LOCALTIMESTAMP(0)
  GROUP BY
    inv.idproduit,
    inv.idmagasin
) AS invm
CROSS JOIN public.type_produit AS tp
CROSS JOIN (
  SELECT
    p.id,
    p.val,
    p.desce,
    p.id AS idpoint,
    CAST('-' AS TEXT) AS idproduit,
    CAST(NULL AS TEXT) AS idtypemagasin,
    11 AS etat
  FROM public.point AS p
) AS mag
WHERE
  inv.daty = invm.maxdateinventaire
  AND inv.idmagasin = invm.idmagasin
  AND inv.idproduit = invm.idproduit
  AND p.idtypeproduit = tp.id
  AND inv.idmagasin = mag.id
  AND (
    mvt.sortie > 0 OR mvt.entree > 0
  )
  AND inv.etat >= 11;

-- Niveau 1 - vue 109 / 129 : V_ETATSTOCK_ENTREE
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_etatstock_entree (
    "id", "idproduit", "idproduitlib", "categorieingredient", "idtypeproduitlib", "idmagasin", "idmagasinlib", "quantite", "entree", "sortie", "reste", "unite", "idunitelib", "pu", "daty", "idfournisseur", "idfournisseurlib", "dateachat", "puvente", "idpoint", "idtypemagasin", "seuilmin", "seuilmax", "montantentree", "montantsortie", "montantreste", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.idproduit AS idproduit,
  sq.idproduitlib AS idproduitlib,
  sq.categorieingredient AS categorieingredient,
  sq.idtypeproduitlib AS idtypeproduitlib,
  sq.idmagasin AS idmagasin,
  sq.idmagasinlib AS idmagasinlib,
  CAST(COALESCE(sq.quantite, 0) AS DECIMAL(30, 5)) AS quantite,
  CAST(COALESCE(sq.entree, 0) AS DECIMAL(30, 5)) AS entree,
  CAST(COALESCE(sq.sortie, 0) AS DECIMAL(30, 5)) AS sortie,
  CAST(COALESCE(sq.reste, 0) AS DECIMAL(30, 5)) AS reste,
  sq.unite AS unite,
  sq.idunitelib AS idunitelib,
  sq.pu AS pu,
  sq.daty AS daty,
  sq.idfournisseur AS idfournisseur,
  sq.idfournisseurlib AS idfournisseurlib,
  sq.dateachat AS dateachat,
  CAST(COALESCE(sq.puvente, 0) AS DECIMAL(30, 5)) AS puvente,
  sq.idpoint AS idpoint,
  sq.idtypemagasin AS idtypemagasin,
  CAST(COALESCE(sq.seuilmin, 0) AS DECIMAL(30, 5)) AS seuilmin,
  CAST(COALESCE(sq.seuilmax, 0) AS DECIMAL(30, 5)) AS seuilmax,
  CAST(COALESCE(sq.montantentree, 0) AS DECIMAL(30, 5)) AS montantentree,
  CAST(COALESCE(sq.montantsortie, 0) AS DECIMAL(30, 5)) AS montantsortie,
  CAST(COALESCE(sq.montantreste, 0) AS DECIMAL(30, 5)) AS montantreste,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idproduit AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idproduitlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.categorieingredient AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idtypeproduitlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idmagasin AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idmagasinlib AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.quantite
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.quantite
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.quantite
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.entree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.entree
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.entree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.sortie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.sortie
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.sortie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.reste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.reste
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.reste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.unite AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idunitelib AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.pu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.pu
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.pu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(sq.idfournisseur AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idfournisseurlib AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.dateachat, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.puvente
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.puvente
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.puvente
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.idpoint AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idtypemagasin AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.seuilmin
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.seuilmin
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.seuilmin
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.seuilmax
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.seuilmax
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.seuilmax
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantentree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantentree
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantentree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantsortie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantsortie
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantsortie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantreste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantreste
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantreste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT DISTINCT
    ve.id AS id,
    ai.id AS idproduit,
    ai.libelle AS idproduitlib,
    ai.categorieingredient AS categorieingredient,
    c.val AS idtypeproduitlib,
    ve.idmagasin AS idmagasin,
    m.val AS idmagasinlib,
    CAST(ve.quantite AS DECIMAL(30, 5)) AS quantite,
    CAST(ve.entree AS DECIMAL(30, 5)) AS entree,
    CAST(ve.sortie AS DECIMAL(30, 5)) AS sortie,
    CAST(ve.reste AS DECIMAL(30, 5)) AS reste,
    ai.unite AS unite,
    u.val AS idunitelib,
    ve.pu AS pu,
    ve.daty AS daty,
    ve.idfournisseur AS idfournisseur,
    f.nom AS idfournisseurlib,
    ve.dateachat AS dateachat,
    CAST(COALESCE(ai.pv, 0) AS DECIMAL(30, 5)) AS puvente,
    m.idpoint AS idpoint,
    m.idtypemagasin AS idtypemagasin,
    ai.seuilmin AS seuilmin,
    ai.seuilmax AS seuilmax,
    ve.montantentree AS montantentree,
    ve.montantsortie AS montantsortie,
    ve.montantreste AS montantreste
  FROM (
    SELECT
      x.id AS id,
      x.idmvtstock AS idmvtstock,
      x.idproduit AS idproduit,
      x.entree AS entree,
      x.sortie AS sortie,
      x.idventedetail AS idventedetail,
      x.idtransfertdetail AS idtransfertdetail,
      x.pu AS pu,
      x.mvtsrc AS mvtsrc,
      x.daty AS daty,
      x.reste AS reste,
      x.quantite AS quantite,
      x.idmagasin AS idmagasin,
      x.idinventairefille AS idinventairefille,
      x.montantentree AS montantentree,
      x.montantsortie AS montantsortie,
      x.montantreste AS montantreste,
      COALESCE(b.idfournisseur, invf.idfournisseur, bb.idfournisseur, trs.idfournisseur) AS idfournisseur,
      f.daty AS dateachat
    FROM (
      SELECT
        _0.id AS id,
        _0.idmvtstock AS idmvtstock,
        _0.idproduit AS idproduit,
        _0.entree AS entree,
        _0.sortie AS sortie,
        _0.idventedetail AS idventedetail,
        _0.idtransfertdetail AS idtransfertdetail,
        _0.pu AS pu,
        _0.mvtsrc AS mvtsrc,
        _0.daty AS daty,
        _0.reste AS reste,
        _0.quantite AS quantite,
        _0.idmagasin AS idmagasin,
        _0.idinventairefille AS idinventairefille,
        _0.montantentree AS montantentree,
        _0.montantsortie AS montantsortie,
        _0.montantreste AS montantreste
      FROM (
        SELECT
          mf.id AS id,
          mf.idmvtstock AS idmvtstock,
          mf.idproduit AS idproduit,
          COALESCE(mf.entree, 0) + COALESCE(s.entree, 0) AS entree,
          s.sortie AS sortie,
          mf.idventedetail AS idventedetail,
          mf.idtransfertdetail AS idtransfertdetail,
          mf.pu AS pu,
          mf.mvtsrc AS mvtsrc,
          ms.daty AS daty,
          COALESCE(mf.entree, 0) - COALESCE(s.sortie, 0) + COALESCE(s.entree, 0) AS reste,
          COALESCE(mf.entree, 0) - COALESCE(s.sortie, 0) + COALESCE(s.entree, 0) AS quantite,
          ms.idmagasin AS idmagasin,
          mf.idinventairefille AS idinventairefille,
          CAST((
            mf.pu * mf.entree
          ) AS DECIMAL(30, 5)) AS montantentree,
          CAST((
            mf.pu * s.sortie
          ) AS DECIMAL(30, 5)) AS montantsortie,
          CAST(COALESCE(mf.entree, 0) - COALESCE(s.sortie, 0) + COALESCE(s.entree, 0) AS DECIMAL(30, 5)) * mf.pu AS montantreste
        FROM public.mvtstockfille AS mf
        LEFT JOIN public.mvtstock AS ms
          ON ms.id = mf.idmvtstock
        LEFT JOIN (
          SELECT
            mf2.mvtsrc AS mvtsrc,
            SUM(mf2.sortie) AS sortie,
            SUM(mf2.entree) AS entree
          FROM public.mvtstockfille AS mf2
          LEFT JOIN public.mvtstock AS ms2
            ON ms2.id = mf2.idmvtstock
          WHERE
            ms2.etat >= 11 AND NOT mf2.mvtsrc IS NULL
          GROUP BY
            mf2.mvtsrc
        ) AS s
          ON s.mvtsrc = mf.id
        WHERE
          mf.entree > 0
          AND (
            mf.mvtsrc IS NULL OR mf.mvtsrc = mf.id
          )
          AND (
            ms.idcategoriestock IS NULL OR ms.idcategoriestock <> 'CTGST000003'
          )
          AND ms.etat >= 11
      ) AS _0
    ) AS x
    LEFT JOIN public.mvtstock AS ms
      ON ms.id = x.idmvtstock
    LEFT JOIN public.as_bondelivraison AS b
      ON b.id = ms.idobjet
    LEFT JOIN public.as_bondelivraison AS bb
      ON b.id = ms.idtransfert
    LEFT JOIN public.facturefournisseur AS f
      ON f.id = b.idfacturefournisseur
    LEFT JOIN public.inventairefille AS invf
      ON invf.id = x.idinventairefille
    LEFT JOIN public.transfertstockdetails AS trs
      ON trs.id = x.idtransfertdetail
    WHERE
      NOT b.idfournisseur IS NULL
      OR NOT invf.idfournisseur IS NULL
      OR NOT bb.idfournisseur IS NULL
      OR NOT trs.idfournisseur IS NULL
  ) AS ve
  LEFT JOIN public.as_ingredients AS ai
    ON ai.id = ve.idproduit
  LEFT JOIN public.categorieingredient AS c
    ON ai.categorieingredient = c.id
  LEFT JOIN public.magasinpoint AS m
    ON ve.idmagasin = m.id
  LEFT JOIN public.as_unite AS u
    ON ai.unite = u.id
  LEFT JOIN public.fournisseur AS f
    ON f.id = ve.idfournisseur
  WHERE
    ve.pu > 0 AND CAST(ve.reste AS DECIMAL(30, 5)) <> 0
) AS sq;

-- Niveau 1 - vue 110 / 129 : V_ETATSTOCK_ENTREE_STANDARD
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_etatstock_entree_standard (
    "id", "daty", "invquantite", "entree", "sortie", "reste", "quantite", "montantreste", "idproduitlib", "categorieingredient", "unite", "typestock", "idunitelib", "idtypeproduitlib", "pu", "idfournisseur", "idfournisseurlib", "idproduit", "idmagasin", "idmagasinlib", "invdaty", "motsclesss"
) AS
WITH max_inventaire AS (
  SELECT
    invff.mvtsrc AS mvtsrc,
    MAX(imeref.daty) AS max_daty
  FROM public.inventairefille AS invff
  LEFT JOIN (
    SELECT
      i.id,
      TO_TIMESTAMP(
        NULLIF(
          CONCAT(
            (
              NULLIF(CONCAT(TO_CHAR(i.daty, CAST('YYYY-MM-DD' AS TEXT)), CAST(' ' AS TEXT)), '')
            ),
            CAST(COALESCE(i.heure, CAST('00:00:00' AS VARCHAR)) AS TEXT)
          ),
          ''
        ),
        CAST('YYYY-MM-DD HH24:MI:SS' AS TEXT)
      ) AS daty,
      i.designation,
      i.idmagasin,
      i.etat,
      i.remarque,
      i.idcategorie,
      i.heure
    FROM public.inventaire AS i
  ) AS imeref
    ON imeref.id = invff.idinventaire
  WHERE
    imeref.etat >= 11
  GROUP BY
    invff.mvtsrc
), inv_final_precalc AS (
  SELECT
    invfff.mvtsrc AS mvtsrc,
    invfff.quantite AS quantite,
    imm.daty AS invdaty
  FROM public.inventairefille AS invfff
  LEFT JOIN (
    SELECT
      i.id,
      TO_TIMESTAMP(
        NULLIF(
          CONCAT(
            (
              NULLIF(CONCAT(TO_CHAR(i.daty, CAST('YYYY-MM-DD' AS TEXT)), CAST(' ' AS TEXT)), '')
            ),
            CAST(COALESCE(i.heure, CAST('00:00:00' AS VARCHAR)) AS TEXT)
          ),
          ''
        ),
        CAST('YYYY-MM-DD HH24:MI:SS' AS TEXT)
      ) AS daty,
      i.designation,
      i.idmagasin,
      i.etat,
      i.remarque,
      i.idcategorie,
      i.heure
    FROM public.inventaire AS i
  ) AS imm
    ON imm.id = invfff.idinventaire
  INNER JOIN max_inventaire AS mi
    ON mi.mvtsrc = invfff.mvtsrc AND imm.daty = mi.max_daty
  WHERE
    imm.etat >= 11
), somme_precalc AS (
  SELECT
    mff.mvtsrc AS mvtsrc,
    COALESCE(SUM(mff.entree), 0) AS entree,
    COALESCE(SUM(mff.sortie), 0) AS sortie
  FROM public.mvtstockfille AS mff
  LEFT JOIN (
    SELECT
      m.id,
      m.designation,
      m.idmagasin,
      m.idvente,
      m.idtransfert,
      m.idtypemvstock,
      TO_TIMESTAMP(
        NULLIF(
          CONCAT(
            (
              NULLIF(CONCAT(TO_CHAR(m.daty, CAST('YYYY-MM-DD' AS TEXT)), CAST(' ' AS TEXT)), '')
            ),
            CAST(COALESCE(m.heure, CAST('00:00:00' AS VARCHAR)) AS TEXT)
          ),
          ''
        ),
        CAST('YYYY-MM-DD HH24:MI:SS' AS TEXT)
      ) AS daty,
      m.etat,
      m.idpoint,
      m.idobjet,
      m.fabprecedent,
      m.idcategoriestock,
      m.heure
    FROM public.mvtstock AS m
  ) AS meref
    ON meref.id = mff.idmvtstock
  LEFT JOIN inv_final_precalc AS inv
    ON inv.mvtsrc = mff.mvtsrc
  WHERE
    meref.daty > COALESCE(inv.invdaty, CAST('2025-01-01' AS DATE))
    AND meref.etat >= 11
    AND meref.idtypemvstock <> 'TPMVST000023'
  GROUP BY
    mff.mvtsrc
), main_data AS (
  SELECT
    mf.id AS id,
    mere.daty AS daty,
    CAST(COALESCE(invfinal.quantite, 0) AS DECIMAL(30, 2)) AS invquantite,
    CASE
      WHEN mere.daty > COALESCE(invfinal.invdaty, CAST('2025-01-01' AS DATE))
      THEN CAST(COALESCE(mf.entree, 0) AS DECIMAL(30, 2))
      ELSE CAST(0 AS DECIMAL(30, 2))
    END AS entree,
    CAST(COALESCE(somme.sortie, 0) AS DECIMAL(30, 2)) AS sortie,
    CASE
      WHEN mere.daty <= COALESCE(invfinal.invdaty, CAST('2025-01-01' AS DATE))
      THEN CAST(COALESCE(invfinal.quantite, 0) - COALESCE(somme.sortie, 0) AS DECIMAL(30, 2))
      ELSE CAST(COALESCE(invfinal.quantite, 0) + COALESCE(mf.entree, 0) - COALESCE(somme.sortie, 0) AS DECIMAL(30, 2))
    END AS reste,
    ai.libelle AS idproduitlib,
    ai.categorieingredient AS categorieingredient,
    ai.unite AS unite,
    ai.typestock AS typestock,
    u.val AS idunitelib,
    c.val AS idtypeproduitlib,
    mf.pu AS pu,
    b.idfournisseur AS idfournisseur,
    b.idfournisseurlib AS idfournisseurlib,
    mf.idproduit AS idproduit,
    mere.idmagasin AS idmagasin,
    m.val AS idmagasinlib,
    invfinal.invdaty AS invdaty
  FROM public.mvtstockfille AS mf
  LEFT JOIN (
    SELECT
      m.id,
      m.designation,
      m.idmagasin,
      m.idvente,
      m.idtransfert,
      m.idtypemvstock,
      TO_TIMESTAMP(
        NULLIF(
          CONCAT(
            (
              NULLIF(CONCAT(TO_CHAR(m.daty, CAST('YYYY-MM-DD' AS TEXT)), CAST(' ' AS TEXT)), '')
            ),
            CAST(COALESCE(m.heure, CAST('00:00:00' AS VARCHAR)) AS TEXT)
          ),
          ''
        ),
        CAST('YYYY-MM-DD HH24:MI:SS' AS TEXT)
      ) AS daty,
      m.etat,
      m.idpoint,
      m.idobjet,
      m.fabprecedent,
      m.idcategoriestock,
      m.heure
    FROM public.mvtstock AS m
  ) AS mere
    ON mere.id = mf.idmvtstock
  LEFT JOIN somme_precalc AS somme
    ON somme.mvtsrc = mf.id
  LEFT JOIN inv_final_precalc AS invfinal
    ON invfinal.mvtsrc = mf.id
  LEFT JOIN public.as_ingredients AS ai
    ON ai.id = mf.idproduit
  LEFT JOIN public.categorieingredient AS c
    ON c.id = ai.categorieingredient
  LEFT JOIN public.magasinpoint AS m
    ON m.id = mere.idmagasin
  LEFT JOIN public.as_unite AS u
    ON u.id = ai.unite
  LEFT JOIN (
    SELECT
      bl.id,
      bl.remarque,
      bl.idbc,
      bl.daty,
      bl.etat,
      bl.magasin,
      m.val AS magasinlib,
      CASE
        WHEN bl.etat = CAST(1 AS DECIMAL)
        THEN CAST('CR&Eacute;&Eacute;(E)' AS TEXT)
        WHEN bl.etat = CAST(11 AS DECIMAL)
        THEN CAST('VIS&Eacute;(E)' AS TEXT)
        ELSE CAST(NULL AS TEXT)
      END AS etatlib,
      bl.idfournisseur,
      f.nom AS idfournisseurlib,
      bl.idfacturefournisseur
    FROM public.as_bondelivraison AS bl
    LEFT JOIN public.magasin2 AS m
      ON CAST(bl.magasin AS TEXT) = CAST(m.id AS TEXT)
    LEFT JOIN public.fournisseur AS f
      ON CAST(f.id AS TEXT) = CAST(bl.idfournisseur AS TEXT)
  ) AS b
    ON b.id = mere.idobjet
  WHERE
    mf.entree > 0 AND mere.idtypemvstock <> 'TPMVST000023' AND mere.etat >= 11
), final_data AS (
  SELECT
    md.id AS id,
    md.daty AS daty,
    CAST(md.invquantite AS DECIMAL(30, 2)) AS invquantite,
    CAST(md.entree AS DECIMAL(30, 2)) AS entree,
    CAST(md.sortie AS DECIMAL(30, 2)) AS sortie,
    CAST(md.reste AS DECIMAL(30, 2)) AS reste,
    CAST(md.reste AS DECIMAL(30, 2)) AS quantite,
    CAST(md.reste * md.pu AS DECIMAL(30, 2)) AS montantreste,
    md.idproduitlib AS idproduitlib,
    md.categorieingredient AS categorieingredient,
    md.unite AS unite,
    md.typestock AS typestock,
    md.idunitelib AS idunitelib,
    md.idtypeproduitlib AS idtypeproduitlib,
    md.pu AS pu,
    md.idfournisseur AS idfournisseur,
    md.idfournisseurlib AS idfournisseurlib,
    md.idproduit AS idproduit,
    md.idmagasin AS idmagasin,
    md.idmagasinlib AS idmagasinlib,
    md.invdaty AS invdaty
  FROM main_data AS md
  WHERE
    md.reste <> 0
)
SELECT
  fd.id AS id,
  fd.daty AS daty,
  fd.invquantite AS invquantite,
  fd.entree AS entree,
  fd.sortie AS sortie,
  fd.reste AS reste,
  fd.quantite AS quantite,
  fd.montantreste AS montantreste,
  fd.idproduitlib AS idproduitlib,
  fd.categorieingredient AS categorieingredient,
  fd.unite AS unite,
  fd.typestock AS typestock,
  fd.idunitelib AS idunitelib,
  fd.idtypeproduitlib AS idtypeproduitlib,
  fd.pu AS pu,
  fd.idfournisseur AS idfournisseur,
  fd.idfournisseurlib AS idfournisseurlib,
  fd.idproduit AS idproduit,
  fd.idmagasin AS idmagasin,
  fd.idmagasinlib AS idmagasinlib,
  fd.invdaty AS invdaty,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(fd.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(fd.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    fd.invquantite
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    fd.invquantite
                  ) AS TEXT)))
                  ELSE CAST((
                    fd.invquantite
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    fd.entree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    fd.entree
                  ) AS TEXT)))
                  ELSE CAST((
                    fd.entree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    fd.sortie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    fd.sortie
                  ) AS TEXT)))
                  ELSE CAST((
                    fd.sortie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    fd.reste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    fd.reste
                  ) AS TEXT)))
                  ELSE CAST((
                    fd.reste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    fd.quantite
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    fd.quantite
                  ) AS TEXT)))
                  ELSE CAST((
                    fd.quantite
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    fd.montantreste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    fd.montantreste
                  ) AS TEXT)))
                  ELSE CAST((
                    fd.montantreste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(fd.idproduitlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.categorieingredient AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.unite AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.typestock AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.idunitelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.idtypeproduitlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    fd.pu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    fd.pu
                  ) AS TEXT)))
                  ELSE CAST((
                    fd.pu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(fd.idfournisseur AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.idfournisseurlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.idproduit AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.idmagasin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(fd.idmagasinlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(fd.invdaty, 'YYYY-MM-DD HH24:MI:SS'), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM final_data AS fd;

-- Niveau 1 - vue 111 / 129 : V_ETATSTOCK_ING_ENG
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_etatstock_ing_eng (
    "id", "idproduitlib", "categorieingredient", "idtypeproduitlib", "idmagasin", "idmagasinlib", "datederniermouvement", "quantite", "entree", "sortie", "reste", "unite", "idunitelib", "puvente", "idpoint", "idtypemagasin", "seuilmin", "seuilmax", "montantentree", "montantsortie", "pu", "montantreste", "libellevente", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.idproduitlib AS idproduitlib,
  base.categorieingredient AS categorieingredient,
  base.idtypeproduitlib AS idtypeproduitlib,
  base.idmagasin AS idmagasin,
  base.idmagasinlib AS idmagasinlib,
  base.datederniermouvement AS datederniermouvement,
  base.quantite AS quantite,
  base.entree AS entree,
  base.sortie AS sortie,
  base.reste AS reste,
  base.unite AS unite,
  base.idunitelib AS idunitelib,
  base.puvente AS puvente,
  base.idpoint AS idpoint,
  base.idtypemagasin AS idtypemagasin,
  base.seuilmin AS seuilmin,
  base.seuilmax AS seuilmax,
  base.montantentree AS montantentree,
  base.montantsortie AS montantsortie,
  base.pu AS pu,
  base.montantreste AS montantreste,
  base.libellevente AS libellevente,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idproduitlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.categorieingredient AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypeproduitlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idmagasin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idmagasinlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.datederniermouvement, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.quantite
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.quantite
                  ) AS TEXT)))
                  ELSE CAST((
                    base.quantite
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.entree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.entree
                  ) AS TEXT)))
                  ELSE CAST((
                    base.entree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.sortie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.sortie
                  ) AS TEXT)))
                  ELSE CAST((
                    base.sortie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.reste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.reste
                  ) AS TEXT)))
                  ELSE CAST((
                    base.reste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.unite AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idunitelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.puvente
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.puvente
                  ) AS TEXT)))
                  ELSE CAST((
                    base.puvente
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.idpoint AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idtypemagasin AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.seuilmin
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.seuilmin
                  ) AS TEXT)))
                  ELSE CAST((
                    base.seuilmin
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.seuilmax
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.seuilmax
                  ) AS TEXT)))
                  ELSE CAST((
                    base.seuilmax
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantentree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantentree
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantentree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantsortie
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantsortie
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantsortie
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.pu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.pu
                  ) AS TEXT)))
                  ELSE CAST((
                    base.pu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantreste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantreste
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantreste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.libellevente AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    p.id AS id,
    p.libelle AS idproduitlib,
    p.categorieingredient AS categorieingredient,
    tp.desce AS idtypeproduitlib,
    ms.idmagasin AS idmagasin,
    mag.val AS idmagasinlib,
    CAST('2001-01-01' AS DATE) AS datederniermouvement,
    CAST(ms.quantite AS DECIMAL(30, 5)) AS quantite,
    CAST(COALESCE(ms.entree, 0) AS DECIMAL(30, 5)) AS entree,
    CAST(COALESCE(ms.sortie, 0) AS DECIMAL(30, 5)) AS sortie,
    CAST(COALESCE(ms.quantite, 0) AS DECIMAL(30, 5)) AS reste,
    p.unite AS unite,
    u.desce AS idunitelib,
    CAST(COALESCE(p.pv, 0) AS DECIMAL(30, 5)) AS puvente,
    mag.idpoint AS idpoint,
    mag.idtypemagasin AS idtypemagasin,
    p.seuilmin AS seuilmin,
    p.seuilmax AS seuilmax,
    CAST(ms.montantentree AS DECIMAL(30, 5)) AS montantentree,
    CAST(ms.montantsortie AS DECIMAL(30, 5)) AS montantsortie,
    CAST(p.pu AS DECIMAL(30, 5)) AS pu,
    CAST(ms.montant AS DECIMAL(30, 5)) AS montantreste,
    p.libellevente AS libellevente
  FROM public.as_ingredients AS p
  LEFT JOIN public.montant_stock_eng AS ms
    ON ms.idproduit = p.id
  LEFT JOIN public.categorieingredient AS tp
    ON tp.id = p.categorieingredient
  LEFT JOIN public.magasinpoint AS mag
    ON mag.id = ms.idmagasin
  LEFT JOIN public.as_unite AS u
    ON u.id = p.unite
  WHERE
    COALESCE(ms.entree, 0) > 0 OR COALESCE(ms.sortie, 0) > 0
) AS base;

-- Niveau 1 - vue 112 / 129 : V_ETATSTOCK_ING_VENTE
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_etatstock_ing_vente (
    "id", "idproduitlib", "idmagasin", "idmagasinlib", "physique", "engage", "afacturer", "montantentree", "montantsortie", "montantreste", "unite", "idunitelib", "pu"
) AS
SELECT
  ai.id AS id,
  ai.libellevente AS idproduitlib,
  m.id AS idmagasin,
  m.val AS idmagasinlib,
  CAST(ve.reste AS DECIMAL(30, 2)) AS physique,
  COALESCE(CAST(ste.sortie AS DECIMAL(30, 2)), 0) AS engage,
  COALESCE(
    (
      CAST(ve.reste AS DECIMAL(30, 2)) - COALESCE(CAST(ste.sortie AS DECIMAL(30, 2)), 0)
    ),
    0
  ) AS afacturer,
  CAST(COALESCE(ve.entree * ve.pu, 0) AS DECIMAL(30, 2)) AS montantentree,
  CAST(COALESCE(ve.sortie * ve.pu, 0) AS DECIMAL(30, 2)) AS montantsortie,
  CAST(COALESCE((
    ve.entree * ve.pu
  ) - (
    ve.sortie * ve.pu
  ), 0) AS DECIMAL(30, 2)) AS montantreste,
  ai.unite AS unite,
  u.val AS idunitelib,
  CASE
    WHEN ve.reste <> 0
    THEN CAST(COALESCE(
      (
        CAST((
          (
            ve.entree * ve.pu
          ) - (
            ve.sortie * ve.pu
          )
        ) AS DECIMAL) / COALESCE(ve.reste, 1)
      ),
      0
    ) AS DECIMAL(30, 2))
    ELSE CAST(ai.pu AS DECIMAL(30, 2))
  END AS pu
FROM (
  SELECT
    mf.idproduit AS idproduit,
    SUM(mf.entree) AS entree,
    SUM(mf.sortie) AS sortie,
    NULL AS idventedetail,
    NULL AS idtransfertdetail,
    AVG(mf.pu) AS pu,
    NULL AS mvtsrc,
    NULL AS daty,
    (
      SUM(mf.entree) - SUM(mf.sortie)
    ) AS reste,
    0 AS quantite,
    m.idmagasin AS idmagasin
  FROM public.mvtstockfille AS mf
  LEFT JOIN public.mvtstock AS m
    ON m.id = mf.idmvtstock
  WHERE
    m.etat >= 11
  GROUP BY
    mf.idproduit,
    m.idmagasin
) AS ve
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = ve.idproduit
LEFT JOIN public.categorieingredient AS c
  ON ai.categorieingredient = c.id
LEFT JOIN public.magasinpoint AS m
  ON ve.idmagasin = m.id
LEFT JOIN public.as_unite AS u
  ON ai.unite = u.id
LEFT JOIN public.stock_engage_fille_gp_mag AS ste
  ON ste.idproduit = ve.idproduit AND ste.idmagasin = ve.idmagasin
WHERE
  ai.categorieingredient = 'CAT008';

-- Niveau 1 - vue 113 / 129 : V_FORMATION_BILAN_PAR_TYPE
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_formation_bilan_par_type (
    "annee", "nbinterne", "nbexterne", "motsclesss"
) AS
SELECT
  base.annee AS annee,
  base.nbinterne AS nbinterne,
  base.nbexterne AS nbexterne,
  (
    NULLIF(
      CONCAT(
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbinterne
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbinterne
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbinterne
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbexterne
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbexterne
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbexterne
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    pf.annee AS annee,
    SUM(CASE WHEN af.typeprestataire = '0' THEN 1 ELSE 0 END) AS nbinterne,
    SUM(CASE WHEN af.typeprestataire = '1' THEN 1 ELSE 0 END) AS nbexterne
  FROM public.action_formation AS af
  LEFT JOIN public.plan_formation_annuel AS pf
    ON pf.id = af.idplanformation
  GROUP BY
    pf.annee
) AS base;

