-- Niveau 1 - vue 115 / 129 : V_INVENTAIREFILLECPL
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_inventairefillecpl (
    "id", "idinventaire", "idproduit", "idproduitlib", "explication", "quantitetheorique", "quantite", "libelleextacte", "pu", "ecart", "dateinv", "montanttheorique", "montantreelle", "ecartmontant", "categorieingredient", "motsclesss", "idmagasin", "idmagasinlib"
) AS
SELECT
  base.id AS id,
  base.idinventaire AS idinventaire,
  base.idproduit AS idproduit,
  base.idproduitlib AS idproduitlib,
  base.explication AS explication,
  base.quantitetheorique AS quantitetheorique,
  base.quantite AS quantite,
  base.libelleextacte AS libelleextacte,
  base.pu AS pu,
  base.ecart AS ecart,
  base.dateinv AS dateinv,
  base.montanttheorique AS montanttheorique,
  base.montantreelle AS montantreelle,
  base.ecartmontant AS ecartmontant,
  base.categorieingredient AS categorieingredient,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idinventaire AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idproduit AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idproduitlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.explication AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.quantitetheorique
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.quantitetheorique
                  ) AS TEXT)))
                  ELSE CAST((
                    base.quantitetheorique
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.quantite
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.quantite
                  ) AS TEXT)))
                  ELSE CAST((
                    base.quantite
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.libelleextacte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.pu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.pu
                  ) AS TEXT)))
                  ELSE CAST((
                    base.pu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.ecart
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.ecart
                  ) AS TEXT)))
                  ELSE CAST((
                    base.ecart
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(TO_CHAR(base.dateinv, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montanttheorique
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montanttheorique
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montanttheorique
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantreelle
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantreelle
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantreelle
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.ecartmontant
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.ecartmontant
                  ) AS TEXT)))
                  ELSE CAST((
                    base.ecartmontant
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.categorieingredient AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss,
  base.idmagasin AS idmagasin,
  base.idmagasinlib AS idmagasinlib
FROM (
  SELECT
    i.id AS id,
    i.idinventaire AS idinventaire,
    i.idproduit AS idproduit,
    p.libelle AS idproduitlib,
    i.explication AS explication,
    CAST(COALESCE(i.quantitetheorique, 0) AS DECIMAL(30, 6)) AS quantitetheorique,
    CAST(COALESCE(i.quantite, 0) AS DECIMAL(30, 6)) AS quantite,
    p.libelleextacte AS libelleextacte,
    CAST(COALESCE(i.pu, 0) AS DECIMAL(30, 6)) AS pu,
    CAST(COALESCE(i.quantite, 0) - COALESCE(i.quantitetheorique, 0) AS DECIMAL(30, 6)) AS ecart,
    iv.daty AS dateinv,
    CAST(COALESCE(i.pu, 0) * COALESCE(i.quantitetheorique, 0) AS DECIMAL(30, 6)) AS montanttheorique,
    CAST(COALESCE(i.pu, 0) * COALESCE(i.quantite, 0) AS DECIMAL(30, 6)) AS montantreelle,
    CAST((
      COALESCE(i.pu, 0) - COALESCE(i.quantite, 0)
    ) - (
      COALESCE(i.pu, 0) - COALESCE(i.quantitetheorique, 0)
    ) AS DECIMAL(30, 6)) AS ecartmontant,
    p.categorieingredient AS categorieingredient,
    iv.idmagasin AS idmagasin,
    m.val AS idmagasinlib
  FROM public.inventairefille AS i
  LEFT JOIN public.inventaire AS iv
    ON iv.id = i.idinventaire
  LEFT JOIN public.as_ingredients AS p
    ON p.id = i.idproduit
  LEFT JOIN public.magasin2 AS m
    ON iv.idmagasin = m.id
  WHERE
    iv.etat >= 11
) AS base;

-- Niveau 1 - vue 116 / 129 : V_JOURS_2016_NOW
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_jours_2016_now (
    "daty", "jour", "semainemois", "mois", "annee", "numerojoursemaine", "jourlib"
) AS
SELECT
  g.d AS daty,
  EXTRACT(DAY FROM g.d) AS jour,
  CEIL(
    CAST((
      EXTRACT(DAY FROM g.d) + EXTRACT(ISODOW FROM DATE_TRUNC('MONTH', g.d)) - 1
    ) AS DECIMAL) / 7.0
  ) AS semainemois,
  EXTRACT(MONTH FROM g.d) AS mois,
  EXTRACT(YEAR FROM g.d) AS annee,
  CAST(CAST(EXTRACT(ISODOW FROM g.d) AS INT) AS TEXT) AS numerojoursemaine,
  RPAD(
    CAST((
      ARRAY['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche']
    )[CAST(EXTRACT(ISODOW FROM g.d) AS INT) + 0] AS TEXT),
    8,
    ' '
  ) AS jourlib
FROM GENERATE_SERIES(
  CAST('2025-05-01' AS TIMESTAMP),
  DATE_TRUNC('MONTH', LOCALTIMESTAMP(0)) + INTERVAL '1 MONTH' - INTERVAL '1 DAY',
  INTERVAL '1 DAY'
) AS g(d);

-- Niveau 1 - vue 117 / 129 : V_MOIS_ANNEE_DISTINCTS
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_mois_annee_distincts (
    "mois", "annee", "moislib"
) AS
SELECT
  EXTRACT(MONTH FROM g.dt) AS mois,
  EXTRACT(YEAR FROM g.dt) AS annee,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM g.dt) AS INT) + 0] AS moislib
FROM GENERATE_SERIES(
  CAST('2025-05-01' AS TIMESTAMP),
  DATE_TRUNC('MONTH', LOCALTIMESTAMP(0)),
  INTERVAL '1 MONTH'
) AS g(dt)
ORDER BY
  annee,
  mois;

-- Niveau 1 - vue 118 / 129 : V_NEXT_FACTURE_FOURNISSEUR
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_next_facture_fournisseur (
    "prefixe", "date_facture", "nextnum"
) AS
SELECT
  NULLIF(
    CONCAT(
      facturefournisseurcpl.typeachat,
      '-',
      NULLIF(SUBSTRING(facturefournisseurcpl.idfournisseurlib FROM 1 FOR 1), '')
    ),
    ''
  ) AS prefixe,
  facturefournisseurcpl.daty AS date_facture,
  LPAD(CAST(COUNT(*) + 1 AS TEXT), 2, '0') AS nextnum
FROM (
  SELECT
    f.id,
    f.idfournisseur,
    f2.nom AS idfournisseurlib,
    f.idmodepaiement,
    m.val AS idmodepaiementlib,
    f.daty,
    f.designation,
    f.dateecheancepaiement,
    f.etat,
    CASE
      WHEN f.etat = CAST(1 AS DECIMAL)
      THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
      WHEN f.etat = CAST(0 AS DECIMAL)
      THEN CAST('ANNUL&Eacute;E' AS TEXT)
      WHEN f.etat = CAST(11 AS DECIMAL)
      THEN CAST('VIS&Eacute;E' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS etatlib,
    COALESCE(f.reference, reff.reference) AS reference,
    f.idbc,
    f.idmagasin,
    f.devise,
    CASE WHEN f.taux = CAST(0 AS DECIMAL) THEN CAST(1 AS DECIMAL) ELSE f.taux END AS taux,
    p.val AS idmagasinlib,
    f3.iddevise,
    CAST(f3.montanttva AS DECIMAL(30, 5)) AS montanttva,
    CAST((
      f3.montantttc - f3.montanttva
    ) AS DECIMAL(30, 5)) AS montantht,
    CAST(f3.montantttc AS DECIMAL(30, 5)) AS montantttc,
    CAST((
      f3.montantttc * f3.tauxdechange
    ) AS DECIMAL(30, 5)) AS montantttcar,
    CAST(COALESCE(mv.debit, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
    CAST((
      f3.montantttc - COALESCE(mv.debit, CAST(0 AS DECIMAL))
    ) AS DECIMAL(30, 5)) AS montantreste,
    CAST(COALESCE(f3.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS tauxdechange,
    prev.id AS idprevision,
    CASE
      WHEN f.estprevu = CAST(0 AS DECIMAL)
      THEN CAST('NON' AS TEXT)
      ELSE CAST('OUI' AS TEXT)
    END AS estprevulib,
    f.idobjet,
    f.idref,
    f.idtypefacture,
    tf.val AS typefacture,
    f.numero,
    f.typeachat,
    f.idfactureprincipale,
    s.libelle AS idservicelib,
    f.service,
    f.typefacturefournisseur,
    tff.desce AS typefacturefournisseurlib,
    ce.id AS idecriture,
    ta.val AS typeachatlib
  FROM public.facturefournisseur AS f
  LEFT JOIN public.typeachat AS ta
    ON CAST(ta.desce AS TEXT) = CAST(f.typeachat AS TEXT)
  LEFT JOIN public.fournisseur AS f2
    ON CAST(f2.id AS TEXT) = CAST(f.idfournisseur AS TEXT)
  LEFT JOIN public.modepaiement AS m
    ON CAST(m.id AS TEXT) = CAST(f.idmodepaiement AS TEXT)
  LEFT JOIN (
    SELECT
      p.id,
      p.val,
      p.desce,
      p.id AS idpoint,
      CAST('-' AS TEXT) AS idproduit,
      CAST(NULL AS TEXT) AS idtypemagasin,
      11 AS etat
    FROM public.point AS p
  ) AS p
    ON CAST(p.id AS TEXT) = CAST(f.idmagasin AS TEXT)
  JOIN (
    SELECT
      v.id,
      CAST(SUM(
        (
          CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
        ) * (
          COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
        )
      ) AS DECIMAL(30, 2)) AS montanttotal,
      CAST(SUM(
        (
          CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
        ) * (
          COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
        ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
      ) AS DECIMAL(30, 2)) AS montanttva,
      CAST((
        SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) + SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          )
        )
      ) AS DECIMAL(30, 2)) AS montantttc,
      COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
      COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) AS tauxdechange
    FROM public.facturefournisseurfille AS vd
    LEFT JOIN public.facturefournisseur AS v
      ON CAST(v.id AS TEXT) = CAST(vd.idfacturefournisseur AS TEXT)
    GROUP BY
      v.id,
      vd.iddevise,
      vd.tauxdechange
  ) AS f3
    ON CAST(f.id AS TEXT) = CAST(f3.id AS TEXT)
  LEFT JOIN public.mouvementcaissegroupefacture AS mv
    ON CAST(f.id AS TEXT) = CAST(mv.idorigine AS TEXT)
  LEFT JOIN public.prevision AS prev
    ON CAST(prev.idfacture AS TEXT) = CAST(f.id AS TEXT)
  LEFT JOIN public.type_facture AS tf
    ON CAST(tf.id AS TEXT) = CAST(f.idtypefacture AS TEXT)
  LEFT JOIN public.service AS s
    ON CAST(f.service AS TEXT) = CAST(s.compte AS TEXT)
  LEFT JOIN public.referencefacture AS reff
    ON CAST(f.id AS TEXT) = CAST(reff.idfacture AS TEXT)
  LEFT JOIN public.typefacturefournisseur AS tff
    ON CAST(tff.id AS TEXT) = CAST(f.typefacturefournisseur AS TEXT)
  LEFT JOIN public.compta_ecriture AS ce
    ON CAST(ce.idobjet AS TEXT) = CAST(f.id AS TEXT)
) AS facturefournisseurcpl
WHERE
  facturefournisseurcpl.etat >= 11
GROUP BY
  NULLIF(
    CONCAT(
      facturefournisseurcpl.typeachat,
      '-',
      NULLIF(SUBSTRING(facturefournisseurcpl.idfournisseurlib FROM 1 FOR 1), '')
    ),
    ''
  ),
  facturefournisseurcpl.daty;

-- Niveau 1 - vue 119 / 129 : V_NUMEROAVOIR_EN_COURS
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_numeroavoir_en_cours (
    "annee_en_cours", "dernier_num", "prochain_num", "prochain_num_format"
) AS
SELECT
  EXTRACT(YEAR FROM LOCALTIMESTAMP(0)) AS annee_en_cours,
  COALESCE(
    MAX(
      CAST(NULLIF(SUBSTRING(avoirfc.numavoir FROM 1 FOR POSITION('/' IN avoirfc.numavoir) - 1), '') AS DECIMAL)
    ),
    0
  ) AS dernier_num,
  COALESCE(
    MAX(
      CAST(NULLIF(SUBSTRING(avoirfc.numavoir FROM 1 FOR POSITION('/' IN avoirfc.numavoir) - 1), '') AS DECIMAL)
    ),
    0
  ) + 1 AS prochain_num,
  NULLIF(
    CONCAT(
      LPAD(
        CAST(COALESCE(
          MAX(
            CAST(NULLIF(SUBSTRING(avoirfc.numavoir FROM 1 FOR POSITION('/' IN avoirfc.numavoir) - 1), '') AS DECIMAL)
          ),
          0
        ) + 1 AS TEXT),
        4,
        '0'
      ),
      '/',
      REPLACE(
        REGEXP_REPLACE(
          (
            CASE
              WHEN POSITION('.' IN CAST((
                EXTRACT(YEAR FROM LOCALTIMESTAMP(0))
              ) AS TEXT)) > 0
              THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                EXTRACT(YEAR FROM LOCALTIMESTAMP(0))
              ) AS TEXT)))
              ELSE CAST((
                EXTRACT(YEAR FROM LOCALTIMESTAMP(0))
              ) AS TEXT)
            END
          ),
          '^(-?)0[.]',
          e'\\1.'
        ),
        '.',
        ','
      )
    ),
    ''
  ) AS prochain_num_format
FROM public.avoirfc AS avoirfc
WHERE
  NULLIF(SUBSTRING(avoirfc.numavoir FROM POSITION('/' IN avoirfc.numavoir) + 1), '') = REPLACE(
    REGEXP_REPLACE(
      (
        CASE
          WHEN POSITION('.' IN CAST((
            EXTRACT(YEAR FROM LOCALTIMESTAMP(0))
          ) AS TEXT)) > 0
          THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
            EXTRACT(YEAR FROM LOCALTIMESTAMP(0))
          ) AS TEXT)))
          ELSE CAST((
            EXTRACT(YEAR FROM LOCALTIMESTAMP(0))
          ) AS TEXT)
        END
      ),
      '^(-?)0[.]',
      e'\\1.'
    ),
    '.',
    ','
  );

