-- Niveau 1 - vue 123 / 129 : V_POINTAGE_KPI_RETARD
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_pointage_kpi_retard (
    "daty", "nb_retards", "retard_moyen_minutes"
) AS
WITH premier_pointage AS (
  SELECT
    pm.daty AS daty,
    pm.idpersonnel AS idpersonnel,
    MIN(pm.heure) AS heure
  FROM public.pointage_magasinier AS pm
  WHERE
    pm.idtypepointage = 'TP000001'
  GROUP BY
    pm.daty,
    pm.idpersonnel
), horaire AS (
  SELECT
    conf_horaire.heurearriveenormal AS heurearriveenormal
  FROM public.conf_horaire AS conf_horaire
  WHERE
    TRUE
  LIMIT 1
)
SELECT
  p.daty AS daty,
  COUNT(*) AS nb_retards,
  ROUND(
    CAST(AVG(
      (
        (
          EXTRACT(EPOCH FROM (
            CAST(TO_TIMESTAMP(CAST(p.heure AS TEXT), 'HH24:MI:SS') AS TIMESTAMP) - CAST(TO_TIMESTAMP(CAST(h.heurearriveenormal AS TEXT), 'HH24:MI:SS') AS TIMESTAMP)
          )) / 86400.0
        )
      ) * 24 * 60
    ) AS DECIMAL),
    0
  ) AS retard_moyen_minutes
FROM premier_pointage AS p
CROSS JOIN horaire AS h
WHERE
  CAST(TO_TIMESTAMP(CAST(p.heure AS TEXT), 'HH24:MI:SS') AS TIMESTAMP) > CAST(TO_TIMESTAMP(CAST(h.heurearriveenormal AS TEXT), 'HH24:MI:SS') AS TIMESTAMP)
GROUP BY
  p.daty;

-- Niveau 1 - vue 124 / 129 : V_PROG_INTEGRATION_DETAIL_LIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_prog_integration_detail_lib (
    "id", "idprogramedetail", "jourdelasemaine", "heure", "duree", "actiontheme", "contenue", "idintervenant", "idintervenantlib", "idintervenantfonction", "idintervenantfonctionlib", "idintervenantservice", "idintervenantservicelib", "duree_effective"
) AS
SELECT
  pd.id AS id,
  pd.idprogramedetail AS idprogramedetail,
  CASE
    WHEN CAST(pd.jourdelasemaine AS DECIMAL) = 1
    THEN 'Lundi'
    WHEN CAST(pd.jourdelasemaine AS DECIMAL) = 2
    THEN 'Mardi'
    WHEN CAST(pd.jourdelasemaine AS DECIMAL) = 3
    THEN 'Mercredi'
    WHEN CAST(pd.jourdelasemaine AS DECIMAL) = 4
    THEN 'Jeudi'
    WHEN CAST(pd.jourdelasemaine AS DECIMAL) = 5
    THEN 'Vendredi'
    WHEN CAST(pd.jourdelasemaine AS DECIMAL) = 6
    THEN 'Samedi'
    WHEN CAST(pd.jourdelasemaine AS DECIMAL) = 7
    THEN 'Dimanche'
    ELSE 'Inconnu'
  END AS jourdelasemaine,
  pd.heure AS heure,
  pd.duree AS duree,
  pd.actiontheme AS actiontheme,
  pd.contenue AS contenue,
  pd.idintervenant AS idintervenant,
  NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS idintervenantlib,
  paie.idfonction AS idintervenantfonction,
  f.val AS idintervenantfonctionlib,
  lp.service AS idintervenantservice,
  s.libelle AS idintervenantservicelib,
  (
    pd.duree * 2
  ) AS duree_effective
FROM public.programme_integration_detail AS pd
LEFT JOIN public.log_personnel AS lp
  ON pd.idintervenant = lp.id
LEFT JOIN public.paie_info_personnel AS paie
  ON lp.id = paie.id
LEFT JOIN public.paie_fonction AS f
  ON paie.idfonction = f.id
LEFT JOIN public.log_service AS s
  ON lp.service = s.id;

