) AS
SELECT
  base.annee AS annee,
  base.ref_formation AS ref_formation,
  base.type_formation AS type_formation,
  base.type_formationlib AS type_formationlib,
  base.categorie AS categorie,
  base.categorielib AS categorielib,
  base.intitule AS intitule,
  base.semestre AS semestre,
  base.semestrelib AS semestrelib,
  base.interne_externe AS interne_externe,
  base.formateur AS formateur,
  base.formateurlib AS formateurlib,
  base.type_cout_id AS type_cout_id,
  base.type_cout_lib AS type_cout_lib,
  base.montant_cout AS montant_cout,
  base.nombre_session AS nombre_session,
  base.nb_participant_ouvriers AS nb_participant_ouvriers,
  base.nb_participant_cadres AS nb_participant_cadres,
  base.nb_participant_total AS nb_participant_total,
  base.duree_par_stagiaire AS duree_par_stagiaire,
  base.duree_totale_heure AS duree_totale_heure,
  (
    NULLIF(
      CONCAT(
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.ref_formation AS VARCHAR(4000)), NULL),
