        COALESCE(CAST(base.type_formationlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.categorie AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.categorielib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.intitule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.semestre AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.semestrelib AS VARCHAR(4000)), NULL),
