                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nb_participant_total
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nb_participant_total
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nb_participant_total
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.duree_par_stagiaire
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.duree_par_stagiaire
                  ) AS TEXT)))
                  ELSE CAST((
                    base.duree_par_stagiaire
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.duree_totale_heure
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.duree_totale_heure
                  ) AS TEXT)))
                  ELSE CAST((
                    base.duree_totale_heure
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    pfa.annee AS annee,
    af.reference AS ref_formation,
    af.idtypeformation AS type_formation,
    tf.val AS type_formationlib,
    af.idcategorieformation AS categorie,
    cf.val AS categorielib,
    af.intitule AS intitule,
    af.idsemestre AS semestre,
    s.val AS semestrelib,
    CASE af.typeprestataire
      WHEN '0'
      THEN 'INTERNE'
      WHEN '1'
      THEN 'EXTERNE'
      ELSE 'AUTRE'
    END AS interne_externe,
    af.formateur AS formateur,
    f.libelle AS formateurlib,
    tcf.id AS type_cout_id,
    tcf.val AS type_cout_lib,
    COALESCE(cout.montant, 0) AS montant_cout,
    COALESCE(sess.nb_session, 0) AS nombre_session,
    COALESCE(af.nbouvriersprevue, 0) AS nb_participant_ouvriers,
    COALESCE(af.nbcadreprevue, 0) AS nb_participant_cadres,
    COALESCE(af.nbouvriersprevue, 0) + COALESCE(af.nbcadreprevue, 0) AS nb_participant_total,
    COALESCE(af.dureestagiaireheure, 0) AS duree_par_stagiaire,
    COALESCE(af.dureestagiaireheure, 0) * (
      COALESCE(af.nbouvriersprevue, 0) + COALESCE(af.nbcadreprevue, 0)
    ) AS duree_totale_heure
  FROM public.plan_formation_annuel AS pfa
  JOIN public.action_formation AS af
    ON af.idplanformation = pfa.id
  LEFT JOIN public.type_formation AS tf
    ON tf.id = af.idtypeformation
  LEFT JOIN public.categorie_formation AS cf
    ON cf.id = af.idcategorieformation
  LEFT JOIN public.semestre AS s
    ON s.id = af.idsemestre
  LEFT JOIN public.formateur AS f
    ON f.id = af.formateur
  LEFT JOIN (
    SELECT
      sf.idactionformation AS idactionformation,
      COUNT(*) AS nb_session
    FROM public.session_formation AS sf
    GROUP BY
      sf.idactionformation
  ) AS sess
    ON sess.idactionformation = af.id
  LEFT JOIN (
    SELECT
      afd.idactionformation AS idactionformation,
      afd.idtypecout AS idtypecout,
      SUM(afd.cout) AS montant
    FROM public.action_formation_detail AS afd
    GROUP BY
      afd.idactionformation,
      afd.idtypecout
  ) AS cout
    ON cout.idactionformation = af.id
  LEFT JOIN public.type_cout_formation AS tcf
    ON tcf.id = cout.idtypecout
) AS base;

-- Niveau 1 - vue 126 / 129 : V_REFCOULEUR_AVECCODE
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_refcouleur_aveccode (
    "referencecouleur", "nomcouleur", "codecouleur"
) AS
SELECT
  c.referencecouleur AS referencecouleur,
  NULLIF(
    CONCAT(STRING_AGG(cc.val, ' - '
    ORDER BY
      c.referencecouleur), '-', c.referencecouleur),
    ''
  ) AS nomcouleur,
  STRING_AGG(cc.desce, ' - '
  ORDER BY
    c.referencecouleur) AS codecouleur
FROM public.combinaisoncouleur AS c
LEFT JOIN public.couleur AS cc
  ON c.idcouleur = cc.id
GROUP BY
  c.referencecouleur;

-- Niveau 1 - vue 127 / 129 : V_REFERENCE_COULEUR
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_reference_couleur (
    "referencecouleur", "nomcouleur", "codecouleur"
) AS
SELECT
  c.referencecouleur AS referencecouleur,
  STRING_AGG(cc.val, ' - '
  ORDER BY
    c.referencecouleur) AS nomcouleur,
  STRING_AGG(cc.desce, ' - '
  ORDER BY
    c.referencecouleur) AS codecouleur
FROM public.combinaisoncouleur AS c
LEFT JOIN public.couleur AS cc
  ON c.idcouleur = cc.id
GROUP BY
  c.referencecouleur;

-- Niveau 1 - vue 128 / 129 : V_STATISTIQUE_CA
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_statistique_ca (
    "annee", "daty", "ca_du_jour", "meilleur_ca_semaine", "meilleur_ca_mois", "ca_annee", "ca_janvier", "ca_fevrier", "ca_mars", "ca_avril", "ca_mai", "ca_juin", "ca_juillet", "ca_aout", "ca_septembre", "ca_octobre", "ca_novembre", "ca_decembre"
) AS
WITH ca_par_vente AS (
  SELECT
    v.id AS idvente,
    DATE_TRUNC('DAY', v.daty) AS daty,
    SUM(COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0)) - COALESCE(v.fraislivraison, 0) AS ca_vente
  FROM public.vente AS v
  JOIN public.vente_details AS vd
    ON vd.idvente = v.id
  WHERE
    NOT v.daty IS NULL AND v.etat >= 11
  GROUP BY
    v.id,
    DATE_TRUNC('DAY', v.daty),
    v.fraislivraison
), ca_par_jour AS (
  SELECT
    ca_par_vente.daty AS daty,
    SUM(ca_par_vente.ca_vente) AS ca
  FROM ca_par_vente AS ca_par_vente
  GROUP BY
    ca_par_vente.daty
)
SELECT
  EXTRACT(YEAR FROM LOCALTIMESTAMP(0)) AS annee,
  DATE_TRUNC('day', LOCALTIMESTAMP(0)) AS daty,
  COALESCE(
    MAX(
      CASE
        WHEN ca_par_jour.daty = DATE_TRUNC('day', LOCALTIMESTAMP(0))
        THEN ca_par_jour.ca
      END
    ),
    0
  ) AS ca_du_jour, /* CA du jour */
  COALESCE(
    MAX(
      CASE
        WHEN ca_par_jour.daty >= DATE_TRUNC('week', LOCALTIMESTAMP(0))
        AND ca_par_jour.daty < (
          DATE_TRUNC('WEEK', LOCALTIMESTAMP(0)) + (
            7
          ) * INTERVAL '1 DAY'
        )
        THEN ca_par_jour.ca
      END
    ),
    0
  ) AS meilleur_ca_semaine, /* Meilleur CA journalier de la semaine */
  COALESCE(
    MAX(
      CASE
        WHEN ca_par_jour.daty >= DATE_TRUNC('month', LOCALTIMESTAMP(0))
        AND ca_par_jour.daty < (
          DATE_TRUNC('MONTH', LOCALTIMESTAMP(0)) + (
            1
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
      END
    ),
    0
  ) AS meilleur_ca_mois, /* Meilleur CA journalier du mois */
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= DATE_TRUNC('year', LOCALTIMESTAMP(0))
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            12
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_annee, /* CA total de l'annee */
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= DATE_TRUNC('year', LOCALTIMESTAMP(0))
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            1
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_janvier, /* CA par mois de l'annee courante */
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            1
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            2
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_fevrier,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            2
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            3
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_mars,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            3
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            4
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_avril,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            4
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            5
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_mai,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            5
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            6
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_juin,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            6
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            7
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_juillet,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            7
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            8
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_aout,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            8
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            9
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_septembre,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            9
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            10
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_octobre,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            10
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            11
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_novembre,
  COALESCE(
    SUM(
      CASE
        WHEN ca_par_jour.daty >= (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            11
          ) * INTERVAL '1 MONTH'
        )
        AND ca_par_jour.daty < (
          DATE_TRUNC('YEAR', LOCALTIMESTAMP(0)) + (
            12
          ) * INTERVAL '1 MONTH'
        )
        THEN ca_par_jour.ca
        ELSE 0
      END
    ),
    0
  ) AS ca_decembre
FROM ca_par_jour AS ca_par_jour;

-- Niveau 1 - vue 129 / 129 : V_UTILISATEURLIB
-- Dependances nouvelles : aucune.
CREATE VIEW public.v_utilisateurlib (
    "refuser", "loginuser", "pwduser", "nomuser", "adruser", "teluser", "idrole", "descrole", "idpersonnel", "motsclesss"
) AS
SELECT
  u.refuser AS refuser,
  u.loginuser AS loginuser,
  u.pwduser AS pwduser,
  u.nomuser AS nomuser,
  u.adruser AS adruser,
  u.teluser AS teluser,
  u.idrole AS idrole,
  r.descrole AS descrole,
  up.idpersonnel AS idpersonnel,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(u.refuser AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(u.loginuser AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(u.nomuser AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(u.adruser AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(u.teluser AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(u.idrole AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(r.descrole AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(up.idpersonnel AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.utilisateur AS u
LEFT JOIN public.roles AS r
  ON r.idrole = u.idrole
LEFT JOIN public.utilisateur_personnel AS up
  ON CAST(up.idutilisateur AS DECIMAL) = u.refuser;

COMMIT;

