-- Niveau 2 - vue 1 / 100 : AS_BC_RESTE_A_FACTURER
-- Dependances nouvelles : FF_FILLEBL_GRP.
CREATE VIEW public.as_bc_reste_a_facturer (
    "id", "idbc", "produitlib", "unitelib", "produit", "quantite", "qtelivrer", "qtefacturer", "fournisseur", "fournisseurlib", "daty"
) AS
SELECT
  bc.id AS id,
  bc.idbc AS idbc,
  bc.produitlib AS produitlib,
  bc.unitelib AS unitelib,
  bc.produit AS produit,
  COALESCE(bc.quantite, 0) AS quantite,
  COALESCE(bl.qte, 0) AS qtelivrer,
  COALESCE(ffm.qte, 0) AS qtefacturer, /* nvl(ff.qte + ffm.qte,0) AS qtefacturer */
  bc.fournisseur AS fournisseur,
  bc.fournisseurlib AS fournisseurlib,
  bc.daty AS daty
FROM public.as_bondecommande_cpl AS bc
LEFT JOIN public.ff_fillebl_grp AS bl
  ON bc.id = bl.idbc_fille
/* LEFT JOIN ff_fillebc_grp ff ON bc.id = ff.IDBCDETAIL */
LEFT JOIN public.ff_fillebc_grp_mere AS ffm
  ON ffm.idbc = bc.idbc AND ffm.idproduit = bc.produit;

-- Niveau 2 - vue 2 / 100 : AS_BONDECOMMANDE_CPL_RECEPT
-- Dependances nouvelles : FF_FILLEBL_GRP.
CREATE VIEW public.as_bondecommande_cpl_recept (
    "id", "idbc", "produitlib", "unitelib", "produit", "quantite", "qtelivrer", "qtefacturer"
) AS
SELECT
  bc.id AS id,
  bc.idbc AS idbc,
  bc.produitlib AS produitlib,
  bc.unitelib AS unitelib,
  bc.produit AS produit,
  COALESCE(bc.quantite, 0) AS quantite,
  COALESCE(bl.qte, 0) AS qtelivrer,
  COALESCE(ffm.qte, 0) AS qtefacturer /* nvl(ff.qte + ffm.qte,0) AS qtefacturer */
FROM public.as_bondecommande_cpl AS bc
LEFT JOIN public.ff_fillebl_grp AS bl
  ON bc.id = bl.idbc_fille
/* LEFT JOIN ff_fillebc_grp ff ON bc.id = ff.IDBCDETAIL */
LEFT JOIN public.ff_fillebc_grp_mere AS ffm
  ON ffm.idbc = bc.idbc AND ffm.idproduit = bc.produit;

-- Niveau 2 - vue 3 / 100 : AS_INGREDIENTS_LIB
-- Dependances nouvelles : V_REFERENCE_COULEUR.
CREATE VIEW public.as_ingredients_lib (
    "id", "libelle", "parfums", "seuil", "unite", "quantiteparpack", "pu", "actif", "photo", "calorie", "durre", "compose", "marque", "idmodele", "idmodelelib", "marquelib", "taillelib", "couleur", "taille", "composelib", "idcategorieingredient", "categorieingredient", "idcategorie", "idfournisseur", "daty", "bienouserv", "etatlib", "compte_vente", "compte_achat", "pv", "tva", "typestock", "idunite", "refpost", "refqualification", "refpostlib", "refqualificationlib", "idfamillelib", "typeproduit", "idligne", "compte_stock", "compte_sortie_stock", "idfournisseurlib", "iddepartementlib", "libellevente", "nbpiece", "typeproduitlib", "codebarre", "reference", "couleurlib"
) AS
SELECT
  ing.id AS id,
  ing.libelle AS libelle,
  ing.parfums AS parfums,
  CAST(ing.seuil AS DECIMAL(10, 5)) AS seuil,
  au.val AS unite,
  CAST(ing.quantiteparpack AS DECIMAL(10, 5)) AS quantiteparpack,
  CAST(ing.pu AS DECIMAL(30, 5)) AS pu,
  ing.actif AS actif,
  ing.photo AS photo,
  ing.calorie AS calorie,
  ing.durre AS durre,
  ing.compose AS compose,
  ing.marque AS marque,
  ing.idmodele AS idmodele,
  mo.libelle AS idmodelelib,
  po.val AS marquelib,
  ta.val AS taillelib,
  ing.couleur AS couleur,
  ing.taille AS taille,
  CAST(CASE WHEN ing.compose = 1 THEN 'OUI' WHEN ing.compose = 0 THEN 'NON' END AS VARCHAR(100)) AS composelib,
  cating.id AS idcategorieingredient,
  cating.val AS categorieingredient,
  ing.categorieingredient AS idcategorie,
  ing.idfournisseur AS idfournisseur,
  ing.daty AS daty,
  cating.desce AS bienouserv,
  CASE
    WHEN ing.id IN (
      SELECT
        i.idproduit AS idproduit
      FROM public.indisponibilite AS i
    )
    THEN 'INDISPONIBLE'
    WHEN NOT ing.id IN (
      SELECT
        i.idproduit AS idproduit
      FROM public.indisponibilite AS i
    )
    THEN 'DISPONIBLE'
  END AS etatlib,
  ing.compte_vente AS compte_vente,
  ing.compte_achat AS compte_achat,
  CAST(ing.pv AS DECIMAL(30, 5)) AS pv,
  CAST(ing.tva AS DECIMAL(10, 5)) AS tva,
  ing.typestock AS typestock,
  ing.unite AS idunite,
  ing.refpost AS refpost,
  ing.refqualification AS refqualification,
  p.val AS refpostlib,
  qp.val AS refqualificationlib,
  fp.val AS idfamillelib,
  ing.typeproduit AS typeproduit,
  tp.idligne AS idligne,
  ing.compte_stock AS compte_stock,
  ing.compte_sortie_stock AS compte_sortie_stock,
  f.nom AS idfournisseurlib,
  dep.val AS iddepartementlib,
  ing.libellevente AS libellevente,
  eq.quantite AS nbpiece,
  tp.val AS typeproduitlib,
  ing.codebarre AS codebarre,
  ing.reference AS reference,
  vrc.nomcouleur AS couleurlib
FROM public.as_ingredients AS ing
LEFT JOIN public.as_unite AS au
  ON ing.unite = au.id
LEFT JOIN public.categorieingredientlib AS cating
  ON cating.id = ing.categorieingredient
LEFT JOIN public.poste AS p
  ON p.id = ing.refpost
LEFT JOIN public.familleproduit AS fp
  ON fp.id = ing.idfamille
LEFT JOIN public.qualification_paie AS qp
  ON qp.id = ing.refqualification
LEFT JOIN public.type_produit AS tp
  ON tp.id = ing.typeproduit
LEFT JOIN public.fournisseur AS f
  ON ing.idfournisseur = f.id
LEFT JOIN public.departement AS dep
  ON dep.id = ing.parfums
LEFT JOIN public.equivalencevente AS eq
  ON eq.idproduit1 = ing.id
LEFT JOIN public.modele AS mo
  ON mo.id = ing.idmodele
LEFT JOIN public.taille AS ta
  ON ta.id = ing.taille
LEFT JOIN public.pointure AS po
  ON po.id = ing.marque
LEFT JOIN public.v_reference_couleur AS vrc
  ON ing.couleur = vrc.referencecouleur
WHERE
  ing.actif = 1;

-- Niveau 2 - vue 4 / 100 : AS_INGREDIENT_VENTE_LIB
-- Dependances nouvelles : V_REFERENCE_COULEUR.
CREATE VIEW public.as_ingredient_vente_lib (
    "id", "libelle", "seuil", "unite", "quantiteparpack", "pu", "actif", "photo", "calorie", "durre", "compose", "categorieingredient", "idfournisseur", "daty", "qtelimite", "pv", "libellevente", "seuilmin", "seuilmax", "puachatusd", "puachateuro", "puachatautredevise", "puventeusd", "puventeeuro", "puventeautredevise", "isvente", "isachat", "compte_vente", "compte_achat", "libelleextacte", "tva", "filepath", "reste", "typestock", "refpost", "refqualification", "idchambre", "isperishable", "pv2", "idmagasin", "prixunitaire", "idtypeclient", "idtypeclientlib", "idunite", "idunitelib", "poids", "quantite", "tarifmagasin", "unite2", "couleur", "couleurlib", "marque", "marquelib"
) AS
SELECT
  ing.id AS id,
  NULLIF(CONCAT(ing.libelle, ' ', pointure.val, ' ', vrc.nomcouleur), '') AS libelle,
  CAST(ing.seuil AS DECIMAL(10, 5)) AS seuil,
  ing.unite AS unite,
  CAST(ing.quantiteparpack AS DECIMAL(10, 5)) AS quantiteparpack,
  CAST(ing.pu AS DECIMAL(30, 5)) AS pu,
  ing.actif AS actif,
  ing.photo AS photo,
  ing.calorie AS calorie,
  ing.durre AS durre,
  ing.compose AS compose,
  ing.categorieingredient AS categorieingredient,
  ing.idfournisseur AS idfournisseur,
  ing.daty AS daty,
  CAST(ing.qtelimite AS DECIMAL(30, 5)) AS qtelimite,
  CAST(ing.pv AS DECIMAL(30, 5)) AS pv,
  ing.libellevente AS libellevente,
  CAST(COALESCE(ing.seuilmin, 0) AS DECIMAL(30, 5)) AS seuilmin,
  CAST(COALESCE(ing.seuilmax, 0) AS DECIMAL(30, 5)) AS seuilmax,
  CAST(COALESCE(ing.puachatusd, 0) AS DECIMAL(30, 5)) AS puachatusd,
  CAST(COALESCE(ing.puachateuro, 0) AS DECIMAL(30, 5)) AS puachateuro,
  CAST(COALESCE(ing.puachatautredevise, 0) AS DECIMAL(30, 5)) AS puachatautredevise,
  CAST(COALESCE(ing.puventeusd, 0) AS DECIMAL(30, 5)) AS puventeusd,
  CAST(COALESCE(ing.puventeeuro, 0) AS DECIMAL(30, 5)) AS puventeeuro,
  CAST(COALESCE(ing.puventeautredevise, 0) AS DECIMAL(30, 5)) AS puventeautredevise,
  ing.isvente AS isvente,
  ing.isachat AS isachat,
  ing.compte_vente AS compte_vente,
  ing.compte_achat AS compte_achat,
  ing.libelleextacte AS libelleextacte,
  CAST(ing.tva AS DECIMAL(10, 5)) AS tva,
  ing.filepath AS filepath,
  CAST(ing.reste AS DECIMAL(20, 5)) AS reste,
  ing.typestock AS typestock,
  ing.refpost AS refpost,
  ing.refqualification AS refqualification,
  ing.idchambre AS idchambre,
  ing.isperishable AS isperishable,
  ing.pv2 AS pv2,
  ing.idmagasin AS idmagasin,
  CAST(COALESCE(ting.prixunitaire, ing.pv) AS DECIMAL(30, 5)) AS prixunitaire,
  tc.id AS idtypeclient,
  tc.val AS idtypeclientlib,
  COALESCE(un.id, un2.id) AS idunite,
  COALESCE(un.val, un2.val) AS idunitelib,
  CAST(eq.poids AS DECIMAL(30, 5)) AS poids,
  CAST(eq.quantite AS DECIMAL(20, 5)) AS quantite,
  ting.idmagasin AS tarifmagasin,
  ing.unite2 AS unite2,
  ing.couleur AS couleur,
  vrc.nomcouleur AS couleurlib,
  ing.marque AS marque,
  pointure.val AS marquelib
FROM public.as_ingredients AS ing
CROSS JOIN public.typeclient AS tc
LEFT JOIN public.tarif_ingredients_max AS ting
  ON ing.id = ting.idingredient AND ting.idtypeclient = tc.id
LEFT JOIN public.as_unite AS un
  ON un.id = ting.unite
LEFT JOIN public.as_unite AS un2
  ON un2.id = ing.unite
LEFT JOIN public.equivalencevente AS eq
  ON eq.idproduit2 = ting.idingredient
LEFT JOIN public.v_reference_couleur AS vrc
  ON ing.couleur = vrc.referencecouleur
LEFT JOIN public.pointure AS pointure
  ON ing.marque = pointure.id
WHERE
  (
    ing.categorieingredient = 'CAT008' OR ing.isvente = 1
  );

