  ON ing.unite = au.id
LEFT JOIN public.categorieingredientlib AS cating
  ON cating.id = ing.categorieingredient
LEFT JOIN public.poste AS p
  ON p.id = ing.refpost
LEFT JOIN public.familleproduit AS fp
  ON fp.id = ing.idfamille
LEFT JOIN public.qualification_paie AS qp
  ON qp.id = ing.refqualification
LEFT JOIN public.type_produit AS tp
  ON tp.id = ing.typeproduit
LEFT JOIN public.fournisseur AS f
  ON ing.idfournisseur = f.id
LEFT JOIN public.departement AS dep
  ON dep.id = ing.parfums
LEFT JOIN public.equivalencevente AS eq
  ON eq.idproduit1 = ing.id
LEFT JOIN public.modele AS mo
  ON mo.id = ing.idmodele
LEFT JOIN public.taille AS ta
  ON ta.id = ing.taille
LEFT JOIN public.pointure AS po
  ON po.id = ing.marque
LEFT JOIN public.v_reference_couleur AS vrc
  ON ing.couleur = vrc.referencecouleur
WHERE
  ing.actif = 1;

