  base.cnaps_employeur3 AS cnaps_employeur3,
  base.cotisation_travailleur AS cotisation_travailleur,
  base.cotisation_employeur AS cotisation_employeur,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.personnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.prenom AS VARCHAR(4000)), NULL),
        ' | ',
