                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.cotisation_travailleur
                  ) AS TEXT)))
                  ELSE CAST((
                    base.cotisation_travailleur
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
