        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.cotisation_employeur
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.cotisation_employeur
                  ) AS TEXT)))
                  ELSE CAST((
                    base.cotisation_employeur
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    pec.idpersonnel AS idpersonnel,
    pipl.matricule AS matricule,
    pipl.nom AS personnel,
    pipl.prenom AS prenom,
    pipl.numero_cnaps AS numero_cnaps,
    pipl.direction AS direction,
    pipl.dateembauche AS dateembauche,
    pec.annee AS annee,
    COALESCE(s1.brut, 0) AS mois1,
    COALESCE(s1.cnaps_travailleur, 0) AS cnaps_travailleur1,
    COALESCE(s1.cnaps_employeur, 0) AS cnaps_employeur1,
    COALESCE(s2.brut, 0) AS mois2,
    COALESCE(s2.cnaps_travailleur, 0) AS cnaps_travailleur2,
    COALESCE(s2.cnaps_employeur, 0) AS cnaps_employeur2,
    COALESCE(s3.brut, 0) AS mois3,
    COALESCE(s3.cnaps_travailleur, 0) AS cnaps_travailleur3,
    COALESCE(s3.cnaps_employeur, 0) AS cnaps_employeur3,
    COALESCE(s1.cnaps_travailleur, 0) + COALESCE(s2.cnaps_travailleur, 0) + COALESCE(s3.cnaps_travailleur, 0) AS cotisation_travailleur,
    COALESCE(s1.cnaps_employeur, 0) + COALESCE(s2.cnaps_employeur, 0) + COALESCE(s3.cnaps_employeur, 0) AS cotisation_employeur
  FROM public.paie_edition_cnaps AS pec
  JOIN public.paie_info_personnel_libcomplet AS pipl
    ON CAST(pipl.id AS VARCHAR(4000)) = CAST(pec.idpersonnel AS VARCHAR(4000))
    AND pec.mois IN (1, 2, 3)
  LEFT JOIN (
    SELECT
      c1.idpersonnel AS idpersonnel,
      c1.annee AS annee,
      c1.brut AS brut,
      c1.cnaps_travailleur AS cnaps_travailleur,
      c1.cnaps_employeur AS cnaps_employeur
    FROM public.paie_edition_cnaps AS c1
    WHERE
      c1.mois = 1
  ) AS s1
    ON CAST(pec.idpersonnel AS VARCHAR(4000)) = CAST(s1.idpersonnel AS VARCHAR(4000))
    AND pec.annee = s1.annee
  LEFT JOIN (
    SELECT
      c2.idpersonnel AS idpersonnel,
      c2.annee AS annee,
      c2.brut AS brut,
      c2.cnaps_travailleur AS cnaps_travailleur,
      c2.cnaps_employeur AS cnaps_employeur
    FROM public.paie_edition_cnaps AS c2
    WHERE
      c2.mois = 2
  ) AS s2
    ON CAST(pec.idpersonnel AS VARCHAR(4000)) = CAST(s2.idpersonnel AS VARCHAR(4000))
    AND pec.annee = s2.annee
  LEFT JOIN (
    SELECT
      c3.idpersonnel AS idpersonnel,
      c3.annee AS annee,
      c3.brut AS brut,
      c3.cnaps_travailleur AS cnaps_travailleur,
      c3.cnaps_employeur AS cnaps_employeur
    FROM public.paie_edition_cnaps AS c3
    WHERE
      c3.mois = 3
  ) AS s3
    ON CAST(pec.idpersonnel AS VARCHAR(4000)) = CAST(s3.idpersonnel AS VARCHAR(4000))
    AND pec.annee = s3.annee
  GROUP BY
    pec.idpersonnel,
    pipl.matricule,
    pipl.nom,
    pipl.prenom,
    pipl.numero_cnaps,
    pipl.direction,
    pipl.dateembauche,
    pec.annee,
    s1.brut,
    s1.cnaps_travailleur,
    s1.cnaps_employeur,
    s2.brut,
    s2.cnaps_travailleur,
    s2.cnaps_employeur,
    s3.brut,
    s3.cnaps_travailleur,
    s3.cnaps_employeur
) AS base;

-- Niveau 2 - vue 14 / 100 : CNAPS_T2
-- Dependances nouvelles : PAIE_EDITION_CNAPS.
CREATE VIEW public.cnaps_t2 (
    "idpersonnel", "matricule", "personnel", "prenom", "numero_cnaps", "dateembauche", "direction", "annee", "mois1", "cnaps_travailleur1", "cnaps_employeur1", "mois2", "cnaps_travailleur2", "cnaps_employeur2", "mois3", "cnaps_travailleur3", "cnaps_employeur3", "cotisation_travailleur", "cotisation_employeur"
) AS
SELECT
  pec.idpersonnel AS idpersonnel,
  pipl.matricule AS matricule,
  pipl.nom AS personnel,
  pipl.prenom AS prenom,
  pipl.numero_cnaps AS numero_cnaps,
  pipl.dateembauche AS dateembauche,
  pipl.direction AS direction,
  pec.annee AS annee,
  COALESCE(s1.brut, 0) AS mois1,
  COALESCE(s1.cnaps_travailleur, 0) AS cnaps_travailleur1,
  COALESCE(s1.cnaps_employeur, 0) AS cnaps_employeur1,
  COALESCE(s2.brut, 0) AS mois2,
  COALESCE(s2.cnaps_travailleur, 0) AS cnaps_travailleur2,
  COALESCE(s2.cnaps_employeur, 0) AS cnaps_employeur2,
  COALESCE(s3.brut, 0) AS mois3,
  COALESCE(s3.cnaps_travailleur, 0) AS cnaps_travailleur3,
  COALESCE(s3.cnaps_employeur, 0) AS cnaps_employeur3,
  ROUND(
    CAST(COALESCE(s1.cnaps_travailleur, 0) + COALESCE(s2.cnaps_travailleur, 0) + COALESCE(s3.cnaps_travailleur, 0) AS DECIMAL),
    2
  ) AS cotisation_travailleur,
  ROUND(
    CAST(COALESCE(s1.cnaps_employeur, 0) + COALESCE(s2.cnaps_employeur, 0) + COALESCE(s3.cnaps_employeur, 0) AS DECIMAL),
    2
  ) AS cotisation_employeur
FROM public.paie_edition_cnaps AS pec
JOIN public.paie_info_personnel_libcomplet AS pipl
  ON pipl.id = pec.idpersonnel AND pec.mois IN (4, 5, 6)
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.mois AS mois,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 4
) AS s1
  ON pec.idpersonnel = s1.idpersonnel AND pec.annee = s1.annee
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.mois AS mois,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 5
) AS s2
  ON pec.idpersonnel = s2.idpersonnel AND pec.annee = s2.annee
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.mois AS mois,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 6
) AS s3
  ON pec.idpersonnel = s3.idpersonnel AND pec.annee = s3.annee
GROUP BY
  pec.idpersonnel,
  pipl.matricule,
  pipl.nom,
  pipl.numero_cnaps,
  pipl.prenom,
  pipl.dateembauche,
  pipl.direction,
  pec.annee,
  s1.brut,
  s1.cnaps_travailleur,
  s1.cnaps_employeur,
  s2.brut,
  s2.cnaps_travailleur,
  s2.cnaps_employeur,
  s3.brut,
  s3.cnaps_travailleur,
  s3.cnaps_employeur;

-- Niveau 2 - vue 15 / 100 : CNAPS_T3
-- Dependances nouvelles : PAIE_EDITION_CNAPS.
CREATE VIEW public.cnaps_t3 (
    "idpersonnel", "matricule", "personnel", "prenom", "numero_cnaps", "dateembauche", "direction", "annee", "mois1", "cnaps_travailleur1", "cnaps_employeur1", "mois2", "cnaps_travailleur2", "cnaps_employeur2", "mois3", "cnaps_travailleur3", "cnaps_employeur3", "cotisation_travailleur", "cotisation_employeur"
) AS
SELECT
  pec.idpersonnel AS idpersonnel,
  pipl.matricule AS matricule,
  pipl.nom AS personnel,
  pipl.prenom AS prenom,
  pipl.numero_cnaps AS numero_cnaps,
  pipl.dateembauche AS dateembauche,
  pipl.direction AS direction,
  pec.annee AS annee,
  ROUND(CAST(COALESCE(s1.brut, 0) AS DECIMAL), 2) AS mois1,
  ROUND(CAST(COALESCE(s1.cnaps_travailleur, 0) AS DECIMAL), 2) AS cnaps_travailleur1,
  ROUND(CAST(COALESCE(s1.cnaps_employeur, 0) AS DECIMAL), 2) AS cnaps_employeur1,
  ROUND(CAST(COALESCE(s2.brut, 0) AS DECIMAL), 2) AS mois2,
  ROUND(CAST(COALESCE(s2.cnaps_travailleur, 0) AS DECIMAL), 2) AS cnaps_travailleur2,
  ROUND(CAST(COALESCE(s2.cnaps_employeur, 0) AS DECIMAL), 2) AS cnaps_employeur2,
  ROUND(CAST(COALESCE(s3.brut, 0) AS DECIMAL), 2) AS mois3,
  ROUND(CAST(COALESCE(s3.cnaps_travailleur, 0) AS DECIMAL), 2) AS cnaps_travailleur3,
  ROUND(CAST(COALESCE(s3.cnaps_employeur, 0) AS DECIMAL), 2) AS cnaps_employeur3,
  ROUND(
    CAST(COALESCE(s1.cnaps_travailleur, 0) + COALESCE(s2.cnaps_travailleur, 0) + COALESCE(s3.cnaps_travailleur, 0) AS DECIMAL),
    2
  ) AS cotisation_travailleur,
  ROUND(
    CAST(COALESCE(s1.cnaps_employeur, 0) + COALESCE(s2.cnaps_employeur, 0) + COALESCE(s3.cnaps_employeur, 0) AS DECIMAL),
    2
  ) AS cotisation_employeur
FROM public.paie_edition_cnaps AS pec
JOIN public.paie_info_personnel_libcomplet AS pipl
  ON pipl.id = pec.idpersonnel
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 7
) AS s1
  ON pec.idpersonnel = s1.idpersonnel AND pec.annee = s1.annee
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 8
) AS s2
  ON pec.idpersonnel = s2.idpersonnel AND pec.annee = s2.annee
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 9
) AS s3
  ON pec.idpersonnel = s3.idpersonnel AND pec.annee = s3.annee
WHERE
  pec.mois IN (7, 8, 9)
GROUP BY
  pec.idpersonnel,
  pipl.matricule,
  pipl.nom,
  pipl.prenom,
  pipl.numero_cnaps,
  pipl.dateembauche,
  pipl.direction,
  pec.annee,
  s1.brut,
  s1.cnaps_travailleur,
  s1.cnaps_employeur,
  s2.brut,
  s2.cnaps_travailleur,
  s2.cnaps_employeur,
  s3.brut,
  s3.cnaps_travailleur,
  s3.cnaps_employeur;

