  pipl.dateembauche AS dateembauche,
  pipl.direction AS direction,
  pec.annee AS annee,
  ROUND(CAST(COALESCE(s1.brut, 0) AS DECIMAL), 2) AS mois1,
  ROUND(CAST(COALESCE(s1.cnaps_travailleur, 0) AS DECIMAL), 2) AS cnaps_travailleur1,
  ROUND(CAST(COALESCE(s1.cnaps_employeur, 0) AS DECIMAL), 2) AS cnaps_employeur1,
  ROUND(CAST(COALESCE(s2.brut, 0) AS DECIMAL), 2) AS mois2,
  ROUND(CAST(COALESCE(s2.cnaps_travailleur, 0) AS DECIMAL), 2) AS cnaps_travailleur2,
  ROUND(CAST(COALESCE(s2.cnaps_employeur, 0) AS DECIMAL), 2) AS cnaps_employeur2,
  ROUND(CAST(COALESCE(s3.brut, 0) AS DECIMAL), 2) AS mois3,
  ROUND(CAST(COALESCE(s3.cnaps_travailleur, 0) AS DECIMAL), 2) AS cnaps_travailleur3,
  ROUND(CAST(COALESCE(s3.cnaps_employeur, 0) AS DECIMAL), 2) AS cnaps_employeur3,
  ROUND(
    CAST(COALESCE(s1.cnaps_travailleur, 0) + COALESCE(s2.cnaps_travailleur, 0) + COALESCE(s3.cnaps_travailleur, 0) AS DECIMAL),
    2
  ) AS cotisation_travailleur,
  ROUND(
    CAST(COALESCE(s1.cnaps_employeur, 0) + COALESCE(s2.cnaps_employeur, 0) + COALESCE(s3.cnaps_employeur, 0) AS DECIMAL),
    2
  ) AS cotisation_employeur
FROM public.paie_edition_cnaps AS pec
JOIN public.paie_info_personnel_libcomplet AS pipl
  ON pipl.id = pec.idpersonnel AND pec.mois IN (10, 11, 12)
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.mois AS mois,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 10
) AS s1
  ON pec.idpersonnel = s1.idpersonnel AND pec.annee = s1.annee
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.mois AS mois,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 11
) AS s2
  ON pec.idpersonnel = s2.idpersonnel AND pec.annee = s2.annee
LEFT JOIN (
  SELECT
    paie_edition_cnaps.idpersonnel AS idpersonnel,
    paie_edition_cnaps.mois AS mois,
    paie_edition_cnaps.annee AS annee,
    paie_edition_cnaps.brut AS brut,
    paie_edition_cnaps.cnaps_travailleur AS cnaps_travailleur,
    paie_edition_cnaps.cnaps_employeur AS cnaps_employeur
  FROM public.paie_edition_cnaps AS paie_edition_cnaps
  WHERE
    paie_edition_cnaps.mois = 12
) AS s3
  ON pec.idpersonnel = s3.idpersonnel AND pec.annee = s3.annee;

