-- Dependances nouvelles : V_CLASSEETFICHE.
CREATE VIEW public.compta_ecriture_fiche (
    "id", "daty", "datecomptable", "exercice", "designation", "remarque", "etat", "horsexercice", "journal", "od", "origine", "credit", "debit", "iduser", "periode", "trimestre", "annee", "idobjet", "lettrage", "lien", "datesaisie", "datemodif", "idmodificateur", "idmodificateurlib", "journallib"
) AS
SELECT
  ce.id AS id,
  ce.daty AS daty,
  ce.datecomptable AS datecomptable,
  ce.exercice AS exercice,
  ce.designation AS designation,
  ce.remarque AS remarque,
  ce.etat AS etat,
  ce.horsexercice AS horsexercice,
  ce.journal AS journal,
  ce.od AS od,
  ce.origine AS origine,
  ce.credit AS credit,
  ce.debit AS debit,
  ce.iduser AS iduser,
  ce.periode AS periode,
  ce.trimestre AS trimestre,
  ce.annee AS annee,
  ce.idobjet AS idobjet,
  ce.lettrage AS lettrage,
  vc.fiche AS lien,
  ce.datesaisie AS datesaisie,
  ce.datemodif AS datemodif,
  ce.idmodificateur AS idmodificateur,
  u.nomuser AS idmodificateurlib,
  cj.val AS journallib
FROM public.compta_ecriture AS ce
LEFT JOIN public.v_classeetfiche AS vc
  ON NULLIF(SUBSTRING(ce.idobjet FROM 1 FOR 3), '') = vc.libelle
LEFT JOIN public.utilisateur AS u
  ON CAST(ce.idmodificateur AS DECIMAL) = u.refuser
LEFT JOIN public.compta_journal AS cj
  ON cj.id = ce.journal;

