-- Niveau 2 - vue 22 / 100 : COUT_FAB_PAR_OF
-- Dependances nouvelles : OFFILLELIBSTOCK.
CREATE VIEW public.cout_fab_par_of (
    "idmere", "datybesoin", "ingredients", "coutdeproduction"
) AS
SELECT
  base.idmere AS idmere,
  base.datybesoin AS datybesoin,
  base.idingredients AS ingredients,
  CAST(ROUND(
    CAST(SUM(
      CASE
        WHEN base.qtefabrique = 0 OR base.qtefabrique IS NULL
        THEN 0
        ELSE CAST(base.montantsortie AS DECIMAL) / base.qtefabrique
      END
    ) AS DECIMAL),
    2
  ) AS DECIMAL) / 1000000 AS coutdeproduction
FROM public.offillelibstock AS base
JOIN public.ofab AS fb
  ON fb.id = base.idmere AND fb.etat >= 11
GROUP BY
  base.idmere,
  base.datybesoin,
  base.idingredients
ORDER BY
  idmere;

-- Niveau 2 - vue 23 / 100 : COUT_FAB_PAR_OF_TEMP
-- Dependances nouvelles : OFFILLELIBSTOCK.
CREATE VIEW public.cout_fab_par_of_temp (
    "idmere", "datybesoin", "ingredients", "coutdeproduction", "motsclesss"
) AS
SELECT
  sq.idmere AS idmere,
  sq.datybesoin AS datybesoin,
  sq.ingredients AS ingredients,
  CAST(sq.coutdeproduction AS DECIMAL(30, 5)) AS coutdeproduction,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.idmere AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.datybesoin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(sq.ingredients AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.coutdeproduction
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.coutdeproduction
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.coutdeproduction
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    base.idmere AS idmere,
    base.datybesoin AS datybesoin,
    base.idingredients AS ingredients,
    ROUND(CAST(SUM(base.montantsortie) AS DECIMAL), 2) AS coutdeproduction
  FROM public.offillelibstock AS base
  JOIN public.ofab AS fb
    ON fb.id = base.idmere AND fb.etat >= 11
  GROUP BY
    base.idmere,
    base.datybesoin,
    base.idingredients
  ORDER BY
    idmere
) AS sq;

-- Niveau 2 - vue 24 / 100 : DEMANDETRANSFERTFILLECPL
-- Dependances nouvelles : V_REFERENCE_COULEUR.
CREATE VIEW public.demandetransfertfillecpl (
    "id", "iddemandetransfert", "iddemandetransfertlib", "idproduit", "idproduitlib", "quantite", "typestock", "unite", "pu"
) AS
SELECT
  t.id AS id,
  t.iddemandetransfert AS iddemandetransfert,
  t2.designation AS iddemandetransfertlib,
  t.idproduit AS idproduit,
  NULLIF(CONCAT(p.libelle, ' - ', c.nomcouleur, ' - ', po.val), '') AS idproduitlib,
  t.quantite AS quantite,
  p.typestock AS typestock,
  p.unite AS unite,
  CAST(p.pu AS DECIMAL(30, 5)) AS pu
FROM public.demandetransfertfille AS t
LEFT JOIN public.demandetransfert AS t2
  ON t2.id = t.iddemandetransfert
LEFT JOIN public.as_ingredients AS p
  ON p.id = t.idproduit
LEFT JOIN public.pointure AS po
  ON po.id = p.marque
LEFT JOIN public.v_reference_couleur AS c
  ON c.referencecouleur = p.couleur;

