        ' | ',
        COALESCE(CAST(base.iddirection AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.directionlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.etatlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.refuser AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.ranguser
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.ranguser
                  ) AS TEXT)))
                  ELSE CAST((
                    base.ranguser
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.idremplacents AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.remplacents AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.matricules AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.datefin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(base.personnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idsup AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.avenant AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.annuler AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.superieur AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.motifrefu AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.weekenddecomptelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.iddepartement AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.departementlib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    d.id AS id,
    d.idpersonnel AS idpersonnel,
    pip.matricule AS matricule,
    pip.idfonction AS idfonction,
    pf.val AS fonctionlib,
    d.idtypedemande AS idtypedemande,
    t.val AS typedemandelib,
    d.titre AS titre,
    d.horairenormal AS horairenormal,
    d.heuredepart AS heuredepart,
    d.heurearrive AS heurearrive,
    d.idtypeabsence AS idtypeabsence,
    t2.desce AS typeabsencelib,
    d.motif AS motif,
    d.numero AS numero,
    d.desce AS desce,
    d.etat AS etat,
    d.daty AS daty,
    d.duree AS duree,
    d.datedepart AS datedepart,
    d.dateretour AS dateretour,
    d.observation AS observation,
    d.remarque AS remarque,
    lp.nom AS nom,
    lp.prenom AS prenom,
    lp.direction AS iddirection,
    ld.val AS directionlib,
    CASE
      WHEN d.etat = 1
      THEN 'Cree'
      WHEN d.etat = 11
      THEN 'Valide'
      WHEN d.etat = -1
      THEN 'Refusee'
      ELSE 'AUTRE'
    END AS etatlib,
    u.refuser AS refuser,
    r.rang AS ranguser,
    d.idremplacents AS idremplacents,
    rmp.remplacents AS remplacents,
    pip.matricule AS matricules,
    d.datefin AS datefin,
    NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS personnel,
    lp.idsup AS idsup,
    d.avenant AS avenant,
    CASE WHEN NOT d.avenant IS NULL THEN 'OUI' ELSE NULL END AS annuler,
    NULLIF(CONCAT(pl.nom, ' ', pl.prenom), '') AS superieur,
    d.motifrefu AS motifrefu,
    CASE
      WHEN d.weekenddecompte = 1
      THEN 'OUI'
      WHEN d.weekenddecompte = 0
      THEN 'NON'
      ELSE NULL
    END AS weekenddecomptelib,
    d.iddepartement AS iddepartement,
    dp.desce AS departementlib
  FROM public.demande AS d
  LEFT JOIN public.paie_info_personnel AS pip
    ON d.idpersonnel = pip.id
  LEFT JOIN public.paie_fonction AS pf
    ON pf.id = pip.idfonction
  LEFT JOIN public.typedemande AS t
    ON t.id = d.idtypedemande
  LEFT JOIN public.typeabsence AS t2
    ON t2.id = d.idtypeabsence
  LEFT JOIN public.log_personnel AS lp
    ON lp.id = pip.id
  LEFT JOIN public.log_direction AS ld
    ON ld.id = lp.direction
  LEFT JOIN public.utilisateur AS u
    ON u.refuser = lp.refuser
  LEFT JOIN public.roles AS r
    ON r.idrole = u.idrole
  LEFT JOIN public.demande_remplacents AS rmp
    ON rmp.id = d.id
  LEFT JOIN public.log_personnel AS pl
    ON pl.id = lp.idsup
  LEFT JOIN public.departement AS dp
    ON dp.id = d.iddepartement
) AS base;

-- Niveau 2 - vue 27 / 100 : DEMANDE_LIBCOMPLET2
