CREATE VIEW public.demande_libcomplet2 (
    "id", "idpersonnel", "matricules", "idfonction", "fonctionlib", "idtypedemande", "typedemandelib", "titre", "horairenormal", "heuredepart", "heurearrive", "idtypeabsence", "typeabsencelib", "motif", "numero", "desce", "etat", "daty", "duree", "datedepart", "datefin", "dateretour", "observation", "remarque", "nom", "prenom", "personnel", "iddirection", "directionlib", "etatlib", "refuser", "ranguser", "idremplacents", "remplacents", "avenant"
) AS
SELECT
  d.id AS id,
  d.idpersonnel AS idpersonnel,
  pip.matricule AS matricules,
  pip.idfonction AS idfonction,
  pf.val AS fonctionlib,
  d.idtypedemande AS idtypedemande,
  t.val AS typedemandelib,
  d.titre AS titre,
  d.horairenormal AS horairenormal,
  d.heuredepart AS heuredepart,
  d.heurearrive AS heurearrive,
  d.idtypeabsence AS idtypeabsence,
  t2.desce AS typeabsencelib,
  d.motif AS motif,
  d.numero AS numero,
  d.desce AS desce,
  d.etat AS etat,
  d.daty AS daty,
  d.duree AS duree,
  d.datedepart AS datedepart,
  d.datefin AS datefin,
  d.dateretour AS dateretour,
  d.observation AS observation,
  d.remarque AS remarque,
  lp.nom AS nom,
  lp.prenom AS prenom,
  NULLIF(CONCAT((
    NULLIF(CONCAT(lp.nom, ' '), '')
  ), lp.prenom), '') AS personnel,
  lp.direction AS iddirection,
  ld.val AS directionlib,
  CASE
    WHEN d.etat = 1
    THEN '<span style="color:green;">CR&Eacute;&Eacute;E</span>'
    WHEN d.etat = 11
    THEN '<span style="color:blue;">VIS&Eacute;E</span>'
    WHEN d.etat = -1
    THEN '<span style="color:red;">REFUS&Eacute;E</span>'
    ELSE '<span style="color: yellow;">AUTRE</span>'
  END AS etatlib,
  u.refuser AS refuser,
  r.rang AS ranguser,
  d.idremplacents AS idremplacents,
  rmp.remplacents AS remplacents,
  d.avenant AS avenant
FROM public.demande AS d
LEFT JOIN public.paie_info_personnel AS pip
  ON d.idpersonnel = pip.id
LEFT JOIN public.paie_fonction AS pf
  ON pf.id = pip.idfonction
LEFT JOIN public.typedemande AS t
  ON t.id = d.idtypedemande
LEFT JOIN public.typeabsence AS t2
  ON t2.id = d.idtypeabsence
LEFT JOIN public.log_personnel AS lp
  ON lp.id = pip.id
LEFT JOIN public.log_direction AS ld
  ON ld.id = lp.direction
LEFT JOIN public.utilisateur AS u
  ON u.refuser = lp.refuser
LEFT JOIN public.roles AS r
  ON r.idrole = u.idrole
LEFT JOIN public.demande_remplacents AS rmp
  ON rmp.id = d.id;

-- Niveau 2 - vue 28 / 100 : DEMANDE_LIBCOMPLET3
