CREATE VIEW public.demande_libcomplet3 (
    "id", "idpersonnel", "matricule", "idfonction", "fonctionlib", "idtypedemande", "typedemandelib", "titre", "horairenormal", "heuredepart", "heurearrive", "idtypeabsence", "typeabsencelib", "motif", "numero", "desce", "etat", "daty", "duree", "datedepart", "dateretour", "observation", "remarque", "nom", "prenom", "iddirection", "directionlib", "etatlib", "refuser", "ranguser", "idremplacents", "remplacents", "matricules", "datefin", "personnel", "idsup", "avenant", "annuler", "superieur", "motifrefu", "iddepartement"
) AS
SELECT
  d.id AS id,
  d.idpersonnel AS idpersonnel,
  pip.matricule AS matricule,
  pip.idfonction AS idfonction,
  pf.val AS fonctionlib,
  d.idtypedemande AS idtypedemande,
  t.val AS typedemandelib,
  d.titre AS titre,
  d.horairenormal AS horairenormal,
  d.heuredepart AS heuredepart,
  d.heurearrive AS heurearrive,
  d.idtypeabsence AS idtypeabsence,
  t2.desce AS typeabsencelib,
  d.motif AS motif,
  d.numero AS numero,
  d.desce AS desce,
  d.etat AS etat,
  d.daty AS daty,
  d.duree AS duree,
  d.datedepart AS datedepart,
  d.dateretour AS dateretour,
  d.observation AS observation,
  d.remarque AS remarque,
  lp.nom AS nom,
  lp.prenom AS prenom,
  lp.direction AS iddirection,
  ld.val AS directionlib,
  CASE
    WHEN d.etat = 1
    THEN '<span style="color:green;">CR&Eacute;&Eacute;E</span>'
    WHEN d.etat = 11
    THEN '<span style="color:blue;">VIS&Eacute;E</span>'
    WHEN d.etat = -1
    THEN '<span style="color:red;">REFUS&Eacute;E</span>'
    ELSE '<span style="color: yellow;">AUTRE</span>'
  END AS etatlib,
