-- Niveau 2 - vue 29 / 100 : ECART_CARBU_GRAPH
-- Dependances nouvelles : INVENTAIRELIB.
CREATE VIEW public.ecart_carbu_graph (
    "idmagasinlib", "daty", "ecart"
) AS
(
  SELECT
    i.idmagasinlib AS idmagasinlib,
    i.daty AS daty,
    ifc.quantitetheorique - ifc.quantite AS ecart
  FROM public.inventairelib AS i
  JOIN public.inventaire_fille_cpl AS ifc
    ON ifc.idinventaire = i.id
  JOIN (
    SELECT
      p.id,
      p.val,
      p.desce,
      p.id AS idpoint,
      CAST('-' AS TEXT) AS idproduit,
      CAST(NULL AS TEXT) AS idtypemagasin,
      11 AS etat
    FROM public.point AS p
  ) AS m
    ON m.id = i.idmagasin
);

