) AS
SELECT
  dp.id AS id,
  dp.mois AS mois,
  dp.annee AS annee,
  dp.matricule AS matricule,
  COALESCE(dp.numero_cnaps, NULL) AS numero_cnaps,
  dp.nom AS nom,
  dp.poste AS poste,
  dp.salaire_de_base AS salaire_de_base,
  dp.indemnitedepresentationbrut + dp.indemnite_de_transport AS indemnite,
  dp.avantages_en_nature AS avantages_en_nature,
  dp.montant_brut AS montant_brut,
  dp.cnaps AS cnaps,
  dp.net_a_payer AS net_a_payer,
  dp.imposable AS imposable,
  dp.irsa AS irsa,
  dp.reductionpourpersonnesacharge AS reductionpourpersonnesacharge,
  dp.irsanet AS irsanet,
  RPAD(
    (
      ARRAY[
        'JANVIER',
        'FÉVRIER',
        'MARS',
        'AVRIL',
        'MAI',
        'JUIN',
        'JUILLET',
        'AOÛT',
        'SEPTEMBRE',
        'OCTOBRE',
        'NOVEMBRE',
        'DÉCEMBRE'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(dp.mois AS TEXT), 'MM')) AS INT) + 0],
    9,
    ' '
  ) AS mois_lib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(dp.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    dp.mois
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    dp.mois
                  ) AS TEXT)))
                  ELSE CAST((
                    dp.mois
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    dp.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    dp.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    dp.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(dp.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(dp.numero_cnaps AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(dp.nom AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(dp.poste AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    dp.salaire_de_base
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
