        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    dp.reductionpourpersonnesacharge
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    dp.reductionpourpersonnesacharge
                  ) AS TEXT)))
                  ELSE CAST((
                    dp.reductionpourpersonnesacharge
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    dp.irsanet
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    dp.irsanet
                  ) AS TEXT)))
                  ELSE CAST((
                    dp.irsanet
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          RPAD(
            (
              ARRAY[
                'JANVIER',
                'FÉVRIER',
                'MARS',
                'AVRIL',
                'MAI',
                'JUIN',
                'JUILLET',
                'AOÛT',
                'SEPTEMBRE',
                'OCTOBRE',
                'NOVEMBRE',
                'DÉCEMBRE'
              ]
            )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(dp.mois AS TEXT), 'MM')) AS INT) + 0],
            9,
            ' '
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM public.details_paie_edition_finalpdf AS dp
LEFT JOIN public.moiscp AS mcp
  ON dp.mois = mcp.id;

-- Niveau 2 - vue 31 / 100 : FABNONRATTACHE
-- Dependances nouvelles : FABRICATIONCPL.
CREATE VIEW public.fabnonrattache (
    "idfabrication", "daty", "idproduit", "idproduitlib", "qte", "qtepetri", "idligne", "ligne"
) AS
SELECT
  f.id AS idfabrication,
  f.daty AS daty,
  ffille.idingredients AS idproduit,
  ai.libelle AS idproduitlib,
  ffille.qte AS qte,
  ffille.qte AS qtepetri,
  l.id AS idligne,
  l.val AS ligne
FROM public.fabricationcpl AS f
LEFT JOIN public.fabricationfille AS ffille
  ON f.id = ffille.idmere
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = ffille.idingredients
LEFT JOIN public.as_ingredient_maintenance AS aim
  ON aim.id = ffille.idmachine
LEFT JOIN public.ligne AS l
  ON l.id = aim.idligne
LEFT JOIN public.relevefab AS rfab
  ON rfab.idfab = f.id
WHERE
  ai.ispetri = 1;

-- Niveau 2 - vue 32 / 100 : FABRICATIONCPLANNULE
-- Dependances nouvelles : FABRICATIONCPL.
CREATE VIEW public.fabricationcplannule (
    "id", "lancepar", "cible", "remarque", "libelle", "besoin", "daty", "idoffille", "idof", "lanceparlib", "ciblelib", "etat", "etatlib", "fabricationprec", "fabricationsuiv"
) AS
SELECT
  f.id AS id,
  f.lancepar AS lancepar,
  f.cible AS cible,
  f.remarque AS remarque,
  f.libelle AS libelle,
  f.besoin AS besoin,
  f.daty AS daty,
  f.idoffille AS idoffille,
  f.idof AS idof,
  f.lanceparlib AS lanceparlib,
