CREATE VIEW public.historiqueinspectionfillelib (
    "id", "idmere", "idelement", "etatinspection", "remarque", "idelementlib", "etatinspectionlib"
) AS
SELECT
  hif.id AS id,
  hif.idmere AS idmere,
  hif.idelement AS idelement,
  hif.etatinspection AS etatinspection,
  hif.remarque AS remarque,
  eim.idelementinspectionlib AS idelementlib,
  ei.val AS etatinspectionlib
FROM public.historiqueinspectionfille AS hif
