  ON hif.etatinspection = ei.id;

-- Niveau 2 - vue 43 / 100 : HS_FABRICATION_SEMAINE
-- Dependances nouvelles : HEURESUPFABRICATION_CPL.
CREATE VIEW public.hs_fabrication_semaine (
    "idpersonne", "annee", "mois", "semaine", "hs_total", "hs30", "hs50", "if", "jf", "mn", "hd"
) AS
SELECT
  hp.idpersonne AS idpersonne,
  p.annee AS annee,
  p.mois AS mois,
  TO_CHAR(hp.datefabrication, 'IYYY-IW') AS semaine,
  SUM(hp.hs) AS hs_total,
  LEAST(SUM(hp.hs), 8) AS hs30,
  GREATEST(SUM(hp.hs) - 8, 0) AS hs50,
  SUM(hp.if) AS if,
  SUM(hp.jf) AS jf,
  SUM(hp.mn) AS mn,
  SUM(hp.hd) AS hd
FROM public.heuresupfabrication_cpl AS hp
LEFT JOIN public.fabrication AS f
  ON f.id = hp.idfabrication
LEFT JOIN public.periodepaie AS p
  ON hp.datefabrication BETWEEN p.datedebut AND p.datefin
GROUP BY
  hp.idpersonne,
  p.annee,
  p.mois,
  TO_CHAR(hp.datefabrication, 'IYYY-IW');

