-- Niveau 2 - vue 47 / 100 : MONTANTCAISSE
-- Dependances nouvelles : V_ETATCAISSE_CLOTURE.
CREATE VIEW public.montantcaisse (
    "caisselib", "idcaisse", "montanttheorique", "montant", "datedernierreport", "explication", "idcloture"
) AS
SELECT
  etatcaisse.idcaisselib AS caisselib,
  etatcaisse.idcaisse AS idcaisse,
  CAST(ROUND(CAST(etatcaisse.reste AS DECIMAL), 0) AS DECIMAL(30, 0)) AS montanttheorique,
  0 AS montant,
  etatcaisse.datedernierreport AS datedernierreport,
  CAST(NULL AS TEXT) AS explication,
  CAST(NULL AS TEXT) AS idcloture
FROM public.v_etatcaisse_cloture AS etatcaisse
WHERE
  DATE_TRUNC('DAY', etatcaisse.datedernierreport) <= DATE_TRUNC('day', LOCALTIMESTAMP(0));

-- Niveau 2 - vue 48 / 100 : MOYENNEPANNESTRAVAUX
