-- Niveau 2 - vue 49 / 100 : MVTINTRACAISSETRAITEV
-- Dependances nouvelles : TRAITELIB_GRP.
CREATE VIEW public.mvtintracaissetraitev (
    "id", "daty", "caissedepart", "caissearrivee", "montant", "modepaiement", "remarque", "etat", "designation", "idtraite", "etatversement", "idfinaledestination", "dateecheance", "reference", "tiers", "codeclient", "caissedepartlib", "caissearriveelib", "modepaiementlib", "etatlib", "etatversementlib", "finaledestinationlib", "facture"
) AS
SELECT
  mic.id AS id,
  mic.daty AS daty,
  mic.caissedepart AS caissedepart,
  mic.caissearrivee AS caissearrivee,
  mic.montant AS montant,
  mic.modepaiement AS modepaiement,
  mic.remarque AS remarque,
  mic.etat AS etat,
  mic.designation AS designation,
  mic.idtraite AS idtraite,
  mic.etatversement AS etatversement,
  mic.idfinaledestination AS idfinaledestination,
  t.dateecheance AS dateecheance,
  t.reference AS reference,
  t.tiers AS tiers,
  t.cdclt AS codeclient,
  c1.val AS caissedepartlib,
  c2.val AS caissearriveelib,
  m.desce AS modepaiementlib,
  CASE WHEN mic.etat = 1 THEN 'CREE' WHEN mic.etat >= 11 THEN 'VISE' ELSE NULL END AS etatlib,
  CASE
    WHEN mic.etatversement = -2
    THEN 'encaissee'
    WHEN mic.etatversement = 11
    THEN 'versee'
    ELSE NULL
  END AS etatversementlib,
  c3.val AS finaledestinationlib,
  grp.code AS facture
FROM public.mvtintracaisse AS mic
JOIN (
  SELECT
    tr.id,
    tr.daty,
    ti.nom AS tiers,
    ba.val AS banque,
    tr.dateecheance,
    tr.etat,
    tr.montant,
    tr.reference,
    CAST(NULL AS TEXT) AS cdclt,
    ba.id AS idbanque,
    tr.idtypepiece,
    tp.val AS typepiece
  FROM public.traite AS tr
  LEFT JOIN public.client AS ti
    ON CAST(tr.tiers AS TEXT) = CAST(ti.id AS TEXT)
  LEFT JOIN public.banque AS ba
    ON CAST(tr.banque AS TEXT) = CAST(ba.id AS TEXT)
  LEFT JOIN public.type_piece AS tp
    ON CAST(tp.id AS TEXT) = CAST(tr.idtypepiece AS TEXT)
) AS t
  ON t.id = mic.idtraite
LEFT JOIN public.caisse AS c1
  ON c1.id = mic.caissedepart
LEFT JOIN public.caisse AS c2
  ON c2.id = mic.caissearrivee
LEFT JOIN public.caisse AS c3
  ON c3.id = mic.idfinaledestination
LEFT JOIN public.modepaiement AS m
  ON m.id = mic.modepaiement
LEFT JOIN public.traitelib_grp AS grp
  ON mic.idtraite = grp.idtraite
WHERE
  mic.etatversement = 11
  AND NOT mic.idtraite IN (
    SELECT
      mvtintracaisse.idtraite AS idtraite
    FROM public.mvtintracaisse AS mvtintracaisse
    WHERE
      mvtintracaisse.etatversement = -2
  );

