CREATE VIEW public.mvtstockfilletransfert (
    "idtransfertdetail", "entree", "sortie"
) AS
SELECT
  m.idtransfertdetail AS idtransfertdetail,
  CAST(SUM(COALESCE(m.entree, 0)) AS DECIMAL(30, 5)) AS entree,
  CAST(SUM(COALESCE(m.sortie, 0)) AS DECIMAL(30, 5)) AS sortie
FROM public.mvtstockfillelib AS m
LEFT JOIN public.mvtstock AS mv
  ON mv.id = m.idmvtstock
WHERE
  mv.etat >= 11
GROUP BY
  m.idtransfertdetail;

