-- Niveau 2 - vue 57 / 100 : OFFILLESTOCK_RECAP_JOUR
-- Dependances nouvelles : OFFILLELIBSTOCK.
CREATE VIEW public.offillestock_recap_jour (
    "daty", "nombre", "qte", "qtefabrique", "qtereste"
) AS
SELECT
  DATE_TRUNC('DAY', offillelibstock.daty) AS daty,
  COUNT(*) AS nombre,
  CAST(SUM(COALESCE(offillelibstock.qte, 0)) AS DECIMAL(30, 5)) AS qte,
  CAST(SUM(COALESCE(offillelibstock.qtefabrique, 0)) AS DECIMAL(30, 5)) AS qtefabrique,
  CAST(SUM(COALESCE(offillelibstock.qtereste, 0)) AS DECIMAL(30, 5)) AS qtereste
FROM public.offillelibstock AS offillelibstock
GROUP BY
  DATE_TRUNC('DAY', offillelibstock.daty);

-- Niveau 2 - vue 58 / 100 : OFNONRATTACHEREEL
-- Dependances nouvelles : OFFILLELIBSTOCK.
CREATE VIEW public.ofnonrattachereel (
    "idoffille", "daty", "idproduit", "idproduitlib", "qte", "qtepetri", "idligne", "ligne", "lancepar"
) AS
SELECT
  offille.id AS idoffille,
  o.daty AS daty,
  offille.idingredients AS idproduit,
  ai.libelle AS idproduitlib,
  offille.qtefabrique AS qte,
  (
    CAST(offille.qtefabrique AS DECIMAL) / e.nbcarton
  ) AS qtepetri,
  l.id AS idligne,
  l.val AS ligne,
  o.lancepar AS lancepar
FROM public.ofab AS o
LEFT JOIN public.offillelibstock AS offille
  ON o.id = offille.idmere
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = offille.idingredients
LEFT JOIN public.type_produit AS tp
  ON tp.id = ai.typeproduit
LEFT JOIN public.ligne AS l
  ON l.id = tp.idligne
LEFT JOIN public.equivalencecarton AS e
  ON e.idcarton = offille.idingredients
WHERE
  o.etat = 11;

-- Niveau 2 - vue 59 / 100 : PAIEPERS_ELP_CPL
-- Dependances nouvelles : CATEGORIE_QUALIFICATION_LIBC.
CREATE VIEW public.paiepers_elp_cpl (
    "id", "matricule", "id_code_rubrique", "nomrubrique", "date_debut", "date_fin", "gain", "retenue", "remarque", "nompersonnel", "etat", "id_objet", "iduser", "moisregularisation", "anneeregularisation", "idcategorie_qualification", "idfonction", "pourcentage", "idpersonnel", "etatlib"
) AS
SELECT
  ppe.id AS id,
  pip2.matricule AS matricule,
  pr.id AS id_code_rubrique,
  pr.val AS nomrubrique,
  ppe.date_debut AS date_debut,
  ppe.date_fin AS date_fin,
  ppe.gain AS gain,
  ppe.retenue AS retenue,
  ppe.remarque AS remarque,
  NULLIF(CONCAT(pip.nom, ' ', pip.prenom), '') AS nompersonnel,
  ppe.etat AS etat,
  ppe.id_objet AS id_objet,
  ppe.iduser AS iduser,
  ppe.moisregularisation AS moisregularisation,
  ppe.anneeregularisation AS anneeregularisation,
  NULLIF(CONCAT(cq.idcategorielib, ' ', cq.categorie_qualificationlib), '') AS idcategorie_qualification,
  pf.desce AS idfonction,
  ppe.pourcentage AS pourcentage,
  ppe.idpersonnel AS idpersonnel,
  CASE WHEN ppe.etat = 1 THEN 'CREE' WHEN ppe.etat = 11 THEN 'VISEE' ELSE 'INCONNU' END AS etatlib
FROM public.paie_personnel_elementpaie AS ppe
LEFT JOIN public.log_personnel AS pip
  ON CAST(pip.id AS TEXT) = CAST(ppe.idpersonnel AS TEXT)
LEFT JOIN public.categorie_qualification_libc AS cq
  ON CAST(ppe.idcategorie_qualification AS TEXT) = CAST(cq.id AS TEXT)
LEFT JOIN public.paie_fonction AS pf
  ON CAST(ppe.idfonction AS TEXT) = CAST(pf.id AS TEXT)
LEFT JOIN public.paie_rubrique AS pr
  ON CAST(pr.id AS TEXT) = CAST(ppe.code_rubrique AS TEXT)
JOIN public.paie_info_personnel AS pip2
  ON CAST(pip.id AS TEXT) = CAST(pip2.id AS TEXT);

-- Niveau 2 - vue 60 / 100 : PAIE_INFO_JOURS_MOIS
-- Dependances nouvelles : JOURS_PAR_MOIS.
CREATE VIEW public.paie_info_jours_mois (
    "id", "dateembauche", "date_depart", "annee", "mois", "nb_jour", "conge_journalier", "jourplusdepart", "jourplusembauche"
) AS
SELECT
  pip.id AS id,
  pip.dateembauche AS dateembauche,
  pip.date_depart AS date_depart,
  j.annee AS annee,
  j.mois AS mois,
  j.nb_jour AS nb_jour,
  j.conge_journalier AS conge_journalier,
  0 AS jourplusdepart,
  CASE
    WHEN j.annee = EXTRACT(YEAR FROM pip.dateembauche)
    AND j.mois = EXTRACT(MONTH FROM pip.dateembauche)
    THEN EXTRACT(DAY FROM pip.dateembauche)
    ELSE 0
  END AS jourplusembauche
FROM public.paie_info_personnel AS pip, public.jours_par_mois AS j
WHERE
  TO_DATE(
    CAST(NULLIF(CONCAT(j.annee, LPAD(CAST(j.mois AS TEXT), 2, '0')), '') AS TEXT),
    'YYYYMM'
  ) >= TO_DATE(CAST(TO_CHAR(pip.dateembauche, 'YYYYMM') AS TEXT), 'YYYYMM')
  AND pip.date_depart IS NULL
UNION
SELECT
  pip.id AS id,
  pip.dateembauche AS dateembauche,
  pip.date_depart AS date_depart,
  j.annee AS annee,
  j.mois AS mois,
  j.nb_jour AS nb_jour,
  j.conge_journalier AS conge_journalier,
  CASE
    WHEN j.annee = EXTRACT(YEAR FROM pip.date_depart)
    AND j.mois = EXTRACT(MONTH FROM pip.date_depart)
    THEN EXTRACT(DAY FROM pip.date_depart)
    ELSE 0
  END AS jourplusdepart,
  CASE
    WHEN j.annee = EXTRACT(YEAR FROM pip.dateembauche)
    AND j.mois = EXTRACT(MONTH FROM pip.dateembauche)
    THEN EXTRACT(DAY FROM pip.dateembauche)
    ELSE 0
  END AS jourplusembauche
FROM public.paie_info_personnel AS pip, public.jours_par_mois AS j
WHERE
  TO_DATE(
    CAST(NULLIF(CONCAT(j.annee, LPAD(CAST(j.mois AS TEXT), 2, '0')), '') AS TEXT),
    'YYYYMM'
  ) >= TO_DATE(CAST(TO_CHAR(pip.dateembauche, 'YYYYMM') AS TEXT), 'YYYYMM')
  AND NOT pip.date_depart IS NULL
  AND TO_DATE(
    CAST(NULLIF(CONCAT(j.annee, LPAD(CAST(j.mois AS TEXT), 2, '0')), '') AS TEXT),
    'YYYYMM'
  ) <= TO_DATE(CAST(TO_CHAR(pip.date_depart, 'YYYYMM') AS TEXT), 'YYYYMM');

