-- Niveau 2 - vue 62 / 100 : PAIE_PERS_ELTPAIE_LIB2
-- Dependances nouvelles : CATEGORIE_QUALIFICATION_LIBC.
CREATE VIEW public.paie_pers_eltpaie_lib2 (
    "id", "matricule", "id_code_rubrique", "code_rubrique", "date_debut", "date_fin", "gain", "retenue", "remarque", "idpersonnel", "etat", "id_objet", "iduser", "moisregularisation", "anneeregularisation", "rubrique", "moislib", "idcategorie_qualification", "idfonction", "pourcentage", "etatlib", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.matricule AS matricule,
  base.id_code_rubrique AS id_code_rubrique,
  base.code_rubrique AS code_rubrique,
  base.date_debut AS date_debut,
  base.date_fin AS date_fin,
  base.gain AS gain,
  base.retenue AS retenue,
  base.remarque AS remarque,
  base.idpersonnel AS idpersonnel,
  base.etat AS etat,
  base.id_objet AS id_objet,
  base.iduser AS iduser,
  base.moisregularisation AS moisregularisation,
  base.anneeregularisation AS anneeregularisation,
  base.rubrique AS rubrique,
  base.moislib AS moislib,
  base.idcategorie_qualification AS idcategorie_qualification,
  base.idfonction AS idfonction,
  base.pourcentage AS pourcentage,
  base.etatlib AS etatlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_code_rubrique AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.code_rubrique AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.date_debut, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.date_fin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.gain
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.gain
                  ) AS TEXT)))
                  ELSE CAST((
                    base.gain
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.retenue
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.retenue
                  ) AS TEXT)))
                  ELSE CAST((
                    base.retenue
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.remarque AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.etat AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.id_objet AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.iduser AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.moisregularisation AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(base.anneeregularisation AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(base.rubrique AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.moislib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idcategorie_qualification AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idfonction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.pourcentage
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.pourcentage
                  ) AS TEXT)))
                  ELSE CAST((
                    base.pourcentage
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.etatlib AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    ppe.id AS id,
    pip2.matricule AS matricule,
    pr.id AS id_code_rubrique,
    pr.val AS code_rubrique,
    ppe.date_debut AS date_debut,
    ppe.date_fin AS date_fin,
    ppe.gain AS gain,
    ppe.retenue AS retenue,
    ppe.remarque AS remarque,
    NULLIF(CONCAT(pip.nom, ' ', pip.prenom), '') AS idpersonnel,
    ppe.etat AS etat,
    ppe.id_objet AS id_objet,
    ppe.iduser AS iduser,
    ppe.moisregularisation AS moisregularisation,
    ppe.anneeregularisation AS anneeregularisation,
    pr.val AS rubrique,
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(CAST(ppe.moisregularisation AS DECIMAL), 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
    NULLIF(CONCAT(cq.idcategorielib, ' ', cq.categorie_qualificationlib), '') AS idcategorie_qualification,
    pf.desce AS idfonction,
    ppe.pourcentage AS pourcentage,
    CASE
      WHEN ppe.etat = CAST('1' AS DECIMAL)
      THEN 'CREE'
      WHEN ppe.etat = CAST('11' AS DECIMAL)
      THEN 'VALIDE'
      WHEN ppe.etat = CAST('0' AS DECIMAL)
      THEN 'ANNULE'
      ELSE 'INCONNU'
    END AS etatlib
  FROM public.paie_personnel_elementpaie AS ppe
  LEFT JOIN public.log_personnel AS pip
    ON CAST(pip.id AS VARCHAR(4000)) = CAST(ppe.idpersonnel AS VARCHAR(4000))
  LEFT JOIN public.categorie_qualification_libc AS cq
    ON CAST(ppe.idcategorie_qualification AS VARCHAR(4000)) = CAST(cq.id AS VARCHAR(4000))
  LEFT JOIN public.paie_fonction AS pf
    ON CAST(ppe.idfonction AS VARCHAR(4000)) = CAST(pf.id AS VARCHAR(4000))
  LEFT JOIN public.paie_rubrique AS pr
    ON CAST(pr.id AS VARCHAR(4000)) = CAST(ppe.code_rubrique AS VARCHAR(4000))
  JOIN public.paie_info_personnel AS pip2
    ON CAST(pip.id AS VARCHAR(4000)) = CAST(pip2.id AS VARCHAR(4000))
  WHERE
    ppe.code_rubrique <> 'PR0000150HS'
) AS base;

