-- Niveau 2 - vue 64 / 100 : PLANNING_CPL
-- Dependances nouvelles : DEMANDETRAVAUX_CPL.
CREATE VIEW public.planning_cpl (
    "id", "refobjet", "estperiodique", "idtypemaintenance", "idmachine", "unite", "frequence", "datedebut", "datefin", "duree", "etat", "heure", "idsource", "idmachinelib", "idtypemaintenancelib", "estperiodiquelib", "etatlib", "unitelib", "priorite", "prioritelib", "iddemandetravaux", "idordretravaux", "idordretravauxfille", "idtravaux", "identite", "identitelib", "etatdemandetravaux", "etatordretravaux", "etattravaux", "etatdemandetravauxlib", "etatordretravauxlib", "etattravauxlib", "cout", "iddepartement"
) AS
SELECT
  p.id AS id,
  p.refobjet AS refobjet,
  p.estperiodique AS estperiodique,
  p.idtypemaintenance AS idtypemaintenance,
  p.idmachine AS idmachine,
  p.unite AS unite,
  p.frequence AS frequence,
  p.datedebut AS datedebut,
  p.datefin AS datefin,
  p.duree AS duree,
  p.etat AS etat,
  p.heure AS heure,
  p.idsource AS idsource,
  ai.libelle AS idmachinelib,
  t.val AS idtypemaintenancelib,
  CASE WHEN p.estperiodique = 1 THEN 'OUI' ELSE 'NON' END AS estperiodiquelib,
  CASE WHEN p.etat = 11 THEN 'VALID&Eacute;E' ELSE 'CR&Eacute;E' END AS etatlib,
  u.val AS unitelib,
  d.priorite AS priorite,
  d.prioritelib AS prioritelib,
  d.id AS iddemandetravaux,
  o.id AS idordretravaux,
  otf.id AS idordretravauxfille,
  tr.id AS idtravaux,
  e.id AS identite,
  e.val AS identitelib,
  d.etat AS etatdemandetravaux,
  o.etat AS etatordretravaux,
  tr.etat AS etattravaux,
  CASE d.etat WHEN 1 THEN 'Creee' WHEN 11 THEN 'Visee' ELSE 'Aucun' END AS etatdemandetravauxlib,
  CASE o.etat WHEN 1 THEN 'Creee' WHEN 11 THEN 'Visee' ELSE 'Aucun' END AS etatordretravauxlib,
  CASE tr.etat
    WHEN 1
    THEN 'Creee'
    WHEN 11
    THEN 'Visee'
    WHEN 21
    THEN 'Entamee'
    WHEN 41
    THEN 'Terminee'
    ELSE 'Aucun'
  END AS etattravauxlib,
  COALESCE(SUM(fff.pu * fff.qte), 0) AS cout,
  ai.parfums AS iddepartement
FROM public.planning AS p
LEFT JOIN public.as_ingredient_maintenance AS aim
  ON aim.id = p.idmachine
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = aim.idingredient
LEFT JOIN public.typemaintenance AS t
  ON t.id = p.idtypemaintenance
LEFT JOIN public.unitemaintenance AS u
  ON u.id = p.unite
LEFT JOIN public.demandetravaux_cpl AS d
  ON d.id = p.idsource
LEFT JOIN public.ordretravaux AS o
  ON o.idbc = d.id
LEFT JOIN public.ordretravauxfille AS otf
  ON otf.idmere = o.id
LEFT JOIN public.travaux AS tr
  ON tr.idoffille = otf.id
LEFT JOIN public.travauxfille AS trf
  ON trf.idmere = tr.id
LEFT JOIN public.entite AS e
  ON e.id = aim.identite
LEFT JOIN public.facturefournisseur AS f
  ON f.idref = tr.id
LEFT JOIN public.facturefournisseurfille AS fff
  ON fff.idfacturefournisseur = f.id
GROUP BY
  p.id,
  p.refobjet,
  p.estperiodique,
  p.idtypemaintenance,
  p.idmachine,
  p.unite,
  p.frequence,
  p.datedebut,
  p.datefin,
  p.duree,
  p.etat,
  p.heure,
  p.idsource,
  ai.libelle,
  t.val,
  u.val,
  d.priorite,
  d.prioritelib,
  d.id,
  d.etat,
  o.id,
  o.etat,
  otf.id,
  tr.id,
  tr.etat,
  e.id,
  e.val,
  ai.parfums
ORDER BY
  datedebut;

-- Niveau 2 - vue 65 / 100 : PREVISION_COMPLET_CPL
-- Dependances nouvelles : PREVISION_CPL.
CREATE VIEW public.prevision_complet_cpl (
    "id", "designation", "idcaisse", "idcaisselib", "idventedetail", "idvente", "idventelib", "idvirement", "debit", "credit", "daty", "etat", "idop", "idoplib", "idorigine", "iddevise", "iddeviselib", "taux", "idtiers", "idtierslib", "compte", "effectifdebit", "effectifcredit", "depenseecart", "recetteecart", "idfacture", "idfacturemere"
) AS
SELECT
  p.id AS id,
  p.designation AS designation,
  p.idcaisse AS idcaisse,
  p.idcaisselib AS idcaisselib,
  p.idventedetail AS idventedetail,
  p.idvente AS idvente,
  p.idventelib AS idventelib,
  p.idvirement AS idvirement,
  p.debit AS debit,
  p.credit AS credit,
  p.daty AS daty,
  p.etat AS etat,
  p.idop AS idop,
  p.idoplib AS idoplib,
  p.idorigine AS idorigine,
  p.iddevise AS iddevise,
  p.iddeviselib AS iddeviselib,
  p.taux AS taux,
  p.idtiers AS idtiers,
  t.nom AS idtierslib,
  p.compte AS compte,
  COALESCE(pe.effectifdeb, 0) AS effectifdebit,
  COALESCE(pe.effectifcred, 0) AS effectifcredit,
  p.debit - COALESCE(pe.effectifdeb, 0) AS depenseecart,
  p.credit - COALESCE(pe.effectifcred, 0) AS recetteecart,
  p.idfacture AS idfacture,
  COALESCE(v.idvente, f.idfacturefournisseur) AS idfacturemere
FROM public.prevision_cpl AS p
LEFT JOIN public.previsionavecmvtcaisse AS pe
  ON pe.id = p.id
LEFT JOIN public.vente_details AS v
  ON v.id = p.idfacture
LEFT JOIN public.facturefournisseurfille AS f
  ON f.id = p.idfacture
LEFT JOIN public.tiers AS t
  ON t.id = p.idtiers;

-- Niveau 2 - vue 66 / 100 : PRIXTEMP
-- Dependances nouvelles : V_ETATSTOCK_ENTREE.
CREATE VIEW public.prixtemp (
    "putemp", "idproduit"
) AS
SELECT
  AVG(vee.pu) AS putemp,
  vee.idproduit AS idproduit
FROM public.v_etatstock_entree AS vee
GROUP BY
  vee.idproduit;

-- Niveau 2 - vue 67 / 100 : PROCESSMAINTENANCEGLOBAL
-- Dependances nouvelles : PROCESSMAINTENANCELIB.
CREATE VIEW public.processmaintenanceglobal (
    "idtravaux", "idpersonnel", "dureereel", "dureereelhms"
) AS
SELECT
  pr.idtravaux AS idtravaux,
  pr.idpersonnel AS idpersonnel,
  SUM(pr.ecart_seconde) AS dureereel,
  NULLIF(
    CONCAT(
      LPAD(
        CAST(FLOOR(CAST(CAST(SUM(pr.ecart_seconde) AS DECIMAL) AS DECIMAL) / 3600) AS TEXT),
        2,
        '0'
      ),
      ':',
      LPAD(
        CAST(FLOOR(
          CAST(CAST(CAST(SUM(pr.ecart_seconde) AS DECIMAL) AS DECIMAL) % CAST(3600 AS DECIMAL) AS DECIMAL) / 60
        ) AS TEXT),
        2,
        '0'
      ),
      ':',
      LPAD(
        CAST(CAST(CAST(SUM(pr.ecart_seconde) AS DECIMAL) AS DECIMAL) % CAST(60 AS DECIMAL) AS TEXT),
        2,
        '0'
      )
    ),
    ''
  ) AS dureereelhms
FROM public.processmaintenancelib AS pr
GROUP BY
  pr.idtravaux,
  pr.idpersonnel;

-- Niveau 2 - vue 68 / 100 : RESULTATFABRICATION
-- Dependances nouvelles : OFFILLELIBSTOCK.
CREATE VIEW public.resultatfabrication (
    "id", "idoffille", "idfabrication", "idproduit", "idproduitlib", "qte", "idingredients", "qteingredients", "idligne", "daty", "entreedechet"
) AS
SELECT
  off.idmere AS id,
  off.id AS idoffille,
  f.id AS idfabrication,
  off.idingredients AS idproduit,
  off.libelle AS idproduitlib,
  off.qte AS qte,
  ff.idingredients AS idingredients,
  ff.qte AS qteingredients,
  m.idligne AS idligne,
  f.daty AS daty,
  COALESCE(
    (
      SELECT
        SUM(mvtstfillefabcatvisegroupe.entree) AS _col_0
      FROM public.mvtstfillefabcatvisegroupe AS mvtstfillefabcatvisegroupe
      WHERE
        mvtstfillefabcatvisegroupe.idfab = f.id
        AND mvtstfillefabcatvisegroupe.entree > 0
        AND mvtstfillefabcatvisegroupe.categorieingredient = 'Dechets'
    ),
    0
  ) AS entreedechet
FROM public.fabricationfille AS ff
LEFT JOIN public.fabrication AS f
  ON f.id = ff.idmere
LEFT JOIN public.offillelibstock AS off
  ON off.id = f.idoffille
LEFT JOIN public.machine AS m
  ON m.id = ff.idmachine
WHERE
  f.etat = 11 AND NOT off.idingredients IS NULL;

-- Niveau 2 - vue 69 / 100 : RESULTATPREVEFFECTIFTOUS
-- Dependances nouvelles : TOUSLESDATE.
CREATE VIEW public.resultatpreveffectiftous (
    "daty", "debit", "credit", "semaine", "annee", "mois"
) AS
SELECT
  t.daty AS daty,
  COALESCE(r.debit, 0) AS debit,
  COALESCE(r.credit, 0) AS credit,
  (
    CAST(TO_CHAR(t.daty, 'IW') AS INT)
  ) AS semaine,
  EXTRACT(YEAR FROM t.daty) AS annee,
  EXTRACT(MONTH FROM t.daty) AS mois
FROM public.touslesdate AS t
LEFT JOIN public.resultatprevisionneleffectif AS r
  ON t.daty = r.daty;

