-- Niveau 2 - vue 73 / 100 : ST_INGREDIENTSVENTEPOS
-- Dependances nouvelles : V_REFERENCE_COULEUR.
CREATE VIEW public.st_ingredientsventepos (
    "id", "libelle", "seuil", "unite", "quantiteparpack", "pu", "actif", "photo", "calorie", "durre", "compose", "categorieingredient", "idfournisseur", "daty", "qtelimite", "pv", "libellevente", "seuilmin", "seuilmax", "puachatusd", "puachateuro", "puachatautredevise", "puventeusd", "puventeeuro", "puventeautredevise", "isvente", "isachat", "compte_vente", "compte_achat", "tva", "taux", "compte", "libellecomposant", "couleur", "couleurlib", "taille", "marque", "marquelib", "codebarre", "reference", "codegros", "pvgros", "unitelib", "designation", "typestock", "pvtva", "montantttc"
) AS
SELECT
  ai.id AS id,
  ai.libelle AS libelle,
  ai.seuil AS seuil,
  ai.unite AS unite,
  ai.quantiteparpack AS quantiteparpack,
  ai.pu AS pu,
  ai.actif AS actif,
  ai.photo AS photo,
  ai.calorie AS calorie,
  ai.durre AS durre,
  ai.compose AS compose,
  ai.categorieingredient AS categorieingredient,
  ai.idfournisseur AS idfournisseur,
  ai.daty AS daty,
  ai.qtelimite AS qtelimite,
  ai.pv AS pv,
  ai.libellevente AS libellevente,
  ai.seuilmin AS seuilmin,
  ai.seuilmax AS seuilmax,
  ai.puachatusd AS puachatusd,
  ai.puachateuro AS puachateuro,
  ai.puachatautredevise AS puachatautredevise,
  ai.puventeusd AS puventeusd,
  ai.puventeeuro AS puventeeuro,
  ai.puventeautredevise AS puventeautredevise,
  ai.isvente AS isvente,
  ai.isachat AS isachat,
  ai.compte_vente AS compte_vente,
  ai.compte_achat AS compte_achat,
  ai.tva AS tva,
  1 AS taux,
  ai.compte_vente AS compte,
  NULLIF(CONCAT(ai.libelle, ' ', ai.couleur, ' ', ai.taille), '') AS libellecomposant,
  ai.couleur AS couleur,
  vrc.nomcouleur AS couleurlib,
  ai.taille AS taille,
  ai.marque AS marque,
  pointure.val AS marquelib,
  ai.codebarre AS codebarre,
  ai.reference AS reference,
  ai.codegros AS codegros,
  ai.pvgros AS pvgros,
  u.val AS unitelib,
  ai.libelle || ' - ' || u.val AS designation,
  ai.typestock AS typestock,
  CAST(ai.pv * (
    1 + CAST(ai.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS pvtva,
  CAST(ai.pv * (
    1 + CAST(ai.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS montantttc
FROM public.as_ingredients AS ai
LEFT JOIN public.as_recette AS ar
  ON ar.idproduits = ai.id
LEFT JOIN public.as_ingredients AS cps
  ON cps.id = ar.idingredients
LEFT JOIN public.as_unite AS u
  ON ai.unite = u.id
LEFT JOIN public.v_reference_couleur AS vrc
  ON vrc.referencecouleur = ai.couleur
LEFT JOIN public.pointure AS pointure
  ON ai.marque = pointure.id
WHERE
  ai.pv <> 0 AND ai.actif = 1
GROUP BY
  ai.id,
  ai.libelle,
  ai.seuil,
  ai.unite,
  ai.quantiteparpack,
  ai.pu,
  ai.actif,
  ai.photo,
  ai.calorie,
  ai.durre,
  ai.compose,
  ai.categorieingredient,
  ai.idfournisseur,
  ai.daty,
  ai.qtelimite,
  ai.pv,
  ai.libellevente,
  ai.seuilmin,
  ai.seuilmax,
  ai.puachatusd,
  ai.puachateuro,
  ai.puachatautredevise,
  ai.puventeusd,
  ai.puventeeuro,
  ai.puventeautredevise,
  ai.isvente,
  ai.isachat,
  ai.compte_vente,
  ai.compte_achat,
  ai.tva,
  ai.couleur,
  vrc.nomcouleur,
  ai.taille,
  ai.marque,
  pointure.val,
  ai.codebarre,
  ai.reference,
  ai.codegros,
  ai.pvgros,
  u.val,
  ai.typestock;

-- Niveau 2 - vue 74 / 100 : SUM_HS_DAY
-- Dependances nouvelles : HEURESUPFABRICATION_CPL.
CREATE VIEW public.sum_hs_day (
    "jour", "avg_hs_per_day", "iddepartement", "departementlib"
) AS
SELECT
  heuresupfabrication_cpl.datefabrication AS jour,
  SUM(heuresupfabrication_cpl.hs) AS avg_hs_per_day,
  heuresupfabrication_cpl.iddepartement AS iddepartement,
  heuresupfabrication_cpl.departementlib AS departementlib
FROM public.heuresupfabrication_cpl AS heuresupfabrication_cpl
GROUP BY
  heuresupfabrication_cpl.datefabrication,
  heuresupfabrication_cpl.iddepartement,
  heuresupfabrication_cpl.departementlib
ORDER BY
  jour;

-- Niveau 2 - vue 75 / 100 : SUM_HS_MONTH
-- Dependances nouvelles : HEURESUPFABRICATION_CPL.
CREATE VIEW public.sum_hs_month (
    "annee", "mois", "avg_hs_per_month", "iddepartement", "departementlib"
) AS
SELECT
  EXTRACT(YEAR FROM heuresupfabrication_cpl.datefabrication) AS annee,
  EXTRACT(MONTH FROM heuresupfabrication_cpl.datefabrication) AS mois,
  SUM(heuresupfabrication_cpl.hs) AS avg_hs_per_month,
  heuresupfabrication_cpl.iddepartement AS iddepartement,
  heuresupfabrication_cpl.departementlib AS departementlib
FROM public.heuresupfabrication_cpl AS heuresupfabrication_cpl
GROUP BY
  EXTRACT(YEAR FROM heuresupfabrication_cpl.datefabrication),
  EXTRACT(MONTH FROM heuresupfabrication_cpl.datefabrication),
  heuresupfabrication_cpl.iddepartement,
  heuresupfabrication_cpl.departementlib
ORDER BY
  annee,
  mois;

-- Niveau 2 - vue 76 / 100 : SUM_HS_MONTH_LIB
-- Dependances nouvelles : HEURESUPFABRICATION_CPL.
CREATE VIEW public.sum_hs_month_lib (
    "annee", "mois", "monthlib", "avg_hs_per_month", "iddepartement", "departementlib"
) AS
SELECT
  EXTRACT(YEAR FROM heuresupfabrication_cpl.datefabrication) AS annee,
  EXTRACT(MONTH FROM heuresupfabrication_cpl.datefabrication) AS mois,
  NULLIF(
    CONCAT(
      RPAD(
        (
          ARRAY[
            'Janvier',
            'Février',
            'Mars',
            'Avril',
            'Mai',
            'Juin',
            'Juillet',
            'Août',
            'Septembre',
            'Octobre',
            'Novembre',
            'Décembre'
          ]
        )[CAST(EXTRACT(MONTH FROM heuresupfabrication_cpl.datefabrication) AS INT) + 0],
        9,
        ' '
      ),
      ' ',
      TO_CHAR(heuresupfabrication_cpl.datefabrication, 'YYYY')
    ),
    ''
  ) AS monthlib,
  SUM(heuresupfabrication_cpl.hs) AS avg_hs_per_month,
  heuresupfabrication_cpl.iddepartement AS iddepartement,
  heuresupfabrication_cpl.departementlib AS departementlib
FROM public.heuresupfabrication_cpl AS heuresupfabrication_cpl
GROUP BY
  EXTRACT(YEAR FROM heuresupfabrication_cpl.datefabrication),
  EXTRACT(MONTH FROM heuresupfabrication_cpl.datefabrication),
  NULLIF(
    CONCAT(
      RPAD(
        (
          ARRAY[
            'Janvier',
            'Février',
            'Mars',
            'Avril',
            'Mai',
            'Juin',
            'Juillet',
            'Août',
            'Septembre',
            'Octobre',
            'Novembre',
            'Décembre'
          ]
        )[CAST(EXTRACT(MONTH FROM heuresupfabrication_cpl.datefabrication) AS INT) + 0],
        9,
        ' '
      ),
      ' ',
      TO_CHAR(heuresupfabrication_cpl.datefabrication, 'YYYY')
    ),
    ''
  ),
  heuresupfabrication_cpl.iddepartement,
  heuresupfabrication_cpl.departementlib
ORDER BY
  annee,
  mois;

-- Niveau 2 - vue 77 / 100 : SUM_HS_YEAR
-- Dependances nouvelles : HEURESUPFABRICATION_CPL.
CREATE VIEW public.sum_hs_year (
    "annee", "avg_hs_per_year", "iddepartement", "departementlib"
) AS
SELECT
  EXTRACT(YEAR FROM heuresupfabrication_cpl.datefabrication) AS annee,
  SUM(heuresupfabrication_cpl.hs) AS avg_hs_per_year,
  heuresupfabrication_cpl.iddepartement AS iddepartement,
  heuresupfabrication_cpl.departementlib AS departementlib
FROM public.heuresupfabrication_cpl AS heuresupfabrication_cpl
GROUP BY
  EXTRACT(YEAR FROM heuresupfabrication_cpl.datefabrication),
  heuresupfabrication_cpl.iddepartement,
  heuresupfabrication_cpl.departementlib
ORDER BY
  annee;

-- Niveau 2 - vue 78 / 100 : TARIF_INGREDIENTS_MAX_MN
-- Dependances nouvelles : TARIF_INGREDIENTS_MAX_DATE_MN.
CREATE VIEW public.tarif_ingredients_max_mn (
    "idingredient", "unite", "idtypeclient", "daty", "idmagasin", "prixunitaire"
) AS
SELECT
  timd.idingredient AS idingredient,
  timd.unite AS unite,
  timd.idtypeclient AS idtypeclient,
  timd.daty AS daty,
  timd.idmagasin AS idmagasin,
  ti.prixunitaire AS prixunitaire
FROM public.tarif_ingredients_max_date_mn AS timd
LEFT JOIN (
  SELECT
    tarif_ingredients.id AS id,
    tarif_ingredients.idtypeclient AS idtypeclient,
    tarif_ingredients.idingredient AS idingredient,
    tarif_ingredients.daty AS daty,
    tarif_ingredients.prixunitaire AS prixunitaire,
    tarif_ingredients.unite AS unite,
    tarif_ingredients.idmagasin AS idmagasin
  FROM public.tarif_ingredients AS tarif_ingredients
  WHERE
    tarif_ingredients.idmagasin IS NULL
) AS ti
  ON ti.daty = timd.daty
  AND timd.idingredient = ti.idingredient
  AND timd.unite = ti.unite
  AND timd.idtypeclient = ti.idtypeclient;

-- Niveau 2 - vue 79 / 100 : TARIF_INGREDIENTS_MAX_MNN
-- Dependances nouvelles : TARIF_INGREDIENTS_MAX_DATE_MNN.
CREATE VIEW public.tarif_ingredients_max_mnn (
    "idingredient", "unite", "idtypeclient", "daty", "idmagasin", "prixunitaire"
) AS
SELECT
  timd.idingredient AS idingredient,
  timd.unite AS unite,
  timd.idtypeclient AS idtypeclient,
  timd.daty AS daty,
  timd.idmagasin AS idmagasin,
  ti.prixunitaire AS prixunitaire
FROM public.tarif_ingredients_max_date_mnn AS timd
LEFT JOIN (
  SELECT
    tarif_ingredients.id AS id,
    tarif_ingredients.idtypeclient AS idtypeclient,
    tarif_ingredients.idingredient AS idingredient,
    tarif_ingredients.daty AS daty,
    tarif_ingredients.prixunitaire AS prixunitaire,
    tarif_ingredients.unite AS unite,
    tarif_ingredients.idmagasin AS idmagasin
  FROM public.tarif_ingredients AS tarif_ingredients
  WHERE
    NOT tarif_ingredients.idmagasin IS NULL
) AS ti
  ON ti.daty = timd.daty
  AND timd.idingredient = ti.idingredient
  AND timd.unite = ti.unite
  AND ti.idmagasin = timd.idmagasin
  AND timd.idtypeclient = ti.idtypeclient;

-- Niveau 2 - vue 80 / 100 : TEST_SITUATION_SALAIRE_EDITION
-- Dependances nouvelles : PAIE_EDITION_LIBCOMPLET.
CREATE VIEW public.test_situation_salaire_edition (
    "id", "idedition", "nbenfant", "matricule", "nom", "prenom", "personnel", "fonction", "idfonction", "classification", "idcategorie", "iddirection", "direction", "section", "section_numero", "section_libelle", "salaire", "salairebrute", "heuremois", "heurepresence", "tauxhoraire", "salairemois", "heuresup", "rappel", "retenuabsc", "prime", "congepayer", "preavis", "netpayer", "netpayerarr", "indamdivfixe", "cnaps", "ostie", "netimposable", "netimposablearr", "irsa", "irsanet", "allocation", "avancesalaire", "avanceexcep", "annee", "mois"
) AS
SELECT
  lp.id AS id,
  pe.idedition AS idedition,
  pip.nbenfant AS nbenfant,
  pip.matricule AS matricule,
  NULLIF(TRIM(TRAILING ' ' FROM lp.nom), '') AS nom,
  NULLIF(TRIM(TRAILING ' ' FROM lp.prenom), '') AS prenom,
  NULLIF(
    CONCAT(
      NULLIF(TRIM(TRAILING ' ' FROM lp.nom), ''),
      ' ',
      NULLIF(TRIM(TRAILING ' ' FROM lp.prenom), '')
    ),
    ''
  ) AS personnel,
  pf.desce AS fonction,
  pf.id AS idfonction,
  pc.val AS classification,
  pc.id AS idcategorie,
  ld.id AS iddirection,
  ld.val AS direction,
  ls.id AS section,
  ls.code_service AS section_numero,
  ls.libelle AS section_libelle,
  COALESCE(salairedebase.salairedebase, 0) AS salaire,
  COALESCE(totalgain.gain, 0) AS salairebrute,
  173.33 AS heuremois,
  COALESCE(poi.heurenormal, 0) AS heurepresence,
  COALESCE(pe.tauxhoraire, 0) AS tauxhoraire,
  COALESCE(salaire.gain, 0) AS salairemois,
  COALESCE(heuresup.gain, 0) AS heuresup,
  COALESCE(rappel.gain, 0) AS rappel,
  COALESCE(retenuabsc.retenue, 0) AS retenuabsc,
  COALESCE(prime.gain, 0) AS prime,
  COALESCE(congepayer.gain, 0) AS congepayer,
  COALESCE(preavis.gain, 0) AS preavis,
  COALESCE(netpayer.gain, 0) AS netpayer,
  COALESCE(netpayerarr.gain, 0) AS netpayerarr,
  COALESCE(indamdivfixe.gain, 0) AS indamdivfixe,
  COALESCE(cnaps.retenue, 0) AS cnaps,
  COALESCE(ostie.retenue, 0) AS ostie,
  COALESCE(netimposable.retenue, 0) AS netimposable,
  COALESCE(netimposablearr.retenue, 0) AS netimposablearr,
  COALESCE(irsa.retenue, 0) AS irsa,
  COALESCE(irsanet.retenue, 0) AS irsanet,
  COALESCE(allocation.gain, 0) AS allocation,
  COALESCE(avancesalaire.retenue, 0) AS avancesalaire,
  COALESCE(avanceexcep.retenue, 0) AS avanceexcep,
  pe.annee AS annee,
  pe.mois AS mois
/* select * from */
FROM public.paie_edition AS pe
INNER JOIN public.log_personnel AS lp
  ON lp.id = pe.idpersonnel
INNER JOIN public.paie_info_personnel AS pip
  ON pip.id = pe.idpersonnel
INNER JOIN public.log_direction AS ld
  ON pe.direction = ld.id
INNER JOIN public.log_service AS ls
  ON pe.service = ls.id
INNER JOIN public.categorie_paie AS pc
  ON pe.idcategorie = pc.id
INNER JOIN public.paie_fonction AS pf
  ON pe.idfonction = pf.id
INNER JOIN public.pointage AS poi
  ON pe.idpersonnel = poi.idpersonnel
LEFT JOIN (
  SELECT
    pe.idpersonnel AS idpersonnel,
    SUM(pe.gain) AS gain,
    pe.mois AS mois,
    pe.annee AS annee
  FROM public.paie_edition AS pe
  WHERE
    pe.regroupement = 1
  GROUP BY
    pe.idpersonnel,
    pe.mois,
    pe.annee
) AS salaire
  ON salaire.idpersonnel = lp.id
  AND salaire.annee = pe.annee
  AND salaire.mois = pe.mois
LEFT JOIN (
  SELECT
    pe.idpersonnel AS idpersonnel,
    MAX(pe.salairedebase) AS salairedebase,
    pe.mois AS mois,
    pe.annee AS annee
  FROM public.paie_edition AS pe
  WHERE
    pe.regroupement = 18
  GROUP BY
    pe.idpersonnel,
    pe.mois,
    pe.annee
) AS salairedebase
  ON salairedebase.idpersonnel = lp.id
  AND salairedebase.annee = pe.annee
  AND salairedebase.mois = pe.mois
LEFT JOIN (
  SELECT
    pe.idpersonnel AS idpersonnel,
    SUM(pe.gain) AS gain,
    pe.mois AS mois,
    pe.annee AS annee
  FROM public.paie_edition AS pe
  WHERE
    pe.regroupement = 2
  GROUP BY
    pe.idpersonnel,
    pe.mois,
    pe.annee
) AS heuresup
  ON heuresup.idpersonnel = lp.id
  AND heuresup.annee = pe.annee
  AND heuresup.mois = pe.mois
LEFT JOIN (
  SELECT
    pe.idpersonnel AS idpersonnel,
    SUM(pe.gain) AS gain,
    pe.mois AS mois,
    pe.annee AS annee
  FROM public.paie_edition AS pe
  WHERE
    pe.regroupement = 3
  GROUP BY
    pe.idpersonnel,
