  pe.idedition;

-- Niveau 2 - vue 81 / 100 : TRAITEMTTRESTE
-- Dependances nouvelles : TRAITE_LIBMTT.
CREATE VIEW public.traitemttreste (
    "id", "daty", "tiers", "banque", "dateecheance", "etat", "montant", "escompte", "total", "reference", "montantreste", "cdclt", "idbanque", "idtypepiece", "typepiece", "etatversement", "etatversementlib"
) AS
SELECT
  t.id AS id,
  t.daty AS daty,
  t.tiers AS tiers,
  t.banque AS banque,
  t.dateecheance AS dateecheance,
  t.etat AS etat,
  CAST(COALESCE(t.montant, 0) AS DECIMAL(30, 2)) AS montant,
  t.escompte AS escompte,
  CAST(COALESCE(t.total, 0) AS DECIMAL(30, 2)) AS total,
  t.reference AS reference,
  CAST((
    COALESCE(t.total, 0) - COALESCE(tf.montantenlevetraite, 0)
  ) AS DECIMAL(30, 2)) AS montantreste,
  t.cdclt AS cdclt,
  t.idbanque AS idbanque,
  t.idtypepiece AS idtypepiece,
  t.typepiece AS typepiece,
  COALESCE(te.etatversement, 1) AS etatversement,
  CASE
    WHEN te.etatversement = -2
    THEN 'Encaissee'
    WHEN te.etatversement = 11
    THEN 'Versee'
    ELSE 'Non Versee'
  END AS etatversementlib
FROM public.traite_libmtt AS t
LEFT JOIN public.traitemttfc AS tf
  ON tf.id = t.id
LEFT JOIN public.traiteetatversement AS te
  ON te.idtraite = t.id;

-- Niveau 2 - vue 82 / 100 : TRAITEMTTRESTE_NONVERSEE
-- Dependances nouvelles : TRAITE_LIBMTT.
CREATE VIEW public.traitemttreste_nonversee (
    "id", "daty", "tiers", "banque", "dateecheance", "etat", "montant", "escompte", "total", "reference", "montantreste", "cdclt", "idbanque"
) AS
SELECT
  tmttrst.id AS id,
  tmttrst.daty AS daty,
  tmttrst.tiers AS tiers,
  tmttrst.banque AS banque,
  tmttrst.dateecheance AS dateecheance,
  tmttrst.etat AS etat,
  tmttrst.montant AS montant,
  tmttrst.escompte AS escompte,
  tmttrst.total AS total,
  tmttrst.reference AS reference,
  tmttrst.montantreste AS montantreste,
  tmttrst.cdclt AS cdclt,
  tmttrst.idbanque AS idbanque
FROM (
  SELECT
    t.id AS id,
    t.daty AS daty,
    t.tiers AS tiers,
    t.banque AS banque,
    t.dateecheance AS dateecheance,
    t.etat AS etat,
    t.montant AS montant,
    t.escompte AS escompte,
    t.total AS total,
    t.reference AS reference,
    (
      t.total - tf.montantenlevetraite
    ) AS montantreste,
    t.cdclt AS cdclt,
    t.idbanque AS idbanque
  FROM public.traite_libmtt AS t
  LEFT JOIN public.traitemttfc AS tf
    ON tf.id = t.id
) AS tmttrst
WHERE
  NOT tmttrst.id IN (
    SELECT
      m.idtraite AS idtraite
    FROM public.mvtintracaisse AS m
    WHERE
      NOT m.idtraite IS NULL AND m.etatversement = 11
  );

