-- Niveau 2 - vue 87 / 100 : VENTE_DETAILS_CPL_2
-- Dependances nouvelles : V_REFCOULEUR_AVECCODE.
CREATE VIEW public.vente_details_cpl_2 (
    "id", "idvente", "idventelib", "idproduit", "idproduitlib", "idorigine", "qte", "pu", "putotal", "putotalachat", "purevient", "idcategorie", "idcategorielib", "daty", "idmagasin", "idmagasinlib", "idpoint", "idpointlib", "iddevise", "iddeviselib", "idreservation", "idbcfille", "typeproduit", "typeproduitlib", "idprovince", "idprovincelib", "motsclesss", "idmodele", "idmodelelib", "idcategoriemodele", "idsouscategorie", "idcategoriemodellib", "idsouscategorielib", "idcategmodele", "idcategmodelelib", "pointure", "idpointurelib", "idcouleurlib"
) AS
SELECT
  sq.id AS id,
  sq.idvente AS idvente,
  sq.idventelib AS idventelib,
  sq.idproduit AS idproduit,
  sq.idproduitlib AS idproduitlib,
  sq.idorigine AS idorigine,
  sq.qte AS qte,
  sq.pu AS pu,
  sq.putotal AS putotal,
  sq.putotalachat AS putotalachat,
  sq.purevient AS purevient,
  sq.idcategorie AS idcategorie,
  sq.idcategorielib AS idcategorielib,
  sq.daty AS daty,
  sq.idmagasin AS idmagasin,
  sq.idmagasinlib AS idmagasinlib,
  sq.idpoint AS idpoint,
  sq.idpointlib AS idpointlib,
  sq.iddevise AS iddevise,
  sq.iddeviselib AS iddeviselib,
  sq.idreservation AS idreservation,
  sq.idbcfille AS idbcfille,
  sq.typeproduit AS typeproduit,
  sq.typeproduitlib AS typeproduitlib,
  sq.idprovince AS idprovince,
  sq.idprovincelib AS idprovincelib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idvente AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idventelib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idproduit AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idproduitlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idorigine AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.qte
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qte
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qte
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.pu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.pu
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.pu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.putotal
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.putotal
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.putotal
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.putotalachat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.putotalachat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.putotalachat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.purevient
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.purevient
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.purevient
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.idcategorie AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idcategorielib AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(sq.idmagasin AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idmagasinlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idpoint AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idpointlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.iddevise AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.iddeviselib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idreservation AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idbcfille AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.typeproduit AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.typeproduitlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idprovince AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idprovincelib AS TEXT), NULL)
      ),
      ''
    )
  ) AS motsclesss,
  sq.idmodele AS idmodele,
  sq.idmodelelib AS idmodelelib,
  sq.idcategoriemodele AS idcategoriemodele,
  sq.idsouscategorie AS idsouscategorie,
  sq.idcategoriemodellib AS idcategoriemodellib,
  sq.idsouscategorielib AS idsouscategorielib,
  sq.idcategmodele AS idcategmodele,
  sq.idcategmodelelib AS idcategmodelelib,
  sq.pointure AS pointure,
  sq.idpointurelib AS idpointurelib,
  sq.idcouleurlib AS idcouleurlib
FROM (
  SELECT
    vd.id AS id,
    vd.idvente AS idvente,
    v.designation AS idventelib,
    vd.idproduit AS idproduit,
    p.libellevente AS idproduitlib,
    vd.idorigine AS idorigine,
    vd.qte AS qte,
    COALESCE(vd.pu, 0) AS pu,
    CAST((
      (
        COALESCE(vd.pu, 0) * (
          1 - CAST(COALESCE(vd.remise, 0) AS DECIMAL) / 100
        )
      ) * vd.qte - COALESCE(v.fraislivraison, 0) * COALESCE(p.calorie, 0) * COALESCE(vd.qte, 0)
    ) /* Partie HT avec de?duction des frais */ + (
      CAST((
        (
          COALESCE(vd.pu, 0) * (
            1 - CAST(COALESCE(vd.remise, 0) AS DECIMAL) / 100
          )
        ) * vd.qte - COALESCE(v.fraislivraison, 0) * COALESCE(p.calorie, 0) * COALESCE(vd.qte, 0)
      ) * COALESCE(vd.tva, 0) AS DECIMAL) / 100
    ) /* Partie TVA applique?e sur cette me?me base HT modifie?e */ AS DECIMAL(30, 2)) AS putotal, /* Formule de PUTOTAL aligne?e sur le MONTANTTTC de la vue de?taille?e */
    CAST(COALESCE(vd.puachat * vd.qte, 0) AS DECIMAL(30, 2)) AS putotalachat,
    CAST(COALESCE(vd.pu * vd.qte, 0) - COALESCE(vd.puachat * vd.qte, 0) AS DECIMAL(30, 2)) AS purevient,
    cat.id AS idcategorie,
    cat.val AS idcategorielib,
    v.daty AS daty,
    m.id AS idmagasin,
    m.val AS idmagasinlib,
    p1.id AS idpoint,
    p1.val AS idpointlib,
    vd.iddevise AS iddevise,
    vd.iddevise AS iddeviselib,
    v.idreservation AS idreservation,
    vd.idbcfille AS idbcfille,
    p.typeproduit AS typeproduit,
    tp.val AS typeproduitlib,
    cli.idprovince AS idprovince,
    pro.val AS idprovincelib,
    p.idmodele AS idmodele,
    mod.libelle AS idmodelelib,
    mod.idcategorie AS idcategoriemodele,
    mod.idsouscategorie AS idsouscategorie,
    cm.val AS idcategoriemodellib,
    sc.val AS idsouscategorielib,
    categmod.id AS idcategmodele,
    categmod.val AS idcategmodelelib,
    p.marque AS pointure,
    pt.val AS idpointurelib,
    vrc.nomcouleur AS idcouleurlib
  FROM public.vente_details AS vd
  LEFT JOIN public.vente AS v
    ON v.id = vd.idvente
  LEFT JOIN public.magasin2 AS m
    ON m.id = v.idmagasin
  LEFT JOIN public.as_ingredients AS p
    ON p.id = vd.idproduit
  LEFT JOIN public.modele AS mod
    ON mod.id = p.idmodele
  LEFT JOIN public.point AS p1
    ON p1.id = m.idpoint
  LEFT JOIN public.categorieingredient AS cat
    ON p.categorieingredient = cat.id
  LEFT JOIN public.type_produit AS tp
    ON tp.id = p.typeproduit
  LEFT JOIN public.client AS cli
    ON cli.id = v.idclient
  LEFT JOIN public.zone AS pro
    ON pro.id = p1.idzone
  LEFT JOIN public.categoriemodele AS cm
    ON mod.idcategorie = cm.id
  LEFT JOIN public.souscategoriemodele AS sc
    ON mod.idsouscategorie = sc.id
  LEFT JOIN public.categoriemodele AS categmod
    ON categmod.id = p.id
  LEFT JOIN public.pointure AS pt
    ON pt.id = p.marque
  LEFT JOIN public.v_refcouleur_aveccode AS vrc
    ON vrc.referencecouleur = p.couleur
) AS sq;

-- Niveau 2 - vue 88 / 100 : VENTE_DETAILS_LIB_ING
-- Dependances nouvelles : V_REFERENCE_COULEUR.
CREATE VIEW public.vente_details_lib_ing (
    "id", "idvente", "idproduit", "idorigine", "qte", "pu", "remise", "tva", "puachat", "puvente", "iddevise", "tauxdechange", "designation", "compte", "purevient", "idbcfille", "unite", "unitelib", "punet", "montantht", "montantttc", "montanttva", "montantremise", "montant", "reste", "frais", "idproduitlib", "daty", "datyprevu", "iddeviselib", "idcategorielib", "categorieproduitlib", "putotal", "idclientlib", "ristourne", "idprevision", "idreservation", "fraislivraison", "calorie", "puingredient", "contenue", "unite2", "montantremiser", "idremise", "couleur", "couleurlib", "marque", "marquelib"
) AS
SELECT
  p.id AS id,
  p.idvente AS idvente,
  p.idproduit AS idproduit,
  p.idorigine AS idorigine,
  CAST(p.qte AS DECIMAL(38, 2)) AS qte,
  p.pu AS pu,
  p.remise AS remise,
  p.tva AS tva,
  p.puachat AS puachat,
  p.puvente AS puvente,
  p.iddevise AS iddevise,
  p.tauxdechange AS tauxdechange,
  p.designation AS designation,
  p.compte AS compte,
  p.purevient AS purevient,
  p.idbcfille AS idbcfille,
  p.unite AS unite,
  u.val AS unitelib,
  CAST(p.pu - (
    CAST(p.pu * p.remise AS DECIMAL) / 100
  ) + (
    CAST(p.pu * p.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 5)) AS punet,
  CAST((
    (
      p.pu - (
        CAST(p.pu * p.remise AS DECIMAL) / 100
      )
    ) * p.qte - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
  ) AS DECIMAL(30, 5)) AS montantht,
  CAST((
    (
      p.pu - (
        CAST(p.pu * p.remise AS DECIMAL) / 100
      )
    ) * p.qte - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
  ) + (
    CAST((
      (
        (
          p.pu * p.qte
        ) - (
          CAST(p.pu * p.remise AS DECIMAL) / 100
        ) * p.qte
      ) - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
    ) * p.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS montantttc,
  CAST((
    CAST((
      (
        (
          p.pu * p.qte
        ) - (
          CAST(p.pu * p.remise AS DECIMAL) / 100
        ) * p.qte
      ) - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
    ) * p.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS montanttva,
  CAST((
    CAST(p.pu * p.remise AS DECIMAL) / 100
  ) * p.qte AS DECIMAL(30, 5)) AS montantremise,
  CAST(p.pu * p.qte AS DECIMAL(30, 5)) AS montant,
  (
    COALESCE(p.qte, 0) - COALESCE(bl.quantite, 0)
  ) - COALESCE(avcf.qte, 0) AS reste,
  CAST(COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0) AS DECIMAL(30, 5)) AS frais,
  ing.libellevente AS idproduitlib,
  v.daty AS daty,
  v.datyprevu AS datyprevu,
  p.iddevise AS iddeviselib,
  c.val AS idcategorielib,
  c.val AS categorieproduitlib,
  CAST((
    (
      p.pu - (
        CAST(p.pu * p.remise AS DECIMAL) / 100
      )
    ) * p.qte - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
  ) + (
    CAST((
      (
        (
          p.pu * p.qte
        ) - (
          CAST(p.pu * p.remise AS DECIMAL) / 100
        ) * p.qte
      ) - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
    ) * p.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS putotal,
  cl.nom AS idclientlib,
  p.ristourne AS ristourne,
  p.idprevision AS idprevision,
  v.idreservation AS idreservation,
  COALESCE(v.fraislivraison, 0) AS fraislivraison,
  ing.calorie AS calorie,
  CAST(CAST(p.pu AS DECIMAL) / COALESCE(eq.quantite, 1) AS DECIMAL(30, 2)) AS puingredient,
  COALESCE(eq.quantite, 1) AS contenue,
  ing.unite2 AS unite2,
  (
    p.pu * p.qte
  ) - (
    (
      CAST(p.pu * p.remise AS DECIMAL) / 100
    ) * p.qte
  ) AS montantremiser,
  p.idremise AS idremise,
  ing.couleur AS couleur,
  vrc.nomcouleur AS couleurlib,
  ing.marque AS marque,
  pointure.val AS marquelib
FROM public.vente_details AS p
LEFT JOIN public.vente AS v
  ON v.id = p.idvente
LEFT JOIN public.as_unite AS u
  ON u.id = p.unite
LEFT JOIN public.as_ingredients AS ing
  ON ing.id = p.idproduit
LEFT JOIN public.client AS cl
  ON v.idclient = cl.id
LEFT JOIN public.categorieingredient AS c
  ON ing.categorieingredient = c.id
LEFT JOIN public.equivalencevente AS eq
  ON eq.idproduit1 = p.idproduit
LEFT JOIN public.bl_client_fille_grp_vente AS bl
  ON bl.idventedetail = p.id
LEFT JOIN public.avoirfcfille_grp_viseee AS avcf
  ON avcf.idventedetails = p.id
LEFT JOIN public.v_reference_couleur AS vrc
  ON ing.couleur = vrc.referencecouleur
LEFT JOIN public.pointure AS pointure
  ON ing.marque = pointure.id;

-- Niveau 2 - vue 89 / 100 : VENTE_DETAILS_SAISIE_DIRECTE
-- Dependances nouvelles : V_REFERENCE_COULEUR.
CREATE VIEW public.vente_details_saisie_directe (
    "id", "idvente", "idproduit", "designation", "idorigine", "qte", "pu", "remise", "remisemontant", "tva", "puachat", "puvente", "iddevise", "tauxdechange", "compte", "photo", "reference", "montant", "unite", "ristourne", "couleurlib", "marquelib", "montantttc"
) AS
SELECT
  vd.id AS id,
  vd.idvente AS idvente,
  vd.idproduit AS idproduit,
  vd.designation AS designation,
  vd.idorigine AS idorigine,
  vd.qte AS qte,
  vd.pu AS pu,
  vd.remise AS remise,
  COALESCE(vd.remisemontant, 0) AS remisemontant,
  vd.tva AS tva,
  vd.puachat AS puachat,
  vd.puvente AS puvente,
  vd.iddevise AS iddevise,
  vd.tauxdechange AS tauxdechange,
  vd.compte AS compte,
  vd.photo AS photo,
  vd.reference AS reference,
  vd.montant AS montant,
  vd.unite AS unite,
  vd.ristourne AS ristourne,
  vrc.nomcouleur AS couleurlib,
  pointure.val AS marquelib,
  CAST(ai.pv * (
    1 + CAST(ai.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS montantttc
FROM public.vente_details AS vd
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = vd.idproduit
LEFT JOIN public.v_reference_couleur AS vrc
  ON ai.couleur = vrc.referencecouleur
LEFT JOIN public.pointure AS pointure
  ON ai.marque = pointure.id;

-- Niveau 2 - vue 90 / 100 : VENTE_DETAILS_VIDE
-- Dependances nouvelles : V_REFERENCE_COULEUR.
CREATE VIEW public.vente_details_vide (
    "id", "idvente", "idproduit", "idorigine", "qte", "pu", "remise", "tva", "puachat", "puvente", "iddevise", "tauxdechange", "designation", "compte", "purevient", "idbcfille", "unite", "unitelib", "punet", "frais", "montantht", "montantttc", "montanttva", "montantremise", "montant", "ristourne", "idclientlib", "daty", "datyprevu", "idproduitlib", "idcategorielib", "categorieproduitlib", "poids", "idprevision", "calorie", "idreservation", "fraislivraison", "marque", "couleur", "marquelib", "couleurlib"
) AS
SELECT
  p.id AS id,
  p.idvente AS idvente,
  p.idproduit AS idproduit,
  p.idorigine AS idorigine,
  p.qte AS qte,
  p.pu AS pu,
  p.remise AS remise,
  p.tva AS tva,
  p.puachat AS puachat,
  p.puvente AS puvente,
  p.iddevise AS iddevise,
  p.tauxdechange AS tauxdechange,
  p.designation AS designation,
  p.compte AS compte,
  p.purevient AS purevient,
  p.idbcfille AS idbcfille,
  p.unite AS unite,
  u.val AS unitelib,
  CAST(p.pu - (
    CAST(p.pu * p.remise AS DECIMAL) / 100
  ) + (
    (
      CAST(p.pu * p.tva AS DECIMAL) / 100
    )
  ) AS DECIMAL(30, 5)) AS punet,
  CAST(COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0) AS DECIMAL(30, 5)) AS frais,
  CAST((
    (
      p.pu - (
        CAST(p.pu * p.remise AS DECIMAL) / 100
      )
    ) * p.qte - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
  ) AS DECIMAL(30, 5)) AS montantht,
  CAST((
    (
      p.pu - (
        CAST(p.pu * p.remise AS DECIMAL) / 100
      )
    ) * p.qte - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
  ) + (
    CAST((
      (
        (
          p.pu * p.qte
        ) - (
          CAST(p.pu * p.remise AS DECIMAL) / 100
        ) * p.qte
      ) - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
    ) * p.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 5)) AS montantttc,
  CAST((
    CAST((
      (
        (
          p.pu * p.qte
        ) - (
          CAST(p.pu * p.remise AS DECIMAL) / 100
        ) * p.qte
      ) - COALESCE(v.fraislivraison, 0) * COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0)
    ) * p.tva AS DECIMAL) / 100
  ) AS DECIMAL(30, 5)) AS montanttva,
  CAST((
    CAST(p.pu * p.remise AS DECIMAL) / 100
  ) * p.qte AS DECIMAL(30, 5)) AS montantremise,
  CAST((
    p.pu
  ) * p.qte AS DECIMAL(30, 5)) AS montant,
  p.ristourne AS ristourne,
  cl.nom AS idclientlib,
  v.daty AS daty,
  v.datyprevu AS datyprevu,
  ing.libellevente AS idproduitlib,
  c.val AS idcategorielib,
  c.val AS categorieproduitlib,
  CAST(COALESCE(ing.calorie, 0) * COALESCE(p.qte, 0) AS DECIMAL(30, 5)) AS poids,
  p.idprevision AS idprevision,
  ing.calorie AS calorie,
  v.idreservation AS idreservation,
  COALESCE(v.fraislivraison, 0) AS fraislivraison,
  ing.marque AS marque,
  ing.couleur AS couleur,
  pt.val AS marquelib,
  vrc.nomcouleur AS couleurlib
FROM public.vente_details AS p
LEFT JOIN public.as_unite AS u
  ON u.id = p.unite
LEFT JOIN public.vente AS v
  ON v.id = p.idvente
LEFT JOIN public.as_ingredients AS ing
  ON ing.id = p.idproduit
LEFT JOIN public.client AS cl
  ON v.idclient = cl.id
LEFT JOIN public.categorieingredient AS c
  ON ing.categorieingredient = c.id
LEFT JOIN public.pointure AS pt
  ON pt.id = ing.marque
LEFT JOIN public.v_reference_couleur AS vrc
  ON vrc.referencecouleur = ing.couleur;

-- Niveau 2 - vue 91 / 100 : VENTE_SANS_RISTOURNE
-- Dependances nouvelles : VENTE_EDITEES.
CREATE VIEW public.vente_sans_ristourne (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "etatlib", "montanttotal", "iddevise", "idclient", "idclientlib", "montanttva", "montantttc", "montantttcar", "montantpaye", "montantreste", "avoir", "tauxdechange", "montantrevient", "margebrute", "idreservation", "datyprevu", "mois", "annee"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  v.idmagasinlib AS idmagasinlib,
  v.daty AS daty,
  v.remarque AS remarque,
  v.etat AS etat,
  v.etatlib AS etatlib,
  v.montanttotal AS montanttotal,
  v.iddevise AS iddevise,
  v.idclient AS idclient,
  v.idclientlib AS idclientlib,
  v.montanttva AS montanttva,
  v.montantttc AS montantttc,
  v.montantttcar AS montantttcar,
  v.montantpaye AS montantpaye,
  v.montantreste AS montantreste,
  v.avoir AS avoir,
  v.tauxdechange AS tauxdechange,
  v.montantrevient AS montantrevient,
  v.margebrute AS margebrute,
  v.idreservation AS idreservation,
  v.datyprevu AS datyprevu,
  v.mois AS mois,
  v.annee AS annee
FROM (
  SELECT
    v.id,
    v.designation,
    v.idmagasin,
    m.val AS idmagasinlib,
    v.daty,
    v.remarque,
    v.etat,
    CASE
      WHEN v.etat = CAST(1 AS DECIMAL)
      THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
      WHEN v.etat = CAST(11 AS DECIMAL)
      THEN CAST('VIS&Eacute;E' AS TEXT)
      WHEN v.etat = CAST(0 AS DECIMAL)
      THEN CAST('ANNUL&Eacute;E' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS etatlib,
    CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
    v2.iddevise,
    v.idclient,
    c.nom AS idclientlib,
    CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
    CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
    CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
    CAST(COALESCE(mv.montant, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
    CAST((
      COALESCE(v2.montantttc, CAST(0 AS DECIMAL)) - COALESCE(mv.montant, CAST(0 AS DECIMAL)) - COALESCE(acg.montantttcar - acg.montantpayear, CAST(0 AS DECIMAL))
    ) AS DECIMAL(30, 5)) AS montantreste,
    CAST(COALESCE(acg.montantttcar, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS avoir,
    CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
    CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
    CAST((
      v2.montantttcar - v2.montantrevient
    ) AS DECIMAL(20, 5)) AS margebrute,
    v.idreservation,
    CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
    rf.reference AS referencefacture,
    CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
    CAST((
      COALESCE(v2.montanttotal, CAST(0 AS DECIMAL)) + COALESCE(v2.montantremise, CAST(0 AS DECIMAL))
    ) AS DECIMAL(30, 5)) AS montant,
    EXTRACT(month FROM v.daty) AS mois,
    EXTRACT(year FROM v.daty) AS annee,
    CAST(v2.poids AS DECIMAL(30, 5)) AS poids,
    CAST(v2.colis AS DECIMAL(30, 5)) AS colis,
    v.modepaiement,
    mp.val AS modepaiementlib,
    COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(v2.poids, CAST(0 AS DECIMAL)) AS fraislivraison,
    v.modelivraison,
    CASE
      WHEN v.modelivraison = CAST(1 AS DECIMAL)
      THEN CAST('<span style=color: green;>LIVRAISON</span>' AS TEXT)
      WHEN v.modelivraison = CAST(2 AS DECIMAL)
      THEN CAST('<span style=color: green;>RECUPERATION</span>' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS modelivraisonlib,
    CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
    pv.id AS idprovince,
    pv.val AS provincelib,
    v.idorigine,
    CAST(COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS frais,
    v.referencefact,
    v.numerofacture,
    v.lieulivraison,
    v.datelivraison,
    v.updated_at,
    CASE
      WHEN v.estprevu = CAST(0 AS DECIMAL)
      THEN CAST('Non' AS TEXT)
      ELSE CAST('Oui' AS TEXT)
    END AS estprevulib,
    ce.id AS idecriture,
    COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
    NULLIF(
      CONCAT(
        (
          NULLIF(
            CONCAT(
              (
                NULLIF(
                  CONCAT(
                    (
                      NULLIF(
                        CONCAT(
                          (
                            NULLIF(
                              CONCAT(
                                (
                                  NULLIF(
                                    CONCAT(
                                      (
                                        NULLIF(
                                          CONCAT(
                                            (
                                              NULLIF(
                                                CONCAT(
                                                  (
                                                    NULLIF(
                                                      CONCAT(
                                                        (
                                                          NULLIF(
                                                            CONCAT(
                                                              (
                                                                NULLIF(
                                                                  CONCAT((
                                                                    NULLIF(CONCAT(CAST(v.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                                  ), v.daty),
                                                                  ''
                                                                )
                                                              ),
                                                              CAST(NULL AS TEXT)
                                                            ),
                                                            ''
                                                          )
                                                        ),
                                                        CAST(v.idclient AS TEXT)
                                                      ),
                                                      ''
                                                    )
                                                  ),
                                                  CAST(NULL AS TEXT)
                                                ),
                                                ''
                                              )
                                            ),
                                            CAST(c.nom AS TEXT)
                                          ),
                                          ''
                                        )
                                      ),
                                      CAST(NULL AS TEXT)
                                    ),
                                    ''
                                  )
                                ),
                                CAST(v.idmagasin AS TEXT)
                              ),
                              ''
                            )
                          ),
                          CAST(NULL AS TEXT)
                        ),
                        ''
                      )
                    ),
                    CAST(m.val AS TEXT)
                  ),
                  ''
                )
              ),
              CAST(NULL AS TEXT)
            ),
            ''
          )
        ),
        CAST(v.remarque AS TEXT)
      ),
      ''
    ) AS motsclesss,
    v.heuresaisie,
    v.adeclarer,
    v.factureechange,
    m.id AS idpoint
  FROM public.vente AS v
  LEFT JOIN public.client AS c
    ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
  LEFT JOIN public.point AS m
    ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
  LEFT JOIN public.zone AS pv
    ON CAST(pv.id AS TEXT) = CAST(m.idzone AS TEXT)
  JOIN (
    SELECT
      vd.idvente AS id,
      CAST(SUM(
        (
          CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
        ) * (
          COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
        ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
      ) AS DECIMAL(30, 2)) AS montanttotal,
      CAST((
        SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))) - SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          )
        )
      ) AS DECIMAL(30, 2)) AS montantremise,
      CAST(SUM(
        COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * COALESCE(vd.qte, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS frais,
      CAST(SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.puachat, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS montanttotalachat,
      CAST(SUM(
        (
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
      ) AS DECIMAL(30, 2)) AS montanttva,
      CAST((
        SUM(
          (
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) + SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        )
      ) AS DECIMAL(30, 2)) AS montantttc,
      COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
      COALESCE(AVG(vd.tauxdechange), CAST(1 AS DECIMAL)) AS tauxdechange,
      CAST((
        SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL))
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) + SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        )
      ) AS DECIMAL(30, 2)) AS montantttcar,
      CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
      v.idreservation,
      COALESCE(SUM(ing.calorie * vd.qte), CAST(0 AS DECIMAL)) AS poids,
      SUM(vd.qte) AS colis
    FROM public.vente_details AS vd
    LEFT JOIN public.vente AS v
      ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
    LEFT JOIN public.as_ingredients AS ing
      ON CAST(ing.id AS TEXT) = CAST(vd.idproduit AS TEXT)
    GROUP BY
      vd.idvente,
      vd.iddevise,
      v.idreservation
  ) AS v2
    ON CAST(v2.id AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.liaisonpaiementtotal AS mv
    ON CAST(v.id AS TEXT) = CAST(mv.id2 AS TEXT)
  LEFT JOIN (
    SELECT
      a.id,
      a.designation,
      a.idmagasin,
      CAST(NULL AS TEXT) AS idmagasinlib,
      a.daty,
      a.remarque,
      a.etat,
      a.idorigine,
      a.idclient,
      CAST(NULL AS TEXT) AS compte,
      CAST(NULL AS TEXT) AS compteauxiliaire,
      a.idvente,
      CAST(NULL AS TEXT) AS idventelib,
      a.idmotif,
      CAST(NULL AS TEXT) AS idmotiflib,
      a.idcategorie,
      CAST(NULL AS TEXT) AS idcategorielib,
      ag.iddevise,
      ag.tauxdechange,
      ag.montantht,
      ag.montanttva,
      ag.montantttc,
      ag.montanthtar,
      ag.montanttvaar,
      ag.montantttcar,
      CAST(NULL AS TEXT) AS idreservation,
      CAST(NULL AS TEXT) AS typeavoir,
      CAST(NULL AS TEXT) AS clientlib,
      COALESCE(m.montant, CAST(0 AS DECIMAL)) * COALESCE(ag.tauxdechange, CAST(0 AS DECIMAL)) AS montantpayear
    FROM public.avoirfc AS a
    JOIN public.avoirfcfille_grp AS ag
      ON CAST(ag.idavoirfc AS TEXT) = CAST(a.id AS TEXT)
    LEFT JOIN (
      SELECT
        m.id1 AS idorigine,
        SUM(m.montant) AS montant,
        CAST('AR' AS TEXT) AS iddevise
      FROM public.liaisonpaiement AS m
      WHERE
        m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
      GROUP BY
        m.id1
    ) AS m
      ON CAST(a.id AS TEXT) = CAST(m.idorigine AS TEXT)
    WHERE
      a.etat >= CAST(11 AS DECIMAL) AND a.idorigine IS NOT NULL
  ) AS acg
    ON CAST(acg.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.referencefacture AS rf
    ON CAST(rf.idfacture AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.modepaiement AS mp
    ON CAST(mp.id AS TEXT) = CAST(v.modepaiement AS TEXT)
  LEFT JOIN public.vente_reste AS vr
    ON CAST(vr.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.as_bondelivraison_client AS blc
    ON CAST(blc.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.compta_ecriture AS ce
    ON CAST(ce.idobjet AS TEXT) = CAST(v.id AS TEXT)
) AS v
WHERE
  v.etat >= 11
  AND NOT EXISTS(
    SELECT
      1 AS "1"
    FROM public.vente_editees AS e
    WHERE
      e.id = v.id
  );

-- Niveau 2 - vue 92 / 100 : V_ARRETTRAVAIL_LIB
-- Dependances nouvelles : V_ACCIDENT_LIB.
CREATE VIEW public.v_arrettravail_lib (
    "id", "daty", "date_fin_arret", "date_debut_arret", "id_accident", "nombre_jour", "nompersonnel", "matricule", "dateaccident", "id_personnel"
) AS
SELECT
  at.id AS id,
  at.daty AS daty,
  at.date_fin_arret AS date_fin_arret,
  at.date_debut_arret AS date_debut_arret,
  at.id_accident AS id_accident,
  at.nombre_jour AS nombre_jour,
  acc.id_personnel_lib AS nompersonnel,
  acc.matricule AS matricule,
  acc.daty AS dateaccident,
  acc.id_personnel AS id_personnel
FROM public.arret_travail AS at
LEFT JOIN public.v_accident_lib AS acc
  ON acc.id = at.id_accident;

-- Niveau 2 - vue 93 / 100 : V_DUREE_AGREGEE_TRAVAUX
-- Dependances nouvelles : V_DUREE_REELLE_TRAVAUX.
CREATE VIEW public.v_duree_agregee_travaux (
    "refobjet", "duree_reelle_total_heures", "ecart_enregistre"
) AS
SELECT
  v_duree_reelle_travaux.refobjet AS refobjet,
  SUM(v_duree_reelle_travaux.duree_heures_decimale) AS duree_reelle_total_heures,
  MAX(v_duree_reelle_travaux.ecart) AS ecart_enregistre
FROM public.v_duree_reelle_travaux AS v_duree_reelle_travaux
GROUP BY
  v_duree_reelle_travaux.refobjet;

-- Niveau 2 - vue 94 / 100 : V_ETATCAISSE
-- Dependances nouvelles : MOUVEMENTCAISSEAVECHEURE.
-- KEEP DENSE_RANK LAST : tri inverse des dates, puis MAX des valeurs ex aequo.
CREATE VIEW public.v_etatcaisse (
    "idcaisse", "idcaisselib", "credit", "debit", "reste", "taux", "restear", "daty", "id", "datedernierreport", "montantdernierreport", "idpoint", "idpointlib", "idtypecaisse", "idtypecaisselib"
) AS
WITH max_inventaire AS (
  /* Etape 1 : On extrait la date maximale valide et la quantite par COUPLE produit/magasin */
  SELECT
    rep.idcaisse AS idcaisse,
    MAX(rep.daty) AS max_daty,
    (
      ARRAY_AGG(rep.montant ORDER BY rep.daty DESC, rep.montant DESC NULLS LAST)
    )[1] AS montant_max_daty
  FROM (
    SELECT
      r.id,
      r.idcaisse,
      r.montant,
      r.montanttheorique,
      TO_TIMESTAMP(
        NULLIF(
          CONCAT(
            (
              NULLIF(CONCAT(TO_CHAR(r.daty, CAST('YYYY-MM-DD' AS TEXT)), CAST(' ' AS TEXT)), '')
            ),
            CAST(COALESCE(r.heure, CAST('00:00:00' AS VARCHAR)) AS TEXT)
          ),
          ''
        ),
        CAST('YYYY-MM-DD HH24:MI:SS' AS TEXT)
      ) AS daty,
      r.etat,
      r.remarque,
      r.heure
    FROM public.reportcaisse AS r
  ) AS rep
  WHERE
    rep.etat >= 11 /* and rep.DATY<=TO_DATE('27/07/2026','DD-MM-YYYY') */
  GROUP BY
    rep.idcaisse
), tauxchangemax AS (
  SELECT
    (
      ARRAY_AGG(tau.taux ORDER BY tau.daty DESC, tau.taux DESC NULLS LAST)
    )[1] AS taux,
    tau.iddevise AS tauxiddevise,
    MAX(tau.daty) AS tauxdaty
  FROM public.tauxdechange AS tau
  GROUP BY
    tau.iddevise
), somme_precalc AS (
  SELECT
    c.id AS idcaisse,
    c.val AS idcaisselib,
    COALESCE(
      SUM(
        CASE
          WHEN mff.daty > COALESCE(inv.max_daty, CAST('2025-01-01' AS DATE))
          THEN mff.credit
          ELSE 0
        END
      ),
      0
    ) AS credit,
    COALESCE(
      SUM(
        CASE
          WHEN mff.daty > COALESCE(inv.max_daty, CAST('2025-01-01' AS DATE))
          THEN mff.debit
          ELSE 0
        END
      ),
      0
    ) AS debit,
    MAX(inv.max_daty) AS datedernierreport,
    COALESCE(MAX(inv.montant_max_daty), 0) AS montantdernierreport,
    c.idpoint AS idpoint,
    p.val AS idpointlib,
    c.idtypecaisse AS idtypecaisse,
    typ.val AS idtypecaisselib,
    c.iddevise AS iddevise,
    MAX(tau.taux) AS taux
  FROM public.caisse AS c
  LEFT JOIN public.mouvementcaisseavecheure AS mff
    ON mff.idcaisse = c.id
    AND mff.etat >= 11
    AND NOT mff.idreport IS NULL /* and mff.DATY<=TO_DATE('27/07/2026','DD-MM-YYYY') */
  LEFT JOIN max_inventaire AS inv
    ON inv.idcaisse = c.id
  LEFT JOIN tauxchangemax AS tau
    ON tau.tauxiddevise = c.iddevise
  LEFT JOIN public.point AS p
    ON p.id = c.idpoint
  LEFT JOIN public.typecaisse AS typ
    ON typ.id = c.idtypecaisse
  GROUP BY
    c.id,
    c.idpoint,
    p.val,
    c.idtypecaisse,
    typ.val,
    c.val,
    c.iddevise
)
/* Selection finale */
SELECT
  somme_precalc.idcaisse AS idcaisse,
  NULLIF(
    CONCAT(somme_precalc.idcaisselib, ' (', COALESCE(somme_precalc.iddevise, 'AR'), ')'),
    ''
  ) AS idcaisselib,
  CAST(somme_precalc.credit AS DECIMAL(30, 2)) AS credit,
  CAST(somme_precalc.debit AS DECIMAL(30, 2)) AS debit,
  CAST(somme_precalc.montantdernierreport + somme_precalc.credit - somme_precalc.debit AS DECIMAL(30, 2)) AS reste,
  CAST(COALESCE(somme_precalc.taux, 1) AS DECIMAL(30, 2)) AS taux,
  CAST((
    somme_precalc.montantdernierreport + somme_precalc.credit - somme_precalc.debit
  ) * COALESCE(somme_precalc.taux, 1) AS DECIMAL(30, 2)) AS restear,
  CAST('2025-01-01' AS DATE) AS daty,
  somme_precalc.idcaisse AS id,
  somme_precalc.datedernierreport AS datedernierreport,
  CAST(somme_precalc.montantdernierreport AS DECIMAL(30, 2)) AS montantdernierreport,
  somme_precalc.idpoint AS idpoint,
  somme_precalc.idpointlib AS idpointlib,
  somme_precalc.idtypecaisse AS idtypecaisse,
  somme_precalc.idtypecaisselib AS idtypecaisselib
FROM somme_precalc AS somme_precalc;

-- Niveau 2 - vue 95 / 100 : V_ETATSTOCK_ING_TOUS
-- Dependances nouvelles : V_REFERENCE_COULEUR.
-- KEEP DENSE_RANK LAST : tri inverse des dates, puis MAX des valeurs ex aequo.
CREATE VIEW public.v_etatstock_ing_tous (
    "id", "daty", "invquantite", "entree", "sortie", "reste", "quantite", "montantreste", "pu", "idproduitlib", "idmodele", "idmodelelib", "idcategoriemodele", "idcategoriemodelelib", "idsouscategoriemodele", "idsouscategoriemodelelib", "idpointure", "idpointurelib", "categorieingredient", "unite", "typestock", "idunitelib", "idtypeproduitlib", "idfournisseur", "idfournisseurlib", "idproduit", "idmagasin", "idmagasinlib", "invdaty", "referencecouleur", "nomcouleur", "codecouleur", "seuil", "seuilmin", "seuilmax"
) AS
WITH max_inventaire AS (
  /* Etape 1 : On extrait la date maximale valide et la quantite par COUPLE produit/magasin */
  SELECT
    invff.idproduit AS idproduit,
    imeref.idmagasin AS idmagasin,
    MAX(imeref.daty) AS max_daty,
    (
      ARRAY_AGG(invff.quantite ORDER BY imeref.daty DESC, invff.quantite DESC NULLS LAST)
    )[1] AS qte_max_daty,
    (
      ARRAY_AGG(invff.pu ORDER BY imeref.daty DESC, invff.pu DESC NULLS LAST)
    )[1] AS pu_max_daty
  FROM public.inventairefille AS invff
  LEFT JOIN (
    SELECT
      i.id,
      TO_TIMESTAMP(
        NULLIF(
          CONCAT(
            (
              NULLIF(CONCAT(TO_CHAR(i.daty, CAST('YYYY-MM-DD' AS TEXT)), CAST(' ' AS TEXT)), '')
            ),
            CAST(COALESCE(i.heure, CAST('00:00:00' AS VARCHAR)) AS TEXT)
          ),
          ''
        ),
        CAST('YYYY-MM-DD HH24:MI:SS' AS TEXT)
      ) AS daty,
      i.designation,
      i.idmagasin,
      i.etat,
      i.remarque,
      i.idcategorie,
      i.heure
    FROM public.inventaire AS i
  ) AS imeref
    ON imeref.id = invff.idinventaire
  WHERE
    imeref.etat >= 11
  GROUP BY
    invff.idproduit,
    imeref.idmagasin
), somme_precalc AS (
  /* Etape 3 : Calcul des sommes globales agregees par COUPLE produit/magasin */
  SELECT
    mff.idproduit AS idproduit,
    meref.idmagasin AS idmagasin,
    COALESCE(
      SUM(
        CASE
          WHEN meref.daty > COALESCE(inv.max_daty, TO_DATE(CAST('01/01/2025' AS TEXT), 'DD-MM-YYYY'))
          THEN mff.entree
          ELSE 0
        END
      ),
      0
    ) AS entree,
    COALESCE(
      SUM(
        CASE
          WHEN meref.daty > COALESCE(inv.max_daty, TO_DATE(CAST('01/01/2025' AS TEXT), 'DD-MM-YYYY'))
          THEN mff.sortie
          ELSE 0
        END
      ),
      0
    ) AS sortie,
    ai.libelle AS idproduitlib,
    ai.categorieingredient AS categorieingredient,
    ai.idmodele AS idmodele,
    mo.libelle AS idmodelelib,
    mo.idcategorie AS idcategoriemodele,
    camo.val AS idcategoriemodelelib,
    scm.id AS idsouscategoriemodele,
    scm.val AS idsouscategoriemodelelib,
    ai.unite AS unite,
    ai.typestock AS typestock,
    ai.marque AS idpointure,
    pt.val AS idpointurelib,
    u.val AS idunitelib,
    c.val AS idtypeproduitlib,
    vrc.referencecouleur AS referencecouleur,
    vrc.nomcouleur AS nomcouleur,
    vrc.codecouleur AS codecouleur,
    AVG(mff.pu) AS pu,
    CAST(NULL AS TEXT) AS idfournisseur,
    CAST(NULL AS TEXT) AS idfournisseurlib,
    m.val AS idmagasinlib,
    MAX(inv.max_daty) AS invdaty,
    COALESCE(MAX(inv.qte_max_daty), 0) AS invquantite,
    COALESCE(
      SUM(
        CASE
          WHEN meref.daty > COALESCE(inv.max_daty, TO_DATE(CAST('01/01/2025' AS TEXT), 'DD-MM-YYYY'))
          THEN mff.entree * mff.pu
          ELSE 0
        END
      ),
      0
    ) AS montantentree,
    COALESCE(
      SUM(
        CASE
          WHEN meref.daty > COALESCE(inv.max_daty, TO_DATE(CAST('01/01/2025' AS TEXT), 'DD-MM-YYYY'))
          THEN mff.sortie * mff.pu
          ELSE 0
        END
      ),
      0
    ) AS montantsortie,
    COALESCE(AVG(inv.pu_max_daty * inv.qte_max_daty), 0) AS montantinv,
    COALESCE(MAX(ai.seuil), 0) AS seuil,
    COALESCE(MAX(ai.seuilmax), COALESCE(MAX(ai.seuilmin), 0) + 1000) AS seuilmax,
    COALESCE(MAX(ai.seuilmin), 0) AS seuilmin
  FROM public.mvtstockfille AS mff
  LEFT JOIN (
    SELECT
      m.id,
      m.designation,
      m.idmagasin,
      m.idvente,
      m.idtransfert,
      m.idtypemvstock,
      TO_TIMESTAMP(
        NULLIF(
          CONCAT(
            (
              NULLIF(CONCAT(TO_CHAR(m.daty, CAST('YYYY-MM-DD' AS TEXT)), CAST(' ' AS TEXT)), '')
            ),
            CAST(COALESCE(m.heure, CAST('00:00:00' AS VARCHAR)) AS TEXT)
          ),
          ''
        ),
        CAST('YYYY-MM-DD HH24:MI:SS' AS TEXT)
      ) AS daty,
      m.etat,
      m.idpoint,
      m.idobjet,
      m.fabprecedent,
      m.idcategoriestock,
      m.heure
    FROM public.mvtstock AS m
  ) AS meref
    ON meref.id = mff.idmvtstock
  LEFT JOIN max_inventaire AS inv
    ON inv.idproduit = mff.idproduit AND inv.idmagasin = meref.idmagasin
  LEFT JOIN public.as_ingredients AS ai
    ON ai.id = mff.idproduit
  LEFT JOIN public.categorieingredient AS c
    ON ai.categorieingredient = c.id
  LEFT JOIN public.magasinpoint AS m
    ON meref.idmagasin = m.id
  LEFT JOIN public.as_unite AS u
    ON ai.unite = u.id
  LEFT JOIN public.modele AS mo
    ON mo.id = ai.idmodele
  LEFT JOIN public.categoriemodele AS camo
    ON camo.id = mo.idcategorie
  LEFT JOIN public.souscategoriemodele AS scm
    ON scm.id = mo.idsouscategorie
  LEFT JOIN public.pointure AS pt
    ON pt.id = ai.marque
  LEFT JOIN public.couleur AS coul
    ON coul.id = ai.couleur
  LEFT JOIN public.v_reference_couleur AS vrc
    ON vrc.codecouleur = coul.desce
  /* meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) and */
  WHERE
    meref.etat >= 11 AND meref.idtypemvstock <> 'TPMVST000023'
  GROUP BY
    mff.idproduit,
    meref.idmagasin,
    ai.libelle,
    ai.categorieingredient,
    ai.unite,
    ai.typestock,
    u.val,
    c.val,
    m.val,
    ai.idmodele,
    mo.idcategorie,
    camo.val,
    mo.libelle,
    scm.id,
    scm.val,
    ai.marque,
    pt.val,
    vrc.referencecouleur,
    vrc.nomcouleur,
    vrc.codecouleur
)
/* Selection finale */
SELECT
  CAST(NULL AS TEXT) AS id,
  CAST(NULL AS TEXT) AS daty,
  CAST(COALESCE(somme_precalc.invquantite, 0) AS DECIMAL(30, 2)) AS invquantite,
  CAST(COALESCE(somme_precalc.entree, 0) AS DECIMAL(30, 2)) AS entree,
  CAST(COALESCE(somme_precalc.sortie, 0) AS DECIMAL(30, 2)) AS sortie,
  CAST(COALESCE(somme_precalc.invquantite, 0) + COALESCE(somme_precalc.entree, 0) - COALESCE(somme_precalc.sortie, 0) AS DECIMAL(30, 2)) AS reste,
  CAST(COALESCE(somme_precalc.invquantite, 0) + COALESCE(somme_precalc.entree, 0) - COALESCE(somme_precalc.sortie, 0) AS DECIMAL(30, 2)) AS quantite,
  CAST(COALESCE(somme_precalc.montantinv, 0) + COALESCE(somme_precalc.montantentree, 0) - COALESCE(somme_precalc.montantsortie, 0) AS DECIMAL(30, 2)) AS montantreste,
  CASE
    WHEN COALESCE(somme_precalc.invquantite, 0) + COALESCE(somme_precalc.entree, 0) - COALESCE(somme_precalc.sortie, 0) = 0
    THEN 0
    ELSE CAST(CAST((
      COALESCE(somme_precalc.montantinv, 0) + COALESCE(somme_precalc.montantentree, 0) - COALESCE(somme_precalc.montantsortie, 0)
    ) AS DECIMAL) / (
      COALESCE(somme_precalc.invquantite, 0) + COALESCE(somme_precalc.entree, 0) - COALESCE(somme_precalc.sortie, 0)
    ) AS DECIMAL(30, 2))
  END AS pu,
  somme_precalc.idproduitlib AS idproduitlib,
  somme_precalc.idmodele AS idmodele,
  somme_precalc.idmodelelib AS idmodelelib,
  somme_precalc.idcategoriemodele AS idcategoriemodele,
  somme_precalc.idcategoriemodelelib AS idcategoriemodelelib,
  somme_precalc.idsouscategoriemodele AS idsouscategoriemodele,
  somme_precalc.idsouscategoriemodelelib AS idsouscategoriemodelelib,
  somme_precalc.idpointure AS idpointure,
  somme_precalc.idpointurelib AS idpointurelib,
  somme_precalc.categorieingredient AS categorieingredient,
  somme_precalc.unite AS unite,
  somme_precalc.typestock AS typestock,
  somme_precalc.idunitelib AS idunitelib,
  somme_precalc.idtypeproduitlib AS idtypeproduitlib,
  somme_precalc.idfournisseur AS idfournisseur,
  somme_precalc.idfournisseurlib AS idfournisseurlib,
  somme_precalc.idproduit AS idproduit,
  somme_precalc.idmagasin AS idmagasin,
  somme_precalc.idmagasinlib AS idmagasinlib,
  somme_precalc.invdaty AS invdaty,
  somme_precalc.referencecouleur AS referencecouleur,
  somme_precalc.nomcouleur AS nomcouleur,
  somme_precalc.codecouleur AS codecouleur,
  CAST(COALESCE(somme_precalc.seuil, 0) AS DECIMAL(30, 2)) AS seuil,
  CAST(COALESCE(somme_precalc.seuilmin, 0) AS DECIMAL(30, 2)) AS seuilmin,
  CAST(COALESCE(somme_precalc.seuilmax, 0) AS DECIMAL(30, 2)) AS seuilmax
FROM somme_precalc AS somme_precalc;

-- Niveau 2 - vue 96 / 100 : V_ETATSTOCK_PU
-- Dependances nouvelles : V_ETATSTOCK_ENTREE.
CREATE VIEW public.v_etatstock_pu (
    "id", "reste", "idmagasin", "pu", "idmagasinlib", "mvtsrc"
) AS
SELECT
  vee.idproduit AS id,
  SUM(vee.quantite) AS reste,
  vee.idmagasin AS idmagasin,
  vee.pu AS pu,
  vee.idmagasinlib AS idmagasinlib,
  MAX(vee.id) AS mvtsrc
FROM public.v_etatstock_entree AS vee
GROUP BY
  vee.idproduit,
  vee.pu,
  vee.idmagasin,
  vee.idmagasinlib;

-- Niveau 2 - vue 97 / 100 : V_FORMATION_BILAN_PAR_STATUT
-- Dependances nouvelles : ACTION_FORMATION_LIB.
CREATE VIEW public.v_formation_bilan_par_statut (
    "annee", "nbrealise", "nbnonrealisee", "motsclesss"
) AS
SELECT
  base.annee AS annee,
  base.nbrealise AS nbrealise,
  base.nbnonrealisee AS nbnonrealisee,
  (
    NULLIF(
      CONCAT(
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbrealise
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbrealise
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbrealise
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.nbnonrealisee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.nbnonrealisee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.nbnonrealisee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    pf.annee AS annee,
    SUM(CASE WHEN afl.estrealiseelib = 'OUI' THEN 1 ELSE 0 END) AS nbrealise,
    SUM(CASE WHEN afl.estrealiseelib = 'NON' THEN 1 ELSE 0 END) AS nbnonrealisee
  FROM public.action_formation_lib AS afl
  LEFT JOIN public.plan_formation_annuel AS pf
    ON pf.id = afl.idplanformation
  GROUP BY
    pf.annee
) AS base;

-- Niveau 2 - vue 98 / 100 : V_HISTOINSERT
-- Dependances nouvelles : V_CLASSEETFICHE.
CREATE VIEW public.v_histoinsert (
    "idhistorique", "datehistorique", "heure", "objet", "action", "idutilisateur", "refobjet", "remarque", "fiche"
) AS
SELECT
  hi.idhistorique AS idhistorique,
  hi.datehistorique AS datehistorique,
  hi.heure AS heure,
  hi.objet AS objet,
  hi.action AS action,
  hi.idutilisateur AS idutilisateur,
  hi.refobjet AS refobjet,
  NULLIF(CONCAT(hi.remarque, ' ', hi.refobjet, ' ', hi.datehistorique), '') AS remarque,
  cf.fiche AS fiche
FROM public.histoinsert AS hi
LEFT JOIN public.v_classeetfiche AS cf
  ON cf.classe = hi.objet;

-- Niveau 2 - vue 99 / 100 : V_HS_FABRICATION_DETAIL
-- Dependances nouvelles : HEURESUPFABRICATION_CPL.
CREATE VIEW public.v_hs_fabrication_detail (
    "idfabrication", "idpersonne", "daty", "annee", "mois", "hs_total", "hs30", "hs50"
) AS
SELECT
  hp.idfabrication AS idfabrication,
  hp.idpersonne AS idpersonne,
  f.daty AS daty,
  p.annee AS annee,
  p.mois AS mois,
  SUM(hp.hs) AS hs_total,
  LEAST(SUM(hp.hs), 8) AS hs30,
  GREATEST(SUM(hp.hs) - 8, 0) AS hs50
FROM public.heuresupfabrication_cpl AS hp
LEFT JOIN public.fabrication AS f
  ON f.id = hp.idfabrication
LEFT JOIN public.periodepaie AS p
  ON f.daty BETWEEN p.datedebut AND p.datefin
GROUP BY
  hp.idfabrication,
  hp.idpersonne,
  f.daty,
  p.annee,
  p.mois;

-- Niveau 2 - vue 100 / 100 : V_MODELE_LIB
-- Dependances nouvelles : V_REFERENCE_COULEUR.
CREATE VIEW public.v_modele_lib (
    "id", "libelle", "idcategorie", "idcategorielib", "idsouscategorie", "idsouscategorielib", "univers", "universlib", "gamme", "gammelib", "statut", "statutlib", "matiere", "matierelib", "serie", "serielib", "collection", "collectionlib", "typologie", "typologielib", "provenance", "provenancelib", "idcouleur", "nomcouleur", "codecouleur", "semelle", "semellelib"
) AS
SELECT
  m.id AS id,
  m.libelle AS libelle,
  m.idcategorie AS idcategorie,
  cm.val AS idcategorielib,
  m.idsouscategorie AS idsouscategorie,
  scm.val AS idsouscategorielib,
  m.univers AS univers,
  u.val AS universlib,
  m.gamme AS gamme,
  g.val AS gammelib,
  m.statut AS statut,
  s.val AS statutlib,
  m.matiere AS matiere,
  ma.val AS matierelib,
  m.serie AS serie,
  se.val AS serielib,
  m.collection AS collection,
  co.val AS collectionlib,
  m.typologie AS typologie,
  typo.val AS typologielib,
  m.provenance AS provenance,
  pm.val AS provenancelib,
  m.codecouleur AS idcouleur,
  vrf.nomcouleur AS nomcouleur,
  vrf.codecouleur AS codecouleur,
  m.semelle AS semelle,
  sem.val AS semellelib
FROM public.modele AS m
LEFT JOIN public.categoriemodele AS cm
  ON m.idcategorie = cm.id
LEFT JOIN public.souscategoriemodele AS scm
  ON m.idsouscategorie = scm.id
LEFT JOIN public.univers AS u
  ON m.univers = u.id
LEFT JOIN public.gamme AS g
  ON m.gamme = g.id
LEFT JOIN public.statut AS s
  ON m.statut = s.id
LEFT JOIN public.matiere AS ma
  ON m.matiere = ma.id
LEFT JOIN public.serie AS se
  ON m.serie = se.id
LEFT JOIN public.collection AS co
  ON m.collection = co.id
LEFT JOIN public.typologie AS typo
  ON m.typologie = typo.id
LEFT JOIN public.provenancemodele AS pm
  ON m.provenance = pm.id
LEFT JOIN public.v_reference_couleur AS vrf
  ON m.codecouleur = vrf.referencecouleur
LEFT JOIN public.semelle AS sem
  ON m.semelle = sem.id;

COMMIT;

-- Verification du lot prepare (les vues bloquees ne sont pas comptees).
SELECT 2 AS niveau, count(*) AS vues_presentes, 100 AS vues_attendues
FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relkind='v' AND c.relname=ANY(ARRAY[
