-- Niveau 3 - vue 1 / 50 : ANOMALIETRANSFERT
-- Dependances nouvelles : MVTSTOCKFILLETRANSFERT, TRANSFERTSTOCKCPL.
CREATE VIEW public.anomalietransfert (
    "idtransfert", "magasindepart", "magasindepartlib", "magasinarrive", "magasinarrivelib", "daty", "designation", "idproduit", "idproduitlib", "quantite", "montant", "envoye", "montantenvoye", "recu", "montantrecu", "ecart", "montantecart", "reste", "motsclesss"
) AS
SELECT
  base.idtransfert AS idtransfert,
  base.magasindepart AS magasindepart,
  base.magasindepartlib AS magasindepartlib,
  base.magasinarrive AS magasinarrive,
  base.magasinarrivelib AS magasinarrivelib,
  base.daty AS daty,
  base.designation AS designation,
  base.idproduit AS idproduit,
  base.idproduitlib AS idproduitlib,
  base.quantite AS quantite,
  base.montant AS montant,
  base.envoye AS envoye,
  base.montantenvoye AS montantenvoye,
  base.recu AS recu,
  base.montantrecu AS montantrecu,
  base.ecart AS ecart,
  base.montantecart AS montantecart,
  base.reste AS reste,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.idtransfert AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.magasindepart AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.magasindepartlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.magasinarrive AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.magasinarrivelib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(base.designation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idproduit AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idproduitlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.quantite
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.quantite
                  ) AS TEXT)))
                  ELSE CAST((
                    base.quantite
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montant
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montant
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montant
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.envoye
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.envoye
                  ) AS TEXT)))
                  ELSE CAST((
                    base.envoye
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantenvoye
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantenvoye
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantenvoye
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.recu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.recu
                  ) AS TEXT)))
                  ELSE CAST((
                    base.recu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantrecu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantrecu
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantrecu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.ecart
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.ecart
                  ) AS TEXT)))
                  ELSE CAST((
                    base.ecart
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantecart
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantecart
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantecart
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.reste
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.reste
                  ) AS TEXT)))
                  ELSE CAST((
                    base.reste
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    t.id AS idtransfert,
    t.idmagasindepart AS magasindepart,
    t.idmagasindepartlib AS magasindepartlib,
    t.idmagasinarrive AS magasinarrive,
    t.idmagasinarrivelib AS magasinarrivelib,
    t.daty AS daty,
    t.designation AS designation,
    td.idproduit AS idproduit,
    td.idproduitlib AS idproduitlib,
    CAST(COALESCE(td.quantite, 0) AS DECIMAL(30, 5)) AS quantite,
    CAST(COALESCE(td.pu, 0) * COALESCE(td.quantite, 0) AS DECIMAL(30, 5)) AS montant,
    CAST(COALESCE(m.sortie, 0) AS DECIMAL(30, 5)) AS envoye,
    CAST(COALESCE(td.pu, 0) * COALESCE(m.sortie, 0) AS DECIMAL(30, 5)) AS montantenvoye,
    CAST(COALESCE(m.entree, 0) AS DECIMAL(30, 5)) AS recu,
    CAST(COALESCE(td.pu, 0) * COALESCE(m.entree, 0) AS DECIMAL(30, 5)) AS montantrecu,
    CAST(COALESCE(m.sortie, 0) - COALESCE(m.entree, 0) AS DECIMAL(30, 5)) AS ecart,
    CAST(COALESCE(td.pu, 0) * (
      COALESCE(m.sortie, 0) - COALESCE(m.entree, 0)
    ) AS DECIMAL(30, 5)) AS montantecart,
    CAST(COALESCE(td.quantite, 0) - COALESCE(m.sortie, 0) AS DECIMAL(30, 5)) AS reste
  FROM public.transfertstockdetailscpl AS td
  LEFT JOIN public.transfertstockcpl AS t
    ON t.id = td.idtransfertstock
  LEFT JOIN public.mvtstockfilletransfert AS m
    ON m.idtransfertdetail = td.id
) AS base;

-- Niveau 3 - vue 2 / 50 : AS_BONDECOMMANDE_CPL_RECEPTGRP
-- Dependances nouvelles : AS_BONDECOMMANDE_CPL_RECEPT.
CREATE VIEW public.as_bondecommande_cpl_receptgrp (
    "idbc", "totalcommande", "totalrecept"
) AS
SELECT
  bc.idbc AS idbc,
  SUM(bc.quantite) AS totalcommande,
  SUM(bc.qtelivrer) AS totalrecept
FROM public.as_bondecommande_cpl_recept AS bc
GROUP BY
  bc.idbc;

