) AS
SELECT
  budget_depense_sum_view.compte AS compte,
  budget_depense_sum_view.mois AS mois,
  budget_depense_sum_view.annee AS annee,
  budget_depense_sum_view.moislib AS moislib,
  budget_depense_sum_view.depenses AS depenses,
