-- Niveau 3 - vue 7 / 50 : DEPENSEDIVERSFILLELIB
-- Dependances nouvelles : AS_INGREDIENTS_LIB.
CREATE VIEW public.depensediversfillelib (
    "id", "idmere", "idproduit", "designation", "quantite", "pu", "idproduitlib", "montant", "tva"
) AS
SELECT
  d.id AS id,
  d.idmere AS idmere,
  d.idproduit AS idproduit,
  d.designation AS designation,
  d.quantite AS quantite,
  d.pu AS pu,
  ail.libelle AS idproduitlib,
  COALESCE(d.quantite, 0) * COALESCE(d.pu, 0) AS montant,
  d.tva AS tva
FROM public.depensediversfille AS d
LEFT JOIN public.as_ingredients_lib AS ail
  ON d.idproduit = ail.id;

-- Niveau 3 - vue 8 / 50 : ETATRECAPITULATIFCOMMANDE
-- Dependances nouvelles : BONDECOMMANDE_CLIENT_GLOBALE.
CREATE VIEW public.etatrecapitulatifcommande (
    "idclient", "idclientlib", "daty", "montant", "qtelivre", "qtenonlivre", "montantpaye", "montantrestant", "etat", "etatlib"
) AS
SELECT
  bcg.idclient AS idclient,
  bcg.idclientlib AS idclientlib,
  bcg.daty AS daty,
  SUM(bcg.pu * bcg.quantite) AS montant,
  SUM(bcg.qtelivre) AS qtelivre,
  SUM(bcg.qtenonlivre) AS qtenonlivre,
  COALESCE(SUM(mc_accompte.credit), 0) + COALESCE(SUM(mc_paye.credit), 0) AS montantpaye,
  COALESCE(SUM(bcg.pu * bcg.quantite), 0) - COALESCE(COALESCE(SUM(mc_accompte.credit), 0) + COALESCE(SUM(mc_paye.credit), 0), 0) AS montantrestant,
  CASE
    WHEN (
      COALESCE(SUM(mc_accompte.credit), 0) + COALESCE(SUM(mc_paye.credit), 0)
    ) >= SUM(bcg.pu * bcg.quantite)
    THEN 22
    WHEN (
      COALESCE(SUM(bcg.pu * bcg.quantite), 0) - COALESCE(COALESCE(SUM(mc_accompte.credit), 0) + COALESCE(SUM(mc_paye.credit), 0), 0)
    ) > 0
    THEN 2
    WHEN SUM(bcg.qtelivre) = SUM(bcg.quantite)
    THEN 111
    WHEN SUM(bcg.qtelivre) > 0
    THEN 11
    ELSE 1
  END AS etat,
  CASE
    WHEN (
      COALESCE(SUM(mc_accompte.credit), 0) + COALESCE(SUM(mc_paye.credit), 0)
    ) >= SUM(bcg.pu * bcg.quantite)
    THEN 'Pay&eacute;'
    WHEN (
      COALESCE(SUM(bcg.pu * bcg.quantite), 0) - COALESCE(COALESCE(SUM(mc_accompte.credit), 0) + COALESCE(SUM(mc_paye.credit), 0), 0)
    ) > 0
    THEN 'Accompte'
    WHEN SUM(bcg.qtelivre) = SUM(bcg.quantite)
    THEN 'Livr&eacute;'
    WHEN SUM(bcg.qtelivre) > 0
    THEN 'non livr&eacute; en totalit&eacute;'
    ELSE 'non livr&eacute;'
  END AS etatlib
FROM public.bondecommande_client_globale AS bcg
LEFT JOIN public.mouvementcaisse AS mc_accompte
  ON mc_accompte.idorigine = bcg.idbc
LEFT JOIN public.vente AS v
  ON v.idorigine = bcg.idbc
LEFT JOIN public.mouvementcaisse AS mc_paye
  ON mc_paye.idorigine = v.id
WHERE
  bcg.etat = 11
GROUP BY
  bcg.idclient,
  bcg.idclientlib,
  bcg.daty,
  bcg.idbc;

-- Niveau 3 - vue 9 / 50 : ETAT_VENTE_DETAILS_POIDS
