) AS
SELECT
  v.id AS id,
  v.idvente AS idvente,
  v.idproduit AS idproduit,
  v.idorigine AS idorigine,
  CAST(v.qte AS DECIMAL(38, 2)) AS qte,
  v.pu AS pu,
  v.remise AS remise,
  v.tva AS tva,
  v.puachat AS puachat,
  v.puvente AS puvente,
  v.iddevise AS iddevise,
  v.tauxdechange AS tauxdechange,
  v.designation AS designation,
  v.compte AS compte,
  v.purevient AS purevient,
  v.idbcfille AS idbcfille,
  v.unite AS unite,
  v.unitelib AS unitelib,
  v.punet AS punet,
  v.montantht AS montantht,
  CAST(v.montantttc AS DECIMAL(30, 2)) AS montantttc,
  CAST(v.montanttva AS DECIMAL(30, 2)) AS montanttva,
  v.montantremise AS montantremise,
  v.montant AS montant,
  v.poids AS poids,
  vc.reste AS reste,
  v.frais AS frais,
  v.idproduitlib AS idproduitlib,
  v.daty AS daty,
  v.datyprevu AS datyprevu,
  v.iddevise AS iddeviselib,
  v.idcategorielib AS idcategorielib,
  v.categorieproduitlib AS categorieproduitlib,
  v.montantttc AS putotal,
  v.idclientlib AS idclientlib,
  v.ristourne AS ristourne,
  v.idprevision AS idprevision,
  ve.idclient AS idclient,
  c.idprovince AS idprovince,
  ve.etat AS etat,
  pro.val AS idprovincelib,
  m.id AS idmagasin,
  m.val AS idmagasinlib,
  p1.id AS idpoint,
  p1.val AS idpointlib,
  tp.id AS typeproduit,
  tp.val AS typeproduitlib
FROM public.vente_details_vide AS v
LEFT JOIN public.equivalence AS e
  ON e.idproduit = v.idproduit AND e.idunite = v.unite
LEFT JOIN public.vente_details_reste AS vc
  ON vc.id = v.id
LEFT JOIN public.vente AS ve
  ON ve.id = v.idvente
LEFT JOIN public.as_ingredients AS p
  ON p.id = v.idproduit
LEFT JOIN public.client AS c
  ON c.id = ve.idclient
LEFT JOIN public.province AS pro
  ON pro.id = c.idprovince
LEFT JOIN public.magasin2 AS m
  ON m.id = ve.idmagasin
LEFT JOIN public.point AS p1
  ON p1.id = m.idpoint
LEFT JOIN public.type_produit AS tp
  ON tp.id = p.typeproduit;

