-- Niveau 3 - vue 11 / 50 : HS_FABBRICATION_SEMAINECPL
-- Dependances nouvelles : HS_FABRICATION_SEMAINE.
CREATE VIEW public.hs_fabbrication_semainecpl (
    "id", "idpersonne", "annee", "mois", "semaine", "hs_total", "hs30", "hs50", "matricule", "nompersonnel", "datedebutsemaine", "datefinsemaine", "if", "jf", "mn", "hd", "hs", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.idpersonne AS idpersonne,
  base.annee AS annee,
  base.mois AS mois,
  base.semaine AS semaine,
  base.hs_total AS hs_total,
  base.hs30 AS hs30,
  base.hs50 AS hs50,
  base.matricule AS matricule,
  base.nompersonnel AS nompersonnel,
  base.datedebutsemaine AS datedebutsemaine,
  base.datefinsemaine AS datefinsemaine,
  base.if AS if,
  base.jf AS jf,
  base.mn AS mn,
  base.hd AS hd,
  base.hs AS hs,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.idpersonne AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.mois AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(base.semaine AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.hs_total
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.hs_total
                  ) AS TEXT)))
                  ELSE CAST((
                    base.hs_total
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.hs30
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.hs30
                  ) AS TEXT)))
                  ELSE CAST((
                    base.hs30
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.hs50
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.hs50
                  ) AS TEXT)))
                  ELSE CAST((
                    base.hs50
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.nompersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.datedebutsemaine, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(base.datefinsemaine, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.if
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.if
                  ) AS TEXT)))
                  ELSE CAST((
                    base.if
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.jf
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.jf
                  ) AS TEXT)))
                  ELSE CAST((
                    base.jf
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.mn
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.mn
                  ) AS TEXT)))
                  ELSE CAST((
                    base.mn
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.hd
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.hd
                  ) AS TEXT)))
                  ELSE CAST((
                    base.hd
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.hs
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.hs
                  ) AS TEXT)))
                  ELSE CAST((
                    base.hs
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    hs.idpersonne AS id,
    hs.idpersonne AS idpersonne,
    hs.annee AS annee,
    hs.mois AS mois,
    hs.semaine AS semaine,
    hs.hs_total AS hs_total,
    hs.hs30 AS hs30,
    hs.hs50 AS hs50,
    pip.matricule AS matricule,
    NULLIF(CONCAT(log.nom, ' ', log.prenom), '') AS nompersonnel,
    CAST((
      DATE_TRUNC(
        'WEEK',
        TO_DATE(
          CAST(NULLIF(CONCAT(NULLIF(SUBSTRING(hs.semaine FROM 1 FOR 4), ''), '-01-04'), '') AS TEXT),
          'YYYY-MM-DD'
        )
      ) - (
        (
          CAST(NULLIF(SUBSTRING(hs.semaine FROM 6 FOR 2), '') AS DECIMAL) - 1
        ) * 7
      ) * INTERVAL '1 DAY'
    ) AS DATE) AS datedebutsemaine,
    CAST((
      (
        DATE_TRUNC(
          'WEEK',
          TO_DATE(
            CAST(NULLIF(CONCAT(NULLIF(SUBSTRING(hs.semaine FROM 1 FOR 4), ''), '-01-04'), '') AS TEXT),
            'YYYY-MM-DD'
          )
        ) - (
          (
            CAST(NULLIF(SUBSTRING(hs.semaine FROM 6 FOR 2), '') AS DECIMAL) - 1
          ) * 7
        ) * INTERVAL '1 DAY'
      ) - (
        6
      ) * INTERVAL '1 DAY'
    ) AS DATE) AS datefinsemaine,
    hs.if AS if,
    hs.jf AS jf,
    hs.mn AS mn,
    hs.hd AS hd,
    hs.hs_total AS hs
  FROM public.hs_fabrication_semaine AS hs
  LEFT JOIN public.paie_info_personnel AS pip
    ON pip.id = hs.idpersonne
  LEFT JOIN public.log_personnel AS log
    ON log.id = hs.idpersonne
) AS base;

-- Niveau 3 - vue 12 / 50 : HS_GROUPE
-- Dependances nouvelles : PAIEPERS_ELP_CPL.
-- PIVOT Oracle : sommes conditionnelles, avec groupement explicite identique.
CREATE VIEW public.hs_groupe (
    "id", "matricule", "date_debut", "date_fin", "retenue", "remarque", "nompersonnel", "etat", "id_objet", "iduser", "moisregularisation", "anneeregularisation", "idcategorie_qualification", "idfonction", "pourcentage", "etatlib", "hs_30_ni", "hs_30_i", "hs_50_ni", "hs_50_i"
) AS
SELECT
  p.idpersonnel AS id,
  p.matricule,
  p.date_debut,
  p.date_fin,
  p.retenue,
  p.remarque,
  p.nompersonnel,
  p.etat,
  p.id_objet,
  p.iduser,
  p.moisregularisation,
  p.anneeregularisation,
  p.idcategorie_qualification,
  p.idfonction,
  p.pourcentage,
  p.etatlib,
  SUM(CASE WHEN p.id_code_rubrique = 'PR0000130' THEN p.gain END) AS hs_30_ni,
  SUM(CASE WHEN p.id_code_rubrique = 'PR0000130I' THEN p.gain END) AS hs_30_i,
  SUM(CASE WHEN p.id_code_rubrique = 'PR0000150' THEN p.gain END) AS hs_50_ni,
  SUM(CASE WHEN p.id_code_rubrique = 'PR0000150I' THEN p.gain END) AS hs_50_i
FROM public.paiepers_elp_cpl AS p
GROUP BY
  p.idpersonnel,
  p.matricule,
  p.date_debut,
  p.date_fin,
  p.retenue,
  p.remarque,
  p.nompersonnel,
  p.etat,
  p.id_objet,
  p.iduser,
  p.moisregularisation,
  p.anneeregularisation,
  p.idcategorie_qualification,
  p.idfonction,
  p.pourcentage,
  p.etatlib
ORDER BY
  p.matricule ASC;

-- Niveau 3 - vue 13 / 50 : HS_MOIS
-- Dependances nouvelles : HS_FABRICATION_SEMAINE.
CREATE VIEW public.hs_mois (
    "idpersonnel", "annee", "mois", "hs30_mois", "hs50_mois", "iddepartement", "idcategorie"
) AS
SELECT
  hs.idpersonne AS idpersonnel,
  hs.annee AS annee,
  hs.mois AS mois,
  SUM(hs.hs30) AS hs30_mois,
  SUM(hs.hs50) AS hs50_mois,
  pip.iddepartement AS iddepartement,
  pip.idcategorie_paie AS idcategorie
FROM public.hs_fabrication_semaine AS hs
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = hs.idpersonne
GROUP BY
  hs.idpersonne,
  hs.annee,
  hs.mois,
  pip.iddepartement,
  pip.idcategorie_paie;

-- Niveau 3 - vue 14 / 50 : HS_MOIS_PARTRANCHE
-- Dependances nouvelles : HS_FABRICATION_SEMAINE.
CREATE VIEW public.hs_mois_partranche (
    "idpersonne", "annee", "mois", "hs30_mois", "hs50_mois", "iddepartement", "idcategorie"
) AS
SELECT
  hs.idpersonne AS idpersonne,
  hs.annee AS annee,
  hs.mois AS mois,
  SUM(hs.hs30) AS hs30_mois,
  SUM(hs.hs50) AS hs50_mois,
  pip.iddepartement AS iddepartement,
  pip.idcategorie_paie AS idcategorie
FROM public.hs_fabrication_semaine AS hs
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = hs.idpersonne
GROUP BY
  hs.idpersonne,
  hs.annee,
  hs.mois,
  pip.iddepartement,
  pip.idcategorie_paie;

-- Niveau 3 - vue 15 / 50 : HS_NON_PAYE
-- Dependances nouvelles : HEURESUPFABRICATION_CPL, HEURESUPFABRICATION_CPL_VISEE.
CREATE VIEW public.hs_non_paye (
    "id", "idressparfab", "hs", "mn", "jf", "hd", "if", "etat", "idpersonne", "idfabrication", "etatlib", "nompersonnel", "montantjf", "montanthd", "total", "matricule"
) AS
SELECT
  hs.id AS id,
  hs.idressparfab AS idressparfab,
  hs.hs AS hs,
  hs.mn AS mn,
  hs.jf AS jf,
  hs.hd AS hd,
  hs.if AS if,
  hs.etat AS etat,
  hs.idpersonne AS idpersonne,
  hs.idfabrication AS idfabrication,
  hs.etatlib AS etatlib,
  hs.idpersonnelib AS nompersonnel,
  hsf.montantjf AS montantjf,
  hsf.montanthd AS montanthd,
  hsf.montantjf + hsf.montanthd AS total,
  hsf.matricule AS matricule
FROM public.heuresupfabrication_cpl_visee AS hs
LEFT JOIN public.heuresupfabrication_cpl AS hsf
  ON hsf.id = hs.id
WHERE
  NOT hs.id IN (
    SELECT
      paiementheuresup.idhs AS idhs
    FROM public.paiementheuresup AS paiementheuresup
    WHERE
      NOT paiementheuresup.idhs IS NULL
  );

-- Niveau 3 - vue 16 / 50 : HS_PAR_FABRICATION
-- Dependances nouvelles : V_HS_FABRICATION_DETAIL.
CREATE VIEW public.hs_par_fabrication (
    "idfabrication", "idpersonne", "daty", "hs30", "hs50", "mois", "annee"
) AS
SELECT
  d.idfabrication AS idfabrication,
  d.idpersonne AS idpersonne,
  d.daty AS daty,
  d.hs30 AS hs30,
  d.hs50 AS hs50,
  d.mois AS mois,
  d.annee AS annee
FROM public.v_hs_fabrication_detail AS d
ORDER BY
  d.idpersonne,
  d.daty;

-- Niveau 3 - vue 17 / 50 : INVENTAIREFILLECOMPLET
-- Dependances nouvelles : V_ETATSTOCK_PU.
CREATE VIEW public.inventairefillecomplet (
    "id", "idinventaire", "idproduit", "explication", "idjauge", "pu", "quantitetheorique", "quantite", "mvtsrc", "idmagasin", "reste", "mvtentree"
) AS
SELECT
  i.id AS id,
  i.idinventaire AS idinventaire,
  i.idproduit AS idproduit,
  i.explication AS explication,
  i.idjauge AS idjauge,
  i.pu AS pu,
  i.quantitetheorique AS quantitetheorique,
  i.quantite AS quantite,
  i.mvtsrc AS mvtsrc,
  i.idmagasin AS idmagasin,
  vee.reste AS reste,
  vee.mvtsrc AS mvtentree
FROM public.inventairefillemere AS i
LEFT JOIN public.v_etatstock_pu AS vee
  ON vee.id = i.idproduit AND vee.pu = i.pu AND i.idmagasin = vee.idmagasin;

-- Niveau 3 - vue 18 / 50 : OFRATTACHE
-- Dependances nouvelles : OFNONRATTACHEREEL.
CREATE VIEW public.ofrattache (
    "id", "idoffille", "daty", "idproduit", "idproduitlib", "qte", "qtepetri", "idligne", "ligne", "idreleve", "pourcentage"
) AS
SELECT
  r.id AS id,
  ofn.idoffille AS idoffille,
  ofn.daty AS daty,
  ofn.idproduit AS idproduit,
  ofn.idproduitlib AS idproduitlib,
  ofn.qte AS qte,
  ofn.qtepetri AS qtepetri,
  ofn.idligne AS idligne,
  ofn.ligne AS ligne,
  r.idreleve AS idreleve,
  CAST((
    CAST(ofn.qtepetri AS DECIMAL) / SUM(ofn.qtepetri) OVER (PARTITION BY r.idreleve)
  ) * 100 AS DECIMAL(30, 2)) AS pourcentage /* Pourcentage de QTEPETRI par IDRELEVE */
FROM public.ofnonrattachereel AS ofn
JOIN public.relevefab AS r
  ON r.idfab = ofn.idoffille;

-- Niveau 3 - vue 19 / 50 : PAIE_INFO_JOURS_MOIS2
-- Dependances nouvelles : PAIE_INFO_JOURS_MOIS.
CREATE VIEW public.paie_info_jours_mois2 (
    "id", "dateembauche", "date_depart", "annee", "mois", "nb_jour", "conge_journalier", "jourplusdepart", "jourplusembauche", "nbjoursvrai"
) AS
SELECT
  p.id AS id,
  p.dateembauche AS dateembauche,
  p.date_depart AS date_depart,
  p.annee AS annee,
  p.mois AS mois,
  p.nb_jour AS nb_jour,
  p.conge_journalier AS conge_journalier,
  p.jourplusdepart AS jourplusdepart,
  p.jourplusembauche AS jourplusembauche,
  CASE
    WHEN p.jourplusdepart > 0 AND p.jourplusembauche = 0
    THEN p.jourplusdepart
    WHEN p.jourplusdepart = 0 AND p.jourplusembauche > 0
    THEN p.nb_jour - p.jourplusembauche + 1
    WHEN p.jourplusdepart > 0 AND p.jourplusembauche > 0
    THEN p.jourplusdepart - p.jourplusembauche
    WHEN p.annee = EXTRACT(YEAR FROM LOCALTIMESTAMP(0))
    AND p.mois = EXTRACT(MONTH FROM LOCALTIMESTAMP(0))
    THEN EXTRACT(DAY FROM LOCALTIMESTAMP(0))
    ELSE p.nb_jour
  END AS nbjoursvrai
FROM public.paie_info_jours_mois AS p;

