-- Niveau 3 - vue 24 / 50 : PLANNING_DUREENONPROGRAMME
-- Dependances nouvelles : PLANNING_CPL.
CREATE VIEW public.planning_dureenonprogramme (
    "datedebut", "id", "idmachinelib", "duree", "dureenonprogramme"
) AS
SELECT
  pc.datedebut AS datedebut,
  pc.idmachine AS id,
  pc.idmachinelib AS idmachinelib,
  SUM(CAST(pc.duree AS DECIMAL)) AS duree,
  COALESCE(
    (
      SELECT
        SUM(t.dureeestimatif) AS _col_0
      FROM public.travaux AS t
      LEFT JOIN public.ordretravauxfille AS ot
        ON t.idoffille = ot.id
      WHERE
        t.etat = 11 AND pc.idmachine = ot.idingredients AND t.daty = pc.datedebut
    ),
    0
  ) AS dureenonprogramme
FROM public.planning_cpl AS pc
GROUP BY
  pc.datedebut,
  pc.idmachine,
  pc.idmachinelib;

