-- Niveau 3 - vue 28 / 50 : RAPPROCHEMENTTRAVAUX
-- Dependances nouvelles : MOTRAVAUXLIB, PROCESSMAINTENANCEGLOBAL.
CREATE VIEW public.rapprochementtravaux (
    "id", "idtravaux", "idpersonnel", "idpersonnellib", "dureeestimatif_hms", "dureereel_hms", "ecart_hms", "dureeestimatif_seconde", "dureereel_seconde", "ecart_seconde", "montantestimatif", "montantreel", "montantecart", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.idtravaux AS idtravaux,
  sq.idpersonnel AS idpersonnel,
  sq.idpersonnellib AS idpersonnellib,
  sq.dureeestimatif_hms AS dureeestimatif_hms,
  sq.dureereel_hms AS dureereel_hms,
  sq.ecart_hms AS ecart_hms,
  sq.dureeestimatif_seconde AS dureeestimatif_seconde,
  sq.dureereel_seconde AS dureereel_seconde,
  sq.ecart_seconde AS ecart_seconde,
  sq.montantestimatif AS montantestimatif,
  sq.montantreel AS montantreel,
  sq.montantecart AS montantecart,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idtravaux AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idpersonnel AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idpersonnellib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.dureeestimatif_hms AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.dureereel_hms AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.ecart_hms AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.dureeestimatif_seconde AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.dureereel_seconde
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.dureereel_seconde
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.dureereel_seconde
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.ecart_seconde
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.ecart_seconde
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.ecart_seconde
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantestimatif
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantestimatif
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantestimatif
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantreel
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantreel
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantreel
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantecart
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantecart
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantecart
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    CAST(NULL AS TEXT) AS id,
    mo.idtravaux AS idtravaux,
    mo.idpersonnel AS idpersonnel,
    mo.idpersonnellib AS idpersonnellib,
    mo.dureeestimatiflib AS dureeestimatif_hms,
    pr.dureereelhms AS dureereel_hms,
    NULLIF(
      CONCAT(
        LPAD(
          CAST(FLOOR(
            CAST(ABS(CAST(CAST(mo.dureeestimatif AS DECIMAL) - pr.dureereel AS DECIMAL)) AS DECIMAL) / 3600
          ) AS TEXT),
          2,
          '0'
        ) /* Ecart HMS calcule avec ABS pour eviter le signe - */,
        ':',
        LPAD(
          CAST(FLOOR(
            CAST(CAST(ABS(CAST(CAST(mo.dureeestimatif AS DECIMAL) - pr.dureereel AS DECIMAL)) AS DECIMAL) % CAST(3600 AS DECIMAL) AS DECIMAL) / 60
          ) AS TEXT),
          2,
          '0'
        ),
        ':',
        LPAD(
          CAST(CAST(ABS(CAST(CAST(mo.dureeestimatif AS DECIMAL) - pr.dureereel AS DECIMAL)) AS DECIMAL) % CAST(60 AS DECIMAL) AS TEXT),
          2,
          '0'
        )
      ),
      ''
    ) AS ecart_hms,
    mo.dureeestimatif AS dureeestimatif_seconde,
    pr.dureereel AS dureereel_seconde,
    ABS(CAST(mo.dureeestimatif AS DECIMAL) - pr.dureereel) AS ecart_seconde, /* Ecart Seconde en valeur absolue */
    mo.montant AS montantestimatif,
    (
      CAST((
        CAST(pr.dureereel AS DECIMAL) / 60
      ) AS DECIMAL) / 60
    ) * mo.tauxhoraire AS montantreel,
    ABS(
      mo.montant - (
        (
          CAST((
            CAST(pr.dureereel AS DECIMAL) / 60
          ) AS DECIMAL) / 60
        ) * mo.tauxhoraire
      )
    ) AS montantecart /* Ecart Montant en valeur absolue */
  FROM public.motravauxlib AS mo
  LEFT JOIN public.processmaintenanceglobal AS pr
    ON pr.idpersonnel = mo.idpersonnel AND pr.idtravaux = mo.idtravaux
) AS sq;

-- Niveau 3 - vue 29 / 50 : RAPPROCHEMENT_BF_FOURNISSEUR
-- Dependances nouvelles : MVTSTOCKLIBVALIDER.
CREATE VIEW public.rapprochement_bf_fournisseur (
    "id", "produit", "numbl", "quantite", "iddetailsfacturefournisseur", "unite", "idbc_fille", "remarque", "idbc", "daty", "etat", "magasin", "produitlib", "unitelib", "magasinlib", "libelleexacte", "qteentree", "resteasortir", "pu", "puar", "resteaentrer"
) AS
SELECT
  abcc.id AS id,
  abcc.produit AS produit,
  abcc.numbl AS numbl,
  abcc.quantite AS quantite,
  abcc.iddetailsfacturefournisseur AS iddetailsfacturefournisseur,
  abcc.unite AS unite,
  abcc.idbc_fille AS idbc_fille,
  abcc.remarque AS remarque,
  abcc.idbc AS idbc,
  abcc.daty AS daty,
  abcc.etat AS etat,
  abcc.magasin AS magasin,
  abcc.produitlib AS produitlib,
  abcc.unitelib AS unitelib,
  abcc.magasinlib AS magasinlib,
  abcc.libelleextacte AS libelleexacte,
  COALESCE(SUM(mvf.entree), 0) AS qteentree,
  COALESCE(abcc.quantite, 0) - COALESCE(SUM(mvf.entree), 0) AS resteasortir,
  abcc.pu AS pu,
  abcc.puar AS puar,
  COALESCE(abcc.quantite, 0) - COALESCE(SUM(mvf.entree), 0) AS resteaentrer
FROM public.as_bondelivraison_libcpl AS abcc
LEFT JOIN public.mvtstocklibvalider AS mv
  ON mv.idobjet = abcc.numbl
LEFT JOIN public.mvtstockfille AS mvf
  ON mv.id = mvf.idmvtstock AND mvf.idproduit = abcc.produit
GROUP BY
  abcc.id,
  abcc.produit,
  abcc.numbl,
  abcc.quantite,
  abcc.iddetailsfacturefournisseur,
  abcc.unite,
  abcc.idbc_fille,
  abcc.remarque,
  abcc.idbc,
  abcc.daty,
  abcc.etat,
  abcc.magasin,
  abcc.produitlib,
  abcc.unitelib,
  abcc.magasinlib,
  abcc.libelleextacte,
  abcc.pu,
  abcc.puar;

-- Niveau 3 - vue 30 / 50 : RAPPROCHEMENT_BF_LIVREE
-- Dependances nouvelles : MVTSTOCKLIBVALIDER.
CREATE VIEW public.rapprochement_bf_livree (
    "id", "produit", "numbl", "quantite", "iddetailsfacturefournisseur", "unite", "idbc_fille", "remarque", "idbc", "daty", "etat", "magasin", "produitlib", "unitelib", "magasinlib", "libelleexacte", "qteentree", "resteasortir", "pu", "puar", "resteaentrer", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.produit AS produit,
  sq.numbl AS numbl,
  sq.quantite AS quantite,
  sq.iddetailsfacturefournisseur AS iddetailsfacturefournisseur,
  sq.unite AS unite,
  sq.idbc_fille AS idbc_fille,
  sq.remarque AS remarque,
  sq.idbc AS idbc,
  sq.daty AS daty,
  sq.etat AS etat,
  sq.magasin AS magasin,
  sq.produitlib AS produitlib,
  sq.unitelib AS unitelib,
  sq.magasinlib AS magasinlib,
  sq.libelleexacte AS libelleexacte,
  sq.qteentree AS qteentree,
  sq.resteasortir AS resteasortir,
  sq.pu AS pu,
  sq.puar AS puar,
  sq.resteaentrer AS resteaentrer,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.produit AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.numbl AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.quantite
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.quantite
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.quantite
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.iddetailsfacturefournisseur AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.unite AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idbc_fille AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.remarque AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.idbc AS TEXT), NULL),
        ' | ',
        COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.magasin AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.produitlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.unitelib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.magasinlib AS TEXT), NULL),
        ' | ',
        COALESCE(CAST(sq.libelleexacte AS TEXT), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.qteentree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.qteentree
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.qteentree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.resteasortir
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.resteasortir
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.resteasortir
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.pu
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.pu
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.pu
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.puar
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.puar
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.puar
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.resteaentrer
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.resteaentrer
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.resteaentrer
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    abcc.id AS id,
    abcc.produit AS produit,
    abcc.numbl AS numbl,
    abcc.quantite AS quantite,
    abcc.iddetailsfacturefournisseur AS iddetailsfacturefournisseur,
    abcc.unite AS unite,
    abcc.idbc_fille AS idbc_fille,
    abcc.remarque AS remarque,
    abcc.idbc AS idbc,
    abcc.daty AS daty,
    abcc.etat AS etat,
    abcc.magasin AS magasin,
    abcc.produitlib AS produitlib,
    abcc.unitelib AS unitelib,
    abcc.magasinlib AS magasinlib,
    abcc.libelleextacte AS libelleexacte,
    COALESCE(SUM(mvf.entree), 0) AS qteentree,
    COALESCE(abcc.quantite, 0) - COALESCE(SUM(mvf.entree), 0) AS resteasortir,
    abcc.pu AS pu,
    abcc.puar AS puar,
    COALESCE(abcc.quantite, 0) - COALESCE(SUM(mvf.entree), 0) AS resteaentrer
  FROM public.as_bondelivraison_libcpl AS abcc
  LEFT JOIN public.mvtstocklibvalider AS mv
    ON mv.idobjet = abcc.numbl
  LEFT JOIN public.mvtstockfille AS mvf
    ON mv.id = mvf.idmvtstock AND mvf.idproduit = abcc.produit
  GROUP BY
    abcc.id,
    abcc.produit,
    abcc.numbl,
    abcc.quantite,
    abcc.iddetailsfacturefournisseur,
    abcc.unite,
    abcc.idbc_fille,
    abcc.remarque,
    abcc.idbc,
    abcc.daty,
    abcc.etat,
    abcc.magasin,
    abcc.produitlib,
    abcc.unitelib,
    abcc.magasinlib,
    abcc.libelleextacte,
    abcc.pu,
    abcc.puar
) AS sq
WHERE
  sq.resteaentrer > 0;

-- Niveau 3 - vue 31 / 50 : RESERVATIONDETAILS_LIB
-- Dependances nouvelles : AS_INGREDIENTS_LIB.
CREATE VIEW public.reservationdetails_lib (
    "id", "idmere", "qte", "daty", "idproduit", "libelleproduit", "categorieproduit", "pu", "montant", "tva", "montanttva", "montantttc", "categorieproduitlib", "heure"
) AS
SELECT
  r.id AS id,
  r.idmere AS idmere,
  r.qte AS qte,
  r.daty AS daty,
  r.idproduit AS idproduit,
  ai.libelle AS libelleproduit,
  ai.idcategorieingredient AS categorieproduit,
  r.pu AS pu,
  r.qte * r.pu AS montant,
  ai.tva AS tva,
  CAST(r.qte * r.pu * (
    CAST(COALESCE(ai.tva, 0) AS DECIMAL) / 100
  ) AS DECIMAL(20, 2)) AS montanttva,
  CAST((
    r.qte * r.pu
  ) + (
    r.qte * r.pu * (
      CAST(COALESCE(ai.tva, 0) AS DECIMAL) / 100
    )
  ) AS DECIMAL(20, 2)) AS montantttc,
  ai.categorieingredient AS categorieproduitlib,
  r.heure AS heure
FROM public.reservationdetails AS r
LEFT JOIN public.as_ingredients_lib AS ai
  ON ai.id = r.idproduit;

-- Niveau 3 - vue 32 / 50 : RETRAIT_FRAIS_MEDICAUX_RESTE
-- Dependances nouvelles : PERSONNE_GAIN_SORTIE_RESTE.
CREATE VIEW public.retrait_frais_medicaux_reste (
    "id", "daty", "idpersonnel", "description", "montant", "etat", "reste"
) AS
SELECT
  rfm.id AS id,
  rfm.daty AS daty,
  rfm.idpersonnel AS idpersonnel,
  rfm.description AS description,
  rfm.montant AS montant,
  rfm.etat AS etat,
  p.reste AS reste
FROM public.retrait_frais_medicaux AS rfm
LEFT JOIN public.personne_gain_sortie_reste AS p
  ON rfm.idpersonnel = p.id;

-- Niveau 3 - vue 33 / 50 : SITUATION_BUDGET_RECETTES
-- Dependances nouvelles : BUDGET_RECETTE_SUM_VIEW.
CREATE VIEW public.situation_budget_recettes (
    "id", "compte", "service", "mois", "annee", "moislib", "budget", "montantfacture", "paiement", "resteapayer", "ecartfacturebudget", "ecartbudgetpaiement", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.compte AS compte,
  sq.service AS service,
  sq.mois AS mois,
  sq.annee AS annee,
  sq.moislib AS moislib,
  sq.budget AS budget,
  sq.montantfacture AS montantfacture,
  sq.paiement AS paiement,
  sq.resteapayer AS resteapayer,
  sq.ecartfacturebudget AS ecartfacturebudget,
  sq.ecartbudgetpaiement AS ecartbudgetpaiement,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.compte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.service AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.mois
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.mois
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.mois
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.moislib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.budget
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.budget
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.budget
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantfacture
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantfacture
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantfacture
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.paiement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.paiement
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.paiement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.resteapayer
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.resteapayer
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.resteapayer
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.ecartfacturebudget
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.ecartfacturebudget
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.ecartfacturebudget
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.ecartbudgetpaiement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.ecartbudgetpaiement
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.ecartbudgetpaiement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    CAST('-' AS TEXT) AS id,
    bdsv.compte AS compte,
    bdsv.idservicelib AS service,
    bdsv.mois AS mois,
    bdsv.annee AS annee,
    bdsv.moislib AS moislib,
    bdsv.depenses AS budget,
    ffc.montant AS montantfacture,
    ffc.montantpaye AS paiement,
    ffc.resteapayer AS resteapayer,
    bdsv.depenses - ffc.montant AS ecartfacturebudget,
    bdsv.depenses - ffc.montantpaye AS ecartbudgetpaiement
  FROM public.budget_recette_sum_view AS bdsv
  LEFT JOIN (
    SELECT
      NULLIF(SUBSTRING(ffp.compte FROM 1 FOR LENGTH(bdsv_inner.compte)), '') AS compteregr_groupe,
      ffp.mois AS mois,
      ffp.annee AS annee,
      SUM(ffp.montantfille * ffp.tauxdechange) AS montant,
      SUM(ffp.montantfillepaye * ffp.tauxdechange) AS montantpaye,
      SUM(ffp.resteapayerfille * ffp.tauxdechange) AS resteapayer
    FROM (
      SELECT
        vd.id,
        vd.idvente,
        vd.idproduit,
        vd.idorigine,
        vd.qte,
        vd.pu,
        vd.remise,
        vd.tva,
        vd.puachat,
        vd.puvente,
        vd.iddevise,
        vd.tauxdechange,
        vd.designation,
        vd.compte,
        vd.purevient,
        vd.idbcfille,
        vd.unite,
        vd.poids,
        vd.ristourne,
        vd.idprevision,
        v.mois,
        v.annee,
        v.montantpaye * CAST(100 AS DECIMAL) / NULLIF(v.montantttc, CAST(0 AS DECIMAL)) AS pourcentagepaye,
        v.montantpaye / NULLIF(v.montantttc, CAST(0 AS DECIMAL)) * (
          vd.qte * vd.pu
        ) AS montantfillepaye,
        vd.qte * vd.pu - v.montantpaye / NULLIF(v.montantttc, CAST(0 AS DECIMAL)) * (
          vd.qte * vd.pu
        ) AS resteapayerfille,
        v.montantpaye / NULLIF(v.montantttc, CAST(0 AS DECIMAL)) * (
          vd.qte * vd.pu
        ) * vd.tauxdechange AS montantfillepayear,
        vd.qte * vd.pu AS montantfille
      FROM public.vente_details AS vd
      LEFT JOIN (
        SELECT
          v.id,
          v.designation,
          v.idmagasin,
          m.val AS idmagasinlib,
          v.daty,
          v.remarque,
          v.etat,
          CASE
            WHEN v.etat = CAST(1 AS DECIMAL)
            THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
            WHEN v.etat = CAST(11 AS DECIMAL)
            THEN CAST('VIS&Eacute;E' AS TEXT)
            WHEN v.etat = CAST(0 AS DECIMAL)
            THEN CAST('ANNUL&Eacute;E' AS TEXT)
            ELSE CAST(NULL AS TEXT)
          END AS etatlib,
          CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
          v2.iddevise,
          v.idclient,
          c.nom AS idclientlib,
          CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
          CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
          CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
          CAST(COALESCE(mv.montant, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
          CAST((
            COALESCE(v2.montantttc, CAST(0 AS DECIMAL)) - COALESCE(mv.montant, CAST(0 AS DECIMAL)) - COALESCE(acg.montantttcar - acg.montantpayear, CAST(0 AS DECIMAL))
          ) AS DECIMAL(30, 5)) AS montantreste,
          CAST(COALESCE(acg.montantttcar, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS avoir,
          CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
          CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
          CAST((
            v2.montantttcar - v2.montantrevient
          ) AS DECIMAL(20, 5)) AS margebrute,
          v.idreservation,
          CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
          rf.reference AS referencefacture,
          CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
          CAST((
            COALESCE(v2.montanttotal, CAST(0 AS DECIMAL)) + COALESCE(v2.montantremise, CAST(0 AS DECIMAL))
          ) AS DECIMAL(30, 5)) AS montant,
          EXTRACT(month FROM v.daty) AS mois,
          EXTRACT(year FROM v.daty) AS annee,
          CAST(v2.poids AS DECIMAL(30, 5)) AS poids,
          CAST(v2.colis AS DECIMAL(30, 5)) AS colis,
          v.modepaiement,
          mp.val AS modepaiementlib,
          COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(v2.poids, CAST(0 AS DECIMAL)) AS fraislivraison,
          v.modelivraison,
          CASE
            WHEN v.modelivraison = CAST(1 AS DECIMAL)
            THEN CAST('<span style=color: green;>LIVRAISON</span>' AS TEXT)
            WHEN v.modelivraison = CAST(2 AS DECIMAL)
            THEN CAST('<span style=color: green;>RECUPERATION</span>' AS TEXT)
            ELSE CAST(NULL AS TEXT)
          END AS modelivraisonlib,
          CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
          pv.id AS idprovince,
          pv.val AS provincelib,
          v.idorigine,
          CAST(COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS frais,
          v.referencefact,
          v.numerofacture,
          v.lieulivraison,
          v.datelivraison,
          v.updated_at,
          CASE
            WHEN v.estprevu = CAST(0 AS DECIMAL)
            THEN CAST('Non' AS TEXT)
            ELSE CAST('Oui' AS TEXT)
          END AS estprevulib,
          ce.id AS idecriture,
          COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
          NULLIF(
            CONCAT(
              (
                NULLIF(
                  CONCAT(
                    (
                      NULLIF(
                        CONCAT(
                          (
                            NULLIF(
                              CONCAT(
                                (
                                  NULLIF(
                                    CONCAT(
                                      (
                                        NULLIF(
                                          CONCAT(
                                            (
                                              NULLIF(
                                                CONCAT(
                                                  (
                                                    NULLIF(
                                                      CONCAT(
                                                        (
                                                          NULLIF(
                                                            CONCAT(
                                                              (
                                                                NULLIF(
                                                                  CONCAT(
                                                                    (
                                                                      NULLIF(
                                                                        CONCAT((
                                                                          NULLIF(CONCAT(CAST(v.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                                        ), v.daty),
                                                                        ''
                                                                      )
                                                                    ),
                                                                    CAST(NULL AS TEXT)
                                                                  ),
                                                                  ''
                                                                )
                                                              ),
                                                              CAST(v.idclient AS TEXT)
                                                            ),
                                                            ''
                                                          )
                                                        ),
                                                        CAST(NULL AS TEXT)
                                                      ),
                                                      ''
                                                    )
                                                  ),
                                                  CAST(c.nom AS TEXT)
                                                ),
                                                ''
                                              )
                                            ),
                                            CAST(NULL AS TEXT)
                                          ),
                                          ''
                                        )
                                      ),
                                      CAST(v.idmagasin AS TEXT)
                                    ),
                                    ''
                                  )
                                ),
                                CAST(NULL AS TEXT)
                              ),
                              ''
                            )
                          ),
                          CAST(m.val AS TEXT)
                        ),
                        ''
                      )
                    ),
                    CAST(NULL AS TEXT)
                  ),
                  ''
                )
              ),
              CAST(v.remarque AS TEXT)
            ),
            ''
          ) AS motsclesss,
          v.heuresaisie,
          v.adeclarer,
          v.factureechange,
          m.id AS idpoint
        FROM public.vente AS v
        LEFT JOIN public.client AS c
          ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
        LEFT JOIN public.point AS m
          ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
        LEFT JOIN public.zone AS pv
          ON CAST(pv.id AS TEXT) = CAST(m.idzone AS TEXT)
        JOIN (
          SELECT
            vd.idvente AS id,
            CAST(SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
            ) AS DECIMAL(30, 2)) AS montanttotal,
            CAST((
              SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))) - SUM(
                (
                  CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                ) * (
                  COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
                )
              )
            ) AS DECIMAL(30, 2)) AS montantremise,
            CAST(SUM(
              COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * COALESCE(vd.qte, CAST(0 AS DECIMAL))
            ) AS DECIMAL(30, 5)) AS frais,
            CAST(SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.puachat, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS montanttotalachat,
            CAST(SUM(
              (
                (
                  CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                ) * (
                  COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
                ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
              ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
            ) AS DECIMAL(30, 2)) AS montanttva,
            CAST((
              SUM(
                (
                  (
                    CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                  ) * (
                    COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
                  ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
                ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
              ) + SUM(
                (
                  CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                ) * (
                  COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
                ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
              )
            ) AS DECIMAL(30, 2)) AS montantttc,
            COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
            COALESCE(AVG(vd.tauxdechange), CAST(1 AS DECIMAL)) AS tauxdechange,
            CAST((
              SUM(
                (
                  CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                ) * (
                  COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL))
                ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
              ) + SUM(
                (
                  CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                ) * (
                  COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
                ) * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
              )
            ) AS DECIMAL(30, 2)) AS montantttcar,
            CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
            v.idreservation,
            COALESCE(SUM(ing.calorie * vd.qte), CAST(0 AS DECIMAL)) AS poids,
            SUM(vd.qte) AS colis
          FROM public.vente_details AS vd
          LEFT JOIN public.vente AS v
            ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
          LEFT JOIN public.as_ingredients AS ing
            ON CAST(ing.id AS TEXT) = CAST(vd.idproduit AS TEXT)
          GROUP BY
            vd.idvente,
            vd.iddevise,
            v.idreservation
        ) AS v2
          ON CAST(v2.id AS TEXT) = CAST(v.id AS TEXT)
        LEFT JOIN public.liaisonpaiementtotal AS mv
          ON CAST(v.id AS TEXT) = CAST(mv.id2 AS TEXT)
        LEFT JOIN (
          SELECT
            a.id,
            a.designation,
            a.idmagasin,
            CAST(NULL AS TEXT) AS idmagasinlib,
            a.daty,
            a.remarque,
            a.etat,
            a.idorigine,
            a.idclient,
            CAST(NULL AS TEXT) AS compte,
            CAST(NULL AS TEXT) AS compteauxiliaire,
            a.idvente,
            CAST(NULL AS TEXT) AS idventelib,
            a.idmotif,
            CAST(NULL AS TEXT) AS idmotiflib,
            a.idcategorie,
            CAST(NULL AS TEXT) AS idcategorielib,
            ag.iddevise,
            ag.tauxdechange,
            ag.montantht,
            ag.montanttva,
            ag.montantttc,
            ag.montanthtar,
            ag.montanttvaar,
            ag.montantttcar,
            CAST(NULL AS TEXT) AS idreservation,
            CAST(NULL AS TEXT) AS typeavoir,
            CAST(NULL AS TEXT) AS clientlib,
            COALESCE(m.montant, CAST(0 AS DECIMAL)) * COALESCE(ag.tauxdechange, CAST(0 AS DECIMAL)) AS montantpayear
          FROM public.avoirfc AS a
          JOIN public.avoirfcfille_grp AS ag
            ON CAST(ag.idavoirfc AS TEXT) = CAST(a.id AS TEXT)
          LEFT JOIN (
            SELECT
              m.id1 AS idorigine,
              SUM(m.montant) AS montant,
              CAST('AR' AS TEXT) AS iddevise
            FROM public.liaisonpaiement AS m
            WHERE
              m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
            GROUP BY
              m.id1
          ) AS m
            ON CAST(a.id AS TEXT) = CAST(m.idorigine AS TEXT)
          WHERE
            a.etat >= CAST(11 AS DECIMAL) AND a.idorigine IS NOT NULL
        ) AS acg
          ON CAST(acg.idvente AS TEXT) = CAST(v.id AS TEXT)
        LEFT JOIN public.referencefacture AS rf
          ON CAST(rf.idfacture AS TEXT) = CAST(v.id AS TEXT)
        LEFT JOIN public.modepaiement AS mp
          ON CAST(mp.id AS TEXT) = CAST(v.modepaiement AS TEXT)
        LEFT JOIN public.vente_reste AS vr
          ON CAST(vr.idvente AS TEXT) = CAST(v.id AS TEXT)
        LEFT JOIN public.as_bondelivraison_client AS blc
          ON CAST(blc.idvente AS TEXT) = CAST(v.id AS TEXT)
        LEFT JOIN public.compta_ecriture AS ce
          ON CAST(ce.idobjet AS TEXT) = CAST(v.id AS TEXT)
      ) AS v
        ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
    ) AS ffp
    CROSS JOIN (
      SELECT DISTINCT
        brsv.compte AS compte
      FROM public.budget_recette_sum_view AS brsv
    ) AS bdsv_inner
    WHERE
      NULLIF(SUBSTRING(ffp.compte FROM 1 FOR LENGTH(bdsv_inner.compte)), '') = bdsv_inner.compte
    GROUP BY
      NULLIF(SUBSTRING(ffp.compte FROM 1 FOR LENGTH(bdsv_inner.compte)), ''),
      ffp.mois,
      ffp.annee
  ) AS ffc
    ON ffc.compteregr_groupe LIKE NULLIF(CONCAT(bdsv.compte, '%'), '')
    AND ffc.mois = bdsv.mois
    AND ffc.annee = bdsv.annee
) AS sq;

-- Niveau 3 - vue 34 / 50 : ST_INGREDIENTSAUTO
-- Dependances nouvelles : AS_INGREDIENTS_LIB, V_REFERENCE_COULEUR.
CREATE VIEW public.st_ingredientsauto (
    "id", "libelle", "seuil", "unite", "quantiteparpack", "pu", "actif", "photo", "calorie", "durre", "compose", "categorieingredient", "idfournisseur", "daty", "qtelimite", "pv", "libellevente", "seuilmin", "seuilmax", "puachatusd", "puachateuro", "puachatautredevise", "puventeusd", "puventeeuro", "puventeautredevise", "isvente", "isachat", "compte_vente", "compte_achat", "compte", "unitelib", "couleur", "marquelib", "couleurlib"
) AS
SELECT
  ai.id AS id,
  ai.libelle AS libelle,
  CAST(ai.seuil AS DECIMAL(10, 5)) AS seuil,
  au.val AS unite,
  CAST(ai.quantiteparpack AS DECIMAL(10, 5)) AS quantiteparpack,
  CAST(ai.pu AS DECIMAL(30, 5)) AS pu,
  ai.actif AS actif,
  ai.photo AS photo,
  ai.calorie AS calorie,
  ai.durre AS durre,
  ai.compose AS compose,
  ai.categorieingredient AS categorieingredient,
  ai.idfournisseur AS idfournisseur,
  ai.daty AS daty,
  CAST(ai.qtelimite AS DECIMAL(30, 5)) AS qtelimite,
  CAST(ai.pv AS DECIMAL(30, 5)) AS pv,
  ai.libellevente AS libellevente,
  CAST(COALESCE(ai.seuilmin, 0) AS DECIMAL(30, 5)) AS seuilmin,
  CAST(COALESCE(ai.seuilmax, 0) AS DECIMAL(30, 5)) AS seuilmax,
  CAST(COALESCE(ai.puachatusd, 0) AS DECIMAL(30, 5)) AS puachatusd,
  CAST(COALESCE(ai.puachateuro, 0) AS DECIMAL(30, 5)) AS puachateuro,
  CAST(COALESCE(ai.puachatautredevise, 0) AS DECIMAL(30, 5)) AS puachatautredevise,
  CAST(COALESCE(ai.puventeusd, 0) AS DECIMAL(30, 5)) AS puventeusd,
  CAST(COALESCE(ai.puventeeuro, 0) AS DECIMAL(30, 5)) AS puventeeuro,
  CAST(COALESCE(ai.puventeautredevise, 0) AS DECIMAL(30, 5)) AS puventeautredevise,
  ai.isvente AS isvente,
  ai.isachat AS isachat,
  ai.compte_vente AS compte_vente,
  ai.compte_achat AS compte_achat,
  CASE WHEN NOT ai.compte_vente IS NULL THEN ai.compte_vente ELSE ai.compte_achat END AS compte,
  au.val AS unitelib,
  ai.couleur AS couleur,
  ingl.marquelib AS marquelib,
  vrc.nomcouleur AS couleurlib
FROM public.as_ingredients AS ai
LEFT JOIN public.as_unite AS au
  ON au.id = ai.unite
LEFT JOIN public.as_ingredients_lib AS ingl
  ON ai.id = ingl.id
LEFT JOIN public.v_reference_couleur AS vrc
  ON ai.couleur = vrc.referencecouleur
WHERE
  ai.actif = 1;

