CREATE VIEW public.vente_cpl_analysef (
    "id", "idvente", "idventelib", "idproduit", "idproduitlib", "idorigine", "qte", "pu", "putotal", "putotalachat", "purevient", "categorieingredient", "idcategorielib", "idmagasin", "idmagasinlib", "idpoint", "idpointlib", "iddevise", "iddeviselib", "idreservation", "daty"
) AS
SELECT
  vd.id AS id,
  vd.idvente AS idvente,
  vd.idventelib AS idventelib,
  vd.idproduit AS idproduit,
  ai.libelle AS idproduitlib,
  vd.idorigine AS idorigine,
  vd.qte AS qte,
  vd.pu AS pu,
  vd.putotal AS putotal,
  vd.putotalachat AS putotalachat,
  vd.purevient AS purevient,
  ai.categorieingredient AS categorieingredient,
  cat.val AS idcategorielib,
  vd.idmagasin AS idmagasin,
  vd.idmagasinlib AS idmagasinlib,
  vd.idpoint AS idpoint,
  vd.idpointlib AS idpointlib,
  vd.iddevise AS iddevise,
  vd.iddeviselib AS iddeviselib,
  vd.idreservation AS idreservation,
  v.daty AS daty
FROM public.vente_details_cpl_2 AS vd
LEFT JOIN public.vente AS v
  ON v.id = vd.idvente
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = vd.idproduit
LEFT JOIN public.categorieingredient AS cat
  ON cat.id = ai.categorieingredient
WHERE
  v.etat >= 11;

