  CAST(vd.pu AS DECIMAL(30, 5)) AS pu,
  CAST(vd.putotal AS DECIMAL(30, 2)) AS putotal,
  CAST(vd.putotalachat AS DECIMAL(30, 2)) AS putotalachat,
  CAST(vd.purevient AS DECIMAL(30, 2)) AS purevient,
  vd.idcategorie AS idcategorie,
  vd.idcategorielib AS idcategorielib,
