  SUM(vd.qte) OVER () AS sum_qte,
  CAST(SUM(vd.putotal) OVER () AS DECIMAL(30, 2)) AS montanttotal,
  CAST(SUM(vd.putotal) OVER () AS DECIMAL(30, 2)) AS montant_total,
  v.idclient AS idclient,
  CAST(SUM(vd.putotal) OVER (PARTITION BY v.idclient) AS DECIMAL(30, 2)) AS total_achat,
  vd.typeproduit AS typeproduit,
  vd.typeproduitlib AS typeproduitlib,
  vd.idprovince AS idprovince,
  vd.idprovincelib AS idprovincelib,
  vd.idmodele AS idmodele,
  vd.idmodelelib AS idmodelelib,
  vd.idcategoriemodele AS idcategoriemodele,
  vd.idsouscategorie AS idsouscategorie,
  vd.idcategoriemodellib AS idcategoriemodellib,
  vd.idsouscategorielib AS idsouscategorielib,
  vd.pointure AS pointure,
  vd.idpointurelib AS idpointurelib,
  vd.idcouleurlib AS idcouleurlib
FROM public.vente_details_cpl_2 AS vd
LEFT JOIN public.vente AS v
  ON v.id = vd.idvente
WHERE
  v.etat >= 11;

-- Niveau 3 - vue 44 / 50 : VENTE_DETAILS_POIDS
-- Dependances nouvelles : VENTE_DETAILS_VIDE.
CREATE VIEW public.vente_details_poids (
    "id", "idvente", "idproduit", "idorigine", "qte", "pu", "remise", "tva", "puachat", "puvente", "iddevise", "tauxdechange", "designation", "compte", "purevient", "idbcfille", "unite", "unitelib", "punet", "montantht", "montantttc", "montanttva", "montantremise", "montant", "poids", "reste", "frais", "idproduitlib", "daty", "datyprevu", "iddeviselib", "idcategorielib", "categorieproduitlib", "putotal", "idclientlib", "ristourne", "idprevision", "idreservation", "fraislivraison", "calorie"
) AS
SELECT
