-- Niveau 3 - vue 45 / 50 : VENTE_DETAILS_VIDEAUTOCOMPLETE
-- Dependances nouvelles : VENTE_DETAILS_VIDE.
CREATE VIEW public.vente_details_videautocomplete (
    "id", "idvente", "idproduit", "idorigine", "qte", "pu", "remise", "tva", "puachat", "puvente", "iddevise", "tauxdechange", "designation", "compte", "purevient", "idbcfille", "unite", "unitelib", "punet", "frais", "montantht", "montantttc", "montanttva", "montantremise", "montant", "ristourne", "idclientlib", "daty", "datyprevu", "idproduitlib", "idcategorielib", "categorieproduitlib", "poids", "idprevision", "calorie", "idreservation", "fraislivraison"
) AS
SELECT
  v.id AS id,
  v.idvente AS idvente,
  CASE
    WHEN v.idproduit IS NULL
    THEN v.idproduit
    ELSE NULLIF(CONCAT(v.idproduit, '---', a.libelle), '')
  END AS idproduit,
  v.idorigine AS idorigine,
  v.qte AS qte,
  v.pu AS pu,
  v.remise AS remise,
  v.tva AS tva,
  v.puachat AS puachat,
  v.puvente AS puvente,
  v.iddevise AS iddevise,
  v.tauxdechange AS tauxdechange,
  v.designation AS designation,
  v.compte AS compte,
  v.purevient AS purevient,
  v.idbcfille AS idbcfille,
  v.unite AS unite,
  v.unitelib AS unitelib,
  v.punet AS punet,
  v.frais AS frais,
  v.montantht AS montantht,
  v.montantttc AS montantttc,
  v.montanttva AS montanttva,
  v.montantremise AS montantremise,
  v.montant AS montant,
  v.ristourne AS ristourne,
  v.idclientlib AS idclientlib,
  v.daty AS daty,
  v.datyprevu AS datyprevu,
  v.idproduitlib AS idproduitlib,
  v.idcategorielib AS idcategorielib,
  v.categorieproduitlib AS categorieproduitlib,
  v.poids AS poids,
  CASE
    WHEN v.idprevision IS NULL
    THEN v.idprevision
    ELSE NULLIF(CONCAT(v.idprevision, '---', p.designation), '')
  END AS idprevision,
  v.calorie AS calorie,
  v.idreservation AS idreservation,
  v.fraislivraison AS fraislivraison
FROM public.vente_details_vide AS v
LEFT JOIN public.as_ingredients AS a
  ON a.id = v.idproduit
LEFT JOIN public.prevision AS p
  ON p.id = v.idprevision;

-- Niveau 3 - vue 46 / 50 : V_DUREE_TRAVAUX_MACHINE
-- Dependances nouvelles : V_DUREE_AGREGEE_TRAVAUX.
CREATE VIEW public.v_duree_travaux_machine (
    "idingredients", "descriptionobjet", "daty", "id_travaux", "duree_estimative_heures", "duree_reelle_heures", "ecart_heures", "ecart_pourcentage", "ecart_enregistre"
) AS
SELECT
  CASE WHEN aim.id IS NULL THEN ai.id ELSE aim.id END AS idingredients,
  CASE WHEN aim.libelle IS NULL THEN ai.descriptionobjet ELSE aim.libelle END AS descriptionobjet,
  t.daty AS daty,
  t.id AS id_travaux,
  COALESCE(t.dureeestimatif, 0) AS duree_estimative_heures,
  COALESCE(vd.duree_reelle_total_heures, 0) AS duree_reelle_heures,
  COALESCE(vd.duree_reelle_total_heures, 0) - COALESCE(t.dureeestimatif, 0) AS ecart_heures,
  CASE
    WHEN t.dureeestimatif > 0
    THEN ROUND(
      CAST((
        CAST((
          COALESCE(vd.duree_reelle_total_heures, 0) - t.dureeestimatif
        ) AS DECIMAL) / t.dureeestimatif
      ) * 100 AS DECIMAL),
      2
    )
    ELSE NULL
  END AS ecart_pourcentage,
  vd.ecart_enregistre AS ecart_enregistre
FROM public.ordretravauxfille AS o
LEFT JOIN public.as_ingredients AS aim
  ON o.idingredients = aim.id
LEFT JOIN public.as_ingredient_maintenance AS ai
  ON o.idingredients = ai.id
JOIN public.travaux AS t
  ON o.id = t.idoffille
LEFT JOIN public.v_duree_agregee_travaux AS vd
  ON vd.refobjet = t.id;

