-- Niveau 4 - vue 1 / 22 : AS_BONDECOMMANDE_MERETRAITE
-- Dependances nouvelles : AS_BONDECOMMANDE_CPL_RECEPTGRP.
CREATE VIEW public.as_bondecommande_meretraite (
    "id", "daty", "etat", "remarque", "designation", "modepaiement", "fournisseur", "reference", "datelimite", "iddmdachat", "modepaiementlib", "fournisseurlib", "montanttva", "montantht", "montantttc", "montantttcariary", "iddeviselib", "iddevise", "etatlib", "idservicelib", "refproforma", "idtraite", "traite"
) AS
SELECT
  abm.id AS id,
  abm.daty AS daty,
  abm.etat AS etat,
  abm.remarque AS remarque,
  abm.designation AS designation,
  abm.modepaiement AS modepaiement,
  abm.fournisseur AS fournisseur,
  abm.reference AS reference,
  abm.datelimite AS datelimite,
  abm.iddmdachat AS iddmdachat,
  abm.modepaiementlib AS modepaiementlib,
  abm.fournisseurlib AS fournisseurlib,
  abm.montanttva AS montanttva,
  abm.montantht AS montantht,
  abm.montantttc AS montantttc,
  abm.montantttcariary AS montantttcariary,
  abm.iddeviselib AS iddeviselib,
  abm.iddevise AS iddevise,
  abm.etatlib AS etatlib,
  abm.idservicelib AS idservicelib,
  abm.refproforma AS refproforma,
  CASE
    WHEN abrcp.totalrecept = 0
    THEN '0'
    WHEN abrcp.totalcommande > abrcp.totalrecept
    THEN '1'
    WHEN abrcp.totalcommande = abrcp.totalrecept
    THEN '2'
    WHEN abrcp.totalcommande < abrcp.totalrecept
    THEN '3'
  END AS idtraite,
  CASE
    WHEN abrcp.totalrecept = 0
    THEN 'Non Trait&eacute;'
    WHEN abrcp.totalcommande > abrcp.totalrecept
    THEN 'Trait&eacute; Partiellement'
    WHEN abrcp.totalcommande = abrcp.totalrecept
    THEN 'Trait&eacute;'
    WHEN abrcp.totalcommande < abrcp.totalrecept
    THEN 'Trait&eacute; avec surplus'
  END AS traite
FROM (
  SELECT
    ab.id,
    ab.daty,
    ab.etat,
    ab.remarque,
    ab.designation,
    ab.modepaiement,
    ab.fournisseur,
    ab.reference,
    ab.datelimite,
    ab.iddmdachat,
    mp.val AS modepaiementlib,
    f.nom AS fournisseurlib,
    CAST(abf.montanttva AS DECIMAL(30, 5)) AS montanttva,
    CAST(abf.montantht AS DECIMAL(30, 5)) AS montantht,
    CAST(COALESCE(abf.montantht + abf.montanttva, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantttc,
    CAST(COALESCE((
      abf.montantht + abf.montanttva
    ) * abf.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantttcariary,
    d.val AS iddeviselib,
    d.id AS iddevise,
    CASE
      WHEN ab.etat = CAST(1 AS DECIMAL)
      THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
      WHEN ab.etat = CAST(11 AS DECIMAL)
      THEN CAST('VIS&Eacute;E' AS TEXT)
      WHEN ab.etat = CAST(0 AS DECIMAL)
      THEN CAST('ANNUL&Eacute;E' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS etatlib,
    s.libelle AS idservicelib,
    ab.refproforma,
    1 AS nb
  FROM public.as_bondecommande AS ab
  LEFT JOIN public.modepaiement AS mp
    ON CAST(ab.modepaiement AS TEXT) = CAST(mp.id AS TEXT)
  LEFT JOIN public.fournisseur AS f
    ON CAST(ab.fournisseur AS TEXT) = CAST(f.id AS TEXT)
  LEFT JOIN public.as_bondecommandefille_cpl AS abf
    ON CAST(abf.idbc AS TEXT) = CAST(ab.id AS TEXT)
  LEFT JOIN public.devise AS d
    ON CAST(d.id AS TEXT) = CAST(ab.iddevise AS TEXT)
  LEFT JOIN public.service AS s
    ON CAST(ab.service AS TEXT) = CAST(s.compte AS TEXT)
) AS abm
LEFT JOIN public.as_bondecommande_cpl_receptgrp AS abrcp
  ON abrcp.idbc = abm.id;

-- Niveau 4 - vue 2 / 22 : CA_ANNEE_VIEW
-- Dependances nouvelles : VENTE_DETAILS_CPL_2_VISEE.
CREATE VIEW public.ca_annee_view (
    "montant", "annee", "mois"
) AS
WITH deja AS (
  SELECT
    SUM(ca_annee_anterieur.montant) AS montant,
    CAST(ca_annee_anterieur.annee AS DECIMAL) AS annee,
    CAST(ca_annee_anterieur.mois AS DECIMAL) AS mois
  FROM public.ca_annee_anterieur AS ca_annee_anterieur
  GROUP BY
    CAST(ca_annee_anterieur.annee AS DECIMAL),
    CAST(ca_annee_anterieur.mois AS DECIMAL)
), recalc AS (
  SELECT
    EXTRACT(YEAR FROM vente_details_cpl_2_visee.daty) AS annee,
    EXTRACT(MONTH FROM vente_details_cpl_2_visee.daty) AS mois,
    SUM(vente_details_cpl_2_visee.putotal) AS montant
  FROM public.vente_details_cpl_2_visee AS vente_details_cpl_2_visee
  GROUP BY
    EXTRACT(YEAR FROM vente_details_cpl_2_visee.daty),
    EXTRACT(MONTH FROM vente_details_cpl_2_visee.daty)
), manquants AS (
  SELECT
    r.montant AS montant,
    r.annee AS annee,
    r.mois AS mois
  FROM recalc AS r
  WHERE
    NOT EXISTS(
      SELECT
        1 AS "1"
      FROM deja AS d
      WHERE
        d.annee = r.annee AND d.mois = r.mois
    )
)
SELECT
  deja.montant AS montant,
  deja.annee AS annee,
  deja.mois AS mois
FROM deja AS deja
UNION ALL
SELECT
  manquants.montant AS montant,
  manquants.annee AS annee,
  manquants.mois AS mois
FROM manquants AS manquants;

-- Niveau 4 - vue 3 / 22 : CA_JOURNALIER
-- Dependances nouvelles : VENTE_DETAILS_CPL_2_VISEE.
CREATE VIEW public.ca_journalier (
    "montant", "annee", "mois", "moislib", "daty"
) AS
WITH agg AS (
  SELECT
    DATE_TRUNC('DAY', vente_details_cpl_2_visee.daty) AS jour,
    SUM(vente_details_cpl_2_visee.putotal) AS montant
  FROM public.vente_details_cpl_2_visee AS vente_details_cpl_2_visee
  GROUP BY
    DATE_TRUNC('DAY', vente_details_cpl_2_visee.daty)
)
SELECT
  a.montant AS montant,
  EXTRACT(YEAR FROM a.jour) AS annee,
  EXTRACT(MONTH FROM a.jour) AS mois,
  RPAD(
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM a.jour) AS INT) + 0],
    9,
    ' '
  ) AS moislib,
  a.jour AS daty
FROM agg AS a
WHERE
  NOT EXISTS(
    SELECT
      1 AS "1"
    FROM public.ca_jour AS j
    WHERE
      j.daty = a.jour
  );

-- Niveau 4 - vue 4 / 22 : CA_MENSUEL
-- Dependances nouvelles : VENTE_DETAILS_CPL_2_VISEE.
CREATE VIEW public.ca_mensuel (
    "annee", "mois", "moislib", "montant"
) AS
WITH agg AS (
  SELECT
    DATE_TRUNC('DAY', vente_details_cpl_2_visee.daty) AS jour,
    CAST(SUM(vente_details_cpl_2_visee.putotal) AS DECIMAL(30, 5)) AS montant
  FROM public.vente_details_cpl_2_visee AS vente_details_cpl_2_visee
  GROUP BY
    DATE_TRUNC('DAY', vente_details_cpl_2_visee.daty)
), agg_mois AS (
  SELECT
    EXTRACT(YEAR FROM agg.jour) AS annee,
    EXTRACT(MONTH FROM agg.jour) AS mois,
    RPAD(
      (
        ARRAY[
          'Janvier',
          'Février',
          'Mars',
          'Avril',
          'Mai',
          'Juin',
          'Juillet',
          'Août',
          'Septembre',
          'Octobre',
          'Novembre',
          'Décembre'
        ]
      )[CAST(EXTRACT(MONTH FROM agg.jour) AS INT) + 0],
      9,
      ' '
    ) AS moislib,
    CAST(SUM(agg.montant) AS DECIMAL(30, 5)) AS montant
  FROM agg AS agg
  GROUP BY
    EXTRACT(YEAR FROM agg.jour),
    EXTRACT(MONTH FROM agg.jour),
    RPAD(
      (
        ARRAY[
          'Janvier',
          'Février',
          'Mars',
          'Avril',
          'Mai',
          'Juin',
          'Juillet',
          'Août',
          'Septembre',
          'Octobre',
          'Novembre',
          'Décembre'
        ]
      )[CAST(EXTRACT(MONTH FROM agg.jour) AS INT) + 0],
      9,
      ' '
    )
)
SELECT
  m.annee AS annee,
  m.mois AS mois,
  m.moislib AS moislib,
  m.montant AS montant
FROM agg_mois AS m
WHERE
  NOT EXISTS(
    SELECT
      1 AS "1"
    FROM public.ca_jour AS j
    WHERE
      EXTRACT(YEAR FROM j.daty) = m.annee AND EXTRACT(MONTH FROM j.daty) = m.mois
  );

