-- Niveau 4 - vue 6 / 22 : PAIE_INFO_JOURS_MOIS2_BIS
-- Dependances nouvelles : PAIE_INFO_JOURS_MOIS2.
CREATE VIEW public.paie_info_jours_mois2_bis (
    "id", "dateembauche", "date_depart", "annee", "mois", "nb_jour", "conge_journalier", "jourplusdepart", "jourplusembauche", "nbjoursvrai"
) AS
SELECT
  pijm.id AS id,
  pijm.dateembauche AS dateembauche,
  pijm.date_depart AS date_depart,
  pijm.annee AS annee,
  pijm.mois AS mois,
  pijm.nb_jour AS nb_jour,
  pijm.conge_journalier AS conge_journalier,
  pijm.jourplusdepart AS jourplusdepart,
  pijm.jourplusembauche AS jourplusembauche,
  pijm.nbjoursvrai AS nbjoursvrai
FROM public.paie_info_jours_mois2 AS pijm
WHERE
  pijm.dateembauche <= TO_DATE(CAST('2024-01-01' AS TEXT), 'YYYY-MM-DD')
  AND pijm.annee >= 2024;

-- Niveau 4 - vue 7 / 22 : PAIE_INFO_JOURS_MOIS3
-- Dependances nouvelles : PAIE_INFO_JOURS_MOIS2.
CREATE VIEW public.paie_info_jours_mois3 (
    "id", "jourconge"
) AS
SELECT
  paie_info_jours_mois2.id AS id,
  ROUND(
    CAST(SUM(paie_info_jours_mois2.nbjoursvrai * paie_info_jours_mois2.conge_journalier) AS DECIMAL),
    1
  ) AS jourconge
FROM public.paie_info_jours_mois2 AS paie_info_jours_mois2
GROUP BY
  paie_info_jours_mois2.id;

