-- Niveau 4 - vue 9 / 22 : PREVISION_COMPLET_CPL_NR
-- Dependances nouvelles : PREVISION_COMPLET_CPL_DEP, PREVISION_COMPLET_CPL_REC.
CREATE VIEW public.prevision_complet_cpl_nr (
    "id", "designation", "idcaisse", "idcaisselib", "idventedetail", "idvente", "idventelib", "idvirement", "debit", "credit", "daty", "etat", "idop", "idoplib", "idorigine", "iddevise", "iddeviselib", "taux", "idtiers", "compte", "effectifdebit", "effectifcredit", "depenseecart", "recetteecart", "idfacture"
) AS
SELECT
