  prevision_complet_cpl_dep.designation AS designation,
  prevision_complet_cpl_dep.idcaisse AS idcaisse,
  prevision_complet_cpl_dep.idcaisselib AS idcaisselib,
  prevision_complet_cpl_dep.idventedetail AS idventedetail,
  prevision_complet_cpl_dep.idvente AS idvente,
  prevision_complet_cpl_dep.idventelib AS idventelib,
  prevision_complet_cpl_dep.idvirement AS idvirement,
  prevision_complet_cpl_dep.debit AS debit,
  prevision_complet_cpl_dep.credit AS credit,
  prevision_complet_cpl_dep.daty AS daty,
  prevision_complet_cpl_dep.etat AS etat,
  prevision_complet_cpl_dep.idop AS idop,
  prevision_complet_cpl_dep.idoplib AS idoplib,
  prevision_complet_cpl_dep.idorigine AS idorigine,
  prevision_complet_cpl_dep.iddevise AS iddevise,
  prevision_complet_cpl_dep.iddeviselib AS iddeviselib,
