FROM public.prevision_complet_cpl_dep AS prevision_complet_cpl_dep
WHERE
  prevision_complet_cpl_dep.depenseecart > 0
UNION ALL
SELECT
  prevision_complet_cpl_rec.id AS id,
  prevision_complet_cpl_rec.designation AS designation,
  prevision_complet_cpl_rec.idcaisse AS idcaisse,
  prevision_complet_cpl_rec.idcaisselib AS idcaisselib,
  prevision_complet_cpl_rec.idventedetail AS idventedetail,
  prevision_complet_cpl_rec.idvente AS idvente,
