  prevision_complet_cpl_rec.idvirement AS idvirement,
  prevision_complet_cpl_rec.debit AS debit,
  prevision_complet_cpl_rec.credit AS credit,
  prevision_complet_cpl_rec.daty AS daty,
  prevision_complet_cpl_rec.etat AS etat,
  prevision_complet_cpl_rec.idop AS idop,
  prevision_complet_cpl_rec.idoplib AS idoplib,
  prevision_complet_cpl_rec.idorigine AS idorigine,
  prevision_complet_cpl_rec.iddevise AS iddevise,
  prevision_complet_cpl_rec.iddeviselib AS iddeviselib,
  prevision_complet_cpl_rec.taux AS taux,
  prevision_complet_cpl_rec.idtiers AS idtiers,
  prevision_complet_cpl_rec.compte AS compte,
  prevision_complet_cpl_rec.effectifdebit AS effectifdebit,
  prevision_complet_cpl_rec.effectifcredit AS effectifcredit,
  prevision_complet_cpl_rec.depenseecart AS depenseecart,
  prevision_complet_cpl_rec.recetteecart AS recetteecart,
  prevision_complet_cpl_rec.idfacture AS idfacture
FROM public.prevision_complet_cpl_rec AS prevision_complet_cpl_rec
