-- Niveau 4 - vue 10 / 22 : PREVISION_TIERS
-- Dependances nouvelles : PREVISION_COMPLET_CPLPOSITIF.
CREATE VIEW public.prevision_tiers (
    "id", "designation", "idcaisse", "idcaisselib", "idventedetail", "idvente", "idventelib", "idvirement", "debit", "credit", "daty", "etat", "idop", "idoplib", "idorigine", "iddevise", "iddeviselib", "taux", "idtiers", "compte", "effectifdebit", "effectifcredit", "depenseecart", "recetteecart", "idfacture", "tierslib"
) AS
SELECT
  p.id AS id,
  p.designation AS designation,
  p.idcaisse AS idcaisse,
  p.idcaisselib AS idcaisselib,
  p.idventedetail AS idventedetail,
  p.idvente AS idvente,
  p.idventelib AS idventelib,
  p.idvirement AS idvirement,
  p.debit AS debit,
  p.credit AS credit,
  p.daty AS daty,
  p.etat AS etat,
  p.idop AS idop,
  p.idoplib AS idoplib,
  p.idorigine AS idorigine,
  p.iddevise AS iddevise,
  p.iddeviselib AS iddeviselib,
  p.taux AS taux,
  p.idtiers AS idtiers,
  p.compte AS compte,
  p.effectifdebit AS effectifdebit,
  p.effectifcredit AS effectifcredit,
  p.depenseecart AS depenseecart,
  p.recetteecart AS recetteecart,
  p.idfacture AS idfacture,
  t.nom AS tierslib
FROM public.prevision_complet_cplpositif AS p
LEFT JOIN public.tiers AS t
  ON t.id = p.idtiers;

-- Niveau 4 - vue 11 / 22 : RESERVATIONDETAILS_LIBGROUPE
-- Dependances nouvelles : RESERVATIONDETAILS_LIB.
CREATE VIEW public.reservationdetails_libgroupe (
    "id", "idmere", "qte", "daty", "idproduit", "libelleproduit", "categorieproduit", "pu", "montant", "tva", "montanttva", "montantttc", "categorieproduitlib", "heure"
) AS
SELECT
  MIN(r.id) AS id,
  r.idmere AS idmere,
  SUM(r.qte) AS qte,
  MIN(r.daty) AS daty,
  r.idproduit AS idproduit,
  r.libelleproduit AS libelleproduit,
  r.categorieproduit AS categorieproduit,
  AVG(r.pu) AS pu,
  SUM(r.qte * r.pu) AS montant,
  AVG(r.tva) AS tva,
  CAST(SUM(r.montanttva) AS DECIMAL(20, 2)) AS montanttva,
  CAST(SUM(r.montantttc) AS DECIMAL(20, 2)) AS montantttc,
  r.categorieproduitlib AS categorieproduitlib,
  MIN(r.heure) AS heure
FROM public.reservationdetails_lib AS r
GROUP BY
  r.idmere,
  r.idproduit,
  r.libelleproduit,
  r.categorieproduit,
  r.categorieproduitlib;

-- Niveau 4 - vue 12 / 22 : RESERVATIONMONTANT
-- Dependances nouvelles : RESERVATIONDETAILS_LIB.
CREATE VIEW public.reservationmontant (
    "idmere", "montant", "montanttva", "montantttc"
) AS
SELECT
  r.idmere AS idmere,
  CAST(SUM(r.montant) AS DECIMAL(20, 2)) AS montant,
  CAST(SUM(r.montanttva) AS DECIMAL(20, 2)) AS montanttva,
  CAST(SUM(r.montantttc) AS DECIMAL(20, 2)) AS montantttc
FROM public.reservationdetails_lib AS r
GROUP BY
  r.idmere;

-- Niveau 4 - vue 13 / 22 : SITUATION_BUDGET_DEPENSES
-- Dependances nouvelles : BUDGET_DEPENSE_SUM_VIEW, BUDGET_DEPENSE_SUM_VIEW_BUDGET.
CREATE VIEW public.situation_budget_depenses (
    "id", "compte", "service", "mois", "annee", "moislib", "budget", "montantfacture", "paiement", "resteapayer", "ecartfacturebudget", "ecartbudgetpaiement", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.compte AS compte,
  sq.service AS service,
  sq.mois AS mois,
  sq.annee AS annee,
  sq.moislib AS moislib,
  sq.budget AS budget,
  sq.montantfacture AS montantfacture,
  sq.paiement AS paiement,
  sq.resteapayer AS resteapayer,
  sq.ecartfacturebudget AS ecartfacturebudget,
  sq.ecartbudgetpaiement AS ecartbudgetpaiement,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(sq.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.compte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(sq.service AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.mois
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.mois
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.mois
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(sq.moislib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.budget
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.budget
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.budget
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.montantfacture
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.montantfacture
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.montantfacture
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.paiement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.paiement
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.paiement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.resteapayer
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.resteapayer
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.resteapayer
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.ecartfacturebudget
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.ecartfacturebudget
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.ecartfacturebudget
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    sq.ecartbudgetpaiement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    sq.ecartbudgetpaiement
                  ) AS TEXT)))
                  ELSE CAST((
                    sq.ecartbudgetpaiement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    CAST('-' AS TEXT) AS id,
    bdsv.compte AS compte,
    bdsv.idservicelib AS service,
    bdsv.mois AS mois,
    bdsv.annee AS annee,
    bdsv.moislib AS moislib,
    bdsv.depenses AS budget,
    ffc.montant AS montantfacture,
    ffc.montantpaye AS paiement,
    ffc.resteapayer AS resteapayer,
    bdsv.depenses - ffc.montant AS ecartfacturebudget,
    bdsv.depenses - ffc.montantpaye AS ecartbudgetpaiement
  FROM public.budget_depense_sum_view AS bdsv
  LEFT JOIN (
    SELECT
      NULLIF(SUBSTRING(ffp.compteregr FROM 1 FOR LENGTH(bdsv_inner.compte)), '') AS compteregr_groupe,
      ffp.mois AS mois,
      ffp.annee AS annee,
      ffp.service AS service,
      SUM(ffp.montantfille * ffp.tauxdechange) AS montant,
      SUM(ffp.montantfillepaye * ffp.tauxdechange) AS montantpaye,
      SUM(ffp.resteapayerfille * ffp.tauxdechange) AS resteapayer
    FROM (
      SELECT
        fff.id,
        fff.idfacturefournisseur,
        fff.idproduit,
        fff.qte,
        fff.pu,
        fff.remises,
        fff.idbcdetail,
        fff.tva,
        fff.produitlib,
        fff.compte,
        fff.compte AS compteregr,
        fff.etat,
        fff.iddevise,
        fff.tauxdechange,
        ff.montantttc,
        fff.mois,
        fff.annee,
        ff.daty,
        ff.montantpaye * CAST(100 AS DECIMAL) / NULLIF(ff.montantttc, CAST(0 AS DECIMAL)) AS pourcentagepaye,
        ff.montantpaye / NULLIF(ff.montantttc, CAST(0 AS DECIMAL)) * (
          fff.qte * fff.pu
        ) AS montantfillepaye,
        fff.qte * fff.pu - ff.montantpaye / NULLIF(ff.montantttc, CAST(0 AS DECIMAL)) * (
          fff.qte * fff.pu
        ) AS resteapayerfille,
        ff.montantpaye / NULLIF(ff.montantttc, CAST(0 AS DECIMAL)) * (
          fff.qte * fff.pu
        ) * fff.tauxdechange AS montantfillepayear,
        fff.qte * fff.pu AS montantfille,
        ff.service
      FROM public.facturefournisseur_fillecpl AS fff
      LEFT JOIN (
        SELECT
          f.id,
          f.idfournisseur,
          f2.nom AS idfournisseurlib,
          f.idmodepaiement,
          m.val AS idmodepaiementlib,
          f.daty,
          f.designation,
          f.dateecheancepaiement,
          f.etat,
          CASE
            WHEN f.etat = CAST(1 AS DECIMAL)
            THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
            WHEN f.etat = CAST(0 AS DECIMAL)
            THEN CAST('ANNUL&Eacute;E' AS TEXT)
            WHEN f.etat = CAST(11 AS DECIMAL)
            THEN CAST('VIS&Eacute;E' AS TEXT)
            ELSE CAST(NULL AS TEXT)
          END AS etatlib,
          COALESCE(f.reference, reff.reference) AS reference,
          f.idbc,
          f.idmagasin,
          f.devise,
          CASE WHEN f.taux = CAST(0 AS DECIMAL) THEN CAST(1 AS DECIMAL) ELSE f.taux END AS taux,
          p.val AS idmagasinlib,
          f3.iddevise,
          CAST(f3.montanttva AS DECIMAL(30, 5)) AS montanttva,
          CAST((
            f3.montantttc - f3.montanttva
          ) AS DECIMAL(30, 5)) AS montantht,
          CAST(f3.montantttc AS DECIMAL(30, 5)) AS montantttc,
          CAST((
            f3.montantttc * f3.tauxdechange
          ) AS DECIMAL(30, 5)) AS montantttcar,
          CAST(COALESCE(mv.debit, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
          CAST((
            f3.montantttc - COALESCE(mv.debit, CAST(0 AS DECIMAL))
          ) AS DECIMAL(30, 5)) AS montantreste,
          CAST(COALESCE(f3.tauxdechange, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS tauxdechange,
          prev.id AS idprevision,
          CASE
            WHEN f.estprevu = CAST(0 AS DECIMAL)
            THEN CAST('NON' AS TEXT)
            ELSE CAST('OUI' AS TEXT)
          END AS estprevulib,
          f.idobjet,
          f.idref,
          f.idtypefacture,
          tf.val AS typefacture,
          f.numero,
          f.typeachat,
          f.idfactureprincipale,
          s.libelle AS idservicelib,
          f.service,
          f.typefacturefournisseur,
          tff.desce AS typefacturefournisseurlib,
          ce.id AS idecriture,
          ta.val AS typeachatlib
        FROM public.facturefournisseur AS f
        LEFT JOIN public.typeachat AS ta
          ON CAST(ta.desce AS TEXT) = CAST(f.typeachat AS TEXT)
        LEFT JOIN public.fournisseur AS f2
          ON CAST(f2.id AS TEXT) = CAST(f.idfournisseur AS TEXT)
        LEFT JOIN public.modepaiement AS m
          ON CAST(m.id AS TEXT) = CAST(f.idmodepaiement AS TEXT)
        LEFT JOIN (
          SELECT
            p.id,
            p.val,
            p.desce,
            p.id AS idpoint,
            CAST('-' AS TEXT) AS idproduit,
            CAST(NULL AS TEXT) AS idtypemagasin,
            11 AS etat
          FROM public.point AS p
        ) AS p
          ON CAST(p.id AS TEXT) = CAST(f.idmagasin AS TEXT)
        JOIN (
          SELECT
            v.id,
            CAST(SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              )
            ) AS DECIMAL(30, 2)) AS montanttotal,
            CAST(SUM(
              (
                CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
              ) * (
                COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
              ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
            ) AS DECIMAL(30, 2)) AS montanttva,
            CAST((
              SUM(
                (
                  CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                ) * (
                  COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
                ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
              ) + SUM(
                (
                  CAST(1 AS DECIMAL) - COALESCE(vd.remises / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
                ) * (
                  COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
                )
              )
            ) AS DECIMAL(30, 2)) AS montantttc,
            COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
            COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) AS tauxdechange
          FROM public.facturefournisseurfille AS vd
          LEFT JOIN public.facturefournisseur AS v
            ON CAST(v.id AS TEXT) = CAST(vd.idfacturefournisseur AS TEXT)
          GROUP BY
            v.id,
            vd.iddevise,
            vd.tauxdechange
        ) AS f3
          ON CAST(f.id AS TEXT) = CAST(f3.id AS TEXT)
        LEFT JOIN public.mouvementcaissegroupefacture AS mv
          ON CAST(f.id AS TEXT) = CAST(mv.idorigine AS TEXT)
        LEFT JOIN public.prevision AS prev
          ON CAST(prev.idfacture AS TEXT) = CAST(f.id AS TEXT)
        LEFT JOIN public.type_facture AS tf
          ON CAST(tf.id AS TEXT) = CAST(f.idtypefacture AS TEXT)
        LEFT JOIN public.service AS s
          ON CAST(f.service AS TEXT) = CAST(s.compte AS TEXT)
        LEFT JOIN public.referencefacture AS reff
          ON CAST(f.id AS TEXT) = CAST(reff.idfacture AS TEXT)
        LEFT JOIN public.typefacturefournisseur AS tff
          ON CAST(tff.id AS TEXT) = CAST(f.typefacturefournisseur AS TEXT)
        LEFT JOIN public.compta_ecriture AS ce
          ON CAST(ce.idobjet AS TEXT) = CAST(f.id AS TEXT)
      ) AS ff
        ON CAST(ff.id AS TEXT) = CAST(fff.idfacturefournisseur AS TEXT)
    ) AS ffp
    CROSS JOIN (
      SELECT DISTINCT
        b.compte AS compte
      FROM public.budget_depense_sum_view_budget AS b
    ) AS bdsv_inner
    WHERE
      NULLIF(SUBSTRING(ffp.compteregr FROM 1 FOR LENGTH(bdsv_inner.compte)), '') = bdsv_inner.compte
    GROUP BY
      NULLIF(SUBSTRING(ffp.compteregr FROM 1 FOR LENGTH(bdsv_inner.compte)), ''),
      ffp.mois,
      ffp.annee,
      ffp.service
  ) AS ffc
    ON ffc.compteregr_groupe LIKE NULLIF(CONCAT(bdsv.compte, '%'), '')
    AND ffc.mois = bdsv.mois
    AND ffc.annee = bdsv.annee
    AND ffc.service = bdsv.service
) AS sq;

-- Niveau 4 - vue 14 / 22 : SITUATION_BUDGET_RECETTES_VIDE
-- Dependances nouvelles : SITUATION_BUDGET_RECETTES.
CREATE VIEW public.situation_budget_recettes_vide (
    "id", "compte", "service", "annee", "moisdebut", "moisdebutlib", "moisfin", "moisfinlib", "budget", "montantfacture", "paiement", "resteapayer", "ecartfacturebudget", "ecartbudgetpaiement", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.compte AS compte,
  base.service AS service,
  base.annee AS annee,
  base.moisdebut AS moisdebut,
  base.moisdebutlib AS moisdebutlib,
  base.moisfin AS moisfin,
  base.moisfinlib AS moisfinlib,
  base.budget AS budget,
  base.montantfacture AS montantfacture,
  base.paiement AS paiement,
  base.resteapayer AS resteapayer,
  base.ecartfacturebudget AS ecartfacturebudget,
  base.ecartbudgetpaiement AS ecartbudgetpaiement,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.compte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.service AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.moisdebut
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.moisdebut
                  ) AS TEXT)))
                  ELSE CAST((
                    base.moisdebut
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.moisdebutlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.moisfin
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.moisfin
                  ) AS TEXT)))
                  ELSE CAST((
                    base.moisfin
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.moisfinlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.budget
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.budget
                  ) AS TEXT)))
                  ELSE CAST((
                    base.budget
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantfacture
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantfacture
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantfacture
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.paiement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.paiement
                  ) AS TEXT)))
                  ELSE CAST((
                    base.paiement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.resteapayer
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.resteapayer
                  ) AS TEXT)))
                  ELSE CAST((
                    base.resteapayer
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.ecartfacturebudget
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.ecartfacturebudget
                  ) AS TEXT)))
                  ELSE CAST((
                    base.ecartfacturebudget
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.ecartbudgetpaiement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.ecartbudgetpaiement
                  ) AS TEXT)))
                  ELSE CAST((
                    base.ecartbudgetpaiement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    sbr.id AS id,
    sbr.compte AS compte,
    sbr.service AS service,
    sbr.annee AS annee,
    6 AS moisdebut,
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST('06' AS TEXT), 'MM')) AS INT) + 0] AS moisdebutlib,
    8 AS moisfin,
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST('08' AS TEXT), 'MM')) AS INT) + 0] AS moisfinlib,
    SUM(COALESCE(sbr.budget, 0)) AS budget,
    SUM(COALESCE(sbr.montantfacture, 0)) AS montantfacture,
    SUM(COALESCE(sbr.paiement, 0)) AS paiement,
    SUM(COALESCE(sbr.resteapayer, 0)) AS resteapayer,
    SUM(COALESCE(sbr.ecartfacturebudget, 0)) AS ecartfacturebudget,
    SUM(COALESCE(sbr.ecartbudgetpaiement, 0)) AS ecartbudgetpaiement
  FROM public.situation_budget_recettes AS sbr
  WHERE
    sbr.mois BETWEEN 6 AND 8
  GROUP BY
    sbr.id,
    sbr.compte,
    sbr.service,
    sbr.annee
) AS base;

