-- Niveau 4 - vue 16 / 22 : VENTEMONTANT
-- Dependances nouvelles : VENTE_DETAILS_POIDS.
CREATE VIEW public.ventemontant (
    "id", "montanttotal", "montantremise", "frais", "montanttotalachat", "montanttva", "montantttc", "iddevise", "tauxdechange", "montantttcar", "montantrevient", "idreservation"
) AS
SELECT
  vd.idvente AS id,
  CAST(SUM(
    (
      1 - COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
    ) * (
      COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0)
    ) - (
      COALESCE(vd.fraislivraison, 0) * COALESCE(vd.calorie, 0) * vd.qte
    )
  ) AS DECIMAL(30, 2)) AS montanttotal,
  CAST(SUM((
    COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0)
  )) - SUM(
    (
      1 - COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
    ) * (
      COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0)
    )
  ) AS DECIMAL(30, 2)) AS montantremise,
  SUM(vd.frais) AS frais,
  CAST(SUM((
    COALESCE(vd.qte, 0) * COALESCE(vd.puachat, 0)
  )) AS DECIMAL(30, 2)) AS montanttotalachat,
  CAST(SUM(
    CAST((
      (
        1 - COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
      ) * (
        COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0)
      ) - (
        COALESCE(vd.fraislivraison, 0) * COALESCE(vd.calorie, 0) * vd.qte
      )
    ) * (
      COALESCE(vd.tva, 0)
    ) AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS montanttva,
  CAST(SUM(
    CAST((
      (
        1 - COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
      ) * (
        COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0)
      ) - (
        COALESCE(vd.fraislivraison, 0) * COALESCE(vd.calorie, 0) * vd.qte
      )
    ) * (
      COALESCE(vd.tva, 0)
    ) AS DECIMAL) / 100
  ) + SUM(
    (
      1 - COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
    ) * (
      COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0)
    ) - (
      COALESCE(vd.fraislivraison, 0) * COALESCE(vd.calorie, 0) * vd.qte
    )
  ) AS DECIMAL(30, 2)) AS montantttc,
  COALESCE(vd.iddevise, 'AR') AS iddevise,
  COALESCE(AVG(vd.tauxdechange), 1) AS tauxdechange,
  CAST(SUM(
    CAST((
      1 - COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
    ) * (
      COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0) - (
        COALESCE(vd.fraislivraison, 0) * COALESCE(vd.calorie, 0) * vd.qte
      ) * COALESCE(vd.tauxdechange, 1)
    ) * (
      COALESCE(vd.tva, 0)
    ) AS DECIMAL) / 100
  ) + SUM(
    (
      (
        1 - COALESCE(CAST(vd.remise AS DECIMAL) / 100, 0)
      ) * (
        COALESCE(vd.qte, 0) * COALESCE(vd.pu, 0) - (
          COALESCE(vd.fraislivraison, 0) * COALESCE(vd.calorie, 0) * vd.qte
        )
      ) * COALESCE(vd.tauxdechange, 1)
    ) - (
      (
        COALESCE(vd.fraislivraison, 0) * COALESCE(vd.calorie, 0) * vd.qte
      )
    )
  ) AS DECIMAL(30, 2)) AS montantttcar,
  CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
  vd.idreservation AS idreservation
FROM public.vente_details_poids AS vd
/*         LEFT JOIN VENTE v ON v.ID = vd.IDVENTE */
/*         left join AS_INGREDIENTS vp on vp.id = vd.IDPRODUIT */
GROUP BY
  vd.idvente,
  vd.iddevise,
  vd.idreservation;

-- Niveau 4 - vue 17 / 22 : VENTE_DETAILS_ANALYSE
-- Dependances nouvelles : VENTE_DETAILS_POIDS.
CREATE VIEW public.vente_details_analyse (
    "idventelib", "idclientlib", "categorieproduitlib", "daty", "datyprevu"
) AS
SELECT
  v.designation AS idventelib,
  c.nom AS idclientlib,
  ct.val AS categorieproduitlib,
  v.daty AS daty,
  v.datyprevu AS datyprevu
FROM public.vente_details_poids AS vdp
LEFT JOIN public.vente AS v
  ON v.id = vdp.idvente
LEFT JOIN public.client AS c
  ON c.id = v.idclient
LEFT JOIN public.as_ingredients AS ai
  ON ai.id = vdp.idproduit
LEFT JOIN public.categorieingredient AS ct
  ON ct.id = ai.categorieingredient;

-- Niveau 4 - vue 18 / 22 : VENTE_DETAILS_QTE_GRP
-- Dependances nouvelles : VENTE_DETAILS_CPL_2_VISEE.
CREATE VIEW public.vente_details_qte_grp (
    "idbcfille", "qte"
) AS
SELECT
  vd.idbcfille AS idbcfille,
  SUM(vd.qte) AS qte
FROM public.vente_details_cpl_2_visee AS vd
GROUP BY
  vd.idbcfille;

-- Niveau 4 - vue 19 / 22 : VENTE_POIDS
-- Dependances nouvelles : VENTE_DETAILS_POIDS.
CREATE VIEW public.vente_poids (
    "idvente", "poids", "colis"
) AS
SELECT
  vente_details_poids.idvente AS idvente,
  SUM(vente_details_poids.poids) AS poids,
  SUM(vente_details_poids.qte) AS colis
FROM public.vente_details_poids AS vente_details_poids
GROUP BY
  vente_details_poids.idvente;

-- Niveau 4 - vue 20 / 22 : V_ETATSTOCK_ING_GP
-- Dependances nouvelles : V_ETATSTOCK_ING.
CREATE VIEW public.v_etatstock_ing_gp (
    "id", "idproduitlib", "reste"
) AS
SELECT
  v_etatstock_ing.id AS id,
  v_etatstock_ing.idproduitlib AS idproduitlib,
  SUM(v_etatstock_ing.reste) AS reste
FROM public.v_etatstock_ing AS v_etatstock_ing
WHERE
  v_etatstock_ing.categorieingredient = 'CAT008'
GROUP BY
  v_etatstock_ing.idproduitlib,
  v_etatstock_ing.id;

-- Niveau 4 - vue 21 / 22 : V_ETATSTOCK_ING_GP_PDF
-- Dependances nouvelles : V_ETATSTOCK_ING.
CREATE VIEW public.v_etatstock_ing_gp_pdf (
    "id", "idproduitlib", "reste", "idtypeproduitlib", "pu", "montantreste"
) AS
SELECT
  ving.id AS id,
  ving.idproduitlib AS idproduitlib,
  SUM(ving.reste) AS reste,
  tp.val AS idtypeproduitlib,
  SUM(ving.pu) AS _col_4,
  SUM(ving.montantreste) AS _col_5
FROM public.v_etatstock_ing AS ving
LEFT JOIN public.as_ingredients AS aig
  ON aig.id = ving.id
LEFT JOIN public.type_produit AS tp
  ON aig.typeproduit = tp.id
WHERE
  ving.categorieingredient = 'CAT008'
GROUP BY
  ving.idproduitlib,
  ving.id,
  tp.val;

-- Niveau 4 - vue 22 / 22 : V_PANIERMOYEN
-- Dependances nouvelles : VENTE_DETAILS_CPL_2_VISEE.
CREATE VIEW public.v_paniermoyen (
    "daty", "idpointlib", "idprovincelib", "qte", "montanttotal", "putotal"
) AS
SELECT
  vente_unique.daty AS daty,
  vente_unique.idpointlib AS idpointlib,
  vente_unique.idprovincelib AS idprovincelib,
  COUNT(*) AS qte,
  SUM(vente_unique.montant_vente) AS montanttotal,
  CAST(SUM(vente_unique.montant_vente) AS DECIMAL) / COUNT(*) AS putotal
FROM (
  SELECT
    vente_details_cpl_2_visee.idvente AS idvente,
    vente_details_cpl_2_visee.daty AS daty,
    vente_details_cpl_2_visee.idpointlib AS idpointlib,
    vente_details_cpl_2_visee.idprovincelib AS idprovincelib,
    SUM(vente_details_cpl_2_visee.putotal) AS montant_vente
  FROM public.vente_details_cpl_2_visee AS vente_details_cpl_2_visee
  GROUP BY
    vente_details_cpl_2_visee.idvente,
    vente_details_cpl_2_visee.daty,
    vente_details_cpl_2_visee.idpointlib,
    vente_details_cpl_2_visee.idprovincelib
) AS vente_unique
GROUP BY
  vente_unique.daty,
  vente_unique.idpointlib,
  vente_unique.idprovincelib;

COMMIT;

-- Verification du lot prepare (les vues bloquees ne sont pas comptees).
SELECT 4 AS niveau, count(*) AS vues_presentes, 22 AS vues_attendues
FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relkind='v' AND c.relname=ANY(ARRAY[
        'as_bondecommande_meretraite', 'ca_annee_view', 'ca_journalier', 'ca_mensuel',
        'dureetravauxmachine', 'paie_info_jours_mois2_bis', 'paie_info_jours_mois3', 'paie_info_pers_histo_all',
        'prevision_complet_cpl_nr', 'prevision_tiers', 'reservationdetails_libgroupe', 'reservationmontant',
        'situation_budget_depenses', 'situation_budget_recettes_vide', 'st_ingredientsautoachat_cpl', 'ventemontant',
        'vente_details_analyse', 'vente_details_qte_grp', 'vente_poids', 'v_etatstock_ing_gp',
        'v_etatstock_ing_gp_pdf', 'v_paniermoyen'
    ]::text[]);

