        'v_etatstock_ing_eng_pdf'
    ]::text[]);
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Objets deja presents, aucune vue ne sera remplacee : %', problemes;
    END IF;
    SELECT string_agg(r.nom, ', ' ORDER BY r.nom) INTO problemes
    FROM unnest(ARRAY[
        'public.as_ingredients', 'public.as_unite', 'public.avoirfc', 'public.avoirfcfille_grp',
        'public.bondecommande_client', 'public.bondecommande_client_fille', 'public.ca_annee_view', 'public.ca_jour',
        'public.ca_journalier', 'public.categorieavoirfc', 'public.client', 'public.commande',
        'public.commandefille', 'public.compta_compte', 'public.dureetravauxmachine', 'public.liaisonpaiementtotal',
        'public.magasin2', 'public.magasinpoint', 'public.modepaiement', 'public.motifavoirfc',
        'public.mouvementcaissegrouperesa', 'public.paie_info_jours_mois2_bis', 'public.paie_info_jours_mois3', 'public.paie_info_pers_histo_all',
        'public.paie_info_pers_histo_contrat', 'public.paie_info_personnel', 'public.point', 'public.province',
        'public.referencefacture', 'public.reservation', 'public.reservationmontant', 'public.situation_budget_depenses',
        'public.st_ingredientsautoachat_cpl', 'public.stock_engage_fille_gp', 'public.tiers', 'public.typeavoir',
        'public.v_etatstock_ing_gp_pdf', 'public.vente', 'public.vente_details_qte_grp', 'public.vente_poids',
        'public.vente_reste', 'public.ventemontant'
    ]::text[]) AS r(nom)
    WHERE pg_catalog.to_regclass(r.nom::cstring) IS NULL;
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Prerequis absents : %', problemes;
    END IF;
END;
$migration_guard$ LANGUAGE plpgsql;

-- Niveau 5 - vue 1 / 17 : AVOIRFCLIB_2
-- Dependances nouvelles : VENTEMONTANT.
CREATE VIEW public.avoirfclib_2 (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "idorigine", "idclient", "compte", "compteauxiliaire", "idvente", "idventelib", "idmotif", "idmotiflib", "idcategorie", "idcategorielib", "iddevise", "tauxdechange", "montantht", "montanttva", "montantttc", "montanthtar", "montanttvaar", "montantttcar", "idreservation", "typeavoir", "clientlib", "numavoir", "idristourne", "montantreste", "numfact"
) AS
SELECT
  a.id AS id,
  a.designation AS designation,
  a.idmagasin AS idmagasin,
  m.val AS idmagasinlib,
  a.daty AS daty,
  a.remarque AS remarque,
  a.etat AS etat,
  a.idorigine AS idorigine,
  a.idclient AS idclient,
  t.compte AS compte,
  t.compteauxiliaire AS compteauxiliaire,
  a.idvente AS idvente,
  v.designation AS idventelib,
  a.idmotif AS idmotif,
  ma.val AS idmotiflib,
  a.idcategorie AS idcategorie,
  c.val AS idcategorielib,
  ag.iddevise AS iddevise,
  ag.tauxdechange AS tauxdechange,
  ag.montantht AS montantht,
  ag.montanttva AS montanttva,
  ag.montantttc AS montantttc,
  ag.montanthtar AS montanthtar,
  ag.montanttvaar AS montanttvaar,
  ag.montantttcar AS montantttcar,
  v.idreservation AS idreservation,
  ta.val AS typeavoir,
  t.nom AS clientlib,
  a.numavoir AS numavoir,
  a.idristourne AS idristourne,
  CAST(v2.montantttc - COALESCE(mv.montant, 0) AS DECIMAL(30, 2)) AS montantreste,
  v.numerofacture AS numfact
FROM public.avoirfc AS a
LEFT JOIN public.magasin2 AS m
  ON m.id = a.idmagasin
LEFT JOIN public.vente AS v
  ON v.id = a.idvente
JOIN public.ventemontant AS v2
  ON v2.id = v.id
LEFT JOIN public.liaisonpaiementtotal AS mv
  ON v.id = mv.id2
LEFT JOIN public.motifavoirfc AS ma
  ON ma.id = a.idmotif
LEFT JOIN public.categorieavoirfc AS c
  ON c.id = a.idcategorie
JOIN public.avoirfcfille_grp AS ag
  ON ag.idavoirfc = a.id
LEFT JOIN public.tiers AS t
  ON t.id = a.idclient
LEFT JOIN public.typeavoir AS ta
  ON ta.id = a.idtypeavoir;

-- Niveau 5 - vue 2 / 17 : BC_CLIENT_FILLE_CPL_LIB
-- Dependances nouvelles : VENTE_DETAILS_QTE_GRP.
CREATE VIEW public.bc_client_fille_cpl_lib (
    "id", "produit", "idbc", "quantite", "pu", "montant", "tva", "remise", "iddevise", "unite", "produitlib", "compte", "qtereste", "unitelib", "montanttotal", "montantdelaremise", "montantristourne", "montantremise", "montanttva", "montantttc", "ristourne", "fraistransport", "poidstotal"
) AS
SELECT
  bcf.id AS id,
  bcf.produit AS produit,
  bcf.idbc AS idbc,
  bcf.quantite AS quantite,
  bcf.pu AS pu,
  bcf.montant AS montant,
  bcf.tva AS tva,
  bcf.remise AS remise,
  bcf.iddevise AS iddevise,
  bcf.unite AS unite,
  i.libellevente AS produitlib,
  i.compte_vente AS compte,
  COALESCE(bcf.quantite, 0) - COALESCE(vdbc.qte, 0) AS qtereste, /* nanova qte reste : atao moins qte vendu  avy aminy vente_details_qte_grp                                                                                   */
  au.val AS unitelib,
  CAST(COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) AS DECIMAL(30, 2)) AS montanttotal,
  CAST((
    (
      COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
    ) * (
      CAST(bcf.remise AS DECIMAL) / 100
    )
  ) AS DECIMAL(30, 2)) AS montantdelaremise,
  CAST((
    COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) - (
      (
        COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
      ) * (
        CAST(bcf.remise AS DECIMAL) / 100
      )
    )
  ) * (
    CAST(bcf.ristourne AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS montantristourne,
  CAST(COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) - (
    (
      COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
    ) * (
      CAST(bcf.remise AS DECIMAL) / 100
    )
  ) - (
    (
      COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) - (
        (
          COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
        ) * (
          CAST(bcf.remise AS DECIMAL) / 100
        )
      )
    ) * (
      CAST(bcf.ristourne AS DECIMAL) / 100
    )
  ) - COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0) AS DECIMAL(30, 2)) AS montantremise,
  CAST((
    (
      (
        COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
      ) - (
        (
          (
            COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
          ) * (
            CAST(bcf.remise AS DECIMAL) / 100
          )
        ) + (
          (
            COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) - (
              (
                COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
              ) * (
                CAST(bcf.remise AS DECIMAL) / 100
              )
            )
          ) * (
            CAST(bcf.ristourne AS DECIMAL) / 100
          )
        )
      ) - COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0)
    ) * (
      CAST(COALESCE(bcf.tva, 0) AS DECIMAL) / 100
    )
  ) AS DECIMAL(30, 2)) AS montanttva,
  CAST((
    CAST((
      bcf.quantite * bcf.pu
    ) - CAST((
      (
        bcf.quantite * bcf.pu
      ) * COALESCE(bcf.remise, 0)
    ) AS DECIMAL) / 100 AS DECIMAL(30, 2)) - (
      CAST(CAST((
        bcf.quantite * bcf.pu
      ) - CAST((
        (
          bcf.quantite * bcf.pu
        ) * COALESCE(bcf.remise, 0)
      ) AS DECIMAL) / 100 AS DECIMAL(30, 2)) * COALESCE(bcf.ristourne, 0) AS DECIMAL) / 100
    ) - COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0)
  ) + (
    CAST(COALESCE(bcf.tva, 0) AS DECIMAL) / 100
  ) * (
    CAST((
      bcf.quantite * bcf.pu
    ) - CAST((
      (
        bcf.quantite * bcf.pu
      ) * COALESCE(bcf.remise, 0)
    ) AS DECIMAL) / 100 AS DECIMAL(30, 2)) - (
      CAST(CAST((
        bcf.quantite * bcf.pu
      ) - CAST((
        (
          bcf.quantite * bcf.pu
        ) * COALESCE(bcf.remise, 0)
      ) AS DECIMAL) / 100 AS DECIMAL(30, 2)) * COALESCE(bcf.ristourne, 0) AS DECIMAL) / 100
    ) - COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0)
  ) AS DECIMAL(30, 2)) AS montantttc,
  bcf.ristourne AS ristourne,
  COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0) AS fraistransport,
  CAST(COALESCE(i.calorie * bcf.quantite, 0) AS DECIMAL(30, 2)) AS poidstotal
FROM public.bondecommande_client_fille AS bcf
LEFT JOIN public.as_ingredients AS i
  ON i.id = bcf.produit
LEFT JOIN public.vente_details_qte_grp AS vdbc
  ON bcf.id = vdbc.idbcfille
LEFT JOIN public.as_unite AS au
  ON au.id = i.unite
LEFT JOIN public.bondecommande_client AS bc
  ON bc.id = bcf.idbc;

-- Niveau 5 - vue 3 / 17 : BC_CLIENT_FILLE_CPL_LIBB
-- Dependances nouvelles : VENTE_DETAILS_QTE_GRP.
CREATE VIEW public.bc_client_fille_cpl_libb (
    "id", "produit", "idbc", "quantite", "pu", "montantremise", "montanttotal", "montant", "tva", "montanttva", "remise", "iddevise", "unite", "unitelib", "produitlib", "compte", "qtereste"
) AS
SELECT
  bcf.id AS id,
  bcf.produit AS produit,
  bcf.idbc AS idbc,
  bcf.quantite AS quantite,
  bcf.pu AS pu,
  CAST((
    COALESCE(COALESCE(bcf.quantite, 0) * COALESCE(bcf.pu, 0), 0) * bcf.remise
  ) AS DECIMAL) / 100 AS montantremise,
  COALESCE(bcf.quantite, 0) * COALESCE(bcf.pu, 0) - (
    CAST((
      COALESCE(COALESCE(bcf.quantite, 0) * COALESCE(bcf.pu, 0), 0) * bcf.remise
    ) AS DECIMAL) / 100
  ) + (
    (
      CAST((
        (
          COALESCE(bcf.quantite, 0) * COALESCE(bcf.pu, 0) - CAST((
            COALESCE(COALESCE(bcf.quantite, 0) * COALESCE(bcf.pu, 0), 0) * bcf.remise
          ) AS DECIMAL) / 100
        ) * bcf.tva
      ) AS DECIMAL) / 100
    )
  ) AS montanttotal,
  bcf.montant AS montant,
  bcf.tva AS tva,
  (
    CAST((
      (
        COALESCE(bcf.quantite, 0) * COALESCE(bcf.pu, 0) - CAST((
          COALESCE(COALESCE(bcf.quantite, 0) * COALESCE(bcf.pu, 0), 0) * bcf.remise
        ) AS DECIMAL) / 100
      ) * bcf.tva
    ) AS DECIMAL) / 100
  ) AS montanttva,
  bcf.remise AS remise,
  bcf.iddevise AS iddevise,
  bcf.unite AS unite,
  un.val AS unitelib,
  i.libelle AS produitlib,
  i.compte_vente AS compte,
  GREATEST(COALESCE(bcf.quantite, 0) - COALESCE(vdbc.qte, 0), 0) AS qtereste
FROM public.bondecommande_client_fille AS bcf
JOIN public.as_ingredients AS i
  ON i.id = bcf.produit
LEFT JOIN public.as_unite AS un
  ON un.id = bcf.unite
LEFT JOIN public.vente_details_qte_grp AS vdbc
  ON bcf.id = vdbc.idbcfille;

-- Niveau 5 - vue 4 / 17 : CA_ANNEE_MOIS
-- Dependances nouvelles : CA_ANNEE_VIEW.
CREATE VIEW public.ca_annee_mois (
    "annee", "janvier", "fevrier", "mars", "avril", "mai", "juin", "juillet", "aout", "septembre", "octobre", "novembre", "decembre"
) AS
SELECT
  ca_annee_view.annee AS annee,
  SUM(CASE WHEN ca_annee_view.mois = 1 THEN ca_annee_view.montant ELSE 0 END) AS janvier,
  SUM(CASE WHEN ca_annee_view.mois = 2 THEN ca_annee_view.montant ELSE 0 END) AS fevrier,
  SUM(CASE WHEN ca_annee_view.mois = 3 THEN ca_annee_view.montant ELSE 0 END) AS mars,
  SUM(CASE WHEN ca_annee_view.mois = 4 THEN ca_annee_view.montant ELSE 0 END) AS avril,
  SUM(CASE WHEN ca_annee_view.mois = 5 THEN ca_annee_view.montant ELSE 0 END) AS mai,
  SUM(CASE WHEN ca_annee_view.mois = 6 THEN ca_annee_view.montant ELSE 0 END) AS juin,
  SUM(CASE WHEN ca_annee_view.mois = 7 THEN ca_annee_view.montant ELSE 0 END) AS juillet,
  SUM(CASE WHEN ca_annee_view.mois = 8 THEN ca_annee_view.montant ELSE 0 END) AS aout,
  SUM(CASE WHEN ca_annee_view.mois = 9 THEN ca_annee_view.montant ELSE 0 END) AS septembre,
  SUM(CASE WHEN ca_annee_view.mois = 10 THEN ca_annee_view.montant ELSE 0 END) AS octobre,
  SUM(CASE WHEN ca_annee_view.mois = 11 THEN ca_annee_view.montant ELSE 0 END) AS novembre,
  SUM(CASE WHEN ca_annee_view.mois = 12 THEN ca_annee_view.montant ELSE 0 END) AS decembre
FROM public.ca_annee_view AS ca_annee_view
GROUP BY
  ca_annee_view.annee
ORDER BY
  annee;

-- Niveau 5 - vue 5 / 17 : CA_JOURNALIER_UNION
