) AS
SELECT
  bcf.id AS id,
  bcf.produit AS produit,
  bcf.idc AS idc,
  bcf.quantite AS quantite,
  bcf.pu AS pu,
  bcf.montant AS montant,
  bcf.tva AS tva,
  bcf.remise AS remise,
  bcf.iddevise AS iddevise,
  bcf.unite AS unite,
  i.libellevente AS produitlib,
  i.compte_vente AS compte,
  COALESCE(bcf.quantite, 0) - COALESCE(vdbc.qte, 0) AS qtereste,
  au.val AS unitelib,
  CAST(COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) AS DECIMAL(30, 2)) AS montanttotal,
  CAST((
    (
      COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
    ) * (
      CAST(bcf.remise AS DECIMAL) / 100
    )
  ) AS DECIMAL(30, 2)) AS montantdelaremise,
  CAST((
    COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) - (
      (
        COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
      ) * (
        CAST(bcf.remise AS DECIMAL) / 100
      )
    )
  ) * (
    CAST(bcf.ristourne AS DECIMAL) / 100
  ) AS DECIMAL(30, 2)) AS montantristourne,
  CAST(COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) - (
    (
      COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
    ) * (
      CAST(bcf.remise AS DECIMAL) / 100
    )
  ) - (
    (
      COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) - (
        (
          COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
        ) * (
          CAST(bcf.remise AS DECIMAL) / 100
        )
      )
    ) * (
      CAST(bcf.ristourne AS DECIMAL) / 100
    )
  ) - COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0) AS DECIMAL(30, 2)) AS montantremise,
  CAST((
    (
      (
        COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
      ) - (
        (
          (
            COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
          ) * (
            CAST(bcf.remise AS DECIMAL) / 100
          )
        ) + (
          (
            COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0) - (
              (
                COALESCE(bcf.pu, 0) * COALESCE(bcf.quantite, 0)
              ) * (
                CAST(bcf.remise AS DECIMAL) / 100
              )
            )
          ) * (
            CAST(bcf.ristourne AS DECIMAL) / 100
          )
        )
      ) - COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0)
    ) * (
      CAST(COALESCE(bcf.tva, 0) AS DECIMAL) / 100
    )
  ) AS DECIMAL(30, 2)) AS montanttva,
  CAST((
    CAST((
      bcf.quantite * bcf.pu
    ) - CAST((
      (
        bcf.quantite * bcf.pu
      ) * COALESCE(bcf.remise, 0)
    ) AS DECIMAL) / 100 AS DECIMAL(30, 2)) - (
      CAST(CAST((
        bcf.quantite * bcf.pu
      ) - CAST((
        (
          bcf.quantite * bcf.pu
        ) * COALESCE(bcf.remise, 0)
      ) AS DECIMAL) / 100 AS DECIMAL(30, 2)) * COALESCE(bcf.ristourne, 0) AS DECIMAL) / 100
    ) - COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0)
  ) + (
    CAST(COALESCE(bcf.tva, 0) AS DECIMAL) / 100
  ) * (
    CAST((
      bcf.quantite * bcf.pu
    ) - CAST((
      (
        bcf.quantite * bcf.pu
      ) * COALESCE(bcf.remise, 0)
    ) AS DECIMAL) / 100 AS DECIMAL(30, 2)) - (
      CAST(CAST((
        bcf.quantite * bcf.pu
      ) - CAST((
        (
          bcf.quantite * bcf.pu
        ) * COALESCE(bcf.remise, 0)
      ) AS DECIMAL) / 100 AS DECIMAL(30, 2)) * COALESCE(bcf.ristourne, 0) AS DECIMAL) / 100
    ) - COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0)
  ) AS DECIMAL(30, 2)) AS montantttc,
  bcf.ristourne AS ristourne,
  COALESCE(i.calorie * bcf.quantite * bc.fraislivraison, 0) AS fraistransport,
  CAST(COALESCE(i.calorie * bcf.quantite, 0) AS DECIMAL(30, 2)) AS poidstotal,
  i.calorie AS calorie
FROM public.commandefille AS bcf
LEFT JOIN public.as_ingredients AS i
  ON i.id = bcf.produit
LEFT JOIN public.vente_details_qte_grp AS vdbc
  ON bcf.id = vdbc.idbcfille
LEFT JOIN public.as_unite AS au
  ON au.id = i.unite
