-- Niveau 5 - vue 8 / 17 : CONGE_DROIT
-- Dependances nouvelles : PAIE_INFO_JOURS_MOIS3.
CREATE VIEW public.conge_droit (
    "id", "idpersonnel", "mois", "annee", "conge", "etat"
) AS
SELECT
  NULLIF(CONCAT('CONG-', pip.id), '') AS id,
  pip.id AS idpersonnel,
  0 AS mois,
  0 AS annee,
  (
    CAST(ROUND(pijm.jourconge * 2) AS DECIMAL) / 2
  ) AS conge,
  11 AS etat
FROM public.paie_info_personnel AS pip
LEFT JOIN public.paie_info_jours_mois3 AS pijm
  ON pip.id = pijm.id;

-- Niveau 5 - vue 9 / 17 : MOYENNETRAVAUXMACHINE
-- Dependances nouvelles : DUREETRAVAUXMACHINE.
CREATE VIEW public.moyennetravauxmachine (
    "idmachine", "nommachine", "moyennedureeestimatif", "moyenneduree", "moyenneecart"
) AS
SELECT
  d.idmachine AS idmachine,
  d.nommachine AS nommachine,
  CAST(AVG(d.dureeestimatif) AS DECIMAL(10, 2)) AS moyennedureeestimatif,
  CAST(AVG(d.duree) AS DECIMAL(10, 2)) AS moyenneduree,
  CAST(AVG(d.ecart) AS DECIMAL(10, 2)) AS moyenneecart
FROM public.dureetravauxmachine AS d
GROUP BY
  d.idmachine,
  d.nommachine;

-- Niveau 5 - vue 10 / 17 : PAIE_INFO_JOURS_MOIS3_BIS
-- Dependances nouvelles : PAIE_INFO_JOURS_MOIS2_BIS.
CREATE VIEW public.paie_info_jours_mois3_bis (
    "id", "jourconge"
) AS
SELECT
  paie_info_jours_mois2_bis.id AS id,
  ROUND(
    CAST(SUM(
      paie_info_jours_mois2_bis.nbjoursvrai * paie_info_jours_mois2_bis.conge_journalier
    ) AS DECIMAL),
    1
  ) AS jourconge
FROM public.paie_info_jours_mois2_bis AS paie_info_jours_mois2_bis
GROUP BY
  paie_info_jours_mois2_bis.id;

