-- Niveau 5 - vue 12 / 17 : RESERVATION_LIB
-- Dependances nouvelles : RESERVATIONMONTANT.
CREATE VIEW public.reservation_lib (
    "id", "idclient", "idclientlib", "daty", "remarque", "etat", "etatlib", "montant", "montantttc", "montanttva", "paye", "resteapayer"
) AS
SELECT
  r.id AS id,
  r.idclient AS idclient,
  c.nom AS idclientlib,
  r.daty AS daty,
  r.remarque AS remarque,
  r.etat AS etat,
  CASE
    WHEN r.etat = 1
    THEN 'CREE'
    WHEN r.etat = 0
    THEN 'ANNULEE'
    WHEN r.etat = 11
    THEN 'VISEE'
  END AS etatlib,
  rm.montant AS montant,
  rm.montantttc AS montantttc,
  rm.montanttva AS montanttva,
  mvt.credit AS paye,
  CAST(rm.montantttc - mvt.credit AS DECIMAL(20, 2)) AS resteapayer
FROM public.reservation AS r
LEFT JOIN public.client AS c
  ON c.id = r.idclient
LEFT JOIN public.reservationmontant AS rm
  ON rm.idmere = r.id
LEFT JOIN public.mouvementcaissegrouperesa AS mvt
  ON mvt.idorigine = r.id;

-- Niveau 5 - vue 13 / 17 : SITUATION_BUDGET_DEPENSES_VIDE
-- Dependances nouvelles : SITUATION_BUDGET_DEPENSES.
CREATE VIEW public.situation_budget_depenses_vide (
    "id", "compte", "service", "annee", "moisdebut", "moisdebutlib", "moisfin", "moisfinlib", "budget", "montantfacture", "paiement", "resteapayer", "ecartfacturebudget", "ecartbudgetpaiement", "motsclesss"
) AS
SELECT
  base.id AS id,
  base.compte AS compte,
  base.service AS service,
  base.annee AS annee,
  base.moisdebut AS moisdebut,
  base.moisdebutlib AS moisdebutlib,
  base.moisfin AS moisfin,
  base.moisfinlib AS moisfinlib,
  base.budget AS budget,
  base.montantfacture AS montantfacture,
  base.paiement AS paiement,
  base.resteapayer AS resteapayer,
  base.ecartfacturebudget AS ecartfacturebudget,
  base.ecartbudgetpaiement AS ecartbudgetpaiement,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(base.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.compte AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(base.service AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    base.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.moisdebut
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.moisdebut
                  ) AS TEXT)))
                  ELSE CAST((
                    base.moisdebut
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.moisdebutlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.moisfin
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.moisfin
                  ) AS TEXT)))
                  ELSE CAST((
                    base.moisfin
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(base.moisfinlib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.budget
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.budget
                  ) AS TEXT)))
                  ELSE CAST((
                    base.budget
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.montantfacture
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.montantfacture
                  ) AS TEXT)))
                  ELSE CAST((
                    base.montantfacture
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.paiement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.paiement
                  ) AS TEXT)))
                  ELSE CAST((
                    base.paiement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.resteapayer
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.resteapayer
                  ) AS TEXT)))
                  ELSE CAST((
                    base.resteapayer
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.ecartfacturebudget
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.ecartfacturebudget
                  ) AS TEXT)))
                  ELSE CAST((
                    base.ecartfacturebudget
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    base.ecartbudgetpaiement
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    base.ecartbudgetpaiement
                  ) AS TEXT)))
                  ELSE CAST((
                    base.ecartbudgetpaiement
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM (
  SELECT
    sbd.id AS id,
    sbd.compte AS compte,
    sbd.service AS service,
    sbd.annee AS annee,
    6 AS moisdebut,
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST('06' AS TEXT), 'MM')) AS INT) + 0] AS moisdebutlib,
    8 AS moisfin,
    (
      ARRAY[
        'Janvier',
        'Février',
        'Mars',
        'Avril',
        'Mai',
        'Juin',
        'Juillet',
        'Août',
        'Septembre',
        'Octobre',
        'Novembre',
        'Décembre'
      ]
    )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST('08' AS TEXT), 'MM')) AS INT) + 0] AS moisfinlib,
    SUM(COALESCE(sbd.budget, 0)) AS budget,
    SUM(COALESCE(sbd.montantfacture, 0)) AS montantfacture,
    SUM(COALESCE(sbd.paiement, 0)) AS paiement,
    SUM(COALESCE(sbd.resteapayer, 0)) AS resteapayer,
    SUM(COALESCE(sbd.ecartfacturebudget, 0)) AS ecartfacturebudget,
    SUM(COALESCE(sbd.ecartbudgetpaiement, 0)) AS ecartbudgetpaiement
  FROM public.situation_budget_depenses AS sbd
  WHERE
    sbd.mois BETWEEN 6 AND 8
  GROUP BY
    sbd.id,
    sbd.compte,
    sbd.service,
    sbd.annee
) AS base;

-- Niveau 5 - vue 14 / 17 : UPDATEVENTE
-- Dependances nouvelles : VENTEMONTANT.
CREATE VIEW public.updatevente (
    "id", "designation", "idmagasin", "daty", "remarque", "etat", "idorigine", "idclient", "idclientlib", "iddevise", "idreservation", "datyprevu", "echeancefacture", "estprevu"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  v.daty AS daty,
  v.remarque AS remarque,
  v.etat AS etat,
  v.idorigine AS idorigine,
  v.idclient AS idclient,
  c.nom AS idclientlib,
  v2.iddevise AS iddevise,
  v.idreservation AS idreservation,
  v.datyprevu AS datyprevu,
  v.echeancefacture AS echeancefacture,
  v.estprevu AS estprevu
FROM public.vente AS v
JOIN public.client AS c
  ON c.id = v.idclient
JOIN public.ventemontant AS v2
  ON v2.id = v.id;

-- Niveau 5 - vue 15 / 17 : VENTE_CPL_ANALYSE
-- Dependances nouvelles : VENTEMONTANT.
CREATE VIEW public.vente_cpl_analyse (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "etatlib", "montanttotal", "montanttotalachat", "idpoint", "idpointlib", "montantrevient", "idreservation"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  m.val AS idmagasinlib,
  v.daty AS daty,
  v.remarque AS remarque,
  v.etat AS etat,
  CASE
    WHEN v.etat = 1
    THEN 'CREE'
    WHEN v.etat = 11
    THEN 'EN ATTENTE LIVRAISON ET PAIEMENT'
    WHEN v.etat = 0
    THEN 'ANNULEE'
    WHEN v.etat = 12
    THEN 'LIVRE NON PAYE'
    WHEN v.etat = 13
    THEN 'PAYE NON LIVRE'
    WHEN v.etat = 14
    THEN 'PAYE ET LIVRE'
  END AS etatlib,
  v2.montanttotal AS montanttotal,
  v2.montanttotalachat AS montanttotalachat,
  p.id AS idpoint,
  p.val AS idpointlib,
  v2.montanttotal - v2.montanttotalachat AS montantrevient,
  v.idreservation AS idreservation
FROM public.vente AS v
LEFT JOIN (
  SELECT
    p.id,
    p.val,
    p.desce,
    p.id AS idpoint,
    CAST('-' AS TEXT) AS idproduit,
    CAST(NULL AS TEXT) AS idtypemagasin,
    11 AS etat
  FROM public.point AS p
) AS m
  ON m.id = v.idmagasin
LEFT JOIN public.point AS p
  ON m.idpoint = p.id
JOIN public.ventemontant AS v2
  ON v2.id = v.id;

-- Niveau 5 - vue 16 / 17 : VENTE_CPL_SANSAVOIR
-- Dependances nouvelles : VENTE_POIDS, VENTEMONTANT.
CREATE VIEW public.vente_cpl_sansavoir (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "etatlib", "montanttotal", "iddevise", "idclient", "idclientlib", "montanttva", "montantttc", "montantttcar", "montantpaye", "montantreste", "tauxdechange", "montantrevient", "margebrute", "idreservation", "datyprevu", "referencefacture", "montantremise", "montant", "mois", "annee", "poids", "modepaiement", "modepaiementlib", "fraislivraison", "modelivraison", "modelivraisonlib", "reste", "idprovince", "provincelib", "numfact"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  m.val AS idmagasinlib,
  v.daty AS daty,
  v.remarque AS remarque,
  v.etat AS etat,
  CASE
    WHEN v.etat = 1
    THEN 'CREE'
    WHEN v.etat = 11
    THEN 'VISE'
    WHEN v.etat = 0
    THEN 'ANNULE'
  END AS etatlib,
  v2.montanttotal AS montanttotal,
  v2.iddevise AS iddevise,
  v.idclient AS idclient,
  c.nom AS idclientlib,
  CAST(v2.montanttva AS DECIMAL(30, 2)) AS montanttva,
  CAST(v2.montantttc AS DECIMAL(30, 2)) AS montantttc,
  CAST(v2.montantttcar AS DECIMAL(30, 2)) AS montantttcar,
  CAST(COALESCE(mv.montant, 0) AS DECIMAL(30, 2)) AS montantpaye,
  CAST(v2.montantttc - COALESCE(mv.montant, 0) AS DECIMAL(30, 2)) AS montantreste,
  v2.tauxdechange AS tauxdechange,
  v2.montantrevient AS montantrevient,
  CAST((
    v2.montantttcar - v2.montantrevient
  ) AS DECIMAL(20, 2)) AS margebrute,
  v.idreservation AS idreservation,
  CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
  rf.reference AS referencefacture,
  v2.montantremise AS montantremise,
  COALESCE(v2.montanttotal, 0) + COALESCE(v2.montantremise, 0) AS montant,
  EXTRACT(MONTH FROM v.daty) AS mois,
  EXTRACT(YEAR FROM v.daty) AS annee,
  vp.poids AS poids,
  v.modepaiement AS modepaiement,
  mp.val AS modepaiementlib,
  COALESCE(v.fraislivraison, 0) * COALESCE(vp.poids, 0) AS fraislivraison,
  v.modelivraison AS modelivraison,
  CASE
    WHEN v.modelivraison = 1
    THEN '<span style=color: green;>LIVRAISON</span>'
    WHEN v.modelivraison = 2
    THEN '<span style=color: green;>RECUPERATION</span>'
  END AS modelivraisonlib,
  vr.reste AS reste,
  pv.id AS idprovince,
  pv.val AS provincelib,
  v.numerofacture AS numfact
FROM public.vente AS v
LEFT JOIN public.client AS c
  ON c.id = v.idclient
LEFT JOIN public.province AS pv
  ON pv.id = c.idprovince
LEFT JOIN public.magasinpoint AS m
  ON m.id = v.idmagasin
JOIN public.ventemontant AS v2
  ON v2.id = v.id
LEFT JOIN public.liaisonpaiementtotal AS mv
  ON v.id = mv.id2
LEFT JOIN public.referencefacture AS rf
  ON rf.idfacture = v.id
LEFT JOIN public.vente_poids AS vp
  ON vp.idvente = v.id
LEFT JOIN public.modepaiement AS mp
  ON mp.id = v.modepaiement
LEFT JOIN public.vente_reste AS vr
  ON vr.idvente = v.id;

-- Niveau 5 - vue 17 / 17 : V_ETATSTOCK_ING_ENG_PDF
-- Dependances nouvelles : V_ETATSTOCK_ING_GP_PDF.
CREATE VIEW public.v_etatstock_ing_eng_pdf (
    "id", "idproduitlib", "reste", "sortie", "entree", "idtypeproduitlib", "pu", "montantreste"
) AS
SELECT
  v.id AS id,
  v.idproduitlib AS idproduitlib,
  v.reste AS reste,
  COALESCE(s.sortie, 0) AS sortie,
  v.reste - COALESCE(s.sortie, 0) AS entree,
  v.idtypeproduitlib AS idtypeproduitlib,
  v.pu AS pu,
  v.montantreste AS montantreste
FROM public.v_etatstock_ing_gp_pdf AS v
LEFT JOIN public.stock_engage_fille_gp AS s
  ON v.id = s.idproduit;

