-- Niveau 6 - vue 1 / 9 : AVOIRFCLIB
-- Dependances nouvelles : VENTE_CPL_SANSAVOIR.
CREATE VIEW public.avoirfclib (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "idorigine", "idclient", "compte", "compteauxiliaire", "idvente", "idventelib", "idmotif", "idmotiflib", "idcategorie", "idcategorielib", "iddevise", "tauxdechange", "montantht", "montanttva", "montantttc", "montanthtar", "montanttvaar", "montantttcar", "idreservation", "typeavoir", "clientlib", "numavoir", "idristourne", "montantreste", "numfact"
) AS
SELECT
  a.id AS id,
  a.designation AS designation,
  a.idmagasin AS idmagasin,
  m.val AS idmagasinlib,
  a.daty AS daty,
  a.remarque AS remarque,
  a.etat AS etat,
  a.idorigine AS idorigine,
  a.idclient AS idclient,
  t.compte AS compte,
  t.compteauxiliaire AS compteauxiliaire,
  a.idvente AS idvente,
  v.designation AS idventelib,
  a.idmotif AS idmotif,
  ma.val AS idmotiflib,
  a.idcategorie AS idcategorie,
  c.val AS idcategorielib,
  ag.iddevise AS iddevise,
  ag.tauxdechange AS tauxdechange,
  ag.montantht AS montantht,
  ag.montanttva AS montanttva,
  ag.montantttc AS montantttc,
  ag.montanthtar AS montanthtar,
  ag.montanttvaar AS montanttvaar,
  ag.montantttcar AS montantttcar,
  v.idreservation AS idreservation,
  ta.val AS typeavoir,
  t.nom AS clientlib,
  a.numavoir AS numavoir,
  a.idristourne AS idristourne,
  v.montantreste AS montantreste,
  v.numfact AS numfact
FROM public.avoirfc AS a
LEFT JOIN public.magasin2 AS m
  ON m.id = a.idmagasin
LEFT JOIN public.vente_cpl_sansavoir AS v
  ON v.id = a.idvente
LEFT JOIN public.motifavoirfc AS ma
  ON ma.id = a.idmotif
LEFT JOIN public.categorieavoirfc AS c
  ON c.id = a.idcategorie
JOIN public.avoirfcfille_grp AS ag
  ON ag.idavoirfc = a.id
LEFT JOIN public.tiers AS t
  ON t.id = a.idclient
LEFT JOIN public.typeavoir AS ta
  ON ta.id = a.idtypeavoir;

-- Niveau 6 - vue 2 / 9 : BONDECOMMANDE_CLIENT_CPL_M
-- Dependances nouvelles : BC_CLIENT_FILLE_CPL_LIB.
CREATE VIEW public.bondecommande_client_cpl_m (
    "id", "daty", "etat", "remarque", "designation", "modepaiement", "modepaiementlib", "idclient", "idclientlib", "reference", "idmagasinlib", "etatlib", "idproforma", "nbfacture", "modelivraisonlib", "datelivraison", "lieulivraison", "numerobc", "qtereste", "facturelib", "motsclesss"
) AS
SELECT
  bc.id AS id,
  bc.daty AS daty,
  CASE WHEN (
    SUM(bcf.qtereste)
  ) = 0 THEN 12 ELSE bc.etat END AS etat,
  bc.remarque AS remarque,
  bc.designation AS designation,
  bc.modepaiement AS modepaiement,
  m.val AS modepaiementlib,
  bc.idclient AS idclient,
  c.nom AS idclientlib,
  bc.reference AS reference,
  m2.val AS idmagasinlib,
  CASE
    WHEN (
      SUM(bcf.qtereste)
    ) = 0
    THEN '<span style=color: green;>VALID&Eacute;</span>'
    WHEN bc.etat = 0
    THEN '<span style=color: green;>ANNUL&Eacute;</span>'
    WHEN bc.etat = 1
    THEN '<span style=color: green;>CR&Eacute;&Eacute;</span>'
    WHEN bc.etat = 11
    THEN '<span style=color: green;>VALID&Eacute;</span>'
    WHEN bc.etat = 12
    THEN '<span style=color: green;>VALID&Eacute;</span>'
  END AS etatlib,
  bc.idproforma AS idproforma,
  COALESCE(vo.nombre, 0) AS nbfacture,
  CASE
    WHEN bc.modelivraison = 1
    THEN '<span style=color: green;>LIVRAISON</span>'
    WHEN bc.modelivraison = 2
    THEN '<span style=color: green;>R&Eacute;CUP&Eacute;RATION</span>'
  END AS modelivraisonlib,
  bc.datelivraison AS datelivraison,
  bc.lieulivraison AS lieulivraison,
  bc.numerobc AS numerobc,
  SUM(bcf.qtereste) AS qtereste,
  CASE
    WHEN COALESCE(vo.nombre, 0) > 0
    THEN '<span style=color: green;>FACTUR&Eacute;</span>'
    WHEN COALESCE(vo.nombre, 0) = 0
    THEN '<span style=color: red;>NON FACTUR&Eacute;</span>'
  END AS facturelib,
  NULLIF(
    CONCAT(
      bc.id,
      NULL,
      bc.daty,
      NULL,
      bc.idclient,
      NULL,
      c.nom,
      NULL,
      bc.designation,
      NULL,
      bc.reference,
      NULL,
      bc.modepaiement,
      NULL,
      bc.numerobc
    ),
    ''
  ) AS motsclesss
FROM public.bondecommande_client AS bc
LEFT JOIN public.client AS c
  ON c.id = bc.idclient
LEFT JOIN public.modepaiement AS m
  ON m.id = bc.modepaiement
LEFT JOIN public.magasin2 AS m2
  ON m2.id = bc.idmagasin
LEFT JOIN public.vente_origine AS vo
  ON vo.idorigine = bc.id
LEFT JOIN public.bc_client_fille_cpl_lib AS bcf
  ON bcf.idbc = bc.id
GROUP BY
  bc.id,
  bc.daty,
  bc.etat,
  bc.remarque,
  bc.designation,
  bc.modepaiement,
  m.val,
  bc.idclient,
  c.nom,
  bc.reference,
  m2.val,
  bc.idproforma,
  vo.nombre,
  bc.datelivraison,
  bc.lieulivraison,
  bc.numerobc,
  bc.modelivraison;

-- Niveau 6 - vue 3 / 9 : CA_JOURNALIER_UNION_GP
-- Dependances nouvelles : CA_JOURNALIER_UNION.
CREATE VIEW public.ca_journalier_union_gp (
    "montant", "annee", "mois", "daty"
) AS
SELECT
  SUM(ca_journalier_union.montant) AS montant,
  ca_journalier_union.annee AS annee,
  ca_journalier_union.mois AS mois,
  ca_journalier_union.daty AS daty
FROM public.ca_journalier_union AS ca_journalier_union
GROUP BY
  ca_journalier_union.annee,
  ca_journalier_union.mois,
  ca_journalier_union.daty;

-- Niveau 6 - vue 4 / 9 : COMMANDEMONTANT
-- Dependances nouvelles : COMMANDEFILLE_CPL_LIB.
CREATE VIEW public.commandemontant (
    "id", "poidstotal", "montant", "montantremise", "montantristourne", "fraistransport", "montanttotal", "montanttotalachat", "montanttva", "montantttc", "iddevise", "tauxdechange", "montantttcar"
) AS
SELECT
  v.id AS id,
  CAST(SUM(vd.poidstotal) AS DECIMAL(30, 2)) AS poidstotal,
  CAST(SUM(vd.pu) AS DECIMAL(30, 2)) AS montant,
  CAST(SUM(vd.montantremise) AS DECIMAL(30, 2)) AS montantremise,
  CAST(SUM(vd.montantristourne) AS DECIMAL(30, 2)) AS montantristourne,
  CAST(SUM(vd.fraistransport) AS DECIMAL(30, 2)) AS fraistransport,
  CAST(SUM(vd.montanttotal) AS DECIMAL(30, 2)) AS montanttotal,
  CAST(SUM((
    COALESCE(vd.quantite, 0) * COALESCE(vd.pu, 0)
  )) AS DECIMAL(30, 2)) AS montanttotalachat,
  CAST(SUM(vd.montanttva) AS DECIMAL(30, 2)) AS montanttva,
  CAST(SUM(vd.montantttc) AS DECIMAL(30, 2)) AS montantttc,
  COALESCE(vd.iddevise, 'AR') AS iddevise,
  COALESCE(AVG(1), 1) AS tauxdechange,
  CAST(SUM(vd.montantttc) AS DECIMAL(30, 2)) AS montantttcar
FROM public.commandefille_cpl_lib AS vd
LEFT JOIN public.commande AS v
  ON v.id = vd.idc
GROUP BY
  v.id,
  vd.iddevise;

-- Niveau 6 - vue 5 / 9 : CONGE_DROIT_LIB
-- Dependances nouvelles : CONGE_DROIT.
CREATE VIEW public.conge_droit_lib (
    "id", "idpersonnel", "mois", "annee", "conge", "etat", "matricule", "etatlib"
) AS
SELECT
  cd.id AS id,
  NULLIF(CONCAT((
    NULLIF(CONCAT(lp.nom, ' '), '')
  ), lp.prenom), '') AS idpersonnel,
  cd.mois AS mois,
  cd.annee AS annee,
  cd.conge AS conge,
  cd.etat AS etat,
  lp.matricule AS matricule,
  CASE
    WHEN cd.etat = 1
    THEN 'CREE(E)'
    WHEN cd.etat = 11
    THEN 'VISE(E)'
    WHEN cd.etat <= 0
    THEN 'ANNULE(E)'
    ELSE NULL
  END AS etatlib
FROM public.conge_droit AS cd
JOIN public.log_personnel_infocomplet AS lp
  ON lp.id = cd.idpersonnel;

-- Niveau 6 - vue 6 / 9 : CONGE_DROIT_LIBCOMPLET
-- Dependances nouvelles : CONGE_DROIT.
CREATE VIEW public.conge_droit_libcomplet (
    "id", "idpersonnel", "mois", "annee", "conge", "etat", "idpersonnellib"
) AS
SELECT
  cd.id AS id,
  cd.idpersonnel AS idpersonnel,
  cd.mois AS mois,
  cd.annee AS annee,
  cd.conge AS conge,
  cd.etat AS etat,
  NULLIF(CONCAT((
    NULLIF(CONCAT(lp.nom, ' '), '')
  ), lp.prenom), '') AS idpersonnellib
FROM public.conge_droit AS cd
JOIN public.log_personnel AS lp
  ON lp.id = cd.idpersonnel;

-- Niveau 6 - vue 7 / 9 : DROITDECONGE_PARPERSONNE
-- Dependances nouvelles : PAIE_INFO_JOURS_MOIS3_BIS.
CREATE VIEW public.droitdeconge_parpersonne (
    "idpersonnel", "conge"
) AS
SELECT
  dp.idpersonnel AS idpersonnel,
  CAST(ROUND((
    dp.conge + pij.jourconge
  ) * 2) AS DECIMAL) / 2 - 1.5 AS conge
FROM public.droitdeconge_parpers AS dp
LEFT JOIN public.paie_info_jours_mois3_bis AS pij
  ON dp.idpersonnel = pij.id;

-- Niveau 6 - vue 8 / 9 : RESERVATION_LIB_AVECMAXDATE
-- Dependances nouvelles : RESERVATION_LIB, RESERVATIONDETAILSMAXDATE.
CREATE VIEW public.reservation_lib_avecmaxdate (
    "id", "idclient", "idclientlib", "daty", "remarque", "etat", "etatlib", "montant", "montantttc", "montanttva", "paye", "resteapayer", "datyfinpotentiel"
) AS
SELECT
  rl.id AS id,
  rl.idclient AS idclient,
  rl.idclientlib AS idclientlib,
  rl.daty AS daty,
  rl.remarque AS remarque,
  rl.etat AS etat,
  rl.etatlib AS etatlib,
  rl.montant AS montant,
  rl.montantttc AS montantttc,
  rl.montanttva AS montanttva,
  rl.paye AS paye,
  rl.resteapayer AS resteapayer,
  rdmd.daty AS datyfinpotentiel
FROM public.reservation_lib AS rl
LEFT JOIN public.reservationdetailsmaxdate AS rdmd
  ON rl.id = rdmd.idmere;

-- Niveau 6 - vue 9 / 9 : TAUXDISPONIBILITEMACHINE
-- Dependances nouvelles : MOYENNEPANNESTRAVAUX, MOYENNETRAVAUXMACHINE.
CREATE VIEW public.tauxdisponibilitemachine (
    "idmachine", "nommachine", "idligne", "idlignelib", "tauxdisponibilite"
) AS
SELECT
  m.idmachine AS idmachine,
  m.nommachine AS nommachine,
  l.id AS idligne,
  l.val AS idlignelib,
  CASE
    WHEN m2.ecartjours <> 0 AND m.moyenneduree <> 0
    THEN CAST((
      m2.ecartjours * 24
    ) AS DECIMAL) / (
      CAST((
        m2.ecartjours * 24
      ) AS DECIMAL) / m.moyenneduree
    )
    ELSE 0
  END AS tauxdisponibilite
FROM public.moyennetravauxmachine AS m
LEFT JOIN public.moyennepannestravaux AS m2
  ON m.idmachine = m2.idmachine
LEFT JOIN public.as_ingredient_maintenance AS aim
  ON m.idmachine = aim.id
LEFT JOIN public.ligne AS l
  ON aim.idligne = l.id;

COMMIT;

