-- Niveau 7 - vue 1 / 9 : AVOIRFCLIB_CPL
-- Dependances nouvelles : AVOIRFCLIB, VENTE_CPL_SANSAVOIR.
CREATE VIEW public.avoirfclib_cpl (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "idorigine", "idclient", "compte", "idvente", "idventelib", "idmotif", "idmotiflib", "idcategorie", "idcategorielib", "iddevise", "tauxdechange", "montantht", "montanttva", "montantttc", "montanthtar", "montanttvaar", "montantttcar", "montantpaye", "montantpayear", "montant_reste_facture", "montant_avoirs_anterieurs", "reste_calcule", "excedent_ar", "resteapayer", "resteapayerar", "clientlib", "typeavoir", "numfact"
) AS
SELECT
  al.id AS id,
  al.designation AS designation,
  al.idmagasin AS idmagasin,
  al.idmagasinlib AS idmagasinlib,
  al.daty AS daty,
  al.remarque AS remarque,
  al.etat AS etat,
  al.idorigine AS idorigine,
  al.idclient AS idclient,
  al.compte AS compte,
  al.idvente AS idvente,
  al.idventelib AS idventelib,
  al.idmotif AS idmotif,
  al.idmotiflib AS idmotiflib,
  al.idcategorie AS idcategorie,
  al.idcategorielib AS idcategorielib,
  al.iddevise AS iddevise,
  al.tauxdechange AS tauxdechange,
  al.montantht AS montantht,
  al.montanttva AS montanttva,
  al.montantttc AS montantttc,
  al.montanthtar AS montanthtar,
  al.montanttvaar AS montanttvaar,
  al.montantttcar AS montantttcar,
  COALESCE(m.montant, 0) AS montantpaye,
  COALESCE(m.montant, 0) * COALESCE(al.tauxdechange, 0) AS montantpayear,
  COALESCE(vc.montantreste, 0) AS montant_reste_facture,
  COALESCE(sum_precedents.montant_avoirs_precedents, 0) AS montant_avoirs_anterieurs,
  CASE
    WHEN COALESCE(vc.montantreste, 0) = 0
    THEN 0
    ELSE COALESCE(vc.montantreste, 0) - COALESCE(sum_precedents.montant_avoirs_precedents, 0) - COALESCE(al.montantttcar, 0)
  END AS reste_calcule, /* Cas 1 : facture deja soldee -> chaque avoir = credit direct (exedent) */
  CASE
    WHEN COALESCE(vc.montantreste, 0) = 0
    THEN COALESCE(al.montantttcar, 0)
    WHEN COALESCE(vc.montantreste, 0) - COALESCE(sum_precedents.montant_avoirs_precedents, 0) - COALESCE(al.montantttcar, 0) < 0
    THEN ABS(
      COALESCE(vc.montantreste, 0) - COALESCE(sum_precedents.montant_avoirs_precedents, 0) - COALESCE(al.montantttcar, 0)
    )
    ELSE 0
  END AS excedent_ar, /* Excedent a rembourser ou a reporter */
  (
    CASE
      WHEN COALESCE(vc.montantreste, 0) = 0
      THEN COALESCE(al.montantttcar, 0)
      WHEN COALESCE(vc.montantreste, 0) - COALESCE(sum_precedents.montant_avoirs_precedents, 0) - COALESCE(al.montantttcar, 0) < 0
      THEN ABS(
        COALESCE(vc.montantreste, 0) - COALESCE(sum_precedents.montant_avoirs_precedents, 0) - COALESCE(al.montantttcar, 0)
      )
      ELSE 0
    END
  ) - COALESCE(m.montant, 0) AS resteapayer,
  (
    CASE
      WHEN COALESCE(vc.montantreste, 0) = 0
      THEN COALESCE(al.montantttcar, 0)
      WHEN COALESCE(vc.montantreste, 0) - COALESCE(sum_precedents.montant_avoirs_precedents, 0) - COALESCE(al.montantttcar, 0) < 0
      THEN ABS(
        COALESCE(vc.montantreste, 0) - COALESCE(sum_precedents.montant_avoirs_precedents, 0) - COALESCE(al.montantttcar, 0)
      )
      ELSE 0
    END
  ) - (
    COALESCE(m.montant, 0) * COALESCE(al.tauxdechange, 0)
  ) AS resteapayerar,
  al.clientlib AS clientlib,
  al.typeavoir AS typeavoir,
  vc.numfact AS numfact
FROM public.avoirfclib AS al
LEFT JOIN (
  SELECT
    m.id1 AS idorigine,
    SUM(m.montant) AS montant,
    CAST('AR' AS TEXT) AS iddevise
  FROM public.liaisonpaiement AS m
  WHERE
    m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
  GROUP BY
    m.id1
) AS m
  ON al.id = m.idorigine
LEFT JOIN public.vente_cpl_sansavoir AS vc
  ON vc.id = al.idvente
/* Somme des avoirs precedents pour la meme facture */
LEFT JOIN (
  SELECT
    _0.idvente AS idvente,
    _0.id AS idcourant,
    _0.montant_avoirs_precedents AS montant_avoirs_precedents
  FROM (
    SELECT
      avoirfclib.idvente AS idvente,
      avoirfclib.id AS id,
      SUM(CASE WHEN avoirfclib.etat <> 0 THEN avoirfclib.montantttcar ELSE 0 END) OVER (
        PARTITION BY avoirfclib.idvente
        ORDER BY avoirfclib.daty, avoirfclib.id
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ) AS montant_avoirs_precedents
    FROM public.avoirfclib AS avoirfclib
  ) AS _0
  WHERE
    NOT _0.montant_avoirs_precedents IS NULL
) AS sum_precedents
  ON sum_precedents.idvente = al.idvente AND sum_precedents.idcourant = al.id;

-- Niveau 7 - vue 2 / 9 : AVOIRFCLIB_CPL_V2
-- Dependances nouvelles : AVOIRFCLIB.
CREATE VIEW public.avoirfclib_cpl_v2 (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "idorigine", "idclient", "compte", "idvente", "idventelib", "idmotif", "idmotiflib", "idcategorie", "idcategorielib", "iddevise", "tauxdechange", "montantht", "montanttva", "montantttc", "montanthtar", "montanttvaar", "montantttcar", "montantpaye", "montantpayear", "montant_reste_facture", "montant_avoirs_anterieurs", "reste_calcule", "excedent_ar", "resteapayer", "resteapayerar", "clientlib", "typeavoir", "numfact"
) AS
SELECT
  al.id AS id,
  al.designation AS designation,
  al.idmagasin AS idmagasin,
  al.idmagasinlib AS idmagasinlib,
  al.daty AS daty,
  al.remarque AS remarque,
  al.etat AS etat,
  al.idorigine AS idorigine,
  al.idclient AS idclient,
  al.compte AS compte,
  al.idvente AS idvente,
  al.idventelib AS idventelib,
  al.idmotif AS idmotif,
  al.idmotiflib AS idmotiflib,
  al.idcategorie AS idcategorie,
  al.idcategorielib AS idcategorielib,
  al.iddevise AS iddevise,
  al.tauxdechange AS tauxdechange,
  al.montantht AS montantht,
  al.montanttva AS montanttva,
  al.montantttc AS montantttc,
  al.montanthtar AS montanthtar,
  al.montanttvaar AS montanttvaar,
  al.montantttcar AS montantttcar,
  COALESCE(m.montant, 0) AS montantpaye,
  COALESCE(m.montant, 0) * COALESCE(al.tauxdechange, 0) AS montantpayear,
  COALESCE(al.montantreste, 0) AS montant_reste_facture,
  0 AS montant_avoirs_anterieurs,
  CASE
    WHEN COALESCE(al.montantreste, 0) = 0
    THEN 0
    ELSE COALESCE(al.montantreste, 0) - COALESCE(al.montantttcar, 0)
  END AS reste_calcule, /* Cas 1 : facture deja soldee -> chaque avoir = credit direct (exedent) */
  CASE
    WHEN COALESCE(al.montantreste, 0) = 0
    THEN COALESCE(al.montantttcar, 0)
    WHEN COALESCE(al.montantreste, 0) - COALESCE(al.montantttcar, 0) < 0
    THEN ABS(COALESCE(al.montantreste, 0) - COALESCE(al.montantttcar, 0))
    ELSE 0
  END AS excedent_ar, /* Excedent a rembourser ou a reporter */
  (
    CASE
      WHEN COALESCE(al.montantreste, 0) = 0
      THEN COALESCE(al.montantttcar, 0)
      WHEN COALESCE(al.montantreste, 0) - COALESCE(al.montantttcar, 0) < 0
      THEN ABS(COALESCE(al.montantreste, 0) - COALESCE(al.montantttcar, 0))
      ELSE 0
    END
  ) - COALESCE(m.montant, 0) AS resteapayer,
  (
    CASE
      WHEN COALESCE(al.montantreste, 0) = 0
      THEN COALESCE(al.montantttcar, 0)
      WHEN COALESCE(al.montantreste, 0) - COALESCE(al.montantttcar, 0) < 0
      THEN ABS(COALESCE(al.montantreste, 0) - COALESCE(al.montantttcar, 0))
      ELSE 0
    END
  ) - (
    COALESCE(m.montant, 0) * COALESCE(al.tauxdechange, 0)
  ) AS resteapayerar,
  al.clientlib AS clientlib,
  al.typeavoir AS typeavoir,
  al.numfact AS numfact
FROM public.avoirfclib AS al
LEFT JOIN (
  SELECT
    m.id1 AS idorigine,
    SUM(m.montant) AS montant,
    CAST('AR' AS TEXT) AS iddevise
  FROM public.liaisonpaiement AS m
  WHERE
    m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
  GROUP BY
    m.id1
) AS m
  ON al.id = m.idorigine;

-- Niveau 7 - vue 3 / 9 : CA_JOUR_DETAILS
-- Dependances nouvelles : CA_JOURNALIER_UNION_GP, V_JOURS_2016_NOW.
CREATE VIEW public.ca_jour_details (
    "daty", "jour", "semainemois", "mois", "annee", "jourlib", "montant", "idjoursemaine", "numerojoursemaine"
) AS
SELECT
  vj2n.daty AS daty,
  vj2n.jour AS jour,
  vj2n.semainemois AS semainemois,
  vj2n.mois AS mois,
  vj2n.annee AS annee,
  vj2n.jourlib AS jourlib,
  CAST(COALESCE(cj.montant, 0) AS DECIMAL(38, 2)) AS montant,
  js.id AS idjoursemaine,
  vj2n.numerojoursemaine AS numerojoursemaine
FROM public.v_jours_2016_now AS vj2n
LEFT JOIN public.ca_journalier_union_gp AS cj
  ON cj.daty = vj2n.daty
LEFT JOIN public.joursemaine AS js
  ON js.numsemaine = vj2n.semainemois
  AND js.numjour = CAST(vj2n.numerojoursemaine AS DECIMAL);

-- Niveau 7 - vue 4 / 9 : COMMANDECPL
-- Dependances nouvelles : COMMANDEMONTANT.
CREATE VIEW public.commandecpl (
    "id", "daty", "etat", "remarque", "designation", "modepaiement", "idclient", "reference", "iddevise", "idmagasin", "datebesoin", "idproforma", "modelivraison", "datelivraison", "lieulivraison", "fraislivraison", "idmagasinlib", "idclientlib", "etatlib", "modelivraisonlib", "modepaiementlib", "montantttc"
) AS
SELECT
  cmd.id AS id,
  cmd.daty AS daty,
  cmd.etat AS etat,
  cmd.remarque AS remarque,
  cmd.designation AS designation,
  cmd.modepaiement AS modepaiement,
  cmd.idclient AS idclient,
  cmd.reference AS reference,
  cmd.iddevise AS iddevise,
  cmd.idmagasin AS idmagasin,
  cmd.datebesoin AS datebesoin,
  cmd.idproforma AS idproforma,
  cmd.modelivraison AS modelivraison,
  cmd.datelivraison AS datelivraison,
  cmd.lieulivraison AS lieulivraison,
  cmd.fraislivraison AS fraislivraison,
  p.val AS idmagasinlib,
  cl.nom AS idclientlib,
  CASE
    WHEN cmd.etat = 1
    THEN 'Creee'
    WHEN cmd.etat = 11
    THEN 'Validee'
    WHEN cmd.etat = 0
    THEN 'Annulee'
    ELSE 'Inconnu'
  END AS etatlib,
  CASE
    WHEN cmd.modelivraison = 1
    THEN '<span style=color: green;>LIVRAISON</span>'
    WHEN cmd.modelivraison = 2
    THEN '<span style=color: green;>RECUPERATION</span>'
  END AS modelivraisonlib,
  mp.val AS modepaiementlib,
  cmm.montantttc AS montantttc
FROM public.commande AS cmd
LEFT JOIN public.magasin2 AS p
  ON p.id = cmd.idmagasin
LEFT JOIN public.client AS cl
  ON cl.id = cmd.idclient
LEFT JOIN public.modepaiement AS mp
  ON mp.id = cmd.modepaiement
LEFT JOIN public.commandemontant AS cmm
  ON cmm.id = cmd.id;

