-- Niveau 7 - vue 8 / 9 : LOG_PERSONNEL_FIN
-- Dependances nouvelles : DROITDECONGE_PARPERSONNE.
CREATE VIEW public.log_personnel_fin (
    "id", "permis_conduire", "chemin_permis", "remarque", "id_pers", "nom", "prenom", "date_naissance", "sexe", "numero_cin", "date_cin", "date_dupl_cin", "nationalite", "adresse", "fokotany", "acte_naissance", "direction", "service", "code_dr", "matricule", "idcategorie", "ctg", "indicegrade", "indice_fonctionnel", "statut", "categorieval", "ctgval", "numero_cnaps", "numero_ostie", "temporaire", "droit", "prie", "resteconge", "etat", "idpersonnel", "iddirection", "departementlib", "iddepartement", "idqualification", "qualificationlib", "idcategorie_paie"
) AS
SELECT
  l.id AS id,
  l.permis_conduire AS permis_conduire,
  l.chemin_permis AS chemin_permis,
  l.remarque AS remarque,
  l.id_pers AS id_pers,
  l.nom AS nom,
  l.prenom AS prenom,
  l.date_naissance AS date_naissance,
  sex.desce AS sexe,
  l.numero_cin AS numero_cin,
  l.date_cin AS date_cin,
  l.date_dupl_cin AS date_dupl_cin,
  l.nationalite AS nationalite,
  l.adresse AS adresse,
  l.fokotany AS fokotany,
  l.acte_naissance AS acte_naissance,
  d.val AS direction,
  s.code_service AS service,
  s.code_dr AS code_dr,
  CAST(paie.matricule AS TEXT) AS matricule,
  paie.idcategorie AS idcategorie,
  paie.ctg AS ctg,
  paie.indicegrade AS indicegrade,
  paie.indice_fonctionnel AS indice_fonctionnel,
  paie.statut AS statut,
  c.taux AS categorieval,
  CAST('''' AS TEXT) AS ctgval,
  paie.numero_cnaps AS numero_cnaps,
  paie.numero_ostie AS numero_ostie,
  CASE
    WHEN paie.temporaire = -1
    THEN 'Temporaire'
    WHEN paie.temporaire = 0
    THEN 'Permanent'
    WHEN paie.temporaire = 1
    THEN 'Cadre'
    ELSE NULL
  END AS temporaire,
  COALESCE(dr.conge, 0) AS droit,
  COALESCE(cg.conge, 0) AS prie,
  COALESCE(dr.conge, 0) - COALESCE(cg.conge, 0) AS resteconge,
  paie.etat AS etat,
  l.id AS idpersonnel,
  l.direction AS iddirection,
  dp.val AS departementlib,
  paie.iddepartement AS iddepartement,
  paie.idqualification AS idqualification,
  qp.val AS qualificationlib,
  paie.idcategorie_paie AS idcategorie_paie
FROM public.log_personnel AS l
LEFT JOIN public.log_service AS s
  ON l.service = s.id
LEFT JOIN public.paie_info_personnel AS paie
  ON paie.id = l.id
LEFT JOIN public.sexe AS sex
  ON l.sexe = sex.id
LEFT JOIN public.log_direction AS d
  ON d.id = l.direction
LEFT JOIN public.paie_categorie AS c
  ON c.id = paie.idcategorie
LEFT JOIN public.droitdeconge_parpersonne AS dr
  ON dr.idpersonnel = l.id
LEFT JOIN (
  SELECT
    congepris.idpersonnel,
    SUM(congepris.duree) AS conge
  FROM (
    SELECT
      demande.id,
      demande.idpersonnel,
      demande.idtypedemande,
      demande.titre,
      demande.horairenormal,
      demande.heuredepart,
      demande.heurearrive,
      demande.idtypeabsence,
      demande.motif,
      demande.numero,
      demande.desce,
      demande.etat,
      demande.daty,
      demande.duree,
      demande.datedepart,
      demande.dateretour,
      demande.observation,
      demande.remarque,
      demande.idremplacents,
      demande.reste_conge,
      demande.datefin
    FROM public.demande
    WHERE
      demande.etat = CAST(11 AS DECIMAL)
      AND CAST(demande.idtypeabsence AS TEXT) = CAST('TYP000004' AS TEXT)
  ) AS congepris
  GROUP BY
    congepris.idpersonnel
) AS cg
  ON cg.idpersonnel = l.id
LEFT JOIN public.departement AS dp
  ON dp.id = paie.iddepartement
LEFT JOIN public.qualification_paie AS qp
  ON qp.id = paie.idqualification;

-- Niveau 7 - vue 9 / 9 : LOG_PERSONNEL_GRAPHE
-- Dependances nouvelles : DROITDECONGE_PARPERSONNE.
CREATE VIEW public.log_personnel_graphe (
    "id", "permis_conduire", "chemin_permis", "remarque", "id_pers", "nom", "prenom", "date_naissance", "sexe", "numero_cin", "date_cin", "date_dupl_cin", "nationalite", "adresse", "fokotany", "acte_naissance", "direction", "service", "code_dr", "matricule", "idcategorie", "idcategorielib", "indicegrade", "indice_fonctionnel", "statut", "categorieval", "ctgval", "numero_cnaps", "numero_ostie", "temporaire", "droit", "prie", "resteconge", "etat", "idpersonnel", "iddirection", "departementlib", "iddepartement"
) AS
SELECT
  l.id AS id,
  l.permis_conduire AS permis_conduire,
  l.chemin_permis AS chemin_permis,
  l.remarque AS remarque,
  l.id_pers AS id_pers,
  l.nom AS nom,
  l.prenom AS prenom,
  l.date_naissance AS date_naissance,
  sex.desce AS sexe,
  l.numero_cin AS numero_cin,
  l.date_cin AS date_cin,
  l.date_dupl_cin AS date_dupl_cin,
  l.nationalite AS nationalite,
  l.adresse AS adresse,
  l.fokotany AS fokotany,
  l.acte_naissance AS acte_naissance,
  d.val AS direction,
  s.code_service AS service,
  s.code_dr AS code_dr,
  CAST(paie.matricule AS TEXT) AS matricule,
  paie.idcategorie_paie AS idcategorie,
  ctp.val AS idcategorielib,
  paie.indicegrade AS indicegrade,
  paie.indice_fonctionnel AS indice_fonctionnel,
  paie.statut AS statut,
  c.taux AS categorieval,
  CAST('''' AS TEXT) AS ctgval,
  paie.numero_cnaps AS numero_cnaps,
  paie.numero_ostie AS numero_ostie,
  CASE
    WHEN paie.temporaire = -1
    THEN 'Temporaire'
    WHEN paie.temporaire = 0
    THEN 'Permanent'
    WHEN paie.temporaire = 1
    THEN 'Cadre'
    ELSE NULL
  END AS temporaire,
  COALESCE(dr.conge, 0) AS droit,
  COALESCE(cg.conge, 0) AS prie,
  COALESCE(dr.conge, 0) - COALESCE(cg.conge, 0) AS resteconge,
  paie.etat AS etat,
  l.id AS idpersonnel,
  l.direction AS iddirection,
  dp.val AS departementlib,
  paie.iddepartement AS iddepartement
FROM public.log_personnel AS l
LEFT JOIN public.log_service AS s
  ON l.service = s.id
LEFT JOIN public.paie_info_personnel AS paie
  ON paie.id = l.id
LEFT JOIN public.sexe AS sex
  ON l.sexe = sex.id
LEFT JOIN public.log_direction AS d
  ON d.id = l.direction
LEFT JOIN public.paie_categorie AS c
  ON c.id = paie.idcategorie
LEFT JOIN public.droitdeconge_parpersonne AS dr
  ON dr.idpersonnel = l.id
LEFT JOIN (
  SELECT
    congepris.idpersonnel,
    SUM(congepris.duree) AS conge
  FROM (
    SELECT
      demande.id,
      demande.idpersonnel,
      demande.idtypedemande,
      demande.titre,
      demande.horairenormal,
      demande.heuredepart,
      demande.heurearrive,
      demande.idtypeabsence,
      demande.motif,
      demande.numero,
      demande.desce,
      demande.etat,
      demande.daty,
      demande.duree,
      demande.datedepart,
      demande.dateretour,
      demande.observation,
      demande.remarque,
      demande.idremplacents,
      demande.reste_conge,
      demande.datefin
    FROM public.demande
    WHERE
      demande.etat = CAST(11 AS DECIMAL)
      AND CAST(demande.idtypeabsence AS TEXT) = CAST('TYP000004' AS TEXT)
  ) AS congepris
  GROUP BY
    congepris.idpersonnel
) AS cg
  ON cg.idpersonnel = l.id
LEFT JOIN public.departement AS dp
  ON dp.id = paie.iddepartement
LEFT JOIN public.categorie_paie AS ctp
  ON ctp.id = paie.idcategorie_paie;

COMMIT;

-- Verification du lot prepare (les vues bloquees ne sont pas comptees).
SELECT 7 AS niveau, count(*) AS vues_presentes, 9 AS vues_attendues
FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relkind='v' AND c.relname=ANY(ARRAY[
        'avoirfclib_cpl', 'avoirfclib_cpl_v2', 'ca_jour_details', 'commandecpl',
        'conge_droit_libcree', 'conge_droit_libtous', 'conge_droit_libvise', 'log_personnel_fin',
        'log_personnel_graphe'
    ]::text[]);

-- VUES NON CREEES : erreurs deja presentes dans Oracle, sans correction metier inventee.
-- RAPPROCHEMENT_COMPLET : 
-- RAPPROCHEMENT_COMPLETOFFILLE : 
-- STOCKETDEPOFFABTHECATGROUPE : 
-- STOCKETDEPOFFILLETHECATGROUPE : 

-- ============================================================================
-- NIVEAU 8 / 13 - 10 vues du plan - 10 creations ; 0 blocages source
-- ============================================================================
-- Executer apres les niveaux precedents prepares, dans leur ordre.
BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL search_path = pg_catalog, public;
SET LOCAL lock_timeout = '5s';

DO $migration_guard$
DECLARE
    problemes text;
BEGIN
    IF current_database() <> 'aigledor0110' THEN
        RAISE EXCEPTION 'Base incorrecte : % (attendu : aigledor0110)', current_database();
    END IF;
    IF current_setting('server_version_num')::integer NOT BETWEEN 90500 AND 90599 THEN
        RAISE EXCEPTION 'Script prepare pour PostgreSQL 9.5 : version %', version();
    END IF;
    SELECT string_agg(c.relname, ', ' ORDER BY c.relname) INTO problemes
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='public' AND c.relname=ANY(ARRAY[
        'avoirfclib_cpl_cree', 'avoirfclib_cpl_non_cree', 'avoirfclib_cpl_v2_visee', 'avoirfclib_cpl_visee',
        'categoriequalification_lib', 'effectif_log_personnel', 'employe_complet_pdf', 'log_personnel_v',
        'mouvementcaissecpl_v_d_avoir', 'vue_contrat_lib'
    ]::text[]);
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Objets deja presents, aucune vue ne sera remplacee : %', problemes;
    END IF;
    SELECT string_agg(r.nom, ', ' ORDER BY r.nom) INTO problemes
    FROM unnest(ARRAY[
        'public.avoirfclib_cpl', 'public.avoirfclib_cpl_v2', 'public.caisse', 'public.categorie_paie',
        'public.categorie_qualification', 'public.liaisonpaiement', 'public.liaisonpaiementmvtcaissegrp', 'public.log_direction',
        'public.log_personnel', 'public.log_personnel_fin', 'public.log_personnel_graphe', 'public.log_personnel_non_valide',
        'public.log_service', 'public.modepaiement', 'public.mouvementcaisse', 'public.paie_avancement',
        'public.paie_fonction', 'public.paie_info_personnel', 'public.point', 'public.qualification_paie',
        'public.tiers', 'public.trs_banques_agences', 'public.type_contrat', 'public.vente_details'
    ]::text[]) AS r(nom)
