-- Niveau 8 - vue 5 / 10 : CATEGORIEQUALIFICATION_LIB
-- Dependances nouvelles : LOG_PERSONNEL_FIN.
CREATE VIEW public.categoriequalification_lib (
    "id", "matricule", "nompersonnel", "montant", "categorielib", "qualificationlib"
) AS
SELECT
  log.id AS id,
  log.matricule AS matricule,
  NULLIF(CONCAT(log.nom, ' ', log.prenom), '') AS nompersonnel,
  c.montant AS montant,
  cp.val AS categorielib,
  qp.val AS qualificationlib
FROM public.log_personnel_fin AS log
LEFT JOIN public.categorie_qualification AS c
  ON c.idqualification = log.idqualification
  AND c.idcategorie = log.idcategorie_paie
  AND (
    (
      c.remarque IS NULL
    ) OR (
      c.remarque = log.id
    )
  )
  AND c.etat = 1
LEFT JOIN public.categorie_paie AS cp
  ON cp.id = c.idcategorie
LEFT JOIN public.qualification_paie AS qp
  ON qp.id = c.idqualification;

-- Niveau 8 - vue 6 / 10 : EFFECTIF_LOG_PERSONNEL
-- Dependances nouvelles : LOG_PERSONNEL_GRAPHE.
CREATE VIEW public.effectif_log_personnel (
    "sexe", "nombre", "idcategorie", "idcategorielib", "iddepartement", "departementlib"
) AS
SELECT
  CASE
    WHEN log_personnel_graphe.sexe = 'Masculin'
    THEN 'Masculin'
    WHEN log_personnel_graphe.sexe = 'Feminin'
    THEN 'Feminin'
    ELSE 'Non defini'
  END AS sexe,
  COUNT(*) AS nombre,
  log_personnel_graphe.idcategorie AS idcategorie,
  log_personnel_graphe.idcategorielib AS idcategorielib,
  log_personnel_graphe.iddepartement AS iddepartement,
  log_personnel_graphe.departementlib AS departementlib
FROM public.log_personnel_graphe AS log_personnel_graphe
GROUP BY
  CASE
    WHEN log_personnel_graphe.sexe = 'Masculin'
    THEN 'Masculin'
    WHEN log_personnel_graphe.sexe = 'Feminin'
    THEN 'Feminin'
    ELSE 'Non defini'
  END,
  log_personnel_graphe.idcategorie,
  log_personnel_graphe.idcategorielib,
  log_personnel_graphe.iddepartement,
  log_personnel_graphe.departementlib;

-- Niveau 8 - vue 7 / 10 : EMPLOYE_COMPLET_PDF
-- Dependances nouvelles : LOG_PERSONNEL_FIN.
CREATE VIEW public.employe_complet_pdf (
    "id", "nom", "prenom", "id_pers", "initiale", "matricule", "date_naissance", "lieu_naissance_commune", "sexe", "numero_cin", "date_cin", "date_dupl_cin", "lieu_delivrance_cin", "adresse", "fokotany", "nationalite", "acte_naissance", "situation_matrimonial", "idconjoint", "direction", "service", "idfonction", "ctg", "idcategorie", "classee", "indicegrade", "indice_fonctionnel", "matricule_patron", "statut", "mode_paiement", "code_agence_banque", "banque_numero_compte", "banque_compte_cle", "permis_conduire", "remarque", "chemin_permis", "cturgence_nom_prenom", "cturgence_telephone1", "cturgence_telephone2", "cturgence_telephone3", "dateembauche", "datesaisie", "code_dr", "banque_code", "echelon", "etat", "vehiculee", "date_dernierpromo", "droit_hs", "heurejournalier", "heurehebdomadaire", "heuremensuel", "numero_cnaps", "numero_ostie", "temporaire", "nbenfant", "indesirable", "duree", "telephone", "mail", "idcategorie_paie", "idqualification", "discipline", "formation", "anneeexperience", "montant", "conger"
) AS
SELECT
  logp.id AS id,
  logp.nom AS nom,
  logp.prenom AS prenom,
  logp.id_pers AS id_pers,
  paie.initiale AS initiale,
  paie.matricule AS matricule,
  logp.date_naissance AS date_naissance,
  paie.lieu_naissance_commune AS lieu_naissance_commune,
  logp.sexe AS sexe,
  logp.numero_cin AS numero_cin,
  logp.date_cin AS date_cin,
  logp.date_dupl_cin AS date_dupl_cin,
  paie.lieu_delivrance_cin AS lieu_delivrance_cin,
  paie.adresse_ligne1 AS adresse,
  logp.fokotany AS fokotany,
  logp.nationalite AS nationalite,
  logp.acte_naissance AS acte_naissance,
  paie.situation_matrimonial AS situation_matrimonial,
  paie.idconjoint AS idconjoint,
  logp.direction AS direction,
  logp.service AS service,
  fonct.desce AS idfonction,
  paie.ctg AS ctg,
  paie.idcategorie AS idcategorie,
  paie.classee AS classee,
  paie.indicegrade AS indicegrade,
  paie.indice_fonctionnel AS indice_fonctionnel,
  paie.matricule_patron AS matricule_patron,
  paie.statut AS statut,
  paie.mode_paiement AS mode_paiement,
  paie.code_agence_banque AS code_agence_banque,
  paie.banque_numero_compte AS banque_numero_compte,
  paie.banque_compte_cle AS banque_compte_cle,
  logp.permis_conduire AS permis_conduire,
  logp.remarque AS remarque,
  logp.chemin_permis AS chemin_permis,
  paie.cturgence_nom_prenom AS cturgence_nom_prenom,
  paie.cturgence_telephone1 AS cturgence_telephone1,
  paie.cturgence_telephone2 AS cturgence_telephone2,
  paie.cturgence_telephone3 AS cturgence_telephone3,
  paie.dateembauche AS dateembauche,
  paie.datesaisie AS datesaisie,
  ld.val AS code_dr,
  trs.val AS banque_code,
  paie.echelon AS echelon,
  paie.etat AS etat,
  paie.vehiculee AS vehiculee,
  tab.date_dernierpromo AS date_dernierpromo,
  paie.droit_hs AS droit_hs,
  paie.heurejournalier AS heurejournalier,
  paie.heurehebdomadaire AS heurehebdomadaire,
  paie.heuremensuel AS heuremensuel,
  paie.numero_cnaps AS numero_cnaps,
  paie.numero_ostie AS numero_ostie,
  paie.temporaire AS temporaire,
  paie.nbenfant AS nbenfant,
  paie.indesirable AS indesirable,
  cp.essaie AS duree,
  paie.telephone AS telephone,
  paie.mail AS mail,
  cp.val AS idcategorie_paie,
  qp.val AS idqualification,
  paie.discipline AS discipline,
  paie.formation AS formation,
  paie.anneeexperience AS anneeexperience,
  cq.montant AS montant,
  cd.resteconge AS conger
FROM public.log_personnel AS logp
LEFT JOIN (
  SELECT
    paie_avancement.id_logpers AS id_logpers,
    MAX(paie_avancement.datedecision) AS date_dernierpromo
  FROM public.paie_avancement AS paie_avancement
  GROUP BY
    paie_avancement.id_logpers
) AS tab
  ON logp.id = tab.id_logpers
LEFT JOIN public.paie_info_personnel AS paie
  ON logp.id = paie.id
LEFT JOIN public.log_service AS serv
  ON serv.id = logp.service
LEFT JOIN public.trs_banques_agences AS trs
  ON paie.code_agence_banque = trs.id
LEFT JOIN public.paie_fonction AS fonct
  ON fonct.id = paie.idfonction
LEFT JOIN public.categorie_paie AS cp
  ON cp.id = paie.idcategorie_paie
LEFT JOIN public.qualification_paie AS qp
  ON qp.id = paie.idqualification
LEFT JOIN public.categorie_qualification AS cq
  ON cq.idcategorie = paie.idcategorie_paie
  AND cq.idqualification = paie.idqualification
  AND cq.remarque = logp.id
  AND cq.etat = 1
LEFT JOIN public.log_direction AS ld
  ON ld.id = logp.direction
LEFT JOIN public.log_personnel_fin AS cd
  ON cd.id = logp.id;

-- Niveau 8 - vue 8 / 10 : LOG_PERSONNEL_V
-- Dependances nouvelles : LOG_PERSONNEL_FIN.
CREATE VIEW public.log_personnel_v (
    "id", "permis_conduire", "chemin_permis", "remarque", "id_pers", "nom", "prenom", "date_naissance", "sexe", "numero_cin", "date_cin", "date_dupl_cin", "nationalite", "adresse", "fokotany", "acte_naissance", "direction", "service", "code_dr", "matricule", "idcategorie", "ctg", "indicegrade", "indice_fonctionnel", "statut", "categorieval", "ctgval", "numero_cnaps", "numero_ostie", "temporaire", "resteconge", "iddirection"
) AS
SELECT
  log_personnel_fin.id AS id,
  log_personnel_fin.permis_conduire AS permis_conduire,
  log_personnel_fin.chemin_permis AS chemin_permis,
  log_personnel_fin.remarque AS remarque,
  log_personnel_fin.id_pers AS id_pers,
  log_personnel_fin.nom AS nom,
  log_personnel_fin.prenom AS prenom,
  log_personnel_fin.date_naissance AS date_naissance,
  log_personnel_fin.sexe AS sexe,
  log_personnel_fin.numero_cin AS numero_cin,
  log_personnel_fin.date_cin AS date_cin,
  log_personnel_fin.date_dupl_cin AS date_dupl_cin,
  log_personnel_fin.nationalite AS nationalite,
  log_personnel_fin.adresse AS adresse,
  log_personnel_fin.fokotany AS fokotany,
  log_personnel_fin.acte_naissance AS acte_naissance,
  log_personnel_fin.direction AS direction,
  log_personnel_fin.service AS service,
  log_personnel_fin.code_dr AS code_dr,
  log_personnel_fin.matricule AS matricule,
  log_personnel_fin.idcategorie AS idcategorie,
  log_personnel_fin.ctg AS ctg,
  log_personnel_fin.indicegrade AS indicegrade,
  log_personnel_fin.indice_fonctionnel AS indice_fonctionnel,
  log_personnel_fin.statut AS statut,
  log_personnel_fin.categorieval AS categorieval,
  log_personnel_fin.ctgval AS ctgval,
