    log_personnel_fin.id IN (
      SELECT
        log_personnel_non_valide.idlogpers AS idlogpers
      FROM public.log_personnel_non_valide AS log_personnel_non_valide
      WHERE
        log_personnel_non_valide.etat >= 11
    )
  );

-- Niveau 8 - vue 9 / 10 : MOUVEMENTCAISSECPL_V_D_AVOIR
-- Dependances nouvelles : AVOIRFCLIB_CPL.
CREATE VIEW public.mouvementcaissecpl_v_d_avoir (
    "id", "designation", "idcaisse", "idcaisselib", "idventedetail", "idvirement", "debit", "credit", "montantimpute", "daty", "etat", "etatlib", "idvente", "idorigine", "idtiers", "tiers", "idpaiement", "referencepaiement", "designationpaiement"
) AS
SELECT
  m.id AS id,
  m.designation AS designation,
  m.idcaisse AS idcaisse,
  m.idcaisselib AS idcaisselib,
  m.idventedetail AS idventedetail,
  m.idvirement AS idvirement,
  m.debit AS debit,
  m.credit AS credit,
  lp.montant AS montantimpute,
  m.daty AS daty,
  m.etat AS etat,
  m.etatlib AS etatlib,
  m.idvente AS idvente,
  lp.id2 AS idorigine,
  m.idtiers AS idtiers,
  m.tiers AS tiers,
  lp.id1 AS idpaiement,
  m.reference AS referencepaiement,
  m.designation AS designationpaiement
FROM public.liaisonpaiement AS lp
LEFT JOIN (
  SELECT
    m.id,
    m.designation,
    m.idcaisse,
    c.val AS idcaisselib,
    m.idventedetail,
    m.idvirement,
    m.debit,
    m.credit,
    CAST(CASE
      WHEN m.credit > CAST(0 AS DECIMAL)
      THEN COALESCE(m.credit, CAST(0 AS DECIMAL)) - COALESCE(l.montant, CAST(0 AS DECIMAL))
      ELSE CAST(0 AS DECIMAL)
    END AS DECIMAL(36, 5)) AS soldecredit,
    CAST(CASE
      WHEN m.debit > CAST(0 AS DECIMAL)
      THEN COALESCE(m.debit, CAST(0 AS DECIMAL)) - COALESCE(l.montant, CAST(0 AS DECIMAL))
      ELSE CAST(0 AS DECIMAL)
    END AS DECIMAL(36, 5)) AS soldedebit,
    m.daty,
    m.etat,
    CASE
      WHEN m.etat = CAST(0 AS DECIMAL)
      THEN CAST('ANNULEE' AS TEXT)
      WHEN m.etat = CAST(1 AS DECIMAL)
      THEN CAST('CREEE' AS TEXT)
      WHEN m.etat = CAST(11 AS DECIMAL)
      THEN CAST('VALIDEE' AS TEXT)
      WHEN m.etat = CAST(8 AS DECIMAL)
      THEN CAST('A COMPTABILISER' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS etatlib,
    vd.idvente,
    m.idorigine,
    m.idtiers,
    t.nom AS tiers,
    m.idprevision,
    m.idop,
    m.taux,
    m.compte,
    m.iddevise,
    m.idtraite,
    mp.val AS idmodepaiementlib,
    m.idmvtcaissemere,
    m.reference,
    m.datycomptabilisation,
    m.updated_at,
    m.heure,
    m.idreport,
    point.id AS idpoint,
    point.val AS idpointlib,
    NULLIF(
      CONCAT(
        (
          NULLIF(
            CONCAT(
              (
                NULLIF(
                  CONCAT(
                    (
                      NULLIF(
                        CONCAT(
                          (
                            NULLIF(
                              CONCAT(
                                (
                                  NULLIF(
                                    CONCAT(
                                      (
                                        NULLIF(
                                          CONCAT(
                                            (
                                              NULLIF(
                                                CONCAT(
                                                  (
                                                    NULLIF(
                                                      CONCAT((
                                                        NULLIF(CONCAT(CAST(m.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                      ), m.daty),
                                                      ''
                                                    )
                                                  ),
                                                  CAST(NULL AS TEXT)
                                                ),
                                                ''
                                              )
                                            ),
                                            CAST(m.designation AS TEXT)
                                          ),
                                          ''
                                        )
                                      ),
                                      CAST(NULL AS TEXT)
                                    ),
                                    ''
                                  )
                                ),
                                CAST(t.nom AS TEXT)
                              ),
                              ''
                            )
                          ),
                          CAST(NULL AS TEXT)
                        ),
                        ''
                      )
                    ),
                    CAST(m.idcaisse AS TEXT)
                  ),
                  ''
                )
              ),
              CAST(NULL AS TEXT)
            ),
            ''
          )
        ),
        CAST(c.val AS TEXT)
      ),
      ''
    ) AS motsclesss
  FROM public.mouvementcaisse AS m
  LEFT JOIN public.caisse AS c
    ON CAST(c.id AS TEXT) = CAST(m.idcaisse AS TEXT)
  LEFT JOIN public.vente_details AS vd
    ON CAST(vd.id AS TEXT) = CAST(m.idventedetail AS TEXT)
  LEFT JOIN public.tiers AS t
    ON CAST(t.id AS TEXT) = CAST(m.idtiers AS TEXT)
  LEFT JOIN public.liaisonpaiementmvtcaissegrp AS l
    ON CAST(l.idmvtcaisse AS TEXT) = CAST(m.id AS TEXT)
  LEFT JOIN public.modepaiement AS mp
    ON CAST(m.idmodepaiement AS TEXT) = CAST(mp.id AS TEXT)
  LEFT JOIN public.point AS point
    ON CAST(point.id AS TEXT) = CAST(c.idpoint AS TEXT)
) AS m
  ON m.id = lp.id1
WHERE
  m.etat > 7
UNION ALL
SELECT
  m.id AS id,
  m.designation AS designation,
  CAST(NULL AS TEXT) AS idcaisse,
  CAST(NULL AS TEXT) AS idcaisselib,
  CAST(NULL AS TEXT) AS idventedetail,
  CAST(NULL AS TEXT) AS idvirement,
  0 AS debit,
  m.montantttcar AS credit,
  lp.montant AS montantimpute,
  m.daty AS daty,
  m.etat AS etat,
  CAST(NULL AS TEXT) AS etatlib,
  m.idvente AS idvente,
  lp.id2 AS idorigine,
  m.idclient AS idtiers,
  m.clientlib AS tiers,
  lp.id1 AS idpaiement,
  m.id AS referencepaiement,
  CAST('NOTE DE CREDIT' AS TEXT) AS designationpaiement
FROM public.liaisonpaiement AS lp
LEFT JOIN public.avoirfclib_cpl AS m
  ON m.id = lp.id1
WHERE
  m.etat > 7;

-- Niveau 8 - vue 10 / 10 : VUE_CONTRAT_LIB
-- Dependances nouvelles : LOG_PERSONNEL_FIN.
CREATE VIEW public.vue_contrat_lib (
    "id", "matricule", "nom", "prenom", "sexe", "dateembauche", "periode", "date_fin_contrat", "etat", "type_contrat"
) AS
SELECT
  lpf.idpersonnel AS id,
  lpf.matricule AS matricule,
  lpf.nom AS nom,
  lpf.prenom AS prenom,
  lpf.sexe AS sexe,
  pip.dateembauche AS dateembauche,
  pip.indesirable AS periode,
  CASE
    WHEN pip.indesirable > 0
    THEN pip.dateembauche + INTERVAL '1 MONTH' * pip.indesirable
    ELSE NULL
  END AS date_fin_contrat,
  lpf.etat AS etat,
  tc.val AS type_contrat
FROM public.log_personnel_fin AS lpf
JOIN public.paie_info_personnel AS pip
  ON pip.id = lpf.idpersonnel
JOIN public.type_contrat AS tc
  ON tc.id = pip.typecontrat;

COMMIT;

-- Verification du lot prepare (les vues bloquees ne sont pas comptees).
SELECT 8 AS niveau, count(*) AS vues_presentes, 10 AS vues_attendues
FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relkind='v' AND c.relname=ANY(ARRAY[
        'avoirfclib_cpl_cree', 'avoirfclib_cpl_non_cree', 'avoirfclib_cpl_v2_visee', 'avoirfclib_cpl_visee',
        'categoriequalification_lib', 'effectif_log_personnel', 'employe_complet_pdf', 'log_personnel_v',
        'mouvementcaissecpl_v_d_avoir', 'vue_contrat_lib'
    ]::text[]);

-- ============================================================================
-- NIVEAU 9 / 13 - 8 vues du plan - 8 creations ; 0 blocages source
-- ============================================================================
-- Executer apres les niveaux precedents prepares, dans leur ordre.
BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL search_path = pg_catalog, public;
SET LOCAL lock_timeout = '5s';

DO $migration_guard$
DECLARE
    problemes text;
BEGIN
    IF current_database() <> 'aigledor0110' THEN
        RAISE EXCEPTION 'Base incorrecte : % (attendu : aigledor0110)', current_database();
    END IF;
    IF current_setting('server_version_num')::integer NOT BETWEEN 90500 AND 90599 THEN
        RAISE EXCEPTION 'Script prepare pour PostgreSQL 9.5 : version %', version();
    END IF;
    SELECT string_agg(c.relname, ', ' ORDER BY c.relname) INTO problemes
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='public' AND c.relname=ANY(ARRAY[
        'avoirfclib_cpl_grp', 'avoirfclib_cpl_v2_grp', 'log_personnel_v2', 'log_personnel_v_frais_medicaux',
        'mouvementcaisse_detail', 'nb_pers_valide', 'solde_conge_pers', 'solde_formation_syndicale'
    ]::text[]);
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Objets deja presents, aucune vue ne sera remplacee : %', problemes;
    END IF;
    SELECT string_agg(r.nom, ', ' ORDER BY r.nom) INTO problemes
    FROM unnest(ARRAY[
        'public.as_bondelivraison_client', 'public.as_ingredients', 'public.avoirfc', 'public.avoirfcfille_grp',
        'public.avoirfclib_cpl_v2_visee', 'public.avoirfclib_cpl_visee', 'public.categorie_paie', 'public.client',
        'public.compta_ecriture', 'public.departement', 'public.liaisonpaiement', 'public.liaisonpaiementtotal',
        'public.log_personnel_v', 'public.modepaiement', 'public.mouvementabsence', 'public.mouvementcaissecpl_v_d_avoir',
        'public.paie_info_personnel', 'public.personne_gain_sortie_reste', 'public.point', 'public.qualification_paie',
        'public.referencefacture', 'public.vente', 'public.vente_details', 'public.vente_reste',
        'public.zone'
    ]::text[]) AS r(nom)
    WHERE pg_catalog.to_regclass(r.nom::cstring) IS NULL;
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Prerequis absents : %', problemes;
    END IF;
END;
$migration_guard$ LANGUAGE plpgsql;

-- Niveau 9 - vue 1 / 8 : AVOIRFCLIB_CPL_GRP
-- Dependances nouvelles : AVOIRFCLIB_CPL_VISEE.
CREATE VIEW public.avoirfclib_cpl_grp (
    "idvente", "iddevise", "montantht_avr", "montanttva_avr", "montantttc_avr", "montanthtar_avr", "montanttvaar_avr", "montantttcar_avr", "montantpaye", "montantpayear", "resteapayer_avr", "resteapayerar_avr", "imputeefact", "imputeefactar"
) AS
SELECT
  al.idvente AS idvente,
  al.iddevise AS iddevise,
  SUM(al.montantht) AS montantht_avr,
  SUM(al.montanttva) AS montanttva_avr,
  SUM(al.montantttc) AS montantttc_avr,
  SUM(al.montanthtar) AS montanthtar_avr,
  SUM(al.montanttvaar) AS montanttvaar_avr,
  SUM(al.montantttcar) AS montantttcar_avr,
  SUM(al.montantpaye) AS montantpaye,
  SUM(al.montantpayear) AS montantpayear,
  SUM(al.resteapayer) AS resteapayer_avr,
  SUM(al.resteapayerar) AS resteapayerar_avr,
  SUM(al.imputeefact) AS imputeefact,
  SUM(al.imputeefactar) AS imputeefactar
FROM public.avoirfclib_cpl_visee AS al
GROUP BY
  al.idvente,
  al.iddevise;

-- Niveau 9 - vue 2 / 8 : AVOIRFCLIB_CPL_V2_GRP
-- Dependances nouvelles : AVOIRFCLIB_CPL_V2_VISEE.
CREATE VIEW public.avoirfclib_cpl_v2_grp (
    "idvente", "iddevise", "montantht_avr", "montanttva_avr", "montantttc_avr", "montanthtar_avr", "montanttvaar_avr", "montantttcar_avr", "montantpaye", "montantpayear", "resteapayer_avr", "resteapayerar_avr", "imputeefact", "imputeefactar"
) AS
SELECT
  al.idvente AS idvente,
