  SUM(al.montantht) AS montantht_avr,
  SUM(al.montanttva) AS montanttva_avr,
  SUM(al.montantttc) AS montantttc_avr,
  SUM(al.montanthtar) AS montanthtar_avr,
  SUM(al.montanttvaar) AS montanttvaar_avr,
  SUM(al.montantttcar) AS montantttcar_avr,
  SUM(al.montantpaye) AS montantpaye,
  SUM(al.montantpayear) AS montantpayear,
  SUM(al.resteapayer) AS resteapayer_avr,
