-- Niveau 9 - vue 3 / 8 : LOG_PERSONNEL_V2
-- Dependances nouvelles : LOG_PERSONNEL_V.
CREATE VIEW public.log_personnel_v2 (
    "id", "permis_conduire", "chemin_permis", "remarque", "id_pers", "nom", "prenom", "date_naissance", "sexe", "numero_cin", "date_cin", "date_dupl_cin", "nationalite", "adresse", "fokotany", "acte_naissance", "direction", "service", "code_dr", "matricule", "idcategorie", "ctg", "indicegrade", "indice_fonctionnel", "statut", "categorieval", "ctgval", "numero_cnaps", "numero_ostie", "temporaire", "resteconge", "categorie", "qualification", "iddirection", "iddepartement", "idcategorie_paie"
) AS
SELECT
  lpv.id AS id,
  lpv.permis_conduire AS permis_conduire,
  lpv.chemin_permis AS chemin_permis,
  lpv.remarque AS remarque,
  lpv.id_pers AS id_pers,
  lpv.nom AS nom,
  lpv.prenom AS prenom,
  lpv.date_naissance AS date_naissance,
  lpv.sexe AS sexe,
  lpv.numero_cin AS numero_cin,
  lpv.date_cin AS date_cin,
  lpv.date_dupl_cin AS date_dupl_cin,
  lpv.nationalite AS nationalite,
  lpv.adresse AS adresse,
  lpv.fokotany AS fokotany,
  lpv.acte_naissance AS acte_naissance,
  lpv.direction AS direction,
  lpv.service AS service,
  lpv.code_dr AS code_dr,
  lpv.matricule AS matricule,
  lpv.idcategorie AS idcategorie,
  lpv.ctg AS ctg,
  lpv.indicegrade AS indicegrade,
  lpv.indice_fonctionnel AS indice_fonctionnel,
  lpv.statut AS statut,
  lpv.categorieval AS categorieval,
  lpv.ctgval AS ctgval,
  lpv.numero_cnaps AS numero_cnaps,
  lpv.numero_ostie AS numero_ostie,
  lpv.temporaire AS temporaire,
  lpv.resteconge AS resteconge,
  cpl.val AS categorie,
  qp.val AS qualification,
  lpv.iddirection AS iddirection,
  pinfo.iddepartement AS iddepartement,
  pinfo.idcategorie_paie AS idcategorie_paie
FROM public.log_personnel_v AS lpv
LEFT JOIN public.paie_info_personnel AS pinfo
  ON pinfo.id = lpv.id
LEFT JOIN (
  SELECT
    cp.id,
    cp.val,
    cp.desce,
    cp.montant,
    cp.remarque,
    CASE
      WHEN CAST(cp.droit_heure_sup AS TEXT) = CAST('o' AS TEXT)
      THEN CAST('OUI' AS TEXT)
      WHEN CAST(cp.droit_heure_sup AS TEXT) = CAST('n' AS TEXT)
      THEN CAST('NON' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS droit_heure_sup,
    cp.essaie
  FROM public.categorie_paie AS cp
) AS cpl
  ON cpl.id = pinfo.idcategorie_paie
LEFT JOIN public.qualification_paie AS qp
  ON qp.id = pinfo.idqualification;

-- Niveau 9 - vue 4 / 8 : LOG_PERSONNEL_V_FRAIS_MEDICAUX
-- Dependances nouvelles : LOG_PERSONNEL_V, PERSONNE_GAIN_SORTIE_RESTE.
CREATE VIEW public.log_personnel_v_frais_medicaux (
    "id", "permis_conduire", "chemin_permis", "remarque", "id_pers", "nom", "prenom", "date_naissance", "sexe", "numero_cin", "date_cin", "date_dupl_cin", "nationalite", "adresse", "fokotany", "acte_naissance", "direction", "service", "code_dr", "matricule", "idcategorie", "ctg", "indicegrade", "indice_fonctionnel", "statut", "categorieval", "ctgval", "numero_cnaps", "numero_ostie", "temporaire", "resteconge", "reste_frais_medicaux"
) AS
SELECT
  lp.id AS id,
  lp.permis_conduire AS permis_conduire,
  lp.chemin_permis AS chemin_permis,
  lp.remarque AS remarque,
  lp.id_pers AS id_pers,
  lp.nom AS nom,
  lp.prenom AS prenom,
  lp.date_naissance AS date_naissance,
  lp.sexe AS sexe,
  lp.numero_cin AS numero_cin,
  lp.date_cin AS date_cin,
  lp.date_dupl_cin AS date_dupl_cin,
  lp.nationalite AS nationalite,
  lp.adresse AS adresse,
  lp.fokotany AS fokotany,
  lp.acte_naissance AS acte_naissance,
  lp.direction AS direction,
  lp.service AS service,
  lp.code_dr AS code_dr,
  lp.matricule AS matricule,
  lp.idcategorie AS idcategorie,
  lp.ctg AS ctg,
  lp.indicegrade AS indicegrade,
  lp.indice_fonctionnel AS indice_fonctionnel,
  lp.statut AS statut,
  lp.categorieval AS categorieval,
  lp.ctgval AS ctgval,
  lp.numero_cnaps AS numero_cnaps,
  lp.numero_ostie AS numero_ostie,
  lp.temporaire AS temporaire,
  lp.resteconge AS resteconge,
  COALESCE(p.reste, 0) AS reste_frais_medicaux
FROM public.log_personnel_v AS lp
LEFT JOIN public.personne_gain_sortie_reste AS p
  ON lp.id = p.id;

-- Niveau 9 - vue 5 / 8 : MOUVEMENTCAISSE_DETAIL
-- Dependances nouvelles : MOUVEMENTCAISSECPL_V_D_AVOIR.
CREATE VIEW public.mouvementcaisse_detail (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "etatlib", "montanttotal", "iddevise", "idclient", "idclientlib", "montanttva", "montantttc", "montantttcar", "montantpaye", "montantreste", "avoir", "tauxdechange", "montantrevient", "margebrute", "idreservation", "idobjet", "montantimpute", "referencepaiement", "idpaiement", "designationpaiement", "numerofacture", "updated_at"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  v.idmagasinlib AS idmagasinlib,
  v.daty AS daty,
  v.remarque AS remarque,
  v.etat AS etat,
  v.etatlib AS etatlib,
  v.montanttotal AS montanttotal,
  v.iddevise AS iddevise,
  v.idclient AS idclient,
  v.idclientlib AS idclientlib,
  v.montanttva AS montanttva,
  v.montantttc AS montantttc,
  v.montantttcar AS montantttcar,
  v.montantpaye AS montantpaye,
  v.montantreste AS montantreste,
  v.avoir AS avoir,
  v.tauxdechange AS tauxdechange,
  v.montantrevient AS montantrevient,
  v.margebrute AS margebrute,
  v.idreservation AS idreservation,
  mv.id AS idobjet,
  mv.montantimpute AS montantimpute,
  mv.referencepaiement AS referencepaiement,
  mv.idpaiement AS idpaiement,
  mv.designationpaiement AS designationpaiement,
  v.numerofacture AS numerofacture,
  v.updated_at AS updated_at
FROM (
  SELECT
    v.id,
    v.designation,
    v.idmagasin,
    m.val AS idmagasinlib,
    v.daty,
    v.remarque,
    v.etat,
    CASE
      WHEN v.etat = CAST(1 AS DECIMAL)
      THEN CAST('CR&Eacute;&Eacute;E' AS TEXT)
      WHEN v.etat = CAST(11 AS DECIMAL)
      THEN CAST('VIS&Eacute;E' AS TEXT)
      WHEN v.etat = CAST(0 AS DECIMAL)
      THEN CAST('ANNUL&Eacute;E' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS etatlib,
    CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
    v2.iddevise,
    v.idclient,
    c.nom AS idclientlib,
    CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
    CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
    CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
    CAST(COALESCE(mv.montant, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS montantpaye,
    CAST((
      COALESCE(v2.montantttc, CAST(0 AS DECIMAL)) - COALESCE(mv.montant, CAST(0 AS DECIMAL)) - COALESCE(acg.montantttcar - acg.montantpayear, CAST(0 AS DECIMAL))
    ) AS DECIMAL(30, 5)) AS montantreste,
    CAST(COALESCE(acg.montantttcar, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS avoir,
    CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
    CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
    CAST((
      v2.montantttcar - v2.montantrevient
    ) AS DECIMAL(20, 5)) AS margebrute,
    v.idreservation,
    CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
    rf.reference AS referencefacture,
    CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
    CAST((
      COALESCE(v2.montanttotal, CAST(0 AS DECIMAL)) + COALESCE(v2.montantremise, CAST(0 AS DECIMAL))
    ) AS DECIMAL(30, 5)) AS montant,
    EXTRACT(month FROM v.daty) AS mois,
    EXTRACT(year FROM v.daty) AS annee,
    CAST(v2.poids AS DECIMAL(30, 5)) AS poids,
    CAST(v2.colis AS DECIMAL(30, 5)) AS colis,
    v.modepaiement,
    mp.val AS modepaiementlib,
    COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(v2.poids, CAST(0 AS DECIMAL)) AS fraislivraison,
    v.modelivraison,
    CASE
      WHEN v.modelivraison = CAST(1 AS DECIMAL)
      THEN CAST('<span style=color: green;>LIVRAISON</span>' AS TEXT)
      WHEN v.modelivraison = CAST(2 AS DECIMAL)
      THEN CAST('<span style=color: green;>RECUPERATION</span>' AS TEXT)
      ELSE CAST(NULL AS TEXT)
    END AS modelivraisonlib,
    CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
    pv.id AS idprovince,
    pv.val AS provincelib,
    v.idorigine,
    CAST(COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) AS DECIMAL(30, 5)) AS frais,
    v.referencefact,
    v.numerofacture,
    v.lieulivraison,
    v.datelivraison,
    v.updated_at,
    CASE
      WHEN v.estprevu = CAST(0 AS DECIMAL)
      THEN CAST('Non' AS TEXT)
      ELSE CAST('Oui' AS TEXT)
    END AS estprevulib,
    ce.id AS idecriture,
    COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
    NULLIF(
      CONCAT(
        (
          NULLIF(
            CONCAT(
              (
                NULLIF(
                  CONCAT(
                    (
                      NULLIF(
                        CONCAT(
                          (
                            NULLIF(
                              CONCAT(
                                (
                                  NULLIF(
                                    CONCAT(
                                      (
                                        NULLIF(
                                          CONCAT(
                                            (
                                              NULLIF(
                                                CONCAT(
                                                  (
                                                    NULLIF(
                                                      CONCAT(
                                                        (
                                                          NULLIF(
                                                            CONCAT(
                                                              (
                                                                NULLIF(
                                                                  CONCAT((
                                                                    NULLIF(CONCAT(CAST(v.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                                  ), v.daty),
                                                                  ''
                                                                )
                                                              ),
                                                              CAST(NULL AS TEXT)
                                                            ),
                                                            ''
                                                          )
                                                        ),
                                                        CAST(v.idclient AS TEXT)
                                                      ),
                                                      ''
                                                    )
                                                  ),
                                                  CAST(NULL AS TEXT)
                                                ),
                                                ''
                                              )
                                            ),
                                            CAST(c.nom AS TEXT)
                                          ),
                                          ''
                                        )
                                      ),
                                      CAST(NULL AS TEXT)
                                    ),
                                    ''
                                  )
                                ),
                                CAST(v.idmagasin AS TEXT)
                              ),
                              ''
                            )
                          ),
                          CAST(NULL AS TEXT)
                        ),
                        ''
                      )
                    ),
                    CAST(m.val AS TEXT)
                  ),
                  ''
                )
              ),
              CAST(NULL AS TEXT)
            ),
            ''
          )
        ),
        CAST(v.remarque AS TEXT)
      ),
      ''
    ) AS motsclesss,
    v.heuresaisie,
    v.adeclarer,
    v.factureechange,
    m.id AS idpoint
  FROM public.vente AS v
  LEFT JOIN public.client AS c
    ON CAST(c.id AS TEXT) = CAST(v.idclient AS TEXT)
  LEFT JOIN public.point AS m
    ON CAST(m.id AS TEXT) = CAST(v.idmagasin AS TEXT)
  LEFT JOIN public.zone AS pv
    ON CAST(pv.id AS TEXT) = CAST(m.idzone AS TEXT)
  JOIN (
    SELECT
      vd.idvente AS id,
      CAST(SUM(
        (
          CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
        ) * (
          COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
        ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
      ) AS DECIMAL(30, 2)) AS montanttotal,
      CAST((
        SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))) - SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          )
        )
      ) AS DECIMAL(30, 2)) AS montantremise,
      CAST(SUM(
        COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * COALESCE(vd.qte, CAST(0 AS DECIMAL))
      ) AS DECIMAL(30, 5)) AS frais,
      CAST(SUM(COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.puachat, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS montanttotalachat,
      CAST(SUM(
        (
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
      ) AS DECIMAL(30, 2)) AS montanttva,
      CAST((
        SUM(
          (
            (
              CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
            ) * (
              COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
            ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) + SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL))
          ) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        )
      ) AS DECIMAL(30, 2)) AS montantttc,
      COALESCE(vd.iddevise, CAST('AR' AS VARCHAR)) AS iddevise,
      COALESCE(AVG(vd.tauxdechange), CAST(1 AS DECIMAL)) AS tauxdechange,
      CAST((
        SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL))
          ) * COALESCE(vd.tva, CAST(0 AS DECIMAL)) / CAST(100 AS DECIMAL)
        ) + SUM(
          (
            CAST(1 AS DECIMAL) - COALESCE(vd.remise / CAST(100 AS DECIMAL), CAST(0 AS DECIMAL))
          ) * (
            COALESCE(vd.qte, CAST(0 AS DECIMAL)) * COALESCE(vd.pu, CAST(0 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
          ) * COALESCE(vd.tauxdechange, CAST(1 AS DECIMAL)) - COALESCE(v.fraislivraison, CAST(0 AS DECIMAL)) * COALESCE(ing.calorie, CAST(0 AS DECIMAL)) * vd.qte
        )
      ) AS DECIMAL(30, 2)) AS montantttcar,
      CAST(SUM(vd.purevient * vd.qte) AS DECIMAL(20, 2)) AS montantrevient,
      v.idreservation,
      COALESCE(SUM(ing.calorie * vd.qte), CAST(0 AS DECIMAL)) AS poids,
      SUM(vd.qte) AS colis
    FROM public.vente_details AS vd
    LEFT JOIN public.vente AS v
      ON CAST(v.id AS TEXT) = CAST(vd.idvente AS TEXT)
    LEFT JOIN public.as_ingredients AS ing
      ON CAST(ing.id AS TEXT) = CAST(vd.idproduit AS TEXT)
    GROUP BY
      vd.idvente,
      vd.iddevise,
      v.idreservation
  ) AS v2
    ON CAST(v2.id AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.liaisonpaiementtotal AS mv
    ON CAST(v.id AS TEXT) = CAST(mv.id2 AS TEXT)
  LEFT JOIN (
    SELECT
      a.id,
      a.designation,
      a.idmagasin,
      CAST(NULL AS TEXT) AS idmagasinlib,
      a.daty,
      a.remarque,
      a.etat,
      a.idorigine,
      a.idclient,
      CAST(NULL AS TEXT) AS compte,
      CAST(NULL AS TEXT) AS compteauxiliaire,
      a.idvente,
      CAST(NULL AS TEXT) AS idventelib,
      a.idmotif,
      CAST(NULL AS TEXT) AS idmotiflib,
      a.idcategorie,
      CAST(NULL AS TEXT) AS idcategorielib,
      ag.iddevise,
      ag.tauxdechange,
      ag.montantht,
      ag.montanttva,
      ag.montantttc,
      ag.montanthtar,
      ag.montanttvaar,
      ag.montantttcar,
      CAST(NULL AS TEXT) AS idreservation,
      CAST(NULL AS TEXT) AS typeavoir,
      CAST(NULL AS TEXT) AS clientlib,
      COALESCE(m.montant, CAST(0 AS DECIMAL)) * COALESCE(ag.tauxdechange, CAST(0 AS DECIMAL)) AS montantpayear
    FROM public.avoirfc AS a
    JOIN public.avoirfcfille_grp AS ag
      ON CAST(ag.idavoirfc AS TEXT) = CAST(a.id AS TEXT)
    LEFT JOIN (
      SELECT
        m.id1 AS idorigine,
        SUM(m.montant) AS montant,
        CAST('AR' AS TEXT) AS iddevise
      FROM public.liaisonpaiement AS m
      WHERE
        m.etat >= CAST(11 AS DECIMAL) AND m.id1 IS NOT NULL
      GROUP BY
        m.id1
    ) AS m
      ON CAST(a.id AS TEXT) = CAST(m.idorigine AS TEXT)
    WHERE
      a.etat >= CAST(11 AS DECIMAL) AND a.idorigine IS NOT NULL
  ) AS acg
    ON CAST(acg.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.referencefacture AS rf
    ON CAST(rf.idfacture AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.modepaiement AS mp
    ON CAST(mp.id AS TEXT) = CAST(v.modepaiement AS TEXT)
  LEFT JOIN public.vente_reste AS vr
    ON CAST(vr.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.as_bondelivraison_client AS blc
    ON CAST(blc.idvente AS TEXT) = CAST(v.id AS TEXT)
  LEFT JOIN public.compta_ecriture AS ce
    ON CAST(ce.idobjet AS TEXT) = CAST(v.id AS TEXT)
) AS v
LEFT JOIN public.mouvementcaissecpl_v_d_avoir AS mv
  ON v.id = mv.idorigine;

-- Niveau 9 - vue 6 / 8 : NB_PERS_VALIDE
-- Dependances nouvelles : LOG_PERSONNEL_V.
CREATE VIEW public.nb_pers_valide (
    "nbpersonnelvalide"
) AS
SELECT
  COUNT(*) AS nbpersonnelvalide
FROM public.log_personnel_v AS log_personnel_v;

-- Niveau 9 - vue 7 / 8 : SOLDE_CONGE_PERS
-- Dependances nouvelles : LOG_PERSONNEL_V.
CREATE VIEW public.solde_conge_pers (
    "id", "congedroit", "congepris", "congereste", "nom", "prenom", "matricule", "iddepartement", "iddepartementlib"
) AS
SELECT
  pip.id AS id,
  CAST(SUM(COALESCE(mvt.plus, 0)) AS DECIMAL(30, 2)) AS congedroit,
  CAST(SUM(COALESCE(mvt.moins, 0)) AS DECIMAL(30, 2)) AS congepris,
  CAST(SUM(COALESCE(mvt.plus, 0)) - SUM(COALESCE(mvt.moins, 0)) AS DECIMAL(30, 2)) AS congereste,
  log.nom AS nom,
  log.prenom AS prenom,
  pip.matricule AS matricule,
  pip.iddepartement AS iddepartement,
  dep.val AS iddepartementlib
FROM public.paie_info_personnel AS pip
LEFT JOIN public.mouvementabsence AS mvt
  ON mvt.idpersonnel = pip.id AND mvt.idtype = 'TYP000004'
LEFT JOIN public.log_personnel_v AS log
  ON log.id = pip.id
LEFT JOIN public.departement AS dep
  ON dep.id = pip.iddepartement
GROUP BY
  pip.id,
  log.nom,
  log.prenom,
  pip.matricule,
  pip.iddepartement,
  dep.val;

-- Niveau 9 - vue 8 / 8 : SOLDE_FORMATION_SYNDICALE
-- Dependances nouvelles : LOG_PERSONNEL_V.
CREATE VIEW public.solde_formation_syndicale (
    "id", "annee", "congedroit", "congepris", "congereste", "nom", "prenom", "matricule", "iddepartement", "iddepartementlib"
) AS
SELECT
  pip.id AS id,
  COALESCE(mvt.annee, EXTRACT(YEAR FROM LOCALTIMESTAMP(0))) AS annee,
  CAST(15 AS DECIMAL(30, 2)) AS congedroit,
  CAST(SUM(COALESCE(mvt.moins, 0)) AS DECIMAL(30, 2)) AS congepris,
  CAST(15 - SUM(COALESCE(mvt.moins, 0)) AS DECIMAL(30, 2)) AS congereste,
  log.nom AS nom,
  log.prenom AS prenom,
  pip.matricule AS matricule,
  pip.iddepartement AS iddepartement,
  dep.val AS iddepartementlib
FROM public.paie_info_personnel AS pip
LEFT JOIN public.mouvementabsence AS mvt
  ON mvt.idpersonnel = pip.id AND mvt.idtype = 'TYPCOL0005'
LEFT JOIN public.log_personnel_v AS log
  ON log.id = pip.id
LEFT JOIN public.departement AS dep
  ON dep.id = pip.iddepartement
GROUP BY
  pip.id,
  mvt.annee,
  log.nom,
  log.prenom,
  pip.matricule,
  pip.iddepartement,
  dep.val;

COMMIT;

-- Verification du lot prepare (les vues bloquees ne sont pas comptees).
SELECT 9 AS niveau, count(*) AS vues_presentes, 8 AS vues_attendues
FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relkind='v' AND c.relname=ANY(ARRAY[
        'avoirfclib_cpl_grp', 'avoirfclib_cpl_v2_grp', 'log_personnel_v2', 'log_personnel_v_frais_medicaux',
        'mouvementcaisse_detail', 'nb_pers_valide', 'solde_conge_pers', 'solde_formation_syndicale'
    ]::text[]);

-- ============================================================================
-- NIVEAU 10 / 13 - 20 vues du plan - 20 creations ; 0 blocages source
-- ============================================================================
-- Executer apres les niveaux precedents prepares, dans leur ordre.
BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL search_path = pg_catalog, public;
SET LOCAL lock_timeout = '5s';

DO $migration_guard$
DECLARE
    problemes text;
BEGIN
    IF current_database() <> 'aigledor0110' THEN
        RAISE EXCEPTION 'Base incorrecte : % (attendu : aigledor0110)', current_database();
    END IF;
    IF current_setting('server_version_num')::integer NOT BETWEEN 90500 AND 90599 THEN
        RAISE EXCEPTION 'Script prepare pour PostgreSQL 9.5 : version %', version();
    END IF;
    SELECT string_agg(c.relname, ', ' ORDER BY c.relname) INTO problemes
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='public' AND c.relname=ANY(ARRAY[
        'droitconge_pers', 'employeeonboardingsessionscpl', 'enfantpersonnel_cpl', 'evaluation_annuelle_lib',
        'log_personnel_v2_user', 'mouvementcaisse_detail_unique', 'paiepers_eltfille', 'participation_formation_lib',
        'sanction_cpl', 'soldecongepris_pers', 'tauxabsenteisme', 'vente_cpl1',
        'vente_cpl_cl', 'vente_cpl_db', 'vente_cpl_visee', 'vente_directe_cpl_pdf',
        'vente_lib_bc', 'v_pointage_jour', 'v_pointage_kpi_presence', 'v_pointage_retards'
    ]::text[]);
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Objets deja presents, aucune vue ne sera remplacee : %', problemes;
    END IF;
    SELECT string_agg(r.nom, ', ' ORDER BY r.nom) INTO problemes
    FROM unnest(ARRAY[
        'public.action_formation', 'public.as_bondelivraison_client', 'public.avoirfclib_cpl_grp', 'public.categorie_paie',
        'public.client', 'public.commission', 'public.compta_ecriture', 'public.conf_horaire',
        'public.echeancepaiement', 'public.employee_onboarding_sessions', 'public.enfantpersonnel', 'public.evaluation_annuelle',
        'public.liaisonpaiementtotal', 'public.log_personnel', 'public.log_personnel_v2', 'public.magasinpoint',
        'public.modepaiement', 'public.mouvementabsence', 'public.mouvementcaisse_detail', 'public.mouvementcaissegroupefacture',
        'public.mouvementcaissegroupefacture1', 'public.mvtcaissegroupefacture_pdf', 'public.nb_pers_valide', 'public.onboarding_mere',
        'public.paie_fonction', 'public.paie_info_personnel', 'public.participation_formation', 'public.personnel',
        'public.point', 'public.pointage', 'public.pointage_magasinier', 'public.province',
        'public.referencefacture', 'public.reglementinterieur', 'public.sanction', 'public.typefaute',
        'public.typepointage', 'public.typesanction', 'public.utilisateur', 'public.utilisateur_personnel',
        'public.vente', 'public.vente_poids', 'public.vente_reste', 'public.ventemontant'
    ]::text[]) AS r(nom)
    WHERE pg_catalog.to_regclass(r.nom::cstring) IS NULL;
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Prerequis absents : %', problemes;
    END IF;
END;
$migration_guard$ LANGUAGE plpgsql;

-- Niveau 10 - vue 1 / 20 : DROITCONGE_PERS
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.droitconge_pers (
    "id", "droit", "nompersonnel", "matricule", "iddirection"
) AS
SELECT
  sp.idpersonnel AS id,
  CAST(sp.plus AS DECIMAL(30, 2)) AS droit,
  NULLIF(CONCAT(sp.nom, ' ', sp.prenom), '') AS nompersonnel,
  log.matricule AS matricule,
  log.iddirection AS iddirection
FROM (
  SELECT
    CAST(SUM(COALESCE(m.plus, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS plus,
    CAST(SUM(COALESCE(m.moins, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS moins,
    CAST((
      SUM(COALESCE(m.plus, CAST(0 AS DECIMAL))) - SUM(COALESCE(m.moins, CAST(0 AS DECIMAL)))
    ) AS DECIMAL(30, 2)) AS solde,
    lp.nom,
    lp.prenom,
    lp.id AS idpersonnel
  FROM public.mouvementabsence AS m
  LEFT JOIN public.log_personnel AS lp
    ON CAST(lp.id AS TEXT) = CAST(m.idpersonnel AS TEXT)
  WHERE
    CAST(m.idsource AS TEXT) = CAST('TYP000004' AS TEXT)
  GROUP BY
    lp.nom,
    lp.prenom,
    lp.id
) AS sp
LEFT JOIN public.log_personnel_v2 AS log
  ON log.id = sp.idpersonnel;

-- Niveau 10 - vue 2 / 20 : EMPLOYEEONBOARDINGSESSIONSCPL
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.employeeonboardingsessionscpl (
    "id", "datedebut", "datefin", "etat", "progression", "idpersonnel", "personnellib", "idonboarding", "onboardinglib"
) AS
SELECT
  s.id AS id,
  s.datedebut AS datedebut,
  s.datefin AS datefin,
  s.etat AS etat,
  s.progression AS progression,
  p.id AS idpersonnel,
  p.nom AS personnellib,
  o.id AS idonboarding,
  o.nom AS onboardinglib
FROM public.employee_onboarding_sessions AS s
JOIN public.log_personnel_v2 AS p
  ON s.idpersonnel = p.id
JOIN public.onboarding_mere AS o
  ON s.idonboarding = o.id;

-- Niveau 10 - vue 3 / 20 : ENFANTPERSONNEL_CPL
-- Dependances nouvelles : LOG_PERSONNEL_V2.
-- MONTHS_BETWEEN : memes jours / fins de mois et fraction sur 31 jours preserves.
CREATE VIEW public.enfantpersonnel_cpl (
    "id", "idpersonnel", "nom", "datenaissance", "genrelib", "nompersonnel", "matricule", "age", "estscolariselib"
) AS
SELECT
  e.id AS id,
  e.idpersonnel AS idpersonnel,
  e.nom AS nom,
  e.datenaissance AS datenaissance,
  CASE WHEN e.genre = 1 THEN 'Masculin' ELSE 'F&eacute;minin' END AS genrelib,
  NULLIF(CONCAT(log.nom, ' ', log.prenom), '') AS nompersonnel,
  log.matricule AS matricule,
  FLOOR(
    CAST((
      12 * (
        EXTRACT(YEAR FROM (
          LOCALTIMESTAMP(0)
        )) - EXTRACT(YEAR FROM (
          e.datenaissance
        ))
      ) + EXTRACT(MONTH FROM (
        LOCALTIMESTAMP(0)
      )) - EXTRACT(MONTH FROM (
        e.datenaissance
      )) + CASE
        WHEN CAST(EXTRACT(DAY FROM (
          LOCALTIMESTAMP(0)
        )) AS DECIMAL) = CAST(EXTRACT(DAY FROM (
          e.datenaissance
        )) AS DECIMAL)
        OR (
          CAST((
            LOCALTIMESTAMP(0)
          ) AS DATE) = CAST(DATE_TRUNC('MONTH', (
            LOCALTIMESTAMP(0)
          )) + INTERVAL '1 MONTH' - INTERVAL '1 DAY' AS DATE)
          AND CAST((
            e.datenaissance
          ) AS DATE) = CAST(DATE_TRUNC('MONTH', (
            e.datenaissance
          )) + INTERVAL '1 MONTH' - INTERVAL '1 DAY' AS DATE)
        )
        THEN 0
        ELSE (
          CAST(EXTRACT(DAY FROM (
            LOCALTIMESTAMP(0)
          )) AS DECIMAL) - CAST(EXTRACT(DAY FROM (
            e.datenaissance
          )) AS DECIMAL) + CAST(EXTRACT(EPOCH FROM (
            CAST((
              LOCALTIMESTAMP(0)
            ) AS TIME) - CAST((
              e.datenaissance
            ) AS TIME)
          )) AS DECIMAL) / 86400.0
        ) / 31.0
      END
    ) AS DECIMAL) / 12
  ) AS age,
  CASE WHEN e.estscolarise = 1 THEN 'Oui' WHEN e.estscolarise = 0 THEN 'Non' END AS estscolariselib
FROM public.enfantpersonnel AS e
LEFT JOIN public.log_personnel_v2 AS log
  ON e.idpersonnel = log.id;

-- Niveau 10 - vue 4 / 20 : EVALUATION_ANNUELLE_LIB
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.evaluation_annuelle_lib (
    "id", "idpersonnel", "idpersonnellib", "matricule", "idfonction", "idfonctionlib", "annee", "noteglobale", "commentaire", "etat", "etatlib", "motsclesss"
) AS
SELECT
  ea.id AS id,
  ea.idpersonnel AS idpersonnel,
  NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS idpersonnellib,
  pip.matricule AS matricule,
  pip.idfonction AS idfonction,
  pf.val AS idfonctionlib,
  ea.annee AS annee,
  ea.noteglobale AS noteglobale,
  ea.commentaire AS commentaire,
  ea.etat AS etat,
  CASE
    WHEN ea.etat = 1
    THEN 'En cours'
    WHEN ea.etat = 11
    THEN 'Termin&eacute;e'
    WHEN ea.etat = 0
    THEN 'ANNUL&Eacute;E'
    ELSE NULL
  END AS etatlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(ea.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(ea.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pip.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pip.idfonction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pf.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    ea.annee
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    ea.annee
                  ) AS TEXT)))
                  ELSE CAST((
                    ea.annee
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    ea.noteglobale
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    ea.noteglobale
                  ) AS TEXT)))
                  ELSE CAST((
                    ea.noteglobale
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(ea.commentaire AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    ea.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    ea.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    ea.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          CASE
            WHEN ea.etat = 1
            THEN 'En cours'
            WHEN ea.etat = 11
            THEN 'Termin&eacute;e'
            WHEN ea.etat = 0
            THEN 'ANNUL&Eacute;E'
            ELSE NULL
          END,
          NULL
        )
      ),
      ''
    )
  ) AS motsclesss
FROM public.evaluation_annuelle AS ea
LEFT JOIN public.log_personnel_v2 AS lp
  ON lp.id = ea.idpersonnel
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = ea.idpersonnel
LEFT JOIN public.paie_fonction AS pf
  ON pf.id = pip.idfonction;

-- Niveau 10 - vue 5 / 20 : LOG_PERSONNEL_V2_USER
