-- Niveau 10 - vue 6 / 20 : MOUVEMENTCAISSE_DETAIL_UNIQUE
-- Dependances nouvelles : MOUVEMENTCAISSE_DETAIL.
CREATE VIEW public.mouvementcaisse_detail_unique (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "etatlib", "montanttotal", "iddevise", "idclient", "idclientlib", "montanttva", "montantttc", "montantttcar", "montantpaye", "montantreste", "avoir", "tauxdechange", "montantrevient", "margebrute", "idreservation", "numerofacture", "updated_at", "totalimpute", "references_paiement"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  v.idmagasinlib AS idmagasinlib,
  v.daty AS daty,
  v.remarque AS remarque,
  v.etat AS etat,
  v.etatlib AS etatlib,
  v.montanttotal AS montanttotal,
  v.iddevise AS iddevise,
  v.idclient AS idclient,
  v.idclientlib AS idclientlib,
  v.montanttva AS montanttva,
  v.montantttc AS montantttc,
  v.montantttcar AS montantttcar,
  v.montantpaye AS montantpaye,
  v.montantreste AS montantreste,
  v.avoir AS avoir,
  v.tauxdechange AS tauxdechange,
  v.montantrevient AS montantrevient,
  v.margebrute AS margebrute,
  v.idreservation AS idreservation,
  v.numerofacture AS numerofacture,
  v.updated_at AS updated_at,
  SUM(v.montantimpute) AS totalimpute, /* ? Somme des montants imputes */
  STRING_AGG(
    NULLIF(CONCAT(v.designationpaiement, ' ', v.referencepaiement), ''), ' // '
    ORDER BY
      NULLIF(CONCAT(v.designationpaiement, v.referencepaiement), '')
  ) AS references_paiement /* ? Concatenation des references paiement (separees par //) */
FROM public.mouvementcaisse_detail AS v
GROUP BY
  v.id,
  v.designation,
  v.idmagasin,
  v.idmagasinlib,
  v.daty,
  v.remarque,
  v.etat,
  v.etatlib,
  v.montanttotal,
  v.iddevise,
  v.idclient,
  v.idclientlib,
  v.montanttva,
  v.montantttc,
  v.montantttcar,
  v.montantpaye,
  v.montantreste,
  v.avoir,
  v.tauxdechange,
  v.montantrevient,
  v.margebrute,
  v.idreservation,
  v.numerofacture,
  v.updated_at;

