-- Niveau 10 - vue 8 / 20 : PARTICIPATION_FORMATION_LIB
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.participation_formation_lib (
    "id", "idactionformation", "idpersonnel", "dateinscription", "remarque", "etat", "personnel", "matricule", "categorieemploye", "idactionformationlib", "etatlib", "motsclesss"
) AS
SELECT
  pf.id AS id,
  pf.idactionformation AS idactionformation,
  pf.idpersonnel AS idpersonnel,
  pf.dateinscription AS dateinscription,
  pf.remarque AS remarque,
  pf.etat AS etat,
  NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS personnel,
  pip.matricule AS matricule,
  cp.val AS categorieemploye,
  af.intitule AS idactionformationlib,
  CASE
    WHEN pf.etat = 1
    THEN 'INSCRIT'
    WHEN pf.etat = 11
    THEN 'VALIDE'
    ELSE 'INCONNU'
  END AS etatlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(pf.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pf.idactionformation AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pf.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(pf.dateinscription, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(CAST(pf.remarque AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    pf.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    pf.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    pf.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pip.matricule AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(cp.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(af.intitule AS VARCHAR(4000)), NULL),
        ' | ',
        CASE
          WHEN pf.etat = 1
          THEN 'INSCRIT'
          WHEN pf.etat = 11
          THEN 'VALIDE'
          ELSE 'INCONNU'
        END
      ),
      ''
    )
  ) AS motsclesss
FROM public.participation_formation AS pf
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = pf.idpersonnel
LEFT JOIN public.categorie_paie AS cp
  ON cp.id = pip.idcategorie_paie
LEFT JOIN public.action_formation AS af
  ON af.id = pf.idactionformation
LEFT JOIN public.log_personnel_v2 AS lp
  ON lp.id = pip.id;

-- Niveau 10 - vue 9 / 20 : SANCTION_CPL
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.sanction_cpl (
    "id", "idpersonne", "nompersonnel", "datedebut", "daty", "duree", "niveausanction", "libellefaute", "sanction", "reglementlib", "numeroregle", "etat", "matricule", "motsclesss"
) AS
SELECT
  s.id AS id,
  s.idpersonne AS idpersonne,
  NULLIF(CONCAT(lpr.nom, ' ', lpr.prenom), '') AS nompersonnel,
  s.datedebut AS datedebut,
  s.daty AS daty,
  s.duree AS duree,
  s.niveausanction AS niveausanction,
  tf.val AS libellefaute,
  ts.val AS sanction,
  ri.descriptionregle AS reglementlib,
  ri.numeroregle AS numeroregle,
  s.etat AS etat,
  lpr.matricule AS matricule,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(s.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(s.idpersonne AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(NULLIF(CONCAT(lpr.nom, ' ', lpr.prenom), '') AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(s.datedebut, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(s.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    s.duree
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    s.duree
                  ) AS TEXT)))
                  ELSE CAST((
                    s.duree
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(s.niveausanction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(tf.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(ts.val AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(ri.descriptionregle AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(ri.numeroregle AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    s.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    s.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    s.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(lpr.matricule AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.sanction AS s
LEFT JOIN public.log_personnel_v2 AS lpr
  ON s.idpersonne = lpr.id
LEFT JOIN public.typefaute AS tf
  ON s.typefaute = tf.id
LEFT JOIN public.typesanction AS ts
  ON s.typesanction = ts.id
LEFT JOIN public.reglementinterieur AS ri
  ON s.idregleenfreinte = ri.id;

-- Niveau 10 - vue 10 / 20 : SOLDECONGEPRIS_PERS
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.soldecongepris_pers (
    "id", "plus", "congepris", "nompersonnel", "matricule", "iddirection"
) AS
SELECT
  lp.id AS id,
  CAST(SUM(COALESCE(m.plus, 0)) AS DECIMAL(30, 2)) AS plus,
  CAST(SUM(COALESCE(m.moins, 0)) AS DECIMAL(30, 2)) AS congepris,
  NULLIF(CONCAT(lp.nom, ' ', lp.prenom), '') AS nompersonnel,
  lp.matricule AS matricule,
  lp.iddirection AS iddirection
FROM public.mouvementabsence AS m
LEFT JOIN public.log_personnel_v2 AS lp
  ON lp.id = m.idpersonnel
GROUP BY
  lp.nom,
  lp.prenom,
  lp.id,
  lp.matricule,
  lp.iddirection;

-- Niveau 10 - vue 11 / 20 : TAUXABSENTEISME
-- Dependances nouvelles : NB_PERS_VALIDE.
CREATE VIEW public.tauxabsenteisme (
    "heuretheorique", "heureabsence", "mois", "annee", "tauxabsence", "moislib", "iddirection"
) AS
SELECT
  CAST(nb.nbpersonnelvalide * 173.33 AS DECIMAL(30, 2)) AS heuretheorique,
  CAST(COALESCE(SUM(p.absence), 0) AS DECIMAL(30, 2)) AS heureabsence,
  p.mois AS mois,
  p.annee AS annee,
  CAST(ROUND(
    CAST((
      CAST(COALESCE(SUM(p.absence), 0) AS DECIMAL) / (
        nb.nbpersonnelvalide * 173.33
      )
    ) * 100 AS DECIMAL),
    2
  ) AS DECIMAL(30, 2)) AS tauxabsence,
  (
    ARRAY[
      'Janvier',
      'Février',
      'Mars',
      'Avril',
      'Mai',
      'Juin',
      'Juillet',
      'Août',
      'Septembre',
      'Octobre',
      'Novembre',
      'Décembre'
    ]
  )[CAST(EXTRACT(MONTH FROM TO_DATE(CAST(TO_CHAR(p.mois, 'FM00') AS TEXT), 'MM')) AS INT) + 0] AS moislib,
  p.direction AS iddirection
FROM public.pointage AS p, public.nb_pers_valide AS nb
GROUP BY
  nb.nbpersonnelvalide,
  p.mois,
  p.annee,
  p.direction;

-- Niveau 10 - vue 12 / 20 : VENTE_CPL1
-- Dependances nouvelles : AVOIRFCLIB_CPL_GRP, VENTEMONTANT.
CREATE VIEW public.vente_cpl1 (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "datyprevu", "remarque", "etat", "adeclarer", "etatlib", "montanttotal", "iddevise", "idclient", "idclientlib", "montanttva", "montantttc", "montantttcar", "montantpaye", "montantreste", "avoir", "tauxdechange", "montantrevient", "margebrute", "idreservation", "aveccommission", "idmodepaiement", "referencefacture", "idmodepaiementlib", "montantdonne", "montantretourner", "heuresaisie", "idresponsablelib"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  m.val AS idmagasinlib,
  v.daty AS daty,
  v.datyprevu AS datyprevu,
  v.remarque AS remarque,
  v.etat AS etat,
  v.adeclarer AS adeclarer,
  CASE
    WHEN v.etat = 0
    THEN 'ANNULEE'
    WHEN v.etat = 1
    THEN 'CREEE'
    WHEN v.etat = 11
    THEN 'VALIDEE'
  END AS etatlib,
  v2.montanttotal AS montanttotal,
  v2.iddevise AS iddevise,
  v.idclient AS idclient,
  c.nom AS idclientlib,
  CAST(v2.montanttva AS DECIMAL(30, 2)) AS montanttva,
  CAST(v2.montantttc AS DECIMAL(30, 2)) AS montantttc,
  CAST(v2.montantttcar AS DECIMAL(30, 2)) AS montantttcar,
  CAST(COALESCE(mv.credit, 0) - COALESCE(acg.montantpaye, 0) AS DECIMAL(30, 2)) AS montantpaye,
  CAST(v2.montantttc - COALESCE(mv.credit, 0) - COALESCE(acg.resteapayer_avr, 0) AS DECIMAL(30, 2)) AS montantreste,
  COALESCE(acg.montantttc_avr, 0) AS avoir,
  v2.tauxdechange AS tauxdechange,
  v2.montantrevient AS montantrevient,
  CAST((
    v2.montantttcar - v2.montantrevient
  ) AS DECIMAL(20, 2)) AS margebrute,
  v.idreservation AS idreservation,
  CASE WHEN NOT cm.id IS NULL THEN 'Oui' WHEN cm.id IS NULL THEN 'Non' END AS aveccommission,
  v.idmodepaiement AS idmodepaiement,
  rf.reference AS referencefacture,
  mp.val AS idmodepaiementlib,
  v.montantdonne AS montantdonne,
  COALESCE(mv.montantretourner, 0) AS montantretourner,
  v.heuresaisie AS heuresaisie,
  pers.nom AS idresponsablelib
FROM public.vente AS v
LEFT JOIN public.client AS c
  ON c.id = v.idclient
LEFT JOIN public.magasinpoint AS m
  ON m.id = v.idmagasin
JOIN public.ventemontant AS v2
  ON v2.id = v.id
LEFT JOIN public.mouvementcaissegroupefacture1 AS mv
  ON v.id IN (mv.idorigine)
LEFT JOIN public.avoirfclib_cpl_grp AS acg
  ON acg.idvente = v.id
LEFT JOIN public.commission AS cm
  ON cm.idfacture = v.id
LEFT JOIN public.modepaiement AS mp
  ON mp.id = v.idmodepaiement
LEFT JOIN public.referencefacture AS rf
  ON rf.idfacture = v.id
LEFT JOIN public.personnel AS pers
  ON pers.id = v.idresponsable;

-- Niveau 10 - vue 13 / 20 : VENTE_CPL_CL
-- Dependances nouvelles : AVOIRFCLIB_CPL_GRP, VENTE_POIDS, VENTEMONTANT.
CREATE VIEW public.vente_cpl_cl (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "remarque", "etat", "etatlib", "montanttotal", "iddevise", "idclient", "idclientlib", "montanttva", "montantttc", "montantttcar", "montantpaye", "montantreste", "avoir", "tauxdechange", "montantrevient", "margebrute", "idreservation", "datyprevu", "referencefacture", "montantremise", "montant", "mois", "annee", "poids", "colis", "modepaiement", "modepaiementlib", "fraislivraison", "modelivraison", "modelivraisonlib", "reste", "idprovince", "provincelib", "idorigine", "frais", "referencefact", "numerofacture", "lieulivraison", "datelivraison", "updated_at", "estprevulib", "idecriture", "datedelivraison", "adresse"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  m.val AS idmagasinlib,
  v.daty AS daty,
  v.remarque AS remarque,
  v.etat AS etat,
  CASE
    WHEN v.etat = 1
    THEN 'CR&Eacute;&Eacute;E'
    WHEN v.etat = 11
    THEN 'VIS&Eacute;E'
    WHEN v.etat = 0
    THEN 'ANNUL&Eacute;E'
  END AS etatlib,
  CAST(v2.montanttotal AS DECIMAL(30, 5)) AS montanttotal,
  v2.iddevise AS iddevise,
  v.idclient AS idclient,
  c.nom AS idclientlib,
  CAST(v2.montanttva AS DECIMAL(30, 5)) AS montanttva,
  CAST(v2.montantttc AS DECIMAL(30, 5)) AS montantttc,
  CAST(v2.montantttcar AS DECIMAL(30, 5)) AS montantttcar,
  CAST(COALESCE(mv.montant, 0) AS DECIMAL(30, 5)) AS montantpaye,
  CAST(COALESCE(v2.montantttc, 0) - COALESCE(mv.montant, 0) - COALESCE(acg.imputeefactar, 0) AS DECIMAL(30, 5)) AS montantreste,
  CAST(COALESCE(acg.montantttc_avr, 0) AS DECIMAL(30, 5)) AS avoir,
  CAST(v2.tauxdechange AS DECIMAL(10, 2)) AS tauxdechange,
  CAST(v2.montantrevient AS DECIMAL(20, 5)) AS montantrevient,
  CAST((
    v2.montantttcar - v2.montantrevient
  ) AS DECIMAL(20, 5)) AS margebrute,
  v.idreservation AS idreservation,
  CASE WHEN v.datyprevu IS NULL THEN v.daty ELSE v.datyprevu END AS datyprevu,
  rf.reference AS referencefacture,
  CAST(v2.montantremise AS DECIMAL(30, 5)) AS montantremise,
  CAST(COALESCE(v2.montanttotal, 0) + COALESCE(v2.montantremise, 0) AS DECIMAL(30, 5)) AS montant,
  EXTRACT(MONTH FROM v.daty) AS mois,
  EXTRACT(YEAR FROM v.daty) AS annee,
  CAST(vp.poids AS DECIMAL(30, 5)) AS poids,
  CAST(vp.colis AS DECIMAL(30, 5)) AS colis,
  v.modepaiement AS modepaiement,
  mp.val AS modepaiementlib,
  COALESCE(v.fraislivraison, 0) * COALESCE(vp.poids, 0) AS fraislivraison,
  v.modelivraison AS modelivraison,
  CASE
    WHEN v.modelivraison = 1
    THEN '<span style=color: green;>LIVRAISON</span>'
    WHEN v.modelivraison = 2
    THEN '<span style=color: green;>RECUPERATION</span>'
  END AS modelivraisonlib,
  CAST(vr.reste AS DECIMAL(30, 5)) AS reste,
  pv.id AS idprovince,
  pv.val AS provincelib,
  v.idorigine /* bl.id                                                                                         as idbl, */ AS idorigine,
  CAST(COALESCE(v.fraislivraison, 0) AS DECIMAL(30, 5)) AS frais,
  v.referencefact AS referencefact,
  v.numerofacture AS numerofacture,
  v.lieulivraison AS lieulivraison,
  v.datelivraison AS datelivraison,
  v.updated_at AS updated_at,
  CASE WHEN v.estprevu = 0 THEN 'Non' ELSE 'Oui' END AS estprevulib,
  ce.id AS idecriture,
  COALESCE(blc.daty, v.datelivraison) AS datedelivraison,
  c.adresse AS adresse
FROM public.vente AS v
LEFT JOIN public.client AS c
  ON c.id = v.idclient
LEFT JOIN public.province AS pv
  ON pv.id = c.idprovince
LEFT JOIN public.magasinpoint AS m
  ON m.id = v.idmagasin
JOIN public.ventemontant AS v2
  ON v2.id = v.id
LEFT JOIN public.liaisonpaiementtotal AS mv
  ON v.id = mv.id2
LEFT JOIN public.avoirfclib_cpl_grp AS acg
  ON acg.idvente = v.id
LEFT JOIN public.referencefacture AS rf
  ON rf.idfacture = v.id
LEFT JOIN public.vente_poids AS vp
  ON vp.idvente = v.id
LEFT JOIN public.modepaiement AS mp
  ON mp.id = v.modepaiement
LEFT JOIN public.vente_reste AS vr
  ON vr.idvente = v.id
LEFT JOIN public.as_bondelivraison_client AS blc
  ON blc.idvente = v.id
LEFT JOIN public.compta_ecriture AS ce
  ON ce.idobjet = v.id;

-- Niveau 10 - vue 14 / 20 : VENTE_CPL_DB
-- Dependances nouvelles : AVOIRFCLIB_CPL_GRP, VENTEMONTANT.
CREATE VIEW public.vente_cpl_db (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "datyprevu", "remarque", "etat", "adeclarer", "etatlib", "montanttotal", "iddevise", "idclient", "idclientlib", "montanttva", "montantttc", "montantttcar", "montantpaye", "montantreste", "avoir", "tauxdechange", "montantrevient", "margebrute", "idreservation", "aveccommission", "idmodepaiement", "referencefacture", "idmodepaiementlib", "montantdonne", "heuresaisie", "idresponsablelib", "factureechange"
) AS
SELECT
  v.id AS id,
  v.designation AS designation,
  v.idmagasin AS idmagasin,
  m.val AS idmagasinlib,
  v.daty AS daty,
  v.datyprevu AS datyprevu,
  v.remarque AS remarque,
  v.etat AS etat,
  v.adeclarer AS adeclarer,
  CASE
    WHEN v.etat = 0
    THEN 'ANNULEE'
    WHEN v.etat = 1
    THEN 'CREEE'
    WHEN v.etat = 11
    THEN 'VALIDEE'
  END AS etatlib,
  v2.montanttotal AS montanttotal,
  v2.iddevise AS iddevise,
  v.idclient AS idclient,
  c.nom AS idclientlib,
  CAST(v2.montanttva AS DECIMAL(30, 2)) AS montanttva,
  CAST(v2.montantttc AS DECIMAL(30, 2)) AS montantttc,
  CAST(v2.montantttcar AS DECIMAL(30, 2)) AS montantttcar,
  CAST(COALESCE(mv.credit, 0) - COALESCE(acg.montantpaye, 0) AS DECIMAL(30, 2)) AS montantpaye,
  CAST(v2.montantttc - COALESCE(mv.credit, 0) - COALESCE(acg.resteapayer_avr, 0) AS DECIMAL(30, 2)) AS montantreste,
  COALESCE(acg.montantttc_avr, 0) AS avoir,
  v2.tauxdechange AS tauxdechange,
  v2.montantrevient AS montantrevient,
  CAST((
    v2.montantttcar - v2.montantrevient
  ) AS DECIMAL(20, 2)) AS margebrute,
  v.idreservation AS idreservation,
  CASE WHEN NOT cm.id IS NULL THEN 'Oui' WHEN cm.id IS NULL THEN 'Non' END AS aveccommission,
  v.idmodepaiement AS idmodepaiement,
  rf.reference AS referencefacture,
  mp.val AS idmodepaiementlib,
  v.montantdonne AS montantdonne,
  v.heuresaisie AS heuresaisie,
  pers.nom AS idresponsablelib,
  v.factureechange AS factureechange
FROM public.vente AS v
LEFT JOIN public.client AS c
  ON c.id = v.idclient
LEFT JOIN (
  SELECT
    p.id,
    p.val,
    p.desce,
    p.id AS idpoint,
    CAST('-' AS TEXT) AS idproduit,
    CAST(NULL AS TEXT) AS idtypemagasin,
    11 AS etat
  FROM public.point AS p
) AS m
  ON m.id = v.idmagasin
JOIN public.ventemontant AS v2
  ON v2.id = v.id
LEFT JOIN public.mouvementcaissegroupefacture AS mv
  ON v.id IN (mv.idorigine)
LEFT JOIN public.avoirfclib_cpl_grp AS acg
  ON acg.idvente = v.id
LEFT JOIN public.commission AS cm
  ON cm.idfacture = v.id
LEFT JOIN public.modepaiement AS mp
  ON mp.id = v.idmodepaiement
LEFT JOIN public.referencefacture AS rf
  ON rf.idfacture = v.id
LEFT JOIN public.personnel AS pers
  ON pers.id = v.idresponsable;

