-- Niveau 10 - vue 16 / 20 : VENTE_DIRECTE_CPL_PDF
-- Dependances nouvelles : AVOIRFCLIB_CPL_GRP, VENTEMONTANT.
CREATE VIEW public.vente_directe_cpl_pdf (
    "id", "designation", "idmagasin", "idmagasinlib", "daty", "datyprevu", "remarque", "etat", "adeclarer", "etatlib", "montanttotal", "iddevise", "idclient", "idclientlib", "montanttva", "montantttc", "montantttcar", "montantpaye", "montantreste", "avoir", "tauxdechange", "montantrevient", "margebrute", "idreservation", "aveccommission", "idmodepaiement", "referencefacture", "idmodepaiementlib", "montantdonne", "montantretourner", "heuresaisie", "idecheancepaiement", "echeancepaiementlib", "idorigine", "datyheure", "nomclientdivers", "idresponsablelib"
) AS
SELECT
  _0.id AS id,
  _0.designation AS designation,
  _0.idmagasin AS idmagasin,
  _0.idmagasinlib AS idmagasinlib,
  _0.daty AS daty,
  _0.datyprevu AS datyprevu,
  _0.remarque AS remarque,
  _0.etat AS etat,
  _0.adeclarer AS adeclarer,
  _0.etatlib AS etatlib,
  _0.montanttotal AS montanttotal,
  _0.iddevise AS iddevise,
  _0.idclient AS idclient,
  _0.idclientlib AS idclientlib,
  _0.montanttva AS montanttva,
  _0.montantttc AS montantttc,
  _0.montantttcar AS montantttcar,
  _0.montantpaye AS montantpaye,
  _0.montantreste AS montantreste,
  _0.avoir AS avoir,
  _0.tauxdechange AS tauxdechange,
  _0.montantrevient AS montantrevient,
  _0.margebrute AS margebrute,
  _0.idreservation AS idreservation,
  _0.aveccommission AS aveccommission,
  _0.idmodepaiement AS idmodepaiement,
  _0.referencefacture AS referencefacture,
  _0.idmodepaiementlib AS idmodepaiementlib,
  _0.montantdonne AS montantdonne,
  _0.montantretourner AS montantretourner,
  _0.heuresaisie AS heuresaisie,
  _0.idecheancepaiement AS idecheancepaiement,
  _0.echeancepaiementlib AS echeancepaiementlib,
  _0.idorigine AS idorigine,
  _0.datyheure AS datyheure,
  _0.nomclientdivers AS nomclientdivers,
  _0.idresponsablelib AS idresponsablelib
FROM (
  SELECT
    v.id AS id,
    v.designation AS designation,
    v.idmagasin AS idmagasin,
    m.val AS idmagasinlib,
    v.daty AS daty,
    v.datyprevu AS datyprevu,
    v.remarque AS remarque,
    v.etat AS etat,
    v.adeclarer AS adeclarer,
    CASE
      WHEN v.etat = 1
      THEN 'CR&Eacute;&Eacute;E'
      WHEN v.etat = 11
      THEN 'VIS&Eacute;E'
      WHEN v.etat = 0
      THEN 'ANNUL&Eacute;E'
    END AS etatlib,
    v2.montanttotal AS montanttotal,
    v2.iddevise AS iddevise,
    v.idclient AS idclient,
    c.nom AS idclientlib,
    CAST(v2.montanttva AS DECIMAL(30, 2)) AS montanttva,
    CAST(v2.montantttc AS DECIMAL(30, 2)) AS montantttc,
    CAST(v2.montantttcar AS DECIMAL(30, 2)) AS montantttcar,
    CAST(COALESCE(mv.credit, 0) - COALESCE(acg.montantpaye, 0) AS DECIMAL(30, 2)) AS montantpaye,
    CAST(v2.montantttc - COALESCE(mv.credit, 0) - COALESCE(acg.resteapayer_avr, 0) AS DECIMAL(30, 2)) AS montantreste,
    COALESCE(acg.montantttc_avr, 0) AS avoir,
    v2.tauxdechange AS tauxdechange,
    v2.montantrevient AS montantrevient,
    CAST((
      v2.montantttcar - v2.montantrevient
    ) AS DECIMAL(20, 2)) AS margebrute,
    v.idreservation AS idreservation,
    CASE WHEN NOT cm.id IS NULL THEN 'Oui' ELSE 'Non' END AS aveccommission,
    v.idmodepaiement AS idmodepaiement,
    rf.reference AS referencefacture,
    mp.val AS idmodepaiementlib,
    CASE
      WHEN v.montantdonne IS NULL OR v.montantdonne = 0
      THEN CAST(COALESCE(mv.credit, 0) - COALESCE(acg.montantpaye, 0) AS DECIMAL(30, 2))
      ELSE CAST(v.montantdonne AS DECIMAL(30, 2))
    END AS montantdonne,
    COALESCE(mv.montantretourner, 0) AS montantretourner,
    v.heuresaisie AS heuresaisie,
    v.idecheancepaiement AS idecheancepaiement,
    ep.desce AS echeancepaiementlib,
    v.idorigine AS idorigine,
    CAST(TO_TIMESTAMP(
      CAST(NULLIF(CONCAT(v.daty, ' ', v.heuresaisie), '') AS TEXT),
      'DD/MM/YYYY HH24:MI:SS'
    ) AS TIMESTAMP) AS datyheure,
    v.nomclientdivers AS nomclientdivers,
    u.nomuser AS idresponsablelib
  FROM public.vente AS v
  LEFT JOIN public.client AS c
    ON c.id = v.idclient
  LEFT JOIN (
    SELECT
      p.id,
      p.val,
      p.desce,
      p.id AS idpoint,
      CAST('-' AS TEXT) AS idproduit,
      CAST(NULL AS TEXT) AS idtypemagasin,
      11 AS etat
    FROM public.point AS p
  ) AS m
    ON m.id = v.idmagasin
  JOIN public.ventemontant AS v2
    ON v2.id = v.id
  LEFT JOIN public.mvtcaissegroupefacture_pdf AS mv
    ON v.id IN (mv.idorigine)
  LEFT JOIN public.avoirfclib_cpl_grp AS acg
    ON acg.idvente = v.id
  LEFT JOIN public.commission AS cm
    ON cm.idfacture = v.id
  LEFT JOIN public.modepaiement AS mp
    ON mp.id = v.idmodepaiement
  LEFT JOIN public.referencefacture AS rf
    ON rf.idfacture = v.id
  LEFT JOIN public.echeancepaiement AS ep
    ON ep.id = v.idecheancepaiement
  LEFT JOIN public.utilisateur AS u
    ON u.refuser = CAST(v.idresponsable AS DECIMAL)
) AS _0
ORDER BY
  datyheure DESC NULLS LAST;

