-- Niveau 10 - vue 18 / 20 : V_POINTAGE_JOUR
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.v_pointage_jour (
    "daty", "heure", "employe", "point_de_vente", "action"
) AS
SELECT
  pm.daty AS daty,
  pm.heure AS heure,
  NULLIF(CONCAT(p.nom, ' ', p.prenom), '') AS employe,
  pdv.val AS point_de_vente,
  tp.val AS action
FROM public.pointage_magasinier AS pm
JOIN public.log_personnel_v2 AS p
  ON p.id = pm.idpersonnel
JOIN public.point AS pdv
  ON pdv.id = pm.idpoint
JOIN public.typepointage AS tp
  ON tp.id = pm.idtypepointage;

-- Niveau 10 - vue 19 / 20 : V_POINTAGE_KPI_PRESENCE
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.v_pointage_kpi_presence (
    "daty", "presents", "magasiniers_attendus", "absents", "taux_presence"
) AS
WITH totals AS (
  SELECT
    COUNT(*) AS magasiniers_attendus
  FROM public.log_personnel_v2 AS log_personnel_v2
), presence AS (
  SELECT
    pm.daty AS daty,
    COUNT(DISTINCT CASE WHEN pm.idtypepointage = 'TP000001' THEN pm.idpersonnel END) AS presents
  FROM public.pointage_magasinier AS pm
  GROUP BY
    pm.daty
)
SELECT
  p.daty AS daty,
  p.presents AS presents,
  t.magasiniers_attendus AS magasiniers_attendus,
  (
    t.magasiniers_attendus - p.presents
  ) AS absents,
  ROUND(
    CAST(CAST(p.presents * 100.0 AS DECIMAL) / NULLIF(t.magasiniers_attendus, 0) AS DECIMAL),
    2
  ) AS taux_presence
FROM presence AS p
CROSS JOIN totals AS t;

-- Niveau 10 - vue 20 / 20 : V_POINTAGE_RETARDS
-- Dependances nouvelles : LOG_PERSONNEL_V2.
CREATE VIEW public.v_pointage_retards (
    "daty", "personnel", "point_de_vente", "heure_arrivee", "retard_minutes"
) AS
WITH premier_pointage AS (
  SELECT
    pm.daty AS daty,
    pm.idpersonnel AS idpersonnel,
    pm.idpoint AS idpoint,
    MIN(pm.heure) AS heure
  FROM public.pointage_magasinier AS pm
  WHERE
    pm.idtypepointage = 'TP000001'
  GROUP BY
    pm.daty,
    pm.idpersonnel,
    pm.idpoint
), horaire AS (
  SELECT
    conf_horaire.heurearriveenormal AS heurearriveenormal
  FROM public.conf_horaire AS conf_horaire
  WHERE
    TRUE
  LIMIT 1
)
SELECT
  t.daty AS daty,
  NULLIF(CONCAT(p.nom, ' ', p.prenom), '') AS personnel,
  pdv.val AS point_de_vente,
  t.heure AS heure_arrivee,
  ROUND(
    (
      (
        EXTRACT(EPOCH FROM (
          CAST(TO_TIMESTAMP(CAST(t.heure AS TEXT), 'HH24:MI:SS') AS TIMESTAMP) - CAST(TO_TIMESTAMP(CAST(h.heurearriveenormal AS TEXT), 'HH24:MI:SS') AS TIMESTAMP)
        )) / 86400.0
      )
    ) * 24 * 60
  ) AS retard_minutes
FROM premier_pointage AS t
INNER JOIN public.log_personnel_v2 AS p
  ON p.id = t.idpersonnel
INNER JOIN public.point AS pdv
  ON pdv.id = t.idpoint
CROSS JOIN horaire AS h
WHERE
  CAST(TO_TIMESTAMP(CAST(t.heure AS TEXT), 'HH24:MI:SS') AS TIMESTAMP) > CAST(TO_TIMESTAMP(CAST(h.heurearriveenormal AS TEXT), 'HH24:MI:SS') AS TIMESTAMP);

COMMIT;

-- Verification du lot prepare (les vues bloquees ne sont pas comptees).
SELECT 10 AS niveau, count(*) AS vues_presentes, 20 AS vues_attendues
FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relkind='v' AND c.relname=ANY(ARRAY[
        'droitconge_pers', 'employeeonboardingsessionscpl', 'enfantpersonnel_cpl', 'evaluation_annuelle_lib',
        'log_personnel_v2_user', 'mouvementcaisse_detail_unique', 'paiepers_eltfille', 'participation_formation_lib',
        'sanction_cpl', 'soldecongepris_pers', 'tauxabsenteisme', 'vente_cpl1',
        'vente_cpl_cl', 'vente_cpl_db', 'vente_cpl_visee', 'vente_directe_cpl_pdf',
        'vente_lib_bc', 'v_pointage_jour', 'v_pointage_kpi_presence', 'v_pointage_retards'
    ]::text[]);

-- ============================================================================
-- NIVEAU 11 / 13 - 8 vues du plan - 8 creations ; 0 blocages source
-- ============================================================================
-- Executer apres les niveaux precedents prepares, dans leur ordre.
BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL search_path = pg_catalog, public;
SET LOCAL lock_timeout = '5s';

DO $migration_guard$
DECLARE
    problemes text;
BEGIN
    IF current_database() <> 'aigledor0110' THEN
        RAISE EXCEPTION 'Base incorrecte : % (attendu : aigledor0110)', current_database();
    END IF;
    IF current_setting('server_version_num')::integer NOT BETWEEN 90500 AND 90599 THEN
        RAISE EXCEPTION 'Script prepare pour PostgreSQL 9.5 : version %', version();
    END IF;
    SELECT string_agg(c.relname, ', ' ORDER BY c.relname) INTO problemes
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='public' AND c.relname=ANY(ARRAY[
        'emp_onboarding_com', 'emp_onboarding_spec', 'log_personnel_avecconge', 'log_personnel_fin_conge',
        'releveclient', 'vente_ca', 'vente_ca_dashboard', 'v_pointage_retard_point'
    ]::text[]);
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Objets deja presents, aucune vue ne sera remplacee : %', problemes;
    END IF;
    SELECT string_agg(r.nom, ', ' ORDER BY r.nom) INTO problemes
    FROM unnest(ARRAY[
        'public.avoirfclib_cpl_visee', 'public.caisse', 'public.compta_ecriture', 'public.compta_journal',
        'public.compta_lettrage', 'public.compta_sous_ecriture', 'public.departement', 'public.employeeonboardingsessionscpl',
        'public.liaisonpaiementmvtcaissegrp', 'public.log_direction', 'public.log_personnel', 'public.log_service',
        'public.modepaiement', 'public.mouvementabsence', 'public.mouvementcaisse', 'public.mouvementcaisse_detail_unique',
        'public.onboarding_mere', 'public.paie_categorie', 'public.paie_fonction', 'public.paie_info_personnel',
        'public.point', 'public.qualification_paie', 'public.sexe', 'public.soldecongepris_pers',
        'public.tiers', 'public.v_pointage_retards', 'public.vente_cpl1', 'public.vente_cpl_db',
        'public.vente_details'
    ]::text[]) AS r(nom)
    WHERE pg_catalog.to_regclass(r.nom::cstring) IS NULL;
    IF problemes IS NOT NULL THEN
        RAISE EXCEPTION 'Prerequis absents : %', problemes;
    END IF;
END;
$migration_guard$ LANGUAGE plpgsql;

-- Niveau 11 - vue 1 / 8 : EMP_ONBOARDING_COM
-- Dependances nouvelles : EMPLOYEEONBOARDINGSESSIONSCPL.
CREATE VIEW public.emp_onboarding_com (
    "id", "datedebut", "datefin", "etat", "progression", "idpersonnel", "personnellib", "idonboarding", "onboardinglib", "idfonction", "idfonctionlib", "motsclesss"
) AS
SELECT
  eos.id AS id,
  eos.datedebut AS datedebut,
  eos.datefin AS datefin,
  eos.etat AS etat,
  eos.progression AS progression,
  eos.idpersonnel AS idpersonnel,
  eos.personnellib AS personnellib,
  eos.idonboarding AS idonboarding,
  eos.onboardinglib AS onboardinglib,
  om.idfonction AS idfonction,
  pf.val AS idfonctionlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(eos.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(eos.datedebut, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(eos.datefin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    eos.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    eos.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    eos.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    eos.progression
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    eos.progression
                  ) AS TEXT)))
                  ELSE CAST((
                    eos.progression
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(eos.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(eos.personnellib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(eos.idonboarding AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(eos.onboardinglib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(om.idfonction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pf.val AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.employeeonboardingsessionscpl AS eos
LEFT JOIN public.onboarding_mere AS om
  ON om.id = eos.idonboarding
LEFT JOIN public.paie_fonction AS pf
  ON pf.id = om.idfonction
WHERE
  om.idfonction IS NULL;

-- Niveau 11 - vue 2 / 8 : EMP_ONBOARDING_SPEC
-- Dependances nouvelles : EMPLOYEEONBOARDINGSESSIONSCPL.
CREATE VIEW public.emp_onboarding_spec (
    "id", "datedebut", "datefin", "etat", "progression", "idpersonnel", "personnellib", "idonboarding", "onboardinglib", "idfonction", "idfonctionlib", "motsclesss"
) AS
SELECT
  eos.id AS id,
  eos.datedebut AS datedebut,
  eos.datefin AS datefin,
  eos.etat AS etat,
  eos.progression AS progression,
