  eos.idonboarding AS idonboarding,
  eos.onboardinglib AS onboardinglib,
  om.idfonction AS idfonction,
  pf.val AS idfonctionlib,
  (
    NULLIF(
      CONCAT(
        COALESCE(CAST(eos.id AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(TO_CHAR(eos.datedebut, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(TO_CHAR(eos.datefin, 'YYYY-MM-DD HH24:MI:SS'), NULL),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    eos.etat
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    eos.etat
                  ) AS TEXT)))
                  ELSE CAST((
                    eos.etat
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(
          REPLACE(
            REGEXP_REPLACE(
              (
                CASE
                  WHEN POSITION('.' IN CAST((
                    eos.progression
                  ) AS TEXT)) > 0
                  THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                    eos.progression
                  ) AS TEXT)))
                  ELSE CAST((
                    eos.progression
                  ) AS TEXT)
                END
              ),
              '^(-?)0[.]',
              e'\\1.'
            ),
            '.',
            ','
          ),
          NULL
        ),
        ' | ',
        COALESCE(CAST(eos.idpersonnel AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(eos.personnellib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(eos.idonboarding AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(eos.onboardinglib AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(om.idfonction AS VARCHAR(4000)), NULL),
        ' | ',
        COALESCE(CAST(pf.val AS VARCHAR(4000)), NULL)
      ),
      ''
    )
  ) AS motsclesss
FROM public.employeeonboardingsessionscpl AS eos
LEFT JOIN public.onboarding_mere AS om
  ON om.id = eos.idonboarding
LEFT JOIN public.paie_fonction AS pf
  ON pf.id = om.idfonction
WHERE
  NOT om.idfonction IS NULL;

-- Niveau 11 - vue 3 / 8 : LOG_PERSONNEL_AVECCONGE
-- Dependances nouvelles : SOLDECONGEPRIS_PERS.
CREATE VIEW public.log_personnel_avecconge (
    "id", "permis_conduire", "chemin_permis", "remarque", "id_pers", "nom", "prenom", "date_naissance", "sexe", "numero_cin", "date_cin", "date_dupl_cin", "nationalite", "adresse", "fokotany", "acte_naissance", "direction", "service", "code_dr", "matricule", "idcategorie", "ctg", "indicegrade", "indice_fonctionnel", "statut", "categorieval", "ctgval", "numero_cnaps", "numero_ostie", "temporaire", "droit", "prie", "resteconge", "etat", "idpersonnel", "iddirection", "iddepartement", "departementlib", "idqualification", "qualificationlib", "etatlib"
) AS
SELECT
  l.id AS id,
  l.permis_conduire AS permis_conduire,
  l.chemin_permis AS chemin_permis,
  l.remarque AS remarque,
  l.id_pers AS id_pers,
  l.nom AS nom,
  l.prenom AS prenom,
  l.date_naissance AS date_naissance,
  sex.desce AS sexe,
  l.numero_cin AS numero_cin,
  l.date_cin AS date_cin,
  l.date_dupl_cin AS date_dupl_cin,
  l.nationalite AS nationalite,
  l.adresse AS adresse,
  l.fokotany AS fokotany,
  l.acte_naissance AS acte_naissance,
  d.val AS direction,
  s.libelle AS service,
  s.code_dr AS code_dr,
  CAST(paie.matricule AS TEXT) AS matricule,
  paie.idcategorie AS idcategorie,
  paie.ctg AS ctg,
  paie.indicegrade AS indicegrade,
  paie.indice_fonctionnel AS indice_fonctionnel,
  paie.statut AS statut,
  c.taux AS categorieval,
  CAST(NULL AS TEXT) AS ctgval,
  paie.numero_cnaps AS numero_cnaps,
  paie.numero_ostie AS numero_ostie,
  CASE
    WHEN paie.temporaire = -1
    THEN 'Temporaire'
    WHEN paie.temporaire = 0
    THEN 'Permanent'
    WHEN paie.temporaire = 1
    THEN 'Cadre'
    ELSE NULL
  END AS temporaire,
  CAST(COALESCE(sc.plus, 0) AS DECIMAL(30, 2)) AS droit,
  CAST(COALESCE(sp.congepris, 0) AS DECIMAL(30, 2)) AS prie,
  CAST(COALESCE(sc.solde, 0) AS DECIMAL(30, 2)) AS resteconge,
  paie.etat AS etat,
  l.id AS idpersonnel,
  l.direction AS iddirection,
  dp.id AS iddepartement,
  dp.val AS departementlib,
  qp.id AS idqualification,
  qp.val AS qualificationlib,
  CASE
    WHEN paie.etat < 1
    THEN 'Debauches'
    WHEN paie.etat = 1
    THEN 'A Valider'
    WHEN paie.etat = 11
    THEN 'Valides'
    ELSE NULL
  END AS etatlib
FROM public.log_personnel AS l
LEFT JOIN public.log_service AS s
  ON l.service = s.id
LEFT JOIN public.paie_info_personnel AS paie
  ON paie.id = l.id
LEFT JOIN public.sexe AS sex
  ON l.sexe = sex.id
LEFT JOIN public.log_direction AS d
  ON d.id = l.direction
LEFT JOIN public.paie_categorie AS c
  ON c.id = paie.idcategorie
LEFT JOIN public.soldecongepris_pers AS sp
  ON l.id = sp.id
LEFT JOIN (
  SELECT
    CAST(SUM(COALESCE(m.plus, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS plus,
    CAST(SUM(COALESCE(m.moins, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS moins,
    CAST((
      SUM(COALESCE(m.plus, CAST(0 AS DECIMAL))) - SUM(COALESCE(m.moins, CAST(0 AS DECIMAL)))
    ) AS DECIMAL(30, 2)) AS solde,
    lp.nom,
    lp.prenom,
    lp.id AS idpersonnel
  FROM public.mouvementabsence AS m
  LEFT JOIN public.log_personnel AS lp
    ON CAST(lp.id AS TEXT) = CAST(m.idpersonnel AS TEXT)
  WHERE
    CAST(m.idsource AS TEXT) = CAST('TYP000004' AS TEXT)
  GROUP BY
    lp.nom,
    lp.prenom,
    lp.id
) AS sc
  ON l.id = sc.idpersonnel
LEFT JOIN public.departement AS dp
  ON paie.iddepartement = dp.id
LEFT JOIN public.qualification_paie AS qp
  ON qp.id = paie.idqualification;

-- Niveau 11 - vue 4 / 8 : LOG_PERSONNEL_FIN_CONGE
-- Dependances nouvelles : SOLDECONGEPRIS_PERS.
CREATE VIEW public.log_personnel_fin_conge (
    "id", "permis_conduire", "chemin_permis", "remarque", "id_pers", "nom", "prenom", "date_naissance", "sexe", "numero_cin", "date_cin", "date_dupl_cin", "nationalite", "adresse", "fokotany", "acte_naissance", "direction", "service", "code_dr", "matricule", "idcategorie", "ctg", "indicegrade", "indice_fonctionnel", "statut", "categorieval", "ctgval", "numero_cnaps", "numero_ostie", "temporaire", "droit", "prie", "resteconge", "etat", "idpersonnel", "iddirection", "iddepartement", "departementlib", "idqualification", "qualificationlib", "etatlib"
) AS
SELECT
  l.id AS id,
  l.permis_conduire AS permis_conduire,
  l.chemin_permis AS chemin_permis,
  l.remarque AS remarque,
  l.id_pers AS id_pers,
  l.nom AS nom,
  l.prenom AS prenom,
  l.date_naissance AS date_naissance,
  sex.desce AS sexe,
  l.numero_cin AS numero_cin,
  l.date_cin AS date_cin,
  l.date_dupl_cin AS date_dupl_cin,
  l.nationalite AS nationalite,
  l.adresse AS adresse,
  l.fokotany AS fokotany,
  l.acte_naissance AS acte_naissance,
  d.val AS direction,
  s.libelle AS service,
  s.code_dr AS code_dr,
  CAST(paie.matricule AS TEXT) AS matricule,
  paie.idcategorie AS idcategorie,
  paie.ctg AS ctg,
  paie.indicegrade AS indicegrade,
  paie.indice_fonctionnel AS indice_fonctionnel,
  paie.statut AS statut,
  c.taux AS categorieval,
  CAST(NULL AS TEXT) AS ctgval,
  paie.numero_cnaps AS numero_cnaps,
  paie.numero_ostie AS numero_ostie,
  CASE
    WHEN paie.temporaire = -1
    THEN 'Temporaire'
    WHEN paie.temporaire = 0
    THEN 'Permanent'
    WHEN paie.temporaire = 1
    THEN 'Cadre'
    ELSE NULL
  END AS temporaire,
  CAST(COALESCE(sc.plus, 0) AS DECIMAL(30, 2)) AS droit,
  CAST(COALESCE(sp.congepris, 0) AS DECIMAL(30, 2)) AS prie,
  CAST(COALESCE(sc.solde, 0) AS DECIMAL(30, 2)) AS resteconge,
  paie.etat AS etat,
  l.id AS idpersonnel,
  l.direction AS iddirection,
  dp.id AS iddepartement,
  dp.val AS departementlib,
  qp.id AS idqualification,
  qp.val AS qualificationlib,
  CASE
    WHEN paie.etat < 1
    THEN 'Debauches'
    WHEN paie.etat = 1
    THEN 'A Valider'
    WHEN paie.etat = 11
    THEN 'Valides'
    ELSE NULL
  END AS etatlib
FROM public.log_personnel AS l
LEFT JOIN public.log_service AS s
  ON l.service = s.id
LEFT JOIN public.paie_info_personnel AS paie
  ON paie.id = l.id
LEFT JOIN public.sexe AS sex
  ON l.sexe = sex.id
LEFT JOIN public.log_direction AS d
  ON d.id = l.direction
LEFT JOIN public.paie_categorie AS c
  ON c.id = paie.idcategorie
LEFT JOIN public.soldecongepris_pers AS sp
  ON l.id = sp.id
LEFT JOIN (
  SELECT
    CAST(SUM(COALESCE(m.plus, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS plus,
    CAST(SUM(COALESCE(m.moins, CAST(0 AS DECIMAL))) AS DECIMAL(30, 2)) AS moins,
    CAST((
      SUM(COALESCE(m.plus, CAST(0 AS DECIMAL))) - SUM(COALESCE(m.moins, CAST(0 AS DECIMAL)))
    ) AS DECIMAL(30, 2)) AS solde,
    lp.nom,
    lp.prenom,
    lp.id AS idpersonnel
  FROM public.mouvementabsence AS m
  LEFT JOIN public.log_personnel AS lp
    ON CAST(lp.id AS TEXT) = CAST(m.idpersonnel AS TEXT)
  WHERE
    CAST(m.idsource AS TEXT) = CAST('TYP000004' AS TEXT)
  GROUP BY
    lp.nom,
    lp.prenom,
    lp.id
) AS sc
  ON l.id = sc.idpersonnel
LEFT JOIN public.departement AS dp
  ON paie.iddepartement = dp.id
LEFT JOIN public.qualification_paie AS qp
  ON qp.id = paie.idqualification;

-- Niveau 11 - vue 5 / 8 : RELEVECLIENT
-- Dependances nouvelles : AVOIRFCLIB_CPL_VISEE, MOUVEMENTCAISSE_DETAIL_UNIQUE.
CREATE VIEW public.releveclient (
    "id", "journal", "reference", "daty", "libelle", "lettre", "debit", "credit", "idclient", "clientlib", "compte", "updated_at", "solde", "annee", "motsclesss"
) AS
SELECT
  sq.id AS id,
  sq.journal AS journal,
  sq.reference AS reference,
  sq.daty AS daty,
  sq.libelle AS libelle,
  sq.lettre AS lettre,
  CAST(sq.debit AS DECIMAL(30, 5)) AS debit,
  CAST(sq.credit AS DECIMAL(30, 5)) AS credit,
  sq.idclient AS idclient,
  sq.clientlib AS clientlib,
  sq.compte AS compte,
  sq.updated_at AS updated_at,
  CAST(sq.solde AS DECIMAL(30, 5)) AS solde,
  sq.annee AS annee,
  NULLIF(
    CONCAT(
      COALESCE(CAST(sq.id AS TEXT), NULL),
      ' | ',
      COALESCE(CAST(sq.journal AS TEXT), NULL),
      ' | ',
      COALESCE(CAST(sq.reference AS TEXT), NULL),
      ' | ',
      COALESCE(TO_CHAR(sq.daty, 'YYYY-MM-DD HH24:MI:SS'), NULL),
      ' | ',
      COALESCE(CAST(sq.libelle AS TEXT), NULL),
      ' | ',
      COALESCE(CAST(sq.lettre AS TEXT), NULL),
      ' | ',
      COALESCE(
        REPLACE(
          REGEXP_REPLACE(
            (
              CASE
                WHEN POSITION('.' IN CAST((
                  sq.debit
                ) AS TEXT)) > 0
                THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                  sq.debit
                ) AS TEXT)))
                ELSE CAST((
                  sq.debit
                ) AS TEXT)
              END
            ),
            '^(-?)0[.]',
            e'\\1.'
          ),
          '.',
          ','
        ),
        NULL
      ),
      ' | ',
      COALESCE(
        REPLACE(
          REGEXP_REPLACE(
            (
              CASE
                WHEN POSITION('.' IN CAST((
                  sq.credit
                ) AS TEXT)) > 0
                THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                  sq.credit
                ) AS TEXT)))
                ELSE CAST((
                  sq.credit
                ) AS TEXT)
              END
            ),
            '^(-?)0[.]',
            e'\\1.'
          ),
          '.',
          ','
        ),
        NULL
      ),
      ' | ',
      COALESCE(CAST(sq.idclient AS TEXT), NULL),
      ' | ',
      COALESCE(CAST(sq.clientlib AS TEXT), NULL),
      ' | ',
      COALESCE(CAST(sq.compte AS TEXT), NULL),
      ' | ',
      COALESCE(TO_CHAR(sq.updated_at, 'YYYY-MM-DD HH24:MI:SS'), NULL),
      ' | ',
      COALESCE(
        REPLACE(
          REGEXP_REPLACE(
            (
              CASE
                WHEN POSITION('.' IN CAST((
                  sq.solde
                ) AS TEXT)) > 0
                THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                  sq.solde
                ) AS TEXT)))
                ELSE CAST((
                  sq.solde
                ) AS TEXT)
              END
            ),
            '^(-?)0[.]',
            e'\\1.'
          ),
          '.',
          ','
        ),
        NULL
      ),
      ' | ',
      COALESCE(
        REPLACE(
          REGEXP_REPLACE(
            (
              CASE
                WHEN POSITION('.' IN CAST((
                  sq.annee
                ) AS TEXT)) > 0
                THEN TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST((
                  sq.annee
                ) AS TEXT)))
                ELSE CAST((
                  sq.annee
                ) AS TEXT)
              END
            ),
            '^(-?)0[.]',
            e'\\1.'
          ),
          '.',
          ','
        ),
        NULL
      )
    ),
    ''
  ) AS motsclesss
FROM (
  SELECT
    relever.id AS id,
    relever.journal AS journal,
    relever.reference AS reference,
    relever.daty AS daty,
    relever.libelle AS libelle,
    relever.lettre AS lettre,
    relever.debit AS debit,
    relever.credit AS credit,
    relever.idclient AS idclient,
    t.nom AS clientlib,
    COALESCE(relever.compte, t.compte) AS compte,
    relever.updated_at AS updated_at,
    relever.solde AS solde,
    EXTRACT(YEAR FROM relever.daty) AS annee,
    ROW_NUMBER() OVER (
      PARTITION BY relever.id, relever.journal, relever.reference, relever.daty
      ORDER BY CASE
        WHEN NOT relever.lettre IS NULL AND NOT NULLIF(TRIM(relever.lettre), '') IS NULL
        THEN 0
        ELSE 1
      END
    ) AS rn
  FROM (
    /* NOTE DE CREDIT / AVOIR CLIENT */
    SELECT
      av.id AS id,
      COALESCE(cj.desce, ' ') AS journal,
      av.id AS reference,
      av.daty AS daty,
      NULLIF(CONCAT('NOTE DE CREDIT : ', av.id), '') AS libelle,
      COALESCE(cl.lettre, ' ') AS lettre,
      0 AS debit,
      av.montantttcar AS credit,
      av.idclient AS idclient,
      sous.compte AS compte,
      av.daty AS updated_at,
      av.montantttcar * -1 AS solde
    FROM public.avoirfclib_cpl_visee AS av
    JOIN public.compta_ecriture AS ecr
      ON ecr.idobjet = av.id
    JOIN public.compta_sous_ecriture AS sous
      ON sous.idmere = ecr.id
    LEFT JOIN public.compta_lettrage AS cl
      ON cl.id = sous.lettrage
    LEFT JOIN public.compta_journal AS cj
      ON cj.id = sous.journal
    WHERE
      sous.compte LIKE '411%'
    UNION ALL
    /* FACTURE / VENTE CLIENT */
    SELECT
      mcd.id AS id,
      COALESCE(cj.desce, ' ') AS journal,
      mcd.numerofacture AS reference,
      mcd.daty AS daty,
      COALESCE(mcd.references_paiement, ' ') AS libelle,
      COALESCE(cl.lettre, ' ') AS lettre,
      mcd.montantttcar AS debit,
      0 AS credit,
      mcd.idclient AS idclient,
      sous.compte AS compte,
      CAST(mcd.updated_at AS TIMESTAMP) AS updated_at,
      mcd.montantttcar AS solde
    FROM public.mouvementcaisse_detail_unique AS mcd
    JOIN public.compta_ecriture AS ecr
      ON ecr.idobjet = mcd.id
    JOIN public.compta_sous_ecriture AS sous
      ON sous.idmere = ecr.id
    LEFT JOIN public.compta_lettrage AS cl
      ON cl.id = sous.lettrage
    LEFT JOIN public.compta_journal AS cj
      ON cj.id = sous.journal
    WHERE
      mcd.etat >= 7 AND sous.compte LIKE '411%'
    UNION ALL
    /* REGLEMENT CLIENT */
    SELECT
      mc.id AS id,
      COALESCE(cj.desce, ' ') AS journal,
      mc.id AS reference,
      mc.datycomptabilisation AS daty,
      mc.designation AS libelle,
      COALESCE(cl.lettre, ' ') AS lettre,
      0 AS debit,
      mc.credit AS credit,
      mc.idtiers AS idclient,
      sous.compte AS compte,
      CAST(mc.updated_at AS TIMESTAMP) AS updated_at,
      mc.credit * -1 AS solde
    FROM (
      SELECT
        m.id,
        m.designation,
        m.idcaisse,
        c.val AS idcaisselib,
        m.idventedetail,
        m.idvirement,
        m.debit,
        m.credit,
        CAST(CASE
          WHEN m.credit > CAST(0 AS DECIMAL)
          THEN COALESCE(m.credit, CAST(0 AS DECIMAL)) - COALESCE(l.montant, CAST(0 AS DECIMAL))
          ELSE CAST(0 AS DECIMAL)
        END AS DECIMAL(36, 5)) AS soldecredit,
        CAST(CASE
          WHEN m.debit > CAST(0 AS DECIMAL)
          THEN COALESCE(m.debit, CAST(0 AS DECIMAL)) - COALESCE(l.montant, CAST(0 AS DECIMAL))
          ELSE CAST(0 AS DECIMAL)
        END AS DECIMAL(36, 5)) AS soldedebit,
        m.daty,
        m.etat,
        CASE
          WHEN m.etat = CAST(0 AS DECIMAL)
          THEN CAST('ANNULEE' AS TEXT)
          WHEN m.etat = CAST(1 AS DECIMAL)
          THEN CAST('CREEE' AS TEXT)
          WHEN m.etat = CAST(11 AS DECIMAL)
          THEN CAST('VALIDEE' AS TEXT)
          WHEN m.etat = CAST(8 AS DECIMAL)
          THEN CAST('A COMPTABILISER' AS TEXT)
          ELSE CAST(NULL AS TEXT)
        END AS etatlib,
        vd.idvente,
        m.idorigine,
        m.idtiers,
        t.nom AS tiers,
        m.idprevision,
        m.idop,
        m.taux,
        m.compte,
        m.iddevise,
        m.idtraite,
        mp.val AS idmodepaiementlib,
        m.idmvtcaissemere,
        m.reference,
        m.datycomptabilisation,
        m.updated_at,
        m.heure,
        m.idreport,
        point.id AS idpoint,
        point.val AS idpointlib,
        NULLIF(
          CONCAT(
            (
              NULLIF(
                CONCAT(
                  (
                    NULLIF(
                      CONCAT(
                        (
                          NULLIF(
                            CONCAT(
                              (
                                NULLIF(
                                  CONCAT(
                                    (
                                      NULLIF(
                                        CONCAT(
                                          (
                                            NULLIF(
                                              CONCAT(
                                                (
                                                  NULLIF(
                                                    CONCAT(
                                                      (
                                                        NULLIF(
                                                          CONCAT((
                                                            NULLIF(CONCAT(CAST(m.id AS TEXT), CAST(NULL AS TEXT)), '')
                                                          ), m.daty),
                                                          ''
                                                        )
                                                      ),
                                                      CAST(NULL AS TEXT)
                                                    ),
                                                    ''
                                                  )
                                                ),
                                                CAST(m.designation AS TEXT)
                                              ),
                                              ''
                                            )
                                          ),
                                          CAST(NULL AS TEXT)
                                        ),
                                        ''
                                      )
                                    ),
                                    CAST(t.nom AS TEXT)
                                  ),
                                  ''
                                )
                              ),
                              CAST(NULL AS TEXT)
                            ),
                            ''
                          )
                        ),
                        CAST(m.idcaisse AS TEXT)
                      ),
                      ''
                    )
                  ),
                  CAST(NULL AS TEXT)
                ),
                ''
              )
            ),
            CAST(c.val AS TEXT)
          ),
          ''
        ) AS motsclesss
      FROM public.mouvementcaisse AS m
      LEFT JOIN public.caisse AS c
        ON CAST(c.id AS TEXT) = CAST(m.idcaisse AS TEXT)
      LEFT JOIN public.vente_details AS vd
        ON CAST(vd.id AS TEXT) = CAST(m.idventedetail AS TEXT)
      LEFT JOIN public.tiers AS t
        ON CAST(t.id AS TEXT) = CAST(m.idtiers AS TEXT)
      LEFT JOIN public.liaisonpaiementmvtcaissegrp AS l
        ON CAST(l.idmvtcaisse AS TEXT) = CAST(m.id AS TEXT)
      LEFT JOIN public.modepaiement AS mp
        ON CAST(m.idmodepaiement AS TEXT) = CAST(mp.id AS TEXT)
      LEFT JOIN public.point AS point
        ON CAST(point.id AS TEXT) = CAST(c.idpoint AS TEXT)
    ) AS mc
    JOIN public.compta_ecriture AS ecr
      ON ecr.idobjet = mc.id
    JOIN public.compta_sous_ecriture AS sous
      ON sous.idmere = ecr.id
    LEFT JOIN public.compta_lettrage AS cl
      ON cl.id = sous.lettrage
    LEFT JOIN public.compta_journal AS cj
      ON cj.id = sous.journal
    WHERE
      mc.etat > 8 AND sous.compte LIKE '411%'
  ) AS relever
  LEFT JOIN public.tiers AS t
    ON t.id = relever.idclient
) AS sq
WHERE
  sq.rn = 1;

