    "idmagasin", "idmagasinlib", "daty", "ca_jour", "ca_veille", "evolution_pct", "difference_montant", "moislib", "anneelib", "moisanneelib", "ventes_jour", "ventes_veille", "evolution_ventes_pct", "difference_ventes"
