  CASE
    WHEN COALESCE(SUM(v_hier.montanttotal), 0) = 0
    THEN 100
    ELSE ROUND(
      CAST((
        CAST((
          SUM(v_today.montanttotal) - COALESCE(SUM(v_hier.montanttotal), 0)
        ) AS DECIMAL) / COALESCE(SUM(v_hier.montanttotal), 1)
      ) * 100 AS DECIMAL),
      2
    )
  END AS evolution_pct,
  SUM(v_today.montanttotal) - COALESCE(SUM(v_hier.montanttotal), 0) AS difference_montant,
  v_today.moislib AS moislib,
  v_today.anneelib AS anneelib,
  v_today.moisanneelib AS moisanneelib,
  SUM(v_today.nb) AS ventes_jour,
  SUM(v_hier.nb) AS ventes_veille,
  CASE
    WHEN COALESCE(SUM(v_hier.nb), 0) = 0
    THEN 100
    ELSE ROUND(
      CAST((
        CAST((
          SUM(v_today.nb) - COALESCE(SUM(v_hier.nb), 0)
        ) AS DECIMAL) / COALESCE(SUM(v_hier.nb), 1)
      ) * 100 AS DECIMAL),
      2
    )
  END AS evolution_ventes_pct,
  SUM(v_today.nb) - COALESCE(SUM(v_hier.nb), 0) AS difference_ventes
FROM public.vente_ca AS v_today
LEFT JOIN public.vente_ca AS v_hier
  ON v_hier.daty = (
    v_today.daty - (
      1
    ) * INTERVAL '1 DAY'
  )
  AND v_hier.idmagasin = v_today.idmagasin
GROUP BY
  v_today.idmagasin,
  v_today.idmagasinlib,
  v_today.daty,
  v_today.moislib,
  v_today.anneelib,
  v_today.moisanneelib
ORDER BY
