  )
  AND v_hier.idmagasin = v_today.idmagasin
GROUP BY
  v_today.idmagasin,
  v_today.idmagasinlib,
  v_today.daty,
  v_today.mois,
  v_today.annee,
  v_today.moisannee
ORDER BY
  daty DESC;

COMMIT;

