        'public.log_personnel_fin_valide', 'public.organigramme', 'public.paie_fonction', 'public.paie_info_personnel'
    ]::text[]) AS r(nom)
    WHERE pg_catalog.to_regclass(r.nom::cstring) IS NULL;
