-- Niveau 13 - vue 1 / 1 : ORGANIGRAMMELIB
-- Dependances nouvelles : LOG_PERSONNEL_FIN_VALIDE.
CREATE VIEW public.organigrammelib (
    "id", "desce", "val", "nompersonne", "matricule", "poste"
) AS
SELECT
  o.id AS id,
  o.desce AS desce,
  lp.id AS val,
  NULLIF(CONCAT((
    NULLIF(CONCAT(lp.nom, ' '), '')
  ), lp.prenom), '') AS nompersonne,
  lp.matricule AS matricule,
  pf.desce AS poste
FROM public.log_personnel_fin_valide AS lp
LEFT JOIN public.organigramme AS o
  ON lp.id = o.val
LEFT JOIN public.paie_info_personnel AS pip
  ON pip.id = lp.id
LEFT JOIN public.paie_fonction AS pf
  ON pf.id = pip.idfonction
ORDER BY
  o.desce DESC NULLS LAST;

COMMIT;

