CREATE VIEW public.travaux_recap ("id", "montantchargeexterne", "montantpiece", "montantmaindoeuvre", "montanttotal") AS
WITH fac_agg AS (
  SELECT idtravaux,
         SUM(COALESCE(montantttc, 0)) AS montantChargeExterne
  FROM FACTUREFOURNISSEURCPL_TRAVAUX
  GROUP BY idtravaux
),
mvt_agg AS (
  SELECT idobjet,
         SUM(COALESCE(montantsortie, 0)) AS montantPiece
  FROM MVTSTOCKLIB
  GROUP BY idobjet
),
pm_agg AS (
  SELECT idtravaux,
         SUM(COALESCE(montantreel, 0)) AS montantMainDoeuvre
  FROM RAPPROCHEMENTTRAVAUX
  GROUP BY idtravaux
)
SELECT t.id,
       COALESCE(fac_agg.montantChargeExterne, 0) AS montantChargeExterne,
       COALESCE(mvt_agg.montantPiece, 0)         AS montantPiece,
       COALESCE(pm_agg.montantMainDoeuvre, 0)    AS montantMainDoeuvre,
       COALESCE(fac_agg.montantChargeExterne, 0)
           + COALESCE(mvt_agg.montantPiece, 0)
           + COALESCE(pm_agg.montantMainDoeuvre, 0)    AS montantTotal
FROM TRAVAUX t
         LEFT JOIN fac_agg ON fac_agg.idtravaux = t.id
         LEFT JOIN mvt_agg ON mvt_agg.idobjet   = t.id
         LEFT JOIN pm_agg  ON pm_agg.idtravaux  = t.id;
CREATE VIEW public.coutsmaintenance ("idmachine", "nommachine", "idligne", "idlignelib", "idtravaux", "daty", "couttotal") AS
SELECT
    o.IDINGREDIENTS AS idMachine,
    aim.DESCRIPTIONOBJET AS nomMachine,
    l.ID AS IDLIGNE ,
    l.VAL AS IDLIGNELIB,
    tr.ID AS idTravaux,
    t.DATY ,
    CAST (tr.MONTANTTOTAL AS NUMERIC(10,2)) AS CoutTotal
FROM TRAVAUX_RECAP tr
         LEFT JOIN TRAVAUX t
                   ON tr.id = t.ID
         LEFT JOIN ORDRETRAVAUXFILLE o
                   ON t.IDOFFILLE = o.id
         LEFT JOIN AS_INGREDIENT_MAINTENANCE aim
                   ON o.IDINGREDIENTS = aim.ID
         LEFT JOIN LIGNE l
                   ON aim.IDLIGNE = l.ID
WHERE o.IDINGREDIENTS IS NOT NULL;
CREATE VIEW public.bc_client_fille_cpl_lib_pdf ("id", "produit", "idbc", "quantite", "pu", "montant", "tva", "remise", "iddevise", "unite", "produitlib", "compte", "qtereste", "unitelib", "montanttotal", "montantdelaremise", "montantristourne", "montantremise", "montanttva", "montantttc", "ristourne", "fraistransport", "poidstotal", "puingredient", "contenue", "unite2") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDBC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       i.LIBELLEVENTE                                                                                                                                      AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       COALESCE(bcf.quantite, 0)    - COALESCE(vdbc.qte, 0)    AS qtereste,   -- nanova qte reste : atao moins qte vendu  avy aminy vente_details_qte_grp
       au.val                                                                                                                                         AS UNITELIB,
       cast(COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0) as NUMERIC(30, 2))                                                                                   AS MONTANTTOTAL,
       cast(((COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as NUMERIC(30, 2))                                                          as montantdelaremise,
       cast((COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0) - ((COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
            (bcf.ristourne / 100) as NUMERIC(30, 2))                                                                                                   as montantristourne,
       cast(COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0) - ((COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as NUMERIC(30, 2))                                                                    as montantremise,
       CAST(
               (((COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0)) -
                 (((COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) +
                  ((COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0) -
                    ((COALESCE(bcf.PU, 0) * COALESCE(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.ristourne / 100))) -
                 COALESCE(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) *
                (COALESCE(bcf.TVA, 0) / 100))
           AS NUMERIC(30, 2)
       )                                                                                                                                              AS MONTANTTVA,
       cast((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * COALESCE(bcf.remise, 0)) / 100 as NUMERIC(30, 2)) -
             (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * COALESCE(bcf.remise, 0)) / 100 as NUMERIC(30, 2)) *
              COALESCE(bcf.ristourne, 0) /
              100) - COALESCE(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (COALESCE(bcf.TVA, 0) / 100) *
                                                                             (cast((bcf.quantite * bcf.PU) -
                                                                                   ((bcf.quantite * bcf.PU) * COALESCE(bcf.remise, 0)) /
                                                                                   100 as NUMERIC(30, 2)) -
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * COALESCE(bcf.remise, 0)) /
                                                                                    100 as NUMERIC(30, 2)) *
                                                                               COALESCE(bcf.ristourne, 0) / 100) -
                                                                              COALESCE(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) as NUMERIC(30, 2)) AS MONTANTTTC,
       bcf.ristourne,
       COALESCE(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(COALESCE(i.CALORIE * bcf.QUANTITE,0) AS NUMERIC(30,2)) AS poidstotal,
       CAST((bcf.pu/COALESCE(eq.QUANTITE,1)) AS NUMERIC(30,2)) as puingredient,
       COALESCE(eq.QUANTITE,1) as contenue,
       i.UNITE2
FROM bondecommande_client_fille bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN BONDECOMMANDE_CLIENT bc on bc.id = bcf.IDBC
         LEFT JOIN EQUIVALENCEVENTE eq on eq.IDPRODUIT1=i.ID;
CREATE VIEW public.stocketdepensefabnc ("idobjet", "idproduit", "entree", "sortie", "pu", "montantentree", "montantsortie", "idmere", "id", "categorieingredient", "categorieingredientlib") AS
select mvt.IDOBJET, fille.IDPRODUIT,cast(sum(ENTREE) as NUMERIC(15,2)) as entree, cast(sum(SORTIE) as NUMERIC(15,2)) as sortie, cast(avg(fille.pu) as NUMERIC(30,2)) as pu,
cast(COALESCE(avg(fille.pu)*sum(entree),0) as NUMERIC(30,3)) as montantentree,cast(COALESCE(avg(fille.pu)*sum(sortie),0) as NUMERIC(30,3)) as montantsortie,ofille.IDMERE,ofille.id, cat.id AS CATEGORIEINGREDIENT, cat.val AS CATEGORIEINGREDIENTLIB
from MVTSTOCKFILLE fille
left join MvtStockLib mvt on fille.IDMVTSTOCK=mvt.ID
left join FABRICATION fab on mvt.IDOBJET=fab.ID
left join OFFILLE ofille on fab.IDOFFILLE=ofille.ID
left join AS_INGREDIENTS ai on fille.IDPRODUIT=ai.id
LEFT JOIN CATEGORIEINGREDIENT cat ON cat.id = ai.CATEGORIEINGREDIENT 
where mvt.ETAT>=11  and ai.COMPOSE=0
group by fille.IDPRODUIT,mvt.IDOBJET,ofille.IDMERE,ofille.id,ai.COMPOSE, cat.id, cat.val
union all
select c.IDFABRICATION as idobjet,c.IDINGREDIENTS as IDPRODUIT,cast(0 as NUMERIC(15,2)) as entree,cast(1 as NUMERIC(15,2)) as sortie,cast(c.montant as NUMERIC(30,2)) as pu,cast(0 as NUMERIC(30,3)) as montantentree,cast(COALESCE(sum(c.montant),0) as NUMERIC(30,3)) as montantsortie
,ofile.IDMERE,ofile.id, cat.id AS CATEGORIEINGREDIENT, cat.val AS CATEGORIEINGREDIENTLIB
from chargemontant c
left join fabrication fabb on c.IDFABRICATION=fabb.id
left join OFFILLE ofile on fabb.IDOFFILLE=ofile.ID
LEFT JOIN AS_INGREDIENTS ai ON c.IDINGREDIENTS = ai.id
LEFT JOIN CATEGORIEINGREDIENT cat ON cat.id = ai.CATEGORIEINGREDIENT 
where c.etat>=11 group by c.IDFABRICATION, c.IDINGREDIENTS,ofile.IDMERE,ofile.id, cat.id, cat.val,c.montant
UNION all
select 
    rsfab.IDFABRICATION as idobjet,
    'IG000364' as IDPRODUIT,
    cast(0 as NUMERIC(15,2)) as entree,
    CAST(
        COALESCE(
            CASE 
                WHEN h.TEMPORAIRE = 0 THEN h.MN + h.JF + h.HD + h.IF + h.HEURENORMALE
                ELSE h.HS + h.MN + h.JF + h.HD + h.IF
            END,
        0) AS NUMERIC(15,2)
    ) AS sortie,
    cast(rsfab.TAUXHORAIRE as NUMERIC(30,2)) as pu,
    cast(0 as NUMERIC(30,3)) as montantentree,
    cast(COALESCE(h.MONTANT, 0) as NUMERIC(30,3)) as montantsortie,
    off.IDMERE,
    off.ID,
    'CATING000001' as CATEGORIEINGREDIENT,
    'Charge personnelle' as CATEGORIEINGREDIENTLIB
from HEURESUPFABRICATION h
left join RESSOURCEPARFABRICATIONCOMPLET rsfab ON rsfab.IDRESSOURCE = h.IDRESSPARFAB
left join FABRICATION f on rsfab.idfabrication = f.ID
left join OFFILLE off on f.IDOFFILLE = off.ID
where h.ETAT >= 11;
CREATE VIEW public.stocketdepensefab ("idobjet", "idproduit", "entree", "sortie", "pu", "montantentree", "montantsortie", "idmere", "id", "categorieingredient", "categorieingredientlib") AS
select idobjet,IDPRODUIT,cast(entree as NUMERIC(30,5)) as entree,cast(sortie as NUMERIC(30,5)) as sortie,cast(pu as NUMERIC(30,5)) as pu,
       cast(montantentree as NUMERIC(30,5)) as montantentree,cast(montantsortie as NUMERIC(30,5)) as montantsortie,IDMERE,id, CATEGORIEINGREDIENT,CATEGORIEINGREDIENTLIB
from STOCKETDEPENSEFABNC;
CREATE VIEW public.as_recettefablibst ("id", "idingredients", "unite", "qteav", "quantite", "idproduits", "libingredients", "typestock", "sortie", "reste") AS
select th.ID,th.IDINGREDIENTS,th.UNITE,th.QTEAV,th.QUANTITE,th.IDPRODUITS,th.LIBINGREDIENTS,th.TYPESTOCK,cast(COALESCE(st.sortie,0) as NUMERIC(30,2)) as sortie,cast(th.QUANTITE-COALESCE(st.sortie,0) as NUMERIC(30,2)) as reste from as_recetteFabLib th
    left join stockEtDepenseFab st on st.IDOBJET=th.IDPRODUITS and st.IDPRODUIT=th.IDINGREDIENTS;
CREATE VIEW public.stockdepenseoffab ("idobjet", "idproduit", "entree", "sortie", "pu", "montanentree", "montantsortie", "idmere", "id", "categorieingredient", "categorieingredientlib") AS
select idmere as idobjet,sdf.IDPRODUIT,cast(sum(sdf.entree) as NUMERIC(30,5)) as entree,cast(sum(sdf.sortie) as NUMERIC(30,5)) as sortie, cast(avg(sdf.pu) as NUMERIC(30,5)) as pu,
                                                                                                                                             sum(montantentree) as montanentree, sum(montantsortie) as montantsortie,idmere,CAST('-' AS text) AS id, sdf.categorieingredient, sdf.categorieingredientlib
                                                                                                                                             from STOCKETDEPENSEFAB sdf
                                                                                                                                             group by sdf.IDPRODUIT,idmere, sdf.categorieingredient, sdf.categorieingredientlib;
CREATE VIEW public.stockdepenseoffillefab ("idobjet", "idproduit", "entree", "sortie", "pu", "montanentree", "montantsortie", "idmere", "id", "categorieingredient", "categorieingredientlib") AS
select id as idobjet,sdf.IDPRODUIT,cast(sum(sdf.entree) as NUMERIC(30,5)) as entree,cast(sum(sdf.sortie) as NUMERIC(30,5)) as sortie, cast(avg(sdf.pu) as NUMERIC(30,5)) as pu,
       sum(montantentree) as montanentree, sum(montantsortie) as montantsortie,idmere,CAST('-' AS text) AS id, sdf.categorieingredient, sdf.categorieingredientlib
from STOCKETDEPENSEFAB sdf
group by sdf.IDPRODUIT,id, sdf.categorieingredient, sdf.categorieingredientlib,idmere;
CREATE VIEW public.stocketdepensefabthe ("idobjet", "idproduit", "designation", "entree", "sortie", "pu", "montantentree", "montantsortie", "idmere", "id", "qteth", "puth", "montth", "categorieingredient") AS
SELECT
    sed.IDOBJET,
    sed.IDPRODUIT,
    ai.libelle AS designation,
    cast(sed.ENTREE as NUMERIC(30,5)) as entree ,
    cast(sed.SORTIE as NUMERIC(30,5)) as sortie,
    CAST(
            CASE
                WHEN COALESCE(sed.PU,0) = 0 THEN recFab.pu
                ELSE COALESCE(sed.PU,0)
                END
        as NUMERIC(30,2)) AS PU,
    cast(sed.MONTANTENTREE as NUMERIC(30,5)) as MONTANTENTREE,
    CAST(
            CASE
                WHEN COALESCE(sed.PU,0) = 0 THEN recFab.pu * sed.SORTIE
                ELSE COALESCE(sed.PU,0) * sed.SORTIE
                END
        as NUMERIC(30,2)) as MONTANTSORTIE ,
    sed.IDMERE,
    sed.ID,
    CAST(COALESCE(recFab.QUANTITE, 0) AS NUMERIC(30,
                                           10)) AS qteTh,
    CAST(COALESCE(recFab.QTEAV, sed.pu) AS NUMERIC(30,
                                             5)) AS puth,
    CAST(COALESCE(recFab.QUANTITE, 0)* COALESCE(recFab.QTEAV, 0) AS NUMERIC(30,
                                                                 5)) AS montTh,
    recFab.CATEGORIEINGREDIENT
FROM
    stockEtDepenseFab sed
        FULL OUTER JOIN as_recFabLibGroupe recFab
                        ON
                            sed.IDOBJET = recFab.IDPRODUITS
                                AND sed.IDPRODUIT = recFab.IDINGREDIENTS 
        LEFT JOIN as_ingredients ai ON ai.id = sed.idproduit;
CREATE VIEW public.stocketdepensefabthecat ("idobjet", "idproduit", "entree", "sortie", "pu", "montantentree", "montantsortie", "idmere", "id", "qteth", "puth", "montth", "categorieingredient", "idcategorieingredient") AS
select std.IDOBJET,std.IDPRODUIT,std.ENTREE,std.SORTIE,std.PU,std.MONTANTENTREE,std.MONTANTSORTIE,std.IDMERE,std.ID,std.QTETH,std.PUTH,std.MONTTH,cat.VAL as CATEGORIEINGREDIENT, ing.CATEGORIEINGREDIENT IDCATEGORIEINGREDIENT from stockEtDepenseFabThe std
                                                                                                                                                                                                                                         left join AS_INGREDIENTS ing on std.IDPRODUIT=ing.id
                                                                                                                                                                                                                                         left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id;
CREATE VIEW public.stocketdepfabthecatgroupe ("idobjet", "categorieingredient", "idcategorieingredient", "montantsortie", "montth", "ecart") AS
select st.IDOBJET ,st.CATEGORIEINGREDIENT,st.idcategorieingredient,cast(sum(montantsortie) as NUMERIC(30,2)) as montantSortie,cast(sum(montth) as NUMERIC(30,2)) as montth, cast(sum(montth)-sum(montantsortie) as NUMERIC(30,2)) as ecart
  from stockEtDepenseFabTheCat st
  group by st.idobjet,st.CATEGORIEINGREDIENT,st.idcategorieingredient;
CREATE VIEW public.rapprochement_completfab ("idobjet", "categorieingredient", "idcategorieingredient", "montantsortie", "montth", "ecart") AS
select st.IDOBJET ,st.CATEGORIEINGREDIENT,st.idcategorieingredient,cast(sum(montantsortie) as NUMERIC(30,2)) as montantSortie,cast(sum(montth) as NUMERIC(30,2)) as montth, cast(sum(montth)-sum(montantsortie) as NUMERIC(30,2)) as ecart
from stockEtDepenseFabTheCat st
group by st.idobjet,st.CATEGORIEINGREDIENT,st.idcategorieingredient

UNION ALL
SELECT
    hs.idMere,
    'Charge personnelle' as CATEGORIE,
    hs.CATEGORIE as idCategorieIngredient,
    hs.montantPersonnel AS montantSortie,
    0 AS montth,
    -hs.montantPersonnel AS ecart
FROM HS_PAR_FAB hs;
CREATE VIEW public.stocketdepenseoffabthe ("idobjet", "idproduit", "designation", "entree", "sortie", "pu", "montanentree", "montantsortie", "idmere", "id", "qteth", "puth", "montth", "categorieingredient", "categorieingredientlib") AS
select
    sed.IDOBJET,
    sed.IDPRODUIT,
    COALESCE(recFab.LIBINGREDIENTS,ai.LIBELLE) AS designation,
    CAST(sed.ENTREE as NUMERIC(30,5)) AS ENTREE ,
    CAST(sed.SORTIE as NUMERIC(30,5))  AS SORTIE ,
    CAST(
            CASE
                WHEN COALESCE(sed.PU,0) = 0 THEN recFab.pu
                ELSE COALESCE(sed.PU,0)
                END
        as NUMERIC(30,2)) AS PU,
    CAST(sed.MONTANENTREE as NUMERIC(30,5)) AS MONTANENTREE ,
    CAST(
            CASE
                WHEN COALESCE(sed.PU,0) = 0 THEN recFab.pu * sed.SORTIE
                ELSE COALESCE(sed.PU,0) * sed.SORTIE
                END
        as NUMERIC(30,2))  AS MONTANTSORTIE,
    sed.IDMERE,
    sed.ID,
    cast(COALESCE(recFab.QUANTITE,0) as NUMERIC(30,10)) as qteTh,
    cast(COALESCE(recFab.QTEAV,sed.pu) as NUMERIC(30,5)) as puth,
    cast(COALESCE(recFab.QUANTITE,0)*COALESCE(recFab.QTEAV,0) as NUMERIC(30,5)) as montTh,
    sed.CATEGORIEINGREDIENT,
    sed.CATEGORIEINGREDIENTLIB
from stockDepenseOfFab sed full
                               outer join AS_RECFOFABLIBGROUPE recFab
                                          on sed.IDOBJET=recFab.IDPRODUITS and sed.IDPRODUIT=recFab.IDINGREDIENTS
                           LEFT JOIN AS_INGREDIENTS ai ON ai.ID = sed.IDOBJET OR ai.ID =  sed.IDPRODUIT;
CREATE VIEW public.stocketdepenseoffabthecat ("idobjet", "idproduit", "entree", "sortie", "pu", "montanentree", "montantsortie", "idmere", "id", "qteth", "puth", "montth", "categorieingredient", "idcategorieingredient") AS
SELECT
    std.IDOBJET,
    std.IDPRODUIT,
    std.ENTREE,
    std.SORTIE,
    std.PU,
    std.MONTANENTREE,
    std.MONTANTSORTIE,
    std.IDMERE,
    std.ID,
    std.QTETH,
    std.PUTH,
    std.MONTTH,
    cat.VAL as CATEGORIEINGREDIENT,
    cat.ID AS idcategorieingredient
from stockEtDepenseOfFabThe std
         left join AS_INGREDIENTS ing on std.IDPRODUIT=ing.id
         left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id;
CREATE VIEW public.stocketdepoffabthecatgroupe ("idmere", "categorieingredient", "idcategorieingredient", "montantsortie", "montth", "ecart") AS
select
    st.idmere,
    st.CATEGORIEINGREDIENT,
    st.idcategorieingredient,
    cast(sum(montantsortie) as NUMERIC(30,2)) as montantSortie,
    cast(sum(montth) as NUMERIC(30,2)) as montth,
    cast(sum(montth)-sum(montantsortie) as NUMERIC(30,2)) as ecart
from stockEtDepenseOfFabTheCat st
group by st.idmere,st.CATEGORIEINGREDIENT, st.idcategorieingredient;
CREATE VIEW public.rapprochement_complet ("idmere", "categorieingredient", "idcategorieingredient", "montantsortie", "montth", "ecart") AS
SELECT
    st.idmere,
    st.CATEGORIEINGREDIENT AS categorieIngredient,
    st.idcategorieingredient,
    CAST(SUM(montantsortie) AS NUMERIC(30,2)) AS montantSortie,
    CAST(SUM(montth) AS NUMERIC(30,2)) AS montth,
    CAST(SUM(montth)-SUM(montantsortie) AS NUMERIC(30,2)) AS ecart
FROM stockEtDepenseOfFabTheCat st
GROUP BY st.idmere, st.CATEGORIEINGREDIENT, st.idcategorieingredient

UNION ALL

SELECT
    hs.idMere,
    'Charge personnelle' as CATEGORIE,
    hs.CATEGORIE as idCategorieIngredient,
    hs.montantPersonnel AS montantSortie,
    0 AS montth,
    -hs.montantPersonnel AS ecart
FROM HS_PAR_OF hs;
CREATE VIEW public.v_rapprochement_of ("idobjet", "sortie", "pu", "montantsortie", "qteth", "puth", "montth", "ecartqte", "ecartmontant", "ecartpu") AS
SELECT
    IDOBJET,
    CAST(SUM(SORTIE) AS NUMERIC(30,5)) AS sortie,
    CAST(SUM(PU) AS NUMERIC(30,2)) AS pu,
    CAST(SUM(MONTANTSORTIE) AS NUMERIC(30,5)) AS montantsortie,
    CAST(SUM(QTETH) AS NUMERIC(30,5)) AS qteth,
    CAST(SUM(PUTH) AS NUMERIC(30,2)) AS puth,
    CAST(SUM(MONTTH) AS NUMERIC(30,2)) AS montth,
    CAST(SUM(SORTIE - QTETH) AS NUMERIC(30,5)) AS ecartqte,
    CAST(SUM(MONTANTSORTIE - MONTTH) AS NUMERIC(30,2)) AS ecartmontant,
    CAST(SUM(PU - PUTH) AS NUMERIC(30,2)) AS ecartpu
FROM
    STOCKETDEPENSEOFFABTHE
GROUP BY
    IDOBJET;
CREATE VIEW public.v_rapprochement_of_ia ("idobjet", "sortie", "pu", "montantsortie", "qteth", "puth", "montth", "ecartqte", "ecartmontant", "ecartpu", "idproduit", "motsclesss") AS
SELECT SQ.IDOBJET,SQ.SORTIE,SQ.PU,SQ.MONTANTSORTIE,SQ.QTETH,SQ.PUTH,SQ.MONTTH,SQ.ECARTQTE,SQ.ECARTMONTANT,SQ.ECARTPU,SQ.IDPRODUIT,
       (COALESCE((IDOBJET)::text,'') || ' | ' || COALESCE((SORTIE)::text,'') || ' | ' || COALESCE((PU)::text,'') || ' | ' || COALESCE((MONTANTSORTIE)::text,'') || ' | ' || COALESCE((QTETH)::text,'') || ' | ' || COALESCE((PUTH)::text,'') || ' | ' || COALESCE((MONTTH)::text,'') || ' | ' || COALESCE((ECARTQTE)::text,'') || ' | ' || COALESCE((ECARTMONTANT)::text,'') || ' | ' || COALESCE((ECARTPU)::text,'')) AS MOTSCLESSS
FROM (
         SELECT
             IDOBJET,
             IDPRODUIT,
             CAST(SUM(SORTIE) AS NUMERIC(30,5)) AS sortie,
             CAST(SUM(PU) AS NUMERIC(30,2)) AS pu,
             CAST(SUM(MONTANTSORTIE) AS NUMERIC(30,5)) AS montantsortie,
             CAST(SUM(QTETH) AS NUMERIC(30,5)) AS qteth,
             CAST(SUM(PUTH) AS NUMERIC(30,2)) AS puth,
             CAST(SUM(MONTTH) AS NUMERIC(30,2)) AS montth,
             CAST(SUM(SORTIE - QTETH) AS NUMERIC(30,5)) AS ecartqte,
             CAST(SUM(MONTANTSORTIE - MONTTH) AS NUMERIC(30,2)) AS ecartmontant,
             CAST(SUM(PU - PUTH) AS NUMERIC(30,2)) AS ecartpu
         FROM
             STOCKETDEPENSEOFFABTHE
         GROUP BY
             IDOBJET,
             IDPRODUIT
     ) SQ;
CREATE VIEW public.stocketdepenseoffillefabthe ("idobjet", "idproduit", "designation", "entree", "sortie", "pu", "montanentree", "montantsortie", "idmere", "id", "qteth", "puth", "montth", "categorieingredient", "categorieingredientlib") AS
select
    sed.IDOBJET,
    sed.IDPRODUIT,
    COALESCE(recFab.LIBINGREDIENTS,ai.LIBELLE) AS designation,
    CAST(sed.ENTREE as NUMERIC(30,5)) AS ENTREE ,
    CAST(sed.SORTIE as NUMERIC(30,5))  AS SORTIE ,
    CAST(
            CASE
                WHEN COALESCE(sed.PU,0) = 0 THEN recFab.pu
                ELSE COALESCE(sed.PU,0)
                END
        as NUMERIC(30,2)) AS PU,
    CAST(sed.MONTANENTREE as NUMERIC(30,2)) AS MONTANENTREE ,
    CAST(
            CASE
                WHEN COALESCE(sed.PU,0) = 0 THEN recFab.pu * sed.SORTIE
                ELSE COALESCE(sed.PU,0) * sed.SORTIE
                END
        as NUMERIC(30,2))  AS MONTANTSORTIE,
    sed.IDMERE,
    sed.ID,
    cast(COALESCE(recFab.QUANTITE,0) as NUMERIC(30,10)) as qteTh,
    cast(COALESCE(recFab.QTEAV,sed.pu) as NUMERIC(30,2)) as puth,
    cast(COALESCE(recFab.QUANTITE,0)*COALESCE(recFab.QTEAV,0) as NUMERIC(30,2)) as montTh,
    sed.CATEGORIEINGREDIENT,
    sed.CATEGORIEINGREDIENTLIB
from STOCKDEPENSEOFFILLEFAB sed full
                                    outer join AS_RECFOFABLIBGROUPE recFab
                                               on sed.IDMERE =recFab.IDPRODUITS and sed.IDPRODUIT=recFab.IDINGREDIENTS
                                LEFT JOIN AS_INGREDIENTS ai ON ai.ID = sed.IDOBJET OR ai.ID =  sed.IDPRODUIT;
CREATE VIEW public.stocketdepenseoffillethecat ("idobjet", "idproduit", "entree", "sortie", "pu", "montanentree", "montantsortie", "idmere", "id", "qteth", "puth", "montth", "categorieingredient", "idcategorieingredient") AS
SELECT
    std.IDOBJET,
    std.IDPRODUIT,
    std.ENTREE,
    std.SORTIE,
    std.PU,
    std.MONTANENTREE,
    std.MONTANTSORTIE,
    std.IDMERE,
    std.ID,
    std.QTETH,
    std.PUTH,
    std.MONTTH,
    cat.VAL as CATEGORIEINGREDIENT,
    cat.ID AS idcategorieingredient
from STOCKETDEPENSEOFFILLEFABTHE std
         left join AS_INGREDIENTS ing on std.IDPRODUIT=ing.id
         left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id;
CREATE VIEW public.stocketdepoffillethecatgroupe ("idmere", "categorieingredient", "idcategorieingredient", "montantsortie", "montth", "ecart") AS
select
    st.IDOBJET AS idmere,
    st.CATEGORIEINGREDIENT,
    st.idcategorieingredient,
    cast(sum(montantsortie) as NUMERIC(30,2)) as montantSortie,
    cast(sum(montth) as NUMERIC(30,2)) as montth,
    cast(sum(montth)-sum(montantsortie) as NUMERIC(30,2)) as ecart
from STOCKETDEPENSEOFFILLETHECAT st
group by st.IDOBJET ,st.CATEGORIEINGREDIENT, st.idcategorieingredient;
CREATE VIEW public.rapprochement_completoffille ("idmere", "categorieingredient", "idcategorieingredient", "montantsortie", "montth", "ecart") AS
select
    st.IDOBJET AS idmere,
    st.CATEGORIEINGREDIENT,
    st.idcategorieingredient,
    cast(sum(montantsortie) as NUMERIC(30,2)) as montantSortie,
    cast(sum(montth) as NUMERIC(30,2)) as montth,
    cast(sum(montth)-sum(montantsortie) as NUMERIC(30,2)) as ecart
from STOCKETDEPENSEOFFILLETHECAT st
group by st.IDOBJET ,st.CATEGORIEINGREDIENT, st.idcategorieingredient

UNION ALL

SELECT
    hs.idMere,
    'Charge personnelle' as CATEGORIE,
    hs.CATEGORIE as idCategorieIngredient,
    hs.montantPersonnel AS montantSortie,
    0 AS montth,
    -hs.montantPersonnel AS ecart
FROM HS_PAR_OFFILLE hs;

COMMIT;

-- Verification des 22 vues recompilees
SELECT 'vues_recompilees_oracle' AS lot, count(*) AS vues_presentes, 22 AS vues_attendues
FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relkind='v' AND c.relname=ANY(ARRAY[
    'travaux_recap',
        'coutsmaintenance',
        'bc_client_fille_cpl_lib_pdf',
        'stocketdepensefabnc',
        'stocketdepensefab',
        'as_recettefablibst',
        'stockdepenseoffab',
        'stockdepenseoffillefab',
        'stocketdepensefabthe',
        'stocketdepensefabthecat',
        'stocketdepfabthecatgroupe',
        'rapprochement_completfab',
        'stocketdepenseoffabthe',
        'stocketdepenseoffabthecat',
        'stocketdepoffabthecatgroupe',
        'rapprochement_complet',
        'v_rapprochement_of',
        'v_rapprochement_of_ia',
        'stocketdepenseoffillefabthe',
        'stocketdepenseoffillethecat',
        'stocketdepoffillethecatgroupe',
